-- ============================================================
-- 圣经全文（新译本（主名作「主/主神」））· 数据文件 5/6
-- 先运行 bible_cuv_schema.sql 建表（已运行过可跳过），再按序号运行。
-- 可重复运行（冲突自动跳过）。本文件 5200 节。
-- ============================================================
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '以西结书', 26, 16, 47, '你不但行她们所行的，作她们所作的可憎之事，而且你还以那些事为小，你一切所行的比她们更坏。'),
('CNV', '以西结书', 26, 16, 48, '我指着我的永生起誓，你的妹妹所多玛和她的女儿们，都没有行过像你和你女儿们所行的事。这是主神的宣告。'),
('CNV', '以西结书', 26, 16, 49, '你妹妹所多玛的罪孽是这样：她和她的女儿们都骄傲自大，粮食丰足，生活安逸，却没有帮助困苦和贫穷的人。'),
('CNV', '以西结书', 26, 16, 50, '她们自高自傲，在我面前行了可憎的事；我看见了，就把她们除掉。'),
('CNV', '以西结书', 26, 16, 51, '撒玛利亚所犯的罪还不及你所犯的一半；你所行的可憎之事比她更多，以致你的姊妹因你所行的一切可憎之事而显为义。'),
('CNV', '以西结书', 26, 16, 52, '你既然使你的姊妹较显为义，你就要承担自己的耻辱；因为你所犯的罪比她们所犯的更可憎，她们比你更显为义。你使你的姊妹较显为义，所以你就要惭愧，承担自己的耻辱了。'),
('CNV', '以西结书', 26, 16, 53, '“‘我要使所多玛和她的女儿们，撒玛利亚和她的女儿们从苦境中转回，我也要使你们跟她们一起转回，'),
('CNV', '以西结书', 26, 16, 54, '好使你担当自己的耻辱，并且因你一切所行的使她们得了安慰，你就自觉惭愧。'),
('CNV', '以西结书', 26, 16, 55, '你的妹妹所多玛和她的女儿们必回复原来的状况；撒玛利亚和她的女儿们必回复原来的状况；你和你的女儿们也必回复原来的状况。'),
('CNV', '以西结书', 26, 16, 56, '在你骄傲自大的日子，你妹妹所多玛在你口中不是成了笑柄吗？'),
('CNV', '以西结书', 26, 16, 57, '那时你的恶行还没有显露出来，现在你却成了以东的女儿们和以东四围的众人，以及非利士的女儿们讥笑的对象。你周围的人都轻视你。'),
('CNV', '以西结书', 26, 16, 58, '你要承担你那些淫乱和可憎之事的后果。这是主的宣告。'),
('CNV', '以西结书', 26, 16, 59, '主神这样说：你这藐视誓言、背弃盟约的，我必照着你所行的报应你。'),
('CNV', '以西结书', 26, 16, 60, '“‘但我仍要记念在你年幼的时候与你所立的约，也要与你坚立永远的约。'),
('CNV', '以西结书', 26, 16, 61, '你接纳你姊姊和你妹妹回来的时候，你就会想起你所行的，并要自觉惭愧；我要把她们赐给你作女儿，但这并不是出于我与你所立的约。'),
('CNV', '以西结书', 26, 16, 62, '我要坚立我与你所立的约，你就知道我是主，'),
('CNV', '以西结书', 26, 16, 63, '好使你在我赦免你所行的一切时，就会回想，自觉惭愧，并且因你所受的羞辱不再开口。这是主神的宣告。’”'),
('CNV', '以西结书', 26, 17, 1, '主的话临到我说：'),
('CNV', '以西结书', 26, 17, 2, '“人子啊！你要向以色列家出谜语，设比喻，'),
('CNV', '以西结书', 26, 17, 3, '说：‘主神这样说：有一只大鹰，翅膀大，翎毛长，羽毛丰富，彩色缤纷，来到黎巴嫩，把香柏树的树梢取去；'),
('CNV', '以西结书', 26, 17, 4, '它啄断树顶的嫩枝，把它带到贸易之地，栽种在商人的城里。'),
('CNV', '以西结书', 26, 17, 5, '它又把以色列地的种子取去，栽种在肥沃的地土、水流的旁边，好像栽种柳树一样；'),
('CNV', '以西结书', 26, 17, 6, '它生长起来，成了一棵矮小而蔓延的葡萄树；树上的枝子向着那鹰，树根在它以下。这样，它就成了一棵葡萄树，生出枝子，长出嫩芽。'),
('CNV', '以西结书', 26, 17, 7, '“‘另有一只大鹰，翅膀大，羽毛多；这葡萄树从它栽种的苗床上，把树根向这鹰弯过去，又向这鹰长出枝子，好得它的浇灌。'),
('CNV', '以西结书', 26, 17, 8, '其实，这树早已栽种在肥沃的地土、水流的旁边，可以长枝子、结果子，成为佳美的葡萄树。’'),
('CNV', '以西结书', 26, 17, 9, '你要说：‘主神这样说：这葡萄树怎能茂盛呢？鹰不是要拔出它的根来，啄光它的果子，使它和它长出的一切嫩叶都枯干吗？其实，要把它连根拔起，并不需要很多人或很大的气力。'),
('CNV', '以西结书', 26, 17, 10, '看哪！葡萄树被栽种了，但它能发旺吗？东风吹袭它的时候，它不是必然枯干吗？它必在生长的苗床上枯干。’”'),
('CNV', '以西结书', 26, 17, 11, '主的话临到我说：'),
('CNV', '以西结书', 26, 17, 12, '“你要对那叛逆的民族说：‘你们不知道这些事是什么意思吗？’你要告诉他们：‘看哪！巴比伦王曾到耶路撒冷来，把其中的王和众领袖掳去，带他们到巴比伦那里去。'),
('CNV', '以西结书', 26, 17, 13, '他从以色列王室后裔中选出一人，与他立约，叫他起誓，并且把国中那些有势力的人掳去，'),
('CNV', '以西结书', 26, 17, 14, '使国衰微，不能再兴盛，唯有谨守条约他才可以继续存在。'),
('CNV', '以西结书', 26, 17, 15, '可是这人背叛了巴比伦王，差遣使者到埃及去，要得战马和大军。他能亨通吗？行这样事的人，怎能逃脱呢？他破坏条约，怎能逃脱呢？'),
('CNV', '以西结书', 26, 17, 16, '我指着我的永生起誓：他藐视了自己所起的誓，背弃了与王所立的约，因此他必死在巴比伦，就是那立他作王的巴比伦王的国家。这是主的宣告。'),
('CNV', '以西结书', 26, 17, 17, '敌人建造围城的高墙，筑起攻城土垒要剪除多人的时候，法老率领大军和大队人马，还是不能帮助他作战。'),
('CNV', '以西结书', 26, 17, 18, '他藐视誓言，背弃条约；他已宣誓效忠，却又行了这一切事，所以他必不能逃脱。'),
('CNV', '以西结书', 26, 17, 19, '因此主神这样说：我指着我的永生起誓：他既然藐视我的誓言，背弃我的约，我必使这罪归到他的头上。'),
('CNV', '以西结书', 26, 17, 20, '我要把我的网撒在他身上，他必在我的网罗中被捕获；我要把他带到巴比伦去，并且要在那里因他对我不忠的罪审判他。'),
('CNV', '以西结书', 26, 17, 21, '他军中所有的精兵（按照《马索拉文本》，“精兵”作“逃跑的人”；现参照其他抄本、《七十士译本》和其他古译本翻译），都必倒在刀下；剩下的也必分散到四方；你们就知道说这话的是我主。'),
('CNV', '以西结书', 26, 17, 22, '“‘主神这样说：我要从高大香柏树的树梢上取去一根树枝，把它栽上；我要从树顶的嫩枝中折下一根枝子，把它栽种在高耸的山上；'),
('CNV', '以西结书', 26, 17, 23, '我要把它栽种在以色列的高山上，它要长出枝子，结出果子，成为佳美的香柏树；各种各类的飞鸟都必在树下栖宿，就是栖宿在枝子的荫下。'),
('CNV', '以西结书', 26, 17, 24, '田野所有的树木都必知道我主使高大的树矮小，矮小的树高大；使青绿的树枯干，枯干的树茂盛。我主怎样说了，就必怎样行。’”'),
('CNV', '以西结书', 26, 18, 1, '主的话临到我说：'),
('CNV', '以西结书', 26, 18, 2, '“论到以色列地，你们为什么引用这俗语说‘父亲吃了酸葡萄，儿子的牙酸倒了’呢？'),
('CNV', '以西结书', 26, 18, 3, '我指着我的永生起誓：你们在以色列中必不再引用这俗语了。这是主神的话。'),
('CNV', '以西结书', 26, 18, 4, '看哪！所有的人都是属我的，作父亲的怎样属我，作儿子的也怎样属我，唯独犯罪的，才会灭亡。'),
('CNV', '以西结书', 26, 18, 5, '“人若是公义，又行公道和正直的事：'),
('CNV', '以西结书', 26, 18, 6, '他不在山上吃祭肉，眼目也不仰望以色列家的偶像，不玷污邻舍的妻子，不亲近在经期中的妇人；'),
('CNV', '以西结书', 26, 18, 7, '不欺压任何人，把欠债人的抵押归还；他不抢夺人的物件，却把自己的食物给饥饿的人，把衣服给赤身的人穿着；'),
('CNV', '以西结书', 26, 18, 8, '他借东西给人不取利息，也不多要，他使自己的手远离罪恶，在人与人之间施行诚实的判断；'),
('CNV', '以西结书', 26, 18, 9, '他遵行我的律例，谨守我的典章，行事诚实，这人是个义人，他必定存活。这是主神的宣告。'),
('CNV', '以西结书', 26, 18, 10, '“他若是生一个儿子，是个强暴的人，流人的血，又向兄弟行上述任何一件恶事'),
('CNV', '以西结书', 26, 18, 11, '（虽然他父亲并没有作这样的事）：他在山上吃祭肉，又玷污邻舍的妻子；'),
('CNV', '以西结书', 26, 18, 12, '他欺压困苦和贫穷的人，抢夺人的物件，没有把抵押品归还，眼目仰望偶像，并行可憎的事；'),
('CNV', '以西结书', 26, 18, 13, '他借东西给人要收利息，也向人多要，这样的人能存活吗？他必不能存活；他行了这一切可憎的事，必要灭亡；他的罪（“罪”原文作“血”）要归到他身上。'),
('CNV', '以西结书', 26, 18, 14, '“他若生一个儿子，这儿子看见他父亲所犯的一切罪，他虽然看见了，却不照样去作：'),
('CNV', '以西结书', 26, 18, 15, '他不在山上吃祭肉，眼目不仰望以色列家的偶像，不玷污邻舍的妻子；'),
('CNV', '以西结书', 26, 18, 16, '不欺压任何人，不索取抵押品，不抢夺人的物件，却把自己的食物给饥饿的人，把衣服给赤身的人穿着；'),
('CNV', '以西结书', 26, 18, 17, '他不伸手欺压困苦人，借东西给人不取利息，也不多要；他遵守我的典章，遵行我的律例，这人就必不因他父亲的罪孽而灭亡；他必要存活。'),
('CNV', '以西结书', 26, 18, 18, '至于他的父亲，因为他勒索，抢夺兄弟的物件，在自己的同胞中行不善的事，所以他必因自己的罪孽而灭亡。'),
('CNV', '以西结书', 26, 18, 19, '“你们还问：‘儿子为什么不担当父亲的罪孽呢？’儿子若行正直和公义的事，谨守遵行我的一切律例，就必存活。'),
('CNV', '以西结书', 26, 18, 20, '唯独犯罪的，才会灭亡；儿子必不担当父亲的罪孽，父亲也必不担当儿子的罪孽；义人的义必归他自己，恶人的恶也必归他自己。'),
('CNV', '以西结书', 26, 18, 21, '“恶人若回转，离开他所犯的一切罪，谨守我的一切律例，行正直和公义的事，就必存活，不致灭亡。'),
('CNV', '以西结书', 26, 18, 22, '他所犯的一切罪过都不会被记念，作控诉他的理由；他必因自己所行的义而存活。'),
('CNV', '以西结书', 26, 18, 23, '难道我喜悦恶人死亡吗？我不是喜悦他回转离开他所行的而存活吗？这是主神的宣告。'),
('CNV', '以西结书', 26, 18, 24, '“义人若转离他的义去行恶，照着恶人所行一切可憎的事而行，他能存活吗？他所行的一切义都不会被记念；他必因他所行不忠的事和他所犯的罪而灭亡。'),
('CNV', '以西结书', 26, 18, 25, '“你们还说：‘主所行的不公平。’以色列家啊，你们要听！我所行的哪里不公平呢？岂不是你们所行的不公平吗？'),
('CNV', '以西结书', 26, 18, 26, '义人若转离他的义去行恶，他就必因此灭亡；他必因着他所行的不义灭亡。'),
('CNV', '以西结书', 26, 18, 27, '还有，恶人若回转离开他所行的恶，行正直公义的事，他就可以使自己的性命存活。'),
('CNV', '以西结书', 26, 18, 28, '因为他思量了，就转离他所犯的一切罪过，所以他必然存活，不致灭亡。'),
('CNV', '以西结书', 26, 18, 29, '但以色列家还说：‘主所行的不公平。’以色列家啊，我所行的哪里不公平呢？岂不是你们所行的不公平吗？'),
('CNV', '以西结书', 26, 18, 30, '“因此，以色列家啊，我必照着你们各人所行的审判你们。你们回转吧！离开你们的一切罪过吧！免得罪孽成为你们的绊脚石。这是主神的宣告。'),
('CNV', '以西结书', 26, 18, 31, '你们要把你们所犯的一切罪过弃掉，为自己造一个新的心和新的灵。以色列家啊，你们为什么要灭亡呢？'),
('CNV', '以西结书', 26, 18, 32, '“我不喜悦任何人灭亡，所以你们要回转，得以存活。这是主神的宣告。”'),
('CNV', '以西结书', 26, 19, 1, '“你当为以色列的众领袖作一首哀歌，'),
('CNV', '以西结书', 26, 19, 2, '说：‘你的母亲是什么？是狮子群中的母狮，它卧在少壮狮子群中，养育它的小狮子。'),
('CNV', '以西结书', 26, 19, 3, '它养大其中一只小狮子，这幼狮成了一只少壮的狮子，学会了撕碎猎物，把人吃掉。'),
('CNV', '以西结书', 26, 19, 4, '列国听见了，就把它困在他们的坑中；他们用钩子把它带到埃及地去。'),
('CNV', '以西结书', 26, 19, 5, '母狮见自己所等候的落空了，所希望的幻灭了，就从它的小狮子中另取出一只，使它成为少壮的狮子。'),
('CNV', '以西结书', 26, 19, 6, '它在狮子群中行走；它已成了一只少壮的狮子，它学会了撕碎猎物，把人吃掉。'),
('CNV', '以西结书', 26, 19, 7, '它拆毁了他们的城堡，使他们的城市荒凉；因它吼叫的声音，地和其中所充满的都惊恐。'),
('CNV', '以西结书', 26, 19, 8, '于是四围的列国从各地来攻击它，把他们的网撒在它身上，把它困在他们的坑中。'),
('CNV', '以西结书', 26, 19, 9, '他们把它放进笼里，用钩子带到巴比伦王那里，囚在狱中，使它的声音在以色列众山上不再听见。'),
('CNV', '以西结书', 26, 19, 10, '“‘你的母亲像葡萄园里（按照《马索拉文本》，“葡萄园里”作“在你血中”；现参照其他抄本和《七十士译本》翻译）的一棵葡萄树，栽种在水边；因为水源充足，结果累累、枝叶茂盛。'),
('CNV', '以西结书', 26, 19, 11, '它有粗壮的树枝可作掌权者的杖；它树身高大，超乎其他茂密枝叶之上；因为它树身高大，枝子众多，远远就可以看见。'),
('CNV', '以西结书', 26, 19, 12, '但这葡萄树因神的烈怒被拔起，摔在地上；东风使它的果子枯干散掉，粗壮的树枝枯槁，被火吞灭。'),
('CNV', '以西结书', 26, 19, 13, '现在它被栽种在旷野，在干旱无水之地。'),
('CNV', '以西结书', 26, 19, 14, '有火从树枝中的一根发出，吞灭树的果子，以致树上再没有粗壮的树枝，可以作掌权者的杖。’这是一首哀歌，是一首流行的哀歌。”'),
('CNV', '以西结书', 26, 20, 1, '第七年五月十日，有几个以色列的长老来求问主，他们坐在我的面前。'),
('CNV', '以西结书', 26, 20, 2, '主的话临到我说：'),
('CNV', '以西结书', 26, 20, 3, '“人子啊！你要告诉以色列的长老，对他们说：‘主神这样说：你们来求问我吗？我指着我的永生起誓，我必不让你们求问我。这是主神的宣告。’'),
('CNV', '以西结书', 26, 20, 4, '人子啊，你要审问他们吗？要审问他们吗？你要使他们知道他们列祖那些可憎的事，'),
('CNV', '以西结书', 26, 20, 5, '对他们说：‘主神这样说：在我拣选以色列的日子，我向雅各家的后裔举手起誓，又在埃及地向他们显现。我向他们举手起誓说：我是主你们的神。'),
('CNV', '以西结书', 26, 20, 6, '那日，我向他们举手起誓，要把他们从埃及地领出来，到我为他们所选定的流奶与蜜之地，就是万邦中最荣美的地。'),
('CNV', '以西结书', 26, 20, 7, '我对他们说：你们各人要抛弃你们眼中那些可憎的像，不可因埃及的偶像玷污自己：我是主你们的神。'),
('CNV', '以西结书', 26, 20, 8, '但是他们背叛了我，不肯听从我；他们各人没有抛弃他们眼中那些可憎的像，没有离弃埃及的偶像。“‘那时我说，我要把我的烈怒倾倒在他们身上，在埃及地向他们完全发尽我的怒气。'),
('CNV', '以西结书', 26, 20, 9, '然而我为了我名的缘故没有这样作，免得我的名在他们寄居的列国的人眼中被亵渎，我把他们从埃及地领出来，在列国的人眼前向他们显现。'),
('CNV', '以西结书', 26, 20, 10, '“‘这样我把他们从埃及地领了出来，带到旷野。'),
('CNV', '以西结书', 26, 20, 11, '我把我的律例赐给他们，把我的典章指示他们；人如果遵行，就必因此活着。'),
('CNV', '以西结书', 26, 20, 12, '我又把我的安息日赐给他们，作我与他们之间的凭据，使他们知道我是使他们分别为圣的主。'),
('CNV', '以西结书', 26, 20, 13, '可是以色列家在旷野背叛了我，没有遵行我的律例，弃绝了我的典章（人如果遵行这些，就必因此活着），大大亵渎了我的安息日，那时我说我要把我的烈怒倒在他们身上，在旷野把他们灭绝。'),
('CNV', '以西结书', 26, 20, 14, '然而我为了我名的缘故没有这样作，免得我的名在列国的人眼中被亵渎；我曾在他们眼前把以色列人领出来。'),
('CNV', '以西结书', 26, 20, 15, '我在旷野也曾经向他们举手起誓，必不领他们到我赐给他们的流奶与蜜之地，就是万邦中最荣美的地。'),
('CNV', '以西结书', 26, 20, 16, '因为他们弃绝了我的典章，没有遵行我的律例，亵渎了我的安息日；他们的心随从自己的偶像。'),
('CNV', '以西结书', 26, 20, 17, '虽然这样，我的眼还是顾惜他们，不毁灭他们；我没有在旷野把他们灭绝。'),
('CNV', '以西结书', 26, 20, 18, '“‘我在旷野对他们的儿女说：不要遵行你们祖先的律例，不要谨守他们的典章，也不要因他们的偶像玷污自己。'),
('CNV', '以西结书', 26, 20, 19, '我是主你们的神；你们要遵行我的律例，谨守我的典章，把它们实行出来。'),
('CNV', '以西结书', 26, 20, 20, '你们要把我的安息日分别为圣，作我与你们之间的凭据，使你们知道我是主你们的神。'),
('CNV', '以西结书', 26, 20, 21, '可是他们的儿女背叛了我，没有遵行我的律例，也没有谨守实行我的典章（人如果遵行这些律例典章，就必因此活着），亵渎了我的安息日；那时我说我要把我的烈怒倒在他们身上，在旷野向他们发尽我的怒气。'),
('CNV', '以西结书', 26, 20, 22, '然而我为了我名的缘故缩手，没有这样作，免得我名在列国的人眼中被亵渎；我曾在他们眼前把以色列人领出来。'),
('CNV', '以西结书', 26, 20, 23, '我在旷野也曾经向他们举手起誓，要把他们分散在列国，四散在万邦；'),
('CNV', '以西结书', 26, 20, 24, '因为他们没有遵守我的典章，弃绝了我的律例，亵渎了我的安息日，他们的眼目注视着他们祖先的偶像。'),
('CNV', '以西结书', 26, 20, 25, '因此，我也把不好的律例和不能借以存活的典章赐给他们；'),
('CNV', '以西结书', 26, 20, 26, '他们使所有头生的都经火作供物，所以我让他们玷污自己，好叫他们惊惶，知道我是主。’'),
('CNV', '以西结书', 26, 20, 27, '“因此，人子啊！你要告诉以色列家，对他们说：‘主神这样说：你们的列祖在对我不忠的这事上亵渎了我。'),
('CNV', '以西结书', 26, 20, 28, '我领他们到了我曾经举手起誓要赐给他们的那地，他们看见各高山和茂盛的树林，就在那里献祭，在那里奉上惹我发怒的供物，也在那里献上馨香的祭，并且在那里浇上他们的奠祭。’'),
('CNV', '以西结书', 26, 20, 29, '我问他们：‘你们所去的那高处是什么地方？’于是那高处的名字叫巴麻，直到今日。'),
('CNV', '以西结书', 26, 20, 30, '因此，你要对以色列家说：‘主神这样说：你们还照着你们祖先所行的玷污自己吗？仍随着他们可憎的偶像行邪淫吗？'),
('CNV', '以西结书', 26, 20, 31, '你们奉上供物，使你们的儿子经火，用你们的一切偶像玷污自己，直到今日。以色列家啊，我怎能让你们向我求问呢？主神说：我指着我的永生起誓：我决不让你们向我求问。这是主神的宣告。'),
('CNV', '以西结书', 26, 20, 32, '你们说：我们要像列国的人，像列邦的各族一样去事奉木头和石头。你们心里所起的这意念，必不能成就。'),
('CNV', '以西结书', 26, 20, 33, '“‘我指着我的永生起誓：我必用大能的手，伸出来的膀臂，以及倒出来的烈怒，统治你们。这是主神的宣告。'),
('CNV', '以西结书', 26, 20, 34, '我必用大能的手，伸出来的膀臂，以及倒出来的烈怒，把你们从万族中领出来，从你们所分散到的列邦招聚你们。'),
('CNV', '以西结书', 26, 20, 35, '我要把你们带到万族的旷野，在那里当面审判你们。'),
('CNV', '以西结书', 26, 20, 36, '我怎样在埃及地的旷野审判你们的祖先，也必怎样审判你们。这是主神的宣告。'),
('CNV', '以西结书', 26, 20, 37, '我必使你们从牧人的杖下经过，使你们进入盟约的约束。'),
('CNV', '以西结书', 26, 20, 38, '我必从你们中间除净那些背叛和得罪我的人，我虽把他们从寄居之地领出来，可是他们不得进入以色列地；这样，你们就知道我是主。'),
('CNV', '以西结书', 26, 20, 39, '以色列家啊，至于你们，主神这样说：你们各人去事奉自己的偶像吧！只是将来你们必要听从我，不可再以你们的供物和偶像亵渎我的圣名。'),
('CNV', '以西结书', 26, 20, 40, '在我的圣山，就是在以色列的高山，以色列全家所有的人都要在那地事奉我；我要在那里悦纳他们；在那里向你们要举祭和初熟的土产，以及一切圣物。这是主神的宣告。'),
('CNV', '以西结书', 26, 20, 41, '我从万族中把你们领出来，从你们所分散到的列邦召集你们的时候，我必悦纳你们，好像悦纳馨香的祭一样。我要在列国的人眼前，在你们中间显为圣。'),
('CNV', '以西结书', 26, 20, 42, '我领你们进入以色列地，就是进入我曾经举手起誓要赐给你们祖先的地以后，你们就知道我是主。'),
('CNV', '以西结书', 26, 20, 43, '在那里你们要想起你们玷污自己的所作所为，又要为了自己所行的一切恶事而厌恶自己。'),
('CNV', '以西结书', 26, 20, 44, '以色列家啊！为了我名的缘故，我没有照着你们的恶行和败坏的行为待你们，这样，你们就知道我是主。这是主神的宣告。’”'),
('CNV', '以西结书', 26, 20, 45, '主的话临到我说：'),
('CNV', '以西结书', 26, 20, 46, '“人子啊！你要面向南方，向南面发言，说预言攻击南地田野的树林，'),
('CNV', '以西结书', 26, 20, 47, '对南地的树林说：‘你要听主的话，主神这样说：看哪！我要在你中间点起火来，吞灭你中间所有青绿和枯干的树；猛烈的火焰必不熄灭；从南到北遍地都要烧焦。'),
('CNV', '以西结书', 26, 20, 48, '所有的人都必看见是我主使这火燃起来；这火必不熄灭。’”'),
('CNV', '以西结书', 26, 20, 49, '于是我说：“啊，主神啊！人都指着我说：‘这人不是在说比喻吗？’”（本章第45~49节在《马索拉文本》为21:1~5）'),
('CNV', '以西结书', 26, 21, 1, '主的话临到我说：（本节在《马索拉文本》为21:6）'),
('CNV', '以西结书', 26, 21, 2, '“人子啊！你要面向耶路撒冷，向圣所发言，说预言攻击以色列地，'),
('CNV', '以西结书', 26, 21, 3, '你要对以色列地说：‘主这样说：看哪！我要攻击你；我要拔刀出鞘，把义人和恶人都从你那里剪除。'),
('CNV', '以西结书', 26, 21, 4, '我既然要把义人和恶人都从你那里剪除，所以我的刀必要出鞘，从南到北攻击所有的人；'),
('CNV', '以西结书', 26, 21, 5, '所有的人就知道我主已经拔刀出鞘，刀必不再入鞘了。’'),
('CNV', '以西结书', 26, 21, 6, '人子啊！至于你，你要叹息，在他们眼前弯着腰，苦苦叹息。'),
('CNV', '以西结书', 26, 21, 7, '他们如果问你：‘你为什么叹息呢？’你就要回答：‘是因为那将要来到的消息；人人都必心慌意乱，手都发软，精神衰颓，他们的膝都像水一般的柔弱。看哪！它要来到了。这事一定要成就。这是主神的宣告。’”'),
('CNV', '以西结书', 26, 21, 8, '主的话临到我说：'),
('CNV', '以西结书', 26, 21, 9, '“人子啊！你要预言，说：‘主神这样说：有一把刀，有一把磨利了的刀，是擦亮了的刀；'),
('CNV', '以西结书', 26, 21, 10, '磨利，是为要大行杀戮，擦亮，是为要闪烁发光！我们怎能快乐呢？我的儿子藐视管教的杖和一切劝告（“劝告”原文作“木头”）。'),
('CNV', '以西结书', 26, 21, 11, '这刀已经交给人擦亮，可以握在手中使用；这刀已经磨利擦亮了，可以交在行杀戮的人手中。’'),
('CNV', '以西结书', 26, 21, 12, '人子啊！你要呼喊、哀号。因为这刀要临到我的子民，以及以色列所有的领袖；他们与我的子民都要交在刀下；所以你要拍腿悲叹，'),
('CNV', '以西结书', 26, 21, 13, '因为考验必要来到，你为什么要藐视那管教的杖呢？这事必不得成功。这是主神的宣告。'),
('CNV', '以西结书', 26, 21, 14, '“人子啊！至于你，你要拍手说预言，要接二连三地使用这杀人的刀，就是导致极大死伤的刀，把它们围困，'),
('CNV', '以西结书', 26, 21, 15, '好使他们心慌意乱，多人跌倒，我在他们所有的城门那里布下了杀戮（“杀戮”这译法是参考古译本，原文意思不详）的人；啊！这刀做得闪烁发光，磨得尖利，可以杀戮。'),
('CNV', '以西结书', 26, 21, 16, '刀啊，向右边斩吧！向左边刺吧！无论你面向哪一方，就向哪一方杀戮吧！'),
('CNV', '以西结书', 26, 21, 17, '我也要拍手，并且要使我的烈怒止息；这是我主说的。”'),
('CNV', '以西结书', 26, 21, 18, '主的话又临到我说：'),
('CNV', '以西结书', 26, 21, 19, '“人子啊！至于你，你要定出两条路，给巴比伦王的刀前来；这两条路都从同一个地方出来；你要在通往城去的路口上做一个路标。'),
('CNV', '以西结书', 26, 21, 20, '你要定出一条路，使刀临到亚扪的拉巴，又要定出另一条路，使刀临到犹大，攻击坚固城耶路撒冷。'),
('CNV', '以西结书', 26, 21, 21, '因为巴比伦王站在分叉路口，在两条路口上占卜、摇签、求问神像，察看动物的肝。'),
('CNV', '以西结书', 26, 21, 22, '他右手中拿着耶路撒冷的签，要在那里架起攻城锤，下令屠杀，扬声吶喊；架起攻城锤，攻打城门；筑起土垒，建造围城的高墙。'),
('CNV', '以西结书', 26, 21, 23, '在那些曾经向巴比伦起誓效忠的犹大人看来，这是虚假的占卜，但巴比伦王要使他们想起自己的罪孽，把他们掳去。'),
('CNV', '以西结书', 26, 21, 24, '因此，主神这样说：‘你们的过犯显露，你们的罪在你们的一切行为上给人看见；以致你们的罪孽被想起。你们既被想起，就要被人用手掳去。'),
('CNV', '以西结书', 26, 21, 25, '你这该死、邪恶的以色列王啊！你的日子到了，最后惩罚的时刻到了。’'),
('CNV', '以西结书', 26, 21, 26, '主神这样说：‘你当除去头巾，脱下冠冕！现在情形不同了，卑微的要升高，位高的要降卑！'),
('CNV', '以西结书', 26, 21, 27, '倾覆，倾覆，我要倾覆这国，这国不再存在，直等到那统治的人来到，我就把国赐给他。’'),
('CNV', '以西结书', 26, 21, 28, '“人子啊！你要说预言：论到亚扪人和他们的侮辱，主神这样说：‘你要说：有一把刀，有一把刀拔出来，是为要杀戮；擦亮，是为要毁灭，为要闪烁发光。'),
('CNV', '以西结书', 26, 21, 29, '人为你所见的异象是虚假的，为你所占的卜是虚谎的，使你倒在该死的恶人的颈项上；他们受惩罚的日子到了，最后惩罚的时刻到了。'),
('CNV', '以西结书', 26, 21, 30, '收刀入鞘吧！我必在你被造之地，根源之处，审判你。'),
('CNV', '以西结书', 26, 21, 31, '我必把我的忿怒倒在你身上，把我的怒火喷在你身上，又把你交在那些惯于毁灭的野蛮人手中。'),
('CNV', '以西结书', 26, 21, 32, '你必当作燃料被火焚烧；你的血要流在你的国中；你必不再被记念，因为这是我主说的。’”'),
('CNV', '以西结书', 26, 22, 1, '主的话又临到我说：'),
('CNV', '以西结书', 26, 22, 2, '“人子啊，你要审判吗？你要审判这流人血的城吗？你要使这城知道它一切可憎的事。'),
('CNV', '以西结书', 26, 22, 3, '你要说：‘主神这样说：这城中有流人血的事，它制造偶像，玷污自己，以致它受审判的时候来到。'),
('CNV', '以西结书', 26, 22, 4, '因你流了人的血，你就有罪了；因你做了偶像，你就玷污了自己；这样，你使你受罚的日子临近，遭报的年日来到，我使你成为列国辱骂、列邦讥笑的对象。'),
('CNV', '以西结书', 26, 22, 5, '你这混乱喧嚷、名被玷污的城啊！那些离你近的和离你远的，都必讥笑你。'),
('CNV', '以西结书', 26, 22, 6, '看哪！以色列的领袖们恃着自己的能力，在你里面流人的血。'),
('CNV', '以西结书', 26, 22, 7, '在你里面轻视父母的；在你中间有压迫寄居的和欺负孤儿寡妇的。'),
('CNV', '以西结书', 26, 22, 8, '你藐视了我的圣物，亵渎了我的安息日。'),
('CNV', '以西结书', 26, 22, 9, '在你里面有好谗谤的人，他们要流人的血；在你的山上吃祭肉；又在你中间行淫乱的事。'),
('CNV', '以西结书', 26, 22, 10, '在你里面有暴露父亲下体的；有污辱在经期中不洁的妇人的。'),
('CNV', '以西结书', 26, 22, 11, '在你里面，这人与邻舍的妻子行可憎的事；那人行淫乱，玷污自己的儿媳；还有人污辱自己的同胞姊妹。'),
('CNV', '以西结书', 26, 22, 12, '在你里面有接受贿赂而流人血的；你借钱给人，收取利息，并且多要；你用欺压手段向你的邻舍榨取不义之财；你更忘记了我。这是主神的宣告。'),
('CNV', '以西结书', 26, 22, 13, '“‘看哪！因你所得的不义之财，又因在你中间所流的血，我就拍掌。'),
('CNV', '以西结书', 26, 22, 14, '到了我惩治你的日子，你的心还能受得住吗？你的手还有力吗？我主说了，就必实行。'),
('CNV', '以西结书', 26, 22, 15, '我要把你分散在列国，四散在万邦；我要从你中间消除你的污秽。'),
('CNV', '以西结书', 26, 22, 16, '你在列国眼前被玷污的时候，你就知道我是主。’”'),
('CNV', '以西结书', 26, 22, 17, '主的话临到我说：'),
('CNV', '以西结书', 26, 22, 18, '“人子啊！以色列家在我看来已成了渣滓；他们都是炉中的铜、锡、铁和铅；就是银的渣滓。'),
('CNV', '以西结书', 26, 22, 19, '因此，主神这样说：‘你们既然都成了渣滓，所以，我要把你们集合在耶路撒冷城中。'),
('CNV', '以西结书', 26, 22, 20, '人怎样把银、铜、铁、铅、锡，集合在炉中，吹火使它们熔化，我也照样在我的怒气、我的烈怒中，把你们集合起来，放在城中，使你们熔化。'),
('CNV', '以西结书', 26, 22, 21, '我必集合你们，把我烈怒的火吹在你们身上，你们就必在城中熔化。'),
('CNV', '以西结书', 26, 22, 22, '银子怎样在炉中熔化，你们也必照样在城中熔化；你们就知道我主把我的烈怒倒在你身上。’”'),
('CNV', '以西结书', 26, 22, 23, '主的话临到我说：'),
('CNV', '以西结书', 26, 22, 24, '“人子啊！你要对这地说：‘在忿怒的日子，你是没有雨水（“没有雨水”这译法是根据古译本，原文作“未得洁净”），没有甘霖之地’。'),
('CNV', '以西结书', 26, 22, 25, '其中的先知叛逆，像吼叫的狮子撕碎猎物；他们把人吞吃，抢夺财物和珍宝，使其中寡妇的数目增多。'),
('CNV', '以西结书', 26, 22, 26, '这地的祭司违反我的律法，亵渎我的圣物；他们不分别圣俗，也不教导人分辨什么是洁净的和不洁净的，又掩目不理我的安息日，以致我在他们中间被亵渎。'),
('CNV', '以西结书', 26, 22, 27, '其中的官长好像撕碎猎物的豺狼，流人的血，灭人的命，为要得不义之财。'),
('CNV', '以西结书', 26, 22, 28, '这地的先知用灰泥给他们粉刷墙壁，为他们见虚假的异象，行骗人的占卜，说：‘主神这样说’，其实当时主并没有说话。'),
('CNV', '以西结书', 26, 22, 29, '这地的人民常常欺压人，惯行抢掠，亏待困苦穷乏的人，毫无公理地去欺压寄居的人。'),
('CNV', '以西结书', 26, 22, 30, '我在他们中间寻找一人重修墙垣，在我面前为这地站在破口之处，使我不毁灭这地，我却找不到一个。'),
('CNV', '以西结书', 26, 22, 31, '所以我把我的忿怒倒在他们身上，用我烈怒之火消灭他们，把他们所行的报应在他们的头上。这是主神的宣告。”'),
('CNV', '以西结书', 26, 23, 1, '主的话又临到我说：'),
('CNV', '以西结书', 26, 23, 2, '“人子啊！有两个女人，都是同一个母亲生的。'),
('CNV', '以西结书', 26, 23, 3, '她们在埃及行邪淫，在幼年的时候行了邪淫，在那里她们的胸被人抚摩；在那里她们处女的乳房被人抚弄。'),
('CNV', '以西结书', 26, 23, 4, '姊姊的名字是阿荷拉，妹妹的名字是阿荷利巴；她们都嫁了给我，并且生了儿女。论到她们的名字，阿荷拉就是撒玛利亚，阿荷利巴就是耶路撒冷。'),
('CNV', '以西结书', 26, 23, 5, '“阿荷拉嫁了我以后仍行邪淫，恋慕她的爱人，就是亚述的战士。'),
('CNV', '以西结书', 26, 23, 6, '他们穿着紫色衣服，是作总督和省长的；他们都是英俊的年轻人，是骑着马的骑兵。'),
('CNV', '以西结书', 26, 23, 7, '阿荷拉与这些亚述人中最美的男子行邪淫；她因自己所恋慕的每一个人和这些人的偶像玷污了自己。'),
('CNV', '以西结书', 26, 23, 8, '她没有离弃在埃及时的淫乱；那时她年幼，人与她同睡，抚弄她处女的乳房，把他们的情欲发泄在她身上。'),
('CNV', '以西结书', 26, 23, 9, '因此我把她交在她的爱人手里，就是她所恋慕的亚述人手里。'),
('CNV', '以西结书', 26, 23, 10, '这些人露出她的下体，掳去她的儿女，用刀杀了她，使她在妇女中有了臭名，因为他们向她施行惩罚。'),
('CNV', '以西结书', 26, 23, 11, '“她妹妹阿荷利巴虽然看见了，却在自己情欲的事情上比姊姊更腐败，她的淫乱比姊姊的淫乱更甚。'),
('CNV', '以西结书', 26, 23, 12, '她贪恋亚述人，就是作总督和省长，穿着华美衣服的战士，骑着马的骑兵，全都是英俊的年轻人。'),
('CNV', '以西结书', 26, 23, 13, '我看见她被玷污了；她们姊妹两人所行的路都是一样。'),
('CNV', '以西结书', 26, 23, 14, '阿荷利巴又继续行淫；她看见画在墙上的人像，就是用鲜红的颜料所画的迦勒底人像，'),
('CNV', '以西结书', 26, 23, 15, '这些像的腰间束着腰带，头上有下垂的裹头巾，他们看来像官长，有巴比伦人的样子，迦勒底是他们出生之地。'),
('CNV', '以西结书', 26, 23, 16, '阿荷利巴的眼一看见，就恋慕他们，派遣使者到迦勒底去见他们。'),
('CNV', '以西结书', 26, 23, 17, '于是巴比伦人来，上了她爱情的床，与她行淫玷污了她；她被他们玷污以后，心就与他们疏远。'),
('CNV', '以西结书', 26, 23, 18, '她既然显露了她的淫行，露出了自己的下体，我的心就与她疏远，好像我的心从前与她姊姊疏远一样。'),
('CNV', '以西结书', 26, 23, 19, '她还加倍行淫，怀念她幼年在埃及地行淫的日子。'),
('CNV', '以西结书', 26, 23, 20, '她恋慕她的情人，他们的下体像驴的下体；他们射精像马一样。'),
('CNV', '以西结书', 26, 23, 21, '这样，你就渴想你幼年时的淫荡；那时，埃及人抚弄过你的乳房，抚摩你年幼时的胸。'),
('CNV', '以西结书', 26, 23, 22, '“因此，阿荷利巴啊！主神这样说：‘看哪！我必激动你的爱人攻击你，就是你心所疏远的人；我必带他们来从四面攻击你。'),
('CNV', '以西结书', 26, 23, 23, '他们就是巴比伦人、迦勒底人、比割人、书亚人、哥亚人，与他们一起的还有亚述人，他们都是英俊的年轻人，是作总督和省长的，作长官和战士的，全部都是骑马的。'),
('CNV', '以西结书', 26, 23, 24, '他们必带着兵器、马车、战车和大队人来攻击你；他们要拿着大小盾牌，戴着头盔，从四面摆阵攻击你；我要把审判的事交给他们，他们必按着自己的惯例来审判你。'),
('CNV', '以西结书', 26, 23, 25, '我必向你发泄我的妒忿，他们必以烈怒待你；割去你的鼻子和耳朵；你余下的人必倒在刀下；他们要掳去你的儿女；你余下的人必被火吞吃。'),
('CNV', '以西结书', 26, 23, 26, '他们必剥去你的衣服，夺去你华丽的饰物。'),
('CNV', '以西结书', 26, 23, 27, '这样，我必使你的淫荡和你从埃及地沾染的淫乱离开你，你的眼必不仰望他们，你也必不再怀念埃及。'),
('CNV', '以西结书', 26, 23, 28, '因为主神这样说：看哪！我必把你交在你所恨的人手里，就是交在你的心所疏远的人手里。'),
('CNV', '以西结书', 26, 23, 29, '他们必以憎恨待你，夺去你一切劳碌得来的，留下你赤身露体；你行淫的下体、你的淫荡和淫乱，都必显露出来。'),
('CNV', '以西结书', 26, 23, 30, '这些事要行在你身上，因为你随从列国行淫，被他们的偶像玷污了自己。'),
('CNV', '以西结书', 26, 23, 31, '你走了你姊姊所走的路，所以我必把她的杯交在你手里。'),
('CNV', '以西结书', 26, 23, 32, '主神这样说：你必喝你姊姊所喝的杯，那杯又深又阔，容量甚大，必使你成为嗤笑和讥讽的对象。'),
('CNV', '以西结书', 26, 23, 33, '你必酩酊大醉，充满愁苦，那是惊慌和荒凉的杯，就是你姊姊撒玛利亚的杯。'),
('CNV', '以西结书', 26, 23, 34, '你要喝这杯，并且喝尽；然后把这杯摔成碎块，又抓伤自己的胸。因为这是我曾说过的。’这是主神的宣告。'),
('CNV', '以西结书', 26, 23, 35, '因此，主神这样说：‘因为你忘记了我，把我丢在背后，所以你要担当你淫荡和淫乱的后果。’”'),
('CNV', '以西结书', 26, 23, 36, '主又对我说：“人子啊，你要审判阿荷拉和阿荷利巴吗？你要把她们可憎的事向她们说明，'),
('CNV', '以西结书', 26, 23, 37, '因为她们行了奸淫，手中染血，与自己的偶像行奸淫，他们甚至使自己给我所生的儿女经火，献给偶像作食物。'),
('CNV', '以西结书', 26, 23, 38, '此外，同一天，她们还向我作了这事，就是玷污我的圣所，又亵渎我的安息日。'),
('CNV', '以西结书', 26, 23, 39, '她们宰杀了自己的儿女献给偶像，同一天又进了我的圣所，把圣所亵渎。这就是她们在我殿中所行的。'),
('CNV', '以西结书', 26, 23, 40, '况且你们打发使者去请人从远方来；使者到了他们那里，他们就来了。为了他们，你们洗澡、替眼部化妆、佩戴珠宝，'),
('CNV', '以西结书', 26, 23, 41, '你们坐在华丽的床上，床前放置了一张桌子，把我的香料和膏油放在上面。'),
('CNV', '以西结书', 26, 23, 42, '在那里有安逸无忧的群众发出喧哗的声音，有粗俗的人和酒徒从旷野而来，他们把手环戴在两个妇人的手上，把美丽的冠冕戴在她们头上。'),
('CNV', '以西结书', 26, 23, 43, '“我论到这个因行淫而衰颓的妇人说：现在让人与她行淫吧，因为她本来就是妓女。'),
('CNV', '以西结书', 26, 23, 44, '他们与她同睡；人怎样与妓女同睡，也怎样与阿荷拉和阿荷利巴那两个淫荡的妇人同睡。'),
('CNV', '以西结书', 26, 23, 45, '然而必有义人判她们受淫妇和流人血的妇人所受的刑罚，因为她们是淫妇，她们手中染血。'),
('CNV', '以西结书', 26, 23, 46, '“因为主神这样说：我必使一大群人上来攻击她们，使她们惊慌，被人抢掠。'),
('CNV', '以西结书', 26, 23, 47, '这些人必用石头打她们，用刀剑砍她们，又杀戮她们的儿女，放火烧毁她们的房屋。'),
('CNV', '以西结书', 26, 23, 48, '这样，我必使淫荡从这地止息，好叫所有的妇人都受到警戒，不敢照着你们的淫荡而行。'),
('CNV', '以西结书', 26, 23, 49, '人要把你们行淫的报应归在你们身上；你们要担当你们拜偶像的罪；你们就知道我是主神。”'),
('CNV', '以西结书', 26, 24, 1, '第九年十月十日，主的话又临到我说：'),
('CNV', '以西结书', 26, 24, 2, '“人子啊！你要记下今天的日子，正正是今天，因为巴比伦王就是在这一天围困耶路撒冷。'),
('CNV', '以西结书', 26, 24, 3, '你要向这叛逆的民族设比喻，对他们说：‘主神这样说：把锅放在火上，放好了，就把水倒在锅里；'),
('CNV', '以西结书', 26, 24, 4, '把肉块，就是所有肥美的肉块，腿肉和肩肉，都放进锅里；用上好的骨头把锅装满。'),
('CNV', '以西结书', 26, 24, 5, '要选用羊群中最好的，把柴堆放在锅底下，使锅沸腾，把骨头煮在锅中。'),
('CNV', '以西结书', 26, 24, 6, '“‘因此，主神这样说：流人血的城，就是长锈的锅，有祸了！它的锈未曾除掉，要把锅里的东西一块一块取出来，不必为它们抽签。'),
('CNV', '以西结书', 26, 24, 7, '因为她所流的血还在城中；她把血泼在光滑的磐石上，不是倒在地上，被尘土掩盖。'),
('CNV', '以西结书', 26, 24, 8, '我为了发烈怒，好施行报应，就把她的血倒在光滑的磐石上，以致不得掩盖。'),
('CNV', '以西结书', 26, 24, 9, '因此，主神这样说：流人血的城，有祸了！我也必把柴堆加大。'),
('CNV', '以西结书', 26, 24, 10, '你要多加柴枝，点上火，混和香料，把肉煮烂，使骨头烧焦；'),
('CNV', '以西结书', 26, 24, 11, '然后把空锅放在炭火上，使锅烧热，使铜烧红，使其中的污秽熔化，使它的锈得以除净。'),
('CNV', '以西结书', 26, 24, 12, '这锅真叫人疲累！它厚厚的锈总没法除掉，就是用火也不能除掉。'),
('CNV', '以西结书', 26, 24, 13, '你的污秽就是淫荡。我想要洁净你，你却不愿意洁净，所以你的污秽再不能得到洁净，直等到我向你发的烈怒止息。'),
('CNV', '以西结书', 26, 24, 14, '我主已经说了。时候到了，我必成就；我必不退缩，必不顾惜，也不改变心意；我必照着你的所作所为审判你。这是主神的宣告。’”'),
('CNV', '以西结书', 26, 24, 15, '主的话又临到我说：'),
('CNV', '以西结书', 26, 24, 16, '“人子啊！我要打击你，把你眼中所喜爱的夺去，你却不可悲哀，不可哭泣，也不可流泪。'),
('CNV', '以西结书', 26, 24, 17, '只可静默地叹息，不可为死人哀悼；你的头上仍要缠着头巾，脚上仍要穿着鞋子；你不可蒙着脸，也不可吃为丧家预备的食物。”'),
('CNV', '以西结书', 26, 24, 18, '于是我在早上对众人说了这事，晚上我的妻子就死了；次日早晨我就照着所吩咐我的行了。'),
('CNV', '以西结书', 26, 24, 19, '众人问我：“你不告诉我们你这样行与我们有什么关系吗？”'),
('CNV', '以西结书', 26, 24, 20, '我回答他们：“主的话临到我说：'),
('CNV', '以西结书', 26, 24, 21, '‘你要告诉以色列家，主神这样说：看哪！我必使我的圣所被亵渎，这圣所就是你们所夸耀的势力，眼所喜爱的，心中所爱惜的。你们遗下的儿女，都必倒在刀下。'),
('CNV', '以西结书', 26, 24, 22, '那时你们要照着我所行的去行；你们不可蒙着脸，也不可吃为丧家预备的食物。'),
('CNV', '以西结书', 26, 24, 23, '你们的头上仍要缠着头巾，脚上仍要穿着鞋子；你们不可悲哀，不可哭泣；但你们必因自己的罪孽相对叹息，衰弱而死。'),
('CNV', '以西结书', 26, 24, 24, '以西结必成为你们的一个兆头；凡他所行的，将来你们也要照样行。这事来到，你们就知道我是主神。’'),
('CNV', '以西结书', 26, 24, 25, '“人子啊！我从他们中间夺去他们的堡垒、他们所喜欢的荣耀、他们眼所喜爱的、心所崇尚的和他们的儿女的时候，'),
('CNV', '以西结书', 26, 24, 26, '岂没有逃脱的人来到你那里，使你听见这事吗？'),
('CNV', '以西结书', 26, 24, 27, '那时，你要向逃脱的人开口说话，不再作哑巴。你必成为他们的一个兆头。他们就知道我是主。”'),
('CNV', '以西结书', 26, 25, 1, '主的话临到我说：'),
('CNV', '以西结书', 26, 25, 2, '“人子啊！你要面对亚扪人，说预言攻击他们。'),
('CNV', '以西结书', 26, 25, 3, '你要对亚扪人说：‘你们要听主神的话。主神这样说：我的圣所被亵渎，以色列地荒凉，犹大家被掳去的时候，你说：“哈哈！”'),
('CNV', '以西结书', 26, 25, 4, '所以我要把你交给东方人作产业；他们必在你那里安营，在你那里设立居所；他们必吃你的果子，喝你的奶。'),
('CNV', '以西结书', 26, 25, 5, '我必使拉巴成为牧放骆驼的地方，使亚扪人之地成为羊群躺卧之处。你们就知道我是主。'),
('CNV', '以西结书', 26, 25, 6, '主神这样说：因为你手舞足蹈，心存轻蔑，因以色列地的遭遇而欢喜。'),
('CNV', '以西结书', 26, 25, 7, '所以我必伸手攻击你，把你交给列国作掠物；我必从万族中剪除你，使你从列邦中灭亡；我必消灭你，你就知道我是主。’”'),
('CNV', '以西结书', 26, 25, 8, '主神这样说：“因为摩押和西珥说：‘看哪！犹大家与列国毫无分别’，'),
('CNV', '以西结书', 26, 25, 9, '所以我必除去摩押一面的防守，从边界的城市开始，就是他们看为那地之荣美的伯．耶西末、巴力．免和基列亭。'),
('CNV', '以西结书', 26, 25, 10, '我必把摩押连同亚扪人一起交给东方人作产业，使亚扪不再在列国中被记念。'),
('CNV', '以西结书', 26, 25, 11, '我要向摩押施行审判，他们就知道我是主。”'),
('CNV', '以西结书', 26, 25, 12, '主神这样说：“因为以东向犹大家报仇雪恨。他们这样作，就犯了大罪。'),
('CNV', '以西结书', 26, 25, 13, '所以主神这样说：我必伸手攻击以东，把人和牲畜都从其中剪除；我必使以东荒凉；从提幔直到底但，他们都要倒毙在刀下。'),
('CNV', '以西结书', 26, 25, 14, '我必藉着我子民以色列的手报复以东；以色列人必照着我的怒气，按着我的烈怒对待以东，以东人就知道这是我的报复。这是主神的宣告。”'),
('CNV', '以西结书', 26, 25, 15, '主神这样说：“因为非利士人向犹大人报仇雪恨，心存轻蔑报仇雪恨，他们永远怀恨，要毁灭犹大，'),
('CNV', '以西结书', 26, 25, 16, '因此，主神这样说：看哪！我要伸手攻击非利士人，剪除基利提人，消灭沿海剩下的人。'),
('CNV', '以西结书', 26, 25, 17, '我必怒责他们，向他们大施报复；我向他们报复的时候，他们就知道我是主。”'),
('CNV', '以西结书', 26, 26, 1, '第十一年某月初一日，主的话临到我说：'),
('CNV', '以西结书', 26, 26, 2, '“人子啊！因为推罗论到耶路撒冷说：‘哈哈！那万族的门已经破坏了，向我打开了；我必得丰满，她却成了荒场！’'),
('CNV', '以西结书', 26, 26, 3, '所以主神这样说：‘推罗啊！我要与你为敌；我必叫多国上来攻击你，好像海使波浪涌上来一样。'),
('CNV', '以西结书', 26, 26, 4, '他们必毁坏推罗的城墙，拆毁它的城楼；我必刮净它的尘土，使它成为光滑的磐石。'),
('CNV', '以西结书', 26, 26, 5, '它必在海中作晒网的地方，因为我已经说了。这是主的宣告。它必成为列国的掠物，'),
('CNV', '以西结书', 26, 26, 6, '那些在陆地居住的推罗人必被刀剑所杀；然后，他们就知道我是主。'),
('CNV', '以西结书', 26, 26, 7, '“‘因为主神这样说：看哪！我要使诸王之王，就是巴比伦王尼布甲尼撒，率领马匹、战车、骑兵和一支大军，从北方来攻击推罗。'),
('CNV', '以西结书', 26, 26, 8, '他必用刀剑杀戮你那些在陆地居住的人；他必建造围城的高墙，筑起土垒，举起盾牌攻击你。'),
('CNV', '以西结书', 26, 26, 9, '他必用攻城锤攻击你的城墙，用武器拆毁你的城楼。'),
('CNV', '以西结书', 26, 26, 10, '因为他的马匹众多，它们扬起的尘土必遮盖你；他进入你的城门，好像人进入已有破口的城，那时，你的城墙必因骑兵、车轮和战车的响声而震动。'),
('CNV', '以西结书', 26, 26, 11, '他的马蹄必践踏你所有的街道；他必用刀杀戮你的人民；你坚固的柱子必倒在地上。'),
('CNV', '以西结书', 26, 26, 12, '他们必掳去你的财富，以你的货财为掠物；他们必破坏你的城墙，拆毁你华丽的房屋，把你的石头、木头和瓦砾都投在水中。'),
('CNV', '以西结书', 26, 26, 13, '我必使你唱歌的喧声止息；人也再听不到你的琴声。'),
('CNV', '以西结书', 26, 26, 14, '我必使你成为光滑的磐石；你必成为晒网的地方；你必不再被建造，因为我主已经说了。这是主神的宣告。’'),
('CNV', '以西结书', 26, 26, 15, '“主神对推罗这样说：‘杀戮在你中间发生，受伤的人都在唉哼的时候，众海岛岂不因你倾倒的声音而震动吗？'),
('CNV', '以西结书', 26, 26, 16, '那时所有沿海的君王都必由王座下来，除去朝服，脱下刺绣的衣服；披上战兢，坐在地上，不停发抖，因你而惊骇。'),
('CNV', '以西结书', 26, 26, 17, '他们必为你作一首哀歌说：你这著名的城，航海之人的居所，在海上坚固有力的啊！你和你的居民素来使惊恐临到所有住在那里的人身上，你怎么绝了迹呢？'),
('CNV', '以西结书', 26, 26, 18, '现在海岛的居民在你倾倒的日子，都必战兢；众海岛因你的毁灭而惊惶。'),
('CNV', '以西结书', 26, 26, 19, '因为主神这样说：我使你成为荒废的城市，像没有人居住的城镇；我使深渊的水上升漫过你，使大水淹没你，'),
('CNV', '以西结书', 26, 26, 20, '那时，我要使你与那些下到阴府的人一起，下到古时的人那里去；我要使你住在地的深处，就是住在久而荒废之地，与那些下到阴府的人在一起，以致你不再在活人的境界重现（“不再在活人的境界重现”这译法是参考古译本，原文作“不再返回，我却要在活人境地显出荣耀”）。'),
('CNV', '以西结书', 26, 26, 21, '我必使你遭遇可怕的灾祸，你就不再存在了；人虽然寻找你，却永不再寻得着。这是主神的宣告。’”'),
('CNV', '以西结书', 26, 27, 1, '主的话临到我说：'),
('CNV', '以西结书', 26, 27, 2, '“人子啊！你要为推罗作一首哀歌。'),
('CNV', '以西结书', 26, 27, 3, '要对那位于海口，跟沿海邦国通商的推罗说：‘主神这样说：推罗啊！你曾经说过：我是全然美丽的。'),
('CNV', '以西结书', 26, 27, 4, '你的疆界在众海中心，建造你的使你全然美丽。'),
('CNV', '以西结书', 26, 27, 5, '他们用示尼珥的松树做你所有的木板；用黎巴嫩的香柏树做你的桅杆；'),
('CNV', '以西结书', 26, 27, 6, '用巴珊的橡树做你的桨；用基提沿岸的黄杨木镶嵌着象牙，做你的舱板。'),
('CNV', '以西结书', 26, 27, 7, '你的帆是用埃及刺绣的细麻布做的，可作你的旗帜；你的篷是用以利沙沿岸的蓝色和紫色布做的。'),
('CNV', '以西结书', 26, 27, 8, '西顿和亚发的居民给你荡桨；推罗啊！你中间的技师作你的舵手。'),
('CNV', '以西结书', 26, 27, 9, '迦巴勒的技师和老练的工匠都在你那里修补裂缝；所有海上的船只和水手都在你那里，与你进行贸易。'),
('CNV', '以西结书', 26, 27, 10, '波斯人、路德人、弗人都在你的军队中作战士；他们在你那里挂起盾牌和头盔，彰显你的光荣。'),
('CNV', '以西结书', 26, 27, 11, '在你四围的城墙上有亚发人和赫勒克人（“赫勒克人”或译：“你的军兵”）；在你的城楼上有歌玛底人（“歌玛底人”或译：“勇士”）。他们把自己的盾牌挂在你四围的城墙上，使你全然美丽。'),
('CNV', '以西结书', 26, 27, 12, '“他施人因你各样丰富的财物，就作你的贸易伙伴；他们用银、铁、锡和铅来换取你的货物。'),
('CNV', '以西结书', 26, 27, 13, '雅完人、土巴人和米设人都与你通商；他们用奴隶和铜器来换取你的商品。'),
('CNV', '以西结书', 26, 27, 14, '伯陀迦玛人用马、战马和骡子来换取你的货物。'),
('CNV', '以西结书', 26, 27, 15, '底但人与你通商，沿海许多地方都作你贸易的市场；他们用象牙和乌木支付给你。'),
('CNV', '以西结书', 26, 27, 16, '亚兰人因你的产品很多，就作你的贸易伙伴；他们用绿宝石、紫色布、刺绣、细麻布、珊瑚、红宝石，来换取你的货物。'),
('CNV', '以西结书', 26, 27, 17, '犹大和以色列地都与你通商；他们用米匿的麦子、饼、蜜、油和乳香来换取你的商品。'),
('CNV', '以西结书', 26, 27, 18, '大马士革人因你产品很多，又因你各样丰富的财物，就用黑本酒和白羊毛（“白羊毛”或译：“察哈尔羊毛”）来与你交易，'),
('CNV', '以西结书', 26, 27, 19, '威但人用乌萨出的酒（“用乌萨出的酒”原文作“和从乌萨来的雅完人”）来换取你的货物；他们用锻铁、桂皮和菖蒲，来交换你的商品。'),
('CNV', '以西结书', 26, 27, 20, '底但人用马鞍毯子来与你交易。'),
('CNV', '以西结书', 26, 27, 21, '阿拉伯人和基达所有的领袖都作你通商的顾客；他们用羊羔、绵羊和山羊，来与你交易。'),
('CNV', '以西结书', 26, 27, 22, '示巴和拉玛的商人都与你交易；他们用各样上等的香料，各种宝石和黄金，来换取你的货物。'),
('CNV', '以西结书', 26, 27, 23, '哈兰人、干尼人、伊甸人、示巴的商人、亚述人和基抹人，都与你交易。'),
('CNV', '以西结书', 26, 27, 24, '他们用美丽的衣服、蓝色刺绣的袍子、色彩缤纷的地毯，用绳子绑得结实，在你的市场上与你交易。'),
('CNV', '以西结书', 26, 27, 25, '他施的船只运载你的商品，你在海的中心，满载货物，极其沉重。'),
('CNV', '以西结书', 26, 27, 26, '给你荡桨的已经把你荡到水深之处；东风在海的中心把你吹破。'),
('CNV', '以西结书', 26, 27, 27, '你的财富、货物、商品、水手、舵手、修补裂缝的、与你进行贸易的，在你那里所有的战士，并在你中间所有聚集的人、在你倾覆的日子，都必在海的中心沉下去。'),
('CNV', '以西结书', 26, 27, 28, '因你舵手的呼叫声，郊野都必震动。'),
('CNV', '以西结书', 26, 27, 29, '所有荡桨的、水手和航海的舵手，都必离开他们的船只，站在陆上。'),
('CNV', '以西结书', 26, 27, 30, '他们必为你放声痛哭，把尘土撒在自己的头上，在灰中打滚。'),
('CNV', '以西结书', 26, 27, 31, '他们必因你把头剃光，腰束麻布，为你痛心哭泣，苦苦悲哀。'),
('CNV', '以西结书', 26, 27, 32, '他们为你哀悼的时候，必为你作一首哀歌：有哪一座城，像在海中沉寂的推罗呢？'),
('CNV', '以西结书', 26, 27, 33, '你的货物从海上运出去的时候，曾使多国的人饱足；因你丰富的财物和商品，你使地上的君王都富裕。'),
('CNV', '以西结书', 26, 27, 34, '如今你在深水的地方，被海水冲破；你的商品和所有在你那里聚集的人，都沉下去了。'),
('CNV', '以西结书', 26, 27, 35, '沿海地带所有的居民都因你惊骇；他们的君王都极其恐慌，面容扭曲。'),
('CNV', '以西结书', 26, 27, 36, '各族的商人都嗤笑你；你必遭遇可怕的灾祸，你就永远不再存在了。’”'),
('CNV', '以西结书', 26, 28, 1, '主的话临到我说：'),
('CNV', '以西结书', 26, 28, 2, '“人子啊！你要对推罗的君王说：‘主神这样说：因为你心里高傲，说：我是神；我在海的中心、坐在神的宝座上。其实你不过是人，并不是神，你心里却自以为是神。'),
('CNV', '以西结书', 26, 28, 3, '你比但以理更有智慧！任何秘密的事都不能隐瞒你！'),
('CNV', '以西结书', 26, 28, 4, '你靠着自己的智慧和聪明，为自己得了财富，把所得的金银放进自己的府库里。'),
('CNV', '以西结书', 26, 28, 5, '你靠着自己在贸易上的大智慧，增添你的财富，你又因自己的财富心里高傲。'),
('CNV', '以西结书', 26, 28, 6, '因此，主神这样说：因为你心里自以为是神，'),
('CNV', '以西结书', 26, 28, 7, '所以我要使外族人，就是列国中最强横的人，来攻击你；他们要拔出刀来，攻击你用智慧得来的美物，玷污你的光彩。'),
('CNV', '以西结书', 26, 28, 8, '他们必使你下到坑中，你必被杀害，死在海的中心。'),
('CNV', '以西结书', 26, 28, 9, '在杀戮你的人面前，你还能说“我是神”吗？在那些杀害你的人手里，你不过是人，并不是神。'),
('CNV', '以西结书', 26, 28, 10, '你必死在外族人手里，与未受割礼的人一样，因为这是我曾说过的，这是主神的宣告。’”'),
('CNV', '以西结书', 26, 28, 11, '主的话又临到我说：'),
('CNV', '以西结书', 26, 28, 12, '“人子啊！你要为推罗王作一首哀歌，对他说：‘主神这样说：你是完美的典范，满有智慧，全然美丽。'),
('CNV', '以西结书', 26, 28, 13, '你曾在伊甸、神的园中，有各样的宝石作你的衣服，就是红宝石、黄玉、金钢石、水苍玉、红玛瑙、碧玉、蓝宝石、绿宝石和翡翠；宝石座是用金制造的，这些都是在你被造的日子就预备好了的。'),
('CNV', '以西结书', 26, 28, 14, '你是护卫宝座的、受膏的基路伯；我安置你在神的圣山上，你在闪耀如火的宝石中间行走。'),
('CNV', '以西结书', 26, 28, 15, '从你被造的日子起，你的行为都无可指摘，直到在你中间有了罪孽为止。'),
('CNV', '以西结书', 26, 28, 16, '因你的贸易昌盛，你中间就充满了强暴的事，你也犯了罪，所以我把你当作污秽之物，从神的山把你抛弃。护卫宝座的基路伯啊！我要把你从闪耀如火的宝石中除掉。'),
('CNV', '以西结书', 26, 28, 17, '你因自己的美丽心里高傲，又因你的光彩败坏了你的智慧。所以我把你抛在地上；放在列王面前，好让他们观看。'),
('CNV', '以西结书', 26, 28, 18, '你因罪孽众多，又因贸易上的罪恶，玷污了你的圣所，因此我使火从你中间出来，这火要吞灭你。我要在所有观看你的人眼前，把你变为地上的灰烬。'),
('CNV', '以西结书', 26, 28, 19, '万族中认识你的，都必因你惊骇；你必遭遇可怕的灾祸，你就永远不再存在了。’”'),
('CNV', '以西结书', 26, 28, 20, '主的话临到我说：'),
('CNV', '以西结书', 26, 28, 21, '“人子啊！你要面向西顿，说预言攻击它，'),
('CNV', '以西结书', 26, 28, 22, '你要说：‘主神这样说：西顿啊，我要与你为敌！我要在你中间得荣耀。我在它身上施行审判，彰显我的圣洁的时候，人就知道我是主。'),
('CNV', '以西结书', 26, 28, 23, '我必使瘟疫进入西顿，使血流在它的街上；必有刀剑四围攻击它，使被杀的人倒在城中，人就知道我是主。'),
('CNV', '以西结书', 26, 28, 24, '四围一切恨恶以色列家的人，必不再向他们作刺人的荆棘、使人痛苦的蒺藜。人就知道我是主神。'),
('CNV', '以西结书', 26, 28, 25, '“‘主神这样说：我把以色列家从他们所分散到的万族中招聚回来的时候，我必在他们身上向列国显为圣，以色列家必在自己的地方，就是赐给我仆人雅各的地。'),
('CNV', '以西结书', 26, 28, 26, '他们必安然居住，建造房屋，栽种葡萄园；我向四围所有恨恶他们的人施行审判以后，他们必安然居住；人就知道我是主他们的神。’”'),
('CNV', '以西结书', 26, 29, 1, '第十年十月十二日，主的话临到我说：'),
('CNV', '以西结书', 26, 29, 2, '“人子啊！你要面向埃及王法老，说预言攻击他和埃及全地。'),
('CNV', '以西结书', 26, 29, 3, '你要说：‘主神这样说：埃及王法老啊！我要与你为敌，你这卧在自己河中的大海怪，你曾经说过：“这河是我的，是我自己造的。”'),
('CNV', '以西结书', 26, 29, 4, '但我主必用钩子钩住你的腮颊，使你河中的鱼都紧贴着你的鳞甲，我必把你和你河中所有紧贴着你的鳞甲的鱼，都从你河中拉上来。'),
('CNV', '以西结书', 26, 29, 5, '我必把你和你河中所有的鱼，都丢在旷野；你必倒在田间，无人收殓，无人埋葬。我已经把你给了地上的走兽和空中的飞鸟作食物。'),
('CNV', '以西结书', 26, 29, 6, '埃及所有的居民就都知道我是主。因为你作了以色列家芦苇的杖。'),
('CNV', '以西结书', 26, 29, 7, '他们用手抓住你的时候，你就断裂，伤了他们的肩头；他们倚靠你，你就折断、扭伤了他们的腰。'),
('CNV', '以西结书', 26, 29, 8, '因此，主神这样说：看哪！我必使刀剑攻击你，把人和牲畜都从你那里剪除。'),
('CNV', '以西结书', 26, 29, 9, '埃及地必荒凉废弃，人就知道我是主。“‘因为法老曾说：“这河是我的，是我自己做的。”'),
('CNV', '以西结书', 26, 29, 10, '所以我必与你和你的河为敌；我必使埃及地，从密夺到色弗尼，直到古实边界，都全然荒凉废弃。'),
('CNV', '以西结书', 26, 29, 11, '人的脚必不经过那里，兽的蹄也不经过那里；四十年之久，无人居住。'),
('CNV', '以西结书', 26, 29, 12, '我必使埃及成为荒地中的荒地，四十年之久，它的城必成为废城中的废城。我必把埃及人分散到列邦，四散在各地。'),
('CNV', '以西结书', 26, 29, 13, '“‘主神这样说：满了四十年，我必把埃及人从他们所分散到的万族中招聚回来。'),
('CNV', '以西结书', 26, 29, 14, '我必使埃及被掳的人归回，使他们归回自己根源之地巴忒罗，在那里他们必成为低微的国。'),
('CNV', '以西结书', 26, 29, 15, '这国必成为列国中最低微的，也必不能再攀到列国之上；我必使他们弱小，以致他们不能再管辖列国。'),
('CNV', '以西结书', 26, 29, 16, '埃及必不再作以色列家的倚靠；每逢以色列家转去仰赖埃及人的时候，他们就想起自己的罪孽。这样，他们就知道我是主神。’”'),
('CNV', '以西结书', 26, 29, 17, '二十七年正月初一日，主的话临到我说：'),
('CNV', '以西结书', 26, 29, 18, '“人子啊！巴比伦王尼布甲尼撒使他的军兵千辛万苦攻打推罗，以致各人都头秃肩破；但是他和他的军兵攻打推罗所付出的辛劳，并没有从那里得到什么报酬。'),
('CNV', '以西结书', 26, 29, 19, '因此，主神这样说：看哪！我必把埃及地赐给巴比伦王尼布甲尼撒，他把埃及的财富带走，抢其中的财为掳物，夺其中的货为掠物，作他军兵的报酬。'),
('CNV', '以西结书', 26, 29, 20, '我把埃及地赐给他，作辛劳的报酬，因为他们都是为我效力的。这是主神的宣告。'),
('CNV', '以西结书', 26, 29, 21, '到了那天，我必使以色列家的角生出来，我也必使你以西结在他们中间开口。他们就知道我是主。”'),
('CNV', '以西结书', 26, 30, 1, '主的话又临到我说：'),
('CNV', '以西结书', 26, 30, 2, '“人子啊！你要说预言：‘主神这样说：你们要哀号：那一天有祸了！'),
('CNV', '以西结书', 26, 30, 3, '因为那一天临近了，主的日子临近了，就是密云的日子，列国受罚的时候。'),
('CNV', '以西结书', 26, 30, 4, '必有刀剑临到埃及，被杀的人倒在埃及的时候，在古实就有痛苦；埃及的财富必被夺去，它的根基必被拆毁。'),
('CNV', '以西结书', 26, 30, 5, '古实人、弗人、路德人、所有外族的人、吕彼亚（“吕彼亚”原文作“古巴”）人，以及与埃及结盟的人，都必与埃及人一起倒在刀下。'),
('CNV', '以西结书', 26, 30, 6, '“‘主这样说：那些支持埃及的必倾倒，埃及所夸耀的势力必衰落。从密夺到色弗尼，他们都必倒在刀下；这是主神说的：'),
('CNV', '以西结书', 26, 30, 7, '埃及必成为荒地中的荒地，它的城必成为废城中的废城。'),
('CNV', '以西结书', 26, 30, 8, '我在埃及点起火来的时候，所有帮助埃及的都必灭亡；那时他们就知道我是主。'),
('CNV', '以西结书', 26, 30, 9, '那一天，必有使者从我面前乘船出去，使安逸无虑的古实人惊慌；在埃及遭难的日子，必有痛苦临到他们。看哪！这事来到了！'),
('CNV', '以西结书', 26, 30, 10, '主神这样说：“‘我必藉着巴比伦王尼布甲尼撒的手，消灭埃及的财富。'),
('CNV', '以西结书', 26, 30, 11, '他和跟随他的人，就是列国中最强横的人，必被领进来，毁灭这地；他们必拔出刀来攻击埃及，使遍地满了被杀的人。'),
('CNV', '以西结书', 26, 30, 12, '我必使江河干涸，把这地卖给恶人；我必藉着外族人的手，使这地和其中所充满的，都变成荒凉。我主已经说了。'),
('CNV', '以西结书', 26, 30, 13, '主神这样说：“‘我必毁灭偶像，使虚无的神像从挪弗灭绝。必不再有君王从埃及地而出；我也必使惧怕临到埃及地。'),
('CNV', '以西结书', 26, 30, 14, '我必使巴忒罗荒凉，也必在琐安点起火来，又向挪施行审判。'),
('CNV', '以西结书', 26, 30, 15, '我必把我的烈怒倒在训上，就是埃及的保障，并要剪除挪的众民。'),
('CNV', '以西结书', 26, 30, 16, '我必在埃及点起火来；训必有大痛苦；挪必被攻破；挪弗必终日受难。'),
('CNV', '以西结书', 26, 30, 17, '亚文和比伯实的年轻人都必倒在刀下；这些城的人必被掳去。'),
('CNV', '以西结书', 26, 30, 18, '我在答比匿折断埃及众轭的时候，白昼就必变为黑暗；埃及所夸耀的势力必在其中止息；这城必有密云遮盖，城中的居民必被掳去。'),
('CNV', '以西结书', 26, 30, 19, '我必这样向埃及施行审判，他们就知道我是主。’”'),
('CNV', '以西结书', 26, 30, 20, '十一年正月初七日，主的话临到我说：'),
('CNV', '以西结书', 26, 30, 21, '“人子啊！我折断了埃及王法老的膀臂；看哪！没有人把它包扎治疗，没有人用绷带把它缠裹，好让它有力量拿起刀来。'),
('CNV', '以西结书', 26, 30, 22, '因此，主神这样说：‘看哪！我与埃及王法老为敌；我必打断他有力的膀臂，和已经折了的膀臂，使刀从他的手中掉下。'),
('CNV', '以西结书', 26, 30, 23, '我必把埃及人分散到列邦，四散在各地。'),
('CNV', '以西结书', 26, 30, 24, '“‘我必使巴比伦王的膀臂有力量，把我的刀交在他手中；我要折断法老的膀臂，使他在巴比伦王面前呻吟，像一个受伤快死的人一样。'),
('CNV', '以西结书', 26, 30, 25, '我必使巴比伦王的膀臂有力量，法老的膀臂却要下垂。我把我的刀交在巴比伦王手里，使他举刀攻击埃及地的时候，他们就知道我是主。'),
('CNV', '以西结书', 26, 30, 26, '我必把埃及人分散到列邦，四散在各地；他们就知道我是主。’”'),
('CNV', '以西结书', 26, 31, 1, '十一年三月初一日，主的话临到我说：'),
('CNV', '以西结书', 26, 31, 2, '“人子啊！你要对埃及王法老和他的众民说：‘论到你的伟大，谁能与你相比呢？'),
('CNV', '以西结书', 26, 31, 3, '看哪！亚述曾是黎巴嫩的香柏树，枝条秀美，林影茂密，树身高大，树顶在茂密的枝叶之上。'),
('CNV', '以西结书', 26, 31, 4, '众水使它长大，深渊使它长高；有江河从深渊流出环绕它栽种之地，又有支流延到田间的众树。'),
('CNV', '以西结书', 26, 31, 5, '因此，它树身高大，高过田间的众树；它发旺生长的时候，因为水源丰足，所以枝子繁多，枝条长长。'),
('CNV', '以西结书', 26, 31, 6, '空中的飞鸟都在枝上搭窝；田野的走兽都在枝条下生产；所有大国都在它的树荫下居住。'),
('CNV', '以西结书', 26, 31, 7, '它树身高大，枝条长长而显得秀美，因为它的根扎在水多的地方。'),
('CNV', '以西结书', 26, 31, 8, '神园中的香柏树不能与它相比，松树比不上它的枝子；枫树也不及它的枝条；神园中所有的树木都比不上它的秀美。'),
('CNV', '以西结书', 26, 31, 9, '我使它因枝条繁多而显得秀美，以致在神的园中，伊甸所有的树木都嫉妒它。'),
('CNV', '以西结书', 26, 31, 10, '“‘因此，主神这样说：因为它树身高大，树顶在茂密的枝叶之上，又因它高大而心骄气傲，'),
('CNV', '以西结书', 26, 31, 11, '我就把它交在列国中为首的人手中，他必定对付它；因着它的罪恶，我就把它驱逐出去。'),
('CNV', '以西结书', 26, 31, 12, '必有外族人，就是列国中最强暴的，把它砍下丢弃。它的枝叶落在山上和所有的谷中；它的枝子折断，落在地上所有的水沟里；地上的万族都必走离它的荫下，把它丢弃。'),
('CNV', '以西结书', 26, 31, 13, '空中的飞鸟都住在倒下的树身上，田野的走兽都卧在它的枝条间。'),
('CNV', '以西结书', 26, 31, 14, '好使水旁所有的树木都不会因树身高大而自高，也不会使树顶长到茂密的枝叶上，又使一切有水滋润的树都不会高傲地屹立；因为他们在世人中，与那些下到阴府的人一起，都交与死亡、交与地的深处了。'),
('CNV', '以西结书', 26, 31, 15, '“‘主神这样说：它下阴间的日子，我就因它以悲哀遮盖深渊，阻塞深渊的江河，使大水停流；我要使黎巴嫩为它悲伤、田野所有的树木都因它枯干。'),
('CNV', '以西结书', 26, 31, 16, '我把它扔下阴间，与那些下到阴府的人一起的时候，我就使列国因它坠落的响声而震惊。伊甸所有的树木，就是黎巴嫩有水滋润、最佳最美的树，都在地的深处得到安慰。'),
('CNV', '以西结书', 26, 31, 17, '这些树与它一同下到阴间，往那些被刀剑所杀的人那里去。他们作过它的膀臂，曾在列国中住在它的荫下。'),
('CNV', '以西结书', 26, 31, 18, '在伊甸所有的树木中，有谁的荣美和高大能与你相比呢？然而你却要与伊甸的树木一同下到地的深处。你要在没有受割礼的人中，与被刀剑所杀的人一同躺卧。这树就是法老和他的众民。这是主神说的。’”'),
('CNV', '以西结书', 26, 32, 1, '十二年十二月初一日，主的话临到我说：'),
('CNV', '以西结书', 26, 32, 2, '“人子啊！你要为埃及王法老作一首哀歌，对他说：‘你像列国中的少壮狮子，又像海中的海怪，你在河中翻腾，用你的爪搅动河水，使江河浑浊。'),
('CNV', '以西结书', 26, 32, 3, '主神这样说：我必用多国的群众，把我的网撒在你身上，他们必用我的网把你拉上来。'),
('CNV', '以西结书', 26, 32, 4, '我必把你丢弃在地上，抛掷在田野，使空中的飞鸟都住在你身上，使地上所有的野兽都吃你而得饱足。'),
('CNV', '以西结书', 26, 32, 5, '我必把你的肉丢在山上，把你高大的尸体填满山谷。'),
('CNV', '以西结书', 26, 32, 6, '我必用你流出的血浇灌地面，直到山上，水沟都必充满你的血。'),
('CNV', '以西结书', 26, 32, 7, '我毁灭你的时候，必把天遮蔽，使天上的星昏暗，用密云遮盖太阳；月亮也必不发光。'),
('CNV', '以西结书', 26, 32, 8, '我必使天上所有的光体都在你以上变为昏暗；我必使黑暗笼罩你的地；这是主神的宣告。'),
('CNV', '以西结书', 26, 32, 9, '我使你在列国中灭亡的消息，传到你所不认识的列邦的时候，我必使万族的心感到不安。'),
('CNV', '以西结书', 26, 32, 10, '我在他们面前向你挥动刀剑的时候，他们必因你惊骇，他们的君王也必因你非常恐慌；在你倾覆的日子，他们各人都必为自己的性命时刻战兢。'),
('CNV', '以西结书', 26, 32, 11, '“‘主神这样说：巴比伦王的刀必临到你。'),
('CNV', '以西结书', 26, 32, 12, '我必藉着勇士的刀使你的众民倒下，这些勇士都是列国中最强横的人。他们必毁灭埃及所夸耀的；埃及的众民都必消灭。'),
('CNV', '以西结书', 26, 32, 13, '我必从众水的旁边，除灭埃及所有的牲畜；人的脚必不再搅浊这些水，牲畜的蹄也不这样作。'),
('CNV', '以西结书', 26, 32, 14, '那时，我必使众水澄清，使江河的水像油一样缓流；这是主神的宣告。'),
('CNV', '以西结书', 26, 32, 15, '我使埃及地荒凉，使这地失去它所充满的，又击杀其中所有的居民。那时，他们就知道我是主。'),
('CNV', '以西结书', 26, 32, 16, '这就是人为埃及所唱的哀歌，列国的女子必唱这哀歌；她们必为埃及和它的众民唱这哀歌。这是主神的宣告。’”'),
('CNV', '以西结书', 26, 32, 17, '十二年十二月十五日，主的话临到我说：'),
('CNV', '以西结书', 26, 32, 18, '“人子啊！你要为埃及的众民哀号，要把埃及和强国的女子，与下坑的人一同送到地府那里。'),
('CNV', '以西结书', 26, 32, 19, '你要对埃及说：‘你比谁更优越呢？你下去与那些没有受割礼的人一起长眠吧！’'),
('CNV', '以西结书', 26, 32, 20, '他们必倒在那些被刀所杀的人中间；刀既拔出，埃及和它的众民都要被拉下去。'),
('CNV', '以西结书', 26, 32, 21, '勇士中最强的必在阴间论到埃及和帮助埃及的说：‘他们已经下来了，他们与没有受割礼的，就是被刀所杀的人，一起长眠。’'),
('CNV', '以西结书', 26, 32, 22, '“亚述和它的军队都在那里；他们的坟墓在它周围；他们都是被杀死的，是倒在刀下的。'),
('CNV', '以西结书', 26, 32, 23, '他们的坟墓是放在坑中极深之处，亚述的众军都在它坟墓的周围，全是被杀死的，是倒在刀下的；他们曾使惊恐散布在活人之地。'),
('CNV', '以西结书', 26, 32, 24, '“以拦也在那里，它的众民都在它坟墓的周围，全是被杀死的，是倒在刀下的；他们没有受割礼而下到地府去；他们曾使惊恐散布在活人之地，现在他们与下坑的人一同担当自己的羞辱。'),
('CNV', '以西结书', 26, 32, 25, '在被杀的人中，有床为它和它的众民安设；他们的坟墓都在它周围；他们都是没有受割礼的，是被刀所杀的；他们曾使惊恐散布在活人之地。现在他们与下坑的人一同担当自己的羞辱；以拦被安置在被杀的人中间。'),
('CNV', '以西结书', 26, 32, 26, '“米设、土巴和它们所有的人民都在那里；他们的坟墓都在米设和土巴的周围；他们都是没有受割礼的，是被刀所杀的；他们曾使惊恐散布在活人之地。'),
('CNV', '以西结书', 26, 32, 27, '他们不都是与那些没有受割礼而倒毙的勇士一起长眠吗？这些勇士都带着兵器下到阴间，刀剑都放在自己的头下。他们的罪孽是在自己的骨头上。他们曾使惊恐散布在活人之地。'),
('CNV', '以西结书', 26, 32, 28, '法老啊！至于你，你必在没有受割礼的人中被毁灭，与那些被刀所杀的人一起长眠。'),
('CNV', '以西结书', 26, 32, 29, '“以东也在那里，以东的众王和所有首领虽然英勇，还是与被刀所杀的人列在一起。他们必与没有受割礼而下坑的人一起长眠。'),
('CNV', '以西结书', 26, 32, 30, '“在那里有北方的众首领和所有西顿人；他们都与被杀死的人一同下去，他们虽然英勇，使人惊恐，还是蒙受了羞辱；他们没有受割礼而与那些被刀所杀的人一起长眠，与那些下坑的人一同担当羞辱。'),
('CNV', '以西结书', 26, 32, 31, '“法老看见他们，就必为被刀所杀的众民，就是法老自己和他的全军，得了安慰。这是主神的宣告。'),
('CNV', '以西结书', 26, 32, 32, '虽然我任凭法老使惊恐散布在活人之地，他和他的众民必在没有受割礼的人中，与被刀所杀的人一起长眠。这是主神的宣告。”'),
('CNV', '以西结书', 26, 33, 1, '主的话临到我说：'),
('CNV', '以西结书', 26, 33, 2, '“人子啊！你要告诉你本国的人，说：‘我使刀剑临到一地，那地的人民从他们中间选出一个人，作他们的守望者；'),
('CNV', '以西结书', 26, 33, 3, '这人见刀剑临到那地，就吹响号角，警告众人；'),
('CNV', '以西结书', 26, 33, 4, '凡听见号角声而不接受警告的，刀剑若来把他除灭，他的罪（“罪”原文作“血”）就要归到自己的头上；'),
('CNV', '以西结书', 26, 33, 5, '他既然听见号角声而不接受警告，所以他的罪（“罪”原文作“血”）要归到自己的身上；他若接受警告，就可以救回自己的性命了。'),
('CNV', '以西结书', 26, 33, 6, '但是，那守望的人若见刀剑临到，却不吹响号角，以致人民没有受到警告，刀剑来把他们中间的一个人除灭；那人虽然因自己的罪孽被除灭，我却要因他的死追究守望的人。’'),
('CNV', '以西结书', 26, 33, 7, '“人子啊！我立了你作以色列家守望的人，所以你要聆听我口中的话，替我警告他们。'),
('CNV', '以西结书', 26, 33, 8, '如果我对恶人说：‘恶人啊，你必定死亡！’你以西结却不出声警告恶人离开他所行的，这恶人就必因自己的罪孽死亡，我却要因他的死追究你。'),
('CNV', '以西结书', 26, 33, 9, '如果你警告恶人，叫他离开他所行的，他仍不转离，他就必因自己的罪孽死亡，你却救了自己的性命。'),
('CNV', '以西结书', 26, 33, 10, '“人子啊！你要对以色列家说：‘你们这样说：我们的过犯和罪恶常在我们身上；我们必因此衰弱而死，怎能存活呢？’'),
('CNV', '以西结书', 26, 33, 11, '你要对他们说：‘主神这样宣告：我指着我的永生起誓，我绝不喜悦恶人死亡，却喜悦恶人离开他所行的，得以存活。以色列家啊，回转吧！离开你们所行的，何必死亡呢？’'),
('CNV', '以西结书', 26, 33, 12, '人子啊！你要对你本国的人说：‘义人的义在他犯罪的日子，不能救他；恶人的恶在他离开恶行的日子，也不会绊倒他；义人在他犯罪的日子，也不能因他的义存活。’'),
('CNV', '以西结书', 26, 33, 13, '我虽然对义人说他必定生存，但是他若恃着自己的义而行恶，他的一切义都必不被记念；他必因所行的恶死亡。'),
('CNV', '以西结书', 26, 33, 14, '我虽然对恶人说：‘你必定死亡’，但是他若离开他的罪，行公平和正直的事，'),
('CNV', '以西结书', 26, 33, 15, '把抵押归还，把抢夺人的物件偿还，遵行赐生命的律例，不作恶事，他就必存活，不致死亡；'),
('CNV', '以西结书', 26, 33, 16, '他所犯的一切罪，必不被记念；他行了公平和正直的事，就必存活。'),
('CNV', '以西结书', 26, 33, 17, '“你本国的人还说：‘主所行的不公平。’其实他们所行的才是不公平。'),
('CNV', '以西结书', 26, 33, 18, '义人若离开他的义，去行恶事，他就必因此死亡；'),
('CNV', '以西结书', 26, 33, 19, '恶人若离开他的恶，去行公平和正直的事，他就必因此存活。'),
('CNV', '以西结书', 26, 33, 20, '你们还说：‘主所行的不公平。’以色列家啊！我必照着你们各人所行的审判你们。”'),
('CNV', '以西结书', 26, 33, 21, '在我们被掳以后的第十二年十月初五日，有人从耶路撒冷逃到我这里来，说：“城已经被攻陷了。”'),
('CNV', '以西结书', 26, 33, 22, '那人来到的前一天晚上，主的手按在我身上，开了我的口。到了早晨，那人来到我这里，我的口已经开了，不再作哑巴。'),
('CNV', '以西结书', 26, 33, 23, '主的话临到我说：'),
('CNV', '以西结书', 26, 33, 24, '“人子啊！那些住在以色列地废墟里的人常说：‘亚伯拉罕一个人就得了这地为业；我们人数众多，这地更应该给我们为业。’'),
('CNV', '以西结书', 26, 33, 25, '因此，你要对他们说：‘主神这样说：你们吃带血的祭肉，举目仰望你们的偶像，并且流人的血，你们还可以得这地为业吗？'),
('CNV', '以西结书', 26, 33, 26, '你们倚仗自己的刀剑，行可憎恶的事，人人玷污邻舍的妻子，你们还可以得这地为业吗？’'),
('CNV', '以西结书', 26, 33, 27, '你要对他们这样说：‘主神这样说：我指着我的永生起誓，那些在废墟里的，必倒在刀下；在田间的，我必交给野兽吞吃；在堡垒和山洞里的，必因瘟疫而死。'),
('CNV', '以西结书', 26, 33, 28, '我必使这地非常荒凉，它因势力而有的骄傲必止息；以色列的山都必荒凉，无人经过。'),
('CNV', '以西结书', 26, 33, 29, '我必因他们所行一切可憎恶的事，使这地非常荒凉，那时他们就知道我是主。’'),
('CNV', '以西结书', 26, 33, 30, '“人子啊！你本国的人在城墙旁边和各家的门口正在谈论你；弟兄对弟兄彼此说：‘来吧！听听有什么话从主那里出来。’'),
('CNV', '以西结书', 26, 33, 31, '他们成群来到你那里，坐在你面前，象是我的子民一样。其实他们听了你的话，却不去行；他们只是用口表示爱慕，他们的心却是追随不义之财。'),
('CNV', '以西结书', 26, 33, 32, '在他们眼中，你不过是首情歌，唱得美妙，弹得悦耳，他们听了你的话，却不去行。'),
('CNV', '以西结书', 26, 33, 33, '看哪！这事必定应验，到那时候，他们就知道在他们中间有先知了。”'),
('CNV', '以西结书', 26, 34, 1, '主的话临到我说：'),
('CNV', '以西结书', 26, 34, 2, '“人子啊！你要说预言攻击以色列众牧者；你要对他们说预言：‘主神这样说：以色列众牧者有祸了！他们只顾牧养自己。牧者岂不应当牧养羊群吗？'),
('CNV', '以西结书', 26, 34, 3, '你们吃脂油、穿羊毛，宰肥壮的羊，却不牧养羊群。'),
('CNV', '以西结书', 26, 34, 4, '瘦弱的，你们没有养壮；患病的，你们没有医治；受伤的，你们没有包扎；被赶散的，你们没有领回；迷失的，你们没有寻找；你们反而用强暴严严地管辖它们。'),
('CNV', '以西结书', 26, 34, 5, '它们没有牧人，就分散了，作了田野一切走兽的食物。'),
('CNV', '以西结书', 26, 34, 6, '我的羊在众山和各高冈上流离；它们分散在全地上，没有人去寻，也没有人去找。'),
('CNV', '以西结书', 26, 34, 7, '“‘因此，你们这些作牧者的，要听主的话：'),
('CNV', '以西结书', 26, 34, 8, '我指着我的永生起誓，我的羊因没有牧人，就成了猎物，作了田野一切走兽的食物。我的众牧者不寻找我的羊；他们只顾牧养自己，却不牧养我的羊。这是主神的宣告。'),
('CNV', '以西结书', 26, 34, 9, '因此，你们这些作牧者的，要听主的话。'),
('CNV', '以西结书', 26, 34, 10, '主神这样说：看哪！我要与众牧者为敌；我必向他们追讨我的羊，使他们不再牧养羊群，也不再牧养自己。我必救我的羊脱离他们的口，不再作他们的食物。'),
('CNV', '以西结书', 26, 34, 11, '“‘因为主神这样说：看哪！我必亲自寻觅我的羊，把它们找出来。'),
('CNV', '以西结书', 26, 34, 12, '牧人在他的羊群四散的时候，怎样寻找他的羊，我也必照样寻找我的羊。这些羊在密云幽暗的日子四散到各处，我要把它们从那里救回来。'),
('CNV', '以西结书', 26, 34, 13, '我必把它们从万族中领出来，从列邦中聚集它们，领它们归回故土。我必在以色列的群山上，在众溪水旁，在国内一切居住的地方，牧养它们。'),
('CNV', '以西结书', 26, 34, 14, '我必在美好的草场上牧养它们，以色列的高山必作牧放它们的地方。在那里它们必躺卧在美好的牧场上，它们必在以色列群山肥美的草场上吃草。'),
('CNV', '以西结书', 26, 34, 15, '我必亲自牧养我的羊，亲自使它们躺卧。这是主神的宣告。'),
('CNV', '以西结书', 26, 34, 16, '迷失的，我必寻找；被赶散的，我必领回；受伤的，我必包扎；患病的，我必养壮；肥壮的，我却要除灭。我也必按着公正牧养它们。'),
('CNV', '以西结书', 26, 34, 17, '“‘我的羊啊！论到你们，主神这样说：我要在羊与羊之间，在公绵羊与公山羊之间，施行审判。'),
('CNV', '以西结书', 26, 34, 18, '你们在美好的草场上吃草，还不知足吗？剩下的草，你们竟用脚践踏；你们喝了清水，剩下的你们竟用脚搅浊。'),
('CNV', '以西结书', 26, 34, 19, '我的羊，就只能吃你们用脚践踏过的，喝你们用脚搅浊了的。'),
('CNV', '以西结书', 26, 34, 20, '“‘因此，主神对它们这样说：看哪！我必亲自在肥羊与瘦羊之间施行审判。'),
('CNV', '以西结书', 26, 34, 21, '因为你们用腰用肩拥挤所有瘦弱的，又用角抵触它们，直到把它们驱散到外面，'),
('CNV', '以西结书', 26, 34, 22, '所以我必拯救我的羊，使它们不再作猎物。我要在羊与羊之间施行审判。'),
('CNV', '以西结书', 26, 34, 23, '“‘我必立一个牧人，就是我的仆人大卫，看管它们，牧养它们。他必牧养它们，作它们的牧人。'),
('CNV', '以西结书', 26, 34, 24, '我主必作它们的神，我的仆人大卫要在它们中间作领袖。我主已经说了。'),
('CNV', '以西结书', 26, 34, 25, '“‘我必与它们立平安的约，使恶兽从境内灭绝，它们就可以在旷野安居，在树林中躺卧。'),
('CNV', '以西结书', 26, 34, 26, '我必使他们和我的山四围都蒙福；我必按时降雨，这就是赐福的雨。'),
('CNV', '以西结书', 26, 34, 27, '田野的树木必结果子，地也必有出产；他们必在自己的土地上安居。我打断他们所负的轭，救他们脱离奴役者的手的时候，他们就知道我是主。'),
('CNV', '以西结书', 26, 34, 28, '他们必不再作列国的猎物，地上的野兽也不再吞吃他们；他们必安然居住，没有人惊吓他们。'),
('CNV', '以西结书', 26, 34, 29, '我必给他们兴起一个以种植闻名的地方，使他们在境内不再被饥荒消灭，也不再担当列国的羞辱。'),
('CNV', '以西结书', 26, 34, 30, '那时，他们就知道我主他们的神与他们同在，并且知道他们以色列家是我的子民。这是主神的宣告。'),
('CNV', '以西结书', 26, 34, 31, '你们是我的羊，是我草场上的羊；我是你们的神。这是主的宣告。’”'),
('CNV', '以西结书', 26, 35, 1, '主的话临到我说：'),
('CNV', '以西结书', 26, 35, 2, '“人子啊！你要面向西珥山，说预言攻击它，'),
('CNV', '以西结书', 26, 35, 3, '对它说：‘主神这样说：西珥山啊！我要与你为敌，伸手攻击你，使你非常荒凉。'),
('CNV', '以西结书', 26, 35, 4, '我要使你的城市变为废墟，你必然荒凉，那时，你就知道我是主。'),
('CNV', '以西结书', 26, 35, 5, '因为你永远怀恨，在以色列人遭遇灾难，刑罚到了顶点的时候，你把他们交在刀剑之下，'),
('CNV', '以西结书', 26, 35, 6, '所以我指着我的永生起誓，我必使你遭受流血的报应，这血必追赶你；你既不恨恶流人的血，这血必追赶你。这是主神的宣告。'),
('CNV', '以西结书', 26, 35, 7, '我必使西珥山非常荒凉，我必从那里剪除来往的人。'),
('CNV', '以西结书', 26, 35, 8, '我必使西珥的众山布满了被杀的人；被刀剑所杀的人必倒在你的小山、山谷和所有的溪涧中。'),
('CNV', '以西结书', 26, 35, 9, '我必使你永远荒凉，你的城市必没有人居住；你们就知道我是主。'),
('CNV', '以西结书', 26, 35, 10, '“‘因为你曾说：这两国这两邦都必归我，我必得它们为业，但其实主还是在那里。'),
('CNV', '以西结书', 26, 35, 11, '所以我指着我的永生起誓：我必照着你因仇恨而向他们所发的忿怒和嫉妒对待你。我审判你的时候，必把自己显明在他们中间。这是主神的宣告。'),
('CNV', '以西结书', 26, 35, 12, '这样，你就必知道我主听见了你的一切毁谤，就是你攻击以色列众山的话，说：“这些山都已经荒凉了！已经给我们吞吃了！”'),
('CNV', '以西结书', 26, 35, 13, '你们用口说夸大的话攻击我，说出许多话来与我作对，我都听见了。'),
('CNV', '以西结书', 26, 35, 14, '主神这样说：全地都欢乐的时候，我却要使你荒凉。'),
('CNV', '以西结书', 26, 35, 15, '你怎样因以色列家的产业荒凉而欢乐，我也必照样待你。西珥山啊！你和以东全地都必荒凉。他们就知道我是主。’”'),
('CNV', '以西结书', 26, 36, 1, '“人子啊！你要向以色列的众山说预言：‘以色列的众山啊！你们要听主的话。'),
('CNV', '以西结书', 26, 36, 2, '主神这样说：因为仇敌攻击你们说：哈哈！那悠久的山冈都归给我们为业了。'),
('CNV', '以西结书', 26, 36, 3, '所以你要说预言：主神这样说：因为敌人使你们荒凉，四围践踏你们，好使你们归给列国中余剩的人为业，成为人们提说和嘲笑的对象，'),
('CNV', '以西结书', 26, 36, 4, '因此，以色列的众山啊！你们要听主神的话；主神对大山、小冈、溪涧、山谷、荒凉的废墟，被弃的城，就是曾被四围列国中余剩的人所劫掠、所讥笑的，这样说：'),
('CNV', '以西结书', 26, 36, 5, '主神这样说：我在妒火中说话攻击列国中余剩的人和以东众人，因为他们全心欢喜，满怀恨恶，把我的地归给自己为业，好占有它为掠物。'),
('CNV', '以西结书', 26, 36, 6, '因此，你要向以色列地说预言，对大山、小冈、溪涧和山谷说：主神这样说：看哪！我在嫉妒和烈怒中说话，因为你们担当了列国的羞辱。'),
('CNV', '以西结书', 26, 36, 7, '所以主神这样说：我举手起誓说：你们四围的列国必亲自担当自己的羞辱。'),
('CNV', '以西结书', 26, 36, 8, '“‘以色列的众山啊！你们必长出枝条，为我的子民以色列结出果子，因为他们快要回来了。'),
('CNV', '以西结书', 26, 36, 9, '看哪！我是帮助你们的，我必转向你们，使人可以在你们上面耕种和撒种。'),
('CNV', '以西结书', 26, 36, 10, '我要使以色列全家的人数在你们上面增多；城市有人居住，废墟可以重建。'),
('CNV', '以西结书', 26, 36, 11, '我必使人和牲畜都在你们上面增多；他们必繁衍增多；我必使你们有人居住，像从前一样，并要使你们比先前更蒙福。你们就知道我是主。'),
('CNV', '以西结书', 26, 36, 12, '我必使人，就是我的子民以色列，在你上面行走；他们必得你为业；你必作他们的产业，也不再使他们丧失子女。'),
('CNV', '以西结书', 26, 36, 13, '主神这样说：因为人对你说：你是吞吃人的，又是使你的国民丧失子女的。'),
('CNV', '以西结书', 26, 36, 14, '所以你必不再吞吃人，也必不再使你的国民丧失子女。这是主神的宣告。'),
('CNV', '以西结书', 26, 36, 15, '我必使你不再听见列国的羞辱，你必不再受万族的辱骂，也不再使你的国民跌倒。这是主神的宣告。’”'),
('CNV', '以西结书', 26, 36, 16, '主的话又临到我说：'),
('CNV', '以西结书', 26, 36, 17, '“人子啊！以色列家住在他们本土的时候，他们的所作所为玷污了那地。他们所行的在我面前，就像在经期中的妇人那样污秽。'),
('CNV', '以西结书', 26, 36, 18, '所以我因他们在那地上流人的血，又因他们以自己可憎的像玷污那地，就把我的烈怒倒在他们身上。'),
('CNV', '以西结书', 26, 36, 19, '我使他们分散在列邦，四散在各地；我按着他们的所作所为审判他们。'),
('CNV', '以西结书', 26, 36, 20, '他们到了所去的列邦那里，我的圣名就被亵渎，因为人总是谈论他们说：‘这些是主的子民，他们却要从主的地出来。’'),
('CNV', '以西结书', 26, 36, 21, '我却顾惜我的圣名，就是以色列家在他们所去的列邦那里所亵渎的。'),
('CNV', '以西结书', 26, 36, 22, '“因此，你要对以色列家说：‘主神这样说：以色列家啊！我作这事，不是为了你们，而是为了我自己的圣名，就是在你们所去的列邦那里所亵渎的，'),
('CNV', '以西结书', 26, 36, 23, '我要使我的大名显为圣，这名在列邦中已经被亵渎了，是你们在他们中间所亵渎的。我在你们身上向他们显为圣的时候，他们就知道我是主。这是主神的宣告。'),
('CNV', '以西结书', 26, 36, 24, '我必从列国中领你们出来，从万邦中聚集你们，把你们带回故土。'),
('CNV', '以西结书', 26, 36, 25, '我必用洁净的水洒在你们身上，你们就洁净了；我必洁净你们的一切污秽，使你们远离所有可憎的像。'),
('CNV', '以西结书', 26, 36, 26, '“‘我必把新心赐给你们，把新灵放在你们里面；我必从你们的肉体中除去石心，把肉心赐给你们。'),
('CNV', '以西结书', 26, 36, 27, '我必把我的灵放在你们里面，使你们遵行我的律例，谨守遵行我的典章。'),
('CNV', '以西结书', 26, 36, 28, '你们要住在我赐给你们列祖的地；你们要作我的子民，我要作你们的神。'),
('CNV', '以西结书', 26, 36, 29, '我必拯救你们脱离你们的一切污秽；我必叫五谷丰收，不使你们遇见饥荒。'),
('CNV', '以西结书', 26, 36, 30, '我必使树木的果子和田地的出产增多，好使你们在列国中不再因饥荒而遭受耻辱。'),
('CNV', '以西结书', 26, 36, 31, '那时，你们必想起你们的恶行和不好的作为，就必因你们的罪孽和可憎恶的事厌恶自己。'),
('CNV', '以西结书', 26, 36, 32, '你们要知道我这样行，不是为了你们的缘故；以色列家啊！你们要因自己的行为抱愧蒙羞。这是主神的宣告。'),
('CNV', '以西结书', 26, 36, 33, '“‘主神这样说：我洁净你们，使你们脱离一切罪孽的日子，我必使城市有人居住，废墟可以重建。'),
('CNV', '以西结书', 26, 36, 34, '从前所有路过的人都看为荒凉之地，现在却必再可以耕种。'),
('CNV', '以西结书', 26, 36, 35, '他们必说：“先前这荒凉之地，现在竟像伊甸园一样；这些废弃、荒凉、毁坏了的城市，现在却成了坚固城，有人居住了。”'),
('CNV', '以西结书', 26, 36, 36, '那时，在你们四围所余剩的列国，就必知道我是主，是我重建了那些毁坏的地方，栽植了那些荒凉之地。我主说了，就必实行。'),
('CNV', '以西结书', 26, 36, 37, '“‘主神这样说：我还要让以色列家求我为他们增加人数，多如羊群。'),
('CNV', '以西结书', 26, 36, 38, '守节的时候，在耶路撒冷作祭牲的羊群是怎样多，那些荒废了的城市也必照样满了人群。他们就知道我是主。’”'),
('CNV', '以西结书', 26, 37, 1, '主的手按在我身上；主藉着他的灵领我出去，把我放在平原上，这平原布满了骸骨。'),
('CNV', '以西结书', 26, 37, 2, '他带我在骸骨的四围经过；我看见平原上面有很多骸骨，都非常枯干。'),
('CNV', '以西结书', 26, 37, 3, '他问我：“人子啊！这些骸骨能活过来吗？”我回答：“主神啊！唯有你才知道。”'),
('CNV', '以西结书', 26, 37, 4, '他又对我说：“你要向这些骸骨说预言，对它们说：‘枯干的骸骨啊！你们要听主的话。'),
('CNV', '以西结书', 26, 37, 5, '主神对这些骸骨这样说：看哪！我必使气息进入你们里面，你们就活过来了。'),
('CNV', '以西结书', 26, 37, 6, '我必使你们生筋长肉，给你们包上皮，又把气息放入你们里面，你们必活过来；你们就知道我是主。’”'),
('CNV', '以西结书', 26, 37, 7, '于是我遵命说预言；我正在说预言的时候，就听见有响声，骨头与骨头互相结合起来，格格作响。'),
('CNV', '以西结书', 26, 37, 8, '我观看，见骸骨生了筋，长了肉，又有皮包在上面，只是它们里面还没有气息。'),
('CNV', '以西结书', 26, 37, 9, '他对我说：“你要向气息说预言。人子啊！你要说预言。你要向气息说：‘主神这样说：气息啊！你要从四方（“四方”原文作“四风”）而来，吹在这些被杀的人身上，使它们活过来。’”'),
('CNV', '以西结书', 26, 37, 10, '于是我遵命说预言，气息就进入骸骨里面，骸骨就活过来，并且站起，成了一支极大的军队。'),
('CNV', '以西结书', 26, 37, 11, '他对我说：“人子啊！这些骸骨就是以色列全家；他们常说：‘我们的骸骨枯干了，我们的盼望消失了；我们都灭亡了。’'),
('CNV', '以西结书', 26, 37, 12, '因此，你要说预言，对他们说：‘主神这样说：我的子民哪！我要打开你们的坟墓，把你们从坟墓中领上来，带你们回以色列地去。'),
('CNV', '以西结书', 26, 37, 13, '我的子民哪！我打开你们的坟墓，把你们从坟墓中领上来的时候，你们就知道我是主。'),
('CNV', '以西结书', 26, 37, 14, '我要把我的灵放在你们里面，你们就活过来；我要把你们安顿在你们的土地上，你们就知道我主说了，就必实行。这是主神的宣告。’”'),
('CNV', '以西结书', 26, 37, 15, '主的话又临到我说：'),
('CNV', '以西结书', 26, 37, 16, '“人子啊！你要拿一根木杖，在上面写‘犹大和那些与他一起的以色列人’；又拿另一根木杖，在上面写‘以法莲的木杖，就是约瑟和与他一起的以色列全家’。'),
('CNV', '以西结书', 26, 37, 17, '你要把这两根木杖连接在一起，使它们在你手里成为一根。'),
('CNV', '以西结书', 26, 37, 18, '如果你本国的人民问你：‘你不告诉我们这些木杖是什么意思吗？’'),
('CNV', '以西结书', 26, 37, 19, '你就要回答他们：‘主神这样说：看哪！我要拿约瑟和与他一起的以色列众支派的木杖，就是在以法莲手里的，跟犹大的木杖连接在一起，使它们在我手里成为一根。’'),
('CNV', '以西结书', 26, 37, 20, '你写上了字的那两根木杖，要在他们眼前握在手里；'),
('CNV', '以西结书', 26, 37, 21, '你要对他们说：‘主神这样说：看哪！我要把以色列人从他们所到的列国中领出来，又从四围聚集他们，把他们领回故土。'),
('CNV', '以西结书', 26, 37, 22, '我要使他们在那地上，在以色列的众山上，成为一国；必有一王统治他们众人；他们不再是两个国，不再分为两个邦。'),
('CNV', '以西结书', 26, 37, 23, '他们必不再因自己的偶像和可憎的像，以及一切过犯，而玷污自己；我必拯救他们脱离一切背道的罪（“背道的罪”有古卷作“他们在其中犯罪的住处”）；我必洁净他们，他们就必作我的子民，我必作他们的神。'),
('CNV', '以西结书', 26, 37, 24, '“‘我的仆人大卫必作他们的王；他们众人只有一个牧者。他们必遵行我的典章，谨守实行我的律例。'),
('CNV', '以西结书', 26, 37, 25, '他们必住在我所赐给我仆人雅各的地上，就是你们列祖所住的地。他们和他们的子孙，以及子孙的子孙，都必永远住在那里；我的仆人大卫必永远作他们的领袖。'),
('CNV', '以西结书', 26, 37, 26, '我要与他们立平安的约，是一个永远的约；我必坚立他们，使他们人数增多，又在他们中间设立我的圣所，直到永远。'),
('CNV', '以西结书', 26, 37, 27, '我的居所必在他们当中；我要作他们的神，他们要作我的子民。'),
('CNV', '以西结书', 26, 37, 28, '我的圣所必永远在他们中间，列国就知道我是主，是我使以色列成圣的。’”'),
('CNV', '以西结书', 26, 38, 1, '主的话临到我说：'),
('CNV', '以西结书', 26, 38, 2, '“人子啊！你要面向玛各地的歌革，就是罗施、米设和土巴的首领，说预言攻击他，'),
('CNV', '以西结书', 26, 38, 3, '说：‘主神这样说：罗施、米设和土巴的首领歌革啊，我要与你为敌。'),
('CNV', '以西结书', 26, 38, 4, '我必使你转过来，用钩子钩住你的腮颊，把你和你的全军、马匹和骑兵，都领出来，他们都穿着全副军装，成为大队人马，配备大小盾牌，各人紧握刀剑。'),
('CNV', '以西结书', 26, 38, 5, '还有波斯人、古实人和弗人与他们在一起，各人都配备盾牌和头盔；'),
('CNV', '以西结书', 26, 38, 6, '又有歌篾人和他们的全军，北方极处的陀迦玛族和他们的全军，这许多民族都与你在一起。'),
('CNV', '以西结书', 26, 38, 7, '“‘你要准备好，你和那聚集到你那里的各队都要准备好；你要作他们的大帅。'),
('CNV', '以西结书', 26, 38, 8, '过了许多日子，你必被征点出战；在以后的年间，你必来攻击那脱离刀剑的地，就是那从列邦聚集回来的人所住的地；你必来攻击以色列这些久已荒凉的山；他们是从万族中领出来的，都在那里安然居住。'),
('CNV', '以西结书', 26, 38, 9, '你和你的军队，以及与你在一起的许多民族，都必像暴风上来，像密云遮盖那地。'),
('CNV', '以西结书', 26, 38, 10, '“‘主神这样说：到那日你心中必起意念，图谋恶计，'),
('CNV', '以西结书', 26, 38, 11, '说：我要上去攻击那些没有城墙的乡村；我要来攻击那些生活平静的人，他们都安然居住，没有城墙，没有门闩。'),
('CNV', '以西结书', 26, 38, 12, '你要抢夺财物，掳掠货物，伸手攻击那些从前荒废、现在有人居住的地方，攻击那些从列邦招聚出来，得了牲畜财物，又住在世界中心的人民。'),
('CNV', '以西结书', 26, 38, 13, '示巴人、底但人和他施各城镇的商人（按照《马索拉文本》，“他施各城镇的商人”作“他施的商人并她的少壮狮子”；现参照《七十士译本》和其他古译本翻译）都必问你：你来是要抢夺财物吗？你聚集军队是要掳掠货物吗？是要搬走金银、掳去牲畜财物吗？是要大肆抢掠吗？’'),
('CNV', '以西结书', 26, 38, 14, '“因此，人子啊！你要对歌革说预言：‘主神这样说：到那日，我的子民以色列安然居住的时候，你岂不会留意吗？'),
('CNV', '以西结书', 26, 38, 15, '你必从你的地方，从北方的极处，与许多民族一起而来，都骑着马，成为一大队强盛的军兵。'),
('CNV', '以西结书', 26, 38, 16, '你必上来攻击我的子民以色列，像密云遮盖那地一样。歌革啊！在以后的日子，我必领你来攻击我的地，好叫列国在我藉着你向他们显为圣的时候，能认识我。'),
('CNV', '以西结书', 26, 38, 17, '“‘主神这样说：我从前藉着我的众仆人以色列的先知所说的，岂不是你吗？在那些年间，他们曾预言我必领你来攻击以色列人。'),
('CNV', '以西结书', 26, 38, 18, '歌革来攻击以色列地的日子，我的怒气必从我的鼻孔中发出来。这是主神的宣告。'),
('CNV', '以西结书', 26, 38, 19, '我在妒恨和怒火之中说：到那日，以色列地必有大地震。'),
('CNV', '以西结书', 26, 38, 20, '海里的鱼、空中的飞鸟、田野的走兽、在地上爬行的各种动物，以及地上的众人，都要在我面前震动。众山必崩裂，悬崖必塌陷，所有的墙垣都必倒在地上。'),
('CNV', '以西结书', 26, 38, 21, '我必呼唤刀剑在我的众山上攻击歌革，各人的刀剑必攻击自己的兄弟。这是主神的宣告。'),
('CNV', '以西结书', 26, 38, 22, '我必用瘟疫和血腥惩罚他；我必把暴雨、大冰雹、火和硫磺降在他和他的军队，以及与他在一起的许多民族身上。'),
('CNV', '以西结书', 26, 38, 23, '我必显为大、显为圣，在列国的人眼前显现自己。这样，他们就知道我是主。’”'),
('CNV', '以西结书', 26, 39, 1, '“人子啊！你要向歌革说预言：‘主神这样说：罗施、米设和土巴的首领歌革啊！我要与你为敌。'),
('CNV', '以西结书', 26, 39, 2, '我要使你转过来，带你从北方的极处上来，领你去攻击以色列的众山。'),
('CNV', '以西结书', 26, 39, 3, '然后，我要击落你左手的弓，打落你右手的箭。'),
('CNV', '以西结书', 26, 39, 4, '你必倒在以色列的众山之上，你所有的军队和跟你在一起的万族，都必这样；我要把你给各种食肉的飞鸟和田野的走兽作食物。'),
('CNV', '以西结书', 26, 39, 5, '你必倒在田野，因为我已经说过了。这是主神的宣告。'),
('CNV', '以西结书', 26, 39, 6, '我必降火在玛各和安居在沿海地带的人身上，他们就知道我是主。'),
('CNV', '以西结书', 26, 39, 7, '“‘我要在我子民以色列中彰显我的圣名，我必不再让我的圣名被亵渎；这样，列国就知道我是主，是以色列中的圣者。'),
('CNV', '以西结书', 26, 39, 8, '看哪！那日子临近了，事情必定应验，这就是我所说过的那一天。这是主神的宣告。'),
('CNV', '以西结书', 26, 39, 9, '“‘那时，以色列各城的居民必出来，把武器当柴焚烧，就是大小的盾牌、弓、箭、枪和矛，都当柴焚烧，足有七年的时间。'),
('CNV', '以西结书', 26, 39, 10, '他们不必从田野捡柴，也不必从树林里伐木，因为他们必把武器当柴烧；他们必抢劫那些曾抢劫他们的人，掠夺那些掠夺他们的人。这是主神的宣告。'),
('CNV', '以西结书', 26, 39, 11, '“‘到那日，我必在以色列给歌革一块坟地，就是那些朝东往死海去的人所经过的谷。这坟地使过路之人无法通过，因为那里埋葬了歌革和他的众军。因此，那地必称为哈们．歌革谷。'),
('CNV', '以西结书', 26, 39, 12, '以色列家要用七个月的时间去埋葬他们，为要洁净那地。'),
('CNV', '以西结书', 26, 39, 13, '那地所有的人民都必埋葬他们。这是我得荣耀的日子，以色列人也必因此得享美名。这是主神的宣告。'),
('CNV', '以西结书', 26, 39, 14, '他们必分派人经常遍行那地，与过路的人一起埋葬那些还留在地面上的尸体，为要洁净那地；过了七个月，他们还要继续搜索。'),
('CNV', '以西结书', 26, 39, 15, '他们遍行那地，见有人的骸骨，就在旁边立个标记，等埋葬的人来把骸骨葬在哈们．歌革谷。'),
('CNV', '以西结书', 26, 39, 16, '那里也有一座城名叫哈摩那。他们必这样洁净那地。’'),
('CNV', '以西结书', 26, 39, 17, '“人子啊！主神这样说：你要对各类的飞鸟和田野的走兽说：‘你们集合起来，从四围聚集来吃我为你们所预备的祭肉。以色列众山上要献大祭，好叫你们吃肉喝血。'),
('CNV', '以西结书', 26, 39, 18, '你们要吃勇士的肉，喝那地众领袖的血，就如吃公绵羊、羊羔、公山羊和公牛，全部都是巴珊的肥畜。'),
('CNV', '以西结书', 26, 39, 19, '你们吃我为你们所预备的祭，必吃饱脂油，喝醉了血。'),
('CNV', '以西结书', 26, 39, 20, '你们必在我的筵席上吃饱马匹、骑兵、勇士和所有的战士。这是主神的宣告。’'),
('CNV', '以西结书', 26, 39, 21, '“我必在列国中彰显我的荣耀，万邦必看见我施行的审判，和我加在他们身上的手。'),
('CNV', '以西结书', 26, 39, 22, '这样，从那日起，以色列家就必知道我是主他们的神。'),
('CNV', '以西结书', 26, 39, 23, '列国也必知道以色列家是因自己的罪孽被掳去。他们对我不忠，所以我掩面不顾他们，把他们交在敌人手中，他们就都倒在刀下。'),
('CNV', '以西结书', 26, 39, 24, '我是照着他们的污秽和过犯对待他们，并且掩面不顾他们。'),
('CNV', '以西结书', 26, 39, 25, '“因此，主神这样说：现在我要使雅各被掳的归回；我要怜悯以色列全家，又为我的圣名大发热心。'),
('CNV', '以西结书', 26, 39, 26, '他们在自己的土地上安然居住、无人惊吓的时候，就要担当自己的羞辱和向我所犯一切不忠的罪；'),
('CNV', '以西结书', 26, 39, 27, '我把他们从万族中领回来，从仇敌之地召回来的时候，我必在他们身上向列国显为圣。'),
('CNV', '以西结书', 26, 39, 28, '我使他们被掳到列国去，后来又聚集他们到自己的土地，连一个也不再留在列国那里。这样，他们就知道我是主他们的神。'),
('CNV', '以西结书', 26, 39, 29, '我也不再掩面不顾他们，因为我已经把我的灵浇灌在以色列家。这是主神的宣告。”'),
('CNV', '以西结书', 26, 40, 1, '我们被掳后第二十五年，耶路撒冷城被攻陷后第十四年的年初；那月的初十日，正当那日，主的手按在我身上；他把我带到那里去。'),
('CNV', '以西结书', 26, 40, 2, '在神的异象中，他带我到以色列地，把我安置在一座很高的山上；在山上的南面，有好像是一座城的建筑物。'),
('CNV', '以西结书', 26, 40, 3, '他把我带到那里，我见有一个人，他看来像铜，手里拿着麻绳和测量竿，站在门口。'),
('CNV', '以西结书', 26, 40, 4, '那人对我说：“人子啊！我所要指示你的，你都要用眼看，用耳听，并要放在心上，因为我带你到这里来，为的是要指示你；你所看见的，你都要告诉以色列家。”'),
('CNV', '以西结书', 26, 40, 5, '我见殿四围有墙，那人手里的测量竿长三公尺。他量了那建筑物，墙厚三公尺、高三公尺。'),
('CNV', '以西结书', 26, 40, 6, '他到了朝东的门，上了门的台阶，量度门槛，厚三公尺；又量另一个门槛，厚三公尺。'),
('CNV', '以西结书', 26, 40, 7, '又有守卫室，长三公尺、宽三公尺；守卫室与守卫室之间，相隔两公尺半；朝向殿内，在门廊旁边的门槛，厚三公尺。'),
('CNV', '以西结书', 26, 40, 8, '他又量朝向殿内的门廊（有古卷加“厚三公尺”）。'),
('CNV', '以西结书', 26, 40, 9, '门廊深四公尺；墙柱厚一公尺；门廊是朝向殿内的。'),
('CNV', '以西结书', 26, 40, 10, '东门的守卫室，这边有三间，那边有三间；三间都是一样的长宽；两边的墙柱都是一样的厚。'),
('CNV', '以西结书', 26, 40, 11, '他量了东门，入口宽五公尺，通道宽六公尺半。'),
('CNV', '以西结书', 26, 40, 12, '每个守卫室前面都有矮墙，高五十公分，两边守卫室都是一样。守卫室长三公尺，两边都是一样。'),
('CNV', '以西结书', 26, 40, 13, '他量了东门，从这边房顶到那边房顶，就是从这边守卫室后面的门到那边守卫室后面的门，宽十二公尺半。'),
('CNV', '以西结书', 26, 40, 14, '又沿着里面各墙柱量度，直到朝向院子的墙柱，共长三十公尺（原文意思不详，有古译本作“又量了门廊，宽十公尺，墙柱外面周围是院子”）。'),
('CNV', '以西结书', 26, 40, 15, '从东门前面的入口到后面的门廊，共二十五公尺。'),
('CNV', '以西结书', 26, 40, 16, '守卫室和东门里面周围的墙柱，以及门廊，都有小窗；里面周围都有小窗；墙柱上还刻有棕树。'),
('CNV', '以西结书', 26, 40, 17, '他带我到了外院，我见有些房子，院子周围有铺石地，铺石地上有三十间房子。'),
('CNV', '以西结书', 26, 40, 18, '铺石地在各大门的旁边，比门矮一点，宽度与门的长度相同。'),
('CNV', '以西结书', 26, 40, 19, '他从下面的大门量到内院的外墙，共宽五十公尺；东面、北面，都是一样。'),
('CNV', '以西结书', 26, 40, 20, '他又量了外院朝北大门的长度和宽度。'),
('CNV', '以西结书', 26, 40, 21, '里面的守卫室，这边有三间，那边有三间；墙柱和门廊的尺寸都与东门的一样；北门全长二十五公尺，宽十二公尺半。'),
('CNV', '以西结书', 26, 40, 22, '它的窗子、门廊和雕刻的棕树，都与东门的一样；人要登七级台阶才到这门，前面尽头是门廊。'),
('CNV', '以西结书', 26, 40, 23, '内院有门与这门相对；北面、东面，都是一样；他从这门量到那门，共有五十公尺。'),
('CNV', '以西结书', 26, 40, 24, '他领我向南走，我就看见朝南的门。他量了墙柱和门廊，大小与先前的一样。'),
('CNV', '以西结书', 26, 40, 25, '门的里面和门廊周围都有窗子，与先前的窗子一样。南门全长二十五公尺，宽十二公尺半。'),
('CNV', '以西结书', 26, 40, 26, '人要登七级台阶才到这门，前面尽头是门廊，墙柱上两边都刻有棕树。'),
('CNV', '以西结书', 26, 40, 27, '内院南面也有门；他从这门量到南门，共有五十公尺。'),
('CNV', '以西结书', 26, 40, 28, '他领我从内院的南门进到内院，量了这门，大小与先前的一样。'),
('CNV', '以西结书', 26, 40, 29, '守卫室、墙柱和门廊的尺寸都与先前的一样；门的里面和门廊周围都有窗子。这门全长二十五公尺，宽十二公尺半（有古卷加“周围有门廊，长十二公尺半，宽两公尺半”之句）。'),
('CNV', '以西结书', 26, 40, 31, '门廊朝向外院；墙柱刻有棕树；台阶共有八级。'),
('CNV', '以西结书', 26, 40, 32, '他领我到内院的东门，他量了那门，大小与先前的一样。'),
('CNV', '以西结书', 26, 40, 33, '守卫室、墙柱和门廊的尺寸都与先前的一样；门的里面和门廊的周围都有窗子。这门全长二十五公尺，宽十二公尺半。'),
('CNV', '以西结书', 26, 40, 34, '门廊朝着外院；墙柱上两边都刻有棕树；台阶共有八级。'),
('CNV', '以西结书', 26, 40, 35, '他领我到内院的北门，量了那门，大小与先前的一样；'),
('CNV', '以西结书', 26, 40, 36, '守卫室、墙柱和门廊，都是一样。门的里面周围都有窗户；这门全长二十五公尺，宽十二公尺半。'),
('CNV', '以西结书', 26, 40, 37, '门廊（“门廊”这译法是参考古译本，原文作“墙柱”）朝向外院；墙柱上两边都刻有棕树，台阶共有八级。'),
('CNV', '以西结书', 26, 40, 38, '在各门的墙柱旁边都有一间有门的房子；那里是洗燔祭牲的地方。'),
('CNV', '以西结书', 26, 40, 39, '在门廊里，这边有两张桌子，那边也有两张桌子，在上面可以宰杀燔祭牲、赎罪祭牲和赎愆祭牲。'),
('CNV', '以西结书', 26, 40, 40, '在北门入口的台阶那里，朝向外面的一边有两张桌子，朝向门廊的另一边也有两张桌子。'),
('CNV', '以西结书', 26, 40, 41, '在大门两边，这边有四张桌子，那边也有四张桌子，共有八张，供宰杀祭牲之用。'),
('CNV', '以西结书', 26, 40, 42, '另有四张桌子供燔祭使用，是用凿好的石头做的，长七十五公分，宽七十五公分，高五十公分，宰杀燔祭牲和其他祭牲所用的器皿是放在那里的。'),
('CNV', '以西结书', 26, 40, 43, '周围的墙上钉有钩子，各长七公分半。桌子上放有献祭的肉。'),
('CNV', '以西结书', 26, 40, 44, '内院的门外有两间（按照《马索拉文本》，“两间”作“供歌唱的人使用的”；现参照《七十士译本》翻译）房子：一间在北门旁边，朝向南面；一间在南门（按照《马索拉文本》，“南门”作“东门”；现参照《七十士译本》翻译）旁边，朝向北面。'),
('CNV', '以西结书', 26, 40, 45, '他对我说：“这间朝向南面的房子是给那些负责圣殿职事的祭司使用的。'),
('CNV', '以西结书', 26, 40, 46, '那间朝向北面的房子是给那些负责祭坛职事的祭司使用的。这些祭司都是撒督的子孙，在利未人中只有他们可以近前来事奉主。”'),
('CNV', '以西结书', 26, 40, 47, '他又量了内院，长五十公尺，宽五十公尺，是正方形的；祭坛就在殿的前面。'),
('CNV', '以西结书', 26, 40, 48, '他领我到圣殿的门廊，量了门廊的墙柱，这边厚两公尺半，那边厚两公尺半。门口宽七公尺（原文没有“七公尺”，这译法是参考古译本），门的内墙，这边一公尺半，那边一公尺半。'),
('CNV', '以西结书', 26, 40, 49, '门廊宽十公尺，深六公尺（“六公尺”这译法是参考古译本，原文作“七公尺”）；人要登台阶才上到门廊；墙柱旁边有柱子，这边一根，那边一根。'),
('CNV', '以西结书', 26, 41, 1, '他领我到外殿，量了墙柱，这边厚三公尺，那边厚三公尺，宽窄与会幕相同。'),
('CNV', '以西结书', 26, 41, 2, '外殿的入口宽五公尺，门的两边内墙，这边两公尺半，那边两公尺半；他量了外殿，长二十公尺，宽十公尺。'),
('CNV', '以西结书', 26, 41, 3, '他进了内殿，量了门口的墙柱，各厚一公尺；入口宽三公尺，门的内墙各宽三公尺半。'),
('CNV', '以西结书', 26, 41, 4, '他量了内殿，长十公尺，宽十公尺，贴着外殿。他对我说：“这是至圣所。”'),
('CNV', '以西结书', 26, 41, 5, '他又量了圣殿的墙，厚三公尺；殿的周围有多间厢房，各宽二公尺。'),
('CNV', '以西结书', 26, 41, 6, '厢房共有三层，一层叠在一层之上，每层有三十间。殿墙的周围有墙坎子，支撑着厢房，免得厢房的梁木嵌入殿墙。'),
('CNV', '以西结书', 26, 41, 7, '这些围绕着殿的厢房越高越宽。殿四围的内墙一级比一级薄，所以厢房越上越宽；有楼梯从下层经过中层上到上层。'),
('CNV', '以西结书', 26, 41, 8, '我又看见一个高台围绕着殿，作为厢房的根基，台高三公尺。'),
('CNV', '以西结书', 26, 41, 9, '厢房的外墙厚两公尺半；圣殿的厢房与祭司的房子之间有空地，绕着殿的四周，宽十公尺。'),
('CNV', '以西结书', 26, 41, 11, '厢房有门通向空地，一门向北，一门向南。厢房与空地之间相隔两公尺半，周围都是一样。'),
('CNV', '以西结书', 26, 41, 12, '在西边有一座朝向殿院空地的房子，深三十五公尺，长四十五公尺；屋子四周的墙厚两公尺半。'),
('CNV', '以西结书', 26, 41, 13, '他量了圣殿，长五十公尺；又量了殿院的空地，那屋子和它的墙，共长五十公尺。'),
('CNV', '以西结书', 26, 41, 14, '在东面，圣殿前面的空地，宽五十公尺。'),
('CNV', '以西结书', 26, 41, 15, '他量了殿院空地后面的屋子，连同屋子两边的走廊，共长五十公尺。外殿、内殿、朝向内院的门廊、'),
('CNV', '以西结书', 26, 41, 16, '门槛、小窗和对着门槛的三层走廊，周围都镶上木板，从地面直到窗口。窗户都是遮蔽的；'),
('CNV', '以西结书', 26, 41, 17, '在内殿门口上面的外墙，以及内殿和外殿周围的墙上，按着尺寸，'),
('CNV', '以西结书', 26, 41, 18, '都刻上基路伯和棕树。基路伯和棕树相间并排，每个基路伯都有两个脸孔。'),
('CNV', '以西结书', 26, 41, 19, '这边有人的脸向着棕树，那边有狮子的脸向着棕树。全殿周围的雕刻都是这样。'),
('CNV', '以西结书', 26, 41, 20, '外殿的墙，从地面直到门口上面，都刻有基路伯和棕树。'),
('CNV', '以西结书', 26, 41, 21, '外殿的门框是正方形的；在至圣所前面的门框，也是一样。'),
('CNV', '以西结书', 26, 41, 22, '祭坛是木做的，高一公尺半，长一公尺；坛角（有古译本加“坛的座”）和坛的四边，全都是木做的。他对我说：“这是摆在主面前的桌子。”'),
('CNV', '以西结书', 26, 41, 23, '外殿和至圣所各有一个门。'),
('CNV', '以西结书', 26, 41, 24, '每个门分两扇，每扇门分为两页，可以折叠。'),
('CNV', '以西结书', 26, 41, 25, '在外殿的门扇上，刻有基路伯和棕树，像那些刻在墙上的一样；在外边门廊前面，有木做的飞檐。'),
('CNV', '以西结书', 26, 41, 26, '门廊两边都有小窗和棕树。殿的厢房也有飞檐。'),
('CNV', '以西结书', 26, 42, 1, '他领我出来，向着北面的外院去；带我到了祭司的房子。这些房子一排对着殿院的空地，一排对着北面的建筑物。'),
('CNV', '以西结书', 26, 42, 2, '房子共长五十公尺，宽二十五公尺，有朝北的门。'),
('CNV', '以西结书', 26, 42, 3, '这些房子一排对着内院十公尺宽的空地，一排对着外院的铺石地，在三层楼上，都有走廊对着走廊。'),
('CNV', '以西结书', 26, 42, 4, '房子前面有一条夹道，宽五公尺，长五十公尺。房子的门都朝向北面。'),
('CNV', '以西结书', 26, 42, 5, '上层的房子最窄，因为上层的走廊所占的地方，比下层和中层的为多。'),
('CNV', '以西结书', 26, 42, 6, '第三层房子没有柱子，不像外院的房子有柱子。因此，上层比下层和中层较窄。'),
('CNV', '以西结书', 26, 42, 7, '在外面有一道墙，在房子的前面，与房子和外院平行，长二十五公尺。'),
('CNV', '以西结书', 26, 42, 8, '朝着外院的房子，长二十五公尺；朝着圣殿的房子，长五十公尺。'),
('CNV', '以西结书', 26, 42, 9, '下层的房子在东面有一个入口，人从外院进入房子里。'),
('CNV', '以西结书', 26, 42, 10, '在南面（“在南面”这译法是参考古译本，原文作“在东面”），沿着内院的墙也有房子，一排对着殿院的空地，一排对着南面的建筑物。'),
('CNV', '以西结书', 26, 42, 11, '这些房子前面有一条夹道，跟北面的一样，长宽相同。出口之处，也与北面的一样。'),
('CNV', '以西结书', 26, 42, 12, '南边的房子的门，也与北面的一样。在东面夹道的开端，与墙相对的地方，有门可以进入。'),
('CNV', '以西结书', 26, 42, 13, '他对我说：“在南北两面，朝着殿院空地的房子，都是圣洁的房子；亲近主的祭司们要在那里吃至圣之物，也要在那里存放至圣之物，就是素祭、赎罪祭和赎愆祭的祭物，因为那地方是圣的。'),
('CNV', '以西结书', 26, 42, 14, '祭司进了去，不可从圣所出来到外院去；他们要在房子里放下供职时所穿的衣服，因为那些衣服是圣的；他们要穿上别的衣服，才可以到民众的地方。”'),
('CNV', '以西结书', 26, 42, 15, '他量了内院，就领我出朝东的门，又量了整个殿的周围。'),
('CNV', '以西结书', 26, 42, 16, '他用测量竿量了东面，按着测量竿计算，共长二百五十公尺。'),
('CNV', '以西结书', 26, 42, 17, '他又量了北面，按着测量竿计算，共长二百五十公尺。'),
('CNV', '以西结书', 26, 42, 18, '他又量了南面，按着测量竿计算，共长二百五十公尺。'),
('CNV', '以西结书', 26, 42, 19, '他又转去量了西面，按着测量竿计算，共长二百五十公尺。'),
('CNV', '以西结书', 26, 42, 20, '这样，他量了四面。圣殿长二百五十公尺，宽二百五十公尺，四围都有墙，为要分开圣地和俗地。'),
('CNV', '以西结书', 26, 43, 1, '以后，他领我到朝东的门去。'),
('CNV', '以西结书', 26, 43, 2, '看哪！以色列神的荣耀从东面而来；他的声音好像洪水的声音，大地因他的荣耀而发光。'),
('CNV', '以西结书', 26, 43, 3, '我所见的异象，好像我在他来毁灭那城的时候所见的异象一样，又像我在迦巴鲁河边所见的异象一般，我就俯伏在地上。'),
('CNV', '以西结书', 26, 43, 4, '主的荣耀，从朝东的门进入殿中。'),
('CNV', '以西结书', 26, 43, 5, '灵把我提起来，领我进了内院。我看见主的荣耀充满了殿。'),
('CNV', '以西结书', 26, 43, 6, '那人站在我旁边的时候，我听见主从殿中对我说话。'),
('CNV', '以西结书', 26, 43, 7, '他对我说：“人子啊！这是我宝座之地，是我脚掌所踏之地；我要住在那里，在以色列人中间，直到永远。以色列家和他们的诸王，都必不再以他们的淫乱和诸王在邱坛上的石碑玷污我的圣名。'),
('CNV', '以西结书', 26, 43, 8, '他们的门槛靠近我的门槛，他们的门框靠近我的门框，我与他们只有一墙之隔的时候；他们以自己所行的可憎之事玷污了我的圣名，所以我在怒气中灭绝他们。'),
('CNV', '以西结书', 26, 43, 9, '现在他们要从我面前除去淫乱和他们诸王的石碑，我就住在他们中间，直到永远。'),
('CNV', '以西结书', 26, 43, 10, '“人子啊！你要把这殿指示以色列家，使他们因自己的罪孽而羞愧，又要他们量度殿的尺寸。'),
('CNV', '以西结书', 26, 43, 11, '他们若因自己所行的羞愧，你就要把殿的设计、结构、出入之处，以及一切设计、规条、礼仪、法则，都指示他们，在他们眼前写下来，使他们遵着殿的一切设计和规条去作。'),
('CNV', '以西结书', 26, 43, 12, '殿的法则是这样：殿在山顶上周围的界限都是至圣的。这就是殿的法则。'),
('CNV', '以西结书', 26, 43, 13, '“祭坛的尺寸是：底座高五十公分，边缘宽五十公分，四围另有边高二十五公分。这是祭坛的座。'),
('CNV', '以西结书', 26, 43, 14, '从底座到下层的台座，高一公尺，边缘宽五十公分；从小台座到大台座，高二公尺，边缘宽五十公分。'),
('CNV', '以西结书', 26, 43, 15, '祭坛的供台高二公尺，从供台向上突出四个角，'),
('CNV', '以西结书', 26, 43, 16, '供台长六公尺，宽六公尺，四面见方。'),
('CNV', '以西结书', 26, 43, 17, '大台座长七公尺，宽七公尺，四面见方；四围有边高二十五公分；底座四围的边缘宽五十公分。另有台阶朝向东面。”'),
('CNV', '以西结书', 26, 43, 18, '他对我说：“人子啊！主神这样说：祭坛的规条是这样：做成了祭坛，在上面献燔祭、洒上血的时候，'),
('CNV', '以西结书', 26, 43, 19, '你要把一头公牛犊给那些亲近我、事奉我的祭司利未人作赎罪祭，他们是撒督的后裔。这是主神的宣告。'),
('CNV', '以西结书', 26, 43, 20, '你要取些公牛犊的血，抹在祭坛的四角和台座的四角，以及四围那些突起的边上。你这样洁净祭坛，祭坛就洁净了。'),
('CNV', '以西结书', 26, 43, 21, '你又要把那作赎罪祭的公牛犊，烧在圣所外面，在圣殿指定的地方。'),
('CNV', '以西结书', 26, 43, 22, '第二天，你要献一只没有残疾的公山羊作赎罪祭，为要洁净祭坛，像用公牛犊洁净祭坛一样。'),
('CNV', '以西结书', 26, 43, 23, '你洁净了祭坛之后，就要献一头没有残疾的公牛犊和羊群中一只没有残疾的公绵羊。'),
('CNV', '以西结书', 26, 43, 24, '你要在主面前把它们献上，祭司们要把盐撒在它们身上，作燔祭献给主。'),
('CNV', '以西结书', 26, 43, 25, '一连七天，每天你都要预备一头公山羊为赎罪祭，也要预备一头公牛犊和羊群中的一只公绵羊，都要没有残疾的。'),
('CNV', '以西结书', 26, 43, 26, '一连七天，祭司们都要洁净祭坛，祭坛就洁净了。这样，他们就把祭坛分别为圣了。'),
('CNV', '以西结书', 26, 43, 27, '满了七天，从第八天起，祭司们要在祭坛上献你们的燔祭和平安祭。我那时必悦纳你们；这是主神的宣告。”'),
('CNV', '以西结书', 26, 44, 1, '他又领我回到圣所朝东的外门，这门关闭着。'),
('CNV', '以西结书', 26, 44, 2, '主对我说：“这门必须关闭，不可打开；任何人也不得从那里进入；因为主以色列的神已经从那里进入，所以这门必须关闭。'),
('CNV', '以西结书', 26, 44, 3, '只有君王可以坐在里面，在主面前吃饼；他必须从门廊进入，也必须从原路出来。”'),
('CNV', '以西结书', 26, 44, 4, '他又领我经过北门来到殿前；我观看，见主的荣耀充满主的殿，我就脸伏在地。'),
('CNV', '以西结书', 26, 44, 5, '主对我说：“人子啊！我所告诉你主殿的一切规条和法则，你都要留心，用眼看，用耳听，并要留心圣殿的入口和圣所的所有出口。'),
('CNV', '以西结书', 26, 44, 6, '你要对悖逆的以色列家说：‘主神这样说：以色列家啊！你们所行一切可憎的事，该够了吧！'),
('CNV', '以西结书', 26, 44, 7, '你们除了行这一切可憎的事之外，还在你们把脂肪和血献给我作食物的时候，把身心都未受割礼的外族人带进我的圣所，玷污了我的殿，违背了我的约。'),
('CNV', '以西结书', 26, 44, 8, '你们自己没有看守我的圣物，却委派别人在我的圣所里代你们看守。’”'),
('CNV', '以西结书', 26, 44, 9, '主神这样说：“以色列人中一切身心都未受割礼的外族人，都不可进入我的圣所。'),
('CNV', '以西结书', 26, 44, 10, '以色列人走迷了路的时候，有利未人远离我，走迷了路。他们离开我去随从他们的偶像，他们必担当自己的罪孽。'),
('CNV', '以西结书', 26, 44, 11, '他们要在我的圣所作仆役，看管殿门，在圣殿中供职；他们要为人民宰杀燔祭牲和其他祭牲，又要站在人民面前侍候他们。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '以西结书', 26, 44, 12, '因为这些利未人曾在他们的偶像前侍候这人民，成了陷以色列家在罪孽中的绊脚石。因此，我向他们举手起誓，他们必要担当自己的罪孽。这是主神的宣告。'),
('CNV', '以西结书', 26, 44, 13, '他们不可亲近我，作我的祭司，也不可亲近我的一切圣物，或至圣之物。他们必要担当自己的羞辱和他们所行可憎之事的报应。'),
('CNV', '以西结书', 26, 44, 14, '然而我要委派他们看守圣殿，办理圣殿的一切事务，作一切当作的工。'),
('CNV', '以西结书', 26, 44, 15, '“以色列人走迷了路，离开我的时候，有祭司利未人，就是撒督的子孙，仍然看守我的圣所；只有他们可以亲近我，事奉我，侍立在我面前，把脂肪和血献给我。这是主神的宣告。'),
('CNV', '以西结书', 26, 44, 16, '他们可以进入我的圣所，可以走近我的桌前来事奉我，守我所吩咐的职责。'),
('CNV', '以西结书', 26, 44, 17, '每逢他们进入内院的门，必须穿上细麻衣；每逢他们在内院的门和圣殿里供职，他们不可穿上羊毛的衣服。'),
('CNV', '以西结书', 26, 44, 18, '他们头上要戴细麻布的头巾，腰间要穿细麻布的裤子；不可穿上使身体容易出汗的衣服。'),
('CNV', '以西结书', 26, 44, 19, '每逢他们出到外院民众那里，就要把供职的衣服脱下，存放在圣殿的房子里，然后穿上别的衣服，免得因自己的圣衣使人民成圣。'),
('CNV', '以西结书', 26, 44, 20, '他们不可剃头，也不可留长头发，只可剪短头发。'),
('CNV', '以西结书', 26, 44, 21, '所有祭司进入内院的时候，都不可喝酒。'),
('CNV', '以西结书', 26, 44, 22, '他们不可娶寡妇或被休的妇人；只可娶以色列后裔中的处女，或是祭司留下的寡妇。'),
('CNV', '以西结书', 26, 44, 23, '他们要教导我的子民分别圣俗，使他们分辨洁净的和不洁净的。'),
('CNV', '以西结书', 26, 44, 24, '他们要在争讼的事上作判断，要按着我的典章判断。他们要在我所有的节期里谨守我的律法和条例，守我的安息日为圣日。'),
('CNV', '以西结书', 26, 44, 25, '他们不可接近死人，玷污自己，但如果死人是他们的父亲、母亲、儿子、女儿、兄弟或是未嫁的姊妹，他们就可以玷污自己。'),
('CNV', '以西结书', 26, 44, 26, '祭司洁净以后，还要再等七天。'),
('CNV', '以西结书', 26, 44, 27, '他进入内院，到圣所去，在圣所供职的时候，他要献上赎罪祭。这是主神的宣告。'),
('CNV', '以西结书', 26, 44, 28, '“祭司必有产业；我就是他们的产业。你们不可在以色列中给他们基业；我就是他们的基业。'),
('CNV', '以西结书', 26, 44, 29, '素祭、赎罪祭和赎愆祭，他们都可以吃。以色列中所有献给主之物，都要归给他们。'),
('CNV', '以西结书', 26, 44, 30, '所有初熟之物中最好的和你们献上的一切供物，都要归给祭司；你们也要把最先磨好的面给祭司，好让福气临到你的家。'),
('CNV', '以西结书', 26, 44, 31, '无论是飞鸟或是走兽，凡是自然死的，或是被撕裂的，祭司都不可吃。”'),
('CNV', '以西结书', 26, 45, 1, '“你们抽签分地为业的时候，要献上一份给主作圣区，长十二公里半，宽十公里（此译法参古译本，“十公里”原文作“五公里”）；整个地区都是圣的。'),
('CNV', '以西结书', 26, 45, 2, '其中要有一块作为圣所之地，长二百五十公尺，宽二百五十公尺，四面见方；周围再有二十五公尺作空地。'),
('CNV', '以西结书', 26, 45, 3, '你们要从所量的圣区量出一块地来，长十二公里半，宽五公里，其中要有圣所，是至圣的地方。'),
('CNV', '以西结书', 26, 45, 4, '这是整个地区中的一块圣地，要归给那些在圣所里供职，亲近事奉主的祭司，作他们房屋之地和圣所之圣地。'),
('CNV', '以西结书', 26, 45, 5, '其余的一块地，长十二公里半，宽五公里，要归给在圣殿里供职的利未人，作为他们的基业，作居住的城市（按照《马索拉文本》，“作居住的城市”作“二十间房屋”；现参照《七十士译本》翻译）。'),
('CNV', '以西结书', 26, 45, 6, '“你们要划分一块地作城的基业，宽两公里半，长十二公里半，在所献的圣区旁边，归给以色列全家。'),
('CNV', '以西结书', 26, 45, 7, '“归给君王之地要在所献的圣区和城的基业两旁，一块对着所献的圣区，一块对着城的基业，从西边那块地的西面边界，到东边那块地的东面边界，长度与每支派所分得的地一样长。'),
('CNV', '以西结书', 26, 45, 8, '这地在以色列中要归给君王作基业。我所立的君王都不可再欺压我的子民，却要按支派把地分给以色列家。”'),
('CNV', '以西结书', 26, 45, 9, '主神这样说：“以色列的君王啊！你们所作的该够了吧。你们要除掉强暴和毁灭的事，施行公平和公义。不要再掠夺我子民的产业。这是主神的宣告。'),
('CNV', '以西结书', 26, 45, 10, '你们要用公道的天秤、公道的量器。'),
('CNV', '以西结书', 26, 45, 11, '量固体的‘伊法’和量液体的‘罢特’的容量要相同：一‘罢特’等于‘贺梅珥’的十分之一；一‘伊法’也等于‘贺梅珥’的十分之一，都以‘贺梅珥’的容量为准。'),
('CNV', '以西结书', 26, 45, 12, '重量单位的一‘舍客勒’是二十‘季拉’；二十‘舍客勒’，加二十五‘舍客勒’和十五‘舍客勒’、就是你们的一‘弥那’。'),
('CNV', '以西结书', 26, 45, 13, '“你们所当献的供物是这样：一‘贺梅珥’小麦，要献一‘伊法’的六分之一；一‘贺梅珥’大麦，要献一‘伊法’的六分之一。'),
('CNV', '以西结书', 26, 45, 14, '献油的规定是这样：要用‘罢特’来量，一‘柯珥’要献一‘罢特’的十分之一。原来一‘柯珥’等于十‘罢特’或是一‘贺梅珥’，因为十‘罢特’就是一‘贺梅珥’。'),
('CNV', '以西结书', 26, 45, 15, '从以色列肥沃的草场上，每二百只羊中要献一只羊羔。这些供物要作素祭、燔祭和平安祭，为他们赎罪。这是主神的宣告。'),
('CNV', '以西结书', 26, 45, 16, '国中所有的人民都要奉上供物给以色列的君王。'),
('CNV', '以西结书', 26, 45, 17, '君王要在节期、月朔、安息日，就是在以色列家一切规定的节日上，奉上燔祭、素祭和奠祭。他要预备赎罪祭、素祭、燔祭和平安祭，为以色列家赎罪。”'),
('CNV', '以西结书', 26, 45, 18, '主神这样说：“正月初一日，你要取一头无残疾的公牛犊，洁净圣所。'),
('CNV', '以西结书', 26, 45, 19, '祭司要取些赎罪祭牲的血，抹在殿的门框、祭坛台上的四角，以及内院的门框上。'),
('CNV', '以西结书', 26, 45, 20, '正月初七日，你也要为犯了误杀罪的或因愚蒙而犯罪的人这样行，为圣殿赎罪。'),
('CNV', '以西结书', 26, 45, 21, '“正月十四日，你们要守逾越节，节期共七天，期间你们要吃无酵饼。'),
('CNV', '以西结书', 26, 45, 22, '在那一天，君王要为自己和国中所有的人民预备一头公牛作赎罪祭。'),
('CNV', '以西结书', 26, 45, 23, '这节期的七天，每天他都要为主预备无残疾的公牛七头和公绵羊七只作燔祭；他每天又要预备公山羊一只作赎罪祭。'),
('CNV', '以西结书', 26, 45, 24, '他也要预备素祭，每一头公牛要与十七公升细面一同献上，每一只公绵羊要与十七公升细面一同献上；每份十七公升的细面加油三公升。'),
('CNV', '以西结书', 26, 45, 25, '七月十五日，守节的时候，他也要这样行，照着逾越节的赎罪祭、燔祭、素祭和油的条例去作。”'),
('CNV', '以西结书', 26, 46, 1, '主神这样说：“内院朝东的门，在工作的六天里，必须关闭，在安息日却要打开，在月朔之日也要打开。'),
('CNV', '以西结书', 26, 46, 2, '君王要从外面经这门的门廊进入，站在门框旁边。祭司们要为他预备燔祭和平安祭。他要在门槛那里敬拜，然后出去。这门不可关闭，直到晚上。'),
('CNV', '以西结书', 26, 46, 3, '每逢安息日和月朔，国中的人民要在这门口，在主面前敬拜。'),
('CNV', '以西结书', 26, 46, 4, '君王在安息日所献给主的燔祭，是六只无残疾的羊羔和一只无残疾的公绵羊。'),
('CNV', '以西结书', 26, 46, 5, '所献的素祭是这样：公绵羊要与十七公升细面一同献上，他要按着自己的能力，随同那些羊羔献上若干份细面，但每份细面加油三公升。'),
('CNV', '以西结书', 26, 46, 6, '他要在月朔献一头无残疾的公牛犊、六只羊羔和一只公绵羊，都是无残疾的。'),
('CNV', '以西结书', 26, 46, 7, '他要预备素祭，公牛要与十七公升细面一同献上，公绵羊要与十七公升细面一同献上，他要按着自己的能力，随同那些羊羔献上若干份细面，但每份细面加油三公升。'),
('CNV', '以西结书', 26, 46, 8, '君王进入的时候，要经这门的门廊进入，也要从原路出去。'),
('CNV', '以西结书', 26, 46, 9, '“在各指定的节日中，国中的人民来朝见主的时候，那从北门进来敬拜的，要从南门出去；那从南门进来的，要从北门出去；谁也不可从他进来的门回去，却要从对面的门出去。'),
('CNV', '以西结书', 26, 46, 10, '君王要在人民当中，人民进入的时候，他也进入；人民出去的时候，他也出去。'),
('CNV', '以西结书', 26, 46, 11, '在节期和指定的节日中，所献的素祭是这样：每一头公牛要与十七公升细面一同献上，每一只公绵羊要与十七公升细面一同献上，每一只羊羔要按着他的能力，与细面一同献上，每份十七公升的细面加油三公升。'),
('CNV', '以西结书', 26, 46, 12, '君王把甘心献的燔祭或平安祭献给主的时候，朝东的门要为他打开。他就献上他的燔祭和平安祭，正如他在安息日所献上的一样。他献完了就出去；他出去以后，门就要关上。'),
('CNV', '以西结书', 26, 46, 13, '“每天你要预备一只一岁无残疾的羊羔，献给主作燔祭，每天早晨都要献上。'),
('CNV', '以西结书', 26, 46, 14, '每天早晨也要预备同献的素祭，细面两公斤，并调和细面所用的油一公升，作常献给主的素祭，这是永远的定例。'),
('CNV', '以西结书', 26, 46, 15, '所以每天早晨要这样预备羊羔、素祭和油，作常献的燔祭。”'),
('CNV', '以西结书', 26, 46, 16, '主神这样说：“君王如果把自己一部分的产业作礼物赐给他的一个儿子，这产业就要归给他的子孙；那是他们所承受的基业。'),
('CNV', '以西结书', 26, 46, 17, '君王如把自己的一部分产业作礼物赐给他的一个臣仆，这产业就要归给那臣仆直到自由之年，然后要归还给君王。君王的产业，至终只可归儿子所有。'),
('CNV', '以西结书', 26, 46, 18, '君王不可夺取人民的产业，把他们赶离他们的基业。他要从自己的基业中把产业赐给自己的儿子，免得我的子民因被赶离自己的基业而四散。”'),
('CNV', '以西结书', 26, 46, 19, '那带领我的，领我从门旁的入口，进到那些朝向北面，供祭司使用，圣洁的房子。在西边的尽头有一块地方。'),
('CNV', '以西结书', 26, 46, 20, '他对我说：“这就是祭司煮赎愆祭牲和赎罪祭牲，以及烤素祭的地方，免得祭物带出外院，使人民成圣。”'),
('CNV', '以西结书', 26, 46, 21, '他又领我出到外院，使我经过院子的四个角落；院子的每个角落都有一个小院子。'),
('CNV', '以西结书', 26, 46, 22, '院子四个角落的小（“小”字原文不详）院子，每个长二十公尺，宽十五公尺；四个角落的院子，大小都是一样。'),
('CNV', '以西结书', 26, 46, 23, '在四个小院子里面，每个四边都有一排石墙；在这四排石墙下面，都有炉灶。'),
('CNV', '以西结书', 26, 46, 24, '他对我说：“这些都是厨房，在圣殿里供职的要在这里煮人民的祭物。”'),
('CNV', '以西结书', 26, 47, 1, '然后，他带我回到圣殿的门口。有水正从殿的门槛往下流出来，向东流去，因为圣殿是朝东的。这水从殿的右边，从祭坛的南边下面流出来。'),
('CNV', '以西结书', 26, 47, 2, '他又带我从北门出来，再领我从外面绕到朝东的外门。有水正从右边流出来。'),
('CNV', '以西结书', 26, 47, 3, '那人手里拿着一根准绳向东走出去的时候，量了五百公尺的距离，然后领我从水中走过去，那里的水到了脚踝。'),
('CNV', '以西结书', 26, 47, 4, '他又量了五百公尺，然后领我从水中走过去，水到了膝盖。他又量了五百公尺，然后领我走过去，水到了腰。'),
('CNV', '以西结书', 26, 47, 5, '他再量了五百公尺，水已成了一条河，以致我不能走过去，因为水势高涨，成为只可供游泳的水，而不能走过去的河。'),
('CNV', '以西结书', 26, 47, 6, '他对我说：“人子啊！你看到了吗？”他就领着我，带我回到河边。'),
('CNV', '以西结书', 26, 47, 7, '我回来以后，看见河这边和那边的岸上有很多树木。'),
('CNV', '以西结书', 26, 47, 8, '他又对我说：“这水要向东方的地区流出去，下到亚拉巴，流入死海。这水流入死海，就使海里的水变淡（“变淡”原文作“得医治”）。'),
('CNV', '以西结书', 26, 47, 9, '那时，这河流过的地方，所有滋生的动物都可以存活。这水流到哪里，哪里就有许多鱼；因为这河流到哪里，海水就变淡，一切都可以存活。'),
('CNV', '以西结书', 26, 47, 10, '必有渔夫站在河边，从隐．基底直到隐．以革莲，都是晒网的地方。各类的鱼都像大海里的鱼那样多。'),
('CNV', '以西结书', 26, 47, 11, '只有沼泽和洼地的水不能变淡，留作产盐之用。'),
('CNV', '以西结书', 26, 47, 12, '在河这边和那边的岸上，都必有各种果树生长，可作食物，树上的叶子不枯干，果子也不断绝。每月必结出新果子，因为树所需的水是从圣所里流出来的。树上的果子可作食物，叶子可以治病。”'),
('CNV', '以西结书', 26, 47, 13, '主神这样说：“你们按着以色列十二支派分地为业，要照着这些地界：约瑟要得双份。'),
('CNV', '以西结书', 26, 47, 14, '你们要均分这地为业，因为我曾举手要把这地赐给你们的列祖，这地必归给你们为业。'),
('CNV', '以西结书', 26, 47, 15, '“这地的边界是：北边从大海经希特伦的路，到西达达的入口，'),
('CNV', '以西结书', 26, 47, 16, '又经哈马、比罗他和位于大马士革边界与哈马边界之间的西伯莲，直到浩兰的边界的哈撒．哈提干。'),
('CNV', '以西结书', 26, 47, 17, '这边界从海到哈萨．以难，北边有大马士革的边界，再北有哈马的边界。这是北面的地界。'),
('CNV', '以西结书', 26, 47, 18, '东面的地界是在浩兰和大马士革之间，基列和以色列地之间的约旦河。你们要从北面的地界量到东海（“你们要从北面的地界量到东海”或参照《叙利亚文古译本》翻译为“伸界到东海，以至他玛”），这是东面的地界。'),
('CNV', '以西结书', 26, 47, 19, '南面的地界，从他玛到米利巴．加低斯水，经埃及小河，到大海。这是南面的地界。'),
('CNV', '以西结书', 26, 47, 20, '西面的地界是大海，从南面的地界到哈马口的对面。这是西面的地界。'),
('CNV', '以西结书', 26, 47, 21, '“你们要按着以色列的支派分这地。'),
('CNV', '以西结书', 26, 47, 22, '将来你们要抽签分这地为业，归给你们和你们中间的外族人。他们在你们中间生儿育女。你们应该看他们如同本地生的以色列人，他们要在以色列支派中与你们一起抽签分地为业。'),
('CNV', '以西结书', 26, 47, 23, '将来无论在哪一支派里，若有外族人寄居，你们就要在那里把他的产业分给他。”这是主神的宣告。'),
('CNV', '以西结书', 26, 48, 1, '“各支派名下的产业是这样：在北边尽头的地界起，沿着希特伦的路，经哈马口到大马士革边界上的哈萨．以难，北边靠着哈马地，从东到西，是但的一份。'),
('CNV', '以西结书', 26, 48, 2, '沿着但的边界，从东到西，是亚设的一份。'),
('CNV', '以西结书', 26, 48, 3, '沿着亚设的边界，从东到西，是拿弗他利的一份。'),
('CNV', '以西结书', 26, 48, 4, '沿着拿弗他利的边界，从东到西，是玛拿西的一份。'),
('CNV', '以西结书', 26, 48, 5, '沿着玛拿西的边界，从东到西，是以法莲的一份。'),
('CNV', '以西结书', 26, 48, 6, '沿着以法莲的边界，从东到西，是流本的一份。'),
('CNV', '以西结书', 26, 48, 7, '沿着流本的边界，从东到西，是犹大的一份。'),
('CNV', '以西结书', 26, 48, 8, '“沿着犹大的边界，从东到西，就是你们所要献出的圣区，长十二公里半，从东到西的长度与其他各份的一样，圣所要在其中。'),
('CNV', '以西结书', 26, 48, 9, '你们献给主的地区，要长十二公里半，宽十公里。'),
('CNV', '以西结书', 26, 48, 10, '献给祭司的圣地，北边长十二公里半，西边宽五公里，东边宽五公里，南边长十二公里半。'),
('CNV', '以西结书', 26, 48, 11, '这地要归给祭司，就是撒督子孙中分别为圣的。他们守我所吩咐的职责；以色列人走迷路的时候，他们不像利未人那样走迷路。'),
('CNV', '以西结书', 26, 48, 12, '因此，从所献的圣区要有一块地献给祭司，作为至圣之地。这地沿着利未人的地界。'),
('CNV', '以西结书', 26, 48, 13, '沿着祭司的地界要有一块地献给利未人，长十二公里半，宽五公里。祭司的地也是长十二公里半，宽五公里。'),
('CNV', '以西结书', 26, 48, 14, '这地的任何部分不可变卖，不可交换，也不可转让给别人，因为它是这地中最好的一份，是归主为圣的。'),
('CNV', '以西结书', 26, 48, 15, '“所剩下的地，宽两公里半，长十二公里半，要作俗地，供城市、居民和郊野之用。城要在其中。'),
('CNV', '以西结书', 26, 48, 16, '城的大小是这样：北边二千二百五十公尺，南边二千二百五十公尺，东边二千二百五十公尺，西边二千二百五十公尺。'),
('CNV', '以西结书', 26, 48, 17, '城要有郊野，北边一百二十五公尺，南边一百二十五公尺，东边一百二十五公尺，西边一百二十五公尺。'),
('CNV', '以西结书', 26, 48, 18, '这俗地两旁剩下的地，沿着所献的圣区的长度计算，东边五公里，西边五公里，也沿着所献的圣区。这些地的出产要给城里的工人作食物。'),
('CNV', '以西结书', 26, 48, 19, '城里的工人来自以色列各支派，耕种这地。'),
('CNV', '以西结书', 26, 48, 20, '所献的整个地区，长十二公里半，宽十二公里半，是见方的。你们要把所献的圣区，连同城的基业，一起献上。'),
('CNV', '以西结书', 26, 48, 21, '“所献的圣区和城的基业，两旁所剩下的都要归给君王，从那宽十二公里半的献地以东至东面的边界，以及从那宽十二公里半的献地以西至西边的边界沿着其他各分地，都要归给君王。这样所献的圣地和殿的圣所，都在这两块地的中间。'),
('CNV', '以西结书', 26, 48, 22, '利未人的基业和城的基业都位于君王的地中间。君王的地是在犹大的边界和便雅悯的边界中间。'),
('CNV', '以西结书', 26, 48, 23, '“至于其余的支派，从东到西，是便雅悯的一份。'),
('CNV', '以西结书', 26, 48, 24, '沿着便雅悯的边界，从东到西，是西缅的一份。'),
('CNV', '以西结书', 26, 48, 25, '沿着西缅的边界，从东到西，是以萨迦的一份。'),
('CNV', '以西结书', 26, 48, 26, '沿着以萨迦的边界，从东到西，是西布伦的一份。'),
('CNV', '以西结书', 26, 48, 27, '沿着西布伦的边界，从东到西，是迦得的一份。'),
('CNV', '以西结书', 26, 48, 28, '迦得南面的边界，是从他玛到米利巴．加低斯水，经埃及小河到大海。'),
('CNV', '以西结书', 26, 48, 29, '这就是你们要抽签分给以色列各支派为业的地。这些分地就是他们所得的分。”这是主神的宣告。'),
('CNV', '以西结书', 26, 48, 30, '“城北面的长度是二千二百五十公尺。城的出口是这样：'),
('CNV', '以西结书', 26, 48, 31, '城门要按以色列各支派取名。北面有三个门口，一个是流本门，一个是犹大门，一个是利未门。'),
('CNV', '以西结书', 26, 48, 32, '东面的长度是二千二百五十公尺，有三个门口，一个是约瑟门，一个是便雅悯门，一个是但门。'),
('CNV', '以西结书', 26, 48, 33, '南面的长度是二千二百五十公尺，有三个门口，一个是西缅门，一个是以萨迦门，一个是西布伦门。'),
('CNV', '以西结书', 26, 48, 34, '西面的长度是二千二百五十公尺，也有三个门口，一个是迦得门，一个是亚设门，一个是拿弗他利门。'),
('CNV', '以西结书', 26, 48, 35, '城的周围共长九千公尺。从此以后，这城的名字要称为‘主的所在’。”'),
('CNV', '但以理书', 27, 1, 1, '犹大王约雅敬在位第三年，巴比伦王尼布甲尼撒来到耶路撒冷，把城围困。'),
('CNV', '但以理书', 27, 1, 2, '主把犹大王约雅敬和神殿中的一部分器物交在尼布甲尼撒手里，他就把这些器物带到示拿地的神庙那里，存放在庙中的宝库里。'),
('CNV', '但以理书', 27, 1, 3, '王吩咐他的太监长亚施毗拿说：“你要从以色列人中，把一些王室的后裔和贵族带进来；'),
('CNV', '但以理书', 27, 1, 4, '这些年轻人必须没有残疾、英俊、足智多才、有高度学习能力、明察事理，而且他们必须有能力可以在王宫里工作。你要教他们学习迦勒底的文学和语言。”'),
('CNV', '但以理书', 27, 1, 5, '王指定每日给他们一份御用的佳肴美酒；又教养他们三年。期满以后，他们就侍立在王面前。'),
('CNV', '但以理书', 27, 1, 6, '他们中间有犹大人但以理、哈拿尼雅、米沙利、亚撒利雅。'),
('CNV', '但以理书', 27, 1, 7, '太监长给他们起了新的名字，称但以理为伯提沙撒，哈拿尼雅为沙得拉，米沙利为米煞，亚撒利雅为亚伯尼歌。'),
('CNV', '但以理书', 27, 1, 8, '但以理决心不让御用的佳肴美酒玷污自己，所以求太监长帮助他，使他不用玷污自己。'),
('CNV', '但以理书', 27, 1, 9, '于是神使但以理在太监长面前得着恩惠和同情。'),
('CNV', '但以理书', 27, 1, 10, '只是太监长对但以理说：“我惧怕我主我王，他已指定了你们应用的饮食；如果他见到你们的面色比你们同岁的年轻人憔悴难看，你们就使我的头在王面前保不住了。”'),
('CNV', '但以理书', 27, 1, 11, '后来但以理对太监长分派看管但以理、哈拿尼雅、米沙利、亚撒利雅的人说：'),
('CNV', '但以理书', 27, 1, 12, '“请你试试仆人十天，容我们只吃素菜、喝清水。'),
('CNV', '但以理书', 27, 1, 13, '然后，请你观察我们的容貌，和那些享用王的佳肴的年轻人的容貌，就照着你观察的结果，待你的仆人吧！”'),
('CNV', '但以理书', 27, 1, 14, '看管他们的人就允准他们的这个要求，试试他们十天。'),
('CNV', '但以理书', 27, 1, 15, '过了十天，见他们的容貌比所有享用王的佳肴的年轻人，更加俊美健壮。'),
('CNV', '但以理书', 27, 1, 16, '看管他们的人就撤去指定给他们享用的佳肴美酒，让他们吃素菜。'),
('CNV', '但以理书', 27, 1, 17, '这四个年轻人在各种文字和学问上，神都赐他们知识和聪明；但以理并且能明白一切异象和异梦。'),
('CNV', '但以理书', 27, 1, 18, '到了王吩咐带所有年轻人进宫的日子，太监长就领他们到尼布甲尼撒王面前。'),
('CNV', '但以理书', 27, 1, 19, '王和他们谈话，发现他们所有的人中，没有一个比得上但以理、哈拿尼雅、米沙利、亚撒利雅的；他们四人就侍立在王面前。'),
('CNV', '但以理书', 27, 1, 20, '王考问他们一切智慧和聪明的事，就发现他们比全国所有的术士和用法术的更胜十倍。'),
('CNV', '但以理书', 27, 1, 21, '直到古列王元年，但以理还在。'),
('CNV', '但以理书', 27, 2, 1, '尼布甲尼撒在位第二年，他作了梦，因此心里烦乱，不能入睡。'),
('CNV', '但以理书', 27, 2, 2, '于是王吩咐人把术士、用法术的、行邪术的和迦勒底人都召来，要他们把王的梦告诉王。他们来了，站在王面前。'),
('CNV', '但以理书', 27, 2, 3, '王对他们说：“我作了一个梦，心里烦乱，我要知道这是什么梦。”'),
('CNV', '但以理书', 27, 2, 4, '迦勒底人用亚兰话对王说：“愿王万岁！请把那梦告诉仆人，我们好解释梦的意思。”'),
('CNV', '但以理书', 27, 2, 5, '王回答迦勒底人说：“我已经定旨：如果你们不把那梦和梦的意思向我说明，就必被碎尸万段，你们的家必成为废墟。'),
('CNV', '但以理书', 27, 2, 6, '如果你们能把那梦和梦的意思向我解释，就必从我这里得礼物、奖赏和大尊荣，所以你们要把梦和梦的意思向我解释。”'),
('CNV', '但以理书', 27, 2, 7, '他们第二次回答王说：“请王把梦告诉仆人，我们好解释梦的意思。”'),
('CNV', '但以理书', 27, 2, 8, '王回答说：“我清楚知道你们企图拖延时间，因为你们看出我已经定旨。'),
('CNV', '但以理书', 27, 2, 9, '如果你们不把那梦向我说明，只有一个办法对付你们。你们串通在我面前胡言乱语，希望时势有所改变。你们现在要把梦告诉我，好使我知道你们真能把梦的意思向我解释。”'),
('CNV', '但以理书', 27, 2, 10, '迦勒底人在王面前回答说：“世上没有人能把王所问的事说出来，因为从来没有一个伟大和有权势的君王向术士、用法术的和迦勒底人询问过这样的事。'),
('CNV', '但以理书', 27, 2, 11, '王所问的事很难答，除了那不和世人同住的神明以外，没有人能在王面前把这事说出来。”'),
('CNV', '但以理书', 27, 2, 12, '因此，王大发烈怒，下令杀绝巴比伦所有的智慧人。'),
('CNV', '但以理书', 27, 2, 13, '于是王的御旨发出，要把智慧人都杀死；人就寻找但以理和他的同伴，要杀死他们。'),
('CNV', '但以理书', 27, 2, 14, '那时，王的护卫长亚略出来，要杀死巴比伦的智慧人，但以理就婉转机敏地向他询问；'),
('CNV', '但以理书', 27, 2, 15, '但以理对王的护卫长亚略说：“王的命令为什么这样严厉呢？”亚略就把这事告诉但以理。'),
('CNV', '但以理书', 27, 2, 16, '但以理就进去，求王宽限，使他可以把那梦的意思为王解释。'),
('CNV', '但以理书', 27, 2, 17, '但以理回到自己的家里，把这事告诉他的同伴哈拿尼雅、米沙利和亚撒利雅，'),
('CNV', '但以理书', 27, 2, 18, '要他们为这隐秘的事祈求天上的神怜悯，免得但以理和他的同伴与巴比伦其余的智慧人一同灭亡。'),
('CNV', '但以理书', 27, 2, 19, '于是这隐秘的事在夜间的异象中给但以理显明了。但以理就称颂天上的神。'),
('CNV', '但以理书', 27, 2, 20, '但以理说：“愿神的名得称颂，从永远直到永远，因为智慧和能力都是属他的。'),
('CNV', '但以理书', 27, 2, 21, '他改变时间、季节；他废王、立王；他赐智慧给智慧人，赐知识给聪明人。'),
('CNV', '但以理书', 27, 2, 22, '他显明深奥和隐密的事，他洞悉暗中的一切，因为光明与他同住。'),
('CNV', '但以理书', 27, 2, 23, '我列祖的神啊！我感谢你，赞美你！你把智慧和能力赐了给我；我们向你所求的，现在你已向我显明，把王的事告诉了我们。”'),
('CNV', '但以理书', 27, 2, 24, '于是但以理进去见亚略，就是王委派去杀绝巴比伦的智慧人的，对他这样说：“不要杀绝巴比伦的智慧人；请把我带到王面前，我要把梦的意思向王解释。”'),
('CNV', '但以理书', 27, 2, 25, '亚略就急忙把但以理带到王面前，对王这样说：“我在被掳的犹大人中找到一个能把梦的意思向王说明的人。”'),
('CNV', '但以理书', 27, 2, 26, '王问称为伯提沙撒的但以理说：“你能向我说明我所见的梦和梦的意思吗？”'),
('CNV', '但以理书', 27, 2, 27, '但以理在王面前回答说：“王所问的那隐秘的事，没有智慧人、用法术的、术士和占星家能向王解释；'),
('CNV', '但以理书', 27, 2, 28, '只有一位在天上的神能把一切隐秘的事显明；他已经把日后将要发生的事告诉你尼布甲尼撒王了。你的梦和你躺在床上时脑海中出现的异象就是这样：'),
('CNV', '但以理书', 27, 2, 29, '王啊！你躺在床上时，想到日后将要发生的事，那显明隐秘事的神就把将要发生的事向你说明了。'),
('CNV', '但以理书', 27, 2, 30, '现在这隐秘的事向我显明，并不是因为我的智慧胜过所有的人，而是要使王知道梦的意思和你心想明白的事。'),
('CNV', '但以理书', 27, 2, 31, '“王啊！你正在观看，看见有一座大像，那像甚高，非常光耀，竖立在你面前，样貌十分可怕。'),
('CNV', '但以理书', 27, 2, 32, '这像的头是纯金的，胸膛和手臂是银的，腹和腰是铜的，'),
('CNV', '但以理书', 27, 2, 33, '腿是铁的，脚是铁和泥混杂的。'),
('CNV', '但以理书', 27, 2, 34, '你正观看的时候，有一块非人手凿成的石头，击在那座大像铁和泥混杂的脚上，把脚砸碎了。'),
('CNV', '但以理书', 27, 2, 35, '于是铁、泥、铜、银、金都一同砸得粉碎，好像夏天禾场上的糠秕，被风吹散，无处可寻；那打碎这像的石头却变成一座大山，充满全地。'),
('CNV', '但以理书', 27, 2, 36, '“这就是那梦，现在我们要在王面前讲解那梦的意思。'),
('CNV', '但以理书', 27, 2, 37, '王啊！你是万王之王，天上的神已经把国度、权柄、能力和尊荣都赐给你；'),
('CNV', '但以理书', 27, 2, 38, '也把散居在各处的世人、田野的走兽和空中的飞鸟，都交在你手里，使你管理这一切。你就是那金头。'),
('CNV', '但以理书', 27, 2, 39, '在你以后，另一国将兴起，不及于你。后有第三国，就是那铜的，要统治全地。'),
('CNV', '但以理书', 27, 2, 40, '还有第四国，坚强如铁，因为铁能砸碎击破万物；铁怎样压碎一切，那国也要照样砸碎一切。'),
('CNV', '但以理书', 27, 2, 41, '正如你看见那像的脚和脚趾是窑匠的泥和铁混杂的，那国也必分裂；正如你看见铁和陶泥混合在一起，那国也必有铁的坚硬。'),
('CNV', '但以理书', 27, 2, 42, '那些脚趾是铁和泥混杂的，那国也必是部分坚强，部分脆弱。'),
('CNV', '但以理书', 27, 2, 43, '你怎样看见铁和陶泥混合在一起，那国的人也必和列国的人通婚混杂，却不能彼此联合，正如铁和泥不能混杂一样。'),
('CNV', '但以理书', 27, 2, 44, '那些王在位的时候，天上的神必兴起另一个永不灭亡的国，国权必不归给别族的人。这国必砸碎毁灭其他各国；并且这国必存到永远。'),
('CNV', '但以理书', 27, 2, 45, '正如你看见那块从山而出，非人手凿成的石头，把铁、铜、泥、银和金都砸碎了，伟大的神已把日后必有的结局都告诉王了。这梦是确实的，梦的意思也是准确的。”'),
('CNV', '但以理书', 27, 2, 46, '尼布甲尼撒王俯伏在地，向但以理下拜，又下令向但以理献上供物和香品。'),
('CNV', '但以理书', 27, 2, 47, '王对但以理说：“你们的神真是万神之神，万王之王，又是显明隐秘事的，因为你能把这隐秘的事显明出来。”'),
('CNV', '但以理书', 27, 2, 48, '于是王提升但以理，赐他许多贵重的礼物，使他管理巴比伦全省，又立他为总长，管理巴比伦所有的智慧人。'),
('CNV', '但以理书', 27, 2, 49, '但以理求王，王就委派沙得拉、米煞、亚伯尼歌管理巴比伦省的政务；但以理却在朝中侍立。'),
('CNV', '但以理书', 27, 3, 1, '尼布甲尼撒王造了一座金像，高二十七公尺，宽三公尺，竖立在巴比伦省的杜拉平原上。'),
('CNV', '但以理书', 27, 3, 2, '尼布甲尼撒王派人召集总督、总监、省长、参谋、财政大臣、法官、裁判官和各省所有的官员，要他们参加尼布甲尼撒王为所立的像举行的揭幕典礼。'),
('CNV', '但以理书', 27, 3, 3, '于是总督、总监、省长、参谋、财政大臣、法官、裁判官和省内所有其他的官员，都聚集起来，参加尼布甲尼撒王为所立的像举行的揭幕典礼；他们都站在尼布甲尼撒所立的像前。'),
('CNV', '但以理书', 27, 3, 4, '那时，传令官大声呼叫说：“各国、各族、说各种语言的人哪！这是传给你们的命令：'),
('CNV', '但以理书', 27, 3, 5, '你们一听见角、笛、琵琶、弦琴、竖琴、风笛和各种乐器的声音，就要俯伏，向尼布甲尼撒王所立的金像下拜。'),
('CNV', '但以理书', 27, 3, 6, '凡不俯伏下拜的，就必立刻扔在烈火的窑中。”'),
('CNV', '但以理书', 27, 3, 7, '因此，各国、各族和说各种语言的人，一听见角、笛、琵琶、弦琴、竖琴和各种乐器的声音，就都俯伏，向尼布甲尼撒王所立的金像下拜。'),
('CNV', '但以理书', 27, 3, 8, '那时，有几个迦勒底人前来，诬蔑控告犹大人。'),
('CNV', '但以理书', 27, 3, 9, '他们对尼布甲尼撒王说：“愿王万岁！'),
('CNV', '但以理书', 27, 3, 10, '王啊，你曾下令，凡听见角、笛、琵琶、弦琴、竖琴、风笛和各种乐器声音的人，都要俯伏，向金像下拜。'),
('CNV', '但以理书', 27, 3, 11, '凡不俯伏下拜的，就必被扔在烈火的窑中。'),
('CNV', '但以理书', 27, 3, 12, '但有几个犹大人，就是王所派管理巴比伦省政务的沙得拉、米煞和亚伯尼歌，王啊！这些人不理会你的命令，不事奉你的神，也不向你所立的金像下拜。”'),
('CNV', '但以理书', 27, 3, 13, '当时尼布甲尼撒勃然大怒，吩咐人把沙得拉、米煞和亚伯尼歌带来；他们就被带到王面前。'),
('CNV', '但以理书', 27, 3, 14, '尼布甲尼撒问他们说：“沙得拉、米煞、亚伯尼歌啊！你们真的不事奉我的神，也不向我所立的金像下拜吗？'),
('CNV', '但以理书', 27, 3, 15, '现在，如果你们想清楚，一听见角、笛、琵琶、弦琴、竖琴、风笛和各种乐器的声音，就俯伏向我所做的像下拜，那还可以。如果你们不下拜，就必立刻扔在烈火的窑中。哪里有神能救你们脱离我的手呢？”'),
('CNV', '但以理书', 27, 3, 16, '沙得拉、米煞、亚伯尼歌回答王说：“尼布甲尼撒啊！这件事我们无需回答你。'),
('CNV', '但以理书', 27, 3, 17, '如果我们被扔在火窑里，我们所事奉的神必能拯救我们；王啊！他必拯救我们脱离烈火的窑和你的手。（本节或译：“如果我们所事奉的神能拯救我们，王啊！他必拯救我们脱离烈火的窑和你的手。”）'),
('CNV', '但以理书', 27, 3, 18, '即或不然，王啊！你要知道，我们决不事奉你的神，也不向你所立的金像下拜。”'),
('CNV', '但以理书', 27, 3, 19, '当时尼布甲尼撒向沙得拉、米煞和亚伯尼歌大发烈怒，连脸色也变了，吩咐人把窑烧热，比平常猛烈七倍。'),
('CNV', '但以理书', 27, 3, 20, '又吩咐他军队中几个最精壮的士兵，把沙得拉、米煞和亚伯尼歌绑起来，扔在烈火的窑中。'),
('CNV', '但以理书', 27, 3, 21, '于是这三个人穿着外袍、长裤、头巾和身上其他的衣服，被绑起来，扔在烈火的窑中。'),
('CNV', '但以理书', 27, 3, 22, '由于王的命令紧急，窑又烧得非常猛烈，那些把沙得拉、米煞和亚伯尼歌抬起来的人，都被火焰烧死了。'),
('CNV', '但以理书', 27, 3, 23, '而沙得拉、米煞和亚伯尼歌这三个人仍被绑着，落入烈火的窑中。'),
('CNV', '但以理书', 27, 3, 24, '那时尼布甲尼撒王非常惊奇，急忙起来，问他的谋臣说：“我们绑起来扔在火里的，不是三个人吗？”他们回答王说：“王啊！是的。”'),
('CNV', '但以理书', 27, 3, 25, '王说：“但我见有四个人，并没有绑着，在火中走来走去，也没有受伤，并且那第四个的样貌好像神子。”'),
('CNV', '但以理书', 27, 3, 26, '于是尼布甲尼撒走近烈火的窑口，说：“至高神的仆人沙得拉、米煞和亚伯尼歌啊！你们出来，到这里来吧。”沙得拉、米煞和亚伯尼歌就从火中出来。'),
('CNV', '但以理书', 27, 3, 27, '那些总督、总监、省长和王的谋臣，都聚拢来看这三个人，见火无力伤他们的身体；他们的头发没有烧焦，衣服没有烧坏，身上也没有火烧的气味。'),
('CNV', '但以理书', 27, 3, 28, '尼布甲尼撒说：“沙得拉、米煞、亚伯尼歌的神是应当称颂的，他差遣使者拯救那些倚靠他的仆人；他们违抗王的命令，宁愿舍命，除了自己的神以外，不肯事奉敬拜任何其他的神。'),
('CNV', '但以理书', 27, 3, 29, '我现在下令：无论各国、各族、说各种语言的人，凡说话得罪沙得拉、米煞、亚伯尼歌的神的，必被碎尸万段，他的家也必成为废墟，因为没有别的神能这样施行拯救。”'),
('CNV', '但以理书', 27, 3, 30, '于是王在巴比伦省提升了沙得拉、米煞和亚伯尼歌。'),
('CNV', '但以理书', 27, 4, 1, '尼布甲尼撒王向住在全地的各国、各族和说各种语言的人宣告说：“愿你们大享平安！'),
('CNV', '但以理书', 27, 4, 2, '我乐意把至高的神向我所行的神迹奇事宣扬出来。'),
('CNV', '但以理书', 27, 4, 3, '他的神迹多么伟大，他的奇事多么有力；他的国是永远的国，他的统治直到万代！（本章第1~3节在《马索拉文本》为3:31~33）'),
('CNV', '但以理书', 27, 4, 4, '“我尼布甲尼撒安逸地住在家中，在宫里享受荣华富贵。（本节在《马索拉文本》为4:1）'),
('CNV', '但以理书', 27, 4, 5, '我作了一个梦，这梦使我惧怕；我在床上所见的梦幻和我脑海中出现的异象，都使我惊惶。'),
('CNV', '但以理书', 27, 4, 6, '我就下令把巴比伦所有的智慧人，都带到我面前来，要他们把梦的意思向我说明。'),
('CNV', '但以理书', 27, 4, 7, '于是术士、用法术的、迦勒底人和占星家都进来；我当面把那梦告诉了他们，可是他们却不能把梦的意思向我说明。'),
('CNV', '但以理书', 27, 4, 8, '“最后，那照着我神的名，称为伯提沙撒的但以理，来到我面前，他里面有圣神的灵，我就把梦告诉他：'),
('CNV', '但以理书', 27, 4, 9, '‘术士的领袖伯提沙撒啊！因为我知道你里面有圣神的灵，没有什么隐秘的事能难倒你；因此，你要把我梦中所见的异象和梦的意思告诉我。'),
('CNV', '但以理书', 27, 4, 10, '我躺在床上时脑海中所见的异象是这样：我看见大地中间，有一棵树，十分高大。'),
('CNV', '但以理书', 27, 4, 11, '那树渐长，而且坚强，高达于天，地极所有的人都看得到。'),
('CNV', '但以理书', 27, 4, 12, '它的叶子美丽，果实繁多，所有的生物都从它得到食物；野地的走兽在它下面歇息，空中的飞鸟栖宿在它的枝头上；各种生物都从它得着供养。'),
('CNV', '但以理书', 27, 4, 13, '“‘我躺在床上，在我脑海出现的异象中，我看见有一位守望者，就是圣者，从天上下来，'),
('CNV', '但以理书', 27, 4, 14, '大声呼叫，这样说：你们要砍下这树，削断枝子，摇落叶子，打散果子，把树下的走兽赶散，把树枝上的飞鸟赶走。'),
('CNV', '但以理书', 27, 4, 15, '然而，树根的余干却要留在地上，用铁和铜的链子围住，留在野地的青草中，使他被天露滴湿；使他像走兽一样在地上的草丛中得他的分。'),
('CNV', '但以理书', 27, 4, 16, '使他的心改变，不再是人的心，给他一个兽心，使他经过七年的时期。'),
('CNV', '但以理书', 27, 4, 17, '这是守望者宣告的裁决，是圣者颁布的决定，好使世人都知道：至高者在世人的国中掌权，他喜欢把国赐给谁，就赐给谁，甚至立最卑微的人执掌国权。'),
('CNV', '但以理书', 27, 4, 18, '“‘这就是我尼布甲尼撒王所作的梦。伯提沙撒啊！你要把这梦的意思告诉我，因为我国中所有的智慧人都不能把梦的意思向我说明；只有你能，因为你里面有圣神的灵。’”'),
('CNV', '但以理书', 27, 4, 19, '于是那称为伯提沙撒的但以理惊愕片时，他想到的事使他惊惶。王对他说：“伯提沙撒啊！别让这梦和梦的意思使你惊惶。”伯提沙撒回答说：“我主啊！愿这梦归给憎恨你的人，梦的意思归给你的敌人。'),
('CNV', '但以理书', 27, 4, 20, '你所见的树渐长，而且坚强，高达于天，全地的人都看得到。'),
('CNV', '但以理书', 27, 4, 21, '它的叶子美丽，果实繁多，所有的生物都从它得到食物；野地的走兽住在它下面，空中的飞鸟栖在它的枝头上。'),
('CNV', '但以理书', 27, 4, 22, '王啊！你就是那树，越来越伟大坚强；你的威势渐长，高达于天；你的权柄直到地极。'),
('CNV', '但以理书', 27, 4, 23, '王既然看见一位守望者，就是圣者，从天上下来，说：‘你们要砍下毁坏这树，树根的余干却要留在地上，用铁和铜的链子围住，留在野地的青草中，使他被天露滴湿；使他的分和野地的走兽一样，直到他经过那七年的时期。’'),
('CNV', '但以理书', 27, 4, 24, '王啊！梦的意思就是这样：这临到我主我王的事，是至高者的裁决。'),
('CNV', '但以理书', 27, 4, 25, '你必被赶逐，离开人群，和野地的走兽同住；你必像牛一样吃草，被天露滴湿，要经过七年的时期；等到你承认至高者在世人的国中掌权，他喜欢把国赐给谁，就赐给谁。'),
('CNV', '但以理书', 27, 4, 26, '守望者既然吩咐要留下树根的余干，所以，等到你承认上天的至高者是掌权的，你的国就必再归给你。'),
('CNV', '但以理书', 27, 4, 27, '因此，王啊！请你接纳我的劝告，施行公义，断绝罪过，怜悯受欺压者，断绝罪孽，你的平安或者可以延长。”'),
('CNV', '但以理书', 27, 4, 28, '这一切事都在尼布甲尼撒王身上实现了。'),
('CNV', '但以理书', 27, 4, 29, '过了十二个月，王在巴比伦王宫的平顶上散步的时候，'),
('CNV', '但以理书', 27, 4, 30, '他说：“这大巴比伦城不是我用大能大力建造作我的京都，为显我威严的荣耀吗？”'),
('CNV', '但以理书', 27, 4, 31, '这话在王的口中还没有说完，就有声音从天上传下来，说：“尼布甲尼撒王啊！有话对你说：你的王权被褫夺了。'),
('CNV', '但以理书', 27, 4, 32, '你必被赶逐，离开人群，和野地的走兽同住；你必像牛一样吃草，要经过七年的时期；等到你承认至高者在世人的国中掌权，他喜欢把国赐给谁，就赐给谁。”'),
('CNV', '但以理书', 27, 4, 33, '这话立刻就应验在尼布甲尼撒身上；他被赶逐，离开人群，像牛一样吃草，身体被天露滴湿，直到他的头发长得像鹰毛，指甲像鸟爪。'),
('CNV', '但以理书', 27, 4, 34, '“七年的日子满了，我尼布甲尼撒举目望天，我的理智恢复过来，我就称颂至高者，赞美尊崇活到永远的神。他的统治永无穷尽，他的国度直到万代。'),
('CNV', '但以理书', 27, 4, 35, '地上所有的居民，在他来说都是虚无；在天上的万军中，他凭自己的意旨行事；在地上的居民中，也是这样；没有人能拦住他的手，或问他说：‘你作什么？’'),
('CNV', '但以理书', 27, 4, 36, '“那时，我的理智恢复过来后，为着我国的光荣，我的威严和光辉也都恢复过来了。我的谋臣和官员仍来求见我，我的王权重新坚立，我的权势越发增加。'),
('CNV', '但以理书', 27, 4, 37, '现在我尼布甲尼撒赞美、尊崇、荣耀天上的王，因为他所作的一切都正确，他所行的也都公平；行为骄傲的，他都能贬低。”'),
('CNV', '但以理书', 27, 5, 1, '伯沙撒王为他的一千大臣大摆筵席，他和他们一同喝酒。'),
('CNV', '但以理书', 27, 5, 2, '伯沙撒喝酒欢畅的时候，下令把他先祖尼布甲尼撒从耶路撒冷圣殿里掠取的金银器皿拿来，好让他和他的大臣、妻妾、妃嫔用这些器皿来喝酒。'),
('CNV', '但以理书', 27, 5, 3, '于是人把从耶路撒冷圣殿里，就是神的殿里，掠来的金器皿拿来；王和他的大臣、妻妾、妃嫔就用这些器皿来喝酒。'),
('CNV', '但以理书', 27, 5, 4, '他们喝酒，赞美那些用金、银、铜、铁、木、石所做的神。'),
('CNV', '但以理书', 27, 5, 5, '当时，忽然有人手的指头出现，在王宫里灯台对面的粉墙上写字；王看见了那只正在写字的手掌，'),
('CNV', '但以理书', 27, 5, 6, '就脸色大变，心意惊惶，两脚无力，双膝彼此相碰。'),
('CNV', '但以理书', 27, 5, 7, '王大声呼叫，吩咐人把那些用法术的和迦勒底人，以及占星家都领进来；王对巴比伦的智慧人说：“谁能读这文字，又能向我解释它的意思，他必身穿紫袍，颈戴金链，在国中掌权，位列第三。”'),
('CNV', '但以理书', 27, 5, 8, '于是王所有的智慧人都进来，却不能读那文字，也不能把意思向王说明。'),
('CNV', '但以理书', 27, 5, 9, '伯沙撒王就非常惊惶，脸色大变；他的大臣也都不知所措。'),
('CNV', '但以理书', 27, 5, 10, '太后因王和他的大臣所说的话，就进入宴会的大厅，对王说：“愿王万岁！你的心意不要惊惶，也不要脸色大变。'),
('CNV', '但以理书', 27, 5, 11, '在你国中有一个人，他里面有圣神的灵；你先祖在世的日子，发现这人有灼见，有聪明，有智慧，好像神的智慧一样。你先祖尼布甲尼撒王，就是王的先祖，曾立他为术士、用法术的，以及迦勒底人和占星家的领袖。'),
('CNV', '但以理书', 27, 5, 12, '这都因为在这但以理里面有美好的灵性，有知识，有聪明，能解梦，释谜语，能解答难题；这人尼布甲尼撒王曾给他起名叫伯提沙撒。现在可以把但以理召来，他必能解释墙上文字的意思。”'),
('CNV', '但以理书', 27, 5, 13, '于是但以理被带到王面前，王问但以理说：“你就是我先王从犹大掳来的犹大人但以理吗？'),
('CNV', '但以理书', 27, 5, 14, '我听说你里面有神的灵，有灼见，有聪明，有高超的智慧。'),
('CNV', '但以理书', 27, 5, 15, '现在智慧人和用法术的都被带到我面前了，我要他们读这文字，把文字的意思向我说明，可是他们都不能解释这文字的意思。'),
('CNV', '但以理书', 27, 5, 16, '我听说你能解释异梦，也能解答难题。现在你若能读这文字，把它的意思向我说明，就必身穿紫袍，颈戴金链，在国中掌权，位列第三。”'),
('CNV', '但以理书', 27, 5, 17, '但以理在王面前回答说：“你的礼物可以归你自己，你的赏赐可以归给别人；我却要为王读这文字，也要把意思向王说明。'),
('CNV', '但以理书', 27, 5, 18, '王啊！至高的神曾把国位、权势、光荣和威严赐给你先祖尼布甲尼撒。'),
('CNV', '但以理书', 27, 5, 19, '因神所赐给他的权势，各国、各族和说各种语言的人，都在他面前战兢恐惧；他要杀谁，就杀谁；要谁活着，谁就可以活着；要提升谁，就提升谁；要贬低谁，就贬低谁。'),
('CNV', '但以理书', 27, 5, 20, '但他心高气傲、妄自尊大的时候，就从国位上被赶下来，他的尊荣也被夺去。'),
('CNV', '但以理书', 27, 5, 21, '他被赶逐，离开人群，他的心变如兽心，他和野驴同住，像牛一样吃草，身体被天露滴湿；等到他承认至高的神在世人的国中掌权，他喜欢谁，就立谁执掌国权。'),
('CNV', '但以理书', 27, 5, 22, '伯沙撒啊！你是他的子孙，你虽然知道这一切，你的心仍不谦卑，'),
('CNV', '但以理书', 27, 5, 23, '竟高抬自己，敌对天上的主，使人把他殿中的器皿拿到你面前来，你和你的大臣、妻妾、妃嫔用这些器皿喝酒；你又赞美那些不能看见、不能听见、什么都不能知道，用金、银、铜、铁、木、石所做的神，却没有把荣耀归给那手中有你的气息，和那掌管你一切命途的神。'),
('CNV', '但以理书', 27, 5, 24, '因此，有手从神那里伸出来，写了这文字。'),
('CNV', '但以理书', 27, 5, 25, '“所写的文字是：‘弥尼，弥尼，提客勒，乌法珥新。’'),
('CNV', '但以理书', 27, 5, 26, '这文字的意思是这样：‘弥尼’就是神已数算了你国度的年日，使国终止；'),
('CNV', '但以理书', 27, 5, 27, '‘提客勒’就是你被称在天平上，显出你的缺欠；'),
('CNV', '但以理书', 27, 5, 28, '‘毗勒斯’（“毗勒斯”即“乌法珥新”的单数式）就是你的国要分裂，归给玛代人和波斯人。”'),
('CNV', '但以理书', 27, 5, 29, '于是伯沙撒下令，人就把紫袍给但以理穿上，把金链戴在他的颈上，又宣告他在国中掌权，位列第三。'),
('CNV', '但以理书', 27, 5, 30, '当夜，迦勒底人的王伯沙撒被杀。'),
('CNV', '但以理书', 27, 5, 31, '玛代人大利乌夺取了迦勒底国；那时他六十二岁。（本节在《马索拉文本》为6:1）'),
('CNV', '但以理书', 27, 6, 1, '大利乌按自己的心意，立了一百二十个总督，治理全国；（本节在《马索拉文本》为6:2）'),
('CNV', '但以理书', 27, 6, 2, '他又在这些总督之上，设立三位监察司（但以理是其中之一），监管总督的工作，免得王受亏损。'),
('CNV', '但以理书', 27, 6, 3, '因为但以理里面有美好的灵性，所以各方面都比其他的监察司和总督优胜；王有意立他治理全国。'),
('CNV', '但以理书', 27, 6, 4, '于是这些监察司和总督在但以理治国的事上，寻找把柄控告他，只是不能找到任何的把柄和过失，因为他忠心可靠，他们找不到他的任何错误和过失。'),
('CNV', '但以理书', 27, 6, 5, '那些人就说：“如果我们要控告这但以理，就只有在他神的律法中去找把柄。”'),
('CNV', '但以理书', 27, 6, 6, '这些监察司和总督就相约前来见王，对他说：“愿大利乌王万岁！'),
('CNV', '但以理书', 27, 6, 7, '国中所有的监察司、总监、总督、谋臣和省长，一同商议，请王立一条法例，实施一道禁令：无论何人，在三十天内，王啊！除了向你以外，若向任何神或任何人求什么，就必扔在狮子坑中。'),
('CNV', '但以理书', 27, 6, 8, '王啊！现在求你立这禁令，签署这份文告，使禁令不能更改。按照玛代和波斯的律法，这样的禁令是不能废除的。”'),
('CNV', '但以理书', 27, 6, 9, '于是大利乌王签署了这禁令文告。'),
('CNV', '但以理书', 27, 6, 10, '但以理知道这文告签署了以后，就上到自己家里楼顶上的房间，这房间的窗户朝向耶路撒冷开着；他一日三次双膝跪下，在他的神面前祷告称谢，像往日一样。'),
('CNV', '但以理书', 27, 6, 11, '那些人相约前来，看见但以理在他的神面前祈祷恳求。'),
('CNV', '但以理书', 27, 6, 12, '他们就来到王面前，提起王的禁令，说：“你岂不是签署了禁令，无论何人，在三十天内，王啊！除了向你以外，若向任何神或任何人求什么，就必扔在狮子坑中？”王回答说：“确有此事。按照玛代和波斯的律法，这样的禁令是不能废除的。”'),
('CNV', '但以理书', 27, 6, 13, '于是他们对王说：“王啊，在被掳的犹大人中的但以理不理会你的命令，也不理会你签署的禁令，竟仍一日三次向他的神祈求。”'),
('CNV', '但以理书', 27, 6, 14, '王听见了这话，就非常愁烦；他定意要搭救但以理，直到日落的时候，他还在设法营救但以理。'),
('CNV', '但以理书', 27, 6, 15, '那些人就相约前来见王，对他说：“王啊，你该知道，根据玛代和波斯的律法，王所立的禁令和法例，都是不能更改的。”'),
('CNV', '但以理书', 27, 6, 16, '于是王下令，人就把但以理带来，扔在狮子坑中。王对但以理说：“你常常事奉的神，他必搭救你！”'),
('CNV', '但以理书', 27, 6, 17, '有人搬了一块石头，放在坑口，王又盖上自己的印鉴和众大臣的印鉴，使惩办但以理的事不得更改。'),
('CNV', '但以理书', 27, 6, 18, '王回到宫里，整夜没有吃东西，也不要任何娱乐解闷，并且睡不着觉。'),
('CNV', '但以理书', 27, 6, 19, '次日黎明，天一亮，王就起来，急忙到狮子坑那里去。'),
('CNV', '但以理书', 27, 6, 20, '他走近坑边的时候，就用哀痛的声音呼叫但以理，对但以理说：“永活神的仆人但以理啊！你常常事奉的神能搭救你脱离狮子吗？”'),
('CNV', '但以理书', 27, 6, 21, '但以理对王说：“愿王万岁！'),
('CNV', '但以理书', 27, 6, 22, '我的神差遣了他的使者，封住狮子的口，使它们没有伤害我，因为我在神面前是清白的；王啊！在你面前我也没有作过任何错事。”'),
('CNV', '但以理书', 27, 6, 23, '王就非常高兴，吩咐人把但以理从坑里拉上来。于是但以理从坑里被拉上来，他身上一点损伤也没有，因为他信靠他的神。'),
('CNV', '但以理书', 27, 6, 24, '王下令，人就把那些诬蔑控告但以理的人，连同他们的妻子和儿女都一起带来，扔在狮子坑中；他们还没有下到坑底，狮子就抓住他们，把他们所有的骨头都咬碎了。'),
('CNV', '但以理书', 27, 6, 25, '后来大利乌王写信给住在全地的各国、各族和说各种语言的人，说：“愿你们大享平安！'),
('CNV', '但以理书', 27, 6, 26, '现在我下令，我所统治的全国人民都要在但以理的神面前战兢恐惧。“他是永活的神，他永远长存；他的国度永不灭亡，他的统治直到永远。'),
('CNV', '但以理书', 27, 6, 27, '他搭救人，拯救人；他在天上地下施行神迹奇事；他搭救了但以理脱离狮子的爪。”'),
('CNV', '但以理书', 27, 6, 28, '于是这但以理在大利乌作王的时候，和在波斯人古列作王的时候（本句或译：“于是这但以理在大利乌〔即波斯人古列〕作王的时候”），事事亨通。'),
('CNV', '但以理书', 27, 7, 1, '巴比伦王伯沙撒第一年，但以理躺在床上时，他作了一个梦，脑海中出现了异象；他就把那梦记录下来，把事情的重点述说出来。'),
('CNV', '但以理书', 27, 7, 2, '但以理说：“在夜间的异象中，我看见天的四风，搅动大海。'),
('CNV', '但以理书', 27, 7, 3, '“有四只巨兽从海中上来，形状各不相同。'),
('CNV', '但以理书', 27, 7, 4, '第一只兽像狮子，却有鹰的翅膀。我一直在观看，看见它的翅膀被拔去，它从地上被举起来，两脚像人一样直立在地上；又有人的心给了它。'),
('CNV', '但以理书', 27, 7, 5, '我又看见另一只兽，就是第二只兽；它和熊相似，挺起一边的身躯，口中的牙齿衔着三根肋骨。有人这样对它说：‘起来，吃多量的肉吧！’'),
('CNV', '但以理书', 27, 7, 6, '此后，我继续观看，看见另一只兽像豹，背上有鸟的四个翅膀；这兽有四个头，又有权柄给了它。'),
('CNV', '但以理书', 27, 7, 7, '后来，我在夜间的异象中继续观看，看见有第四只兽，非常恐怖，十分可怕，极其强壮。它有大铁牙；它吞吃咬碎，又把剩余的用脚践踏；这兽和前面的各兽都不相同；它有十个角。'),
('CNV', '但以理书', 27, 7, 8, '我正在究察这些角的时候，看见角的中间长出另一个小角来。在这小角前面，有三个先前的角连根被拔起来。这小角有眼，像人的眼，又有一张说夸大话的嘴。'),
('CNV', '但以理书', 27, 7, 9, '“我一直在观看，看见有些宝座安放好了，万古常存者就坐上去；他的衣服洁白如雪，他的头发纯净像羊毛。他的宝座是火焰，宝座的轮子是烈火。'),
('CNV', '但以理书', 27, 7, 10, '有火像河涌出，烈火从他面前冒出；事奉他的有千千，侍立在他面前的有万万。审判已经开始，案卷都展开了。'),
('CNV', '但以理书', 27, 7, 11, '“那时，因那小角说夸大话的声音，我继续观看，看见那兽被杀，尸体被毁，扔在烈火中。'),
('CNV', '但以理书', 27, 7, 12, '至于其余的三兽，它们的权柄都被夺去，它们的生命却得着延长，直到所定的时候和日期。'),
('CNV', '但以理书', 27, 7, 13, '“我在夜间的异象中继续观看，看见有一位像人子的，驾着天云而来，到万古常存者那里，被引领到他面前，'),
('CNV', '但以理书', 27, 7, 14, '得了权柄、尊荣和国度；各国、各族和说各种语言的人都事奉他。他的权柄是永远的权柄，是不能废去的；他的国度是永不毁灭的。'),
('CNV', '但以理书', 27, 7, 15, '“至于我但以理，我的灵在我里面忧伤，我脑海中出现的异象使我惊惶。'),
('CNV', '但以理书', 27, 7, 16, '于是我走近其中一位侍立者，问他有关这一切事的实情；他就告诉我，使我知道这些事的意思，他说：'),
('CNV', '但以理书', 27, 7, 17, '‘这四只巨兽就是将要在世上兴起的四个王。'),
('CNV', '但以理书', 27, 7, 18, '但至高者的圣民必要得国，拥有这国，直到永永远远。’'),
('CNV', '但以理书', 27, 7, 19, '那时我想知道有关第四只兽的实情，它和其他三兽不相同，十分恐怖，有铁牙铜爪；它吞吃咬碎，又把剩余的用脚践踏。'),
('CNV', '但以理书', 27, 7, 20, '我又想知道有关它头上的十角，和那另长出来的小角，以及那三个在这小角前面倒下的角的实情。这小角有眼，有说夸大话的嘴；它的形状比它的同类更威猛。'),
('CNV', '但以理书', 27, 7, 21, '我继续观看，看见这小角和圣民争战，战胜了他们，'),
('CNV', '但以理书', 27, 7, 22, '直到万古常存者来到，为至高者的圣民伸张正义；圣民拥有国度的时候就到了。'),
('CNV', '但以理书', 27, 7, 23, '“那位侍立者这样说：‘那第四只兽就是世上必有的第四国，和其他各国都不相同；它必吞吃全地，践踏咬碎全地。'),
('CNV', '但以理书', 27, 7, 24, '至于那十角，就是从这国中将要兴起的十个王，在他们以后，必有另一个王兴起，和先前的王都不相同；他必制伏三个王。'),
('CNV', '但以理书', 27, 7, 25, '他必说话，敌挡至高者；他必折磨至高者的圣民，又想改变节期和律法；圣民必交在他的手中，一载、二载、半载（“一载、二载、半载”或译：“一个时期、多个时期、半个时期”）。'),
('CNV', '但以理书', 27, 7, 26, '但审判要开始，他的权柄必被夺去，他必被毁坏灭绝，直到永远。'),
('CNV', '但以理书', 27, 7, 27, '那时，国度、权柄，和普天之下万国的大权，都必赐给至高者的圣民。他的国是永远的国；所有掌权的都必事奉他，顺从他。’'),
('CNV', '但以理书', 27, 7, 28, '这事到此完毕。我但以理心中十分惊惶，脸色也变了，但我把这事存放在心里。”'),
('CNV', '但以理书', 27, 8, 1, '伯沙撒王在位第三年，在先前显给我的异象之后，再有一个异象向我但以理显现。'),
('CNV', '但以理书', 27, 8, 2, '我在异象中观看，看见自己在以拦省书珊城堡里；我在异象中继续观看，看见自己在乌莱河的岸边。'),
('CNV', '但以理书', 27, 8, 3, '我举目观看，看见一只公绵羊，站在河边；它有两个角，两角都很高，但高低不一；那较高的角是较迟长出来的。'),
('CNV', '但以理书', 27, 8, 4, '我看见那公绵羊向西、向北、向南撞去，没有走兽能在它面前站立得住，也没有能拯救脱离它手的；它任意而行，狂妄自大。'),
('CNV', '但以理书', 27, 8, 5, '我正在思考的时候，忽然有一只公山羊从西而来，走遍全地，快得脚不沾尘；这山羊两眼之间有一个显眼的角。'),
('CNV', '但以理书', 27, 8, 6, '它走到我先前所看见站在河边、那有两个角的公绵羊那里去，忿怒地向公绵羊猛力冲去。'),
('CNV', '但以理书', 27, 8, 7, '我看见公山羊走近公绵羊，向它发怒，撞击它，折断它的两个角；公绵羊在它面前站立不住，它把公绵羊撞倒在地上，又用脚践踏它，没有能拯救公绵羊脱离它手的。'),
('CNV', '但以理书', 27, 8, 8, '这公山羊非常狂妄自大；但在它强盛的时候，那大角被折断了；在大角原来的地方，有四个显眼的角向天的四方长出来。'),
('CNV', '但以理书', 27, 8, 9, '从这四个角中的一个角，又长出一个小角来，这小角向南、向东和向荣美之地，不断强大起来。'),
('CNV', '但以理书', 27, 8, 10, '它渐渐长大，高及天象，把一些天象和星星摔落在地上，用脚践踏。'),
('CNV', '但以理书', 27, 8, 11, '它狂妄自大，要高及天象之君；它除掉献给天象之君的常献祭，又拆毁他的圣所。'),
('CNV', '但以理书', 27, 8, 12, '因罪过的缘故，圣民（“圣民”和8:10~11的“天象”原文是同一个字）连同常献的祭都交给它；它把真理丢在地上，任意而行，凡事顺利。'),
('CNV', '但以理书', 27, 8, 13, '我听见一位圣者在说话，又有一位圣者问他：“这个关于除掉常献的祭，和引致毁坏的罪过，以及践踏圣所和圣民（“圣民”和8:10~11的“天象”原文是同一个字）的异象，要到几时呢？”'),
('CNV', '但以理书', 27, 8, 14, '他对我说：“要到二千三百个晚上和早晨，圣所才得洁净。”'),
('CNV', '但以理书', 27, 8, 15, '我但以理看见了这异象以后，就想明白它的意义；忽然有一位外貌像人的，站在我面前。'),
('CNV', '但以理书', 27, 8, 16, '我又听见从乌莱河两岸之间，有人的声音呼叫着说：“加百列啊！你要使这人明白这异象。”'),
('CNV', '但以理书', 27, 8, 17, '他就来到我所站的地方；他来到的时候，我就害怕，脸伏在地；他对我说：“人子啊，你要明白！这异象是关于末后的时期的。”'),
('CNV', '但以理书', 27, 8, 18, '他和我说话的时候，我沉睡了，脸伏在地；他触摸我，使我站起来。'),
('CNV', '但以理书', 27, 8, 19, '他说：“看哪！我要告诉你在神忿怒审判的后期必要发生的事，因为这是有关那末后的定期的。'),
('CNV', '但以理书', 27, 8, 20, '你所看见那有两个角的公绵羊，就是玛代和波斯王。'),
('CNV', '但以理书', 27, 8, 21, '那多毛的公山羊就是希腊王；那两眼之间的大角就是第一个王。'),
('CNV', '但以理书', 27, 8, 22, '至于代替那折断了的角，在它原来的地方长出来的四个角，就是四个要从他的国中兴起的王国，只是没有他的权势。'),
('CNV', '但以理书', 27, 8, 23, '“在这四国的后期，犯罪的人恶贯满盈的时候，必有一个面貌凶恶的王兴起，他诡计多端。'),
('CNV', '但以理书', 27, 8, 24, '他的权势强大，却不是出于自己的能力；他必造成惊人的毁灭；他任意而行，凡事顺利；他必毁灭有强力的，又毁灭圣民。'),
('CNV', '但以理书', 27, 8, 25, '他运用诡计，行骗无往而不利；他心里狂妄自大；他必乘人不备的时候，毁灭许多人；他要起来攻击万君之君，最后却非因人的手被毁灭。'),
('CNV', '但以理书', 27, 8, 26, '关于所说二千三百个晚上和早晨的异象是真的，但你要把这异象封住，因为那是关于将来许多的年日的。”'),
('CNV', '但以理书', 27, 8, 27, '我但以理精疲力竭，病了几天，后来我起来，办理王的事务，但我仍因这异象惊骇不已，不明白它的意思。'),
('CNV', '但以理书', 27, 9, 1, '玛代人亚哈随鲁的儿子大利乌被立为王，统治迦勒底国的第一年，'),
('CNV', '但以理书', 27, 9, 2, '就是他作王的第一年，我但以理从经书上留意到主临到耶利米先知的话，指出耶路撒冷荒废的年数必满七十年。'),
('CNV', '但以理书', 27, 9, 3, '于是我转向主神，禁食，披麻蒙灰，藉祈祷和恳求寻求他。'),
('CNV', '但以理书', 27, 9, 4, '我向主我的神祷告、认罪，说：“主啊！伟大可畏的神，你向那些爱你（“你”原文作“他”），遵守你（“你”原文作“他”）诫命的人守约施慈爱。'),
('CNV', '但以理书', 27, 9, 5, '我们犯了罪，行了不义，作了恶，背叛了你，偏离了你的诫命典章；'),
('CNV', '但以理书', 27, 9, 6, '没有听从你的仆人众先知，他们奉你的名向我们的君王、领袖、列祖和国中所有的人民说话。'),
('CNV', '但以理书', 27, 9, 7, '主啊！你是公义的；我们满面羞愧，正如今日的光景；我们犹大人、耶路撒冷的居民，和被你赶逐到远近各地的以色列众人，都因对你不忠而满面羞愧。'),
('CNV', '但以理书', 27, 9, 8, '主啊！我们和我们的君王、领袖、列祖，都满面羞愧，因为我们得罪了你。'),
('CNV', '但以理书', 27, 9, 9, '虽然我们背叛了主我们的神，他仍是满有怜悯和饶恕。'),
('CNV', '但以理书', 27, 9, 10, '我们没有听从主我们神的话，没有遵行他藉着他的仆人众先知向我们颁布的律法。'),
('CNV', '但以理书', 27, 9, 11, '以色列众人都违背了你的律法，偏离了你，不听从你的话，因此，神的仆人摩西的律法书上所记载的咒诅和誓言，都倾倒在我们身上；我们实在得罪了神。'),
('CNV', '但以理书', 27, 9, 12, '他实现了他的预言，按着他向我们和那些治理我们的官长所说过的话，使大灾祸临到我们身上；耶路撒冷所遇的灾祸是在普天之下从未发生过的。'),
('CNV', '但以理书', 27, 9, 13, '这一切灾祸是按着摩西的律法书上所记载的，临到了我们身上，但我们仍没有恳求主我们的神施恩，使我们离开罪孽，明白你的真理。'),
('CNV', '但以理书', 27, 9, 14, '所以主留意使这灾祸临到我们身上，因为主我们的神在他所行的一切事上都是公义的，我们却没有听从他的话。'),
('CNV', '但以理书', 27, 9, 15, '主我们的神啊！你曾用强而有力的手把你的子民从埃及地领出来，使你自己得了名，好像今天一样。现在，我们犯了罪，作了恶。'),
('CNV', '但以理书', 27, 9, 16, '主啊！求你按着你的一切公义，使你的怒气和忿怒转离你的城耶路撒冷，就是你的圣山；因我们的罪和我们列祖的罪孽的缘故，耶路撒冷和你的子民成了在我们四围的人羞辱的对象。'),
('CNV', '但以理书', 27, 9, 17, '现在，我们的神啊！求你垂听你仆人的祷告和恳求；主啊！为了你自己的缘故，使你的脸光照你这荒凉了的圣所。'),
('CNV', '但以理书', 27, 9, 18, '我的神啊！求你侧耳而听，睁眼垂顾我们的荒凉，和那称为你名下的城；因为我们向你恳求，并不是因着自己的义，而是因着你的大怜悯。'),
('CNV', '但以理书', 27, 9, 19, '主啊！求你垂听。主啊！求你赦免。主啊！求你应允而行。我的神啊！为了你自己的缘故，求你不要耽延。因为你的城和你的子民都是称为你名下的。”'),
('CNV', '但以理书', 27, 9, 20, '我还在说话、祷告、承认我的罪和我同胞以色列人的罪，为我神的圣山，向主我的神恳求的时候；'),
('CNV', '但以理书', 27, 9, 21, '我还在祷告说话的时候，我先前在异象中所见的那位样貌像人的加百列，约在献晚祭的时候，快速地飞（“快速地飞”原文意思难确定，或译：“在精疲力竭时”）到我面前来。'),
('CNV', '但以理书', 27, 9, 22, '他向我解释，说：“但以理啊！现在我来，要使你有智慧，有聪明。'),
('CNV', '但以理书', 27, 9, 23, '你开始恳求的时候，就有命令发出。因为你是大蒙眷爱的，所以我来告诉你；你要留意这信息，明白这异象。'),
('CNV', '但以理书', 27, 9, 24, '“为你的同胞和你的圣城，已经定了七十个七，要结束过犯，终止罪恶，遮盖罪孽，引进永义，封住异象和预言，并且膏抹至圣所（“至圣所”或译：“至圣者”）。'),
('CNV', '但以理书', 27, 9, 25, '你要知道，也要明白，从发出命令恢复和重建耶路撒冷，直到受膏君的时候，必有七个七；又有六十二个七（“必有七个七；又有六十二个七”或译：“必有七个七和六十二个七”），耶路撒冷连广场和濠沟，都必重新建造起来；那是一段困苦的时期。'),
('CNV', '但以理书', 27, 9, 26, '六十二个七以后，受膏者必被剪除，一无所有（“一无所有”或译：“不再存在”）；那将要来的领袖的人民必毁灭这城和圣所。结局必像洪水而来；必有争战直到末了；荒凉的事已经定了。'),
('CNV', '但以理书', 27, 9, 27, '一七之内，他必和许多人坚立盟约；一七之半，他必使献祭和供物终止；他必在殿里（“殿里”原文作“翼上”）；设立那使地荒凉的可憎的像（“可憎的像”原文是复数），直到指定的结局倾倒在那造成荒凉的人身上。”'),
('CNV', '但以理书', 27, 10, 1, '波斯王古列第三年，有一个信息启示给那称为伯提沙撒的但以理。这信息是真的，是关于一场大战争；但以理明白这信息，了解这异象。'),
('CNV', '但以理书', 27, 10, 2, '那时，我但以理悲伤了三个星期。'),
('CNV', '但以理书', 27, 10, 3, '美味的食物我没有吃，肉和酒没有入我的口，我也没有用膏油抹身，整整三个星期。'),
('CNV', '但以理书', 27, 10, 4, '正月二十四日，我在底格里斯大河边的时候，'),
('CNV', '但以理书', 27, 10, 5, '我举目观看，看见有一个人身穿细麻衣，腰束乌法纯金的带。'),
('CNV', '但以理书', 27, 10, 6, '他的身像水苍玉，面貌像闪电的样子，眼睛像火把，手臂和腿像擦亮的铜那么闪耀，说话的声音像群众喊叫的声音。'),
('CNV', '但以理书', 27, 10, 7, '独有我但以理看见这异象，那些和我在一起的人都没有看见，不过他们却大大惊慌，逃跑躲藏起来了。'),
('CNV', '但以理书', 27, 10, 8, '因此，只有我一人留下来；我看见了这大异象，就全身无力，脸色大变，一点力气都没有。'),
('CNV', '但以理书', 27, 10, 9, '我却仍听见他说话的声音；我一听见他说话的声音，就沉睡了，脸伏在地。'),
('CNV', '但以理书', 27, 10, 10, '忽然有一只手按在我身上，使我用膝和手掌勉强支持着要站起来。'),
('CNV', '但以理书', 27, 10, 11, '他对我说：“大蒙眷爱的但以理啊！你应当留意我要对你说的话。你只管站起来，因为我现在奉差遣到你这里来。”他和我说这话的时候，我就战战兢兢地站起来。'),
('CNV', '但以理书', 27, 10, 12, '他又对我说：“但以理啊！不要惧怕，因为自从你第一天决心要明白这些事，又在你的神面前谦卑自己，你祷告的话已蒙垂听了；我就是因你祷告的话而来的。'),
('CNV', '但以理书', 27, 10, 13, '但波斯国的护卫天使拦阻我二十一天；后来有护卫天使长中的一位米迦勒来帮助我，我就留他在那里（按照《马索拉文本》，“我就留他在那里”应作“我就被留在那里”；现参照《七十士译本》翻译），和波斯众王在一起。'),
('CNV', '但以理书', 27, 10, 14, '现在我来是要使你明白日后所要发生在你的同胞身上的事，因为这异象是关于将来许多的年日的。”'),
('CNV', '但以理书', 27, 10, 15, '他和我说这些话的时候，我就脸伏在地，默默无声。'),
('CNV', '但以理书', 27, 10, 16, '忽然有一位像人的，摸我的嘴唇，我就开口和那站在我面前的交谈，说：“我主啊！因着这异象，我非常痛苦，毫无气力。'),
('CNV', '但以理书', 27, 10, 17, '我主的仆人怎能和我主说话呢？我现在全身无力，没有气息。”'),
('CNV', '但以理书', 27, 10, 18, '那位像人的再摸我，使我有力量。'),
('CNV', '但以理书', 27, 10, 19, '他说：“大蒙眷爱的人哪！不要惧怕，愿你平安，你要大大刚强。”他和我说话的时候，我就刚强起来；于是我说：“我主请说，因为你刚强了我。”'),
('CNV', '但以理书', 27, 10, 20, '他说：“现在我要回去和波斯的护卫天使作战；我一离去，希腊的护卫天使就要来。但你知道我为什么到你这里来吗？'),
('CNV', '但以理书', 27, 10, 21, '我来是要把那记录在真理书上的事告诉你。除了你们的护卫天使米迦勒之外，没有一个帮助我，和我一起抵挡他们。”'),
('CNV', '但以理书', 27, 11, 1, '“玛代人大利乌王第一年，我曾经起来帮助米迦勒，使他坚强。'),
('CNV', '但以理书', 27, 11, 2, '现在我要把真理告诉你。看哪！在波斯还有三个王要兴起；第四个王必非常富有，远超过所有的王；他因富足成为强盛以后，就必煽动众民攻击希腊国。'),
('CNV', '但以理书', 27, 11, 3, '后来必有一个英勇的王兴起，他必执掌大权，任意而行。'),
('CNV', '但以理书', 27, 11, 4, '他兴起的时候，他的国就破裂，向天的四方（“四方”原文作“四风”）分开，却不归给他的后代，国势也不及他掌权的时候；因为他的国必被拔出，归给他后代以外的人。'),
('CNV', '但以理书', 27, 11, 5, '“南方的王必强盛，他的将领中必有一个比他更强盛的，这人必掌权，他的权势很大。'),
('CNV', '但以理书', 27, 11, 6, '过了多年，南方王的女儿必到北方王那里去修好，他们必互相结盟。但这女子的势力必存留不住；王和他的势力也站立不住；她连同那些带她来的、那生她的，和那帮助她的，都被交出处死。'),
('CNV', '但以理书', 27, 11, 7, '但这女子的本家（“本家”原文作“根”）必另有一个儿子（“儿子”原文作“枝子”）兴起，继承父位；他必来攻击北方王的军队，进入北方王的堡垒，攻打他们，而且得胜。'),
('CNV', '但以理书', 27, 11, 8, '他又把他们的神像、铸成的偶像，连同金银的宝器，都一起掳掠到了埃及去。此后数年之久，他不再去攻击北方王。'),
('CNV', '但以理书', 27, 11, 9, '后来北方王必侵入南方王的国土，然后撤退归回本国。'),
('CNV', '但以理书', 27, 11, 10, '“北方王的众子必备战，招集大军；这大军前进，如洪水泛滥，横扫南方王的国土；之后他又再去争战，直到南方王的堡垒。'),
('CNV', '但以理书', 27, 11, 11, '南方王必发大怒，出来和北方王交战；北方王必摆列大军，但这大军必交在南方王的手里。'),
('CNV', '但以理书', 27, 11, 12, '这大军被扫除以后，南方王就心高气傲；他虽然使千万人倒毙，他的胜利却不能持久。'),
('CNV', '但以理书', 27, 11, 13, '北方王必再招聚大军，比先前的更多；时机成熟的时候（“时机成熟的时候”直译是“过了一些时候，一些年”），他就率领装备好了的大军而来。'),
('CNV', '但以理书', 27, 11, 14, '“那时，必有许多人起来攻击南方王，并且你同胞中的强暴人必挺身而起，要使那异象应验，但他们必失败。'),
('CNV', '但以理书', 27, 11, 15, '北方王必来，堆土筑垒攻取坚固城。南方的军力必抵挡不住，甚至精锐的部队也无力抵抗。'),
('CNV', '但以理书', 27, 11, 16, '那来攻击南方王的，必任意而行；没有人能在他面前站立得住；他必站在那荣美之地，手握毁坏之权。'),
('CNV', '但以理书', 27, 11, 17, '他决意倾全国的力量而来，但他先和南方王修好，把自己的女儿给南方王为妻，好毁灭南国；可是他的计划没有成功，他自己也得不到什么好处。'),
('CNV', '但以理书', 27, 11, 18, '后来他必转向沿海的岛屿，夺取了许多海岛。但有一个将领要制止他的骄横，并且使他的骄横归回他身上。'),
('CNV', '但以理书', 27, 11, 19, '于是他转向自己国中的堡垒，终于绊跌仆倒，不再存在了。'),
('CNV', '但以理书', 27, 11, 20, '“那时，必有一个人兴起来代替他；这人要派一个横征暴敛的人，为了王国的荣华，走遍全地；可是不多几日，这人就必被毁灭，不是因为忿怒，也不是因为战争。'),
('CNV', '但以理书', 27, 11, 21, '必另有一个卑鄙的人兴起来代替他；虽然人未曾把王国的尊荣给这人，这人却乘人不备的时候来到，用奉承的话夺得了王国。'),
('CNV', '但以理书', 27, 11, 22, '必有无数的军兵在他面前像洪水冲没，并且溃败；立约的君也必这样。'),
('CNV', '但以理书', 27, 11, 23, '他结盟以后，就必行诡诈；他虽然只有少数的国民，却渐渐强盛起来。'),
('CNV', '但以理书', 27, 11, 24, '他必乘人不备的时候，侵入省内最富庶的地区，行他列祖和他列祖的祖先所未曾行过的；他把掳掠之物和财物分给自己的部属；又必设下计谋攻打堡垒，只是这都是暂时的。'),
('CNV', '但以理书', 27, 11, 25, '他必竭尽己力，鼓起勇气，率领大军攻击南方王；南方王也必带领极强大的军队奋起还击，却抵挡不住，因为有人设下计谋陷害南方王。'),
('CNV', '但以理书', 27, 11, 26, '那些吃王膳的必毁灭他；他的军队必被冲没，受重伤而倒毙的很多。'),
('CNV', '但以理书', 27, 11, 27, '至于那两个王，他们都存心不良；他们同桌吃饭，也彼此说谎；他们的阴谋却不成功，因为要到了指定的时候，结局才会来到。'),
('CNV', '但以理书', 27, 11, 28, '“北方王必带着大批财物返回自己的国土去；他的心既然反对圣约，必任意而行，然后返回自己的国土去。'),
('CNV', '但以理书', 27, 11, 29, '“到了指定的时候，他必回来，再侵入南方的王国，不过这次的情况却不像前一次。'),
('CNV', '但以理书', 27, 11, 30, '因为基提的战船必来攻击他，他就丧胆而回；他又恼恨圣约，任意而行；他必回来，听取那些背弃圣约的人的建议。'),
('CNV', '但以理书', 27, 11, 31, '他的军队必起来，亵渎圣殿，就是那堡垒，废除常献祭，又在殿里设立了那使地荒凉的可憎的像。'),
('CNV', '但以理书', 27, 11, 32, '那些作恶违背圣约的人，他必用奉承的话败坏他们；但认识神的人民，必刚强行事。'),
('CNV', '但以理书', 27, 11, 33, '民中的智慧人必使许多人明白是非；但他们必有很多日子倒在刀剑之下，或被火烧，或被掳去，或被抢掠。'),
('CNV', '但以理书', 27, 11, 34, '他们仆倒的时候，必得到一些援助，必有许多人用奉承的话要和他们联盟。'),
('CNV', '但以理书', 27, 11, 35, '智慧人中有些仆倒的，为要锻炼他们，洁净他们，使他们成为雪白，直到末了，因为要到了指定的时候，结局才会来到。'),
('CNV', '但以理书', 27, 11, 36, '“那王必任意而行，自高自大，超过所有的神，又说一些怪诞的话攻击万神之神。他必行事顺利，直到神的忿怒完毕；因为所定的事必会实现。'),
('CNV', '但以理书', 27, 11, 37, '他必不尊重他列祖所拜的神，也不尊重妇女所爱慕的神，无论什么神他都不尊重，因为他必自大，高过一切。'),
('CNV', '但以理书', 27, 11, 38, '他倒要敬拜堡垒的神，用金银宝石和各样珍宝去敬拜他列祖所不认识的神。'),
('CNV', '但以理书', 27, 11, 39, '他必得着外族神的帮助，攻破坚固的堡垒；凡承认他的，他必使他们大得尊荣，又使他们管辖许多人，并且把土地分给他们作赏赐。'),
('CNV', '但以理书', 27, 11, 40, '“到了末期，南方王要和他交战；北方王必带着战车、骑兵和大批战船，像暴风一般来到他那里；他必侵入列国，如洪水泛滥，横扫而过。'),
('CNV', '但以理书', 27, 11, 41, '他也必侵入那荣美之地；必有许多国倾覆；但那些以东人、摩押人和亚扪人的首领，必被拯救脱离他的手。'),
('CNV', '但以理书', 27, 11, 42, '他必伸手攻击列国，埃及地也不能逃脱。'),
('CNV', '但以理书', 27, 11, 43, '他必掌管埃及的金银宝藏和一切珍宝；吕彼亚人和古实人都必追随他。'),
('CNV', '但以理书', 27, 11, 44, '但从东方和北方必有消息传来，使他惊惶，他就在烈怒之下出兵，要把许多人杀尽灭绝。'),
('CNV', '但以理书', 27, 11, 45, '他必在海和荣美的圣山之间支搭如宫殿一般的帐幕；然而他们的结局来到，必没有人能帮助他。”'),
('CNV', '但以理书', 27, 12, 1, '“那时保护你同胞的伟大护卫天使米迦勒必站起来；并且必有患难的时期，是立国以来直到那时未曾有过的。那时你的同胞中名字记录在册上的，都必得拯救。'),
('CNV', '但以理书', 27, 12, 2, '必有许多睡在尘土中的人醒过来，有的要得永生，有的要受羞辱，永远被憎恶。'),
('CNV', '但以理书', 27, 12, 3, '那些有智慧的必发光，好像穹苍的光体；那些使许多人归义的必发光，如同星星，直到永永远远。'),
('CNV', '但以理书', 27, 12, 4, '但以理啊！你要隐藏这些话，把这书密封，直到末期，必有许多人来往奔跑，知识增多。”'),
('CNV', '但以理书', 27, 12, 5, '我但以理观看，看见另有两个天使，一个站在河岸的这边，一个站在河岸的那边。'),
('CNV', '但以理书', 27, 12, 6, '有一个问那身穿细麻衣、站在河水以上的人，说：“这些奇异的事的结局几时才到呢？”'),
('CNV', '但以理书', 27, 12, 7, '我听见那身穿细麻衣、站在河水以上的人，向天举起左右手，指着活到永远的主起誓，说：“要经过一载、二载、半载（“一载、二载、半载”或译：“一个时期、多个时期、半个时期”）；在他们完全粉碎圣民的势力的时候，这一切事就都要完成。”'),
('CNV', '但以理书', 27, 12, 8, '我听见，却不明白，我就问：“我主啊，这些事的结局是怎样呢？”'),
('CNV', '但以理书', 27, 12, 9, '他回答：“但以理啊！你只管去吧，因为这些话已经隐藏密封，直到末期。'),
('CNV', '但以理书', 27, 12, 10, '许多人必洁净自己，使自己洁白，并且被熬炼。可是恶人仍然作恶。所有恶人都不明白，只有那些使人有智慧的才能明白。'),
('CNV', '但以理书', 27, 12, 11, '从废除常献祭，并设立那使地荒凉的可憎的像的时候起，必有一千二百九十天。'),
('CNV', '但以理书', 27, 12, 12, '等候到一千三百三十五日的，那人是有福的。'),
('CNV', '但以理书', 27, 12, 13, '你应去等待结局！你必安歇；到了末日，你必起来，承受你的分。”'),
('CNV', '何西阿书', 28, 1, 1, '犹大王乌西雅、约坦、亚哈斯、希西家在位的时候，也是约阿施的儿子以色列王耶罗波安执政的时候，主的话临到备利的儿子何西阿。'),
('CNV', '何西阿书', 28, 1, 2, '主初次藉着何西阿说话。主对何西阿说：“你去娶一个像娼妓一样的女人，生养像娼妓一样的儿女，因为这地盛行淫乱，离开了主。”'),
('CNV', '何西阿书', 28, 1, 3, '于是他就去娶了滴拉音的女儿歌玛。后来，她怀了孕，给他生了一个儿子。'),
('CNV', '何西阿书', 28, 1, 4, '主就对何西阿说：“给他起名叫耶斯列；因为不久我就要惩罚耶户家在耶斯列流人血的罪，我要灭绝以色列家的国。'),
('CNV', '何西阿书', 28, 1, 5, '“到那日，我要在耶斯列平原折断以色列的弓。”'),
('CNV', '何西阿书', 28, 1, 6, '后来，歌玛又怀孕，生了一个女儿。主对何西阿说：“给她起名叫罗．路哈玛（“罗‧路哈玛”意即“不蒙怜恤”）；因为我必不再怜恤以色列家，我决不赦免他们。'),
('CNV', '何西阿书', 28, 1, 7, '“但我要怜恤犹大家，使他们靠主他们的神得救。我要拯救他们，并不是靠弓、靠刀、靠战争，也不是靠战马、靠骑兵。”'),
('CNV', '何西阿书', 28, 1, 8, '罗．路哈玛断奶之后，歌玛又怀孕生了一个儿子。'),
('CNV', '何西阿书', 28, 1, 9, '主说：“给他起名叫罗．阿米（“罗‧阿米”意即“非我民”）；因为你们不是我的子民，我也不是你们的神。'),
('CNV', '何西阿书', 28, 1, 10, '“然而，以色列人的数目，必多如海边的沙，量不尽，数不完。从前在什么地方对他们说：‘你们不是我的子民’，将来要在那里对他们说：‘你们是永活的神的儿子。’'),
('CNV', '何西阿书', 28, 1, 11, '犹大人和以色列人要聚集在一起，为自己立一位首领，并离开那地上去，因为耶斯列的日子必为大日。”（本章第10~11节在《马索拉文本》为2:1~2）'),
('CNV', '何西阿书', 28, 2, 1, '“你们要对你们的兄弟说：‘我的子民’；要对你们的姊妹说：‘蒙怜悯的’。'),
('CNV', '何西阿书', 28, 2, 2, '要与你们的母亲争论，你们要争论，因为她不是我的妻子，我也不是她的丈夫；好让她除掉脸上的淫相，和乳间的淫态，'),
('CNV', '何西阿书', 28, 2, 3, '免得我把她剥光，赤身露体，使她像刚生下来的那天一样；又使她像旷野，像无水的旱地一般，叫她因干渴而死。'),
('CNV', '何西阿书', 28, 2, 4, '我必不怜恤她的儿子，因为他们是像娼妓的儿女；'),
('CNV', '何西阿书', 28, 2, 5, '因为他们的母亲卖了淫，怀他们的作了羞耻的事；因为她曾说：‘我要跟随我那些爱人。我的饼和水，羊毛和麻布，油和我所喝的，都是他们给的。’'),
('CNV', '何西阿书', 28, 2, 6, '因此，我要用荆棘堵塞她的通道，我要筑墙围住她，使她找不着出路。'),
('CNV', '何西阿书', 28, 2, 7, '她要追赶她那些爱人，却追不上；要寻找他们，却找不着。她就说：‘我要回去，回到前夫那里，因为从前比现在好得多了。’'),
('CNV', '何西阿书', 28, 2, 8, '其实她不知道，是我把五谷、新酒、橄榄油赐给了她；甚至他们用来制造巴力的金银，也是我大量给她的；'),
('CNV', '何西阿书', 28, 2, 9, '因此，到了收割的时候，到了出酒的季节，我必收回五谷和新酒；用来给她遮蔽裸体的羊毛和麻布，我也必夺回。'),
('CNV', '何西阿书', 28, 2, 10, '那时，我要在她那些爱人眼前，暴露她的下体；也没有人能救她脱离我的手。'),
('CNV', '何西阿书', 28, 2, 11, '我必使她的一切欢乐、节期、新月、安息日，或任何盛会都终止。'),
('CNV', '何西阿书', 28, 2, 12, '我必毁坏她的葡萄树和无花果树，就是她曾说：‘这是我作妓女所赚的，是我那些爱人给我的。’我必使这些果树成为荒林，任由田野的走兽吃掉。'),
('CNV', '何西阿书', 28, 2, 13, '她在拜众巴力的日子，向他们烧香，佩戴耳环首饰，打扮自己，跟随她那些爱人，却把我遗忘，所以我必惩罚她。”这是主说的。'),
('CNV', '何西阿书', 28, 2, 14, '“因此，我要诱导她，领她到旷野，对她说安慰的话。'),
('CNV', '何西阿书', 28, 2, 15, '在那里我要把葡萄园归还给她，使亚割谷变成‘希望之门’。她必在那里回应，像她少年的时候一样，也像她从埃及地上来的那天一般。”'),
('CNV', '何西阿书', 28, 2, 16, '主说：“到那日，你必称呼我‘伊施’（“伊施”意即“我夫”），不再称呼我‘巴力’（“巴力”意即“我主”）。'),
('CNV', '何西阿书', 28, 2, 17, '我要把‘巴力’的名字从她口中除掉；他们的名字没有人再提起。'),
('CNV', '何西阿书', 28, 2, 18, '到那日，为了他们，我必和田野的走兽、空中的飞鸟、地上爬行的动物立约；我必从这地折断弓弩、刀剑和兵器（“兵器”原文作“战争”）；使他们安然居住。'),
('CNV', '何西阿书', 28, 2, 19, '我必聘你永远归我，以公义、正直、忠信和怜悯聘你归我。'),
('CNV', '何西阿书', 28, 2, 20, '我必以信实聘你归我；这样，你就必认识主。”'),
('CNV', '何西阿书', 28, 2, 21, '主说：“到那日，我必应允，我必应允天，天必应允地，'),
('CNV', '何西阿书', 28, 2, 22, '地必应允五谷、新酒和油。这些必应允耶斯列（“耶斯列”意即“栽种”）。'),
('CNV', '何西阿书', 28, 2, 23, '我必为了自己把她栽种在这地。我必怜恤罗‧路哈玛（“罗‧路哈玛”意即“不蒙怜恤”）。我必对罗‧阿米（“罗‧阿米”意即“非我民”）说：‘你是我的子民’，他必说：‘你是我的神。’”'),
('CNV', '何西阿书', 28, 3, 1, '主对我说：“你再去爱一个妇人，这妇人是为情人所爱，又是个淫妇，就像主爱以色列人，虽然他们转去跟随别神，喜爱葡萄饼。”'),
('CNV', '何西阿书', 28, 3, 2, '于是，我用一百七十一克银子，一百五十公斤大麦，买她回来归我。'),
('CNV', '何西阿书', 28, 3, 3, '我对她说：“你要给我独居多日，不要行淫，不要有别的男人，我也必不与你同房。”'),
('CNV', '何西阿书', 28, 3, 4, '因为以色列人也要独居多日；没有君王，没有领袖，没有祭祀，没有柱像，没有以弗得，也没有家中的神像。'),
('CNV', '何西阿书', 28, 3, 5, '后来以色列人必归回，寻求主他们的神，寻求大卫他们的王。在末后的日子，他们必战战兢兢来到主那里，接受他的恩惠。'),
('CNV', '何西阿书', 28, 4, 1, '以色列人哪！你们要听主的话。主要与这地的居民争辩，因为在这地上没有诚实，没有慈爱，也没有认识神的知识；'),
('CNV', '何西阿书', 28, 4, 2, '只有起假誓、撒谎、残杀、偷盗、奸淫、行强暴，以至流人血事件相继而来。'),
('CNV', '何西阿书', 28, 4, 3, '因此，这地必悲哀，地上所有的居民、田野的走兽、空中的飞鸟都必衰微、枯萎，连海里的鱼也要灭亡。'),
('CNV', '何西阿书', 28, 4, 4, '虽然这样，人人都不必争论，不要彼此指责。你的民像争辩的祭司一样。'),
('CNV', '何西阿书', 28, 4, 5, '白天你要跌倒，晚上先知也必与你一同跌倒；我要毁灭你的母亲。'),
('CNV', '何西阿书', 28, 4, 6, '我的子民因无知识而灭亡；因为你拒绝了知识，我必拒绝你，不让你作我的祭司；因为你忘掉了你神的律法，我也必忘记你的子孙。'),
('CNV', '何西阿书', 28, 4, 7, '祭司越增多，就越发得罪我，我必把他们的尊荣变为耻辱。'),
('CNV', '何西阿书', 28, 4, 8, '他们藉着我的子民犯罪来养活自己，渴望他们多有罪孽。'),
('CNV', '何西阿书', 28, 4, 9, '所以，祭司怎样，人民也怎样。我必按他们的行为惩罚他们，照他们的行为报应他们。'),
('CNV', '何西阿书', 28, 4, 10, '他们吃，却吃不饱；行淫，人数却不会增多；因为他们离弃了主，不遵守他的命令。'),
('CNV', '何西阿书', 28, 4, 11, '淫行、酒和新酒，把人的心夺走了。'),
('CNV', '何西阿书', 28, 4, 12, '我的子民求问木头，由木杖引导他们，因为淫荡的灵使他们走迷了路，他们就行淫不顺从神。'),
('CNV', '何西阿书', 28, 4, 13, '他们在山顶上献祭，在冈陵上的橡树、杨树和栗树之下献祭烧香，因为树荫美好。所以你们的女儿行淫乱，你们的儿媳犯奸淫。'),
('CNV', '何西阿书', 28, 4, 14, '我却不因你们的女儿行淫乱，也不因你们的儿媳犯奸淫而惩罚她们，因为你们男人自己离群与娼妓在一起，又与庙妓一同献祭。这无知的人民必遭毁灭。'),
('CNV', '何西阿书', 28, 4, 15, '以色列啊！你虽然行淫，犹大却不可犯罪，不要往吉甲去，不要上到伯．亚文，也不要指着永活的主起誓。'),
('CNV', '何西阿书', 28, 4, 16, '以色列倔强，好像倔强的母牛，现在主怎样牧放他们，好像牧放宽阔草场上的羊羔呢？'),
('CNV', '何西阿书', 28, 4, 17, '以法莲和偶像连在一起，任凭他吧！'),
('CNV', '何西阿书', 28, 4, 18, '他们醉意全消以后，就不断行淫；他们的官长最喜爱耻辱的事。'),
('CNV', '何西阿书', 28, 4, 19, '风要把他们裹在翅膀里卷去，他们必因自己所献的祭祀而蒙受羞辱。'),
('CNV', '何西阿书', 28, 5, 1, '祭司啊，你们要听这话！以色列家啊，你们要留心听！王的家啊，你们要侧耳而听！因为审判必临到你们，因你们曾是米斯巴地的捕鸟机，是他泊山上张开的网罗。'),
('CNV', '何西阿书', 28, 5, 2, '他们在什亭掘深了陷阱，但我要惩治他们所有的人。'),
('CNV', '何西阿书', 28, 5, 3, '我认识以法莲，以色列也瞒不住我；以法莲啊！现在你竟行淫，以色列竟玷污了自己。'),
('CNV', '何西阿书', 28, 5, 4, '他们所行的使他们不能回转，归回自己的神；因为在他们当中有淫乱的灵；他们也不认识主。'),
('CNV', '何西阿书', 28, 5, 5, '以色列的骄傲当面指证自己，以色列和以法莲因自己的罪孽跌倒，犹大也与他们一同跌倒。'),
('CNV', '何西阿书', 28, 5, 6, '虽然他们带着牛群羊群去寻求主，却寻不见；他已经离开他们远去了。'),
('CNV', '何西阿书', 28, 5, 7, '他们以诡诈待主，因为他们生了私生子。现在新月要吞灭他们和他们的地业。'),
('CNV', '何西阿书', 28, 5, 8, '你们要在基比亚吹角，在拉玛吹号，在伯．亚文大声吶喊：“便雅悯啊！敌人就在你背后。”'),
('CNV', '何西阿书', 28, 5, 9, '在责罚的日子，以法莲必成为荒场。我要在以色列各支派中宣告一定会发生的事情。'),
('CNV', '何西阿书', 28, 5, 10, '“犹大的领袖，好像挪移地界的人，我要把我的忿怒倾倒在他们身上，如同倒水一样。'),
('CNV', '何西阿书', 28, 5, 11, '以法莲受欺压，被审判压碎；因为他们乐意随从人的命令。'),
('CNV', '何西阿书', 28, 5, 12, '因此我要成为以法莲的蛀虫，成为犹大家的朽烂。'),
('CNV', '何西阿书', 28, 5, 13, '以法莲看见自己的疾病，犹大家看见自己的创伤，以法莲就往亚述去，派人去见亚述的大王。可是他却不能医治你们，也不能医好你们的创伤。'),
('CNV', '何西阿书', 28, 5, 14, '因为我对以法莲要像只猛狮，对犹大家必像头少壮狮子。我要亲自撕裂他们，然后离去；我把他们带走，没有人能搭救。'),
('CNV', '何西阿书', 28, 5, 15, '我要回到自己的地方去；直到他们承认自己的罪过，寻求我的面。在痛苦中必恳切寻求我。”'),
('CNV', '何西阿书', 28, 6, 1, '“来吧！让我们回转归向主；因为，他虽然撕裂了我们，但必定医治我们；他虽然击伤了我们，却必替我们裹伤。'),
('CNV', '何西阿书', 28, 6, 2, '两天以后，他要使我们复原；第三天，他使我们起来，我们就可以活在他的面前。'),
('CNV', '何西阿书', 28, 6, 3, '让我们认识，竭力追求认识主。他必定出现，像晨光一样，他必临到我们，如雨水一般，又像滋润大地的春雨。'),
('CNV', '何西阿书', 28, 6, 4, '“以法莲啊！我要怎样待你呢？犹大啊，我要怎样待你呢？你们的爱心像早晨的云雾；又像瞬即消逝的朝露。'),
('CNV', '何西阿书', 28, 6, 5, '因此，我藉众先知砍碎他们，用我口中的话杀戮他们；我的审判必如光一般发出。'),
('CNV', '何西阿书', 28, 6, 6, '我喜爱怜恤，不喜爱祭祀；我喜爱人认识神的知识，胜过人献的燔祭。'),
('CNV', '何西阿书', 28, 6, 7, '可是他们却在亚当城背约，在那里向我行诡诈。'),
('CNV', '何西阿书', 28, 6, 8, '基列是作孽之人的城，他们的脚踪染满了血渍。'),
('CNV', '何西阿书', 28, 6, 9, '在往示剑的路上，祭司结党杀害人，就像埋伏路旁的强盗；他们行了邪恶的事。'),
('CNV', '何西阿书', 28, 6, 10, '在以色列家！我看见了可怕的事；那里有以法莲的淫行，以色列被玷污了。'),
('CNV', '何西阿书', 28, 6, 11, '犹大啊！我使我的子民归回的时候，必有为你定下的一个收割时期。”'),
('CNV', '何西阿书', 28, 7, 1, '“我医治以色列的时候，以法莲的罪孽，和撒玛利亚的罪恶就显露出来；因为他们行欺诈，小偷入屋偷窃，强盗在外抢劫。'),
('CNV', '何西阿书', 28, 7, 2, '他们心里并未想到，我记得他们的一切罪恶。他们所作的一切，现在都围绕他们，都在我面前。'),
('CNV', '何西阿书', 28, 7, 3, '他们以自己的恶行讨王欢喜，用自己的虚谎叫领袖快乐。'),
('CNV', '何西阿书', 28, 7, 4, '他们全是犯奸淫的，像一个被烤饼的人烧热的火炉，从抟面，直到全团发酵的时候，烤饼的人暂停使火发旺。'),
('CNV', '何西阿书', 28, 7, 5, '在我们王喜庆的日子，领袖们因酒的烈性而生病，王就与亵慢人联手。'),
('CNV', '何西阿书', 28, 7, 6, '他们阴谋埋伏的时候，心中烧得热如火炉。他们整夜抑制怒气，一到早晨，却像发出火焰的火燃烧起来。'),
('CNV', '何西阿书', 28, 7, 7, '所有的人都热如火炉，吞灭他们的官长。他们所有的君王都倒毙了，他们中间没有一人向我呼求。'),
('CNV', '何西阿书', 28, 7, 8, '“以法莲与外族混杂，以法莲是没有翻过的饼。'),
('CNV', '何西阿书', 28, 7, 9, '外族人吞吃了他的力量，他却不知道；他头上满是白发，他也不晓得。'),
('CNV', '何西阿书', 28, 7, 10, '虽然以色列的骄傲当面指证自己，他们却不回转归向主他们的神，也不因此寻求他。'),
('CNV', '何西阿书', 28, 7, 11, '以法莲好像一只愚蠢无知的鸽子。他们向埃及求助，投奔亚述。'),
('CNV', '何西阿书', 28, 7, 12, '但他们去的时候，我要把我的网撒在他们身上；我要把他们如同空中的飞鸟打下来。我要按着他们会众所听见的，惩罚他们。'),
('CNV', '何西阿书', 28, 7, 13, '他们有祸了，因为他们离弃了我；他们遭毁灭，因为他们背叛了我。我虽然想救赎他们，他们却对我说谎。'),
('CNV', '何西阿书', 28, 7, 14, '他们并没有真心向我呼求，只是在床上哀恸罢了。他们为了五谷和新酒割伤（“割伤”或译：“聚集”或“激发”）自己，仍然悖逆我。'),
('CNV', '何西阿书', 28, 7, 15, '我虽然锻炼他们的手臂，使它们有力，他们却图谋恶计攻击我。'),
('CNV', '何西阿书', 28, 7, 16, '他们转向巴力，成了不可靠的弓。他们的领袖因自己舌头上的狂傲倒在刀下，这在埃及地必成为被人讥笑的对象。”'),
('CNV', '何西阿书', 28, 8, 1, '“你要把号角放在你的嘴上，敌人如鹰一般来攻击主的家；因为他们违背了我的约，干犯了我的律法。'),
('CNV', '何西阿书', 28, 8, 2, '他们必向我哀求：‘我的神啊！我们以色列认识你。’'),
('CNV', '何西阿书', 28, 8, 3, '以色列弃绝了良善，所以仇敌必追赶他。'),
('CNV', '何西阿书', 28, 8, 4, '“他们立了君王，却不是出于我；他们立了首领，我却不知道。他们用自己的金银为自己做了偶像，以致他们被剪除。'),
('CNV', '何西阿书', 28, 8, 5, '撒玛利亚啊！我要除掉你的牛犊，我的怒气要向撒玛利亚人发作，他们要到几时才能无罪免罚呢？'),
('CNV', '何西阿书', 28, 8, 6, '这牛犊是出于以色列，是匠人所做的，它并不是神，撒玛利亚的牛犊必被粉碎。'),
('CNV', '何西阿书', 28, 8, 7, '他们播种的是风，收成的是暴风。生出来的苗没有麦穗，不能做成面粉；即或做成面粉，也必被别国的人吞吃。'),
('CNV', '何西阿书', 28, 8, 8, '以色列被吞吃，如今在万国中，好像没有人喜悦的器皿。'),
('CNV', '何西阿书', 28, 8, 9, '他们上去投奔亚述，像一只独行的野驴，以法莲贿买爱人。'),
('CNV', '何西阿书', 28, 8, 10, '他们虽然在列国中贿买人，我现在却要招聚他们。他们因着君王和领袖所加的重担，逐渐衰微。'),
('CNV', '何西阿书', 28, 8, 11, '以法莲增添好些祭坛去犯罪，这些就成了他们犯罪的祭坛。'),
('CNV', '何西阿书', 28, 8, 12, '我虽然为他们写了律法万条，他们却看作是为外族人写的，与他们毫无关系一般。'),
('CNV', '何西阿书', 28, 8, 13, '他们喜爱献祭，献肉为祭，又拿来吃；主却不喜悦他们。他必记得他们的罪孽，追讨他们的罪恶；他们必回到埃及去。'),
('CNV', '何西阿书', 28, 8, 14, '以色列忘记了造他的主，建造了很多宫殿；犹大也增添了很多坚固城。我却要降火在他的众城中，吞灭他的堡垒。”'),
('CNV', '何西阿书', 28, 9, 1, '以色列啊！不要欢喜；不要像外族人一样快乐，因为你行了邪淫，离开你的神，在各打谷场上喜爱卖淫的赏赐。'),
('CNV', '何西阿书', 28, 9, 2, '打谷场和榨酒池不能喂养他们，新酒也必使他们失望。'),
('CNV', '何西阿书', 28, 9, 3, '他们必不得住在主之地；以法莲要回到埃及去，要在亚述吃不洁之物。'),
('CNV', '何西阿书', 28, 9, 4, '他们必不得向主奠酒，他们的祭物也不能使他喜悦。他们的饼好像丧家的饼，凡吃这饼的，都必被玷污；因为他们的饼只可自己吃，不可带进主的殿。'),
('CNV', '何西阿书', 28, 9, 5, '那么，在规定集会的日子和主节期的时候，你们能作什么？'),
('CNV', '何西阿书', 28, 9, 6, '看哪！即使他们从毁灭中逃去，埃及要收殓他们，摩弗要埋葬他们。他们珍贵的银器必为蒺藜所占有，他们的帐棚必长满荆棘。'),
('CNV', '何西阿书', 28, 9, 7, '惩罚的日子临近，报应的时候来到，以色列必定知道，因着你们众多的罪孽和深仇大恨，先知被看为愚昧，受灵感动的人被当作疯子。'),
('CNV', '何西阿书', 28, 9, 8, '先知与神一同作以法莲的守望者，在他所行的一切路上，都满有捕鸟人的网罗，在他神的家中只有仇恨。'),
('CNV', '何西阿书', 28, 9, 9, '以法莲深深败坏，如同在基比亚的日子一般。神必记得他们的罪孽，惩罚他们的罪恶。'),
('CNV', '何西阿书', 28, 9, 10, '“我遇见以色列，好像在旷野里遇见葡萄。我看见你们的列祖，像看见无花果树初熟的果子。他们却来到巴力．毗珥，专作羞耻的事，成为可憎恶的，像他们所爱的偶像一样。'),
('CNV', '何西阿书', 28, 9, 11, '至于以法莲，他们的荣耀必如鸟儿飞逝；没有生育，没有怀胎，没有成孕。'),
('CNV', '何西阿书', 28, 9, 12, '即使他们把儿女养大，我也必使他们丧子，一个不留。我离弃他们的时候，他们就有祸了。”'),
('CNV', '何西阿书', 28, 9, 13, '在我看来，以法莲的儿女注定被当作猎物；以法莲要把自己的儿女带出来，交给施行杀戮的人。'),
('CNV', '何西阿书', 28, 9, 14, '主啊，求你赐给他们；你要赐给他们什么呢？求你使他们坠胎小产，乳房萎缩。'),
('CNV', '何西阿书', 28, 9, 15, '“他们的一切罪恶都在吉甲，我在那里憎恨他们，因他们的恶行，我要把他们从我的家里赶出来；我不再爱他们，他们的领袖都是叛徒。'),
('CNV', '何西阿书', 28, 9, 16, '以法莲被击打，他们的根枯干了，必不能再结果子。即使他们生产，我必杀死他们所生的爱子。”'),
('CNV', '何西阿书', 28, 9, 17, '我的神必弃绝他们，因为他们不听从他；他们必在列国中飘流。'),
('CNV', '何西阿书', 28, 10, 1, '以色列最茂盛的葡萄树，自己能结果子。他的果子越多，他就越增添祭坛；他的土地越肥美，他就使柱像越美丽。'),
('CNV', '何西阿书', 28, 10, 2, '他们心怀诡诈，现在要承担这罪的惩罚。主必拆毁他们的祭坛，毁坏他们的柱像。'),
('CNV', '何西阿书', 28, 10, 3, '那时他们必说：“我们没有君王，因为我们不敬畏主。至于君王，他能为我们作什么呢？”'),
('CNV', '何西阿书', 28, 10, 4, '他们说很多话，起假誓，又立盟约；所以审判像毒草一般在田间的犁沟中生长起来。'),
('CNV', '何西阿书', 28, 10, 5, '撒玛利亚的居民必因伯．亚文的牛犊而惧怕；拜牛犊的人民必为它哀恸。拜牛犊的祭司必为它哀号，都因它的荣耀离开它而被掳去了。'),
('CNV', '何西阿书', 28, 10, 6, '人要把它带到亚述去，作贡物献给那里的大王。以法莲必受羞辱，以色列必因自己的计谋蒙羞。'),
('CNV', '何西阿书', 28, 10, 7, '至于撒玛利亚，她与她的君王必被剪除；好像浮在水面的枯枝一般。'),
('CNV', '何西阿书', 28, 10, 8, '伯．亚文的邱坛，就是以色列的罪恶，都要被拆毁；荆棘和蒺藜必在他们的祭坛上面长起来。那时人要对大山说：“遮盖我们！”对小山说：“倒在我们身上！”'),
('CNV', '何西阿书', 28, 10, 9, '以色列啊！从基比亚的日子以来，你就犯罪，他们仍然留在那里，难道攻击恶人的战祸不能在基比亚赶上他们吗？'),
('CNV', '何西阿书', 28, 10, 10, '我必来惩罚他们；他们被自己那双重的罪孽捆绑的时候，列国就集结起来攻击他们。'),
('CNV', '何西阿书', 28, 10, 11, '以法莲是一头驯服的母牛犊，喜爱踹谷；我却要把轭扣在它肥美的颈项上，我要使以法莲拖犁；犹大要耕田，雅各必为自己耙地。'),
('CNV', '何西阿书', 28, 10, 12, '你们要为自己撒种公义，就能收割慈爱的果子，你们要翻松荒地。现在是寻求主的时候，直等到他来，降下公义的雨在你们身上。'),
('CNV', '何西阿书', 28, 10, 13, '你们耕种奸恶，收割不义，自吃谎言的果子；因为你倚靠自己的能力和众多的勇士。'),
('CNV', '何西阿书', 28, 10, 14, '所以必有哄嚷之声攻击你的众民，你的一切城堡都必被毁坏，正如沙勒幔在争战的日子毁坏伯．亚比勒一般，有母亲与儿女一同在那里被摔死。'),
('CNV', '何西阿书', 28, 10, 15, '伯特利啊，因你们的罪大恶极，我必这样待你们。在风暴中，以色列的王必全然被除灭。'),
('CNV', '何西阿书', 28, 11, 1, '“以色列年幼的时候，我就爱他。我从埃及召我的儿子出来。'),
('CNV', '何西阿书', 28, 11, 2, '可是我越发呼唤他们，他们越发走开；他们给巴力献祭，向偶像烧香。'),
('CNV', '何西阿书', 28, 11, 3, '然而是我教导以法莲走路的；我用双臂抱他们，他们却不知道是我医治了他们。'),
('CNV', '何西阿书', 28, 11, 4, '我用慈绳爱索（“慈绳爱索”原文意思不易肯定，或作“人的绳子、爱的绳索”或“皮制的绳索”）牵引他们，我待他们像人拉高牛的轭在两颚之上，又向他们俯身，喂养他们。'),
('CNV', '何西阿书', 28, 11, 5, '“他们必返回埃及地（“他们必返回埃及地”或译：“难道他们不会返回埃及地吗？”），亚述要作他们的王；因为他们不肯回来归我。'),
('CNV', '何西阿书', 28, 11, 6, '刀剑必在他们的城中飞舞，毁坏他们的门闩，因着他们自己的计谋，吞灭他们。'),
('CNV', '何西阿书', 28, 11, 7, '我的子民决要背道离开我，他们因着所负的轭而呼求，却没有人给他们卸下。'),
('CNV', '何西阿书', 28, 11, 8, '“以法莲啊，我怎能舍弃你！以色列啊，我怎能把你交出来！我怎能对你如同押玛，待你好像洗扁呢！我的心肠翻转，我的怜悯发动。'),
('CNV', '何西阿书', 28, 11, 9, '我必不让我的烈怒发作，必不再毁灭以法莲；因为我是神，不是世人；我是你们中间的圣者，必不会含怒而来。'),
('CNV', '何西阿书', 28, 11, 10, '他们必跟随主；主要像狮子吼叫；他一吼叫，他们就从西方战战兢兢而来。'),
('CNV', '何西阿书', 28, 11, 11, '他们必战战兢兢而来，像从埃及赶来的飞鸟，如从亚述地赶来的鸽子，我要使他们住在自己的房子里。这是主说的。'),
('CNV', '何西阿书', 28, 11, 12, '以法莲用虚谎，以色列家用诡诈包围着我；犹大还是与神对抗，就是对抗那可信可靠的至圣者。”（本节在《马索拉文本》为12:1）'),
('CNV', '何西阿书', 28, 12, 1, '“以法莲吃风，整天追赶东风，增添虚谎和强暴。他们与亚述结盟，又给埃及送油。”（本节在《马索拉文本》为12:2）'),
('CNV', '何西阿书', 28, 12, 2, '主与犹大争辩；他必照雅各所行的惩罚他，按他所作的报应他。'),
('CNV', '何西阿书', 28, 12, 3, '他在母腹中抓住他哥哥的脚跟，壮年的时候又与神角力。'),
('CNV', '何西阿书', 28, 12, 4, '他与天使角力，并且得胜；他哀哭，向他求恩。他在伯特利遇见神，神在那里对他说话。'),
('CNV', '何西阿书', 28, 12, 5, '主是万军的神，主是他的名号。'),
('CNV', '何西阿书', 28, 12, 6, '所以你要靠着你的神归回，谨守忠信和公平，常常等候你的神。'),
('CNV', '何西阿书', 28, 12, 7, '以色列是个商人，手里拿着诡诈的天平，喜爱欺压别人。'),
('CNV', '何西阿书', 28, 12, 8, '以法莲说：“我成了富翁，我为自己发了财；在我所有的收益中，人不能找出我有什么罪孽，可算为罪恶的。”'),
('CNV', '何西阿书', 28, 12, 9, '“自从你出埃及地以来，我就是主你的神；我必使你再住在帐棚里，像在节日的日子一样，'),
('CNV', '何西阿书', 28, 12, 10, '我曾对先知说话，加添许多异象；又藉先知说比喻。'),
('CNV', '何西阿书', 28, 12, 11, '在基列仍有罪孽，他们实在是没有价值的。他们在吉甲献牛犊为祭，他们的祭坛好像田间犁沟中的石堆。”'),
('CNV', '何西阿书', 28, 12, 12, '从前雅各逃到亚兰地，以色列为得妻子而作工，为得妻子而替人放羊。'),
('CNV', '何西阿书', 28, 12, 13, '后来，主藉着一位先知把以色列从埃及领上来，也藉着一位先知，以色列得蒙看顾。'),
('CNV', '何西阿书', 28, 12, 14, '以法莲大大地惹了主的烈怒，所以，他的主把他流人血的罪归到他身上，把他当受的羞辱归给他。'),
('CNV', '何西阿书', 28, 13, 1, '从前以法莲一说话，人都战兢。他原在以色列中居高位，但后来因事奉巴力犯了罪，就死了。'),
('CNV', '何西阿书', 28, 13, 2, '现在他们犯罪越来越多，为自己做铸像，按着自己的技巧，用自己的银子做偶像；这些都是匠人的手工。他们论到这些说：“向偶像献祭的人，可以亲吻牛犊。”'),
('CNV', '何西阿书', 28, 13, 3, '因此，他们必像早晨的云雾，又如易逝的朝露，又像打谷场上的糠秕被旋风吹去，又像烟气从烟囱上腾。'),
('CNV', '何西阿书', 28, 13, 4, '“自从你出埃及地以来，我就是主你的神。除我以外，你不可承认别的神；除我以外，再没有拯救者。'),
('CNV', '何西阿书', 28, 13, 5, '我曾在旷野，在干旱之地，认识你。'),
('CNV', '何西阿书', 28, 13, 6, '但他们得了喂养而饱足，饱足以后，就心高气傲，因此忘记了我。'),
('CNV', '何西阿书', 28, 13, 7, '所以我要像狮子临到他们，像豹子埋伏在路旁。'),
('CNV', '何西阿书', 28, 13, 8, '我要袭击他们，像一只失掉幼熊的母熊，撕裂他们的胸膛；在那里我必像一只母狮吞吃他们；野兽必撕裂他们。'),
('CNV', '何西阿书', 28, 13, 9, '“以色列啊，我要毁灭你，谁能帮助你呢（本节在《马索拉抄本》的意思不明确；现参照《七十士译本》和其他古译本翻译）？'),
('CNV', '何西阿书', 28, 13, 10, '现在你的王在哪里？让他拯救你吧！你所有的领袖在哪里？让他们治理你吧！因为论到他们你曾请求：‘把王和领袖赐给我。’'),
('CNV', '何西阿书', 28, 13, 11, '我在忿怒中把王赐给你，又在烈怒中把他废去。'),
('CNV', '何西阿书', 28, 13, 12, '以法莲的罪孽是封着的，他的罪恶贮藏起来。'),
('CNV', '何西阿书', 28, 13, 13, '生产的疼痛要临到他身上，他却是没有智慧的人，因为产期到了，他还迟延不破胎而出。'),
('CNV', '何西阿书', 28, 13, 14, '我要救赎他们脱离阴间的权势吗？救赎他们脱离死亡吗？死亡啊，你的灾害在哪里？阴间啊，你的毁灭在哪里？怜悯必从我眼前隐藏起来。'),
('CNV', '何西阿书', 28, 13, 15, '他虽然在芦苇中长得茂盛，但东风必要来到，主的风要从旷野上来，他的水泉就干涸，他的泉源就枯竭。他所贮藏的一切珍贵器皿，都被掠夺去了。'),
('CNV', '何西阿书', 28, 13, 16, '撒玛利亚必承担自己罪的刑罚，因为他背叛了他的神。他们必倒在刀下。他们的婴孩被摔死，他们的孕妇必被剖开肚腹。”（本节在《马索拉文本》为14:1）'),
('CNV', '何西阿书', 28, 14, 1, '以色列啊，回转吧！回到主你的神那里，因为你是因自己的罪孽跌倒的。（本节在《马索拉文本》为14:2）'),
('CNV', '何西阿书', 28, 14, 2, '你们预备好要说的话，归向主，对他说：“除去我们一切罪孽，悦纳我们的祷告。这样我们就把嘴唇的果子献上。'),
('CNV', '何西阿书', 28, 14, 3, '亚述不能救我们，我们必不再骑马；我们亲手所做的，我们必不再称为‘我们的神’；因为在你那里，孤儿才得着怜悯。”'),
('CNV', '何西阿书', 28, 14, 4, '“我必医治他们背道的病，甘心乐意爱他们，因为我的怒气已经远离他们了。'),
('CNV', '何西阿书', 28, 14, 5, '我对以色列要像甘露，他必像百合花开放；他要扎根，如黎巴嫩的香柏树。'),
('CNV', '何西阿书', 28, 14, 6, '他的幼枝必伸展，他的荣美要像橄榄树，他的香气必如黎巴嫩的香柏树。'),
('CNV', '何西阿书', 28, 14, 7, '他们必再住在他的荫下，使五谷生长。他们必发旺像葡萄树，他们的名声要像黎巴嫩的酒。'),
('CNV', '何西阿书', 28, 14, 8, '以法莲与偶像还有什么关系呢？答允他的是我，看顾他的也是我。我像一棵青翠的松树，你的果子是从我而得。”'),
('CNV', '何西阿书', 28, 14, 9, '谁是智慧人，让他明白这些事吧！谁是有见识的人，让他领会这一切吧！因为主的道路是正直的，义人要行在其中，恶人却必在其上绊倒。'),
('CNV', '约珥书', 29, 1, 1, '主的话临到毗土珥的儿子约珥：'),
('CNV', '约珥书', 29, 1, 2, '老年人哪！你们要听这话。这地所有的居民啊！你们要留心听。在你们的日子，或在你们祖先的日子，曾有这样的事吗？'),
('CNV', '约珥书', 29, 1, 3, '你们要把这事传与子，子传与孙，孙传与后代。'),
('CNV', '约珥书', 29, 1, 4, '剪虫剩下的，蝗虫吃了；蝗虫剩下的，蝻子吃了；蝻子剩下的，蚂蚱吃了。'),
('CNV', '约珥书', 29, 1, 5, '酒醉的人哪！你们要醒过来；要哀哭！所有嗜酒的人哪！你们都要为甜酒哀号，因为甜酒从你们的口里断绝了。'),
('CNV', '约珥书', 29, 1, 6, '因为有一民族上来侵犯我的国土，他们强大又无数；他们的牙齿像狮子的牙齿，他们有母狮的大牙。'),
('CNV', '约珥书', 29, 1, 7, '他们使我的葡萄树荒凉，折断了我的无花果树，把树皮剥尽，丢在一旁，使枝条露白。'),
('CNV', '约珥书', 29, 1, 8, '你们要哀号，像少女腰束麻布，为她幼年时许配的丈夫哀号一样。'),
('CNV', '约珥书', 29, 1, 9, '素祭和奠祭都从主的殿里断绝了，事奉主的祭司也都悲哀。'),
('CNV', '约珥书', 29, 1, 10, '田野荒废，土地凄凉，因为五谷毁坏，新酒干竭，油也缺乏。'),
('CNV', '约珥书', 29, 1, 11, '农夫啊！你们要为大麦和小麦羞愧。修理葡萄园的啊！你们要哀号，因为田间的庄稼都破坏了。'),
('CNV', '约珥书', 29, 1, 12, '葡萄树枯干，无花果树衰残；石榴树、棕树、苹果树，田野所有的树木都枯干，因此欢乐从人间消失了。'),
('CNV', '约珥书', 29, 1, 13, '祭司啊！你们要腰束麻布，并且痛哭。在祭坛侍候的啊！你们要哀号。事奉我的神的啊！你们披上麻布进去过夜吧，因为素祭和奠祭，都从你们的神的殿中止息了。'),
('CNV', '约珥书', 29, 1, 14, '你们要把禁食的日子分别为圣，召开严肃会，聚集众长老和国中所有的居民，到你们的神主的殿里，向主呼求。'),
('CNV', '约珥书', 29, 1, 15, '哀哉那日！因为主的日子临近了；那日来到，好像毁灭从全能者临到一样。'),
('CNV', '约珥书', 29, 1, 16, '粮食不是在我们的眼前断绝了吗？欢喜与快乐不是从我们的神的殿中止息了吗？'),
('CNV', '约珥书', 29, 1, 17, '谷种在土块底下朽烂，仓库荒凉，谷仓破烂被拆毁，因为五谷都枯干了。'),
('CNV', '约珥书', 29, 1, 18, '牲畜发出哀鸣，牛群到处流荡，因为没有草场给它们，羊群也同样受苦。'),
('CNV', '约珥书', 29, 1, 19, '主啊！我向你呼求，因为火吞灭了旷野的草场，火焰烧尽了田间所有的树木。'),
('CNV', '约珥书', 29, 1, 20, '田野的走兽也向你发喘，因为溪水都干涸了，火吞灭了旷野的草场。'),
('CNV', '约珥书', 29, 2, 1, '你们要在锡安吹号，并在我的圣山发出警讯，让国中所有的居民都战栗，因为主的日子快到，必然临近了。'),
('CNV', '约珥书', 29, 2, 2, '那日是黑暗幽冥的日子，是密云漆黑的日子。有一队众多强盛的民来到，好像晨光满布群山；这样的事从前没有发生过，以后直到万代，也不会发生。'),
('CNV', '约珥书', 29, 2, 3, '在他们前面有吞灭的火，在他们后面有燃烧的火焰；他们未到以前，大地像伊甸园，他们过去以后，大地成了荒凉的旷野，没有一样能逃避他们的。'),
('CNV', '约珥书', 29, 2, 4, '他们的形状像马的形状，战马怎样奔跑，他们也怎样奔跑。'),
('CNV', '约珥书', 29, 2, 5, '他们在群山顶上跳跃的声音，如战车的响声，又如火焰吞灭碎秸的响声，像强盛的民摆阵预备作战。'),
('CNV', '约珥书', 29, 2, 6, '在他们面前，万民苦恼，人人脸红耳赤。'),
('CNV', '约珥书', 29, 2, 7, '他们奔跑像勇士，又像战士爬上城墙；他们各按自己的路前行，并不偏离路线。'),
('CNV', '约珥书', 29, 2, 8, '他们彼此不拥挤，各按自己的道前行；甚至他们持着兵器跌倒，也不会被剪除。'),
('CNV', '约珥书', 29, 2, 9, '他们冲入城镇，奔上城墙，爬进房屋，像盗贼一样从窗户爬进去。'),
('CNV', '约珥书', 29, 2, 10, '在他们面前，大地震动，诸天摇撼，日月昏暗，星星无光。'),
('CNV', '约珥书', 29, 2, 11, '主在他的军队前头发出声音；他的队伍极大，成就他话语的，是强盛的人。主的日子伟大，非常可畏，谁能忍受得住呢？'),
('CNV', '约珥书', 29, 2, 12, '主说：“现在虽然如此，你们仍要全心全意，以禁食、哭泣、哀号，归向我。”'),
('CNV', '约珥书', 29, 2, 13, '你们要撕裂你们的心肠，不要撕裂你们的衣服。并要归向主你们的神，因为他有恩典有怜悯，不轻易发怒，并且有丰盛的慈爱，随时转意不降灾祸。'),
('CNV', '约珥书', 29, 2, 14, '有谁知道或许他会转意，并且施慈爱，留下余福，就是留下献给主你们的神的素祭和奠祭。'),
('CNV', '约珥书', 29, 2, 15, '你们要在锡安吹号角，把禁食的日子分别为圣，召开严肃会。'),
('CNV', '约珥书', 29, 2, 16, '你们要召集民众，使会众分别为圣；招聚老人，聚集孩童，和在怀中吃奶的婴孩；让新郎从新房出来，新妇从内室出来。'),
('CNV', '约珥书', 29, 2, 17, '让事奉主的祭司在圣殿的廊子和祭坛之间哭泣，让他们说：“主啊！求你怜恤你的子民。不要使你的产业受羞辱，使他们在列国中成为笑谈。为什么容人在万民中讥笑说：‘他们的神在哪里呢？’”'),
('CNV', '约珥书', 29, 2, 18, '于是主为了自己的地发热心，怜恤他的子民。'),
('CNV', '约珥书', 29, 2, 19, '主应允他的子民，对他们说：“看哪！我必赐给你们五谷、新酒和新油，你们必吃得饱足，我必不再使你们成为列国中的羞辱。'),
('CNV', '约珥书', 29, 2, 20, '我要使北方来的军队远离你们；我要把他们驱逐到干旱荒凉之地，他们的前队赶入东海，他们的后队赶入西海；并且他们的臭气上升，他们的腥味上腾，因为主行了大事。'),
('CNV', '约珥书', 29, 2, 21, '地土啊！你不要惧怕；你要欢喜快乐，因为主行了大事。'),
('CNV', '约珥书', 29, 2, 22, '田野的走兽啊，你们不要惧怕，因为旷野的草场又发青了，树木又结果子了，无花果树和葡萄树也都效力了。'),
('CNV', '约珥书', 29, 2, 23, '锡安的人民哪！你们要欢喜，要靠主你们的神快乐，因为他赐给了你们合时的秋雨。他给你们降下时雨，就是秋雨春雨，像以前一样。'),
('CNV', '约珥书', 29, 2, 24, '禾场上必满了五谷；榨酒池与油醡必溢出新酒与新油。'),
('CNV', '约珥书', 29, 2, 25, '我差遣到你们中间去的，我的大军队，就是蝗虫、蝻子、蚂蚱和剪虫，在那些年间吃尽的，我必补给你们。'),
('CNV', '约珥书', 29, 2, 26, '你们必吃得丰富，并且饱足，你们就赞美主你们的神的名，因为他为你们行了奇妙的事。我的子民必永远不会羞愧。'),
('CNV', '约珥书', 29, 2, 27, '这样，你们必知道我是在以色列中间，又知道我是主你们的神，除了我再没有别的神。我的子民必永远不会羞愧。'),
('CNV', '约珥书', 29, 2, 28, '“以后，我要把我的灵浇灌所有的人。你们的儿女要说预言，你们的老年人要作异梦，你们的少年人要见异象。'),
('CNV', '约珥书', 29, 2, 29, '在那些日子，我也要把我的灵浇灌仆人和婢女。'),
('CNV', '约珥书', 29, 2, 30, '我要在天上地下显出神迹奇事，有血、有火、有烟柱。'),
('CNV', '约珥书', 29, 2, 31, '太阳将变为黑暗，月亮将变为血红。在主伟大可畏的日子临到以前，这一切都要发生。'),
('CNV', '约珥书', 29, 2, 32, '那时，求告主的名的，都必得救；因为正如主所说的，在锡安山和耶路撒冷必有得救的人，在劫后余生的人中，必有主所呼召的。”（本章第28~32节在《马索拉文本》为3:1~5）'),
('CNV', '约珥书', 29, 3, 1, '“看哪！到了那些日子，在那个时期，我使犹大和耶路撒冷被掳的人归回，（本节在《马索拉文本》为4:1）'),
('CNV', '约珥书', 29, 3, 2, '我必招聚列国，领他们下到约沙法谷，为了我的子民，就是我的产业以色列，我要在那里亲临审判他们，因为他们把我的子民分散在列国中，又分取了我的地土。'),
('CNV', '约珥书', 29, 3, 3, '他们为我的子民抽签，用男童交换妓女，女童被卖换酒喝。'),
('CNV', '约珥书', 29, 3, 4, '“推罗、西顿和非利士四境的人哪！你们想对我作什么呢？你们想向我报复吗？你们若向我报复，我很快就使报应归在你们的头上。'),
('CNV', '约珥书', 29, 3, 5, '你们拿去了我的金银，又把我的珍宝带进了你们的庙宇。'),
('CNV', '约珥书', 29, 3, 6, '你们把犹大人和耶路撒冷人卖给希腊人，使他们远离自己的境界。'),
('CNV', '约珥书', 29, 3, 7, '看哪！我要激动他们离开被你们卖到的地方，我也要使报应归到你们的头上。'),
('CNV', '约珥书', 29, 3, 8, '我必把你们的儿女卖在犹大人的手中，犹大人必把他们卖给远方示巴国的人，因为这是主说的。”'),
('CNV', '约珥书', 29, 3, 9, '你们要在列国中宣告以下这话：“你们要预备争战，要激动勇士。让所有的战士都近前来，让他们都上去攻击。'),
('CNV', '约珥书', 29, 3, 10, '要把犁头打成刀剑，把镰刀打成矛枪；软弱的要说：‘我是勇士。’'),
('CNV', '约珥书', 29, 3, 11, '四围的列国啊！你们快来帮助，在那里一同聚集。主啊！求你叫你的勇士下来吧。'),
('CNV', '约珥书', 29, 3, 12, '“万国都当奋起，上到约沙法谷去。因为我必坐在那里，审判四围的列国。'),
('CNV', '约珥书', 29, 3, 13, '你们要伸出镰刀，因为庄稼已经熟了。来践踏吧，因为压酒池满了，酒池盈溢，因为他们的罪恶极大。'),
('CNV', '约珥书', 29, 3, 14, '无数的人群齐集在判决谷，因为主的日子临近了判决谷。'),
('CNV', '约珥书', 29, 3, 15, '日月昏暗，星星无光。'),
('CNV', '约珥书', 29, 3, 16, '主从锡安吼叫，并从耶路撒冷发声，天地就震动。主却要作他子民的避难所，作以色列众子的保障。'),
('CNV', '约珥书', 29, 3, 17, '你们知道我是主你们的神，是住在锡安我的圣山上。那时，耶路撒冷必成为圣。外族人必不得从其中经过。'),
('CNV', '约珥书', 29, 3, 18, '到那日，大山都必滴下甜酒，小山都必流出奶，犹大的一切溪流，都必水流不息。必有泉源从主的殿里流出来，灌溉什亭谷。'),
('CNV', '约珥书', 29, 3, 19, '埃及将会荒凉，以东必变成凄凉的旷野，都因为他们向犹大人所行的强暴，又因为在他们的国中流了无辜人血。'),
('CNV', '约珥书', 29, 3, 20, '“但犹大必存到永远，耶路撒冷也必存到万代。'),
('CNV', '约珥书', 29, 3, 21, '现在我要追讨我还未有追讨的流人血的罪。主在锡安居住。”'),
('CNV', '阿摩司书', 30, 1, 1, '提哥亚的牧人阿摩司，在犹大王乌西雅和以色列王约阿施的儿子耶罗波安作王的日子，大地震前二年所见的异象，就是有关以色列的话，记在下面。'),
('CNV', '阿摩司书', 30, 1, 2, '他说：“主从锡安吼叫，从耶路撒冷发声；牧人的草场因此悲哀，迦密的山顶枯干。'),
('CNV', '阿摩司书', 30, 1, 3, '“主这样说：‘大马士革三番四次犯罪，我必不收回惩罚他的命令（“我必不收回惩罚他的命令”直译作“我必不扭转它”）；因为他用打谷的铁器蹂躏基列。'),
('CNV', '阿摩司书', 30, 1, 4, '我必降火在哈薛的王宫，烧毁便．哈达的堡垒。'),
('CNV', '阿摩司书', 30, 1, 5, '我必折断大马士革的门闩，剪除亚文平原的居民，以及伯．伊甸掌权的首领；亚兰的人民也必被掳至吉珥。’这是主说的。'),
('CNV', '阿摩司书', 30, 1, 6, '“主这样说：‘迦萨三番四次犯罪，我必不收回惩罚他的命令；因为他带走全部的俘虏，交给以东。'),
('CNV', '阿摩司书', 30, 1, 7, '我必降火在迦萨的城墙，烧毁他的堡垒；'),
('CNV', '阿摩司书', 30, 1, 8, '我必剪除亚实突的居民，以及亚实基伦掌权的领袖；我必伸手攻击以革伦，把余剩的非利士人都灭绝。’这是主神说的。'),
('CNV', '阿摩司书', 30, 1, 9, '“主这样说：‘推罗三番四次犯罪，我必不收回惩罚他的命令；因为他把全部的俘虏交给以东，并不记念与兄弟所立的盟约。'),
('CNV', '阿摩司书', 30, 1, 10, '我必降火在推罗的城墙，烧毁他的堡垒。’'),
('CNV', '阿摩司书', 30, 1, 11, '“主这样说：‘以东三番四次犯罪，我必不收回惩罚他的命令；因为他拿刀追杀他的兄弟，没有丝毫怜悯；他的怒气不断爆发，他的忿怒永不止息。'),
('CNV', '阿摩司书', 30, 1, 12, '我必降火在提幔，烧毁伯斯拉的堡垒。’'),
('CNV', '阿摩司书', 30, 1, 13, '“主这样说：‘亚扪三番四次犯罪，我必不收回惩罚他的命令；因为他为了扩张疆界，甚至剖开基列孕妇的肚腹。'),
('CNV', '阿摩司书', 30, 1, 14, '在战争之日的吶喊中，在风雨天的暴风中；我必在拉巴的城墙放火，烧毁他的堡垒。'),
('CNV', '阿摩司书', 30, 1, 15, '他的君王必被掳走，君王和官员一同被掳。’这是主说的。”'),
('CNV', '阿摩司书', 30, 2, 1, '“主这样说：‘摩押三番四次犯罪，我必不收回惩罚他的命令；因为他把以东王的骸骨焚烧成灰。'),
('CNV', '阿摩司书', 30, 2, 2, '我必降火在摩押，烧毁加略的堡垒；在扰攘、吶喊、吹角声中，摩押必被消灭。'),
('CNV', '阿摩司书', 30, 2, 3, '我必剪除他的掌权者，也把他所有的领袖一同杀死。’这是主说的。'),
('CNV', '阿摩司书', 30, 2, 4, '“主这样说：‘犹大三番四次犯罪，我必不收回惩罚他的命令；因为他弃绝主的律法，不遵守他的典章；反被他们列祖跟从的偶像，使他们走错了路。'),
('CNV', '阿摩司书', 30, 2, 5, '我必降火在犹大，烧毁耶路撒冷的堡垒。’'),
('CNV', '阿摩司书', 30, 2, 6, '“主这样说：‘以色列三番四次犯罪，我必不收回惩罚他的命令；因为他为了银子卖义人，为了一双鞋卖穷人。'),
('CNV', '阿摩司书', 30, 2, 7, '他们践踏穷人的头，好像践踏地面的尘土；他们把困苦人应有的权益夺去；儿子和父亲与同一个女子亲近，故意亵渎我的圣名。'),
('CNV', '阿摩司书', 30, 2, 8, '他们在各祭坛旁，躺卧在别人抵押的衣服上面；在他们神的殿中，饮用拿剥削回来的钱所买的酒。'),
('CNV', '阿摩司书', 30, 2, 9, '我不是在他们面前把亚摩利人消灭了吗？亚摩利人虽像香柏树高大，像橡树那样坚固；我却要灭绝它树上的果子，拔除树下的根。'),
('CNV', '阿摩司书', 30, 2, 10, '我不是带你们出埃及地，领你们在旷野度过四十年，叫你们得着亚摩利人的地为业吗？'),
('CNV', '阿摩司书', 30, 2, 11, '我从你们子孙中兴起先知，从年轻人中兴起拿细耳人；以色列人哪！这不是事实吗？’这是主的宣告。'),
('CNV', '阿摩司书', 30, 2, 12, '‘但你们迫使拿细耳人喝酒，吩咐先知说：不要说预言。'),
('CNV', '阿摩司书', 30, 2, 13, '看哪！我要使你脚下的地摇荡，好像满载禾捆的车子摇荡一样。'),
('CNV', '阿摩司书', 30, 2, 14, '行动迅速的不能逃走，强而有力的不能施展他的勇力，勇士也不能救自己；'),
('CNV', '阿摩司书', 30, 2, 15, '拿弓的人站立不住，跑得快的不能逃走，骑马的也不能救自己。'),
('CNV', '阿摩司书', 30, 2, 16, '到那日，最勇敢的战士，也是赤身逃跑。’这是主的宣告。”'),
('CNV', '阿摩司书', 30, 3, 1, '以色列人哪！要听主攻击你们的这些话，就是攻击他从埃及地领上来的以色列全家，说：'),
('CNV', '阿摩司书', 30, 3, 2, '“地上万族中，我只拣选了你；因此，我必追讨你们的一切罪。”'),
('CNV', '阿摩司书', 30, 3, 3, '二人如果没有约定，怎会同行呢？'),
('CNV', '阿摩司书', 30, 3, 4, '狮子如果不是捕获猎物，怎会在林中吼叫？少壮狮子如果没有捕获什么，怎会在洞中咆哮呢？'),
('CNV', '阿摩司书', 30, 3, 5, '如果没有饵，雀鸟怎会掉在地上的网罗中？网罗如果没有捕获雀鸟，怎会从地上翻起呢？'),
('CNV', '阿摩司书', 30, 3, 6, '城中如果吹起号角，居民怎会不惊慌呢？灾祸如果临到某城，不是主所降的吗？'),
('CNV', '阿摩司书', 30, 3, 7, '如果主神不先把计划向他的仆人众先知显示，他就不会作任何事。'),
('CNV', '阿摩司书', 30, 3, 8, '狮子吼叫，谁不害怕；主神宣告，谁敢不代他传话？'),
('CNV', '阿摩司书', 30, 3, 9, '要向亚实突和埃及的堡垒宣告：“你们要在撒玛利亚山上聚集；观看城里极大的骚乱和城中的暴虐。”'),
('CNV', '阿摩司书', 30, 3, 10, '“这些人不知道怎样行正直的事，只管在他们的堡垒中积聚暴行和欺压。”这是主的宣告。'),
('CNV', '阿摩司书', 30, 3, 11, '因此，主神这样说：“敌人必围攻这地，使你们的势力倾覆，抢掠你们的堡垒。”'),
('CNV', '阿摩司书', 30, 3, 12, '主这样说：“牧人从狮子口中，只能夺回一双羊腿和一角耳朵；住在撒玛利亚的以色列人获救也是这样，他们只剩下一角床榻，半边褥子（“他们只剩下一角床榻，半边褥子”，这句原文意义不详，或译：“他们躺卧在华丽的床上，睡在铺上绣花毯子的榻上”）。'),
('CNV', '阿摩司书', 30, 3, 13, '你们要听，要向雅各家作证。（这是主神万军之神的宣告。）'),
('CNV', '阿摩司书', 30, 3, 14, '我追讨以色列的悖逆时，必要惩罚伯特利的祭坛；坛角必砍下，跌落在地。'),
('CNV', '阿摩司书', 30, 3, 15, '我必毁坏冬天和夏天的别墅，用象牙装饰的房子必破烂，宏伟的楼宇必归于无有。”这是主的宣告。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '阿摩司书', 30, 4, 1, '撒玛利亚山上的巴珊母牛啊！要听这话；你们欺负贫穷人，压迫穷苦人，又对自己的丈夫说：“拿酒来，给我们饮用。”'),
('CNV', '阿摩司书', 30, 4, 2, '主神指着自己的圣洁起誓：“看哪！对付你们的日子快到，人必用钩子把你们钩走，最后一个也必被人用鱼钩钩去。'),
('CNV', '阿摩司书', 30, 4, 3, '你们一个一个经过城墙的破口出去，被丢弃在哈门。”这是主的宣告。'),
('CNV', '阿摩司书', 30, 4, 4, '“你们去伯特利犯罪，在吉甲增加过犯吧！每早献上你们的祭物，每三日献上你们的十分之一吧！'),
('CNV', '阿摩司书', 30, 4, 5, '以色列人哪！把有酵的饼作感谢祭献上，高声宣扬你们自愿献的祭吧！这原是你们喜爱行的。”这是主神的宣告。'),
('CNV', '阿摩司书', 30, 4, 6, '“虽然我使你们各城的人牙齿干净，各处都缺乏粮食；但你们仍不归向我。”这是主的宣告。'),
('CNV', '阿摩司书', 30, 4, 7, '“我曾在收割前三个月，不降雨给你们；我降雨给一个城，在另一个城却不降雨；我在一块地降雨，另一块地没有雨水就枯干了。'),
('CNV', '阿摩司书', 30, 4, 8, '两三个城的居民挤到一个城去找水喝，却没有足够的水喝；但你们仍不归向我。”这是主的宣告。'),
('CNV', '阿摩司书', 30, 4, 9, '“我曾多次用热风和霉烂击打你们的园子和葡萄园，叫蝗虫吃光你们的无花果树和橄榄树；但你们仍不归向我。”这是主的宣告。'),
('CNV', '阿摩司书', 30, 4, 10, '“我在你们中间降下瘟疫，正如临到埃及的瘟疫一样；我用刀杀掉你们的年轻人，你们被掳去的马匹也遭杀戮；我使你们营里死尸的臭气扑鼻，但你们仍不归向我。”这是主的宣告。'),
('CNV', '阿摩司书', 30, 4, 11, '“我倾覆你们，就像倾覆所多玛和蛾摩拉一样；你们像一根木柴，从火里抽出来；但你们仍不归向我。”这是主的宣告。'),
('CNV', '阿摩司书', 30, 4, 12, '“因此，以色列啊！我必这样对付你。以色列啊！因我必这样对付你，你应当预备迎见你的神。”'),
('CNV', '阿摩司书', 30, 4, 13, '看哪！他造了山，创造了风，把他的心意告诉人；他使晨光变为黑暗，他的脚踏在地的高处，主万军的神就是他的名。'),
('CNV', '阿摩司书', 30, 5, 1, '以色列家啊！要听这话，就是我为你们唱的挽歌：'),
('CNV', '阿摩司书', 30, 5, 2, '“童贞女以色列，跌倒了，不能再起来；她被抛弃在自己的地上，没有人扶她起来。”'),
('CNV', '阿摩司书', 30, 5, 3, '因为主神论以色列家这样说：“这城派兵一千，剩下的只有一百；出兵一百，只剩下十个。”'),
('CNV', '阿摩司书', 30, 5, 4, '主对以色列家这样说：“寻求我，就必存活；'),
('CNV', '阿摩司书', 30, 5, 5, '不要去伯特利寻求我，不要去吉甲，也不要过去别是巴。因为吉甲必被掳掠，伯特利必化为乌有。”'),
('CNV', '阿摩司书', 30, 5, 6, '寻求主，就必存活，免得他像火在约瑟家猛烈蔓延，吞灭他们；没有人能把伯特利的火扑灭。'),
('CNV', '阿摩司书', 30, 5, 7, '他们使公正变为苦堇，把公义弃于地上。'),
('CNV', '阿摩司书', 30, 5, 8, '那创造昴星和参星，把幽暗变为黎明，把白日转为黑夜；又吩咐海水，把海水倒在地上的；主就是他的名。'),
('CNV', '阿摩司书', 30, 5, 9, '是他使毁灭像闪电临到堡垒，使毁灭临到坚固的城。'),
('CNV', '阿摩司书', 30, 5, 10, '他们讨厌那在城门口主持公道的人，恨恶说正直话的。'),
('CNV', '阿摩司书', 30, 5, 11, '你们欺压穷人，强征他们的五谷；因此，你们用琢磨过的石头建造房屋，却不能住在其中；你们栽种美好的葡萄园，却不能喝园中的酒。'),
('CNV', '阿摩司书', 30, 5, 12, '因为我知道你们的过犯众多，罪大恶极；你们迫害义人，收受贿赂，在城门口屈枉穷乏人；'),
('CNV', '阿摩司书', 30, 5, 13, '为此，聪明人在这时代缄默无声，因这时代邪恶。'),
('CNV', '阿摩司书', 30, 5, 14, '你们要寻求良善，不要寻求邪恶，这样才可以存活。主万军的神就必与你们同在，正如你们所说的。'),
('CNV', '阿摩司书', 30, 5, 15, '你们要喜爱良善，恨恶邪恶，在城门口伸张正义；这样，主万军的神或会恩待约瑟的余民。'),
('CNV', '阿摩司书', 30, 5, 16, '因此，主神万军的神这样说：“各广场充满哀恸的声音，街上只听见‘苦啊！苦啊！’的喊声；人要召农夫来哀哭，召善于哭丧的人来哀喊。'),
('CNV', '阿摩司书', 30, 5, 17, '所有葡萄园充满哀恸的声音，因为我必在你们中间经过。”这是主说的。'),
('CNV', '阿摩司书', 30, 5, 18, '渴望主日子来临的人，你们有祸了！主的日子对你们有什么好处呢？那日是黑暗，没有光明的日子。'),
('CNV', '阿摩司书', 30, 5, 19, '那日就像一个人避过了狮子，却遇上了熊；回到家里，手靠在墙上，却被蛇咬。'),
('CNV', '阿摩司书', 30, 5, 20, '主的日子不是黑暗，没有光明，只有幽暗，全无光辉吗？'),
('CNV', '阿摩司书', 30, 5, 21, '我憎恨、厌恶你们的节期，也不喜爱你们的节日。'),
('CNV', '阿摩司书', 30, 5, 22, '虽然你们给我献上燔祭和素祭，我却不接受。你们献上肥美的牲畜作平安祭，我也不悦纳。'),
('CNV', '阿摩司书', 30, 5, 23, '你们唱歌的吵声要远离我，我不想听见你们的琴声。'),
('CNV', '阿摩司书', 30, 5, 24, '但愿公正好像潮水滚流，公义好像河水长流。'),
('CNV', '阿摩司书', 30, 5, 25, '以色列家啊！你们在旷野四十年，有献燔祭和素祭给我吗？'),
('CNV', '阿摩司书', 30, 5, 26, '你们抬着你们的神“撒固”王，和你们的星神“迦温”的神像，就是你们为自己所做的。'),
('CNV', '阿摩司书', 30, 5, 27, '我必使你们被掳，流亡到大马士革以外。这是主说的，万军的神就是他的名。'),
('CNV', '阿摩司书', 30, 6, 1, '那些在锡安平静安逸的，安稳在撒玛利亚山上的，有祸了！你们是这列国中为首之大国的领袖，是以色列家所归向的。'),
('CNV', '阿摩司书', 30, 6, 2, '你们要过去甲尼看看，从那里往哈马大城去，然后下到非利士的迦特；看你们是否比这些国家胜一筹？他们的领土是否比你们的领土还大？'),
('CNV', '阿摩司书', 30, 6, 3, '你们认为灾祸的日子离开很远，你们的行为却招致残暴的审判。'),
('CNV', '阿摩司书', 30, 6, 4, '你们卧在象牙床上，躺在榻上；你们吃羊群中的羊羔，和牛棚里的牛犊。'),
('CNV', '阿摩司书', 30, 6, 5, '你们闲逸地弹琴奏乐，又为自己制造乐器，像大卫一样。'),
('CNV', '阿摩司书', 30, 6, 6, '你们用大碗喝酒，用最贵重的膏油抹身；但你们并没有为约瑟的败落而痛心。'),
('CNV', '阿摩司书', 30, 6, 7, '因此，你们将是最先被掳去的人，宴乐享受的日子必要消逝。'),
('CNV', '阿摩司书', 30, 6, 8, '主神指着自己起誓说：“我痛恨雅各所夸耀的，憎恶他的堡垒；我要把城市和城中的一切，都交给敌人。”这是主万军的神的宣告。'),
('CNV', '阿摩司书', 30, 6, 9, '如果在一间房子里剩下十个人，他们都必死亡。'),
('CNV', '阿摩司书', 30, 6, 10, '死者的亲属和殓葬的人把尸体从房子抬走，并问那躲在屋内深处的人：“还有人吗？”那人回答：“没有，不要再说话，不可再提主的名。”'),
('CNV', '阿摩司书', 30, 6, 11, '看哪！主下令，大楼就粉碎，小屋也要破裂。'),
('CNV', '阿摩司书', 30, 6, 12, '马会在悬崖奔驰吗？人会用牛耙海吗？（译文是根据对原文字母不同的划分；《马索拉抄本》直译作“人会用牛耙地吗？”）但你使公正变为毒草，使公义的果子转为苦堇。'),
('CNV', '阿摩司书', 30, 6, 13, '你们以夺取罗底巴为夸耀，说：“我们夺取加宁不是靠自己的力量吗？”'),
('CNV', '阿摩司书', 30, 6, 14, '“看哪！以色列家，我要兴起一国攻击你们，这国要欺压你们，从哈马关口直至亚拉巴河。”这是万军主神的宣告。'),
('CNV', '阿摩司书', 30, 7, 1, '主神向我这样显示：看哪！替王收割之后，田产又开始生长时，主造出一群蝗虫。'),
('CNV', '阿摩司书', 30, 7, 2, '蝗虫吃尽地上的农产时，我说：“主神啊！求你宽恕，因雅各太弱小，怎能站立得住呢？”'),
('CNV', '阿摩司书', 30, 7, 3, '主对这事改变心意，主说：“这事不会发生。”'),
('CNV', '阿摩司书', 30, 7, 4, '主神向我这样显示：看哪！主神召来刑罚的火，烧毁广大的深渊和以色列的地业。'),
('CNV', '阿摩司书', 30, 7, 5, '因此我对主神说：“求你停止吧！因雅各太弱小，怎能站立得住呢？”'),
('CNV', '阿摩司书', 30, 7, 6, '主对这事改变心意。主神说：“这事也不会发生。”'),
('CNV', '阿摩司书', 30, 7, 7, '他向我这样显示：看哪！主站在一道按准绳建造的墙旁边，手里拿着准绳。'),
('CNV', '阿摩司书', 30, 7, 8, '主对我说：“阿摩司，你看见什么？”我回答：“我看见准绳。”主又说：“看哪！我把准绳放在我民以色列中间，必不再放过他们。'),
('CNV', '阿摩司书', 30, 7, 9, '以撒的各邱坛必荒废，以色列所有的圣所必废弃；我必起来用刀击杀耶罗波安家。”'),
('CNV', '阿摩司书', 30, 7, 10, '伯特利的祭司亚玛谢派人向以色列王耶罗波安报告：“阿摩司在以色列家中图谋背叛你，这国家不能容忍他说的话；'),
('CNV', '阿摩司书', 30, 7, 11, '因为阿摩司这样说：‘耶罗波安必死在刀下，以色列必被掳，离开本国。’”'),
('CNV', '阿摩司书', 30, 7, 12, '亚玛谢对阿摩司说：“你这个先见，走吧！滚回犹大地去；在那里你可以找食，在那里你可以说预言。'),
('CNV', '阿摩司书', 30, 7, 13, '但不要再在伯特利说预言，因为这里是王的圣所，是王国的圣殿。”'),
('CNV', '阿摩司书', 30, 7, 14, '阿摩司回答亚玛谢说：“我原不是先知，也不是先知的门徒；我本是牧人，是修理桑树的，'),
('CNV', '阿摩司书', 30, 7, 15, '但主选召我，叫我不再跟随羊群；他对我说：‘你去，向我民以色列说预言。’'),
('CNV', '阿摩司书', 30, 7, 16, '现在你要听主的话；因为你说：‘不要说预言攻击以色列，不要说攻击以撒家的话。’'),
('CNV', '阿摩司书', 30, 7, 17, '所以，主这样说：‘你妻子必在城中作妓女，你的儿女必倒在刀下；你的土地必被人量度瓜分，你自己必死在不洁之地；以色列必被掳，离开本国。’”'),
('CNV', '阿摩司书', 30, 8, 1, '主神向我显示，我就看见一篮夏天的果子。'),
('CNV', '阿摩司书', 30, 8, 2, '主说：“阿摩司，你看见什么？”我回答：“一篮夏天的果子。”他跟着对我说：“我民以色列的结局到了，我不再放过他们。'),
('CNV', '阿摩司书', 30, 8, 3, '“到那日，圣殿的歌声必变为哀号；尸首众多，抛弃各处；你们要肃静。”这是主神的宣告。'),
('CNV', '阿摩司书', 30, 8, 4, '践踏穷乏人又除掉国中困苦人的，你们要听这话。'),
('CNV', '阿摩司书', 30, 8, 5, '你们说：“月朔什么时候过去，好让我们可以卖五谷；安息日什么时候结束，好让我们可以开市卖谷物。我们卖东西就把升斗弄小，收银子却用加重了的法码，我们要用假秤欺骗人。'),
('CNV', '阿摩司书', 30, 8, 6, '我们用银子买穷人，用一双鞋换取穷乏人；连麦碎也卖掉。”'),
('CNV', '阿摩司书', 30, 8, 7, '主指着雅各所夸耀的起誓说：“我必永远记着他们所作的一切；'),
('CNV', '阿摩司书', 30, 8, 8, '“这地不应为此震动，所有住在地上的不应悲哀吗？这地必像尼罗河高涨翻腾，像埃及的大河退落。'),
('CNV', '阿摩司书', 30, 8, 9, '“到那日，这是主的宣告：我必使太阳在正午落下，在白昼使地变成昏暗。'),
('CNV', '阿摩司书', 30, 8, 10, '“我必使你们欢乐的节期变为悲哀的日子，把你们的歌声都变为哀哭。我必使你们各人腰束麻带，头都剃光了；我必使你们悲哀，好像丧了独生子，自始至终都是痛苦的。'),
('CNV', '阿摩司书', 30, 8, 11, '“看哪！日子快到，这是主神的宣告。我必使饥荒临到这地，这饥荒不是因为没有食物，这干渴不是因为没有水；而是因为听不见主的话。'),
('CNV', '阿摩司书', 30, 8, 12, '他们从这海飘流到那海，从北到东，到处奔走，要寻求主的话，却寻不见。'),
('CNV', '阿摩司书', 30, 8, 13, '“到那日，美丽的少女和青年男子都因干渴昏倒。'),
('CNV', '阿摩司书', 30, 8, 14, '那些指着撒玛利亚的罪（“罪”或作“亚示玛女神”）起誓，或是那些指着但的神，或别是巴的神（“别是巴的神”原文作“别是巴的道”）起誓的，他们要倒下，再不能起来。”'),
('CNV', '阿摩司书', 30, 9, 1, '我见主站在祭坛旁，他说：“击打圣殿的柱顶，使门槛都震动。砍掉它们，落在众人的头上，剩下的人我必用刀杀死；没有一个能逃走，没有一人逃脱。'),
('CNV', '阿摩司书', 30, 9, 2, '如果他们下到阴间，就是在那里，我的手必把他们揪上来；如果他们升到天上，就是在那里，我必把他们拉下来；'),
('CNV', '阿摩司书', 30, 9, 3, '如果他们躲在迦密山顶，就是在那里，我必搜寻他们，抓他们出来；如果他们要躲避我，藏在海底，就是在那里，我必命令蛇去咬他们；'),
('CNV', '阿摩司书', 30, 9, 4, '如果他们被仇敌掳去，就是在那里，我必命令刀剑杀死他们；我必定睛在他们身上，降祸不降福。”'),
('CNV', '阿摩司书', 30, 9, 5, '万军之主神摸地，地就融化，住在地上的都要悲哀。这地必像尼罗河高涨，像埃及的大河退落。'),
('CNV', '阿摩司书', 30, 9, 6, '那在天上建立楼阁，在大地之上奠立穹苍；又吩咐海水，把海水倒在地上的；主就是他的名。'),
('CNV', '阿摩司书', 30, 9, 7, '“以色列人哪！在我看来，你们不是与古实人一样吗？我带领以色列人出埃及地，不是也领非利士人出迦斐托，领亚兰人出吉珥吗？”这是主的宣告。'),
('CNV', '阿摩司书', 30, 9, 8, '“看哪！主的眼目察看这有罪的国，我要把它从地上除灭；却必不把雅各家完全除灭。”这是主的宣告。'),
('CNV', '阿摩司书', 30, 9, 9, '主说：“看哪！我必下令，我必在列国中筛以色列家，好像人用筛子筛谷，但谷粒不会落在地上。'),
('CNV', '阿摩司书', 30, 9, 10, '我民中所有犯罪的人，就是那些说：‘灾祸必不临近、追上我们’的人，他们必死在刀下。'),
('CNV', '阿摩司书', 30, 9, 11, '“到那日，我必竖立大卫倒塌的帐棚，修补它们的破口；我必重建它的废墟，使它像往日一样建立起来。'),
('CNV', '阿摩司书', 30, 9, 12, '好使他们获得以东所余剩的，以及所有称为我名下的国。”这是行这些事的主的宣告。'),
('CNV', '阿摩司书', 30, 9, 13, '“日子快到，这是主的宣告。耕地的必紧接着收割的，踹葡萄的必紧接着撒种的；大山必滴下甜酒，小山必融化。'),
('CNV', '阿摩司书', 30, 9, 14, '我必使我的子民以色列被掳的人回归，他们必重建荒废的城，住在其中；他们必栽种葡萄园，喝园中的酒；建造果园，吃园中的果子。'),
('CNV', '阿摩司书', 30, 9, 15, '我必把他们栽于他们自己的土地，他们再不会从我赐给他们的土地上被拔除。”这是主你的神说的。'),
('CNV', '俄巴底亚书', 31, 1, 1, '俄巴底亚所见的异象。主神指着以东这样说：我们从主那里听见了一个信息，有一位使者被派往列国去，说：“起来吧！我们起来与以东争战。”'),
('CNV', '俄巴底亚书', 31, 1, 2, '看哪！我必使你在列国中成为弱小的，你必大受藐视。'),
('CNV', '俄巴底亚书', 31, 1, 3, '你心中的傲气欺骗了你；你这住在岩石的隐密处，居所在高处的啊！你心里说：“谁能把我拉下地呢？”'),
('CNV', '俄巴底亚书', 31, 1, 4, '你虽如鹰高飞，在星宿之间搭窝，我也必从那里把你拉下来。这是主的宣告。'),
('CNV', '俄巴底亚书', 31, 1, 5, '窃贼若来到你那里，强盗若夜间来到，岂不会偷窃直到够了呢？你将会怎样被灭绝！摘葡萄的若来到你那里，岂不只剩下几粒葡萄吗？'),
('CNV', '俄巴底亚书', 31, 1, 6, '以扫要怎样被搜索，他收藏的宝物被搜查出来。'),
('CNV', '俄巴底亚书', 31, 1, 7, '曾与你结盟的，都把你送到边界；本来与你友好的，却欺骗你，胜过你；与你同席的（“与你同席的”或译：“吃你的食物的”），在你脚下暗设网罗，你却毫不晓得。'),
('CNV', '俄巴底亚书', 31, 1, 8, '主宣告说：到那日，我岂不从以东灭绝智慧人吗？岂不从以扫山除掉聪明人吗？'),
('CNV', '俄巴底亚书', 31, 1, 9, '提幔哪！你的勇士要惊惶，因此在以扫山上人人被杀戮剪除。'),
('CNV', '俄巴底亚书', 31, 1, 10, '因你对兄弟雅各行强暴，你必受羞辱，永被剪除。'),
('CNV', '俄巴底亚书', 31, 1, 11, '外地人劫掠雅各财物的日子，外族人进入他的城门，为耶路撒冷抽签；那时你竟袖手旁观，甚至好像他们中间的一分子！'),
('CNV', '俄巴底亚书', 31, 1, 12, '你兄弟遭遇祸患的日子，你不该看着不理；犹大人被灭的日子，你不该幸灾乐祸；他们遭难的日子，你不该张口狂傲；'),
('CNV', '俄巴底亚书', 31, 1, 13, '我子民遭灾的日子，你不该进入他们的城门；他们遭灾的日子，你不该看着他们受苦；他们遭灾的日子，你不该抢夺他们的财物。'),
('CNV', '俄巴底亚书', 31, 1, 14, '你不该站在岔路口，剪除他们中间逃脱的人；他们遭难的日子，你不该把他们生还的人交出来。'),
('CNV', '俄巴底亚书', 31, 1, 15, '主的日子临近万国了，人必照你所行的向你施行，你的报应必归到你的头上。'),
('CNV', '俄巴底亚书', 31, 1, 16, '你们怎样在我的圣山上喝过苦杯，万国也必照样不住地喝，他们要喝，并且要吞下去，他们就不再存在了。'),
('CNV', '俄巴底亚书', 31, 1, 17, '但在锡安山上必有逃脱的人，那山必成为圣；雅各家必得回他们原有的产业。'),
('CNV', '俄巴底亚书', 31, 1, 18, '雅各家必成为火，约瑟家必成为火焰；以扫家却像碎秸，被它们焚烧吞灭，以扫家再没有生还的人了。因为主已经说了。'),
('CNV', '俄巴底亚书', 31, 1, 19, '南地的人必占有以扫山，低地的人必占有非利士人之地；他们必占有以法莲的田野和撒玛利亚的田野；便雅悯人必占有基列。'),
('CNV', '俄巴底亚书', 31, 1, 20, '被掳到哈腊的以色列人，必占有迦南人的地，直到撒勒法；被掳到西法拉的耶路撒冷的人，要占有南地众城。'),
('CNV', '俄巴底亚书', 31, 1, 21, '必有拯救者登锡安山，审判以扫山，国权就属于主了。'),
('CNV', '约拿书', 32, 1, 1, '主的话临到亚米太的儿子约拿，说：'),
('CNV', '约拿书', 32, 1, 2, '“起来！到尼尼微大城去，警告其中的居民，因为他们的恶行已经达到我面前。”'),
('CNV', '约拿书', 32, 1, 3, '可是约拿却起来，要逃往他施去，躲避主；他下到约帕，找到了一只要开往他施去的船；他给了钱，就上船（“上船”原文作“下船”），要和他们同往他施去，离开主。'),
('CNV', '约拿书', 32, 1, 4, '但是主在海上忽然刮起大风，于是海中狂风大作，船几乎要破裂了。'),
('CNV', '约拿书', 32, 1, 5, '水手都很惧怕，各人向自己的神大声呼求；他们为了减轻船的重量，就把船上的东西抛在海里，可是约拿却下了船舱，躺着熟睡了。'),
('CNV', '约拿书', 32, 1, 6, '船长走到他面前，对他说：“你怎么啦！睡得那么熟？快起来，求告你的神吧！或者神会记念我们，使我们不至于丧命！”'),
('CNV', '约拿书', 32, 1, 7, '水手就彼此说：“来吧！让我们抽签，好知道这场灾祸临到我们，是因谁的缘故。”于是他们抽签，结果抽中了约拿。'),
('CNV', '约拿书', 32, 1, 8, '他们就对约拿说：“请告诉我们，这场灾祸临到我们，是因谁的缘故？你是作什么的？你从哪里来？你是哪一国的人？哪一族的人？”'),
('CNV', '约拿书', 32, 1, 9, '他回答说：“我是希伯来人，我敬畏主天上的神，就是那创造海洋和陆地的。”'),
('CNV', '约拿书', 32, 1, 10, '众人就大大惧怕，对他说：“你为什么这样作呢？（“你为什么这样作呢？”或译：“你作的是什么呢？”）”那些人知道他躲避主，原来约拿告诉了他们。'),
('CNV', '约拿书', 32, 1, 11, '因为海浪越来越汹涌，他们又对他说：“我们该怎样处置你，才能叫海浪平静呢？”'),
('CNV', '约拿书', 32, 1, 12, '他回答说：“你们把我抬起来，投在海里，海浪就会平静，因为我知道，这场大风暴临到你们，是为了我的缘故。”'),
('CNV', '约拿书', 32, 1, 13, '那些人虽然破浪挣扎，要把船靠岸，却是不能，因为海浪不断汹涌扑来。'),
('CNV', '约拿书', 32, 1, 14, '他们就呼求主，说：“主啊！我们恳求你，不要因这人叫我们丧命；不要把无辜人的血归在我们身上，因为你主是照自己所喜悦的行事。”'),
('CNV', '约拿书', 32, 1, 15, '于是他们把约拿抬起来，投在海里，怒涛就平息了。'),
('CNV', '约拿书', 32, 1, 16, '那些人就大大敬畏主，向他献祭和许愿。'),
('CNV', '约拿书', 32, 1, 17, '主却安排了一条大鱼，把约拿吞下。约拿就在鱼腹中三日三夜。（本节在《马索拉文本》为2:1）'),
('CNV', '约拿书', 32, 2, 1, '约拿从鱼腹中向主他的神祷告，'),
('CNV', '约拿书', 32, 2, 2, '说：“我从患难中求告主，他就应允我；我从阴间的深府呼求，你就垂听我的声音。'),
('CNV', '约拿书', 32, 2, 3, '你把我投入深海，在海洋的深处，大水环绕我；你的洪涛、你的波浪，都漫过我。'),
('CNV', '约拿书', 32, 2, 4, '我说：‘我虽从你眼前被赶逐，我仍要仰望你的圣殿。’'),
('CNV', '约拿书', 32, 2, 5, '众水包围我，几乎置我于死地；深渊环绕我；海草缠裹我的头。'),
('CNV', '约拿书', 32, 2, 6, '我下沉直到山麓，大地的门闩把我永远关闭；主我的神啊！你却把我的性命从坑中拉上来。'),
('CNV', '约拿书', 32, 2, 7, '当我心灵疲弱时，我就思念主；我的祷告直达你面前，进入你的圣殿。'),
('CNV', '约拿书', 32, 2, 8, '那敬奉虚妄之偶像的人，实在是离弃了怜爱他们的神（“怜爱他们的神”原文作“他们的恩典”）。'),
('CNV', '约拿书', 32, 2, 9, '至于我，我要带着感谢的声音向你献祭；我所许的愿，我必偿还。救恩是属于主的。”'),
('CNV', '约拿书', 32, 2, 10, '于是主吩咐那鱼，鱼就把约拿吐在陆地上。'),
('CNV', '约拿书', 32, 3, 1, '主的话再次临到约拿，说：'),
('CNV', '约拿书', 32, 3, 2, '“起来！到尼尼微大城去，向其中的居民宣告我所吩咐你的话。”'),
('CNV', '约拿书', 32, 3, 3, '约拿就动身，照主的话往尼尼微去了，这尼尼微是一座极大的城（“是一座极大的城”或译：“在神面前是一座大城”），要三天才能走完。'),
('CNV', '约拿书', 32, 3, 4, '约拿进城，走了一天，就宣告说：“再过四十天，尼尼微就要毁灭了。”'),
('CNV', '约拿书', 32, 3, 5, '尼尼微人信了（“信了”或译：“信服”）神，就宣告禁食，从大到小，都穿上麻衣。'),
('CNV', '约拿书', 32, 3, 6, '这事传到尼尼微王那里，他就起来，离开宝座，脱去王袍，披上麻衣，坐在炉灰中。'),
('CNV', '约拿书', 32, 3, 7, '他又传谕全尼尼微，说：“王和大臣有令：‘人、畜、牛、羊，都不准尝什么，不准吃，也不准喝。'),
('CNV', '约拿书', 32, 3, 8, '不论人畜，都要披上麻衣；各人要恳切呼求神，悔改，离开恶行，摒弃手中的强暴。'),
('CNV', '约拿书', 32, 3, 9, '或者神回心转意，不发烈怒，使我们不致灭亡。’”'),
('CNV', '约拿书', 32, 3, 10, '神看见他们所作的，就是悔改离开恶行，神就转意，不把所说的灾祸降在他们身上了。'),
('CNV', '约拿书', 32, 4, 1, '约拿对这事非常不高兴，并且发起怒来，'),
('CNV', '约拿书', 32, 4, 2, '就向主祷告，说：“主啊！我还在本国的时候，不是这样说过吗？我知道你是有恩典有怜悯的神，不轻易发怒，并且有丰盛的慈爱，转意不降灾祸，所以我才急忙逃往他施去。'),
('CNV', '约拿书', 32, 4, 3, '主啊！现在求你取去我的性命吧，因为我死了比活着还好。”'),
('CNV', '约拿书', 32, 4, 4, '主回答说：“你这样发怒对不对呢？”'),
('CNV', '约拿书', 32, 4, 5, '约拿出了城，在城东坐下；他在那里搭了一座棚，坐在棚荫之下，要看看那城究竟怎样。'),
('CNV', '约拿书', 32, 4, 6, '主神安排一棵蓖麻，使它长起来高过约拿，成了阴影遮盖他的头，免他受苦；约拿因这棵蓖麻，就大大欢畅。'),
('CNV', '约拿书', 32, 4, 7, '次日黎明的时候，神安排一条虫子，蛀蚀这棵蓖麻，蓖麻就枯槁了。'),
('CNV', '约拿书', 32, 4, 8, '日出的时候，神又安排炎热的东风。烈日晒在约拿的头上，以致发昏，他就为自己求死，说：“我死了比活着还好。”'),
('CNV', '约拿书', 32, 4, 9, '神问约拿：“你因这棵蓖麻这样发怒，对不对呢？”约拿说：“我发怒以至于死都是对的。”'),
('CNV', '约拿书', 32, 4, 10, '主说：“这棵蓖麻，不是你栽种的，也不是你使它长大的，一夜长成，一夜死去，你尚且爱惜它，'),
('CNV', '约拿书', 32, 4, 11, '何况这尼尼微大城，其中不晓得分辨左右手的有十二万多人，并且有许多牲畜，我怎能不爱惜呢？”'),
('CNV', '弥迦书', 33, 1, 1, '在犹大王约坦、亚哈斯、希西家执政的时候，主的话临到摩利沙人弥迦，是他看到关于撒玛利亚和耶路撒冷的话。'),
('CNV', '弥迦书', 33, 1, 2, '万民哪！你们都要听；地和地上所遍满的，你们要聆听；主神要指证你们的不是，主必从他的圣殿指证你们的不是。'),
('CNV', '弥迦书', 33, 1, 3, '看哪！主离开自己的地方，他降下来，踏在地的高处。'),
('CNV', '弥迦书', 33, 1, 4, '群山在他脚下融化，众谷裂开，如蜡在火前一般，像水冲下斜坡一般，'),
('CNV', '弥迦书', 33, 1, 5, '这都是因为雅各的过犯，以色列家的罪恶。雅各的过犯是什么呢？不就是撒玛利亚吗？犹大家的罪恶是什么呢？不就是耶路撒冷吗？'),
('CNV', '弥迦书', 33, 1, 6, '所以我必使撒玛利亚变成田间的废堆，作栽种葡萄之处；我必把撒玛利亚的石头倒在谷中，连它的根基都露出来。'),
('CNV', '弥迦书', 33, 1, 7, '它一切雕刻的偶像必被打碎；它全部的钱财，都要用火烧尽；它所有的偶像，我都要毁灭；因为从妓女钱财榨取的，最后也必归为妓女的钱财。'),
('CNV', '弥迦书', 33, 1, 8, '为此我要痛哭哀号，赤膊光脚而行；又要哀号如豺狼，悲鸣像鸵鸟。'),
('CNV', '弥迦书', 33, 1, 9, '因为撒玛利亚的创伤无法医治，并且殃及犹大，直逼我子民的城门，就是耶路撒冷。'),
('CNV', '弥迦书', 33, 1, 10, '不要在迦特报信，不要在巴歌哭泣；却要在伯．亚弗拉打滚于尘土中。'),
('CNV', '弥迦书', 33, 1, 11, '沙斐的居民哪！你们赤身羞愧走过去吧。撒南的居民不敢出来（“不敢出来”或译：“也逃不掉”）；伯．以薛人的哀号，要把你们立足之地夺去。'),
('CNV', '弥迦书', 33, 1, 12, '玛律的居民，急待得着幸福，因有灾祸从主那里降下，临到耶路撒冷的城门。'),
('CNV', '弥迦书', 33, 1, 13, '拉吉的居民哪！要用快马套车，这就是锡安子民（“子民”原文作“女子”）罪恶的开端；因为以色列的过犯，都在你那里找到了。'),
('CNV', '弥迦书', 33, 1, 14, '因此要把妆奁，送给摩利设．迦特；亚革悉的各家，必用诡诈对待以色列的众王。'),
('CNV', '弥迦书', 33, 1, 15, '玛利沙的居民哪！我要再使那征服你的来到你那里；以色列的荣耀，必去到亚杜兰。'),
('CNV', '弥迦书', 33, 1, 16, '犹大啊！为你所喜爱的儿女，你要剃头，使你的头光秃，完全光秃如同秃鹰；因为他们都从你那里被掳去了。'),
('CNV', '弥迦书', 33, 2, 1, '那些在床上图谋不义，并且行恶的人有祸了！因为他们的手有力量，天一亮，就作出来了。'),
('CNV', '弥迦书', 33, 2, 2, '他们要田地，就去抢夺；想要房屋，就去强取。他们欺压人和他的家眷，取人和人的产业。'),
('CNV', '弥迦书', 33, 2, 3, '因此主这样说：看哪！我策划灾祸攻击这家族，你们无法缩起颈项避开这灾祸。你们不能昂首而行（“昂首而行”或译：“高视阔步”）；因为这是个灾难的时代。'),
('CNV', '弥迦书', 33, 2, 4, '到那日，必有人作歌讽刺你们，唱悲伤的哀歌，说：“我们彻底被毁灭了，我子民分内的产业，他竟转给别人了；他怎可从我这里挪去，把我们的田地分给掳掠我们的人（“分给掳掠我们的人”或译：“分给背道的人”）！”'),
('CNV', '弥迦书', 33, 2, 5, '因此你在主的会众中，必没有抽签拉准绳的人了。'),
('CNV', '弥迦书', 33, 2, 6, '有人预言说：“你们不要说预言；人不可预言这些事；羞耻不会临到我们。”'),
('CNV', '弥迦书', 33, 2, 7, '雅各家啊！人怎可说：“主的心着急，（按照《马索拉文本》，“主的心着急”直译是“主的灵是短的吗”）不能忍耐呢？这些是他的作为吗？”我主的话对行事正直的人不是有益的吗？'),
('CNV', '弥迦书', 33, 2, 8, '你们却像仇敌一样，起来攻击我的子民（“你们却像仇敌一样，起来攻击我的子民”或译：“然而，我的子民竟兴起来像仇敌一样”）；你们竟从安详过路的人身上剥去衣服，从不愿作战的人身上剥去外衣。'),
('CNV', '弥迦书', 33, 2, 9, '你们把我民中的妇女赶逐，离开欢乐的家园；你们把我的尊荣，从她们的婴孩身上夺去，直到永远。'),
('CNV', '弥迦书', 33, 2, 10, '起来，走吧！这不是你们安息之地；你们因为不洁净的缘故，必被毁灭，是不可挽救的毁灭。'),
('CNV', '弥迦书', 33, 2, 11, '若有人随从虚假的心，撒谎说：“我要向你们说清酒和烈酒的预言。”那人就是这民的预言家了。'),
('CNV', '弥迦书', 33, 2, 12, '雅各家啊！我必召集你们所有的人，聚集以色列的余民；我要把他们安置在一起，像羊在羊圈里，像群羊远离了人，在草场上喧哗。'),
('CNV', '弥迦书', 33, 2, 13, '开路的人领先上去；他们开路，闯门进入，又从门里出来；他们的王在他们面前走过，主领导他们。'),
('CNV', '弥迦书', 33, 3, 1, '我说：“雅各的首领，你们要听，以色列家的官长，你们也要听；难道你们不知道公平吗？'),
('CNV', '弥迦书', 33, 3, 2, '然而，你们恨恶良善，喜爱邪恶，从人身上剥皮，从人骨头上剔肉。'),
('CNV', '弥迦书', 33, 3, 3, '你们吃我民的肉，剥他们的皮，打断他们的骨头，切成像锅里的块，像釜中的肉块。'),
('CNV', '弥迦书', 33, 3, 4, '那时，他们要向主呼求，主却不应允他们。到那时，主必掩面不顾他们，因为他们行了恶事。”'),
('CNV', '弥迦书', 33, 3, 5, '关于那些使我民走迷路的先知，主这样说：“他们的牙齿有所咀嚼的时候，就大叫‘平安’；谁不把食物给他们吃，他们就攻击那人。”'),
('CNV', '弥迦书', 33, 3, 6, '因此你们只有黑夜，没有异象，只有黑暗，没有默示。对先知，日头要下落，为他们，白日变为黑暗。'),
('CNV', '弥迦书', 33, 3, 7, '先见必抱愧，得默示的人要蒙羞；他们都必掩着上唇，因为没有神的答覆。'),
('CNV', '弥迦书', 33, 3, 8, '至于我，我却藉着主的灵，满有力量、公平和能力，可以向雅各述说他的过犯，向以色列指出他的罪恶。'),
('CNV', '弥迦书', 33, 3, 9, '雅各家的首领，你们要听这个，以色列家的官长，你们也要听；你们厌恶公平，屈枉正直，'),
('CNV', '弥迦书', 33, 3, 10, '用人血建锡安，以罪孽造耶路撒冷。'),
('CNV', '弥迦书', 33, 3, 11, '城中的首领为贿赂而审判，祭司为薪俸而教导，先知为银子说默示，他们竟倚靠主，说：“主不是在我们中间吗？灾祸必不会临到我们身上。”'),
('CNV', '弥迦书', 33, 3, 12, '所以，为你们的缘故，锡安必像被耕种的田地，耶路撒冷必变为乱堆，这殿的山要成为丛林中的高冈。'),
('CNV', '弥迦书', 33, 4, 1, '到末后的日子，主殿的山，必矗立在万山之上，高举过于万岭；万民都要流归这山。'),
('CNV', '弥迦书', 33, 4, 2, '必有多国的人前来说：“来吧！我们上主的山，登雅各神的殿；他必把他的道路指示我们，我们也要遵行他的道；因为教训必出于锡安。主的话要来自耶路撒冷。'),
('CNV', '弥迦书', 33, 4, 3, '“他要在多族中施行审判，为远方的强国断定是非。他们必把刀剑打成犁头，把矛枪打成镰刀；这国不举刀攻击那国，他们也不再学习战事。'),
('CNV', '弥迦书', 33, 4, 4, '各人都要坐在自己的葡萄树，和无花果树下，无人惊吓他们，因为万军之主亲口说过了。'),
('CNV', '弥迦书', 33, 4, 5, '虽然，万民各奉自己神的名行事，我们却要永远奉主我们神的名而行。”'),
('CNV', '弥迦书', 33, 4, 6, '主说：“到那日，我必召聚瘸腿的，集合被赶散的，和我所苦待的。'),
('CNV', '弥迦书', 33, 4, 7, '我必使瘸腿的作余民；使被放逐的成为强国；主必在锡安山作王统治他们，从现在直到永远。'),
('CNV', '弥迦书', 33, 4, 8, '你这羊群的守望楼啊！锡安女子的俄斐勒啊！从前的权柄，必归给你，就是耶路撒冷女子的国权，要归还给你。'),
('CNV', '弥迦书', 33, 4, 9, '现在你为什么大声呼喊？难道你们中间没有君王吗？或是你的谋士灭亡了，以致疼痛抓紧你，好像临产的妇人呢？'),
('CNV', '弥迦书', 33, 4, 10, '锡安的女子啊！你要疼痛劬劳，好像临产的妇人；因为现在你要从城里出来，住在田野，一定要到巴比伦去；在那里你要蒙拯救，在那里主必救赎你，脱离仇敌的掌握。'),
('CNV', '弥迦书', 33, 4, 11, '现在多国的民集合起来，攻击你，说：‘愿锡安被蹂躏，愿我们亲眼看见锡安遭报应。’”'),
('CNV', '弥迦书', 33, 4, 12, '但是，他们却不知道主的意念，也不明白他的谋略；他收集他们，好像把禾捆收集到禾场一样。'),
('CNV', '弥迦书', 33, 4, 13, '锡安的女子啊！起来踹谷吧！因为我必使你的角成为铁，使你的蹄成为铜；你必粉碎许多民族，毁灭他们所得的不义之财，作为祭物献与主，把他们的财宝献给全地的主。'),
('CNV', '弥迦书', 33, 5, 1, '女子啊！现在你要聚集成队；仇敌正在围攻我们；他们用杖击打以色列执政者的脸颊。（本节在《马索拉文本》为4:14）'),
('CNV', '弥迦书', 33, 5, 2, '伯利恒以法他啊！你在犹大诸城中虽然细小（“伯利恒……细小”有古卷作“以法他家啊，你在犹大诸族中虽然细小”），必有一位从你那里出来，为我作以色列的统治者；他的根源从太初，从亘古就有了。（本节在《马索拉文本》为5:1）'),
('CNV', '弥迦书', 33, 5, 3, '因此，主必把以色列人交给敌人，直到那要生产的妇人生下孩子来；那时，他其余的兄弟，就必归回以色列人那里。'),
('CNV', '弥迦书', 33, 5, 4, '他必站立起来，靠着主的能力，靠着主他神之名的威严，牧养他的羊群；他们必然安居，因为那时他必尊大，直到地极。'),
('CNV', '弥迦书', 33, 5, 5, '这就是那带来太平的。亚述人入侵我们的国土，践踏我们宫殿的时候，我们就要兴起七个牧者；八个作领袖的人攻击他。'),
('CNV', '弥迦书', 33, 5, 6, '他们必用刀剑治理亚述地，必用剑锋治理宁录地；亚述人入侵我们的国土，践踏我们境界的时候，他必拯救我们脱离亚述人的手。'),
('CNV', '弥迦书', 33, 5, 7, '那时，雅各的余民，必在许多民族中，像从主那里降下的露水，又像甘霖降在草上，不期望于人，也不等候世人。'),
('CNV', '弥迦书', 33, 5, 8, '那时雅各的余民，必在万国中，在许多民族里，像树林里百兽中的狮子，又像幼狮在羊群中；他若经过，就必践踏、撕碎，没有人可以拯救。'),
('CNV', '弥迦书', 33, 5, 9, '愿你的手举起高过你的敌人，愿你的一切仇敌都被剪除。'),
('CNV', '弥迦书', 33, 5, 10, '主说：“到那日，我必从你中间剪除你的马匹，毁灭你的车辆，'),
('CNV', '弥迦书', 33, 5, 11, '拆毁你国中的城市，倾覆你的一切保障；'),
('CNV', '弥迦书', 33, 5, 12, '我必从你的手中除掉巫术，你那里就不再有占卜的；'),
('CNV', '弥迦书', 33, 5, 13, '我必从你中间除掉你雕刻的偶像和柱像，你就不再跪拜你手所做的；'),
('CNV', '弥迦书', 33, 5, 14, '我必从你中间除灭你的亚舍拉，毁灭你的偶像。'),
('CNV', '弥迦书', 33, 5, 15, '我必在忿怒和烈怒中，向那些不听从的列国施行报复。”'),
('CNV', '弥迦书', 33, 6, 1, '你们当听主所说的话：“你要起来，向大山争辩，让小山可以听见你的声音。'),
('CNV', '弥迦书', 33, 6, 2, '大山啊！你们要听主的争辩。大地永久的根基啊！你们要听，因为主与他的子民争辩，和以色列争论。'),
('CNV', '弥迦书', 33, 6, 3, '我的子民啊，我向你作了什么呢？我在什么事上叫你厌烦呢？你可以回答我。'),
('CNV', '弥迦书', 33, 6, 4, '我曾经把你从埃及地领上来，把你从为奴之家赎出来；我也差派了摩西、亚伦和米利暗在你前面行。'),
('CNV', '弥迦书', 33, 6, 5, '我的民哪！你们要追念，摩押王巴勒图谋过什么，比珥的儿子巴兰又答应了他什么，以及你们从什亭到吉甲所发生的事，好使你们知道主公义的作为。”'),
('CNV', '弥迦书', 33, 6, 6, '我朝见主，在至高的神面前叩拜，当献上什么呢？我朝见他的时候，当献上燔祭，当献上一岁的牛犊吗？'),
('CNV', '弥迦书', 33, 6, 7, '主喜悦千千的公羊，或是万万的油河吗？为我的过犯，我可以献上我的长子吗？为我的罪恶，献上我亲生的孩子吗？'),
('CNV', '弥迦书', 33, 6, 8, '世人哪！主已经指示你什么是善，他向你所要的又是什么；无非是要你行公义，好怜悯，谦虚谨慎与你的神同行。'),
('CNV', '弥迦书', 33, 6, 9, '听啊！主向这城呼叫，敬畏你的名就是智慧；支派和城里的会众啊！你们要听。'),
('CNV', '弥迦书', 33, 6, 10, '我怎能忘记恶人家中的不义之财，和那些可咒诅的小升斗呢？'),
('CNV', '弥迦书', 33, 6, 11, '用不义的天平，和袋中诈骗的法码的人，我怎能算他为清洁呢？'),
('CNV', '弥迦书', 33, 6, 12, '城里的财主充满了强暴，其中的居民也说假话；他们口中的舌头是诡诈的。'),
('CNV', '弥迦书', 33, 6, 13, '因此我击打你，使你生病（“我击打你，使你生病”或参照《七十士译本》和其他古译本作“我开始击打你”），因你的罪恶，使你荒凉。'),
('CNV', '弥迦书', 33, 6, 14, '你要吃，却吃不饱；因你的腹中常有疾病。你要怀孕，却不能生下来；你生下来的，我都要交给刀剑。'),
('CNV', '弥迦书', 33, 6, 15, '你要撒种，却不得收割，你要榨橄榄油，却不得油抹身；你要榨葡萄汁，却不得酒喝。'),
('CNV', '弥迦书', 33, 6, 16, '你跟随了暗利的规例和亚哈家一切所行的，顺从了他们的计谋；因此，我必使你荒凉，使你（“你”原文作“她”）的居民被嗤笑；你们也必担当我民的羞辱。'),
('CNV', '弥迦书', 33, 7, 1, '我有祸了！因为我好像夏天采摘的果子，又像摘剩的葡萄，没有一挂可吃的，也没有我心所想望早熟的无花果。'),
('CNV', '弥迦书', 33, 7, 2, '虔敬的人从地上灭绝了，人间也没有正直的人，人人都埋伏着要流人的血，各人都用网罗猎取自己的兄弟。'),
('CNV', '弥迦书', 33, 7, 3, '他们双手善于作恶，官长和审判官都要求报酬；达官贵人说出心里的欲望；他们歪曲了一切。'),
('CNV', '弥迦书', 33, 7, 4, '他们中最好的，也不过像荆棘，最正直的，也不过是有刺的篱笆。你的守望者所预言的日子，和你被鉴察的时候，已经来到；现在他们必要慌乱不安。'),
('CNV', '弥迦书', 33, 7, 5, '不可信靠邻舍，也不可信任朋友，要守住你的嘴唇，不可向躺在你怀中的妻子透露。'),
('CNV', '弥迦书', 33, 7, 6, '儿子藐视父亲，女儿抗拒母亲，媳妇与婆婆作对；人的仇敌就是自己的家人。'),
('CNV', '弥迦书', 33, 7, 7, '至于我，我却要仰望主，我要等候那拯救我的神；我的神必应允我。'),
('CNV', '弥迦书', 33, 7, 8, '我的仇敌啊！不要因我的遭遇而高兴；我虽然跌倒了，却必起来；我虽然坐在黑暗里，主却必作我的光。'),
('CNV', '弥迦书', 33, 7, 9, '我要担当主的忿怒，因为我得罪了他，直到他审断我的案件，为我主持公道；他必把我领出来，到光明中去，我就得见他的公义。'),
('CNV', '弥迦书', 33, 7, 10, '我的仇敌看见了，就必蒙羞，就是那曾经对我说：“主你的神在哪里”的人，我必亲眼看见他遭报；那时，他必被人践踏，好像街上的泥土。'),
('CNV', '弥迦书', 33, 7, 11, '必有一天，你要重建你的城墙；到那日，你的地界必扩展到远方。'),
('CNV', '弥迦书', 33, 7, 12, '那日，必有人来归你，从亚述到埃及，从埃及到大河，从这海到那海，从这山到那山，必有人来归你。'),
('CNV', '弥迦书', 33, 7, 13, '然而，大地因其中居民的缘故，又因他们行为的恶果，必一片荒凉。'),
('CNV', '弥迦书', 33, 7, 14, '求你用你的杖牧放你的子民，就是你产业的羊群，他们安然独居在树林里，在佳美的田园中；愿他们在巴珊和基列得着牧养，像古时一样。'),
('CNV', '弥迦书', 33, 7, 15, '就像你从埃及地出来的时候一样，把奇事显给我们看（按照《马索拉文本》，“把奇事显给我们看”作“我必把奇事显给他看”）。'),
('CNV', '弥迦书', 33, 7, 16, '愿万国看见，就为自己的一切势力而惭愧；愿他们用手掩口，耳朵变聋。'),
('CNV', '弥迦书', 33, 7, 17, '愿他们舔土像蛇，又像在地上腹行的动物。愿他们战战兢兢地从他们的要塞出来，带着惊慌的心来到主我们的神那里，因你的缘故而惧怕。'),
('CNV', '弥迦书', 33, 7, 18, '有何神像你，赦免罪孽，不追究产业之余民的过犯呢？他不永远怀怒，因为他喜爱怜悯。'),
('CNV', '弥迦书', 33, 7, 19, '他必再怜爱我们，把我们的罪孽都践踏在脚下，又把我们（按照《马索拉文本》，“我们”作“他们”；现参照其他抄本、《七十士译本》和其他古译本翻译）的一切罪恶都投在深海里。'),
('CNV', '弥迦书', 33, 7, 20, '你必向雅各显诚实，向亚伯拉罕施慈爱，就是古时，你起誓应许我们列祖的。'),
('CNV', '那鸿书', 34, 1, 1, '以下是对尼尼微的宣判，就是伊勒歌斯人那鸿的异象录。'),
('CNV', '那鸿书', 34, 1, 2, '主是嫉恶和施行报复的神；主施行报复，并且满怀烈怒；主向他的对头施行报复，向他的仇敌怀怒。'),
('CNV', '那鸿书', 34, 1, 3, '主不轻易发怒，可是大有能力；他绝不以有罪的为无罪。主乘着狂风暴雨而来，云彩是他脚下的尘土。'),
('CNV', '那鸿书', 34, 1, 4, '他一斥责海，海就干了；他使一切江河枯干。巴珊和迦密的树林枯槁，黎巴嫩的花卉凋残。'),
('CNV', '那鸿书', 34, 1, 5, '大山在他面前震动，小山也都融化；大地在他面前废去，世界和所有住在世上的，也都这样。'),
('CNV', '那鸿书', 34, 1, 6, '在他盛怒之下，谁能站得住呢？他的烈怒谁能受得了呢？他的忿怒像火一般喷出来，磐石在他面前都崩裂了。'),
('CNV', '那鸿书', 34, 1, 7, '主是良善的；在患难的时候，他作人的避难所；信靠他的人，他都认识。'),
('CNV', '那鸿书', 34, 1, 8, '但他必用泛滥的洪水，尽行毁灭尼尼微之地，把他的仇敌赶入黑暗之中。'),
('CNV', '那鸿书', 34, 1, 9, '尼尼微人哪，你们对主还有什么企图？他必尽行毁灭；患难必不再次来临。'),
('CNV', '那鸿书', 34, 1, 10, '他们像缠结着的荆棘，像喝醉了的酒徒，又像枯干的禾秸，全都被吞灭了。'),
('CNV', '那鸿书', 34, 1, 11, '有人从你那里出来，就是筹划奸恶的人，图谋恶事攻击主。'),
('CNV', '那鸿书', 34, 1, 12, '主这样说：尼尼微人虽然装备完整，人数众多，他们仍必被剪除，这样就完了。我既然使你受过苦，就一定不再叫你受苦了。'),
('CNV', '那鸿书', 34, 1, 13, '犹大啊！现在我必粉碎他在你身上的轭，打断你的锁链。'),
('CNV', '那鸿书', 34, 1, 14, '尼尼微啊！主已经向你下了命令：你的名字必不再传于后世；我必从你的神庙中，除掉雕刻和铸造的偶像；我必为你预备坟墓，因为你没有存在的价值。'),
('CNV', '那鸿书', 34, 1, 15, '看哪！那传报佳音、宣告和平之人的脚，已经站在山上，说：犹大啊！守你的节期，还你的愿吧！因为那奸恶的人永不会再从你中间经过；他已被彻底除灭了。（本节在《马索拉文本》为2:1）'),
('CNV', '那鸿书', 34, 2, 1, '尼尼微啊！那分散邦国的必上来攻击你，你要固守堡垒，严防要道，束紧你的腰，大大增强你的力量。（本节在《马索拉抄本》为2:2）'),
('CNV', '那鸿书', 34, 2, 2, '然而，主必恢复雅各的光荣，好像以色列的光荣一样；因为劫掠的人曾把他们劫掠一空，又把他们的葡萄枝子毁坏了。'),
('CNV', '那鸿书', 34, 2, 3, '他勇士的盾牌是红的，战士的衣服是朱红的。在他预备出击的时候，战车的钢铁闪烁如火，骑兵（“骑兵”在《马索拉文本》作“香柏木”）疾驰。'),
('CNV', '那鸿书', 34, 2, 4, '战车在街上狂奔，在广场上东奔西驰；它们看起来像火把，跑起来像闪电。'),
('CNV', '那鸿书', 34, 2, 5, '亚述王召集他的权臣，他们跌跌撞撞而来，急急忙忙走上城墙，竖起了防御的挡牌。'),
('CNV', '那鸿书', 34, 2, 6, '河闸都被打开，宫殿也给摧毁了。'),
('CNV', '那鸿书', 34, 2, 7, '王后赤身被掳去；她的宫女都哀哭，声如鸽子，各人搥胸痛哭。'),
('CNV', '那鸿书', 34, 2, 8, '自古以来，尼尼微一直都像个聚水的池，但现在居民却不断溃逃（全句或参照《七十士译本》作“尼尼微像个水池，她的水不断流出”）；虽然有人呼叫：“止住！止住！”却没有回转的。'),
('CNV', '那鸿书', 34, 2, 9, '你们劫掠银子，抢夺金子吧！积蓄的财宝无穷无尽，珍贵的器皿不可胜数。'),
('CNV', '那鸿书', 34, 2, 10, '现在却空虚、荒凉，一无所有；人心惊惶，两膝发抖，全身疼痛，面无血色。'),
('CNV', '那鸿书', 34, 2, 11, '狮子的洞穴在哪里？喂养幼狮的地方在哪里？公狮、母狮和幼狮不受惊吓之处，可以闲游的地方又在哪里呢？'),
('CNV', '那鸿书', 34, 2, 12, '公狮为幼狮撕碎足够的食物，为母狮掐死活物；把猎物塞满了它的洞，把撕碎的填满了它的穴。'),
('CNV', '那鸿书', 34, 2, 13, '万军之主说：看哪！我必攻击你，我要把你的（按照《马索拉文本》，「你的」作「她的」;现参照其他古译本翻译）战车焚烧成烟，刀剑必吞灭你的幼狮；我必从地上除去你的猎物，你使者的声音也必不再有人听见。'),
('CNV', '那鸿书', 34, 3, 1, '这流人血的城，有祸了！全城欺诈，充满劫掠；抢夺的事总不止息。'),
('CNV', '那鸿书', 34, 3, 2, '鞭声飕飕，轮声辚辚，骏马奔驰，战车颠簸跳动。'),
('CNV', '那鸿书', 34, 3, 3, '骑兵腾跃冲锋；刀剑烁烁发亮，枪矛闪闪生光；被杀的人众多，死尸成堆；尸体无数，众人都被尸体绊倒。'),
('CNV', '那鸿书', 34, 3, 4, '都因妓女多有淫行，施邪术的美丽女巫，藉着她的淫行诱惑列国，藉着她的邪术欺骗万族。'),
('CNV', '那鸿书', 34, 3, 5, '万军之主说：看哪！我必攻击你；我要把你的裙子掀到你的脸上，使万国看见你赤身露体，使列邦看见你的羞耻。'),
('CNV', '那鸿书', 34, 3, 6, '我要把污秽可憎之物抛在你身上，侮辱你，使你成为众人观看的对象。'),
('CNV', '那鸿书', 34, 3, 7, '看见你的都必逃避你，说：“尼尼微荒凉了；有谁为她悲哀呢？”我在哪里可以找到安慰你的人呢？'),
('CNV', '那鸿书', 34, 3, 8, '你比挪亚们还强吗？挪亚们位于尼罗河流域，周围有水环绕；海是她的屏障，水作她的墙垣。'),
('CNV', '那鸿书', 34, 3, 9, '古实和埃及，是她无穷的力量，弗人和路比族，是她的（按照《马索拉文本》，「她的」作「你的」;现参照《七十士译本》翻译）助手。'),
('CNV', '那鸿书', 34, 3, 10, '然而她却被迁徙，被掳去了；她的婴孩在各街头被摔死；人们为她的尊贵人抽签。她所有的达官贵人都被锁链捆着。'),
('CNV', '那鸿书', 34, 3, 11, '至于你，你必喝醉，必被隐藏；你必因仇敌的缘故，寻找避难所。'),
('CNV', '那鸿书', 34, 3, 12, '你一切堡垒，如同无花果树上初熟的果子，若被摇撼，就必落在想吃的人口中。'),
('CNV', '那鸿书', 34, 3, 13, '看哪！在你里面的人都是妇女，你境内的门户，都向仇敌敞开；你的门闩被火烧毁。'),
('CNV', '那鸿书', 34, 3, 14, '你要打水，以备围困，巩固你的堡垒，踹泥踏土，紧握砖模。'),
('CNV', '那鸿书', 34, 3, 15, '在那里火要烧灭你，刀剑要除灭你，吞吃你，好像吞吃蚱蜢一样，你只管增多如蚱蜢，加添像蝗虫，'),
('CNV', '那鸿书', 34, 3, 16, '你增加了你的商人，多过天上的星辰。蚱蜢退了壳，就飞去了。'),
('CNV', '那鸿书', 34, 3, 17, '你的领袖多如蝗虫，你的军长像一群群的蚂蚱；天凉的时候，停留在篱笆上；太阳一出，就都飞走了；没有人知道它们在什么地方。'),
('CNV', '那鸿书', 34, 3, 18, '亚述王啊！你的牧人睡觉，你的贵族安歇，你的子民分散在各山上，没有人招聚他们。'),
('CNV', '那鸿书', 34, 3, 19, '你的创伤无法医治；你受的打击非常严重。听见你这消息的，都必向你鼓掌；因为你不断行恶，谁没有受过害呢？'),
('CNV', '哈巴谷书', 35, 1, 1, '哈巴谷先知所得的默示。'),
('CNV', '哈巴谷书', 35, 1, 2, '主啊！我恳求，你不垂听，要到几时呢？我向你呼叫“有狂暴的事”，你却不拯救。'),
('CNV', '哈巴谷书', 35, 1, 3, '你为什么使我看见恶行？有奸恶的事，你为什么见而不理？毁灭和强暴在我面前，纷争和相斗常常发生。'),
('CNV', '哈巴谷书', 35, 1, 4, '因此律法不能生效（“律法不能生效”原文作“律法松懈”），公理无法彰显。因为恶人把义人包围，所以公理颠倒。'),
('CNV', '哈巴谷书', 35, 1, 5, '你们当看列国，要定睛观看，就会大大惊奇，因为在你们的日子，我要作一件事，即使有人说了出来，你们也不会相信。'),
('CNV', '哈巴谷书', 35, 1, 6, '就是要兴起迦勒底人，那残忍凶暴的民；他们遍行全地，占领别人的家园。'),
('CNV', '哈巴谷书', 35, 1, 7, '他们恐怖可怕，自以为义，趾高气扬。'),
('CNV', '哈巴谷书', 35, 1, 8, '他们的马比豹更快，比晚上的豺狼更猛。他们的骑兵奔驰，自远而来；他们如鹰飞翔，迅速吞噬。'),
('CNV', '哈巴谷书', 35, 1, 9, '他们定着脸面向前，齐来行暴，掳获战俘多如尘沙。'),
('CNV', '哈巴谷书', 35, 1, 10, '他们戏弄君王，以掌权的为笑柄；他们嗤笑一切城堡，筑垒攻取；'),
('CNV', '哈巴谷书', 35, 1, 11, '然后扫荡如风吹过。他们是有罪的，因他们以自己的势力为神。'),
('CNV', '哈巴谷书', 35, 1, 12, '主我的神，我的圣者啊！你不是自古就有的吗？我们不会死的。主啊！你派他们行审判。磐石啊！你立他们施惩罚。'),
('CNV', '哈巴谷书', 35, 1, 13, '你的眼目纯洁，不看邪恶，不能坐视奸恶；为什么见行诡诈的人而不理？恶人吞灭比自己公义的人，你为什么缄默呢？'),
('CNV', '哈巴谷书', 35, 1, 14, '你竟使人像海里的鱼，像无人管辖的爬行的动物。'),
('CNV', '哈巴谷书', 35, 1, 15, '迦勒底人既用钩把他们钓起来，用网拖走，用鱼网收聚在一处，就欢喜快乐，'),
('CNV', '哈巴谷书', 35, 1, 16, '向自己的网献祭，对鱼网烧香，因他们藉此收获丰富，饮食充裕。'),
('CNV', '哈巴谷书', 35, 1, 17, '这样，他们倒空自己的网，毫不留情地继续杀戮列国。'),
('CNV', '哈巴谷书', 35, 2, 1, '我要站在哨岗，立在城楼，留心看主在我里面说什么，怎样使我答覆自己的怨诉。'),
('CNV', '哈巴谷书', 35, 2, 2, '主回答我说：“把异象写下，清楚地记在泥版上，使读的人容易明白，'),
('CNV', '哈巴谷书', 35, 2, 3, '因这异象关乎一定的日期，很快就要实现，决不徒然；纵有迟延，仍当等候，因为它一定会来到，绝不耽误。”'),
('CNV', '哈巴谷书', 35, 2, 4, '迦勒底人自高自大，心不正直；然而义人必因信得生（“必因信得生”或译：“必因他的信实得生”）。'),
('CNV', '哈巴谷书', 35, 2, 5, '财富（传统作“酒”，今照死海古卷译作“财富”）使人奸诈狂傲，不得安宁；扩张欲望，如同阴间；又像死亡，永不满足。他们招聚万国，集合万民，都归自己。'),
('CNV', '哈巴谷书', 35, 2, 6, '这些国民岂不都用譬喻、讽刺、暗语指着他们说：“那些滥得他人财物的，满载别人抵押品的，有祸了！他们这样要到几时呢？”'),
('CNV', '哈巴谷书', 35, 2, 7, '你的债主（“你的债主”或译：“咬你的”）岂不忽然起来？扰乱你的岂不醒起？你就成了他们的掳物。'),
('CNV', '哈巴谷书', 35, 2, 8, '因你抢掠多国，杀人流血，向全地各城和其中所有居民施行暴力，所以剩下的人也必抢掠你。'),
('CNV', '哈巴谷书', 35, 2, 9, '你这为自己的家积聚不义之财，在高处搭窝，以逃避灾害的，有祸了！'),
('CNV', '哈巴谷书', 35, 2, 10, '你剪除多国的民，反害了自己；你所谋算的，使你的家蒙羞。'),
('CNV', '哈巴谷书', 35, 2, 11, '石头必从墙里呼叫，梁木必在树中应声。'),
('CNV', '哈巴谷书', 35, 2, 12, '你这用人血做城，凭邪恶立镇的，有祸了！'),
('CNV', '哈巴谷书', 35, 2, 13, '众民劳碌得来的，被火焚烧；列国辛劳而得的，终归无有。这不都出于万军之主吗？'),
('CNV', '哈巴谷书', 35, 2, 14, '认识主之荣耀的知识，必充满全地，好像众水遮盖海洋一样。'),
('CNV', '哈巴谷书', 35, 2, 15, '你这请邻舍喝酒，却把毒物混入，使他醉倒，为要见他赤裸的，有祸了！'),
('CNV', '哈巴谷书', 35, 2, 16, '你满有羞辱，没有尊荣，你也喝到露出下体来吧！主右手的杯必传回来给你，使极大的羞辱取代你的尊荣。'),
('CNV', '哈巴谷书', 35, 2, 17, '因你向黎巴嫩使用暴力，杀灭惊吓野兽；又杀人流血，向全地各城和其中所有居民施行暴力，就必受到报应（“报应”原文作“遮盖”）。'),
('CNV', '哈巴谷书', 35, 2, 18, '雕刻的像有什么用处呢？不过是匠人雕刻出来的；铸造的像、虚假的教师，有什么用处呢？匠人竟倚靠自己所做，那不能说话的假神。'),
('CNV', '哈巴谷书', 35, 2, 19, '你这对木头说“起来”，对哑石说“醒吧”的人，有祸了！它怎能教导你呢？看哪！它包金镶银，里面却全无气息。'),
('CNV', '哈巴谷书', 35, 2, 20, '然而主在他的圣殿里，全地当在他面前肃静。'),
('CNV', '哈巴谷书', 35, 3, 1, '哈巴谷先知的祷告，配激动的音调。'),
('CNV', '哈巴谷书', 35, 3, 2, '主啊！我听见你的声音，惧怕你的作为；求你在这些年间复兴，在这些年间彰显，发怒的时候以怜悯为怀。'),
('CNV', '哈巴谷书', 35, 3, 3, '神由提幔而来，圣者从巴兰山临到。（细拉）他的荣光弥漫穹苍，赞美他的声音响彻大地。'),
('CNV', '哈巴谷书', 35, 3, 4, '他的辉煌如光，手中四射光芒，就在其中隐藏着能力。'),
('CNV', '哈巴谷书', 35, 3, 5, '瘟疫在他面前行走，灾病在他脚下发出。'),
('CNV', '哈巴谷书', 35, 3, 6, '他站立，震撼全地；他观看，惊散列国。永在的山崩裂，长存的岭塌陷；他的道路存到永远。'),
('CNV', '哈巴谷书', 35, 3, 7, '我看见古珊的帐棚遭难，米甸地的帐幕惊惶。'),
('CNV', '哈巴谷书', 35, 3, 8, '主啊！你骑上你的马，乘驾得胜的战车，难道是恼怒江河、向江河发怒、向海洋泄愤？'),
('CNV', '哈巴谷书', 35, 3, 9, '你的弓显露，你的箭上弦。（原文意义不明，这句参考RSV,JB等译本翻译）（细拉）你裂开大地为江河。'),
('CNV', '哈巴谷书', 35, 3, 10, '诸山见你而颤抖，众水暴流而过；深渊发声，举手高扬。'),
('CNV', '哈巴谷书', 35, 3, 11, '日月停在本位，你的箭发射如光；你的矛闪烁辉耀。'),
('CNV', '哈巴谷书', 35, 3, 12, '你激愤践踏全地，你怀怒打碎列国。'),
('CNV', '哈巴谷书', 35, 3, 13, '你出来救拔子民，拯救你所膏立的。你击打恶人的房顶，使根基全然显露（原文作“直到颈项”，这是闪族语言习用语，意即“到了极点”〔参赛8:8；诗75:5〕；另一可能是“大石”、“磐石”的意思）。（细拉）'),
('CNV', '哈巴谷书', 35, 3, 14, '你用他的枪，刺透他战士的头。他们来如暴风，把我们驱散。他们的喜好，是暗中吞噬穷人。'),
('CNV', '哈巴谷书', 35, 3, 15, '你乘马驰骋海上，大水汹涌翻腾。'),
('CNV', '哈巴谷书', 35, 3, 16, '我一听见，就全身发抖；因这声音，我嘴唇震颤。腐烂侵蚀我骨，我在站立之地战兢。我静候灾难之日，犯境的民上来。'),
('CNV', '哈巴谷书', 35, 3, 17, '无花果树纵不发芽，葡萄树不结果，橄榄树无所出，田里无收成，圈内的羊被剪除，棚里也没有牛，'),
('CNV', '哈巴谷书', 35, 3, 18, '我却要因主欢喜，以救我的神为乐。'),
('CNV', '哈巴谷书', 35, 3, 19, '主神是我的力量，他使我的脚快如母鹿的蹄，在高地上行走。交诗班长，用丝弦的乐器伴奏。'),
('CNV', '西番雅书', 36, 1, 1, '犹大王亚们的儿子约西亚在位的时候，主的话临到希西家的玄孙、亚玛利雅的曾孙、基大利的孙子、古示的儿子西番雅。'),
('CNV', '西番雅书', 36, 1, 2, '主说：“我必把万物从地上完全除灭。”'),
('CNV', '西番雅书', 36, 1, 3, '主说：“我必除灭人类、牲畜、空中飞鸟、海里的鱼。我必使恶人跌倒，我必把人类从地上剪除。'),
('CNV', '西番雅书', 36, 1, 4, '我必伸手攻击犹大，攻击耶路撒冷所有的居民。我必从这地方除掉巴力所余下的，除掉拜偶像的祭司的名字，以及主的祭司；'),
('CNV', '西番雅书', 36, 1, 5, '就是那些在房顶上敬拜天上万象的，那些敬拜主，指着他起誓，又指着玛勒公起誓的，'),
('CNV', '西番雅书', 36, 1, 6, '那些转离不跟从主的，不寻找主，也不求问他的。”'),
('CNV', '西番雅书', 36, 1, 7, '你要在主神面前肃静！因为主的日子临近了，因为主已经预备了祭物，把自己所请来的人分别为圣。'),
('CNV', '西番雅书', 36, 1, 8, '“到了我主献祭的日子，我必惩罚首领和王子，惩罚所有穿外族衣服的人。'),
('CNV', '西番雅书', 36, 1, 9, '到那日，我必惩罚所有跳过门槛的，所有使强暴和欺诈充满主人房屋的。”'),
('CNV', '西番雅书', 36, 1, 10, '主说：“到那日，必有呼叫的声音从鱼门发出来，必有哀号从新区发出来，必有崩裂巨响从山间发出来。'),
('CNV', '西番雅书', 36, 1, 11, '玛革提施的居民哪！你们要哀号，因为所有的商人都灭亡了；所有称银子的都被剪除了。'),
('CNV', '西番雅书', 36, 1, 12, '那时，我必提灯搜查耶路撒冷，惩罚那些在罪中陶然自得的人（“在罪中陶然自得”直译是“沉淀在酒渣上”）。这些人心里说：‘主必不赐福，也不降祸。’'),
('CNV', '西番雅书', 36, 1, 13, '他们的财宝必成为掠物，他们的房屋必变为废墟。他们建造房屋，却不得住在其中；他们栽植葡萄园，却不得喝所出的酒。”'),
('CNV', '西番雅书', 36, 1, 14, '主的大日子临近了，临近了，来得非常快速。听！主的日子的声音。在那日，勇士要哀痛地号叫。'),
('CNV', '西番雅书', 36, 1, 15, '那日是忿怒的日子，是困苦艰难的日子，是荒废凄凉的日子，是黑暗幽冥的日子，是密云漆黑的日子，'),
('CNV', '西番雅书', 36, 1, 16, '是吹号吶喊，要攻打坚城，进击高耸城楼的日子。'),
('CNV', '西番雅书', 36, 1, 17, '我要使人受困苦，以致他们像瞎子行走，因为他们得罪主。他们的鲜血必倒出，如倒灰尘一样，他们的身体必被遗弃像粪土一般。'),
('CNV', '西番雅书', 36, 1, 18, '在主发怒的日子，他们的金银也不能救他们，全地都要被他的妒火吞灭；因为他要彻底毁灭地上所有的居民，真是可怕的毁灭。'),
('CNV', '西番雅书', 36, 2, 1, '无耻的国民哪！你们要聚集，要聚集起来。'),
('CNV', '西番雅书', 36, 2, 2, '趁命令还没有发出，日子还没有像风前的糠秕一般吹过，主的烈怒还没有临到你们，主忿怒的日子还没有临到你们以前，你们要聚集起来！'),
('CNV', '西番雅书', 36, 2, 3, '地上所有谦卑的人，就是遵守主典章的人哪！你们要寻求主，你们要寻求公义，寻求谦卑。在主忿怒的日子，你们或许得以隐藏起来。'),
('CNV', '西番雅书', 36, 2, 4, '因为迦萨必被抛弃，亚实基伦必成荒场，亚实突的居民必在晌午被赶走；以革伦必连根拔起来。'),
('CNV', '西番雅书', 36, 2, 5, '住在沿海地带的人，基列提的国民哪！你们有祸了。这是主攻击你们的话：“非利士人之地迦南啊！我必毁灭你，使你那里没有人居住。'),
('CNV', '西番雅书', 36, 2, 6, '沿海的地必成为草场、牧人的洞穴、羊群的圈栏。'),
('CNV', '西番雅书', 36, 2, 7, '这地必归给犹大家的余民；他们要在那里放牧，晚上他们躺卧在亚实基伦的房舍中；因为主他们的神必眷顾他们，使他们从被掳之地归回。”'),
('CNV', '西番雅书', 36, 2, 8, '我听见了摩押人的辱骂之言，听见了亚扪人的毁谤之语，他们辱骂我的子民，又自夸自大侵犯他们的境界。'),
('CNV', '西番雅书', 36, 2, 9, '因此，万军之主以色列的神说：“我指着我的永生起誓：摩押人必要像所多玛，亚扪人必定像蛾摩拉，成为刺草和盐坑之所，永远荒凉之地。我余下的子民必掳掠他们，我国中所余的要得着他们为业。”'),
('CNV', '西番雅书', 36, 2, 10, '由于他们的狂傲，这事就临到他们；因为他们自夸自大，辱骂万军之主的子民。'),
('CNV', '西番雅书', 36, 2, 11, '对于他们，主是可畏惧的，因为他要消灭地上一切神祇；那时，列国海岛上的居民，都各在自己的地方敬拜他。'),
('CNV', '西番雅书', 36, 2, 12, '古实人哪！你们也必被我的刀剑所杀。'),
('CNV', '西番雅书', 36, 2, 13, '主必伸手攻击北方，毁灭亚述，使尼尼微变成荒场，干旱像旷野。'),
('CNV', '西番雅书', 36, 2, 14, '群畜和各类的走兽必躺卧在其中；鹈鹕和箭猪栖宿在柱顶上；窗内有鸣叫的声音，门槛上必有荒凉；因为香柏木都要暴露出来。'),
('CNV', '西番雅书', 36, 2, 15, '这就是那欢乐安居之城，她心里曾说：“只有我，除我以外，再没有别的了。”现在怎么竟成了荒场、走兽躺卧之处呢！凡从那里经过的，都必舞手嗤笑。'),
('CNV', '西番雅书', 36, 3, 1, '这叛逆、污秽、欺压人的城有祸了！'),
('CNV', '西番雅书', 36, 3, 2, '她不听话，也不受管教；她不倚靠主，也不亲近她的神。'),
('CNV', '西番雅书', 36, 3, 3, '城中的领袖都是咆哮的狮子，城中的审判官是夜间的豺狼，什么都不留到早晨。'),
('CNV', '西番雅书', 36, 3, 4, '城中的先知都是轻浮诡诈的人；城中的祭司亵渎圣物，违犯律法。'),
('CNV', '西番雅书', 36, 3, 5, '主在城中是公义的，决不行不义的事；他每日早晨都显明公正，永不止息。不公义的人却不知廉耻。'),
('CNV', '西番雅书', 36, 3, 6, '我主已经剪除列国，他们的城楼被毁；我已经使他们的街道荒凉，以致杳无人迹；他们的城市荒废，以致无人存留，无人居住。'),
('CNV', '西番雅书', 36, 3, 7, '我说：“她定要敬畏我，接受管教。”这样，她的住所必不会照着我原定对她的惩罚被剪除。可是他们殷勤行恶，败坏了自己一切所作的。'),
('CNV', '西番雅书', 36, 3, 8, '主说：“因此，你们要等候我，等候我起来指证（按照《马索拉文本》，“指证”作“掳掠”；现参照《七十士译本》翻译）的日子，我已经决定集合万邦，召聚列国，把我的盛怒，就是我的一切烈怒，都倾倒在他们身上；因为全地都必被我的妒火吞灭。'),
('CNV', '西番雅书', 36, 3, 9, '那时我要使万民有洁净的嘴唇，他们全都可以呼求主的名，同心合意事奉主。'),
('CNV', '西番雅书', 36, 3, 10, '敬拜我的人，就是我所分散的人，必从古实河外而来，给我献上礼物。'),
('CNV', '西番雅书', 36, 3, 11, '到了那日，你必不因你背叛我所作的一切感到羞愧，因为那时我必从你中间除掉那些自高自大的人。在我的圣山上，你必不再高傲。'),
('CNV', '西番雅书', 36, 3, 12, '但我要在你中间留下谦虚卑微的人；他们必投靠主的名。'),
('CNV', '西番雅书', 36, 3, 13, '以色列的余民必不再行不义，也必不说谎；他们的口里也没有诡诈的舌头。他们吃喝躺卧，没有人惊吓他们。”'),
('CNV', '西番雅书', 36, 3, 14, '锡安的居民（“居民”原文作“女子”）哪！你们要高歌。以色列啊！你们要欢呼。耶路撒冷的居民哪！你们要满心欢喜快乐。'),
('CNV', '西番雅书', 36, 3, 15, '主已经除去你们的刑罚，赶走你们的仇敌。以色列的王，主在你们中间，你们必不再惧怕灾祸。'),
('CNV', '西番雅书', 36, 3, 16, '到了那日，必有人对耶路撒冷说：“锡安哪！不要惧怕；你的手不要下垂。'),
('CNV', '西番雅书', 36, 3, 17, '主你的神在你中间，他是施行拯救的大能者，必因你欢欣快乐，必默然爱你，而且必因你喜乐欢唱。”'),
('CNV', '西番雅书', 36, 3, 18, '“那些属你，为了切慕大会而忧愁的人，他们担当了羞辱；我必招聚他们。'),
('CNV', '西番雅书', 36, 3, 19, '看哪！那时我必对付一切苦待你的人；我必拯救那些瘸腿的，聚集那些被赶散的；在全地受羞辱的，我必使他们得称赞，有名声。'),
('CNV', '西番雅书', 36, 3, 20, '那时我必把你们领回，那时我必把你们齐集；我使你们被掳的人归回的时候，必在你们眼前，叫你们在地上的万民中得称赞，有名声。”这是主说的。'),
('CNV', '哈该书', 37, 1, 1, '大利乌王第二年六月一日，主的话藉着哈该先知临到撒拉铁的儿子、犹大省长所罗巴伯，和约撒答的儿子大祭司约书亚，说：'),
('CNV', '哈该书', 37, 1, 2, '“万军之主这样说：‘这民说，重建主殿宇的时候还没有到。’”'),
('CNV', '哈该书', 37, 1, 3, '于是，主的话临到哈该先知说：'),
('CNV', '哈该书', 37, 1, 4, '“这殿宇仍然荒废，岂是你们住在有天花板的房屋的时候吗？”'),
('CNV', '哈该书', 37, 1, 5, '现在万军之主这样说：“你们要反省自己的行为。'),
('CNV', '哈该书', 37, 1, 6, '你们撒的种多，收割的却少；你们吃，却吃不饱；你们喝，却喝不足；你们穿衣服，却穿不暖；得工钱的，却把工钱放在破袋里。”'),
('CNV', '哈该书', 37, 1, 7, '万军之主这样说：“你们要反省自己的行为。'),
('CNV', '哈该书', 37, 1, 8, '你们要上山取木材，建造殿宇；我必因此喜悦，并且得荣耀。”主说：'),
('CNV', '哈该书', 37, 1, 9, '“你们期望丰收，反倒歉收；你们收到家里的，我就吹去。”为什么呢？万军之主说：“因为我的殿宇荒废，你们各人却为自己的房屋奔驰。'),
('CNV', '哈该书', 37, 1, 10, '所以，因你们的缘故，天就不降甘露，地也不出土产。'),
('CNV', '哈该书', 37, 1, 11, '我叫干旱临到大地、群山、五谷、新酒、新油、地上的出产、人畜和人手劳碌得来的一切。”'),
('CNV', '哈该书', 37, 1, 12, '那时，撒拉铁的儿子所罗巴伯、约撒答的儿子大祭司约书亚和所有余剩的子民，都听从了主他们神的话，听从了主他们神所差来的哈该先知的话。众民在主面前都存着敬畏的心。'),
('CNV', '哈该书', 37, 1, 13, '主的使者哈该，奉主的命，对众民说：“主说：‘我与你们同在。’”'),
('CNV', '哈该书', 37, 1, 14, '于是主激发了撒拉铁的儿子、犹大省长所罗巴伯的心，和约撒答的儿子大祭司约书亚的心，以及所有余剩子民的心，他们就来兴工建造万军之主他们神的殿宇。'),
('CNV', '哈该书', 37, 1, 15, '那时是大利乌王第二年六月二十四日。'),
('CNV', '哈该书', 37, 2, 1, '七月二十一日，主的话临到哈该先知说：'),
('CNV', '哈该书', 37, 2, 2, '“你要对撒拉铁的儿子犹大省长所罗巴伯，和约撒答的儿子大祭司约书亚，以及所有余剩的子民，说：'),
('CNV', '哈该书', 37, 2, 3, '‘你们中间剩下的人，有谁见过这殿宇从前的荣耀呢？现在你们又看它怎样？岂不是视如无物一样吗？’”'),
('CNV', '哈该书', 37, 2, 4, '主说：“所罗巴伯啊！现在你要刚强。”主说：“约撒答的儿子大祭司约书亚啊！你要刚强；这地的一切子民啊！你们也要刚强，并且要作工。”万军之主说：“因为我与你们同在。'),
('CNV', '哈该书', 37, 2, 5, '这就是你们从埃及出来的时候，我与你们立约的话。现在我的灵住在你们中间；你们不要惧怕。”'),
('CNV', '哈该书', 37, 2, 6, '因为万军之主这样说：“再过不多的时候，我要震动天、地、海洋和旱地。”'),
('CNV', '哈该书', 37, 2, 7, '万军之主说：“我要震动万国，万国的珍宝就必运来；我要使这殿宇充满荣耀。”'),
('CNV', '哈该书', 37, 2, 8, '万军之主说：“银子是我的，金子也是我的。”'),
('CNV', '哈该书', 37, 2, 9, '万军之主说：“这殿宇后来的荣耀，必大过先前的荣耀。”万军之主说：“在这地方，我必赐下平安。”'),
('CNV', '哈该书', 37, 2, 10, '大利乌王第二年九月二十四日，主的话临到哈该先知说：'),
('CNV', '哈该书', 37, 2, 11, '“万军之主这样说：你要向祭司询问有关律法的事说：'),
('CNV', '哈该书', 37, 2, 12, '人若用自己的衣襟盛载圣肉，后来又使自己的衣襟触着饼、汤、酒、油或别的食物，这就算为圣吗？”祭司都回答说：“不算为圣。”'),
('CNV', '哈该书', 37, 2, 13, '哈该又说：“人若因触着尸体而成为不洁，又触着这些东西的任何一样，这就算为不洁吗？”祭司都回答说：“要算为不洁净。”'),
('CNV', '哈该书', 37, 2, 14, '于是哈该回答，说：“主说：‘这民也是这样，这国在我面前也是这样；他们手里的一切工作，都是这样；他们在那里所献的，都是不洁净的。’'),
('CNV', '哈该书', 37, 2, 15, '“现在你们要反省，从今日起回想过往，就是在主的殿还没有一块石头叠在另一块石头上面以前，'),
('CNV', '哈该书', 37, 2, 16, '那时你们怎样呢？有人到谷堆来，想得两百公斤谷，却只得一百公斤；有人到榨酒池去，想从酒槽得一百公升酒，却只得四十公升。'),
('CNV', '哈该书', 37, 2, 17, '主说：‘我用旱风、霉烂和冰雹击打你们，和你们手里的一切工作，你们还是不归向我。'),
('CNV', '哈该书', 37, 2, 18, '你们要反省，从今日起回想过往，就是自九月二十四日起，从主殿的奠基日开始，你们要反省：'),
('CNV', '哈该书', 37, 2, 19, '仓里还有种子吗？葡萄树、无花果树、石榴树和橄榄树，岂是还没有结果子吗？从今日起，我必赐福。’”'),
('CNV', '哈该书', 37, 2, 20, '同月二十四日，主的话再次临到哈该，说：'),
('CNV', '哈该书', 37, 2, 21, '“你要向犹大省长所罗巴伯说：‘我要震动天地，'),
('CNV', '哈该书', 37, 2, 22, '我必倾覆列国的宝座，消灭外族万国的势力，我必推翻战车和驾车的人；马匹和骑马的都必跌倒；各人必死在自己兄弟的刀下。’'),
('CNV', '哈该书', 37, 2, 23, '万军之主说：‘撒拉铁的儿子，我的仆人所罗巴伯啊！到那日我必提拔你。’主说：‘我必以你为印记。’万军之主说：‘因为我拣选了你。’”'),
('CNV', '撒迦利亚书', 38, 1, 1, '大利乌王第二年八月，主的话临到易多的孙子、比利家的儿子撒迦利亚先知，说：'),
('CNV', '撒迦利亚书', 38, 1, 2, '“主曾对你们的列祖大发烈怒，'),
('CNV', '撒迦利亚书', 38, 1, 3, '所以，你要对众民说：‘万军之主这样说：你们要转向我（这是万军之主的宣告），我就必转向你们（这是万军之主说的）。'),
('CNV', '撒迦利亚书', 38, 1, 4, '不要效法你们的列祖那样，从前的先知呼唤他们：万军之主这样说，你们要回转，离开你们的恶道和恶行。他们却不听从，也不理会我（这是主的宣告）。'),
('CNV', '撒迦利亚书', 38, 1, 5, '你们的列祖在哪里呢？那些先知能永远活着吗？'),
('CNV', '撒迦利亚书', 38, 1, 6, '然而我吩咐我的仆人众先知的话与条例，不是已报应在你们的列祖身上吗？所以他们就回转，说：万军之主定意按着我们所作所行的对付我们，他已经这样行了。’”'),
('CNV', '撒迦利亚书', 38, 1, 7, '大利乌王第二年十一月（就是细罢特月）二十四日，主的话临到易多的孙子、比利家的儿子撒迦利亚先知，实情如下：'),
('CNV', '撒迦利亚书', 38, 1, 8, '我夜间观看，看见有一个人骑着红马，站在低洼地上的番石榴树中间；在他后面还有些红色、栗色和白色的马。'),
('CNV', '撒迦利亚书', 38, 1, 9, '我就问：“我主啊，这些是什么？”那与我说话的天使对我说：“我会指示你这些是什么。”'),
('CNV', '撒迦利亚书', 38, 1, 10, '那站在番石榴树中间的人回答：“这些就是主所差遣在遍地巡逻的。”'),
('CNV', '撒迦利亚书', 38, 1, 11, '那些骑士回报那站在番石榴树中间的主使者，说：“我们已经在遍地巡逻；看见全地都安定，一片平静。”'),
('CNV', '撒迦利亚书', 38, 1, 12, '于是主的使者说：“万军之主啊！你不怜悯耶路撒冷和犹大的城镇，要到几时呢？这七十年来，你一直恼怒它们。”'),
('CNV', '撒迦利亚书', 38, 1, 13, '主就用满有恩慈和安慰的话回答那与我说话的天使。'),
('CNV', '撒迦利亚书', 38, 1, 14, '那与我说话的天使对我说：“你要宣告：‘万军之主这样说：我为耶路撒冷和锡安心里充满嫉恨。'),
('CNV', '撒迦利亚书', 38, 1, 15, '我向那些安逸的列国大大恼怒，因为我只是稍微恼怒我的子民，他们却加深他们的祸害。'),
('CNV', '撒迦利亚书', 38, 1, 16, '因此，主这样说：我要怀着怜悯的心回到耶路撒冷，我的殿必在城中重建（这是万军之主的宣告）。绳子必拉在耶路撒冷之上。’'),
('CNV', '撒迦利亚书', 38, 1, 17, '你要再宣告：‘万军之主这样说：我的城镇必再昌盛繁荣，主必再怜悯锡安，必再拣选耶路撒冷。’”'),
('CNV', '撒迦利亚书', 38, 1, 18, '我又举目观看，看见有四个角。'),
('CNV', '撒迦利亚书', 38, 1, 19, '于是我问那与我说话的天使：“这些是什么？”他对我说：“这些就是把犹大、以色列和耶路撒冷赶散的角。”'),
('CNV', '撒迦利亚书', 38, 1, 20, '主又使我看见四个匠人。'),
('CNV', '撒迦利亚书', 38, 1, 21, '于是我说：“这些人来作什么？”那天使回答：“他们就是把犹大赶散的角，以致没有一人可以抬起头来；但这些匠人要来惊吓列国，打掉他们的角；这些列国就是曾经举起他们的角攻击犹大地，把犹大地的人赶散的。”（本章第18~21节在《马索拉文本》为2:1~4）'),
('CNV', '撒迦利亚书', 38, 2, 1, '我又举目观看，看见一人手里拿着量度用的绳子。（本节在《马索拉文本》为2:5）'),
('CNV', '撒迦利亚书', 38, 2, 2, '我问他：“你到哪里去？”他对我说：“我要去量度耶路撒冷，看看有多宽，有多长。”'),
('CNV', '撒迦利亚书', 38, 2, 3, '那与我说话的天使离去的时候，另有一位天使迎着他来，'),
('CNV', '撒迦利亚书', 38, 2, 4, '对他说：“你快跑去告诉那年轻人：‘耶路撒冷必有人居住，像没有城墙规限的田野，因为城中的人和牲畜很多。'),
('CNV', '撒迦利亚书', 38, 2, 5, '主说：我要作耶路撒冷四围的火墙和城中的荣耀。’”'),
('CNV', '撒迦利亚书', 38, 2, 6, '“嗨！嗨！你们要从北方之地逃走（这是主的宣告），因为我过去曾把你们分散在天的四方。”这是主的宣告。'),
('CNV', '撒迦利亚书', 38, 2, 7, '主说：“嗨！与巴比伦的居民同住的锡安的人民哪！逃跑吧！”'),
('CNV', '撒迦利亚书', 38, 2, 8, '万军之主这样说，得了荣耀之后，他差遣我去攻击那些劫掠你们的列国，因为凡触摸你们的，就是触摸他眼中的瞳人。'),
('CNV', '撒迦利亚书', 38, 2, 9, '看哪！我要向他们挥动我的手，他们就必成了自己奴仆的掠物。这样，你们就知道万军之主差遣了我。'),
('CNV', '撒迦利亚书', 38, 2, 10, '“锡安的居民（“居民”原文作“女子”）哪！你们要欢呼快乐，因为我要来住在你们中间。”这是主的宣告。'),
('CNV', '撒迦利亚书', 38, 2, 11, '到那日，许多国家要归附主，作他的（“他的”原文作“我的”）子民，他要（“他要”原文作“我要”）住在你们中间。你们就知道万军之主差遣了我到你们那里去。'),
('CNV', '撒迦利亚书', 38, 2, 12, '主必再得着犹大作他在圣地的业分，他必再拣选耶路撒冷。'),
('CNV', '撒迦利亚书', 38, 2, 13, '全人类都当在主面前肃静，因为他从自己圣洁的居所被激动起来了。'),
('CNV', '撒迦利亚书', 38, 3, 1, '主又使我看见大祭司约书亚站在主的使者面前，撒但也站在约书亚右边控告他。'),
('CNV', '撒迦利亚书', 38, 3, 2, '主对撒但说：“撒但哪！主斥责你，那拣选了耶路撒冷的主斥责你。这个人不是从火中抽出来的一根柴吗？”'),
('CNV', '撒迦利亚书', 38, 3, 3, '那时，约书亚穿着污秽的衣服，站在使者的面前。'),
('CNV', '撒迦利亚书', 38, 3, 4, '使者吩咐那些侍立在他面前的说：“你们要脱去他污秽的衣服。”又对约书亚说：“看哪！我已经除去了你的罪孽，要给你穿上华美的礼服。”'),
('CNV', '撒迦利亚书', 38, 3, 5, '我说：“你们要把洁净的冠冕戴在他的头上。”他们就把洁净的冠冕戴在他的头上，又给他穿上华美的衣服。那时，主的使者正在旁边站着。'),
('CNV', '撒迦利亚书', 38, 3, 6, '主的使者劝戒约书亚说：'),
('CNV', '撒迦利亚书', 38, 3, 7, '“万军之主这样说：‘你若遵行我的道，谨守我的吩咐，你就必治理我的家，看守我的院子，我必赐你特权，可以在这些侍立在我面前的使者中间自由出入。'),
('CNV', '撒迦利亚书', 38, 3, 8, '大祭司约书亚啊！你和坐在你面前的众同伴都要听，（他们都是预表将来奇事的人，）我必使我的仆人，就是大卫的苗裔出生。'),
('CNV', '撒迦利亚书', 38, 3, 9, '看我在约书亚面前所立的石头，在这一块石头上有七眼。看哪！我要亲自雕琢这石头（这是万军之主的宣告）。在一日之内，我要除去这地的罪孽。'),
('CNV', '撒迦利亚书', 38, 3, 10, '到那日（这是万军之主的宣告），你们各人要邀请自己的邻舍来，坐在葡萄树下和无花果树下。’”'),
('CNV', '撒迦利亚书', 38, 4, 1, '那与我说话的天使回来唤醒我，我好像人在睡眠中被人唤醒一样。'),
('CNV', '撒迦利亚书', 38, 4, 2, '他对我说：“你看见了什么？”我回答：“我看见一个金灯台，整个是金的，顶上有一个盆子，并有七盏灯；顶上的灯有七个灯嘴。'),
('CNV', '撒迦利亚书', 38, 4, 3, '盆子旁边有两棵橄榄树，一棵在右边，一棵在左边。”'),
('CNV', '撒迦利亚书', 38, 4, 4, '我问那与我说话的天使，说：“我主啊，这些是什么？”'),
('CNV', '撒迦利亚书', 38, 4, 5, '那与我说话的天使回答我说：“你不知道这些是什么意思吗？”我说：“我主啊，我不知道。”'),
('CNV', '撒迦利亚书', 38, 4, 6, '他对我说：“这是主对所罗巴伯所说的话：‘不是倚靠权势，不是倚靠能力，而是倚靠我的灵。’这是万军之主说的。'),
('CNV', '撒迦利亚书', 38, 4, 7, '大山啊！你算得什么？你在所罗巴伯面前必夷为平地！他必安放那块平顶的石头，必有欢呼的声音说：‘愿恩惠、恩惠归与这殿（“这殿”原文作“她”）。’”'),
('CNV', '撒迦利亚书', 38, 4, 8, '主的话又临到我说：'),
('CNV', '撒迦利亚书', 38, 4, 9, '“所罗巴伯的手奠立了这殿的根基，他的手也必完成这工；这样，你就知道万军之主差遣了我到你们这里来。'),
('CNV', '撒迦利亚书', 38, 4, 10, '谁藐视这日子，以为所作的是小事呢？他们看见所罗巴伯手里拿着测锤，就必欢喜。”是主的这七眼，遍察全地。'),
('CNV', '撒迦利亚书', 38, 4, 11, '我又再问那天使：“在这灯台左右的两棵橄榄树是什么意思？”'),
('CNV', '撒迦利亚书', 38, 4, 12, '我又问他：“在两根流出金色油的金管子旁边的两根橄榄树枝，究竟是什么意思？”'),
('CNV', '撒迦利亚书', 38, 4, 13, '他回答我：“你不知道这些是什么意思吗？”我说：“我主啊，我不知道。”'),
('CNV', '撒迦利亚书', 38, 4, 14, '他说：“这是两位受膏者（“受膏者”或译：“供应新油的人”），是服事全地之主的。”'),
('CNV', '撒迦利亚书', 38, 5, 1, '我又举目观看，看见有一卷飞行的书卷。'),
('CNV', '撒迦利亚书', 38, 5, 2, '他问我：“你看见什么？”我回答：“我看见一卷飞行的书卷，长十公尺，宽五公尺。”'),
('CNV', '撒迦利亚书', 38, 5, 3, '他对我说：“这是向全地发出的咒诅：凡偷盗的必照着书卷这面所写的被清除；凡起假誓的必照着那面所记的被清除。'),
('CNV', '撒迦利亚书', 38, 5, 4, '万军之主说：‘我要使这书卷出去，进入盗贼的家和指着我的名起假誓之人的家，这书卷必留在他的家中，要把他家里的木料和石头都毁灭（这是万军之主说的）。’”'),
('CNV', '撒迦利亚书', 38, 5, 5, '那与我说话的天使又出来对我说：“你要举目观看，看看这出来的是什么？”'),
('CNV', '撒迦利亚书', 38, 5, 6, '我说：“这是什么？”他回答：“这出来的是个量器。”他又说：“这是他们在全地上的罪孽（“罪孽”有抄本作“样子”）。”'),
('CNV', '撒迦利亚书', 38, 5, 7, '看哪！量器的圆形铅盖被揭开，有一个妇人坐在量器里面。'),
('CNV', '撒迦利亚书', 38, 5, 8, '天使说：“这是罪恶。”然后他把那妇人掷回量器中，又把那铅盖丢在量器的口上。'),
('CNV', '撒迦利亚书', 38, 5, 9, '我又举目观看，看见有两个妇人出来。她们有翅膀，好像鹳鸟的翅膀；她们的翅膀之下有风。她们把那量器抬起，抬到天地之间。'),
('CNV', '撒迦利亚书', 38, 5, 10, '我问那与我说话的天使：“她们要把量器带到哪里去呢？”'),
('CNV', '撒迦利亚书', 38, 5, 11, '他回答我：“要在示拿地为那量器建造房子；房子预备好了，就在那里把它安放在它自己的地方。”'),
('CNV', '撒迦利亚书', 38, 6, 1, '我又举目观看，看见有四辆战车从两座山中间出来，那两座山是铜山。'),
('CNV', '撒迦利亚书', 38, 6, 2, '第一辆战车套着红马，第二辆套着黑马，'),
('CNV', '撒迦利亚书', 38, 6, 3, '第三辆套着白马，第四辆套着有斑点的马；这些马都很雄壮。'),
('CNV', '撒迦利亚书', 38, 6, 4, '于是我问那与我说话的天使：“我主啊，这些是什么意思？”'),
('CNV', '撒迦利亚书', 38, 6, 5, '天使回答我：“这些是天的四风（“风”或译：“灵”），是从侍立在全地之主面前出来的。”'),
('CNV', '撒迦利亚书', 38, 6, 6, '套着黑马的车出来，往北方之地去；套着白马的车出来，跟在它们后面（“跟在它们后面”或译：“往西方去”）；套着有斑点的马的车出来，往南方之地去。'),
('CNV', '撒迦利亚书', 38, 6, 7, '这些雄壮的马出来，切望在全地走遍各处；天使说：“你们去吧，只管在全地走遍各处。”它们就在全地走遍各处。'),
('CNV', '撒迦利亚书', 38, 6, 8, '他又呼唤我，对我说：“你看，那些出来往北方之地去的，已经在北方之地使我心灵的忿怒平息下来。”'),
('CNV', '撒迦利亚书', 38, 6, 9, '主的话临到我，说：'),
('CNV', '撒迦利亚书', 38, 6, 10, '“你要从黑玳、多比雅和耶大雅手中收取被掳的人奉献的金银；他们已经从巴比伦回来了。你要即日去，进入西番雅的儿子约西亚的家里。'),
('CNV', '撒迦利亚书', 38, 6, 11, '你要拿这金银来做冠冕，戴在约撒答的儿子大祭司约书亚的头上，'),
('CNV', '撒迦利亚书', 38, 6, 12, '告诉他说：‘万军之主这样说：看哪！有一个人名叫大卫的苗裔，他必从自己的地方生长起来，并要建造主的殿。'),
('CNV', '撒迦利亚书', 38, 6, 13, '他必建造主的殿，必得尊荣；他必坐在宝座上执掌王权，又必在他的宝座上作祭司，使两者之间和谐共济。’”'),
('CNV', '撒迦利亚书', 38, 6, 14, '这冠冕要在主的殿中给希连（“希连”有古译本作“黑玳”）、多比雅、耶大雅和西番雅的儿子贤（“贤”有古译本作“约西亚”）作记念。'),
('CNV', '撒迦利亚书', 38, 6, 15, '远方的人也要来建造主的殿，你们就知道万军之主差遣了我到你们这里来。你们若留心听从主你们神的话，这事必定成就。'),
('CNV', '撒迦利亚书', 38, 7, 1, '大利乌王第四年九月，就是基斯流月初四日，主的话临到撒迦利亚。'),
('CNV', '撒迦利亚书', 38, 7, 2, '那时，伯特利人差派了沙利色、利坚米勒和他的随从，去恳求主施恩。'),
('CNV', '撒迦利亚书', 38, 7, 3, '他们询问万军之主殿里的众祭司，以及众先知说：“我们还要在五月哭泣和禁食，像我们这许多年来所行的吗？”'),
('CNV', '撒迦利亚书', 38, 7, 4, '万军之主的话临到我，说：'),
('CNV', '撒迦利亚书', 38, 7, 5, '“你要告诉这地的人民和祭司说：‘这七十年来，你们在五月和七月禁食哀哭，岂是真的为我禁食呢？'),
('CNV', '撒迦利亚书', 38, 7, 6, '你们吃，你们喝，岂不是为你们自己吃，为你们自己喝吗？'),
('CNV', '撒迦利亚书', 38, 7, 7, '这些话主不是曾藉着从前的先知宣告了吗？那时，耶路撒冷和四围的城镇都有人居住，很是兴旺，南地和高地都有人居住。’”'),
('CNV', '撒迦利亚书', 38, 7, 8, '主的话又临到撒迦利亚说：'),
('CNV', '撒迦利亚书', 38, 7, 9, '“万军之主曾这样告诉你们的列祖说：‘你们要执法公正，各人要以慈爱和怜悯待自己的兄弟。'),
('CNV', '撒迦利亚书', 38, 7, 10, '寡妇、孤儿、寄居的和贫穷人，你们都不可欺压，也不可各自心里图谋恶事，陷害自己的兄弟。’'),
('CNV', '撒迦利亚书', 38, 7, 11, '但他们不肯听从，反而硬着颈项，充耳不闻（“反而硬着颈项，充耳不闻”直译是“转着固执的肩膊，使自己的耳朵发沉不听”）。'),
('CNV', '撒迦利亚书', 38, 7, 12, '他们使自己的心刚硬如金钢石，不肯听从律法和万军之主藉着他的灵、透过从前的先知所说的话。因此，万军之主非常忿怒。'),
('CNV', '撒迦利亚书', 38, 7, 13, '我曾呼唤他们，他们不听；照样，将来他们呼求我，我也不听。这是万军之主说的。'),
('CNV', '撒迦利亚书', 38, 7, 14, '我用旋风把他们吹散到他们不认识的列国去，他们留下的地就荒凉了，以致无人来往经过，因为他们使这美好之地变为荒凉了。”'),
('CNV', '撒迦利亚书', 38, 8, 1, '万军之主的话临到我说：'),
('CNV', '撒迦利亚书', 38, 8, 2, '“万军之主这样说：‘我十分热爱锡安；我为锡安大发烈怒。’'),
('CNV', '撒迦利亚书', 38, 8, 3, '主这样说：‘我要返回锡安，住在耶路撒冷里面；耶路撒冷必称为“信实之城”，万军之主的山必称为“圣山”。’'),
('CNV', '撒迦利亚书', 38, 8, 4, '“万军之主这样说：‘年老的男女必再坐在耶路撒冷的街上；他们因为年纪老迈，各人都手拿拐杖。'),
('CNV', '撒迦利亚书', 38, 8, 5, '城里的街上必满了男孩女孩，在街上嬉戏。’'),
('CNV', '撒迦利亚书', 38, 8, 6, '“万军之主这样说：‘在那些日子，这事在这余剩的子民眼中被视为不可能的奇迹，在我眼中也视为不可能吗？’这是万军之主的宣告。'),
('CNV', '撒迦利亚书', 38, 8, 7, '“万军之主这样说：‘看哪！我必从日出之地和日落之地拯救我的子民。'),
('CNV', '撒迦利亚书', 38, 8, 8, '我要把他们领回来，让他们住在耶路撒冷；他们要作我的子民，我也要凭着信实和公义作他们的神。’'),
('CNV', '撒迦利亚书', 38, 8, 9, '“万军之主这样说：‘在万军之主的殿奠立了根基，预备建造的日子，你们这些在当时听过众先知亲口宣告这些话的人，现在你们的手务要刚强。'),
('CNV', '撒迦利亚书', 38, 8, 10, '因为在那些日子以前，人作工是没有工价的，牲畜也是这样，并且因有敌人的缘故，人出入就没有平安，我也使众人互相攻击。'),
('CNV', '撒迦利亚书', 38, 8, 11, '但现在我待这些余剩的子民必不像从前的日子那样（这是万军之主的宣告）。'),
('CNV', '撒迦利亚书', 38, 8, 12, '因为五谷必生长繁茂，葡萄树必结果子，地土必出土产，天也必降下甘露，我要使这些余剩的子民承受这一切。'),
('CNV', '撒迦利亚书', 38, 8, 13, '犹大家和以色列家啊！你们从前怎样在万国中成为可咒诅的，将来，我也要怎样拯救你们，使你们成为祝福。你们不要惧怕，你们的手务要刚强。’'),
('CNV', '撒迦利亚书', 38, 8, 14, '“万军之主这样说：‘你们的列祖惹我发怒的时候，我曾定意降祸在你们身上，并没有改变心意（这是万军之主说的）；'),
('CNV', '撒迦利亚书', 38, 8, 15, '照样，在这些日子里，我定意恩待耶路撒冷和犹大家。你们不要惧怕。'),
('CNV', '撒迦利亚书', 38, 8, 16, '你们应当行这些事：你们各人要与邻舍说真话，在你们的城门口要凭着诚实施行带来和平的审判。'),
('CNV', '撒迦利亚书', 38, 8, 17, '你们各人不要心里图谋恶事，彼此陷害，也不可好起假誓，因为这些都是我所恨恶的。’这是主的宣告。”'),
('CNV', '撒迦利亚书', 38, 8, 18, '万军之主的话临到我，说：'),
('CNV', '撒迦利亚书', 38, 8, 19, '“万军之主这样说：‘四月的禁食、五月的禁食、七月的禁食和十月的禁食都要变为犹大家欢喜快乐的日子和欢乐的节期。所以，你们要喜爱诚实与和平。’'),
('CNV', '撒迦利亚书', 38, 8, 20, '“万军之主这样说：‘将来还有万族的人和多个城市的居民要来。'),
('CNV', '撒迦利亚书', 38, 8, 21, '一城的居民到另一城去，对他们说：我们快去恳求主施恩，求告万军之主；我自己也去。'),
('CNV', '撒迦利亚书', 38, 8, 22, '必有很多的民族和强大的国家前来，在耶路撒冷求告万军之主，恳求他施恩。’'),
('CNV', '撒迦利亚书', 38, 8, 23, '“万军之主这样说：‘在那些日子，必有十个说不同方言，来自列国的人，紧抓住一个犹大人的衣襟，说：让我们与你们同去吧，因为我们听见神与你们同在。’”'),
('CNV', '撒迦利亚书', 38, 9, 1, '以下是主的默示：主的话临到哈得拉地，落在大马士革（世人的眼睛和以色列各支派都仰望主），'),
('CNV', '撒迦利亚书', 38, 9, 2, '又临到大马士革边界的哈马，还有推罗、西顿，尽管她们有极大的智慧。'),
('CNV', '撒迦利亚书', 38, 9, 3, '推罗为自己建造了堡垒，堆积银子，多如尘沙，积聚精金，多如街上的泥土。'),
('CNV', '撒迦利亚书', 38, 9, 4, '看哪！主必夺去她的一切，摧毁她海上的势力，她必被火吞灭。'),
('CNV', '撒迦利亚书', 38, 9, 5, '亚实基伦看见了，就必害怕；迦萨看见了也必非常痛苦；以革伦因失去盼望而蒙羞。迦萨的王必灭亡，亚实基伦必不再有人居住。'),
('CNV', '撒迦利亚书', 38, 9, 6, '混杂的种族（“混杂的种族”或译：“私生子”）必住在亚实突，我必除掉非利士人的骄傲。'),
('CNV', '撒迦利亚书', 38, 9, 7, '我必除去他们口中的血，和他们牙齿间可憎之物。余剩下来的人要归于我们的神，像犹大的一族；以革伦人也必像耶布斯人一样。'),
('CNV', '撒迦利亚书', 38, 9, 8, '我必在我的家四围安营，不容敌军出入往来；欺压人的不能再侵犯我的子民，因我现在亲眼看顾他们。'),
('CNV', '撒迦利亚书', 38, 9, 9, '锡安的居民哪！要大大喜乐。耶路撒冷的居民（“居民”原文作“女子”）哪！应当欢呼。看哪！你的王来到你这里了，他是公义的，是得胜的。他又是温柔的，他骑着驴，骑的是小驴。'),
('CNV', '撒迦利亚书', 38, 9, 10, '我必从以法莲除掉战车，从耶路撒冷除掉战马。争战的弓必被除掉，他要向列国宣讲和平。他的统治权必从这海延伸到那海，从幼发拉底河直到地极。'),
('CNV', '撒迦利亚书', 38, 9, 11, '锡安哪！至于你，因着我与你立约的血，我把你中间被囚禁的人从无水的坑里释放出来。'),
('CNV', '撒迦利亚书', 38, 9, 12, '你们被囚仍有盼望的人哪！要归回保障。今天我要宣告：我必加倍补偿给你。'),
('CNV', '撒迦利亚书', 38, 9, 13, '我把犹大作我手上拉开的弓，把以法莲作我弓上的箭。锡安哪！我必激动你的众子，去攻击希腊的众子；我必使你像勇士的刀剑。'),
('CNV', '撒迦利亚书', 38, 9, 14, '主必在他子民头上显现，他的箭必像闪电一般射出；主神必吹起号角，乘着南方的暴风而行。'),
('CNV', '撒迦利亚书', 38, 9, 15, '万军之主必护卫他们，他们要用投石器投石吞灭和制伏敌人；他们必喝血，并且喧嚷，像喝醉了酒一样；他们必像献祭用的碗盛满了血，又像祭坛的角，沾满了血。'),
('CNV', '撒迦利亚书', 38, 9, 16, '到那日，主他们的神必拯救他们，待他的子民好像羊群一样，因为他们必像冠冕上的宝石，闪耀在他的地上。'),
('CNV', '撒迦利亚书', 38, 9, 17, '他们将是多么的善，多么的美；五谷和新酒使少男少女生气蓬勃。'),
('CNV', '撒迦利亚书', 38, 10, 1, '在春雨的季节，你们要向主求雨。主闪发雷电，给人降雨，使各人的田地生长蔬菜。'),
('CNV', '撒迦利亚书', 38, 10, 2, '因为偶像所说的是空言，占卜者所见的是虚谎，他们所说的是假梦，只给人空洞的安慰。因此，众人都如羊没有牧人，流离困苦。'),
('CNV', '撒迦利亚书', 38, 10, 3, '“我的怒气要向这些牧人发作，我要惩罚那些公山羊。（因为万军之主眷顾他的羊群犹大家，使他们像战场上雄赳赳的战马。）'),
('CNV', '撒迦利亚书', 38, 10, 4, '房角石、帐棚桩、作战的弓和所有的统治者，都从犹大而出。'),
('CNV', '撒迦利亚书', 38, 10, 5, '他们必像勇士，在战场上把仇敌践踏在街上的泥土中，他们必争战，因为主与他们同在，他们必使敌方的骑士羞愧。'),
('CNV', '撒迦利亚书', 38, 10, 6, '我要使犹大家强盛起来，我必拯救约瑟家。我要使他们归回，因为我怜悯他们；他们好像未遭我弃绝一样，因为我是主他们的神，我必应允他们。'),
('CNV', '撒迦利亚书', 38, 10, 7, '以法莲人必像勇士，他们心中快乐，好像饮了酒一样；他们的子孙看见了，也必快乐；他们的心必因主欢乐。'),
('CNV', '撒迦利亚书', 38, 10, 8, '我要向他们吹哨子，招聚他们，因为我救赎了他们。他们的人数要增多，像从前一样。'),
('CNV', '撒迦利亚书', 38, 10, 9, '虽然我把他们散播在万民中，他们仍要在远方记念我；他们与他们的子孙都要存活，并且归回。'),
('CNV', '撒迦利亚书', 38, 10, 10, '我要使他们从埃及地归回，从亚述地招聚他们，带他们到基列地和黎巴嫩山，却仍不够容纳他们。'),
('CNV', '撒迦利亚书', 38, 10, 11, '他必经过苦难的海，击打海中的波浪，尼罗河的深处也都要干涸；亚述的骄傲必降为卑；埃及的权势要过去。'),
('CNV', '撒迦利亚书', 38, 10, 12, '我必使我的子民因主而强盛，他们要奉主的名行事为人。”这是主的宣告。'),
('CNV', '撒迦利亚书', 38, 11, 1, '黎巴嫩哪！敞开你的门户，好让火吞灭你的香柏树。'),
('CNV', '撒迦利亚书', 38, 11, 2, '松树啊！哀号吧，因为香柏树已经倒下，雄壮的树木都毁坏了；巴珊的橡树啊！哀号吧，因为茂密的树林被砍下来了。'),
('CNV', '撒迦利亚书', 38, 11, 3, '听牧人们哀号的声音，因为他们荣美的草场毁坏了；听少壮狮子吼叫的声音，因为约旦河边的丛林毁坏了。'),
('CNV', '撒迦利亚书', 38, 11, 4, '主我的神这样说：“你要牧养这将被宰杀的羊群。'),
('CNV', '撒迦利亚书', 38, 11, 5, '那些买了它们的宰杀它们，也不算为有罪；那些卖它们的说：‘主是应当称颂的，因我成了富足的人。’它们的牧人并不怜恤它们。'),
('CNV', '撒迦利亚书', 38, 11, 6, '因此我必不再怜恤这地的居民（这是主的宣告）。看哪！我把他们各人交在他的邻舍和君王的手中。他们必摧毁这地，我必不救这地的居民脱离他们的手。”'),
('CNV', '撒迦利亚书', 38, 11, 7, '于是，我牧养这将被宰杀的羊群，就是羊群中最困苦的；我取了两根杖，一根我称为“恩宠”，另一根称为“联合”。这样我就牧养了羊群。'),
('CNV', '撒迦利亚书', 38, 11, 8, '在一个月之内我除灭了三个牧人。我的心厌烦他们，他们的心也讨厌我。'),
('CNV', '撒迦利亚书', 38, 11, 9, '我就说：“我不再牧养你们了；那将要死的，让他死吧！那将要被除灭的，让他被除灭吧；那些余剩的，让他们彼此吞食对方的肉吧！”'),
('CNV', '撒迦利亚书', 38, 11, 10, '然后，我拿起我那根称为“恩宠”的杖，把它折断，表示要废除我与万民所立的约；'),
('CNV', '撒迦利亚书', 38, 11, 11, '那约就在当日废除了。这样，那些仰望我的困苦羊群，就知道这是主的话。'),
('CNV', '撒迦利亚书', 38, 11, 12, '我对他们说：“你们若看为美，就给我工资；不然，就算了。”于是，他们称了三十块银子作我的工资。'),
('CNV', '撒迦利亚书', 38, 11, 13, '那时，主对我说：“你要把银子丢给陶匠。”那银子就是他们认为我应得的高价。我就拿了那三十块银子，在主的殿里丢给陶匠了。'),
('CNV', '撒迦利亚书', 38, 11, 14, '我又折断那称为“联合”的另一根杖，表示要废除犹大和以色列之间的手足之情。'),
('CNV', '撒迦利亚书', 38, 11, 15, '主又对我说：“你去取愚昧牧人的装备来。'),
('CNV', '撒迦利亚书', 38, 11, 16, '因为我要在这地兴起一个牧人；那些快要丧亡的他不看顾，失散的他不寻找，受伤的他不医治，强壮的他不喂养，他却要吃肥羊的肉，撕掉它们的蹄子。'),
('CNV', '撒迦利亚书', 38, 11, 17, '“那丢弃羊群的无用牧人有祸了！愿刀剑落在他的膀臂和他的右眼上；愿他的膀臂全然枯槁，愿他的右眼完全失明！”'),
('CNV', '撒迦利亚书', 38, 12, 1, '以下是主的默示，这是主论到以色列的话（是主的宣告，他铺张诸天，奠定大地的根基，造成人里面的灵）：'),
('CNV', '撒迦利亚书', 38, 12, 2, '“看哪！我要使耶路撒冷成为令周围万族喝醉的杯；耶路撒冷被围困的时候，犹大也必受到攻击。'),
('CNV', '撒迦利亚书', 38, 12, 3, '到那日，我要使耶路撒冷对万族来说像一块沉重的石头，举起它的必受重伤；地上的列国必聚集起来攻击耶路撒冷。'),
('CNV', '撒迦利亚书', 38, 12, 4, '到那日（这是主的宣告），我要击打所有的马匹，使它们惊恐，击打骑马的人，使他们疯狂；我必开眼看顾犹大家，我要击打万族所有的马匹，使它们瞎眼。'),
('CNV', '撒迦利亚书', 38, 12, 5, '那时，犹大的族长必心里说：‘耶路撒冷的居民，靠万军之主他们的神得着力量。’'),
('CNV', '撒迦利亚书', 38, 12, 6, '“到那日，我必使犹大的族长好像木柴中的火盆，又好像禾捆中的火把；他们必向左右吞灭周围的万族，但耶路撒冷的人必仍在城中原处安居。'),
('CNV', '撒迦利亚书', 38, 12, 7, '“主必先拯救犹大的帐棚，免得大卫家的荣耀和耶路撒冷居民的荣耀胜过犹大。'),
('CNV', '撒迦利亚书', 38, 12, 8, '到那日，主必保护耶路撒冷的居民；他们中间最软弱的，到那日必好像大卫，大卫家必好像神，好像行在他们前面的主使者。'),
('CNV', '撒迦利亚书', 38, 12, 9, '到那日，我必歼灭所有前来攻打耶路撒冷的列国。'),
('CNV', '撒迦利亚书', 38, 12, 10, '“我必把那恩慈与恳求的灵倾注在大卫家和耶路撒冷居民的身上。他们必仰望我，就是他们所刺的；他们要为他哀哭，好像丧独生子；他们必为他悲痛，好像丧长子。'),
('CNV', '撒迦利亚书', 38, 12, 11, '到那日，耶路撒冷必有极大的哀哭，像在米吉多平原的哈达临门的哀哭一样。'),
('CNV', '撒迦利亚书', 38, 12, 12, '全地都要哀哭，一家一家独在一处哀哭。大卫家独在一处，他们的妇女也独在一处；拿单家独在一处，他们的妇女也独在一处；'),
('CNV', '撒迦利亚书', 38, 12, 13, '利未家独在一处，他们的妇女也独在一处；示每家独在一处，他们的妇女也独在一处；'),
('CNV', '撒迦利亚书', 38, 12, 14, '其余的各家都是一家一家独在一处，他们的妇女也独在一处。”'),
('CNV', '撒迦利亚书', 38, 13, 1, '“到那日，必有一个泉源，为大卫家和耶路撒冷的居民开放，洗除他们的罪恶和不洁。'),
('CNV', '撒迦利亚书', 38, 13, 2, '“到那日（这是万军之主的宣告），我必从这地除掉偶像的名号，它们不再被人记念；我也必从这地除去假先知和污秽的灵。'),
('CNV', '撒迦利亚书', 38, 13, 3, '如果有人再说预言，他的亲生父母必对他说：‘你不该活着，因为你奉主的名说谎。’他说预言的时候，他的亲生父母必把他刺死。'),
('CNV', '撒迦利亚书', 38, 13, 4, '“到那日，假先知说预言的时候，每一个都必因自己所论的异象而羞愧；他们必不再穿兽毛衣服欺骗人。'),
('CNV', '撒迦利亚书', 38, 13, 5, '那时他必说：‘我不是先知，只是耕地的人；因为我自幼以来，就被卖为奴。’'),
('CNV', '撒迦利亚书', 38, 13, 6, '如果有人问他：‘怎么在你胸口上（“胸口上”原文作“两手之间”）有这些伤痕呢？’他就必回答：‘这些是在爱我的人家里所受的伤。’'),
('CNV', '撒迦利亚书', 38, 13, 7, '“刀剑哪，醒来吧！攻击我的牧人，我的同伴，（这是万军之主的宣告。）要击打牧人，羊群就分散；我也要转过手来，攻击小羊。'),
('CNV', '撒迦利亚书', 38, 13, 8, '全地的人必有三分之二被除灭，只有三分之一存留下来。（这是主的宣告。）'),
('CNV', '撒迦利亚书', 38, 13, 9, '我必使这三分之一经火试炼。我要炼净他们，像炼净银子一样；我要试炼他们，像试炼金子一样。他们必呼求我的名，我必应允他们。我要说：‘他们是我的子民。’他们也要说：‘主是我们的神。’”'),
('CNV', '撒迦利亚书', 38, 14, 1, '看哪！主的日子快到，人要在你中间分取你的掠物。'),
('CNV', '撒迦利亚书', 38, 14, 2, '因为我必招聚列国与耶路撒冷作战，城必被占领，房屋被抢掠，妇女被强奸。城中的居民必有半数被掳去，剩下的人民必不会从这城里被剪除。'),
('CNV', '撒迦利亚书', 38, 14, 3, '那时，主要出去，与那些国家作战，像他以前在战争的日子作战一样。'),
('CNV', '撒迦利亚书', 38, 14, 4, '到那日，他的脚必站在对着耶路撒冷，在东面的橄榄山上；这橄榄山必从中间裂开，由东至西成为极大的山谷。山的一半向北挪移，一半向南挪移。'),
('CNV', '撒迦利亚书', 38, 14, 5, '你们要经由我的山谷逃跑，因为山谷必伸展到亚萨；你们要逃跑，好像在犹大王乌西雅年间逃避大地震一样。主我的神必来临，所有的圣者都与他（“与他”《马索拉文本》作“与你”）同来。'),
('CNV', '撒迦利亚书', 38, 14, 6, '到那日，必没有光、寒冷和严霜。'),
('CNV', '撒迦利亚书', 38, 14, 7, '那将是独特的一天，只有主知道；那天不再分白昼和黑夜，因为在晚上仍有光明。'),
('CNV', '撒迦利亚书', 38, 14, 8, '到那日，必有活水从耶路撒冷流出来；一半流往东海，另一半流往西海；冬天夏天都是这样。'),
('CNV', '撒迦利亚书', 38, 14, 9, '主必作全地的王；到那日，人人都承认主是独一无二的，他的名也是独一无二的。'),
('CNV', '撒迦利亚书', 38, 14, 10, '全地，从迦巴直到耶路撒冷南方的临门，都要变成平原；但耶路撒冷仍必屹然耸立，从便雅悯门到第一门的地方，到角门，又从哈楠业楼到王的榨酒池，都在原处。'),
('CNV', '撒迦利亚书', 38, 14, 11, '城中必有人居住，必不再有毁灭的咒诅，耶路撒冷的人必安然居住。'),
('CNV', '撒迦利亚书', 38, 14, 12, '这是主用来击打那些与耶路撒冷争战的万族的灾疫：他们双脚仍然站地的时候，他们的肌肉必腐烂，他们的眼球必在眼眶里腐烂，他们的舌头必在口腔中腐烂。'),
('CNV', '撒迦利亚书', 38, 14, 13, '到那日，主必使他们大大慌乱，他们各人互相抓住对方的手，并举起手来互相攻击。'),
('CNV', '撒迦利亚书', 38, 14, 14, '犹大也必在耶路撒冷争战；四围列国的财物都必被收聚起来，有极多的金子、银子和衣服。'),
('CNV', '撒迦利亚书', 38, 14, 15, '照样，像这类的灾疫也必临到马匹、骡子、骆驼、驴和在营中的一切牲畜身上。'),
('CNV', '撒迦利亚书', 38, 14, 16, '所有前来攻击耶路撒冷的列国中剩下的人，必年年上来敬拜大君王万军之主，并且守住棚节。'),
('CNV', '撒迦利亚书', 38, 14, 17, '地上的万族中，凡是不上耶路撒冷敬拜大君王万军之主的，就必没有雨降给他们。'),
('CNV', '撒迦利亚书', 38, 14, 18, '埃及族若不上来参加，就必没有雨降给他们，这就是主用来击打那些不上来守住棚节的列国的灾祸。'),
('CNV', '撒迦利亚书', 38, 14, 19, '这就是埃及的刑罚，也是所有不上来守住棚节的列国的惩罚。'),
('CNV', '撒迦利亚书', 38, 14, 20, '到那日，马的铃铛上必有“归主为圣”这句话；主殿里的锅必好像祭坛前献祭用的碗一样。'),
('CNV', '撒迦利亚书', 38, 14, 21, '耶路撒冷和犹大所有的锅都必归万军之主为圣；献祭的，都必来取这些锅，用来煮祭肉。到那日，在万军之主的殿中，必不再有商人（“商人”原文作“迦南人”）。'),
('CNV', '玛拉基书', 39, 1, 1, '以下是主藉玛拉基对以色列宣判的话。'),
('CNV', '玛拉基书', 39, 1, 2, '主说：“我爱你们。”你们却说：“你怎样爱了我们呢？”主说：“以扫不是雅各的哥哥吗？我却爱雅各，'),
('CNV', '玛拉基书', 39, 1, 3, '恶以扫。我使以扫的山地荒凉，把他的产业给了旷野的豺狼。”'),
('CNV', '玛拉基书', 39, 1, 4, '如果以东说：“我们虽然遭破坏，但仍要把废墟重建起来。”万军之主这样说：“他们只管建造，我却要拆毁。人要称他们为罪恶的境地，为主永远恼怒的子民。”'),
('CNV', '玛拉基书', 39, 1, 5, '你们要亲眼看见，也要亲自说：“主在以色列的境地以外，必被尊为大。”'),
('CNV', '玛拉基书', 39, 1, 6, '万军之主对你们说：“藐视我名的祭司啊！儿子尊敬父亲，仆人敬畏主人。我若是父亲，我该受的尊敬在哪里呢？我若是主人，我应得的敬畏在哪里呢？”你们却说：“我们怎样藐视了你的名呢？”'),
('CNV', '玛拉基书', 39, 1, 7, '“你们把污秽的食物献在我的坛上，你们竟说：‘我们怎样污秽了你的坛呢？’因你们以为主的桌子是可以藐视的。”'),
('CNV', '玛拉基书', 39, 1, 8, '万军之主说：“你们把瞎眼的献为祭，这不是恶吗？你们把瘸腿的和有病的献上，这不是罪吗？你把这样的礼物献给你的省长，他会喜欢你或是悦纳你的礼物吗？”'),
('CNV', '玛拉基书', 39, 1, 9, '现在，你们要向神求情，好使他恩待我们。这污秽的祭物，既是你们经手献的，他还能悦纳你们吗？万军之主说：'),
('CNV', '玛拉基书', 39, 1, 10, '“真愿你们当中有人把殿门关上，免得你们在我的坛上徒然点火。”万军之主说：“我不喜欢你们，也不从你们手中收纳礼物。”'),
('CNV', '玛拉基书', 39, 1, 11, '万军之主说：“从日出到日落的地方，我的名在列国中为大；在各处都有人向我的名烧香，献上洁净的礼物，因为我的名在列国中为大。”'),
('CNV', '玛拉基书', 39, 1, 12, '万军之主说：“你们却亵渎了我，因你们以为主的桌子是污秽的，桌上的食物也是可藐视的。'),
('CNV', '玛拉基书', 39, 1, 13, '你们又说：‘唉，真麻烦！’你们就嗤之以鼻。”主说：“你们把抢来的、瘸腿的和有病的带来作礼物，我怎能从你们的手中收受呢？”'),
('CNV', '玛拉基书', 39, 1, 14, '万军之主说：“凡以家畜中公的许了愿，却又诡诈地拿有残疾的献给主，那人当受咒诅；因为我是大君王，我的名在列国中是可敬畏的。”'),
('CNV', '玛拉基书', 39, 2, 1, '祭司啊！现在这命令是给你们的。'),
('CNV', '玛拉基书', 39, 2, 2, '万军之主说：“你们若不听从，若不放在心上，不把荣耀归给我的名，我就使咒诅临到你们中间，我要咒诅你们应得的福分，并且已经咒诅了，因为你们没有把这命令放在心上。'),
('CNV', '玛拉基书', 39, 2, 3, '我要斥责你们的子孙，也要把粪涂抹在你们的脸上，就是节期祭牲的粪；人要把你们抬到粪堆去。”'),
('CNV', '玛拉基书', 39, 2, 4, '万军之主说：“这样，你们就知道是我把这命令给你们，使我与利未所立的约得以存留。'),
('CNV', '玛拉基书', 39, 2, 5, '我与他所立的是生命和平安的约，也把这些赐给了他。我要使他敬畏我，又畏惧我的名。'),
('CNV', '玛拉基书', 39, 2, 6, '在他的口中有真理的教训，在他的嘴里也没有不义；他以平安和正直与我同行，使许多人回头离开罪孽。”'),
('CNV', '玛拉基书', 39, 2, 7, '祭司的嘴当保存知识，人要从他的口中寻求教训，因为他是万军主的使者。'),
('CNV', '玛拉基书', 39, 2, 8, '万军之主说：“你们却偏离了正路，使许多人在律法上跌倒；你们也破坏了我与利未所立的约。'),
('CNV', '玛拉基书', 39, 2, 9, '因此，我也使你们在众人面前被藐视、受轻看，因为你们不遵守我的道，在律法上徇人的情面。”'),
('CNV', '玛拉基书', 39, 2, 10, '我们不是同有一位父吗？不是同一位神创造我们吗？为什么我们各人对自己的兄弟不忠，亵渎我们列祖的约呢？'),
('CNV', '玛拉基书', 39, 2, 11, '犹大人行了诡诈，在以色列和耶路撒冷中作了可憎的事；因为犹大人亵渎主所爱的圣所，娶了事奉外族神的女子为妻。'),
('CNV', '玛拉基书', 39, 2, 12, '行这事的，无论是主动的，或是附从的（“无论是主动的，或是附从的”直译是“叫醒的、答应的”），连那献礼物给万军主的，主必把那人从雅各的帐棚中除掉。'),
('CNV', '玛拉基书', 39, 2, 13, '你们又行了这事：使眼泪、哀哭和呻吟盖满了主的坛，因为主不再垂看礼物，也不喜悦从你们手中收纳。'),
('CNV', '玛拉基书', 39, 2, 14, '你们还问：“为什么呢？”因为主在你和你年轻时所娶的妻子中间作证；她是你的伴侣，是你立约的妻子，你竟对她不忠！'),
('CNV', '玛拉基书', 39, 2, 15, '神所作的不是一个吗？其余的气息都是属于他的。那一个寻求什么呢？就是神的子孙。（本节原文意思不确定）所以要谨守你们的灵性，不可对年轻时所娶的妻子不忠。'),
('CNV', '玛拉基书', 39, 2, 16, '主以色列的神说：“我恨恶休妻和以强暴待妻子。”万军之主说：“所以要谨守你们的灵性，不可行诡诈的事。”'),
('CNV', '玛拉基书', 39, 2, 17, '你们用自己的言语使主厌烦，你们还说：“我们怎样使他厌烦呢？”因为你们说：“作恶的，主都看为善，并且喜悦他们。”或说：“公义的神在哪里呢？”'),
('CNV', '玛拉基书', 39, 3, 1, '万军之主说：“看哪！我派我的使者，在我前面预备道路；你们所寻求的主，必忽然进入他的殿；你们所爱慕立约的使者，就要来到。”'),
('CNV', '玛拉基书', 39, 3, 2, '可是，他来的日子，谁能当得起呢？他显现的时候，谁能站立得住呢？因为他像炼金之人的火，又像漂布之人的碱。'),
('CNV', '玛拉基书', 39, 3, 3, '他必坐着，像熬炼和洁净银子的人；他必洁净利未人，炼净他们像炼净金银一样。这样，他们就会凭公义献礼物给主。'),
('CNV', '玛拉基书', 39, 3, 4, '那时，犹大和耶路撒冷所献的礼物，必蒙主悦纳，正如古时的日子，也像往昔之年一样。'),
('CNV', '玛拉基书', 39, 3, 5, '万军之主说：“我必临近你们施行审判；我要快快指证那些行邪术的、犯奸淫的、起假誓的、在工钱上欺压雇工的、欺压孤儿寡妇的、屈枉寄居的和不敬畏我的。”'),
('CNV', '玛拉基书', 39, 3, 6, '万军之主说：“因为我主是不改变的，所以你们雅各的子孙也不会灭没。'),
('CNV', '玛拉基书', 39, 3, 7, '“从你们列祖的日子以来，你们就偏离了我的律例而不遵守。现在你们要转向我，我就必转向你们。你们还问：‘我们要怎样回转呢？’'),
('CNV', '玛拉基书', 39, 3, 8, '人怎可抢夺神之物呢？你们却抢夺属我之物，竟还问：‘我们抢夺了你的什么呢？’就是抢夺了当纳的十分之一和当献的祭物。'),
('CNV', '玛拉基书', 39, 3, 9, '你们要受严厉的咒诅，因你们全国的人都抢夺了属我之物。”'),
('CNV', '玛拉基书', 39, 3, 10, '万军之主说：“你们要把当纳的十分之一，全部送入仓库，使我家中有粮；藉此试验我，看我是不是为你们敞开天窗，把福气倒给你们，直到充足有余呢。”'),
('CNV', '玛拉基书', 39, 3, 11, '万军之主说：“我必为你们斥责那吞吃者，不容他毁坏你们地上的果实，也不让你们田间的葡萄在未熟以先就掉下来。”'),
('CNV', '玛拉基书', 39, 3, 12, '万军之主说：“万国都要称你们为有福，因为你们的地必成为喜乐之地。”'),
('CNV', '玛拉基书', 39, 3, 13, '主说：“你们用无礼的话顶撞我。你们还问：‘我们用什么话顶撞了你呢？’'),
('CNV', '玛拉基书', 39, 3, 14, '你们说：‘事奉神是白费的；遵守他的吩咐，在万军之主面前哀痛而行，有什么益处呢？'),
('CNV', '玛拉基书', 39, 3, 15, '现在我们称骄傲的人为有福，作恶的人得建立；他们虽然试探神，却得以逃脱。’”'),
('CNV', '玛拉基书', 39, 3, 16, '那时，敬畏主的人彼此谈论，主也留意细听；在他面前有记录册，记录那些敬畏主和思念他名的人。'),
('CNV', '玛拉基书', 39, 3, 17, '万军之主说：“在我施行作为的日子，他们要属我，作特别的产业；我必怜恤他们，好像人怜恤那服事自己的儿子一样。'),
('CNV', '玛拉基书', 39, 3, 18, '那时，你们就要再看出义人与恶人、事奉神的人和不事奉他的人之间有什么分别。”'),
('CNV', '玛拉基书', 39, 4, 1, '万军之主说：“看哪！那日来到，像烧着的火炉一样；骄傲的和作恶的，都必成为碎秸；那要来的日子，必把他们烧尽，不给他们留下一根一枝。'),
('CNV', '玛拉基书', 39, 4, 2, '可是，对你们敬畏我名的人，必有公义的太阳升起来；它的光线有医治的功能；你们必出来跳跃，像栏里的肥牛犊。”'),
('CNV', '玛拉基书', 39, 4, 3, '万军之主说：“你们必践踏恶人；在我施行作为的日子，他们必在你们脚掌之下成为尘土。'),
('CNV', '玛拉基书', 39, 4, 4, '“你们要谨记我仆人摩西的律法，就是我在何烈山为以色列众人所吩咐他的律例和典章。'),
('CNV', '玛拉基书', 39, 4, 5, '“看哪！在主大而可畏的日子来到以先，我必差派以利亚先知到你们那里去。'),
('CNV', '玛拉基书', 39, 4, 6, '他要使父亲的心转向儿女，儿女的心转向父亲，免得我来击打这地，以至完全毁灭。”（本章第1~6节在《马索拉文本》为3:19~24）'),
('CNV', '马太福音', 40, 1, 1, '大卫的子孙，亚伯拉罕的后裔，耶稣基督的家谱：'),
('CNV', '马太福音', 40, 1, 2, '亚伯拉罕生以撒，以撒生雅各，雅各生犹大和他的兄弟，'),
('CNV', '马太福音', 40, 1, 3, '他玛给犹大生了法勒斯和谢拉，法勒斯生希斯仑，希斯仑生亚兰，'),
('CNV', '马太福音', 40, 1, 4, '亚兰生亚米拿达，亚米拿达生拿顺，拿顺生撒门，'),
('CNV', '马太福音', 40, 1, 5, '喇合给撒门生了波阿斯，路得给波阿斯生了俄备得，俄备得生耶西，'),
('CNV', '马太福音', 40, 1, 6, '耶西生大卫王。乌利亚的妻子给大卫生了所罗门，'),
('CNV', '马太福音', 40, 1, 7, '所罗门生罗波安，罗波安生亚比雅，亚比雅生亚撒，'),
('CNV', '马太福音', 40, 1, 8, '亚撒生约沙法，约沙法生约兰，约兰生乌西雅，'),
('CNV', '马太福音', 40, 1, 9, '乌西雅生约坦，约坦生亚哈斯，亚哈斯生希西家，'),
('CNV', '马太福音', 40, 1, 10, '希西家生玛拿西，玛拿西生亚们，亚们生约西亚，'),
('CNV', '马太福音', 40, 1, 11, '犹太人被掳到巴比伦的时候，约西亚生耶哥尼雅和他的兄弟。'),
('CNV', '马太福音', 40, 1, 12, '被掳到巴比伦以后，耶哥尼雅生撒拉铁，撒拉铁生所罗巴伯，'),
('CNV', '马太福音', 40, 1, 13, '所罗巴伯生亚比玉，亚比玉生以利亚敬，以利亚敬生亚所，'),
('CNV', '马太福音', 40, 1, 14, '亚所生撒督，撒督生亚金，亚金生以律，'),
('CNV', '马太福音', 40, 1, 15, '以律生以利亚撒，以利亚撒生马但，马但生雅各，'),
('CNV', '马太福音', 40, 1, 16, '雅各生约瑟，就是马利亚的丈夫；那称为基督的耶稣，是马利亚所生的。'),
('CNV', '马太福音', 40, 1, 17, '这样，从亚伯拉罕到大卫，一共是十四代；从大卫到被掳到巴比伦的时候，也是十四代；从被掳到巴比伦的时候到基督，又是十四代。'),
('CNV', '马太福音', 40, 1, 18, '耶稣基督的降生是这样的：耶稣的母亲马利亚许配了约瑟，他们还没有成亲，马利亚就从圣灵怀了孕。'),
('CNV', '马太福音', 40, 1, 19, '她丈夫约瑟是个义人，不愿张扬使她受辱，就打算暗中与她解除婚约。'),
('CNV', '马太福音', 40, 1, 20, '他一直想着这些事，主的使者就在梦中向他显现，说：“大卫的子孙约瑟，只管放胆把你的妻子马利亚迎娶过来，因为她怀的孕是从圣灵来的。'),
('CNV', '马太福音', 40, 1, 21, '她必生一个儿子，你要给他起名叫耶稣，因为他要把自己的子民从罪恶中拯救出来。”'),
('CNV', '马太福音', 40, 1, 22, '这整件事的发生，是要应验主藉着先知所说的：'),
('CNV', '马太福音', 40, 1, 23, '“必有童女怀孕生子，他的名要叫以马内利。”以马内利就是“神与我们同在”的意思。'),
('CNV', '马太福音', 40, 1, 24, '约瑟睡醒了，就照着主的使者所吩咐的，把妻子迎娶过来；'),
('CNV', '马太福音', 40, 1, 25, '只是在孩子出生以前，并没有与她同房。约瑟给孩子起名叫耶稣。'),
('CNV', '马太福音', 40, 2, 1, '希律王执政的时候，耶稣生在犹太的伯利恒。那时，有几个星象家﹙“星象家”或译：“智者。﹚从东方来到耶路撒冷，'),
('CNV', '马太福音', 40, 2, 2, '说：“那生下来作犹太人的王的在哪里？我们看见他的星出现，特来朝拜他。”'),
('CNV', '马太福音', 40, 2, 3, '希律王听见了就心里不安，全耶路撒冷的居民也是这样。'),
('CNV', '马太福音', 40, 2, 4, '他就召集所有的祭司长和民间的经学家，问他们基督应该生在哪里。'),
('CNV', '马太福音', 40, 2, 5, '他们回答：“在犹太的伯利恒。因为有先知在经上这样说：'),
('CNV', '马太福音', 40, 2, 6, '‘犹大地的伯利恒啊！你在犹大的领袖中，并不是最小的，因为必有一位领袖从你那里出来，牧养我的子民以色列。’”'),
('CNV', '马太福音', 40, 2, 7, '希律暗中把星象家召来，仔细查问他们，那颗星什么时候出现，'),
('CNV', '马太福音', 40, 2, 8, '然后派他们到伯利恒去，说：“你们去细心寻访那小孩，找到了就向我报告，好叫我也去拜他。”'),
('CNV', '马太福音', 40, 2, 9, '他们听命去了。他们在东方看见的那颗星，忽然在他们前头，领他们到那小孩所在的地方，就在上头停住了。'),
('CNV', '马太福音', 40, 2, 10, '他们看见那颗星，欢喜极了；'),
('CNV', '马太福音', 40, 2, 11, '进了房子，看见小孩和他母亲马利亚，就俯伏拜他，并且打开宝盒，把黄金、乳香、没药作礼物献给他。'),
('CNV', '马太福音', 40, 2, 12, '后来他们在梦中得着指示不要回到希律那里去，就从别的路回乡去了。'),
('CNV', '马太福音', 40, 2, 13, '他们走了以后，主的使者在梦中向约瑟显现，说：“起来，带着孩子和他母亲逃到埃及去，留在那里，直到我再指示你，因为希律要寻找这孩子，把他杀掉。”'),
('CNV', '马太福音', 40, 2, 14, '约瑟就起来，连夜带着孩子和他母亲往埃及去，'),
('CNV', '马太福音', 40, 2, 15, '住在那里，直到希律死了，为的是要应验主藉先知所说的：“我从埃及召我的儿子出来。”'),
('CNV', '马太福音', 40, 2, 16, '希律见自己被星象家愚弄了，就大怒，于是照着他从星象家所问得的日子，下令把伯利恒和附近地方，两岁及以下的小孩全都杀死。'),
('CNV', '马太福音', 40, 2, 17, '这就应验了耶利米先知所说的：'),
('CNV', '马太福音', 40, 2, 18, '“在拉玛听见有声音，是痛哭、极大哀号的声音；拉结为她的儿女哀哭，不肯受安慰，因为他们都不在了。”'),
('CNV', '马太福音', 40, 2, 19, '希律死后，在埃及，主的使者在梦中向约瑟显现，'),
('CNV', '马太福音', 40, 2, 20, '说：“那些要杀害这孩子的人已经死了。起来，带着孩子和他母亲回以色列地去吧。”'),
('CNV', '马太福音', 40, 2, 21, '约瑟就起来，带着小孩子和他母亲回到以色列地。'),
('CNV', '马太福音', 40, 2, 22, '只是听见亚基老接续他父亲希律作了犹太王，他就不敢到犹太地去；又在梦中得了指示，于是往加利利境去，'),
('CNV', '马太福音', 40, 2, 23, '来到拿撒勒城住下，这样就应验了先知所说的：“他必称为拿撒勒人。”'),
('CNV', '马太福音', 40, 3, 1, '那时，施洗的约翰出来，在犹太的旷野传道，'),
('CNV', '马太福音', 40, 3, 2, '说：“天国近了，你们应当悔改。”'),
('CNV', '马太福音', 40, 3, 3, '以赛亚先知所说：“在旷野有呼喊者的声音：‘预备主的道，修直他的路！’”就是指着这约翰说的。'),
('CNV', '马太福音', 40, 3, 4, '约翰身穿骆驼毛的衣服，腰束皮带，吃的是蝗虫和野蜜。'),
('CNV', '马太福音', 40, 3, 5, '耶路撒冷、犹太全地和约旦河一带的人都出来到他那里去，'),
('CNV', '马太福音', 40, 3, 6, '承认自己的罪，在约旦河里受了他的洗。'),
('CNV', '马太福音', 40, 3, 7, '约翰看见许多法利赛人和撒都该人来到他施洗的地方，就对他们说：“毒蛇所生的啊，谁指示你们逃避那将要来的忿怒呢？'),
('CNV', '马太福音', 40, 3, 8, '应当结出果子来，与悔改的心相称。'),
('CNV', '马太福音', 40, 3, 9, '你们心里不要以为：‘我们有亚伯拉罕作我们的祖宗。’我告诉你们，神能从这些石头中给亚伯拉罕兴起后裔来。'),
('CNV', '马太福音', 40, 3, 10, '现在斧头已经放在树根上，所有不结好果子的树，就砍下来，丢在火里。'),
('CNV', '马太福音', 40, 3, 11, '我用水给你们施洗，表示你们悔改；但在我以后要来的那一位，能力比我更大，我就是替他提鞋也没有资格。他要用圣灵与火给你们施洗。'),
('CNV', '马太福音', 40, 3, 12, '他手里拿着簸箕，要扬净麦场，把麦子收进仓里，却用不灭的火把糠秕烧尽。”'),
('CNV', '马太福音', 40, 3, 13, '那时，耶稣从加利利来到约旦河约翰那里，要受他的洗。'),
('CNV', '马太福音', 40, 3, 14, '约翰想要阻止他，说：“我应该受你的洗，你却到我这里来吗？”'),
('CNV', '马太福音', 40, 3, 15, '耶稣回答：“暂且这样作吧。我们理当这样履行全部的义。”于是约翰答应了他。'),
('CNV', '马太福音', 40, 3, 16, '耶稣受了洗，立刻从水中上来；忽然，天为他开了，他看见神的灵，好像鸽子降下来，落在他身上；'),
('CNV', '马太福音', 40, 3, 17, '又有声音从天上来，说：“这是我的爱子，我所喜悦的。”'),
('CNV', '马太福音', 40, 4, 1, '随后，耶稣被圣灵带到旷野，受魔鬼的试探。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '马太福音', 40, 4, 2, '耶稣禁食了四十昼夜，就饿了，'),
('CNV', '马太福音', 40, 4, 3, '试探者前来对他说：“你若是神的儿子，就吩咐这些石头变成食物吧！”'),
('CNV', '马太福音', 40, 4, 4, '耶稣回答：“经上记着：‘人活着，不是单靠食物，更要靠神口里所出的一切话。’”'),
('CNV', '马太福音', 40, 4, 5, '随后，魔鬼带耶稣进了圣城，使他站在殿的最高处，'),
('CNV', '马太福音', 40, 4, 6, '对他说：“你若是神的儿子，就跳下去吧！因为经上记着：‘神为了你，会吩咐自己的使者用手托住你，免得你的脚碰到石头。’”'),
('CNV', '马太福音', 40, 4, 7, '耶稣对他说：“经上又记着：‘不可试探主你的神。’”'),
('CNV', '马太福音', 40, 4, 8, '最后，魔鬼带耶稣上了一座极高的山，把世界各国和各国的荣华都指给他看。'),
('CNV', '马太福音', 40, 4, 9, '并且对他说：“你只要跪下来拜我，我就把这一切都给你。”'),
('CNV', '马太福音', 40, 4, 10, '但耶稣说：“撒但，走开！经上记着：‘当拜主你的神，单要事奉他。’”'),
('CNV', '马太福音', 40, 4, 11, '于是魔鬼离开了耶稣，有天使前来服事他。'),
('CNV', '马太福音', 40, 4, 12, '耶稣听见约翰被捕，就往加利利去。'),
('CNV', '马太福音', 40, 4, 13, '他又离开拿撒勒，往西布伦和拿弗他利境内近海的迦百农去，住在那里，'),
('CNV', '马太福音', 40, 4, 14, '为了要应验以赛亚先知所说的：'),
('CNV', '马太福音', 40, 4, 15, '“西布伦地、拿弗他利地，沿海之路，约旦河外，外族人的加利利啊！'),
('CNV', '马太福音', 40, 4, 16, '住在黑暗中的人民，看见了大光；死亡幽暗之地的居民，有光照亮他们。”'),
('CNV', '马太福音', 40, 4, 17, '从那时起，耶稣就开始传道，说：“天国近了，你们应当悔改。”'),
('CNV', '马太福音', 40, 4, 18, '耶稣在加利利海边行走的时候，看见兄弟二人，就是名叫彼得的西门和他的弟弟安得烈，正在把网撒到海里去；他们是渔夫。'),
('CNV', '马太福音', 40, 4, 19, '耶稣就对他们说：“来跟从我，我要使你们作得人的渔夫。”'),
('CNV', '马太福音', 40, 4, 20, '他们立刻撇下网，跟从了他。'),
('CNV', '马太福音', 40, 4, 21, '耶稣又往前走，看见另一对兄弟，就是西庇太的儿子雅各和他的兄弟约翰，正和父亲西庇太在船上整理鱼网，他就呼召他们。'),
('CNV', '马太福音', 40, 4, 22, '他们立刻离了船，别了父亲，跟从了耶稣。'),
('CNV', '马太福音', 40, 4, 23, '耶稣走遍加利利，在各会堂里教导人，宣扬天国的福音，医治民间各种疾病、各种病症。'),
('CNV', '马太福音', 40, 4, 24, '他的名声传遍了叙利亚全地，人们就把一切患病的，就是患各种疾病、疼痛、鬼附、癫痫、瘫痪的，都带到他面前，他就医好他们。'),
('CNV', '马太福音', 40, 4, 25, '于是有许多人从加利利、低加波利、耶路撒冷、犹太和约旦河东来跟从耶稣。'),
('CNV', '马太福音', 40, 5, 1, '耶稣看见群众，就上了山；他坐下之后，门徒来到他跟前，'),
('CNV', '马太福音', 40, 5, 2, '他就开口教训他们：'),
('CNV', '马太福音', 40, 5, 3, '“心灵贫乏的人有福了，因为天国是他们的。'),
('CNV', '马太福音', 40, 5, 4, '哀痛的人有福了，因为他们必得安慰。'),
('CNV', '马太福音', 40, 5, 5, '温柔的人有福了，因为他们必承受地土。'),
('CNV', '马太福音', 40, 5, 6, '爱慕公义如饥如渴的人有福了，因为他们必得饱足。'),
('CNV', '马太福音', 40, 5, 7, '怜悯人的人有福了，因为他们必蒙怜悯。'),
('CNV', '马太福音', 40, 5, 8, '内心清洁的人有福了，因为他们必看见神。'),
('CNV', '马太福音', 40, 5, 9, '使人和平的人有福了，因为他们必称为神的儿子。'),
('CNV', '马太福音', 40, 5, 10, '为义遭受迫害的人有福了，因为天国是他们的。'),
('CNV', '马太福音', 40, 5, 11, '人若因我的缘故辱骂你们，迫害你们，并且捏造各样坏话毁谤你们，你们就有福了。'),
('CNV', '马太福音', 40, 5, 12, '你们应该欢喜快乐，因为你们在天上的赏赐是大的；在你们以前的先知，他们也曾这样迫害。'),
('CNV', '马太福音', 40, 5, 13, '“你们是地上的盐；如果盐失了味，怎能使它再咸呢？结果毫无用处，唯有丢在外面任人践踏。'),
('CNV', '马太福音', 40, 5, 14, '你们是世上的光。建在山上的城是无法隐藏的；'),
('CNV', '马太福音', 40, 5, 15, '人点了灯，不会放在量器底下，而是放在灯台上，就照亮一家人。'),
('CNV', '马太福音', 40, 5, 16, '照样，你们的光也应当照在人前，让他们看见你们的好行为，又颂赞你们在天上的父。'),
('CNV', '马太福音', 40, 5, 17, '“你们不要以为我来是要废除律法和先知；我来不是要废除，而是要完成。'),
('CNV', '马太福音', 40, 5, 18, '我实在告诉你们，就算天地过去，律法的一点一画也不会废去，全部都要成就。'),
('CNV', '马太福音', 40, 5, 19, '因此，无论谁废除诫命中最小的一条，又这样教导人，他在天国中必称为最小的；但若有人遵行这些诫命，并且教导人遵行，他在天国中必称为大。'),
('CNV', '马太福音', 40, 5, 20, '我告诉你们，你们的义若不胜过经学家和法利赛人的义，就必不能进天国。'),
('CNV', '马太福音', 40, 5, 21, '“你们听过有这样吩咐古人的话：‘不可杀人，杀人的必被判罪。’'),
('CNV', '马太福音', 40, 5, 22, '可是我告诉你们，凡是向弟兄发怒的，都要被判罪。谁若骂弟兄：‘你这蠢货！（蠢货：原文音译是“拉加”，是亚兰文侮辱别人的用语。）’，就要被公议会判罪；谁若骂：‘你这白痴！（白痴：原文是希腊文骂人的词语，但是有少数学者认为这词语是源于希伯来文，而把它音译为“魔利”，意思是“叛徒”。）’，就罪该送入烈火的地狱。'),
('CNV', '马太福音', 40, 5, 23, '所以你在祭坛上献供物的时候，如果在那里想起你的弟兄对你不满，'),
('CNV', '马太福音', 40, 5, 24, '就当在坛前放下供物，先去与弟兄和好，然后才来献你的供物。'),
('CNV', '马太福音', 40, 5, 25, '趁着你和你的对头还在路上的时候，要赶快与他和解，免得他抓你去见法官，法官把你交给狱警，关在监里。'),
('CNV', '马太福音', 40, 5, 26, '我实在告诉你，除非你还清最后一分钱，否则决不能从那里出来。'),
('CNV', '马太福音', 40, 5, 27, '“你们听过有这样的吩咐：‘不可奸淫。’'),
('CNV', '马太福音', 40, 5, 28, '可是我告诉你们，凡是看见妇女就动淫念的，心里已经犯了奸淫。'),
('CNV', '马太福音', 40, 5, 29, '如果你的右眼使你犯罪，就把它挖出来丢掉；宁可失去身体的一部分，胜过全身被丢进地狱里。'),
('CNV', '马太福音', 40, 5, 30, '如果你的右手使你犯罪，就把它砍下来丢掉；宁可失去身体的一部分，胜过全身进到地狱里去。'),
('CNV', '马太福音', 40, 5, 31, '“又有这样的吩咐：‘人若休妻，就应当给她休书。’'),
('CNV', '马太福音', 40, 5, 32, '可是我告诉你们，凡休妻的，如果不是因她不贞，就是促使她犯奸淫；无论谁娶了被休的妇人，也就是犯奸淫了。'),
('CNV', '马太福音', 40, 5, 33, '“你们又听过有这样吩咐古人的话：‘不可背约，向主许的愿都要偿还。’'),
('CNV', '马太福音', 40, 5, 34, '可是我告诉你们，总不可发誓，不可指着天发誓，因为天是神的宝座；'),
('CNV', '马太福音', 40, 5, 35, '不可指着地发誓，因为地是神的脚凳；不可指着耶路撒冷发誓，因为它是大君王的京城；'),
('CNV', '马太福音', 40, 5, 36, '也不可指着自己的头发誓，因为你不能使一根头发变白或变黑。'),
('CNV', '马太福音', 40, 5, 37, '你们的话，是就说‘是’，不是就说‘不是’；如果再多说，就是出于那恶者。'),
('CNV', '马太福音', 40, 5, 38, '“你们听过有这样的吩咐：‘以眼还眼，以牙还牙。’'),
('CNV', '马太福音', 40, 5, 39, '可是我告诉你们，不要与恶人对抗，有人打你的右脸，把另一边也转过来让他打；'),
('CNV', '马太福音', 40, 5, 40, '有人要告你，想拿你的衬衫，就连外套也让他拿去。'),
('CNV', '马太福音', 40, 5, 41, '有人要强迫你走一里路，就陪他走两里。'),
('CNV', '马太福音', 40, 5, 42, '有求你的，就给他；想借贷的，也不可拒绝。'),
('CNV', '马太福音', 40, 5, 43, '“你们听过有这样的吩咐：‘当爱你的邻舍，恨你的仇敌。’'),
('CNV', '马太福音', 40, 5, 44, '可是我告诉你们，当爱你们的仇敌，为迫害你们的祈祷，'),
('CNV', '马太福音', 40, 5, 45, '好叫你们成为你们天父的儿子；因为他使太阳照恶人，也照好人；降雨给义人，也给不义的人。'),
('CNV', '马太福音', 40, 5, 46, '如果你们只爱那些爱你们的人，有什么赏赐呢？税吏不也是这样作吗？'),
('CNV', '马太福音', 40, 5, 47, '如果你们单问候你们的弟兄，有什么特别呢？教外人不也是这样作吗？'),
('CNV', '马太福音', 40, 5, 48, '所以你们要完全，正如你们的天父是完全的。”'),
('CNV', '马太福音', 40, 6, 1, '“你们小心，不要在众人面前行你们的义，让他们看见；如果这样，就得不到你们天父的赏赐。'),
('CNV', '马太福音', 40, 6, 2, '因此你施舍的时候，不可到处张扬，好像伪君子在会堂和街上所作的一样，以博取众人的称赞。我实在告诉你们，他们已经得了他们的赏赐。'),
('CNV', '马太福音', 40, 6, 3, '你施舍的时候，不要让左手知道右手所作的，'),
('CNV', '马太福音', 40, 6, 4, '好使你的施舍是在隐密中行的。你父在隐密中察看，必定报答你。'),
('CNV', '马太福音', 40, 6, 5, '“你们祈祷的时候，不可像伪君子；他们喜欢在会堂和路口站着祈祷，好让人看见。我实在告诉你们，他们已经得了他们的赏赐。'),
('CNV', '马太福音', 40, 6, 6, '但你祈祷的时候，要进到密室里去，关上门，向在隐密中的父祈祷。你父在隐密中察看，必定报答你。'),
('CNV', '马太福音', 40, 6, 7, '你们祈祷的时候，不可重复无意义的话，像教外人一样，他们以为话多了就蒙垂听。'),
('CNV', '马太福音', 40, 6, 8, '你们不可像他们，因为在你们祈求以先，你们的父已经知道你们的需要了。'),
('CNV', '马太福音', 40, 6, 9, '所以你们要这样祈祷：‘我们在天上的父，愿你的名被尊为圣，'),
('CNV', '马太福音', 40, 6, 10, '愿你的国降临，愿你的旨意成就在地上，如同在天上一样。'),
('CNV', '马太福音', 40, 6, 11, '我们每天所需的食物，求你今天赐给我们；'),
('CNV', '马太福音', 40, 6, 12, '赦免我们的罪债，好像我们饶恕了得罪我们的人；'),
('CNV', '马太福音', 40, 6, 13, '不要让我们陷入试探，救我们脱离那恶者。’﹙有些后期抄本在此有“因为国度、权柄、荣耀，全是你的，直到永远。阿们”一句。﹚'),
('CNV', '马太福音', 40, 6, 14, '如果你们饶恕别人的过犯，你们的天父也必饶恕你们。'),
('CNV', '马太福音', 40, 6, 15, '如果你们不饶恕别人，你们的父也必不饶恕你们的过犯。'),
('CNV', '马太福音', 40, 6, 16, '“你们禁食的时候，不可像伪君子那样愁眉苦脸，他们装成难看的样子，叫人看出他们在禁食。我实在告诉你们，他们已经得了他们的赏赐。'),
('CNV', '马太福音', 40, 6, 17, '可是你禁食的时候，要梳头洗脸，'),
('CNV', '马太福音', 40, 6, 18, '不要叫人看出你在禁食，只让在隐密中的父看见。你父在隐密中察看，必定报答你。'),
('CNV', '马太福音', 40, 6, 19, '“不可为自己在地上积聚财宝，因为地上有虫蛀，有锈侵蚀，也有贼挖洞来偷。'),
('CNV', '马太福音', 40, 6, 20, '要为自己积聚财宝在天上，那里没有虫蛀锈蚀，也没有贼挖洞来偷。'),
('CNV', '马太福音', 40, 6, 21, '你的财宝在哪里，你的心也在哪里。'),
('CNV', '马太福音', 40, 6, 22, '“眼睛就是身体的灯。如果你的眼睛健全，全身就都明亮；'),
('CNV', '马太福音', 40, 6, 23, '如果你的眼睛有毛病，全身就都黑暗。如果你里面的光变成黑暗，这是多么的黑暗！'),
('CNV', '马太福音', 40, 6, 24, '“一个人不能服事两个主人；他若不是恨这个爱那个，就是忠于这个轻视那个。你们不能服事神，又服事金钱﹙“金钱”亚兰文是“玛门”。﹚。'),
('CNV', '马太福音', 40, 6, 25, '所以我告诉你们，不要为生命忧虑吃什么喝什么，也不要为身体忧虑穿什么。难道生命不比食物重要吗？身体不比衣服重要吗？'),
('CNV', '马太福音', 40, 6, 26, '你们看天空的飞鸟：它们不撒种，不收割，也不收进仓里，你们的天父尚且养活它们；难道你们不比它们更宝贵吗？'),
('CNV', '马太福音', 40, 6, 27, '你们中间谁能用忧虑使自己的寿命延长一刻呢？'),
('CNV', '马太福音', 40, 6, 28, '何必为衣服忧虑呢？试想田野的百合花怎样生长，它们不劳苦，也不纺织。'),
('CNV', '马太福音', 40, 6, 29, '但我告诉你们，就是所罗门最威荣的时候所穿的，也比不上这花中的一朵。'),
('CNV', '马太福音', 40, 6, 30, '田野的草，今天还在，明天就投进炉里，神尚且这样妆扮它们；小信的人哪，何况你们呢？'),
('CNV', '马太福音', 40, 6, 31, '所以不要忧虑，说：‘我们该吃什么？喝什么？穿什么？’'),
('CNV', '马太福音', 40, 6, 32, '这些都是教外人所寻求的，你们的天父原知道你们需要这一切。'),
('CNV', '马太福音', 40, 6, 33, '你们要先求他的国和他的义，这一切都必加给你们。'),
('CNV', '马太福音', 40, 6, 34, '所以不要为明天忧虑，因为明天自有明天的忧虑，一天的难处一天当就够了。”'),
('CNV', '马太福音', 40, 7, 1, '“不可判断人，免得你们被判断。'),
('CNV', '马太福音', 40, 7, 2, '你们怎样判断人，也必怎样被判断；你们用什么标准衡量人，也必照样被衡量。'),
('CNV', '马太福音', 40, 7, 3, '为什么看见你弟兄眼中的木屑，却不理会自己眼中的梁木呢？'),
('CNV', '马太福音', 40, 7, 4, '你自己眼中有梁木，怎能对弟兄说：‘让我除掉你眼中的木屑’呢？'),
('CNV', '马太福音', 40, 7, 5, '伪君子啊！先除掉你眼中的梁木，才可以看得清楚，去除掉弟兄眼中的木屑。'),
('CNV', '马太福音', 40, 7, 6, '不要把圣物给狗，也不要把你们的珍珠丢在猪前，免得它们用脚把珍珠践踏，又转过来猛噬你们。'),
('CNV', '马太福音', 40, 7, 7, '“你们祈求，就给你们；寻找，就寻见；叩门，就给你们开门。'),
('CNV', '马太福音', 40, 7, 8, '因为凡祈求的就得着，寻找的就寻见，叩门的就给他开门。'),
('CNV', '马太福音', 40, 7, 9, '你们中间哪一个人，儿子向他要饼，反给他石头；'),
('CNV', '马太福音', 40, 7, 10, '要鱼，反给他蛇呢？'),
('CNV', '马太福音', 40, 7, 11, '你们虽然邪恶，尚且知道把好东西给儿女，何况你们在天上的父，难道不更把好东西赐给求他的人吗？'),
('CNV', '马太福音', 40, 7, 12, '所以，你们愿意人怎样待你们，你们也要怎样待人，这是律法和先知的总纲。'),
('CNV', '马太福音', 40, 7, 13, '“你们当进窄门，因为引到灭亡的门是宽的，路是大的，进去的人也多；'),
('CNV', '马太福音', 40, 7, 14, '但引到生命的门是窄的，路是小的，找着的人也少。'),
('CNV', '马太福音', 40, 7, 15, '“提防假先知！他们披着羊皮到你们当中，里面却是残暴的狼。'),
('CNV', '马太福音', 40, 7, 16, '凭着他们的果子就可以认出他们来：荆棘里怎能摘到葡萄？蒺藜里怎能摘到无花果呢？'),
('CNV', '马太福音', 40, 7, 17, '照样，好树结好果子，坏树结坏果子；'),
('CNV', '马太福音', 40, 7, 18, '好树不能结坏果子，坏树也不能结好果子。'),
('CNV', '马太福音', 40, 7, 19, '凡是不结好果子的树，就被砍下来，丢在火中。'),
('CNV', '马太福音', 40, 7, 20, '因此你们凭着他们的果子就可以认出他们来。'),
('CNV', '马太福音', 40, 7, 21, '“不是每一个对我说：‘主啊，主啊！’的人，都能进入天国，唯有遵行我天父旨意的人，才能进去。'),
('CNV', '马太福音', 40, 7, 22, '到那日，必有许多人对我说：‘主啊，主啊！难道我们没有奉你的名讲道，奉你的名赶鬼，奉你的名行过许多神迹吗？’'),
('CNV', '马太福音', 40, 7, 23, '但我必向他们声明：‘我从来不认识你们；你们这些作恶的人，离开我去吧！’'),
('CNV', '马太福音', 40, 7, 24, '“所以，凡听见我这些话又遵行的，就像聪明的人，把自己的房子盖在磐石上。'),
('CNV', '马太福音', 40, 7, 25, '雨淋、水冲、风吹，摇撼那房子，房子却不倒塌，因为建基在磐石上。'),
('CNV', '马太福音', 40, 7, 26, '凡听见我这些话却不遵行的，就像愚蠢的人，把自己的房子盖在沙土上。'),
('CNV', '马太福音', 40, 7, 27, '雨淋、水冲、风吹，摇撼那房子，房子就倒塌了，并且倒塌得很厉害。”'),
('CNV', '马太福音', 40, 7, 28, '耶稣讲完了这些话，群众都惊奇他的教训。'),
('CNV', '马太福音', 40, 7, 29, '因为耶稣教导他们，像一个有权柄的人，不像他们的经学家。'),
('CNV', '马太福音', 40, 8, 1, '耶稣下了山，许多人跟随着他。'),
('CNV', '马太福音', 40, 8, 2, '有一个患痲风的人前来向他跪拜，说：“主啊！如果你肯，必能使我洁净。”'),
('CNV', '马太福音', 40, 8, 3, '耶稣伸手摸他，说：“我肯，你洁净了吧！”他的痲风立刻洁净了。'),
('CNV', '马太福音', 40, 8, 4, '耶稣对他说：“你千万不可告诉别人，只要去给祭司检查，并且照着摩西所规定的献上供物，好向大家作证。”'),
('CNV', '马太福音', 40, 8, 5, '耶稣到了迦百农，有一个百夫长前来恳求他，'),
('CNV', '马太福音', 40, 8, 6, '说：“主啊！我的仆人瘫痪了，躺在家里非常痛苦。”'),
('CNV', '马太福音', 40, 8, 7, '耶稣对他说：“我去医治他。”'),
('CNV', '马太福音', 40, 8, 8, '百夫长回答：“主啊，要你到舍下来，实在不敢当。只要你说一句话，我的仆人就必好了。'),
('CNV', '马太福音', 40, 8, 9, '我自己是在别人的权下，也有兵在我以下；我对这个说‘去！’他就去，对另一个说‘来！’他就来；对仆人说‘作这个！’他就作。”'),
('CNV', '马太福音', 40, 8, 10, '耶稣听了，就很惊奇，对跟随的人说：“我实在告诉你们，这样的信心，我在以色列中从来没有见过。'),
('CNV', '马太福音', 40, 8, 11, '我告诉你们，必有许多人从东从西来到，和亚伯拉罕、以撒、雅各在天国里一起吃饭。'),
('CNV', '马太福音', 40, 8, 12, '但本来要承受天国的人，反被丢在外面黑暗里，在那里必要哀哭切齿。”'),
('CNV', '马太福音', 40, 8, 13, '于是耶稣对百夫长说：“回去吧！事情必照你所信的给你成就。”他的仆人就在那时痊愈了。'),
('CNV', '马太福音', 40, 8, 14, '耶稣来到彼得家里，看见他的岳母发烧，病在床上。'),
('CNV', '马太福音', 40, 8, 15, '耶稣一摸她的手，热就退了；她就起来服事耶稣。'),
('CNV', '马太福音', 40, 8, 16, '到了黄昏，有些人带了许多被鬼附的人来见耶稣，他只用一句话就把污灵赶出去，并且医好了所有患病的人。'),
('CNV', '马太福音', 40, 8, 17, '这样正应验了以赛亚先知所说的：“他亲自除去我们的软弱，担当我们的疾病。”'),
('CNV', '马太福音', 40, 8, 18, '耶稣看见许多人围着他，就吩咐往对岸去。'),
('CNV', '马太福音', 40, 8, 19, '有一位经学家前来对他说：“老师，你无论往哪里去，我都要跟从你！”'),
('CNV', '马太福音', 40, 8, 20, '耶稣回答：“狐狸有洞，天空的飞鸟有窝，但人子却没有栖身﹙“栖身”原文作“枕头”。﹚的地方。”'),
('CNV', '马太福音', 40, 8, 21, '另一个门徒对他说：“主啊！请准我先回去安葬我的父亲吧。”'),
('CNV', '马太福音', 40, 8, 22, '耶稣对他说：“跟从我吧！让死人去埋葬他们的死人。”'),
('CNV', '马太福音', 40, 8, 23, '耶稣上了船，门徒跟着他。'),
('CNV', '马太福音', 40, 8, 24, '忽然海上起了狂风，甚至船都被波涛掩盖，但耶稣却睡着了。'),
('CNV', '马太福音', 40, 8, 25, '他们走来把他叫醒，说：“主啊！救命啊！我们没命了！”'),
('CNV', '马太福音', 40, 8, 26, '耶稣却对他们说：“小信的人哪！为什么害怕呢？”他就起来斥责风和海，风浪就完全平静了。'),
('CNV', '马太福音', 40, 8, 27, '众人都惊奇，说：“这是什么人，连风和海也听从他？”'),
('CNV', '马太福音', 40, 8, 28, '耶稣过到对岸加大拉人的地区，遇见两个被鬼附着的人从墓地出来；他们十分凶暴，甚至没有人敢从那条路经过。'),
('CNV', '马太福音', 40, 8, 29, '他们喊叫：“神的儿子，我们跟你有什么关系呢？时候还没有到，你就来这里叫我们受苦吗？”'),
('CNV', '马太福音', 40, 8, 30, '那时远远有一大群猪正在吃东西。'),
('CNV', '马太福音', 40, 8, 31, '那些鬼就求耶稣，说：“如果要赶我们出来，就准我们进到猪群里去吧。”'),
('CNV', '马太福音', 40, 8, 32, '耶稣对他们说：“出去吧！”他们就出来，进了猪群。那一群猪忽然闯下山崖，掉在海里淹死了。'),
('CNV', '马太福音', 40, 8, 33, '放猪的人逃进城里，把被鬼附的人的遭遇和一切事情，都报告出来。'),
('CNV', '马太福音', 40, 8, 34, '全城的居民都出来要见耶稣，看见了他，就求他离开他们的地区。'),
('CNV', '马太福音', 40, 9, 1, '耶稣上了船，过到自己的城来。'),
('CNV', '马太福音', 40, 9, 2, '有人把一个躺在床上的瘫子带到他那里。耶稣看见他们的信心，就对瘫子说：“孩子，放心！你的罪赦了。”'),
('CNV', '马太福音', 40, 9, 3, '有几位经学家彼此说：“这个人在说僭妄的话。”'),
('CNV', '马太福音', 40, 9, 4, '耶稣看出他们所想的，就说：“你们心里为什么存着恶念呢？'),
('CNV', '马太福音', 40, 9, 5, '说‘你的罪赦了’，或说‘起来行走’，哪一样容易呢？'),
('CNV', '马太福音', 40, 9, 6, '然而为了要使你们知道人子在地上有赦罪的权柄，（他就对瘫子说：）起来，拿起你的床，回家去吧。”'),
('CNV', '马太福音', 40, 9, 7, '他就起来回家去了。'),
('CNV', '马太福音', 40, 9, 8, '群众看见，就起了敬畏的心，颂赞那把这样的权柄赐给人的神。'),
('CNV', '马太福音', 40, 9, 9, '耶稣从那里往前走，看见一个人，名叫马太，坐在税关那里，就对他说：“来跟从我！”他就起来跟从了耶稣。'),
('CNV', '马太福音', 40, 9, 10, '耶稣在屋里吃饭的时候，有很多税吏和罪人来与他和门徒一起吃饭。'),
('CNV', '马太福音', 40, 9, 11, '法利赛人看见了，就对他的门徒说：“你们的老师为什么跟税吏和罪人一起吃饭呢？”'),
('CNV', '马太福音', 40, 9, 12, '耶稣听见了，就说：“健康的人不需要医生，有病的人才需要，'),
('CNV', '马太福音', 40, 9, 13, '‘我喜爱怜悯，不喜爱祭祀’，你们去想一想这话的意思吧。我来不是要召义人，而是要召罪人。”'),
('CNV', '马太福音', 40, 9, 14, '那时，约翰的门徒前来问耶稣：“为什么我们和法利赛人常常禁食，你的门徒却不禁食呢？”'),
('CNV', '马太福音', 40, 9, 15, '耶稣回答：“新郎跟宾客在一起的时候，宾客怎能哀痛呢？但到了时候，新郎就要从他们中间被取去，那时他们就要禁食了。'),
('CNV', '马太福音', 40, 9, 16, '没有人会拿一块新布补在旧衣服上，因为补上的会把衣服扯破，裂的地方就更大了。'),
('CNV', '马太福音', 40, 9, 17, '也没有人会把新酒装在旧皮袋里，如果这样，皮袋就会胀破，酒就漏出来，皮袋也损坏了。人总是把新酒装在新皮袋里，这样，两样都可以保全。”'),
('CNV', '马太福音', 40, 9, 18, '耶稣对他们说话的时候，有一位会堂的主管走来跪在他面前，说：“我的女儿刚死了，但请你来按手在她身上，她必活过来。”'),
('CNV', '马太福音', 40, 9, 19, '于是耶稣和门徒起来跟着他去了。'),
('CNV', '马太福音', 40, 9, 20, '有一个女人，患了十二年的血漏病，她走到耶稣背后，摸他衣服的繸子，'),
('CNV', '马太福音', 40, 9, 21, '因为她心里说：“只要摸到他的衣服，我就必痊愈。”'),
('CNV', '马太福音', 40, 9, 22, '耶稣转过来看见她，就说：“女儿，放心！你的信心使你痊愈了。”从那时起，那女人就好了。'),
('CNV', '马太福音', 40, 9, 23, '耶稣进了那主管的家，看见有吹笛的人和喧哗的群众，'),
('CNV', '马太福音', 40, 9, 24, '就说：“出去！这女孩不是死了，只是睡了。”他们就嘲笑他。'),
('CNV', '马太福音', 40, 9, 25, '耶稣赶走众人之后，进去拉着女孩的手，女孩就起来了。'),
('CNV', '马太福音', 40, 9, 26, '这消息传遍了那一带。'),
('CNV', '马太福音', 40, 9, 27, '耶稣离开那里的时候，有两个瞎子跟着他，喊着说：“大卫的子孙，可怜我们吧！”'),
('CNV', '马太福音', 40, 9, 28, '耶稣进了房子，他们来到他那里。耶稣问他们：“你们信我能作这些事吗？”他们回答：“主啊，我们信。”'),
('CNV', '马太福音', 40, 9, 29, '于是耶稣摸他们的眼睛，说：“照你们的信心给你们成就吧。”'),
('CNV', '马太福音', 40, 9, 30, '他们的眼睛就看见了。耶稣严严地嘱咐他们：“千万不可让人知道。”'),
('CNV', '马太福音', 40, 9, 31, '他们却出去，把他所作的事传遍了那一带。'),
('CNV', '马太福音', 40, 9, 32, '他们出去的时候，有人带着一个被鬼附着的哑巴来见耶稣。'),
('CNV', '马太福音', 40, 9, 33, '耶稣把鬼赶走之后，哑巴就说话了。众人都很惊奇，说：“这样的事，在以色列从来没有见过。”'),
('CNV', '马太福音', 40, 9, 34, '但法利赛人说：“他不过是靠鬼王赶鬼罢了。”'),
('CNV', '马太福音', 40, 9, 35, '耶稣走遍各城各乡，在各会堂里教导人，宣扬天国的福音，医治各种疾病、各种病症。'),
('CNV', '马太福音', 40, 9, 36, '他看见群众，就怜悯他们，因为他们困苦无依，像没有牧人的羊一样。'),
('CNV', '马太福音', 40, 9, 37, '他就对门徒说：“庄稼多，工人少；'),
('CNV', '马太福音', 40, 9, 38, '所以你们应当求庄稼的主派工人去收割他的庄稼。”'),
('CNV', '马太福音', 40, 10, 1, '耶稣叫了十二门徒来，赐给他们胜过污灵的权柄，可以赶出污灵和医治各种疾病、各种病症。'),
('CNV', '马太福音', 40, 10, 2, '十二使徒的名字如下：为首的是西门（又名彼得），西门的弟弟安得烈，西庇太的儿子雅各，雅各的弟弟约翰，'),
('CNV', '马太福音', 40, 10, 3, '腓力，巴多罗迈，多马，税吏马太，亚勒腓的儿子雅各，达太，'),
('CNV', '马太福音', 40, 10, 4, '激进派的西门，和出卖耶稣的加略人犹大。'),
('CNV', '马太福音', 40, 10, 5, '耶稣差遣这十二个人出去，并且嘱咐他们：“外族人的路，你们不要走，撒玛利亚人的城，你们也不要进；'),
('CNV', '马太福音', 40, 10, 6, '却要到以色列家的迷羊那里去。'),
('CNV', '马太福音', 40, 10, 7, '你们要一边走一边宣扬说：‘天国近了。’'),
('CNV', '马太福音', 40, 10, 8, '要医治有病的，叫死人复活，洁净患痲风的，赶出污鬼。你们白白地得来，也应当白白地给人。'),
('CNV', '马太福音', 40, 10, 9, '你们腰袋里不要带金、银、铜钱；'),
('CNV', '马太福音', 40, 10, 10, '路上不要带行囊，也不要带两件衣裳，不要带鞋或手杖，因为作工的理当得到供应。'),
('CNV', '马太福音', 40, 10, 11, '你们无论进哪一座城哪一个村，都要打听谁配接待你们，就住在那里，直到离去。'),
('CNV', '马太福音', 40, 10, 12, '到他家里的时候，要向他们问安；'),
('CNV', '马太福音', 40, 10, 13, '如果这家是配得的，你们的平安就必临到他们；如果这家不配得，你们的平安仍归你们。'),
('CNV', '马太福音', 40, 10, 14, '如果有人不接待你们，不听你们的话，你们离开那一家那一城的时候，就要把脚上的灰尘跺下去。'),
('CNV', '马太福音', 40, 10, 15, '我实在告诉你们，在审判的日子，所多玛和蛾摩拉所受的，比那城还轻呢。'),
('CNV', '马太福音', 40, 10, 16, '“现在，我差派你们出去，好像羊进到狼群中间；所以你们要像蛇一样机警，像鸽子一样纯洁。'),
('CNV', '马太福音', 40, 10, 17, '你们要小心，因为有人要把你们送交公议会，并要在会堂里鞭打你们；'),
('CNV', '马太福音', 40, 10, 18, '你们为我的缘故，也要被带到统治者和君王面前，向他们和外族人作见证。'),
('CNV', '马太福音', 40, 10, 19, '你们被捕的时候，用不着担心说什么和怎么说，因为那时你们必得着当说的话；'),
('CNV', '马太福音', 40, 10, 20, '因为说话的不是你们，而是你们的父的灵，是他在你们里面说话。'),
('CNV', '马太福音', 40, 10, 21, '弟兄要出卖弟兄，父亲要出卖儿女，甚至把他们置于死地；儿女要悖逆父母，害死他们。'),
('CNV', '马太福音', 40, 10, 22, '你们为我的名，要被众人恨恶，然而坚忍到底的必然得救。'),
('CNV', '马太福音', 40, 10, 23, '如果有人在这城迫害你们，就逃到别的城去。我实在告诉你们，你们还没有走遍以色列的各城，人子就来到了。'),
('CNV', '马太福音', 40, 10, 24, '“学生不能胜过老师，奴仆也不能胜过主人。'),
('CNV', '马太福音', 40, 10, 25, '学生若能像老师一样，奴仆若能像主人一样，也就够了。如果一家之主也被称为别西卜﹙“别西卜”是鬼王的名字。﹚，何况他的家人呢？'),
('CNV', '马太福音', 40, 10, 26, '“所以不要怕他们。没有什么掩盖的事不被揭露，也没有什么秘密是人不知道的。'),
('CNV', '马太福音', 40, 10, 27, '我在暗处告诉你们的，你们要在明处讲出来；你们听见的耳语，要在房顶上宣扬出来。'),
('CNV', '马太福音', 40, 10, 28, '那些杀身体却不能杀灵魂的，不要怕他们；倒要怕那位能把灵魂和身体都投入地狱里的。'),
('CNV', '马太福音', 40, 10, 29, '两只麻雀不是卖一个大钱吗？但你们的父若不许可，一只也不会掉在地上。'),
('CNV', '马太福音', 40, 10, 30, '甚至你们的头发都一一数过了。'),
('CNV', '马太福音', 40, 10, 31, '所以不要怕，你们比许多麻雀贵重得多呢。'),
('CNV', '马太福音', 40, 10, 32, '“凡在人面前承认我的，我在我天父面前也要承认他；'),
('CNV', '马太福音', 40, 10, 33, '在人面前不认我的，我在我天父面前也要不认他。'),
('CNV', '马太福音', 40, 10, 34, '“你们不要以为我来了，是要给地上带来和平；我并没有带来和平，却带来刀剑，'),
('CNV', '马太福音', 40, 10, 35, '因为我来了是要叫人分裂：人与父亲作对，女儿与母亲作对，媳妇与婆婆作对，'),
('CNV', '马太福音', 40, 10, 36, '人的仇敌就是自己的家人。'),
('CNV', '马太福音', 40, 10, 37, '爱父母过于爱我的，不配作属我的；爱儿女过于爱我的，不配作属我的；'),
('CNV', '马太福音', 40, 10, 38, '凡不背起自己的十字架来跟从我的，也不配作属我的。'),
('CNV', '马太福音', 40, 10, 39, '顾惜自己生命的，必要丧掉生命；但为我牺牲生命的，必要得着生命。'),
('CNV', '马太福音', 40, 10, 40, '“接待你们的，就是接待我；接待我的，就是接待那差我来的。'),
('CNV', '马太福音', 40, 10, 41, '因先知的名接待先知的，必得先知所得的赏赐；因义人的名接待义人的，必得义人所得的赏赐。'),
('CNV', '马太福音', 40, 10, 42, '无论谁因门徒的名，只把一杯凉水给这些微不足道的人中的一个喝，我实在告诉你们，他决不会得不到他的赏赐。”'),
('CNV', '马太福音', 40, 11, 1, '耶稣吩咐完了十二门徒，就离开那里，在各城里教导传道。'),
('CNV', '马太福音', 40, 11, 2, '约翰在监狱里听见基督所作的，就派门徒去问他：'),
('CNV', '马太福音', 40, 11, 3, '“你就是那位要来的，还是我们要等别人呢？”'),
('CNV', '马太福音', 40, 11, 4, '耶稣回答他们：“你们回去，把听见和看见的都告诉约翰，'),
('CNV', '马太福音', 40, 11, 5, '就是瞎的可以看见，瘸的可以走路，患痲风的得到洁净，聋的可以听见，死人复活，穷人有福音听。'),
('CNV', '马太福音', 40, 11, 6, '那不被我绊倒的，就有福了。”'),
('CNV', '马太福音', 40, 11, 7, '他们走了之后，耶稣对群众讲起约翰来，说：“你们到旷野去，是要看什么？被风吹动的芦苇吗？'),
('CNV', '马太福音', 40, 11, 8, '你们出去到底要看什么？身穿华丽衣裳的人吗？那些穿着华丽衣裳的人，是在王宫里的。'),
('CNV', '马太福音', 40, 11, 9, '那么，你们出去要看什么？先知吗？我告诉你们，是的。他比先知重要得多了。'),
('CNV', '马太福音', 40, 11, 10, '经上所记：‘看哪，我差遣我的使者在你面前，他必在你前头预备你的道路。’这句话是指着他说的。'),
('CNV', '马太福音', 40, 11, 11, '我实在告诉你们，妇人所生的，没有一个比施洗的约翰更大；然而天国里最小的比他还大。'),
('CNV', '马太福音', 40, 11, 12, '从施洗的约翰的时候直到现在，天国不断遭受猛烈的攻击，强暴的人企图把它夺去。'),
('CNV', '马太福音', 40, 11, 13, '所有的先知和律法，直到约翰为止，都说了预言。'),
('CNV', '马太福音', 40, 11, 14, '如果你们肯接受，约翰就是那要来的以利亚。'),
('CNV', '马太福音', 40, 11, 15, '有耳的，就应当听。'),
('CNV', '马太福音', 40, 11, 16, '“我要把这世代比作什么呢？它好像一些小孩子坐在市中心，呼叫别的小孩子，'),
('CNV', '马太福音', 40, 11, 17, '说：‘我们给你们吹笛子，你们却不跳舞；我们唱哀歌，你们也不捶胸。’'),
('CNV', '马太福音', 40, 11, 18, '约翰来了，不吃也不喝，人说他是鬼附的；'),
('CNV', '马太福音', 40, 11, 19, '人子来了，又吃又喝，人却说：‘你看，这人贪食好酒，与税吏和罪人为友。’但智慧藉着它所作的，就证实是公义的了。”'),
('CNV', '马太福音', 40, 11, 20, '那时，耶稣开始责备那些他曾在那里行过许多神迹的城，因为它们不肯悔改：'),
('CNV', '马太福音', 40, 11, 21, '“哥拉逊啊，你有祸了！伯赛大啊，你有祸了！在你们那里行过的神迹，如果行在推罗和西顿，它们早已披麻蒙灰悔改了。'),
('CNV', '马太福音', 40, 11, 22, '但我告诉你们，在审判的日子，推罗和西顿所受的，比你们还轻呢。'),
('CNV', '马太福音', 40, 11, 23, '迦百农啊！你会被高举到天上吗？你必降到阴间。在你那里行过的神迹，如果行在所多玛，那城还会存留到今天。'),
('CNV', '马太福音', 40, 11, 24, '但我告诉你们，在审判的日子，所多玛那地方所受的，比你还轻呢。”'),
('CNV', '马太福音', 40, 11, 25, '就在那时候，耶稣说：“父啊，天地的主，我赞美你，因为你把这些事向智慧和聪明的人隐藏起来，却向婴孩显明。'),
('CNV', '马太福音', 40, 11, 26, '父啊，是的，这就是你的美意。'),
('CNV', '马太福音', 40, 11, 27, '我父已经把一切交给我；除了父没有人认识子，除了子和子所愿意启示的人，没有人认识父。'),
('CNV', '马太福音', 40, 11, 28, '你们所有劳苦担重担的人哪，到我这里来吧！我必使你们得安息。'),
('CNV', '马太福音', 40, 11, 29, '我心里柔和谦卑，你们应当负我的轭，向我学习，你们就必得着心灵的安息；'),
('CNV', '马太福音', 40, 11, 30, '我的轭是容易负的，我的担子是轻省的。”'),
('CNV', '马太福音', 40, 12, 1, '安息日那天，耶稣从麦田经过；他的门徒饿了，就摘了些麦穗来吃。'),
('CNV', '马太福音', 40, 12, 2, '法利赛人看见了，就对他说：“你看，你的门徒作了安息日不可作的事。”'),
('CNV', '马太福音', 40, 12, 3, '耶稣对他们说：“大卫和跟他在一起的人，在饥饿的时候所作的，你们没有念过吗？'),
('CNV', '马太福音', 40, 12, 4, '他不是进了神的殿，吃了他和跟他在一起的人不可以吃，只有祭司才可以吃的陈设饼吗？'),
('CNV', '马太福音', 40, 12, 5, '律法书上记着：安息日，祭司在殿里供职，触犯了安息日，也不算有罪；你们也没有念过吗？'),
('CNV', '马太福音', 40, 12, 6, '我告诉你们，这里有一位是比圣殿更大的。'),
('CNV', '马太福音', 40, 12, 7, '如果你们明白‘我喜爱怜悯，不喜爱祭祀’这句话的意思，就不会把无罪的定罪了。'),
('CNV', '马太福音', 40, 12, 8, '因为人子是安息日的主。”'),
('CNV', '马太福音', 40, 12, 9, '耶稣离开那里，来到他们的会堂。'),
('CNV', '马太福音', 40, 12, 10, '会堂里有一个人，他的一只手枯干了。有人问耶稣：“在安息日治病，可以吗？”目的是要控告耶稣。'),
('CNV', '马太福音', 40, 12, 11, '耶稣回答：“你们当中有哪一个，他仅有的一只羊在安息日跌进坑里，会不把羊抓住拉上来呢？'),
('CNV', '马太福音', 40, 12, 12, '人比羊贵重得多了！所以，在安息日行善是可以的。”'),
('CNV', '马太福音', 40, 12, 13, '于是对那人说：“伸出手来！”他把手一伸，就复原了，好像另一只手一样。'),
('CNV', '马太福音', 40, 12, 14, '法利赛人出去，商议怎样对付耶稣，好杀掉他。'),
('CNV', '马太福音', 40, 12, 15, '耶稣知道了，就离开那里。有很多人跟随他，他医好他们所有的病人，'),
('CNV', '马太福音', 40, 12, 16, '又嘱咐他们不可替他张扬。'),
('CNV', '马太福音', 40, 12, 17, '这就应验了以赛亚先知所说的：'),
('CNV', '马太福音', 40, 12, 18, '“看哪！我所拣选的仆人，我所爱，心里所喜悦的；我要把我的灵赐给他，他必向万国宣扬公理。'),
('CNV', '马太福音', 40, 12, 19, '他不争吵，也不喧嚷，人在街上听不见他的声音。'),
('CNV', '马太福音', 40, 12, 20, '压伤的芦苇，他不折断，将残的灯火，他不吹灭；直到他施行公理，使公理得胜。'),
('CNV', '马太福音', 40, 12, 21, '万民都要寄望于他的名。”'),
('CNV', '马太福音', 40, 12, 22, '有人带了一个被鬼附着、又瞎又哑的人到耶稣那里。耶稣医好了他，那哑巴就能说话，也能看见了。'),
('CNV', '马太福音', 40, 12, 23, '群众都很惊奇，说：“难道他就是大卫的子孙？”'),
('CNV', '马太福音', 40, 12, 24, '法利赛人听见了，说：“这个人赶鬼，只不过是靠鬼王别西卜罢了。”'),
('CNV', '马太福音', 40, 12, 25, '耶稣知道他们的心思，就对他们说：“如果一个国家自相纷争，就必定荒凉；一城一家自相纷争，必站立不住。'),
('CNV', '马太福音', 40, 12, 26, '如果撒但赶逐撒但，就会自相纷争。那么，他的国怎能站立得住呢？'),
('CNV', '马太福音', 40, 12, 27, '我若靠别西卜赶鬼，你们的子孙又靠谁赶鬼呢？这样，他们就要断定你们的不是。'),
('CNV', '马太福音', 40, 12, 28, '我若靠神的灵赶鬼，神的国就已经临到你们了。'),
('CNV', '马太福音', 40, 12, 29, '如果不先把壮汉绑起来，怎能进到他的家里，抢夺财物呢？如果绑起来了，就可以抢劫他的家了。'),
('CNV', '马太福音', 40, 12, 30, '不站在我这一边的就是反对我的，不跟我一起收聚的，就是分散的。'),
('CNV', '马太福音', 40, 12, 31, '因此，我告诉你们，人的一切罪和亵渎的话，都可以赦免；可是，亵渎圣灵就得不着赦免。'),
('CNV', '马太福音', 40, 12, 32, '无论谁说话得罪了人子，还可以赦免；但说话得罪了圣灵的，今生来世都得不着赦免。'),
('CNV', '马太福音', 40, 12, 33, '“你们种好树就结好果子，种坏树就结坏果子；凭着果子就能认出树来。'),
('CNV', '马太福音', 40, 12, 34, '毒蛇所生的啊，你们既然是邪恶的，怎能说出良善的话？因为心中所充满的，口里就说出来。'),
('CNV', '马太福音', 40, 12, 35, '良善的人从他良善的心﹙“心”原文作“库房。”﹚发出良善，邪恶的人从他邪恶的心﹙“心”原文作“库房”。﹚发出邪恶。'),
('CNV', '马太福音', 40, 12, 36, '我告诉你们，人所说的闲话，在审判的日子，句句都要供出来，'),
('CNV', '马太福音', 40, 12, 37, '因为你要照你的话被称为义，或定为有罪。”'),
('CNV', '马太福音', 40, 12, 38, '当时，有一些经学家和法利赛人对耶稣说：“老师，我们想请你显个神迹看看。”'),
('CNV', '马太福音', 40, 12, 39, '但耶稣说：“邪恶和淫乱的世代寻求神迹，除了约拿先知的神迹以外，再没有神迹给你们了。'),
('CNV', '马太福音', 40, 12, 40, '约拿怎样三日三夜在大鱼的腹中，人子也要照样三日三夜在地里。'),
('CNV', '马太福音', 40, 12, 41, '审判的时候，尼尼微人要和这个世代一同起来，定这个世代的罪，因为他们听了约拿所传的就悔改了。你看，这里有一位是比约拿更大的。'),
('CNV', '马太福音', 40, 12, 42, '审判的时候，南方的女王要和这个世代一同起来，定这个世代的罪，因为她从地极来到，要听所罗门智慧的话。你看，这里有一位是比所罗门更大的。'),
('CNV', '马太福音', 40, 12, 43, '“有一个污灵离开了一个人，走遍干旱之地，寻找栖身的地方，却没有找到。'),
('CNV', '马太福音', 40, 12, 44, '他就说：‘我要回到我从前离开了的那房子。’到了之后，看见里面空着，已经打扫干净，粉饰好了，'),
('CNV', '马太福音', 40, 12, 45, '他就去带了另外七个比自己更恶的污灵来，一齐进去住在那里；那人后来的情况，比以前更坏了。这邪恶的世代也会这样。”'),
('CNV', '马太福音', 40, 12, 46, '耶稣还在对群众讲话的时候，他的母亲和弟弟站在外面，要找他讲话。'),
('CNV', '马太福音', 40, 12, 47, '有人告诉耶稣：“你的母亲和弟弟站在外面，有话要跟你说。”'),
('CNV', '马太福音', 40, 12, 48, '他回答那人：“谁是我的母亲？谁是我的弟兄？”'),
('CNV', '马太福音', 40, 12, 49, '他伸手指着门徒说：“你看，我的母亲，我的弟兄！'),
('CNV', '马太福音', 40, 12, 50, '凡是遵行我天父旨意的，就是我的弟兄、姊妹和母亲了。”'),
('CNV', '马太福音', 40, 13, 1, '那一天，耶稣从房子里出来，坐在海边。'),
('CNV', '马太福音', 40, 13, 2, '有很多人聚集到他那里。于是，他上船坐下来，众人都站在岸上。'),
('CNV', '马太福音', 40, 13, 3, '他用比喻对众人讲了许多事，说：“有一个撒种的出去撒种。'),
('CNV', '马太福音', 40, 13, 4, '撒的时候，有的落在路旁，小鸟飞来就吃掉了。'),
('CNV', '马太福音', 40, 13, 5, '有的落在泥土不多的石地上，因为泥土不深，很快就长起来。'),
('CNV', '马太福音', 40, 13, 6, '但太阳一出来，就把它晒干，又因为没有根就枯萎了。'),
('CNV', '马太福音', 40, 13, 7, '有的落在荆棘里，荆棘长大了，就把它挤住。'),
('CNV', '马太福音', 40, 13, 8, '有的落在好土里，结出果实，有一百倍的，有六十倍的，有三十倍的。'),
('CNV', '马太福音', 40, 13, 9, '有耳的，就应当听。”'),
('CNV', '马太福音', 40, 13, 10, '门徒上前问耶稣：“你对他们讲话，为什么用比喻呢？”'),
('CNV', '马太福音', 40, 13, 11, '他回答：“天国的奥秘，只给你们知道，却不给他们知道。'),
('CNV', '马太福音', 40, 13, 12, '因为凡是有的，还要给他，他就充足有余；凡是没有的，就连他有什么也要拿去。'),
('CNV', '马太福音', 40, 13, 13, '因此，我用比喻对他们讲话，因为他们看却看不见，听也听不到，也不明白。'),
('CNV', '马太福音', 40, 13, 14, '以赛亚的预言，正应验在他们身上，他说：‘你们听是听见了，总是不明白；看是看见了，总是不领悟。'),
('CNV', '马太福音', 40, 13, 15, '因为这人民的心思迟钝，用不灵的耳朵去听，又闭上了眼睛；免得自己眼睛看见，耳朵听见，心里明白，回转过来，我就医好他们。’'),
('CNV', '马太福音', 40, 13, 16, '“你们的眼睛是有福的，因为可以看见；你们的耳朵是有福的，因为可以听见。'),
('CNV', '马太福音', 40, 13, 17, '我实在告诉你们，曾经有许多先知和义人想看你们所看见的，却没有看到，想听你们所听见的，却没有听到。'),
('CNV', '马太福音', 40, 13, 18, '“所以你们要听这撒种人的比喻。'),
('CNV', '马太福音', 40, 13, 19, '凡是听了天国的道却不明白的，那恶者就来把撒在他心中的夺去。这就是撒在路旁的。'),
('CNV', '马太福音', 40, 13, 20, '那撒在石地上的，就是人听了道，立刻欢欢喜喜地接受，'),
('CNV', '马太福音', 40, 13, 21, '可是他里面没有根，只是暂时的；一旦为道遭遇患难，受到迫害，就立刻跌倒了。'),
('CNV', '马太福音', 40, 13, 22, '那撒在荆棘里的，就是人听了道，有今世的忧虑和财富的迷惑把道挤住，结不出果实来。'),
('CNV', '马太福音', 40, 13, 23, '那撒在好土里的，就是人听了道，又明白了，结出果实来，有一百倍的，有六十倍的，有三十倍的。”'),
('CNV', '马太福音', 40, 13, 24, '耶稣对他们另外讲了一个比喻，说：“天国好像人把好的种子撒在田里。'),
('CNV', '马太福音', 40, 13, 25, '人们睡了的时候，他的仇敌来把稗子撒在麦子中间，就走了。'),
('CNV', '马太福音', 40, 13, 26, '到了发苗吐穗的时候，稗子也显出来。'),
('CNV', '马太福音', 40, 13, 27, '仆人都前来问家主：‘主人，你不是把好的种子撒在田里吗？那些稗子是从哪里来的呢？’'),
('CNV', '马太福音', 40, 13, 28, '他回答：‘这是仇敌所作的。’仆人问他：‘你要我们去拔掉它吗？’'),
('CNV', '马太福音', 40, 13, 29, '他说：‘不用，因为拔稗子的时候，恐怕也把麦子连根拔出来。'),
('CNV', '马太福音', 40, 13, 30, '收割之前，让它们一同生长。到了收割的时候，我会吩咐收割的工人先拔掉稗子，捆起来，留着焚烧，却要把麦子收进我的仓里。’”'),
('CNV', '马太福音', 40, 13, 31, '耶稣又对他们讲了另外一个比喻，说：“天国好像一粒芥菜种，人拿去把它种在田里。'),
('CNV', '马太福音', 40, 13, 32, '它是种子中最小的，但长大了，却比其他的蔬菜都大，成为一棵树，甚至天空的飞鸟也来在它的枝头搭窝。”'),
('CNV', '马太福音', 40, 13, 33, '他对他们讲了另一个比喻：“天国好像面酵，妇女拿去放在三斗面里，直到全团发起来。”'),
('CNV', '马太福音', 40, 13, 34, '耶稣用比喻向群众讲了这一切，他所讲的，没有不用比喻的。'),
('CNV', '马太福音', 40, 13, 35, '这就应验了先知所说的：“我要开口用比喻，把创世以来隐秘的事说出来。”'),
('CNV', '马太福音', 40, 13, 36, '耶稣离开群众，进到屋里，门徒前来问他：“请你给我们解释田里稗子的比喻。”'),
('CNV', '马太福音', 40, 13, 37, '他回答：“那撒好种子的是人子，'),
('CNV', '马太福音', 40, 13, 38, '田就是世界，好种子就是属天国的人，稗子就是属那恶者的人，'),
('CNV', '马太福音', 40, 13, 39, '撒稗子的仇敌是魔鬼，收割的时候是这世代的终结，收割的工人是天使。'),
('CNV', '马太福音', 40, 13, 40, '稗子怎样被拔掉用火焚烧，在这世代终结的时候，也是一样。'),
('CNV', '马太福音', 40, 13, 41, '那时，人子要差派他的使者，把一切使人犯罪的事和不法之徒，从他的国中拔掉，'),
('CNV', '马太福音', 40, 13, 42, '丢进火炉，在那里必要哀哭切齿。'),
('CNV', '马太福音', 40, 13, 43, '那时，义人在他们父的国中，要像太阳一样的照耀。有耳的，就应当听。'),
('CNV', '马太福音', 40, 13, 44, '“天国好像藏在田里的宝贝，有人发现了，就把它藏起来，高高兴兴地离去，变卖了他的一切，来买那田地。'),
('CNV', '马太福音', 40, 13, 45, '“天国好像一个商人，搜罗宝贵的珍珠。'),
('CNV', '马太福音', 40, 13, 46, '他发现了一颗极贵重的珍珠，就离去，变卖了他的一切，来买那颗珍珠。'),
('CNV', '马太福音', 40, 13, 47, '“天国又好像一个网，撒在海里，网到各样的鱼。'),
('CNV', '马太福音', 40, 13, 48, '网满了之后，人就把网拉上岸，坐下来把好的拣出，收藏起来，不好的就丢在外面。'),
('CNV', '马太福音', 40, 13, 49, '这世代终结的时候，也是一样。那时天使要出去，把恶人从义人中分别出来。'),
('CNV', '马太福音', 40, 13, 50, '丢进火炉，在那里必要哀哭切齿。'),
('CNV', '马太福音', 40, 13, 51, '“这一切你们明白吗？”他们回答：“明白。”'),
('CNV', '马太福音', 40, 13, 52, '耶稣说：“所以，每一个作天国门徒的经学家，就像家主从宝库中拿出新和旧的东西来。”'),
('CNV', '马太福音', 40, 13, 53, '耶稣讲完了这些比喻，就离开那地方。'),
('CNV', '马太福音', 40, 13, 54, '他回到自己的家乡，在会堂里教导人，众人都惊奇，说：“这个人的智慧和能力是从哪里来的呢？'),
('CNV', '马太福音', 40, 13, 55, '他不是木匠的儿子吗？他母亲不是马利亚，他弟弟不是雅各、约瑟、西门和犹大吗？'),
('CNV', '马太福音', 40, 13, 56, '他妹妹不是都在我们这里吗？他这一切是从哪里来的呢？”'),
('CNV', '马太福音', 40, 13, 57, '他们就厌弃耶稣。耶稣对他们说：“先知除了在本乡本家之外，没有不受人尊敬的。”'),
('CNV', '马太福音', 40, 13, 58, '因为他们不信，他就不在那里多行神迹了。'),
('CNV', '马太福音', 40, 14, 1, '那时，分封王希律听见耶稣的名声，'),
('CNV', '马太福音', 40, 14, 2, '就对臣仆说：“这人是施洗的约翰，他从死人中复活，所以他身上有行神迹的能力。”'),
('CNV', '马太福音', 40, 14, 3, '原来希律为了他弟弟腓力的妻子希罗底的缘故，拘捕了约翰，把他捆绑，关在监里，'),
('CNV', '马太福音', 40, 14, 4, '因为约翰多次告诉他：“你占有她是不合理的。”'),
('CNV', '马太福音', 40, 14, 5, '他想杀约翰，但又害怕群众，因为他们都认为约翰是个先知。'),
('CNV', '马太福音', 40, 14, 6, '到了希律生日的那天，希罗底的女儿在众人面前跳舞，希律非常高兴，'),
('CNV', '马太福音', 40, 14, 7, '就起誓答应她，无论求什么都给她。'),
('CNV', '马太福音', 40, 14, 8, '她在母亲的怂恿之下，说：“请把施洗的约翰的头放在盘子上给我。”'),
('CNV', '马太福音', 40, 14, 9, '王就忧愁，但因为誓言和在座的宾客，就下令给她。'),
('CNV', '马太福音', 40, 14, 10, '他派人去，在监里斩了约翰的头，'),
('CNV', '马太福音', 40, 14, 11, '把头放在盘子上，拿来给那女孩子，她又带给母亲。'),
('CNV', '马太福音', 40, 14, 12, '约翰的门徒前来，领了尸体，把它埋葬，然后去告诉耶稣。'),
('CNV', '马太福音', 40, 14, 13, '耶稣听见了，就离开那里，独自坐船到旷野去。群众听见了，就从各城步行来跟随他。'),
('CNV', '马太福音', 40, 14, 14, '耶稣上了岸，看见一大群人，就怜悯他们，医好了他们的病人。'),
('CNV', '马太福音', 40, 14, 15, '黄昏的时候，门徒前来对他说：“这是旷野的地方，时间也不早了，请叫群众散开，好让他们往村里去，买自己的食物吧。”'),
('CNV', '马太福音', 40, 14, 16, '耶稣回答：“他们用不着离开，你们给他们吃吧！”'),
('CNV', '马太福音', 40, 14, 17, '但门徒说：“我们这里除了五个饼和两条鱼，什么也没有。”'),
('CNV', '马太福音', 40, 14, 18, '他说：“拿过来给我。”'),
('CNV', '马太福音', 40, 14, 19, '于是吩咐群众坐在草地上，拿起那五个饼两条鱼，望着天，祝谢了；然后把饼擘开，递给门徒，门徒又分给群众。'),
('CNV', '马太福音', 40, 14, 20, '大家都吃了，并且吃饱了，他们把剩下的零碎拾起来，装满了十二个篮子。'),
('CNV', '马太福音', 40, 14, 21, '吃的人，除了妇女和孩子，约有五千。'),
('CNV', '马太福音', 40, 14, 22, '耶稣立刻催门徒上船，叫他们先到对岸去，他却留下来叫群众散开。'),
('CNV', '马太福音', 40, 14, 23, '他解散了群众，就独自上山去祷告。到了晚上，他还是独自一人在那里。'),
('CNV', '马太福音', 40, 14, 24, '那时门徒的船已经离岸数公里，因为逆风，被波浪冲击。'),
('CNV', '马太福音', 40, 14, 25, '天快亮的时候﹙“天快亮的时候”原文作“夜里四更天”。﹚，耶稣在海面上向他们走过去。'),
('CNV', '马太福音', 40, 14, 26, '门徒见他在海面上行走，就很惊慌，说：“有鬼啊！”并且恐惧得大叫起来。'),
('CNV', '马太福音', 40, 14, 27, '耶稣立刻对他们说：“放心吧！是我，不要怕。”'),
('CNV', '马太福音', 40, 14, 28, '彼得对他说：“主啊，如果是你，让我在水面上到你那里去。”'),
('CNV', '马太福音', 40, 14, 29, '他说：“来吧！”彼得就从船上下来，行在水面上，走向耶稣那里去。'),
('CNV', '马太福音', 40, 14, 30, '但他一见风浪就害怕，快要沉下去的时候，就呼叫：“主啊！救我！”'),
('CNV', '马太福音', 40, 14, 31, '耶稣马上伸手拉住他，对他说：“小信的人哪，为什么疑惑？”'),
('CNV', '马太福音', 40, 14, 32, '他们上了船，风就平静了。'),
('CNV', '马太福音', 40, 14, 33, '船上的人都拜他，说：“你真是神的儿子。”'),
('CNV', '马太福音', 40, 14, 34, '他们过到对岸，来到革尼撒勒的地区。'),
('CNV', '马太福音', 40, 14, 35, '那地的人认出是耶稣，就把消息传遍了那一带。众人把一切有病的人都带来，'),
('CNV', '马太福音', 40, 14, 36, '求耶稣让他们只摸一摸他衣服的繸子，摸着的人就都痊愈了。'),
('CNV', '马太福音', 40, 15, 1, '有法利赛人和经学家从耶路撒冷前来，问耶稣：'),
('CNV', '马太福音', 40, 15, 2, '“你的门徒为什么违背古人的传统，在饭前不洗手呢？”'),
('CNV', '马太福音', 40, 15, 3, '耶稣回答：“你们又为什么因你们的传统，违背神的诫命呢？'),
('CNV', '马太福音', 40, 15, 4, '神说：‘当孝敬父母’，又说：‘咒骂父母的必被处死’。'),
('CNV', '马太福音', 40, 15, 5, '你们却说：‘人若对父母说：“我应该给你们的，已经作了献给神的礼物”，'),
('CNV', '马太福音', 40, 15, 6, '他就可以不孝敬父母了。’你们因为你们的传统，就废弃了神的话。'),
('CNV', '马太福音', 40, 15, 7, '伪君子啊，以赛亚指着你们说的预言说得好：'),
('CNV', '马太福音', 40, 15, 8, '‘这人民用嘴唇尊敬我，心却远离我；'),
('CNV', '马太福音', 40, 15, 9, '他们把人的规条当作道理去教导人，所以拜我也是徒然。’”'),
('CNV', '马太福音', 40, 15, 10, '耶稣叫群众前来，对他们说：“你们要听，也要明白。'),
('CNV', '马太福音', 40, 15, 11, '进到口里的不能使人污秽，只有从口里出来的，才能使人污秽。”'),
('CNV', '马太福音', 40, 15, 12, '门徒前来告诉他：“法利赛人听了这话很生气，你知道吗？”'),
('CNV', '马太福音', 40, 15, 13, '耶稣说：“所有不是我天父栽种的植物，都要连根拔起来。'),
('CNV', '马太福音', 40, 15, 14, '由得他们吧！他们是瞎眼的，却作了向导；如果瞎子领瞎子，二人都会跌进坑里。”'),
('CNV', '马太福音', 40, 15, 15, '彼得说：“请你给我们解释这个比喻吧。”'),
('CNV', '马太福音', 40, 15, 16, '耶稣说：“你们还是不明白吗？'),
('CNV', '马太福音', 40, 15, 17, '难道不知道一切进到口里的，是进到肚腹，然后排泄到外面﹙“外面”或译：“厕所”。﹚去吗？'),
('CNV', '马太福音', 40, 15, 18, '但从口里出来的，是发自内心，才会使人污秽。'),
('CNV', '马太福音', 40, 15, 19, '因为从心里出来的，有恶念、凶杀、奸淫、淫乱、偷盗、假见证和毁谤。'),
('CNV', '马太福音', 40, 15, 20, '这些才会使人污秽，不洗手吃饭却不会这样。”'),
('CNV', '马太福音', 40, 15, 21, '耶稣离开那里，退到推罗、西顿境内。'),
('CNV', '马太福音', 40, 15, 22, '有一个迦南的妇人从那地区出来，喊着说：“主啊，大卫的子孙，可怜我吧！我的女儿被鬼附得很苦。”'),
('CNV', '马太福音', 40, 15, 23, '耶稣一句话也不回答她。门徒上前求他说：“请叫她走吧，她一直跟在我们后面喊叫。”'),
('CNV', '马太福音', 40, 15, 24, '耶稣回答：“我被差遣，只是到以色列家的迷羊那里去。”'),
('CNV', '马太福音', 40, 15, 25, '她来跪在耶稣面前说：“主啊，求你帮助我！”'),
('CNV', '马太福音', 40, 15, 26, '耶稣回答：“拿儿女的饼丢给小狗吃是不好的。”'),
('CNV', '马太福音', 40, 15, 27, '她说：“主啊，是的，不过小狗也吃主人桌子上掉下来的碎渣。”'),
('CNV', '马太福音', 40, 15, 28, '于是耶稣对她说：“妇人，你的信心真大，照你所想的给你成就吧！”从那时起，她的女儿就好了。'),
('CNV', '马太福音', 40, 15, 29, '耶稣离开那里，来到加利利海边，就上山坐下。'),
('CNV', '马太福音', 40, 15, 30, '有许多人来到他那里，把瘸腿的、瞎眼的、残废的、哑的和许多别的病人，都带到耶稣跟前，他就医好他们。'),
('CNV', '马太福音', 40, 15, 31, '群众看见哑巴说话，残废的复原，瘸腿的行走，瞎眼的看见，就十分惊奇，于是颂赞以色列的神。'),
('CNV', '马太福音', 40, 15, 32, '耶稣叫门徒前来，说：“我怜悯这一群人，因为他们跟我在一起已经有三天，也没有什么吃的；我不想叫他们饿着肚子回去，恐怕他们在路上晕倒。”'),
('CNV', '马太福音', 40, 15, 33, '门徒对他说：“我们在这旷野地方，哪里有足够的食物给这许多的人吃饱呢？”'),
('CNV', '马太福音', 40, 15, 34, '耶稣问他们：“你们有多少饼？”他们说：“七个饼和几条小鱼。”'),
('CNV', '马太福音', 40, 15, 35, '他就吩咐群众坐在地上，'),
('CNV', '马太福音', 40, 15, 36, '拿起那七个饼和那些鱼，祝谢了，擘开递给门徒，门徒又分给众人。'),
('CNV', '马太福音', 40, 15, 37, '大家都吃了，并且吃饱了。他们把剩下的零碎拾起来，装满了七个大篮子。'),
('CNV', '马太福音', 40, 15, 38, '吃的人，除了妇女和孩子，共有四千。'),
('CNV', '马太福音', 40, 15, 39, '耶稣解散了群众，就上了船，来到马加丹地区。'),
('CNV', '马太福音', 40, 16, 1, '法利赛人和撒都该人前来试探耶稣，求他显个从天上来的神迹给他们看。'),
('CNV', '马太福音', 40, 16, 2, '耶稣回答：“黄昏的时候，你们说：‘天色通红，明天一定是晴天。’'),
('CNV', '马太福音', 40, 16, 3, '早上的时候，你们说：‘天色又红又暗，今天一定有风雨。’你们知道分辨天色，却不能分辨时代的征兆吗？'),
('CNV', '马太福音', 40, 16, 4, '邪恶和淫乱的世代要寻求神迹，除了约拿的神迹之外，不会有什么神迹给它了。”耶稣就离开他们走了。'),
('CNV', '马太福音', 40, 16, 5, '门徒到了对岸，忘记了带饼。'),
('CNV', '马太福音', 40, 16, 6, '耶稣对他们说：“你们要小心，提防法利赛人和撒都该人的酵。”'),
('CNV', '马太福音', 40, 16, 7, '他们就彼此议论说：“这是因为我们没有带饼吧。”'),
('CNV', '马太福音', 40, 16, 8, '耶稣知道了，就说：“小信的人，为什么议论没有饼这件事呢？'),
('CNV', '马太福音', 40, 16, 9, '你们还不明白吗？你们是不是忘记了那五个饼分给五千人，又装满了多少个篮子呢？'),
('CNV', '马太福音', 40, 16, 10, '还是忘记了那七个饼分给四千人，又装满了多少个大篮子呢？'),
('CNV', '马太福音', 40, 16, 11, '我对你们讲的不是饼的事，你们为什么不明白？你们要提防法利赛人和撒都该人的酵。”'),
('CNV', '马太福音', 40, 16, 12, '这时他们才领会耶稣说的不是要提防饼酵，而是要提防法利赛人和撒都该人的教训。'),
('CNV', '马太福音', 40, 16, 13, '耶稣来到该撒利亚．腓立比的地区，就问自己的门徒：“人说人子是谁？”'),
('CNV', '马太福音', 40, 16, 14, '他们回答：“有人说是施洗的约翰，有人说是以利亚，也有人说是耶利米，或是先知里的一位。”'),
('CNV', '马太福音', 40, 16, 15, '他问他们：“你们说我是谁？”'),
('CNV', '马太福音', 40, 16, 16, '西门．彼得回答：“你是基督，是永生神的儿子。”'),
('CNV', '马太福音', 40, 16, 17, '耶稣对他说：“约拿的儿子西门，你是有福的，因为这不是人﹙“人”原文作“肉和血”。﹚指示你的，而是我在天上的父启示你的。'),
('CNV', '马太福音', 40, 16, 18, '我告诉你，你是彼得，我要在这磐石上建立我的教会，死亡的权势﹙“死亡的权势”原文作“阴间的门”。﹚不能胜过他。'),
('CNV', '马太福音', 40, 16, 19, '我要把天国的钥匙给你，你在地上捆绑的，在天上也被捆绑；你在地上释放的，在天上也被释放。”'),
('CNV', '马太福音', 40, 16, 20, '于是耶稣吩咐门徒不可对人说他就是基督。'),
('CNV', '马太福音', 40, 16, 21, '从那时起，耶稣开始向门徒指出，他必须往耶路撒冷去，受长老、祭司长和经学家许多的苦害，并且被杀，第三天复活。'),
('CNV', '马太福音', 40, 16, 22, '彼得就把他拉到一边，责怪他说：“主啊，千万不可这样，这事一定不会发生在你身上的。”'),
('CNV', '马太福音', 40, 16, 23, '耶稣转过来对彼得说：“撒但！退到我后面去！你是绊脚石，因为你不思念神的事，只思念人的事。”'),
('CNV', '马太福音', 40, 16, 24, '于是耶稣对门徒说：“如果有人愿意跟从我，就当舍己，背起他的十字架来跟从我。'),
('CNV', '马太福音', 40, 16, 25, '凡是想救自己生命的，必丧掉生命；但为我牺牲生命的，必得着生命。'),
('CNV', '马太福音', 40, 16, 26, '人若赚得全世界，却赔上自己的生命，有什么好处呢？人还能用什么换回自己的生命呢？'),
('CNV', '马太福音', 40, 16, 27, '人子要在父的荣耀里和众天使一同降临，那时他要照各人的行为报应各人。'),
('CNV', '马太福音', 40, 16, 28, '我实在告诉你们，站在这里的，有人在没有尝过死味以前，必要看见人子带着他的国降临。”'),
('CNV', '马太福音', 40, 17, 1, '过了六天，耶稣带着彼得、雅各和雅各的弟弟约翰，领他们悄悄地上了高山。'),
('CNV', '马太福音', 40, 17, 2, '耶稣在他们面前改变了形象，脸好像太阳一样照耀，衣服洁白像光。'),
('CNV', '马太福音', 40, 17, 3, '忽然，摩西和以利亚向他们显现，跟耶稣谈话。'),
('CNV', '马太福音', 40, 17, 4, '彼得对耶稣说：“主啊，我们在这里真好。如果你愿意，我就在这里搭三个帐棚，一个为你，一个为摩西，一个为以利亚。”'),
('CNV', '马太福音', 40, 17, 5, '彼得还说话的时候，有一朵明亮的云彩笼罩他们，云中有声音说：“这是我的爱子，我所喜悦的，你们要听他。”'),
('CNV', '马太福音', 40, 17, 6, '门徒听见了，就俯伏在地上，非常害怕。'),
('CNV', '马太福音', 40, 17, 7, '耶稣前来，摸着他们说：“起来，不用怕。”'),
('CNV', '马太福音', 40, 17, 8, '他们抬起头来，看见只有耶稣自己，没有别的人。'),
('CNV', '马太福音', 40, 17, 9, '他们下山的时候，耶稣吩咐他们：“人子从死人中复活以前，你们不要把所看见的异象告诉人。”'),
('CNV', '马太福音', 40, 17, 10, '门徒就问他：“那么经学家为什么说，以利亚必须先来呢？”'),
('CNV', '马太福音', 40, 17, 11, '他回答：“以利亚当然要来，并且复兴一切。'),
('CNV', '马太福音', 40, 17, 12, '但我告诉你们，以利亚已经来了，可是人们却不认识他，反而任意待他。照样，人子也要这样被他们苦待。”'),
('CNV', '马太福音', 40, 17, 13, '这时门徒才领悟，耶稣是指着施洗的约翰说的。'),
('CNV', '马太福音', 40, 17, 14, '耶稣和门徒来到群众那里，有一个人前来，跪下对耶稣说：'),
('CNV', '马太福音', 40, 17, 15, '“主啊，可怜我的儿子吧，他患了癫痫病，非常痛苦，好几次掉进火里和水中。'),
('CNV', '马太福音', 40, 17, 16, '我带他去见你的门徒，他们却不能医好他。”'),
('CNV', '马太福音', 40, 17, 17, '耶稣说：“唉！这又不信又乖谬的世代啊！我要跟你们在一起到几时呢？我要忍受你们到几时呢？把孩子带到我这里来吧。”'),
('CNV', '马太福音', 40, 17, 18, '耶稣斥责那鬼，鬼就从孩子身上出来；从那时起，孩子就好了。'),
('CNV', '马太福音', 40, 17, 19, '门徒悄悄地前来问耶稣：“为什么我们不能把鬼赶出去呢？”'),
('CNV', '马太福音', 40, 17, 20, '他说：“因为你们的信心太小了。我实在告诉你们，只要你们的信心像一粒芥菜种，就是对这山说：‘从这里移到那里’，它也必移开。没有什么是你们不能作的。”﹙有些抄本有第'),
('CNV', '马太福音', 40, 17, 21, '节：“这一类的鬼，如果不靠祷告和禁食，是赶不出来的。”﹚'),
('CNV', '马太福音', 40, 17, 22, '他们聚集在加利利的时候，耶稣对门徒说：“人子将要被交在人的手里，'),
('CNV', '马太福音', 40, 17, 23, '他们要杀害他，第三天他要复活。”他们就很忧愁。'),
('CNV', '马太福音', 40, 17, 24, '他们来到迦百农，收殿税的人前来对彼得说：“你们的老师不纳税吗？”'),
('CNV', '马太福音', 40, 17, 25, '他说：“纳。”他进到屋子里，耶稣先问他：“西门，你认为怎样？地上的君王向谁征收关税和丁税？向自己的儿子还是外人呢？”'),
('CNV', '马太福音', 40, 17, 26, '他回答：“外人。”耶稣对他说：“这样，儿子就可以免税了。'),
('CNV', '马太福音', 40, 17, 27, '但为了避免触犯他们，你要到海边去钓鱼；把第一条钓上来的鱼拿起来，打开鱼的嘴，你就会找到一个大银币。你可以拿去交给他们作你我的殿税。”'),
('CNV', '马太福音', 40, 18, 1, '那时，门徒前来问耶稣：“天国里谁是最大的呢？”'),
('CNV', '马太福音', 40, 18, 2, '耶稣叫了一个小孩子站在他们当中，说：'),
('CNV', '马太福音', 40, 18, 3, '“我实在告诉你们，如果你们不回转，变成像小孩子一样，一定不能进天国。'),
('CNV', '马太福音', 40, 18, 4, '所以，凡谦卑像这小孩子的，他在天国里是最大的。'),
('CNV', '马太福音', 40, 18, 5, '凡因我的名接待一个这样的小孩子的，就是接待我；'),
('CNV', '马太福音', 40, 18, 6, '但无论谁使一个信我的小弟兄犯罪，倒不如拿一块大磨石拴在他的颈项上，把他沉在深海里。'),
('CNV', '马太福音', 40, 18, 7, '“这世界有祸了，因为充满使人犯罪的事。这些事是免不了的，但那使人犯罪的有祸了！'),
('CNV', '马太福音', 40, 18, 8, '如果你的一只手或一只脚使你犯罪，就把它砍下来丢掉；你一只手或一只脚进永生，总比有两只手或两只脚被投进永火里好。'),
('CNV', '马太福音', 40, 18, 9, '如果你的一只眼睛使你犯罪，就把它挖出来丢掉；你一只眼睛进永生，总比有两只眼睛被投进地狱的火里好。'),
('CNV', '马太福音', 40, 18, 10, '“你们要小心，不要轻视这些小弟兄中的一个。我告诉你们，他们的使者在天上，常常见到我天父的面。﹙有些抄本有第'),
('CNV', '马太福音', 40, 18, 11, '节：“人子来，是要拯救失丧的人。”﹚'),
('CNV', '马太福音', 40, 18, 12, '你们认为怎样？有一个人，他有一百只羊，如果失了一只，他会不把九十九只留在山上，去寻找那迷失的吗？'),
('CNV', '马太福音', 40, 18, 13, '我实在告诉你们，他若找到了，就为这一只羊欢喜，胜过为那九十九只没有迷失的。'),
('CNV', '马太福音', 40, 18, 14, '照样，你们在天上的父是不愿意这些小弟兄中有一个失丧的。'),
('CNV', '马太福音', 40, 18, 15, '“如果你的弟兄犯了罪﹙“犯了罪”有些抄本作“得罪你”。﹚，你趁着和他单独在一起的时候，要去指出他的过失来。如果他肯听，你就得着你的弟兄。'),
('CNV', '马太福音', 40, 18, 16, '如果他不肯听，就另外带一两个人同去，好使一切话，凭两三个证人的口，可以确定。'),
('CNV', '马太福音', 40, 18, 17, '如果他再不听，就告诉教会；如果连教会他也不听，就把他看作教外人和税吏吧。'),
('CNV', '马太福音', 40, 18, 18, '“我实在告诉你们，你们在地上捆绑的，在天上也被捆绑；你们在地上释放的，在天上也被释放。'),
('CNV', '马太福音', 40, 18, 19, '我又告诉你们，你们当中若有两个人，在地上同心为什么事祈求，我在天上的父必为他们成全。'),
('CNV', '马太福音', 40, 18, 20, '因为无论在哪里，有两三个人奉我的名聚会，我就在他们中间。”'),
('CNV', '马太福音', 40, 18, 21, '那时，彼得前来问耶稣：“主啊，如果我的弟兄得罪我，我要饶恕他多少次？七次吗？”'),
('CNV', '马太福音', 40, 18, 22, '耶稣对他说：“我告诉你，不是七次，而是七十七次﹙“七十七次”或译：“七十七个次”。﹚。'),
('CNV', '马太福音', 40, 18, 23, '因此，天国好像一个王，要和他的仆人算帐，'),
('CNV', '马太福音', 40, 18, 24, '刚算的时候，有人带了一个欠下六千万银币的人来。'),
('CNV', '马太福音', 40, 18, 25, '他没有钱偿还，主人就下令叫人把他和他的妻子儿女，以及一切所有的都卖掉，用来偿还。'),
('CNV', '马太福音', 40, 18, 26, '那仆人就跪下拜他，说：‘请宽容我，我会把一切还给你的。’'),
('CNV', '马太福音', 40, 18, 27, '主人动了慈心，把那仆人放了，并且免了他的债。'),
('CNV', '马太福音', 40, 18, 28, '那仆人出来，遇见一个欠了他一百个银币的仆人，就抓住他，扼着他的喉咙，说：‘把你欠我的钱还给我。’'),
('CNV', '马太福音', 40, 18, 29, '那和他一同作仆人的就跪下求他，说：‘请宽容我，我会还给你的。’'),
('CNV', '马太福音', 40, 18, 30, '他却不肯，反而把他带走，关在监里，等他把所欠的还清。'),
('CNV', '马太福音', 40, 18, 31, '其他的仆人看见这事，非常难过，就去向主人报告这一切事情。'),
('CNV', '马太福音', 40, 18, 32, '于是主人叫他来，对他说：‘你这个恶仆，你求我，我就免了你欠我的一切。'),
('CNV', '马太福音', 40, 18, 33, '难道你不应该怜悯你的同伴，好像我怜悯你一样吗？’'),
('CNV', '马太福音', 40, 18, 34, '于是主人大怒，把他送去服刑，等他把所欠的一切还清。'),
('CNV', '马太福音', 40, 18, 35, '如果你们各人不从心里饶恕你的弟兄，我的天父也必这样待你们。”'),
('CNV', '马太福音', 40, 19, 1, '耶稣讲完了这些话，就离开加利利，来到约旦河东的犹太境内。'),
('CNV', '马太福音', 40, 19, 2, '有许多人跟着他；他在那里医好了他们。'),
('CNV', '马太福音', 40, 19, 3, '法利赛人前来试探耶稣，说：“人根据某些理由休妻，可以吗？”'),
('CNV', '马太福音', 40, 19, 4, '他回答：“造物者从起初‘造人的时候，就造男造女’。‘因此人要离开父母，与妻子连合，二人成为一体。’这些话你们没有念过吗？'),
('CNV', '马太福音', 40, 19, 6, '这样，他们不再是两个人，而是一体的了。所以神所配合的，人不可分开。”'),
('CNV', '马太福音', 40, 19, 7, '他们就问：“为什么摩西却吩咐‘人若给了休书，就可以休妻’呢？”'),
('CNV', '马太福音', 40, 19, 8, '他说：“摩西因为你们的心硬，才准许你们休妻，但起初并不是这样。'),
('CNV', '马太福音', 40, 19, 9, '我告诉你们，凡休妻另娶的，如果不是因为妻子不贞，就是犯奸淫了。”'),
('CNV', '马太福音', 40, 19, 10, '门徒对他说：“夫妻的关系既然是这样，倒不如不结婚了。”'),
('CNV', '马太福音', 40, 19, 11, '耶稣对他们说：“这话不是每个人都能领受的，只有赐给谁，谁才能领受。'),
('CNV', '马太福音', 40, 19, 12, '有些人是生来就不能结婚的，有些人不能结婚是因为人使他们这样，也有些人是为了天国的缘故自愿这样的。谁能领受就领受吧！”'),
('CNV', '马太福音', 40, 19, 13, '那时，有人带了小孩子到耶稣面前，求他给他们按手祈祷，门徒就责备那些人。'),
('CNV', '马太福音', 40, 19, 14, '但耶稣说：“让小孩子到我这里来，不要禁止他们，因为天国是属于这样的人的。”'),
('CNV', '马太福音', 40, 19, 15, '于是他给他们按手，然后离开那里。'),
('CNV', '马太福音', 40, 19, 16, '有一个人前来见耶稣，说：“老师，我要作什么善事，才可以得着永生？”'),
('CNV', '马太福音', 40, 19, 17, '耶稣说：“为什么问我关于善的事呢？只有一位是善的。如果你想进入永生，就应当遵守诫命。”'),
('CNV', '马太福音', 40, 19, 18, '他问：“什么诫命？”耶稣回答：“就是‘不可杀人，不可奸淫，不可偷盗，不可作假证供；'),
('CNV', '马太福音', 40, 19, 19, '当孝敬父母，当爱人如己’。”'),
('CNV', '马太福音', 40, 19, 20, '那青年对他说：“这一切我都遵守了，还缺少什么呢？”'),
('CNV', '马太福音', 40, 19, 21, '耶稣对他说：“如果你想要完全，就去变卖你所有的，分给穷人，你就必定有财宝在天上，而且你要来跟从我。”'),
('CNV', '马太福音', 40, 19, 22, '那青年听见这话，就忧忧愁愁地走了，原来他的财产很多。'),
('CNV', '马太福音', 40, 19, 23, '耶稣对门徒说：“我实在告诉你们，有钱的人是很难进天国的。'),
('CNV', '马太福音', 40, 19, 24, '我又告诉你们，骆驼穿过针眼，比有钱的人进神的国还容易呢！”'),
('CNV', '马太福音', 40, 19, 25, '门徒听见了，十分惊奇，就问他：“这样，谁可以得救呢？”'),
('CNV', '马太福音', 40, 19, 26, '耶稣看着他们说：“在人这是不能的，在神却凡事都能。”'),
('CNV', '马太福音', 40, 19, 27, '那时彼得对他说：“你看，我们已经舍弃一切跟从了你，我们会得到什么呢？”'),
('CNV', '马太福音', 40, 19, 28, '耶稣对他们说：“我实在告诉你们，到了万物更新，人子坐在他荣耀的宝座上的时候，你们这些跟从我的人，也会坐在十二个宝座上，审判以色列的十二个支派。'),
('CNV', '马太福音', 40, 19, 29, '凡为我的名撇下房屋、兄弟、姊妹、父母、儿女或田地的，他必得着百倍，并且承受永生。'),
('CNV', '马太福音', 40, 19, 30, '然而许多在前的将要在后，在后的将要在前。”'),
('CNV', '马太福音', 40, 20, 1, '“天国好像一个家主，清早出去雇请工人到他的葡萄园工作。'),
('CNV', '马太福音', 40, 20, 2, '他和工人讲定了一天的工钱是一个银币，然后派他们到葡萄园去。'),
('CNV', '马太福音', 40, 20, 3, '大约九点钟，他又出去，看见还有人闲站在街市上，'),
('CNV', '马太福音', 40, 20, 4, '就对他们说：‘你们也到葡萄园来吧，我会给你们合理的工钱。’'),
('CNV', '马太福音', 40, 20, 5, '他们就去了。约在正午和下午三点钟，他又出去，也是这样作。'),
('CNV', '马太福音', 40, 20, 6, '下午五点钟左右，他再出去，看见还有人站着，就问他们：‘你们为什么整天站在这里不去作工？’'),
('CNV', '马太福音', 40, 20, 7, '他们回答：‘没有人用我们。’他说：‘你们也到葡萄园来吧。’'),
('CNV', '马太福音', 40, 20, 8, '到了黄昏，园主对管工说：‘把工人叫来，给他们工钱，从最后的开始，到最先来的。’'),
('CNV', '马太福音', 40, 20, 9, '那些下午五点钟才开始作工的人来了，每个人都领到一个银币。'),
('CNV', '马太福音', 40, 20, 10, '最先作工的人也来了，以为会多得一点，但每个人也是领到一个银币。'),
('CNV', '马太福音', 40, 20, 11, '他们领到之后，就埋怨家主，说：'),
('CNV', '马太福音', 40, 20, 12, '‘我们整天在烈日之下劳苦，这些后来的人只工作了一个小时，你却给他们跟我们一样的工钱。’'),
('CNV', '马太福音', 40, 20, 13, '家主回答他们当中的一个，说：‘朋友，我并没有亏待你。你我不是讲定了一个银币吗？'),
('CNV', '马太福音', 40, 20, 14, '拿你的工钱走吧！我给那后来的和给你的一样，是我的主意。'),
('CNV', '马太福音', 40, 20, 15, '难道我不可以照自己的主意用我的财物吗？还是因为我仁慈你就嫉妒呢？’'),
('CNV', '马太福音', 40, 20, 16, '因此，在后的将要在前，在前的将要在后。”'),
('CNV', '马太福音', 40, 20, 17, '耶稣上耶路撒冷去的时候，把十二门徒带到一边，在路上对他们说：'),
('CNV', '马太福音', 40, 20, 18, '“我们现在上耶路撒冷去，人子要被交给祭司长和经学家，他们要定他死罪，'),
('CNV', '马太福音', 40, 20, 19, '把他交给外族人凌辱、鞭打，并且钉在十字架上。然而第三天他要复活。”'),
('CNV', '马太福音', 40, 20, 20, '那时，西庇太的儿子的母亲，带着她的两个儿子前来见耶稣。她跪在耶稣面前求他。'),
('CNV', '马太福音', 40, 20, 21, '耶稣问她：“你想要什么？”她说：“求你下令，使我这两个儿子在你的国里，一个坐在你的右边，一个坐在你的左边。”'),
('CNV', '马太福音', 40, 20, 22, '耶稣回答：“你们不知道你们求的是什么。我将要喝的杯，你们能喝吗？”他们说：“能。”'),
('CNV', '马太福音', 40, 20, 23, '他对他们说：“我的杯你们固然要喝，只是坐在我的左右，不是我可以赐的；我父预备赐给谁，就赐给谁。”'),
('CNV', '马太福音', 40, 20, 24, '其他十个门徒听见了，就向他们兄弟二人生气。'),
('CNV', '马太福音', 40, 20, 25, '耶稣把他们叫过来，说：“你们知道各国都有元首统治他们，也有官长管辖他们。'),
('CNV', '马太福音', 40, 20, 26, '但你们中间却不要这样；谁想在你们中间成为大的，就要作你们的仆役；'),
('CNV', '马太福音', 40, 20, 27, '谁想在你们中间为首的，就要作你们的奴仆。'),
('CNV', '马太福音', 40, 20, 28, '正如人子来，不是要受人的服事，而是要服事人，并且要舍命，作许多人的赎价。”'),
('CNV', '马太福音', 40, 20, 29, '他们从耶利哥出来的时候，有许多人跟着耶稣。'),
('CNV', '马太福音', 40, 20, 30, '有两个瞎眼的人坐在路旁，听说耶稣经过，就喊叫：“主啊，大卫的子孙，可怜我们吧！”'),
('CNV', '马太福音', 40, 20, 31, '群众责备他们，叫他们不要出声，他们却更加放声喊叫：“主啊，大卫的子孙，可怜我们吧！”'),
('CNV', '马太福音', 40, 20, 32, '耶稣就站住，叫他们过来，说：“要我为你们作什么呢？”'),
('CNV', '马太福音', 40, 20, 33, '他们说：“主啊，求你开我们的眼睛。”'),
('CNV', '马太福音', 40, 20, 34, '耶稣就怜悯他们，摸他们的眼睛。他们立刻能看见，就跟从了耶稣。'),
('CNV', '马太福音', 40, 21, 1, '耶稣和门徒走近耶路撒冷，来到橄榄山的伯法其那里。耶稣派了两个门徒，'),
('CNV', '马太福音', 40, 21, 2, '对他们说：“你们往对面的村子里去，立刻就会看见一头驴拴在那里，还有小驴跟它在一起。把它们解开，牵来给我。'),
('CNV', '马太福音', 40, 21, 3, '如果有人问你们，就要说：‘主需要它们。’他会立刻让你们牵走。”'),
('CNV', '马太福音', 40, 21, 4, '这件事应验了先知所说的：'),
('CNV', '马太福音', 40, 21, 5, '“要对锡安的居民﹙“居民”原文作“女子”。﹚说：‘看哪，你的王来到你这里了；他是温柔的，他骑着驴，骑的是小驴。’”'),
('CNV', '马太福音', 40, 21, 6, '门徒照着耶稣的吩咐去作。'),
('CNV', '马太福音', 40, 21, 7, '牵了驴和小驴来，把衣服搭在它们上面，耶稣就骑上。'),
('CNV', '马太福音', 40, 21, 8, '有一大群人把自己的衣服铺在路上，也有人从树上把树枝砍下来，铺在路上。'),
('CNV', '马太福音', 40, 21, 9, '前呼后拥的群众喊叫着：“‘和散那’归于大卫的子孙，奉主名来的是应当称颂的，高天之上当唱‘和散那’。”'),
('CNV', '马太福音', 40, 21, 10, '耶稣进了耶路撒冷，全城都震动起来，他们问：“这人是谁？”'),
('CNV', '马太福音', 40, 21, 11, '大家都说：“这就是那先知耶稣，是从加利利的拿撒勒来的。”'),
('CNV', '马太福音', 40, 21, 12, '耶稣进了圣殿，把殿里所有作买卖的人赶走，并推倒找换银钱的人的桌子，和卖鸽子的人的凳子；'),
('CNV', '马太福音', 40, 21, 13, '又对他们说：“经上记着：‘我的殿要称为祷告的殿。’你们竟把它弄成贼窝了。”'),
('CNV', '马太福音', 40, 21, 14, '殿里的瞎子和瘸腿的都走过来，耶稣就医好他们。'),
('CNV', '马太福音', 40, 21, 15, '祭司长和经学家看见耶稣所行的奇事，又看见小孩子在殿中喊叫“‘和散那’归于大卫的子孙”，就很忿怒，'),
('CNV', '马太福音', 40, 21, 16, '对耶稣说：“你听见他们说什么吗？”耶稣说：“我听见了。‘你从小孩和婴儿的口中，得着了赞美。’这话你们没有念过吗？”'),
('CNV', '马太福音', 40, 21, 17, '于是离开他们，出了城，来到伯大尼，在那里过了一夜。'),
('CNV', '马太福音', 40, 21, 18, '耶稣清早回城的时候，觉得饿了。'),
('CNV', '马太福音', 40, 21, 19, '他看见路旁有一棵无花果树，就走过去；但他在树上什么也找不到，只有叶子，就对树说：“你永远不再结果子了。”那棵树就立刻枯萎。'),
('CNV', '马太福音', 40, 21, 20, '门徒看见了，十分惊奇，说：“这棵无花果树是怎样立刻枯萎的呢？”'),
('CNV', '马太福音', 40, 21, 21, '耶稣回答他们：“我实在告诉你们，如果你们有信心，不怀疑，不但能作我对无花果树所作的，就是对这座山说‘移开，投到海里去’，也必成就。'),
('CNV', '马太福音', 40, 21, 22, '你们祷告，无论求什么，只要相信，都必得着。”'),
('CNV', '马太福音', 40, 21, 23, '耶稣进了圣殿，正在教导人的时候，祭司长和民间的长老前来问他：“你凭什么权柄作这些事？谁给你这权柄？”'),
('CNV', '马太福音', 40, 21, 24, '耶稣回答他们：“我也要问你们一句话，如果你们告诉我，我就告诉你们我凭什么权柄作这些事。'),
('CNV', '马太福音', 40, 21, 25, '约翰的洗礼是从哪里来的呢？是从天上来的，还是从人来的呢？”他们就彼此议论：“如果我们说‘是从天上来的’，他会问我们‘那你们为什么不信他呢？’'),
('CNV', '马太福音', 40, 21, 26, '如果我们说‘是从人来的’，我们又怕群众，因为他们都认为约翰是先知。”'),
('CNV', '马太福音', 40, 21, 27, '于是回答耶稣：“我们不知道。”耶稣也对他们说：“我也不告诉你们，我凭什么权柄作这些事。'),
('CNV', '马太福音', 40, 21, 28, '“你们认为怎样？有一个人，他有两个儿子。他去对大儿子说：‘孩子，你今天到葡萄园去工作吧。’'),
('CNV', '马太福音', 40, 21, 29, '他说：‘我不想去。’但后来他改变主意，就去了。'),
('CNV', '马太福音', 40, 21, 30, '父亲又照样去吩咐小儿子。小儿子说：‘父亲，我会去的。’后来却没有去。'),
('CNV', '马太福音', 40, 21, 31, '这两个儿子，哪一个听父亲的话呢？”他们说：“大儿子。”耶稣对他们说：“我实在告诉你们：税吏和娼妓比你们先进神的国。'),
('CNV', '马太福音', 40, 21, 32, '约翰来到你们那里，指示你们行义路﹙或译：“约翰在义路中，来到你们这里”。﹚，你们不信他；税吏和娼妓却信了他。你们看见了之后，还是没有改变心意去信他。'),
('CNV', '马太福音', 40, 21, 33, '“你们再听一个比喻：有一个家主，栽种了一个葡萄园，四面围上篱笆，在园子里挖了一个压酒池，盖了一座瞭望台，然后把园子租给佃户，就远行去了。'),
('CNV', '马太福音', 40, 21, 34, '到了收成的时候，园主派了仆人到佃户那里，收取应该纳给他的果子。'),
('CNV', '马太福音', 40, 21, 35, '佃户却抓住他的仆人，打伤一个，杀了一个，又用石头打死一个。'),
('CNV', '马太福音', 40, 21, 36, '于是园主再派其他的仆人去，人数比前一次更多，但佃户也是同样对付他们。'),
('CNV', '马太福音', 40, 21, 37, '最后，他派了自己的儿子去，说：‘他们必尊敬我的儿子。’'),
('CNV', '马太福音', 40, 21, 38, '佃户看见他的儿子，就彼此说：‘这是继承产业的；来，我们杀了他，占有他的产业吧！’'),
('CNV', '马太福音', 40, 21, 39, '于是他们抓住他，把他推出葡萄园外杀了。'),
('CNV', '马太福音', 40, 21, 40, '那么，葡萄园的主人来到的时候，会怎样对待那些佃户呢？”'),
('CNV', '马太福音', 40, 21, 41, '他们回答：“他会毫不留情地除掉那些恶人，把葡萄园租给按时缴纳果子的佃户。”'),
('CNV', '马太福音', 40, 21, 42, '耶稣对他们说：“经上记着：‘建筑工人所弃的石头，成了房角的主要石头；这是主所作的，在我们眼中看为希奇。’这话你们没有念过吗？'),
('CNV', '马太福音', 40, 21, 43, '因此我告诉你们，神的国要从你们那里取去，赐给那结果子的外族人。'),
('CNV', '马太福音', 40, 21, 44, '谁跌在这石头上，就必摔碎；这石头掉在谁的身上，就必把他压得粉碎。”'),
('CNV', '马太福音', 40, 21, 45, '祭司长和法利赛人听了耶稣这些比喻，知道是指着他们说的。'),
('CNV', '马太福音', 40, 21, 46, '他们想要逮捕他，但又怕群众，因为他们都认为耶稣是先知。'),
('CNV', '马太福音', 40, 22, 1, '耶稣又用比喻对他们说：'),
('CNV', '马太福音', 40, 22, 2, '“天国好像一个王，为儿子摆设婚筵。'),
('CNV', '马太福音', 40, 22, 3, '他派仆人去叫被邀请的人来参加婚筵。但他们不肯来。'),
('CNV', '马太福音', 40, 22, 4, '他再派另一些仆人去，说：‘你们告诉被邀请的人，我已经预备好了筵席，公牛和肥畜已经宰了，一切都预备妥当。来参加婚筵吧！’'),
('CNV', '马太福音', 40, 22, 5, '但那些人却不理会就走了；有的去耕田，有的去作买卖，'),
('CNV', '马太福音', 40, 22, 6, '其余的抓住王的仆人，凌辱他们，并且把他们杀了。'),
('CNV', '马太福音', 40, 22, 7, '王就发怒，派兵消灭那些凶手，焚毁他们的城。'),
('CNV', '马太福音', 40, 22, 8, '然后对仆人说：‘婚筵已经预备好了，只是被邀请的人不配。'),
('CNV', '马太福音', 40, 22, 9, '所以你们要到大路口，凡遇见的，都请来参加婚筵。’'),
('CNV', '马太福音', 40, 22, 10, '“那些仆人就走到街上，把所有遇见的，不论好人坏人，都招聚了来，婚筵上就坐满了人。'),
('CNV', '马太福音', 40, 22, 11, '王进来与赴筵的人见面，看见有一个人没有穿着婚筵的礼服，'),
('CNV', '马太福音', 40, 22, 12, '就对他说：‘朋友，你没有婚筵的礼服，怎能进到这里来呢？’他就无话可说。'),
('CNV', '马太福音', 40, 22, 13, '于是王对侍从说：‘把他的手和脚都绑起来，丢到外面的黑暗里，在那里必要哀哭切齿。’'),
('CNV', '马太福音', 40, 22, 14, '因为被召的人多，选上的人少。”'),
('CNV', '马太福音', 40, 22, 15, '法利赛人就去商量，怎样找耶稣的话柄来陷害他。'),
('CNV', '马太福音', 40, 22, 16, '他们派了自己的门徒和希律党的人一同去问耶稣：“老师，我们知道你为人诚实，照着真理把神的道教导人，不顾忌任何人，因为你不徇情面。'),
('CNV', '马太福音', 40, 22, 17, '请把你的意见告诉我们，纳税给凯撒，可不可以呢？”'),
('CNV', '马太福音', 40, 22, 18, '耶稣看出他们的恶意，就说：“虚伪的人，为什么试探我呢？'),
('CNV', '马太福音', 40, 22, 19, '拿纳税的钱币给我看看。”他们就拿了一个银币给他。'),
('CNV', '马太福音', 40, 22, 20, '耶稣问他们：“这是谁的像，谁的名号？”'),
('CNV', '马太福音', 40, 22, 21, '他们回答：“凯撒的。”他就对他们说：“凯撒的应当归给凯撒，神的应当归给神。”'),
('CNV', '马太福音', 40, 22, 22, '他们听了，十分惊奇，就离开他走了。'),
('CNV', '马太福音', 40, 22, 23, '撒都该人向来认为没有复活的事。那一天，他们前来问耶稣：'),
('CNV', '马太福音', 40, 22, 24, '“老师，摩西说：‘如果一个人死了，没有儿女，他的弟弟应该娶他的妻子，为哥哥立后。’'),
('CNV', '马太福音', 40, 22, 25, '从前我们这里有兄弟七人，头一个结了婚，没有孩子就死了，留下妻子给他的弟弟。'),
('CNV', '马太福音', 40, 22, 26, '第二个、第三个直到第七个都是这样。'),
('CNV', '马太福音', 40, 22, 27, '最后，那女人也死了。'),
('CNV', '马太福音', 40, 22, 28, '那么，复活的时候，她是这七个人中哪一个的妻子呢？因为他们都娶过她。”'),
('CNV', '马太福音', 40, 22, 29, '耶稣回答他们：“你们错了，因为你们不明白圣经，也不晓得神的能力。'),
('CNV', '马太福音', 40, 22, 30, '复活的时候，人们也不娶也不嫁，而是像天上的使者一样。'),
('CNV', '马太福音', 40, 22, 31, '关于死人复活的事，神对你们讲过：‘我是亚伯拉罕的神，以撒的神，雅各的神’，你们没有念过吗？神不是死人的神，而是活人的神。”'),
('CNV', '马太福音', 40, 22, 33, '群众听了他的教训，就十分诧异。'),
('CNV', '马太福音', 40, 22, 34, '法利赛人听见耶稣使撒都该人无话可说，就聚集在一起。'),
('CNV', '马太福音', 40, 22, 35, '他们中间有一个律法家，试探耶稣说：'),
('CNV', '马太福音', 40, 22, 36, '“老师，律法中哪一条诫命是最重要的呢？”'),
('CNV', '马太福音', 40, 22, 37, '他回答：“你要全心、全性、全意爱主你的神。'),
('CNV', '马太福音', 40, 22, 38, '这是最重要的第一条诫命。'),
('CNV', '马太福音', 40, 22, 39, '第二条也和它相似，就是要爱人如己。'),
('CNV', '马太福音', 40, 22, 40, '全部律法和先知书，都以这两条诫命作为根据。”'),
('CNV', '马太福音', 40, 22, 41, '法利赛人聚在一起的时候，耶稣问他们：'),
('CNV', '马太福音', 40, 22, 42, '“你们对基督的看法怎样？他是谁的子孙呢？”他们回答：“大卫的子孙。”'),
('CNV', '马太福音', 40, 22, 43, '耶稣就说：“那么大卫被圣灵感动，怎么会称他为主呢？他说：'),
('CNV', '马太福音', 40, 22, 44, '‘主对我的主说：你坐在我的右边，等我把你的仇敌放在你的脚下。’'),
('CNV', '马太福音', 40, 22, 45, '“大卫既然称他为主，他怎么又是大卫的子孙呢？”'),
('CNV', '马太福音', 40, 22, 46, '没有人能够回答他。从那天起，也没有人敢再问他。'),
('CNV', '马太福音', 40, 23, 1, '那时，耶稣对群众和他的门徒说：'),
('CNV', '马太福音', 40, 23, 2, '“经学家和法利赛人坐在摩西的座位上，'),
('CNV', '马太福音', 40, 23, 3, '所以凡他们吩咐你们的，你们都要遵行和谨守，但不可效法他们的行为，因为他们只会说而不去作。'),
('CNV', '马太福音', 40, 23, 4, '他们把重担捆起来，压在人的肩头上，但自己连一个指头也不肯动。'),
('CNV', '马太福音', 40, 23, 5, '他们所作的一切，都是要作给人看：他们把经文的匣子做大了，衣服的繸子做长了；'),
('CNV', '马太福音', 40, 23, 6, '他们喜欢筵席上的首位、会堂里的高位；'),
('CNV', '马太福音', 40, 23, 7, '又喜欢人在市中心向他们问安，称呼他们‘拉比’。'),
('CNV', '马太福音', 40, 23, 8, '然而你们不要被人称为‘拉比’，因为只有一位是你们的老师，你们都是弟兄。'),
('CNV', '马太福音', 40, 23, 9, '不要称呼地上的人为父，因为只有一位是你们的父，就是天父。'),
('CNV', '马太福音', 40, 23, 10, '你们也不要被人称为师傅，因为只有一位是你们的师傅，就是基督。'),
('CNV', '马太福音', 40, 23, 11, '你们中间最大的，必作你们的仆人。'),
('CNV', '马太福音', 40, 23, 12, '凡高抬自己的，必被降卑；凡自己谦卑的，必被升高。'),
('CNV', '马太福音', 40, 23, 13, '“虚伪的经学家和法利赛人哪，你们有祸了！你们在人面前关了天国的门，自己不进去，连正要进去的人，你们也不准他们进去。﹙有些抄本有第'),
('CNV', '马太福音', 40, 23, 14, '节：“虚伪的经学家和法利赛人哪，你们有祸了！你们吞没了寡妇的房产，假装作冗长的祷告，所以你们必受更重的刑罚。”﹚'),
('CNV', '马太福音', 40, 23, 15, '“虚伪的经学家和法利赛人哪，你们有祸了！你们走遍海洋陆地，要使一个人入教；当他入了教，你们却使他沦为地狱之子，比你们更甚。'),
('CNV', '马太福音', 40, 23, 16, '“你们这些瞎眼的向导有祸了！你们说：‘凡指着圣所而起的誓，是没有用的；但指着圣所的金子而起的誓，就必须遵守。’'),
('CNV', '马太福音', 40, 23, 17, '你们这些瞎眼的愚昧人哪，到底是金子大，还是使金子成圣的圣所大呢？'),
('CNV', '马太福音', 40, 23, 18, '你们又说：‘凡指着祭坛所起的誓，是没有用的；但指着坛上的祭物所起的誓，就必须遵守。’'),
('CNV', '马太福音', 40, 23, 19, '瞎眼的人哪！到底是祭物大，还是使祭物成圣的祭坛大呢？'),
('CNV', '马太福音', 40, 23, 20, '所以，凡指着祭坛起誓的，他就是指着祭坛和坛上的一切起誓；'),
('CNV', '马太福音', 40, 23, 21, '指着圣所起誓的，就是指着圣所和住在那里的神起誓；'),
('CNV', '马太福音', 40, 23, 22, '指着天起誓的，就是指着神的宝座和坐在宝座上的起誓。'),
('CNV', '马太福音', 40, 23, 23, '“虚伪的经学家和法利赛人哪，你们有祸了！你们把薄荷、茴香、芹菜，献上十分之一，却忽略律法上更重要的，就如正义、怜悯和信实；这些更重要的是你们应当作的，但其他的也不可忽略。'),
('CNV', '马太福音', 40, 23, 24, '你们这些瞎眼的向导啊，你们把蚊虫滤出来，却把骆驼吞下去。'),
('CNV', '马太福音', 40, 23, 25, '“虚伪的经学家和法利赛人哪，你们有祸了！你们洗净杯盘的外面，里面却装满了抢夺和放荡。'),
('CNV', '马太福音', 40, 23, 26, '瞎眼的法利赛人哪，先把杯和盘的里面洗净，好使外面也可以干净。'),
('CNV', '马太福音', 40, 23, 27, '“虚伪的经学家和法利赛人哪，你们有祸了！你们好像粉饰了的坟墓，外面好看，里面却装满了死人的骨头和各样的污秽；'),
('CNV', '马太福音', 40, 23, 28, '照样，你们外面看来像义人，里面却充塞着虚伪和不法。'),
('CNV', '马太福音', 40, 23, 29, '“虚伪的经学家和法利赛人哪，你们有祸了！你们建造先知的墓，修饰义人的碑，'),
('CNV', '马太福音', 40, 23, 30, '并且说：‘我们若活在我们祖先的时代，决不会与他们一同流先知的血。’'),
('CNV', '马太福音', 40, 23, 31, '这样，你们就指证自己是杀害先知的人的子孙了。'),
('CNV', '马太福音', 40, 23, 32, '那么，去完成你们祖先的罪孽吧！'),
('CNV', '马太福音', 40, 23, 33, '你们这些蛇，这些毒蛇所生的啊，你们怎能逃脱地狱的刑罚呢？'),
('CNV', '马太福音', 40, 23, 34, '因此，我差派先知、智慧人和经学家到你们那里；有些你们要杀害又钉在十字架上，有些你们要在会堂里鞭打，从一个城赶逐到另一个城。'),
('CNV', '马太福音', 40, 23, 35, '所以，从义人亚伯的血起，到巴拉加的儿子撒迦利亚的血为止，他就是你们在圣所和祭坛中间所杀的，所有义人在地上所流的血，都要归在你们身上。'),
('CNV', '马太福音', 40, 23, 36, '我实在告诉你们，这一切都必临到这个世代。'),
('CNV', '马太福音', 40, 23, 37, '“耶路撒冷，耶路撒冷啊，你杀害先知，又用石头把奉派到你们那里的人打死。我多次想招聚你的儿女，好像母鸡招聚小鸡到翅膀底下，只是你们不愿意。'),
('CNV', '马太福音', 40, 23, 38, '你看，你们的家必成为荒场，留给你们。'),
('CNV', '马太福音', 40, 23, 39, '我告诉你们，从今以后，你们一定见不到我，直等到你们说：‘奉主名来的，是应当称颂的。’”'),
('CNV', '马太福音', 40, 24, 1, '耶稣出了圣殿，往前走的时候，门徒前来把圣殿的建筑指给他看。'),
('CNV', '马太福音', 40, 24, 2, '他对门徒说：“你们不是看见了这一切吗？我实在告诉你们，将来在这里必没有一块石头留在另一块石头上面，每一块都要拆下来。”'),
('CNV', '马太福音', 40, 24, 3, '耶稣坐在橄榄山上，门徒暗中前来问他：“请告诉我们，什么时候会有这些事呢？你的降临和这世代的终结，有什么预兆呢？”'),
('CNV', '马太福音', 40, 24, 4, '耶稣回答他们：“你们要小心，不要被人迷惑；'),
('CNV', '马太福音', 40, 24, 5, '因为许多人要假冒我的名而来，说：‘我就是基督’，并且要迷惑许多的人。'),
('CNV', '马太福音', 40, 24, 6, '你们要听见战争，也听见战争的风声；你们要小心，不要惊慌，因为这是免不了的，不过结局还没有到。'),
('CNV', '马太福音', 40, 24, 7, '一个民族要起来攻打另一个民族，一个国家要起来攻打另一个国家，到处都有饥荒和地震，'),
('CNV', '马太福音', 40, 24, 8, '这一切不过是痛苦的开始。'),
('CNV', '马太福音', 40, 24, 9, '那时人要把你们送去受苦，也要杀害你们，你们要因我的名被万民恨恶。'),
('CNV', '马太福音', 40, 24, 10, '那时许多人会失去信仰，彼此出卖，互相恨恶；'),
('CNV', '马太福音', 40, 24, 11, '也有许多假先知出现，要迷惑许多人。'),
('CNV', '马太福音', 40, 24, 12, '因为不法的事增加，许多人的爱心就冷淡了。'),
('CNV', '马太福音', 40, 24, 13, '唯有坚忍到底的，必然得救。'),
('CNV', '马太福音', 40, 24, 14, '这天国的福音要传遍天下，向万民作见证，然后结局才来到。'),
('CNV', '马太福音', 40, 24, 15, '“当你们看见但以理先知所说的‘那造成荒凉的可憎者’，站在圣地的时候（读者必须领悟），'),
('CNV', '马太福音', 40, 24, 16, '那时，住在犹太的应当逃到山上；'),
('CNV', '马太福音', 40, 24, 17, '在房顶的不要下来拿家里的东西；'),
('CNV', '马太福音', 40, 24, 18, '在田里的也不要回去取衣服。'),
('CNV', '马太福音', 40, 24, 19, '当那些日子，怀孕的和乳养孩子的有祸了！'),
('CNV', '马太福音', 40, 24, 20, '你们应当祈求，叫你们逃难的时候，不是在冬天或安息日，'),
('CNV', '马太福音', 40, 24, 21, '因为那时必有大灾难，这是从世界的开始到现在未曾有过的，以后也必不会再有。'),
('CNV', '马太福音', 40, 24, 22, '如果那些日子不减少，没有一个人可以存活；但是为了选民，那些日子必会减少。'),
('CNV', '马太福音', 40, 24, 23, '那时，如果有人对你们说：‘看哪，基督在这里！’或说：‘他在那里！’你们不要信，'),
('CNV', '马太福音', 40, 24, 24, '因为必有假基督和假先知出现，显大神迹和奇事；如果可以的话，他们连选民也要迷惑。'),
('CNV', '马太福音', 40, 24, 25, '你们看！我已经事先告诉你们了。'),
('CNV', '马太福音', 40, 24, 26, '如果他们对你们说：‘看！基督在旷野里。’你们不要出去；或说：‘看！他在内室里。’也不要相信。'),
('CNV', '马太福音', 40, 24, 27, '电光怎样从东方闪出来，一直照到西方，人子降临的时候，也是这样。'),
('CNV', '马太福音', 40, 24, 28, '尸首在哪里，鹰也必聚在哪里。'),
('CNV', '马太福音', 40, 24, 29, '“那些日子的灾难刚过去：太阳就变黑了，月亮也不发光，众星从天坠落，天上的万象震动。'),
('CNV', '马太福音', 40, 24, 30, '“那时，人子的征兆要显在天上，地上的万族都要哀号，并且看见人子带着能力，满有荣耀，驾着天上的云降临。'),
('CNV', '马太福音', 40, 24, 31, '当号筒发出响声，他要差派使者，把他的选民从四方，从天这边到天那边都招聚来。'),
('CNV', '马太福音', 40, 24, 32, '“你们应该从无花果树学个功课：树枝长出嫩芽生出叶子的时候，你们就知道夏天近了；'),
('CNV', '马太福音', 40, 24, 33, '同样，当你们看见这一切，就知道人子已经近在门口了。'),
('CNV', '马太福音', 40, 24, 34, '我实在告诉你们，这一切都必要发生，然后这世代才会过去。'),
('CNV', '马太福音', 40, 24, 35, '天地都要过去，但我的话决不会废去。'),
('CNV', '马太福音', 40, 24, 36, '“至于那日子和时间，没有人知道，连天上的使者和子也不知道，只有父知道。'),
('CNV', '马太福音', 40, 24, 37, '挪亚的时代怎样，人子降临的时候也是这样。'),
('CNV', '马太福音', 40, 24, 38, '洪水之前的时代，人们吃喝嫁娶，直到挪亚进入方舟的那一天；'),
('CNV', '马太福音', 40, 24, 39, '等到洪水来到，把他们冲去，他们才明白过来；人子降临的时候也是这样。'),
('CNV', '马太福音', 40, 24, 40, '那时，两个人在田里工作，一个被接去，一个撇下来；'),
('CNV', '马太福音', 40, 24, 41, '两个女人在磨坊推磨，一个被接去，一个撇下来。'),
('CNV', '马太福音', 40, 24, 42, '因此，你们要警醒，因为不知道你们的主什么时候要来。'),
('CNV', '马太福音', 40, 24, 43, '你们都知道，家主若晓得窃贼晚上什么时候会来，就会提高警觉，不让他摸进屋里。'),
('CNV', '马太福音', 40, 24, 44, '所以，你们也要准备妥当，因为在想不到的时候，人子就来了。'),
('CNV', '马太福音', 40, 24, 45, '“谁是忠心和精明的仆人，被主人指派管理全家，按时分派粮食的呢？'),
('CNV', '马太福音', 40, 24, 46, '主人来到，看见他这样作，那仆人就有福了。'),
('CNV', '马太福音', 40, 24, 47, '我实在告诉你们，主人要指派他管理自己的一切财产。'),
('CNV', '马太福音', 40, 24, 48, '如果他是个坏的仆人，心里说‘我的主人不会那么快回来’，'),
('CNV', '马太福音', 40, 24, 49, '就动手打其他的仆人，又和醉酒的人吃喝。'),
('CNV', '马太福音', 40, 24, 50, '在他想不到的日子，不知道的时间，那仆人的主人要来，'),
('CNV', '马太福音', 40, 24, 51, '严厉地处罚他，使他和虚伪的人同在一起；在那里必要哀哭切齿。”'),
('CNV', '马太福音', 40, 25, 1, '“那时，天国好像十个童女，拿着她们的灯出去迎接新郎。'),
('CNV', '马太福音', 40, 25, 2, '她们中间有五个是愚蠢的，五个是聪明的。'),
('CNV', '马太福音', 40, 25, 3, '那些愚蠢的拿着灯，却没有带油；'),
('CNV', '马太福音', 40, 25, 4, '但那些聪明的拿着灯，也把油装在瓶里带来。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '马太福音', 40, 25, 5, '新郎很晚还没有到，她们都打瞌睡，而且睡着了。'),
('CNV', '马太福音', 40, 25, 6, '半夜，有人喊叫：‘新郎来了，快出来迎接他。’'),
('CNV', '马太福音', 40, 25, 7, '那些童女都醒过来，整理她们的灯。'),
('CNV', '马太福音', 40, 25, 8, '愚蠢的对聪明的说：‘请把你们的油分一点给我们，我们的灯快要灭了。’'),
('CNV', '马太福音', 40, 25, 9, '聪明的回答：‘这些恐怕不够我们大家用，不如你们自己到卖油的地方去买吧！’'),
('CNV', '马太福音', 40, 25, 10, '她们去买油的时候，新郎来了；准备好了的童女就和他一同进去参加婚筵，门就关上了。'),
('CNV', '马太福音', 40, 25, 11, '后来，其余的童女也来到，说：‘主啊，主啊，给我们开门吧！’'),
('CNV', '马太福音', 40, 25, 12, '新郎却回答：‘我实在告诉你们，我不认识你们。’'),
('CNV', '马太福音', 40, 25, 13, '所以你们要警醒，因为不知道那日子和那时间。'),
('CNV', '马太福音', 40, 25, 14, '“天国又像一个人要出外远行，就叫自己的仆人来，把产业交给他们。'),
('CNV', '马太福音', 40, 25, 15, '他按照各人的才干，一个给三万个银币，一个给一万二千个银币，一个给六千个银币﹙原文作“五个，二个，一个他连得”；一个他连得等于六千个银币。﹚，然后就远行去了。'),
('CNV', '马太福音', 40, 25, 16, '那领了三万的马上去做生意，另外赚了三万。'),
('CNV', '马太福音', 40, 25, 17, '那领了一万二千的也是这样，另赚了一万二千。'),
('CNV', '马太福音', 40, 25, 18, '但那领了六千的，却去把地挖开，把主人的钱藏起来。'),
('CNV', '马太福音', 40, 25, 19, '过了很久，那些仆人的主人回来了，要和他们算帐。'),
('CNV', '马太福音', 40, 25, 20, '那领了三万个银币的，带着另外的三万前来，说：‘主啊，你交了三万给我，你看，我又赚了三万。’'),
('CNV', '马太福音', 40, 25, 21, '主人对他说：‘又良善又忠心的仆人哪，你作得好！你既然在不多的事上忠心，我要派你管理许多的事。进来，享受你主人的快乐吧！’'),
('CNV', '马太福音', 40, 25, 22, '那领了一万二千的也前来，说：‘主啊，你交了一万二千给我，你看，我又赚了一万二千。’'),
('CNV', '马太福音', 40, 25, 23, '主人对他说：‘又良善又忠心的仆人哪，你作得好！你既然在不多的事上忠心，我要派你管理许多的事。进来，享受你主人的快乐吧！’'),
('CNV', '马太福音', 40, 25, 24, '那领了六千的也前来，说：‘主啊，我知道你是个严厉的人，没有撒种的地方，你要收割；没有散播的地方，你要收聚。'),
('CNV', '马太福音', 40, 25, 25, '所以，我就害怕起来，去把你的钱藏在地里。你看，你的钱还在这里。’'),
('CNV', '马太福音', 40, 25, 26, '可是主人对他说：‘你这个又可恶又懒惰的仆人，你既然知道我要在没有撒种的地方收割，在没有散播的地方收聚，'),
('CNV', '马太福音', 40, 25, 27, '那你就应该把我的钱存入银行，到我回来的时候，可以连本带利收回。'),
('CNV', '马太福音', 40, 25, 28, '你们把他的六千银币拿去，交给那个有六万的。'),
('CNV', '马太福音', 40, 25, 29, '因为凡是有的，还要给他，他就充足有余；凡是没有的，就算他有什么也要拿去。'),
('CNV', '马太福音', 40, 25, 30, '把这没有用的仆人丢在外面的黑暗里，在那里必要哀哭切齿。’'),
('CNV', '马太福音', 40, 25, 31, '“当人子在他的荣耀里，带着所有的使者降临的时候，他要坐在荣耀的宝座上。'),
('CNV', '马太福音', 40, 25, 32, '万族要聚集在他面前，他要把他们彼此分开，好像牧羊人把绵羊和山羊分开一样：'),
('CNV', '马太福音', 40, 25, 33, '把绵羊放在右边，山羊放在左边。'),
('CNV', '马太福音', 40, 25, 34, '那时，王要对右边的说：‘蒙我父赐福的，来承受创世以来为你们预备好的国吧。'),
('CNV', '马太福音', 40, 25, 35, '因为我饿了，你们给我吃；我渴了，你们给我喝；我作旅客，你们接待我；'),
('CNV', '马太福音', 40, 25, 36, '我赤身露体，你们给我衣服穿；我病了，你们看顾我；我在监里，你们来看我。’'),
('CNV', '马太福音', 40, 25, 37, '义人就回答：‘主啊，我们什么时候见你饿了就给你吃，渴了就给你喝呢？'),
('CNV', '马太福音', 40, 25, 38, '又什么时候见你作旅客就接待你，赤身露体就给你衣服穿呢？'),
('CNV', '马太福音', 40, 25, 39, '或者什么时候见你病了，或在监里就来看你呢？’'),
('CNV', '马太福音', 40, 25, 40, '王要回答他们：‘我实在告诉你们，你们所作的，只要是作在我一个最小的弟兄身上，就是作在我的身上了。’'),
('CNV', '马太福音', 40, 25, 41, '“王也要对左边的说：‘你们这被咒诅的，离开我，到为魔鬼和他的使者所预备的永火里去吧！'),
('CNV', '马太福音', 40, 25, 42, '因为我饿了，你们没有给我吃；我渴了，你们没有给我喝；'),
('CNV', '马太福音', 40, 25, 43, '我作旅客，你们没有接待我；我赤身露体，你们没有给我衣服穿；我病了，我在监里，你们没有看顾我。’'),
('CNV', '马太福音', 40, 25, 44, '他们就回答：‘主啊，我们什么时候见你饿了、渴了、作旅客、赤身露体、病了，或在监里，却没有服事你呢？’'),
('CNV', '马太福音', 40, 25, 45, '王要回答他们：‘我实在告诉你们，这些事你们既然没有作在一个最小的身上，就是没有作在我的身上了。’'),
('CNV', '马太福音', 40, 25, 46, '他们要进入永远的刑罚，义人却要进入永生。”'),
('CNV', '马太福音', 40, 26, 1, '耶稣说完了这一切话，就对门徒说：'),
('CNV', '马太福音', 40, 26, 2, '“你们知道两天之后就是逾越节，人子将要被交给人，钉在十字架上。”'),
('CNV', '马太福音', 40, 26, 3, '那时，祭司长和民间的长老聚集在大祭司该亚法的官邸，'),
('CNV', '马太福音', 40, 26, 4, '商议怎样用诡计逮捕耶稣，把他杀害。'),
('CNV', '马太福音', 40, 26, 5, '不过他们说：“不可在节期下手，免得引起民众暴动。”'),
('CNV', '马太福音', 40, 26, 6, '耶稣在伯大尼，在患痲风的西门家里的时候，'),
('CNV', '马太福音', 40, 26, 7, '有一个女人拿着一瓶珍贵的香膏前来，当耶稣坐席的时候，把它浇在耶稣的头上。'),
('CNV', '马太福音', 40, 26, 8, '门徒看见了，就很生气，说：“为什么这样浪费呢？'),
('CNV', '马太福音', 40, 26, 9, '这香膏可以卖很多钱，周济穷人。”'),
('CNV', '马太福音', 40, 26, 10, '耶稣知道了，就说：“为什么难为这个女人呢？她为我作了一件美事。'),
('CNV', '马太福音', 40, 26, 11, '你们常常有穷人跟你们在一起，然而却不常有我。'),
('CNV', '马太福音', 40, 26, 12, '她把这香膏浇在我身上，是为了安葬我而作的。'),
('CNV', '马太福音', 40, 26, 13, '我实在告诉你们，这福音无论传到世界上什么地方，这女人所作的都要传讲，来记念她。”'),
('CNV', '马太福音', 40, 26, 14, '那时，十二门徒中的一个，就是加略人犹大，去见祭司长，说：'),
('CNV', '马太福音', 40, 26, 15, '“如果我把他交给你们，你们愿意给我什么呢？”他们就给了他三十块银子。'),
('CNV', '马太福音', 40, 26, 16, '从那时起，他就找机会把耶稣交给他们。'),
('CNV', '马太福音', 40, 26, 17, '除酵节的第一天，门徒前来问耶稣：“你要我们在哪里为你预备逾越节的晚餐呢？”'),
('CNV', '马太福音', 40, 26, 18, '他说：“你们到城里去见某人，对他说，老师说：‘我的时候快到了；我要到你那里和我的门徒守逾越节。’”'),
('CNV', '马太福音', 40, 26, 19, '门徒照耶稣的指示去作，预备好了逾越节的晚餐。'),
('CNV', '马太福音', 40, 26, 20, '到了晚上，耶稣和十二门徒一同吃晚餐。'),
('CNV', '马太福音', 40, 26, 21, '他们吃的时候，耶稣说：“我实在告诉你们，你们中间有一个人要出卖我。”'),
('CNV', '马太福音', 40, 26, 22, '他们就很忧愁，一个一个地问他：“主啊，是我吗？”'),
('CNV', '马太福音', 40, 26, 23, '他回答：“那和我一同把手蘸在盘子里的人，他要出卖我。'),
('CNV', '马太福音', 40, 26, 24, '正如经上指着人子所说的，他固然要离世，但出卖人子的那人有祸了！他没有生下来倒好。”'),
('CNV', '马太福音', 40, 26, 25, '那出卖耶稣的犹大说：“拉比，是我吗？”他说：“这是你说的。”'),
('CNV', '马太福音', 40, 26, 26, '他们吃的时候，耶稣拿起饼来，祝谢了就擘开，递给门徒，说：“你们拿去吃吧，这是我的身体。”'),
('CNV', '马太福音', 40, 26, 27, '耶稣又拿起杯来，祝谢了就递给他们，说：“你们都喝吧，'),
('CNV', '马太福音', 40, 26, 28, '这是我的血，是为立约的，为许多人流出来，使罪得赦。'),
('CNV', '马太福音', 40, 26, 29, '我告诉你们，从今以后我必不再喝这葡萄酒，直到我和你们在我父的国里喝新酒的那一天。”'),
('CNV', '马太福音', 40, 26, 30, '他们唱完了诗，就出来往橄榄山去。'),
('CNV', '马太福音', 40, 26, 31, '那时，耶稣对他们说：“今天晚上，你们因我的缘故都要后退，因为经上记着：‘我要击打牧人，羊群就分散了。’'),
('CNV', '马太福音', 40, 26, 32, '我复活以后，要比你们先到加利利去。”'),
('CNV', '马太福音', 40, 26, 33, '彼得对他说：“就算所有的人都因你的缘故后退，我却永不后退。”'),
('CNV', '马太福音', 40, 26, 34, '耶稣对他说：“我实在告诉你，今天晚上鸡叫以前，你会三次不认我。”'),
('CNV', '马太福音', 40, 26, 35, '彼得对他说：“就算必须与你一同死，我也决不会不认你。”门徒也都这样说。'),
('CNV', '马太福音', 40, 26, 36, '耶稣和门徒来到一个地方，名叫客西马尼，就对门徒说：“你们坐在这里，我要到那边去祷告。”'),
('CNV', '马太福音', 40, 26, 37, '他带了彼得和西庇太的两个儿子一起去，心里忧愁难过，'),
('CNV', '马太福音', 40, 26, 38, '对他们说：“我的心灵痛苦得快要死了；你们留在这里，与我一同警醒吧。”'),
('CNV', '马太福音', 40, 26, 39, '他稍往前走，把脸俯伏在地上，祷告说：“我的父啊！可能的话，求你使这杯离开我；但不要照我的意思，只要照你的旨意。”'),
('CNV', '马太福音', 40, 26, 40, '耶稣回到门徒那里，看见他们都睡着了，就对彼得说：“你们连一个小时也不能同我警醒吗？'),
('CNV', '马太福音', 40, 26, 41, '应当警醒、祷告，免得陷入试探；你们心灵虽然愿意，肉体却是软弱的。”'),
('CNV', '马太福音', 40, 26, 42, '他又再次走开，祷告说：“我的父啊！如果这杯不能离开我，一定要我喝，就愿你的旨意成全。”'),
('CNV', '马太福音', 40, 26, 43, '他再回来的时候，看见门徒睡着了，因为他们十分疲倦。'),
('CNV', '马太福音', 40, 26, 44, '他又离开他们，第三次去祷告，说的也是同样的话。'),
('CNV', '马太福音', 40, 26, 45, '然后，他回到门徒那里，对他们说：“你们还在睡觉休息吗？看哪，时候到了，人子要被交在罪人的手里了。'),
('CNV', '马太福音', 40, 26, 46, '起来，我们走吧！出卖我的人来了。”'),
('CNV', '马太福音', 40, 26, 47, '耶稣还在说话的时候，十二门徒中的犹大，带着一大群拿着刀棒的人来到，他们是祭司长和民间的长老派来的。'),
('CNV', '马太福音', 40, 26, 48, '出卖耶稣的人给他们一个暗号，说：“我跟谁亲吻，谁就是他；你们可以抓住他。”'),
('CNV', '马太福音', 40, 26, 49, '他立刻前来对耶稣说：“拉比，你好。”跟着就与他亲吻。'),
('CNV', '马太福音', 40, 26, 50, '耶稣对他说：“朋友，你来要作的事，快作吧！”于是那些人上前来，动手拿住耶稣，逮捕了他。'),
('CNV', '马太福音', 40, 26, 51, '有一个与耶稣在一起的人，伸手拔出刀来，砍了大祭司的仆人一刀，削掉他的一只耳朵。'),
('CNV', '马太福音', 40, 26, 52, '耶稣对他说：“把你的刀收回原处！凡动刀的必死在刀下。'),
('CNV', '马太福音', 40, 26, 53, '你以为我不能求我的父，他就马上给我派十二营以上的天使下来吗？'),
('CNV', '马太福音', 40, 26, 54, '如果这样，经上预言这事必须发生，怎能应验呢？”'),
('CNV', '马太福音', 40, 26, 55, '那时，耶稣对众人说：“你们带着刀棒出来，把我当作强盗捉拿吗？我天天坐在殿里教导人，你们却没有逮捕我。'),
('CNV', '马太福音', 40, 26, 56, '但这整件事的发生，是要应验先知书上的话。”那时，门徒都离开他逃跑了。'),
('CNV', '马太福音', 40, 26, 57, '那些逮捕了耶稣的人，把他押去见大祭司该亚法。那时经学家和长老已经聚集在那里了。'),
('CNV', '马太福音', 40, 26, 58, '彼得远远地跟着耶稣，直到大祭司的官邸。他进到里面，和差役坐在一起，要看事情怎样了结。'),
('CNV', '马太福音', 40, 26, 59, '祭司长和公议会全体都想找假证供来控告耶稣，好把他处死；'),
('CNV', '马太福音', 40, 26, 60, '虽然有许多人前来作假证供，却找不着证据。最后有两个人前来说：'),
('CNV', '马太福音', 40, 26, 61, '“这人说过：‘我可以拆毁神的圣所，三日之内又把它建造起来。’”'),
('CNV', '马太福音', 40, 26, 62, '大祭司就站起来，对耶稣说：“你为什么不回答？这些人作证，控告你的是什么呢？”'),
('CNV', '马太福音', 40, 26, 63, '耶稣却不作声。大祭司又对他说：“我指着永生的神要你起誓，告诉我们你是不是基督、神的儿子。”'),
('CNV', '马太福音', 40, 26, 64, '耶稣回答：“你已经说了﹙“你已经说了”或译：“这是你说的。”﹚；但我告诉你们：从今以后，你们要看见人子，坐在权能者的右边，驾着天上的云降临。”'),
('CNV', '马太福音', 40, 26, 65, '大祭司就撕开衣服，说：“他说了亵渎的话，我们还要什么证人呢？你们现在听见了这亵渎的话，'),
('CNV', '马太福音', 40, 26, 66, '认为怎样呢？”他们回答：“他是该死的。”'),
('CNV', '马太福音', 40, 26, 67, '于是他们吐唾沫在他的脸上，用拳头打他，也有人用掌掴他，说：'),
('CNV', '马太福音', 40, 26, 68, '“基督啊，向我们说预言吧！是谁打你呢？”'),
('CNV', '马太福音', 40, 26, 69, '彼得坐在外面的院子里，有一个婢女走过来对他说：“你也是和加利利人耶稣一伙的。”'),
('CNV', '马太福音', 40, 26, 70, '彼得却当众否认，说：“我不知道你说什么。”'),
('CNV', '马太福音', 40, 26, 71, '他出到门口，又有一个婢女看见他，就对那里的人说：“这人是和拿撒勒人耶稣一伙的。”'),
('CNV', '马太福音', 40, 26, 72, '彼得再次否认，并且发誓说：“我不认识那个人。”'),
('CNV', '马太福音', 40, 26, 73, '过了一会，站在那里的人前来对他说：“你的确是他们中间的一个，因为一听你的口音就认出来了。”'),
('CNV', '马太福音', 40, 26, 74, '彼得就发咒起誓说：“我不认识那一个人。”立刻鸡就叫了。'),
('CNV', '马太福音', 40, 26, 75, '彼得想起耶稣所说的话：“鸡叫以前，你会三次不认我”，他就出去痛哭。'),
('CNV', '马太福音', 40, 27, 1, '到了早上，所有的祭司长和民间的长老商议怎样对付耶稣，好杀掉他。'),
('CNV', '马太福音', 40, 27, 2, '他们把他绑起来，押去交给总督彼拉多。'),
('CNV', '马太福音', 40, 27, 3, '那时，出卖耶稣的犹大见耶稣定了罪，就后悔了。他把那三十块银子还给祭司长和长老，说：'),
('CNV', '马太福音', 40, 27, 4, '“我有罪了！我出卖了无辜的人﹙“人”原文作“血”。﹚！”他们说：“这是你的事，跟我们有什么关系？”'),
('CNV', '马太福音', 40, 27, 5, '犹大把银子丢进圣所，然后离开，出去吊死了。'),
('CNV', '马太福音', 40, 27, 6, '祭司长把银子拾起来，说：“这是血钱，不可放在殿库里。”'),
('CNV', '马太福音', 40, 27, 7, '他们商议之后，就用那些钱买了“陶匠的田”，用来作外国人的坟地。'),
('CNV', '马太福音', 40, 27, 8, '所以那田称为“血田”，直到今日。'),
('CNV', '马太福音', 40, 27, 9, '这应验了耶利米先知所说的：“他们拿了三十块银子，就是以色列人给他估定的价钱，'),
('CNV', '马太福音', 40, 27, 10, '用它买了‘陶匠的田’，正如主所指示我的。”'),
('CNV', '马太福音', 40, 27, 11, '耶稣站在总督面前，总督问他：“你是犹太人的王吗？”耶稣回答：“这是你说的。”'),
('CNV', '马太福音', 40, 27, 12, '祭司长和长老控告他的时候，他却不回答。'),
('CNV', '马太福音', 40, 27, 13, '彼拉多又问他：“他们作证指控你这么多的事，你没有听见吗？”'),
('CNV', '马太福音', 40, 27, 14, '耶稣一句话也不回答他，令总督非常惊奇。'),
('CNV', '马太福音', 40, 27, 15, '每逢这节期，总督有一个惯例，就是给群众释放一个他们要求释放的囚犯。'),
('CNV', '马太福音', 40, 27, 16, '那时，有个声名狼藉的囚犯，名叫耶数．巴拉巴。'),
('CNV', '马太福音', 40, 27, 17, '群众聚集的时候，彼拉多问他们：“你们要我给你们释放谁？耶数．巴拉巴或是称为基督的耶稣呢？”'),
('CNV', '马太福音', 40, 27, 18, '他知道他们是因为嫉妒才把耶稣交了来。'),
('CNV', '马太福音', 40, 27, 19, '彼拉多坐在审判台上的时候，他的夫人派人来说：“你不要干涉这个义人的事，因为昨夜我在梦中因他受了很多的苦。”'),
('CNV', '马太福音', 40, 27, 20, '祭司长和长老怂恿群众，叫他们去要求释放巴拉巴，除掉耶稣。'),
('CNV', '马太福音', 40, 27, 21, '总督问他们：“这两个人，你们要我给你们释放哪一个？”他们说：“巴拉巴！”'),
('CNV', '马太福音', 40, 27, 22, '彼拉多对他们说：“那么，我怎样处置那称为基督的耶稣呢？”他们齐声说：“把他钉十字架！”'),
('CNV', '马太福音', 40, 27, 23, '彼拉多说：“为什么呢？他作了什么恶事呢？”众人更加大声喊叫：“把他钉十字架！”'),
('CNV', '马太福音', 40, 27, 24, '彼拉多见无济于事，反会引起骚动，就拿水在群众面前洗手，说：“流这人的血，与我无关，你们自己负责吧。”'),
('CNV', '马太福音', 40, 27, 25, '群众回答：“流他的血的责任，归在我们和我们子孙的身上吧。”'),
('CNV', '马太福音', 40, 27, 26, '于是彼拉多给他们释放了巴拉巴；他把耶稣鞭打了，就交给他们钉十字架。'),
('CNV', '马太福音', 40, 27, 27, '总督的士兵把耶稣带到总督府，召集全队士兵到他面前。'),
('CNV', '马太福音', 40, 27, 28, '他们脱去他的衣服，给他披上朱红色的外袍，'),
('CNV', '马太福音', 40, 27, 29, '又用荆棘编成冠冕，戴在他的头上，把一根芦苇放在他的右手，跪在他面前讥笑他说：“犹太人的王万岁！”'),
('CNV', '马太福音', 40, 27, 30, '然后向他吐唾沫，又拿起芦苇打他的头。'),
('CNV', '马太福音', 40, 27, 31, '戏弄完了，就脱下他的外袍，给他穿回自己的衣服，带去钉十字架。'),
('CNV', '马太福音', 40, 27, 32, '他们出来的时候，遇见一个古利奈人，名叫西门，就强迫他背耶稣的十字架。'),
('CNV', '马太福音', 40, 27, 33, '到了一个地方，名叫各各他，就是“髑髅地”的意思，'),
('CNV', '马太福音', 40, 27, 34, '他们把苦胆调和的酒给他喝，他尝了却不肯喝。'),
('CNV', '马太福音', 40, 27, 35, '士兵把他钉了十字架，就抽签分他的衣服，'),
('CNV', '马太福音', 40, 27, 36, '然后坐在那里看守他。'),
('CNV', '马太福音', 40, 27, 37, '他们在耶稣的头以上，钉了一块牌子，写着他的罪状：“这是犹太人的王耶稣”。'),
('CNV', '马太福音', 40, 27, 38, '当时，有两个强盗和他一同钉十字架，一个在右，一个在左。'),
('CNV', '马太福音', 40, 27, 39, '过路的人嘲笑他，摇着头说：'),
('CNV', '马太福音', 40, 27, 40, '“你这个想拆毁圣所，三日之内又把它建造起来的，救救自己吧！如果你是神的儿子，从十字架上下来吧！”'),
('CNV', '马太福音', 40, 27, 41, '祭司长、经学家和长老也同样讥笑他，说：'),
('CNV', '马太福音', 40, 27, 42, '“他救了别人，却不能救自己。如果他是以色列的王，现在可以从十字架上下来，我们就信他。'),
('CNV', '马太福音', 40, 27, 43, '他信靠神；如果神喜悦他，就让神现在救他吧，因为他说自己是神的儿子。”'),
('CNV', '马太福音', 40, 27, 44, '和他一同钉十字架的强盗也都这样侮辱他。'),
('CNV', '马太福音', 40, 27, 45, '从正午到下午三点钟，遍地都黑暗了。'),
('CNV', '马太福音', 40, 27, 46, '大约三点钟，耶稣大声呼叫：“以利，以利，拉马撒巴各大尼？”意思是“我的神，我的神，你为什么离弃我？”'),
('CNV', '马太福音', 40, 27, 47, '有几个站在那里的人，听见了就说：“这个人在呼叫以利亚呢。”'),
('CNV', '马太福音', 40, 27, 48, '有一个人马上跑去拿海绵蘸满了酸酒，用芦苇递给他喝。'),
('CNV', '马太福音', 40, 27, 49, '但其他的人说：“等一等，我们看看以利亚来不来救他。”'),
('CNV', '马太福音', 40, 27, 50, '耶稣再大声呼叫，气就断了。'),
('CNV', '马太福音', 40, 27, 51, '忽然，圣所里的幔子从上到下裂成两半；地面震动，石头崩裂；'),
('CNV', '马太福音', 40, 27, 52, '而且坟墓开了，许多睡了的圣徒的身体也复活了，'),
('CNV', '马太福音', 40, 27, 53, '从坟墓里出来；到了耶稣复活之后，他们进到圣城向许多人显现。'),
('CNV', '马太福音', 40, 27, 54, '百夫长和跟他一起看守耶稣的士兵，看见了地震和所发生的事情，就十分惧怕，说：“这个人真是神的儿子。”'),
('CNV', '马太福音', 40, 27, 55, '有许多妇女在那里远远地观看；她们是从加利利开始跟随耶稣服事他的。'),
('CNV', '马太福音', 40, 27, 56, '她们中间有抹大拉的马利亚、雅各和约西的母亲马利亚，以及西庇太的儿子的母亲。'),
('CNV', '马太福音', 40, 27, 57, '到了晚上，有一个亚利马太的富翁来到，他名叫约瑟，是耶稣的门徒。'),
('CNV', '马太福音', 40, 27, 58, '这个人去见彼拉多，请求领取耶稣的身体，彼拉多就吩咐给他。'),
('CNV', '马太福音', 40, 27, 59, '约瑟领了耶稣的身体，用干净的细麻布裹好，'),
('CNV', '马太福音', 40, 27, 60, '放在自己的新坟墓里，就是在磐石里凿出来的。他辊了一块大石头来挡住墓门，然后才离开。'),
('CNV', '马太福音', 40, 27, 61, '抹大拉的马利亚和另一个马利亚都在那里，对着坟墓坐着。'),
('CNV', '马太福音', 40, 27, 62, '第二天，就是过了“预备日”的那一天，祭司长和法利赛人去见彼拉多，说：'),
('CNV', '马太福音', 40, 27, 63, '“大人，我们想起那个骗子，生前说过：‘三天之后，我要复活。’'),
('CNV', '马太福音', 40, 27, 64, '所以请你下令把坟墓严密看守，直到第三天，免得他的门徒来把他偷去，然后对民众说：‘他从死人中复活了。’这样，日后的骗局比起初的就更大了。”'),
('CNV', '马太福音', 40, 27, 65, '彼拉多对他们说：“你们带着卫兵，尽你们所能的去严密看守吧。”'),
('CNV', '马太福音', 40, 27, 66, '他们就去把墓前的石封好，又派卫兵把守，严密地守住坟墓。'),
('CNV', '马太福音', 40, 28, 1, '过了安息日，在礼拜日天亮的时候，抹大拉的马利亚和另一个马利亚来看坟墓。'),
('CNV', '马太福音', 40, 28, 2, '忽然，地震得很厉害；主的使者从天上下来，把石头辊开，坐在上面。'),
('CNV', '马太福音', 40, 28, 3, '他的样子好像闪电，衣服洁白如雪。'),
('CNV', '马太福音', 40, 28, 4, '看守的人因为害怕他，就浑身战抖，好像死了一样。'),
('CNV', '马太福音', 40, 28, 5, '那使者对妇女们说：“你们不要怕，我知道你们在找被钉十字架的耶稣。'),
('CNV', '马太福音', 40, 28, 6, '他不在这里，已经照他所说的复活了。你们来看安放他的地方吧。'),
('CNV', '马太福音', 40, 28, 7, '快去告诉他的门徒：‘他已经从死人中复活了。他会比你们先到加利利去，你们在那里必看见他。’现在我已经告诉你们了。”'),
('CNV', '马太福音', 40, 28, 8, '她们立刻离开坟墓，又害怕，又十分欢喜，跑去告诉耶稣的门徒。'),
('CNV', '马太福音', 40, 28, 9, '忽然，耶稣向她们迎面而来，说：“你们好。”她们就上前，抱住他的脚拜他。'),
('CNV', '马太福音', 40, 28, 10, '耶稣对她们说：“不要怕，去告诉我的弟兄，叫他们到加利利去，他们在那里必看见我。”'),
('CNV', '马太福音', 40, 28, 11, '她们去的时候，有些卫兵进了城，把一切所发生的事向祭司长报告。'),
('CNV', '马太福音', 40, 28, 12, '祭司长就和长老聚集在一起商量，然后拿许多钱给士兵，'),
('CNV', '马太福音', 40, 28, 13, '说：“你们要这样说：‘他的门徒晚上来了，趁我们睡着的时候，把他偷走了。’'),
('CNV', '马太福音', 40, 28, 14, '如果总督知道了这件事，我们会说服他，不会牵连你们。”'),
('CNV', '马太福音', 40, 28, 15, '士兵收了钱，就照着祭司长和长老的指使去作。这种说法直到今日还流传在犹太人当中。'),
('CNV', '马太福音', 40, 28, 16, '十一个门徒往加利利去，到了耶稣指定的山上。'),
('CNV', '马太福音', 40, 28, 17, '他们看见耶稣就拜他，但仍然有些人怀疑。'),
('CNV', '马太福音', 40, 28, 18, '耶稣上前来，对他们说：“天上地上一切权柄都赐给我了。'),
('CNV', '马太福音', 40, 28, 19, '所以，你们要去使万民作我的门徒，奉父子圣灵的名，给他们施洗﹙“奉父子圣灵的名，给他们施洗”或译：“给他们施洗，归入父子圣灵的名”。﹚，'),
('CNV', '马太福音', 40, 28, 20, '我吩咐你们的一切，都要教导他们遵守。这样，我就常常与你们同在，直到这世代的终结。”'),
('CNV', '马可福音', 41, 1, 1, '神的儿子（有些抄本无“神的儿子”一句）耶稣基督福音的开始。'),
('CNV', '马可福音', 41, 1, 2, '正如以赛亚先知的书上写着：“看哪，我差遣我的使者在你面前，预备你的道路；'),
('CNV', '马可福音', 41, 1, 3, '在旷野有呼喊者的声音：‘预备主的道，修直他的路！’”'),
('CNV', '马可福音', 41, 1, 4, '照这话，施洗的约翰在旷野出现了，传讲悔改的洗礼，使罪得赦。'),
('CNV', '马可福音', 41, 1, 5, '犹太全地和全耶路撒冷的人，都出来到他那里去，承认自己的罪，在约旦河里受了他的洗。'),
('CNV', '马可福音', 41, 1, 6, '约翰身穿骆驼毛的衣服，腰束皮带，吃的是蝗虫和野蜜。'),
('CNV', '马可福音', 41, 1, 7, '他传讲说：“有一位在我以后来的，能力比我大，我就是弯腰给他解鞋带都没有资格。'),
('CNV', '马可福音', 41, 1, 8, '我用水给你们施洗，他却要用圣灵给你们施洗。”'),
('CNV', '马可福音', 41, 1, 9, '那时候耶稣从加利利的拿撒勒来，在约旦河里受了约翰的洗。'),
('CNV', '马可福音', 41, 1, 10, '他从水里一上来，就看见天裂开了，圣灵仿佛鸽子降在他身上。'),
('CNV', '马可福音', 41, 1, 11, '又有声音从天上来说：“你是我的爱子，我喜悦你。”'),
('CNV', '马可福音', 41, 1, 12, '圣灵随即催促耶稣到旷野去。'),
('CNV', '马可福音', 41, 1, 13, '他在那里四十天，受撒但的试探，和野兽在一起，有天使来服事他。'),
('CNV', '马可福音', 41, 1, 14, '约翰被捕以后，耶稣来到加利利，宣讲神的福音，'),
('CNV', '马可福音', 41, 1, 15, '说：“时候到了，神的国近了，你们应当悔改，相信福音。”'),
('CNV', '马可福音', 41, 1, 16, '耶稣沿着加利利海边行走，看见西门和他弟弟安得烈在海上撒网；他们是渔夫。'),
('CNV', '马可福音', 41, 1, 17, '耶稣就对他们说：“来跟从我，我要使你们成为得人的渔夫。”'),
('CNV', '马可福音', 41, 1, 18, '他们立刻撇下网，跟从了他。'),
('CNV', '马可福音', 41, 1, 19, '耶稣稍往前走，看见西庇太的儿子雅各，和雅各的弟弟约翰，正在船上整理鱼网，'),
('CNV', '马可福音', 41, 1, 20, '他立即呼召他们。他们撇下父亲西庇太和雇工在船上，就跟从他去了。'),
('CNV', '马可福音', 41, 1, 21, '他们到了迦百农，耶稣随即在安息日进入会堂教导人。'),
('CNV', '马可福音', 41, 1, 22, '大家对他的教训都很惊奇，因为他教导他们，像一个有权柄的人，不像经学家。'),
('CNV', '马可福音', 41, 1, 23, '就在那时，会堂里有一个被污灵附着的人，喊叫起来，'),
('CNV', '马可福音', 41, 1, 24, '说：“拿撒勒人耶稣，我们跟你有什么关系呢？你来毁灭我们吗？我知道你是谁，你是神的圣者。”'),
('CNV', '马可福音', 41, 1, 25, '耶稣斥责他说：“住口！从他身上出来！”'),
('CNV', '马可福音', 41, 1, 26, '污灵使那人抽疯，大声喊叫，就从他身上出来了。'),
('CNV', '马可福音', 41, 1, 27, '众人都很惊讶，于是彼此对问说：“这是怎么一回事？是个有权能的新道理啊！他吩咐污灵，污灵竟服从了他！”'),
('CNV', '马可福音', 41, 1, 28, '耶稣的名声立刻传遍了加利利一带。'),
('CNV', '马可福音', 41, 1, 29, '他们一出会堂，就和雅各、约翰到西门和安得烈的家里去。'),
('CNV', '马可福音', 41, 1, 30, '西门的岳母正在发烧躺着，他们立刻告诉耶稣。'),
('CNV', '马可福音', 41, 1, 31, '耶稣走到她面前，拉着她的手，扶她起来，热就退了，她就服事他们。'),
('CNV', '马可福音', 41, 1, 32, '到了黄昏，有人不断把生病的和被鬼附的，都带到耶稣面前。'),
('CNV', '马可福音', 41, 1, 33, '全城的人都聚集在门口。'),
('CNV', '马可福音', 41, 1, 34, '耶稣医好了各样的病，也赶出许多的鬼，并且不许鬼说话，因为鬼认识他。'),
('CNV', '马可福音', 41, 1, 35, '次日凌晨，天还没有亮，耶稣起身出去，来到荒野的地方，在那里祷告。'),
('CNV', '马可福音', 41, 1, 36, '西门和那些跟他在一起的人就去寻找耶稣。'),
('CNV', '马可福音', 41, 1, 37, '他们找到了，就对他说：“大家都在找你呢！”'),
('CNV', '马可福音', 41, 1, 38, '耶稣对他们说：“我们到邻近的乡镇去吧，我也好在那里传道，因为我就是为这事而来的。”'),
('CNV', '马可福音', 41, 1, 39, '于是他走遍加利利全地，在他们的会堂里传道，并且赶鬼。'),
('CNV', '马可福音', 41, 1, 40, '有一个患痲风的人，来到耶稣跟前，跪下求他说：“如果你肯，必能使我洁净。”'),
('CNV', '马可福音', 41, 1, 41, '耶稣动了怜悯的心，就伸手摸他，说：“我肯，你洁净了吧！”'),
('CNV', '马可福音', 41, 1, 42, '痲风立刻离开了他，他就洁净了。'),
('CNV', '马可福音', 41, 1, 43, '耶稣打发那人离开以前，严厉地吩咐他，'),
('CNV', '马可福音', 41, 1, 44, '说：“你千万不可把这事告诉任何人，你只要去给祭司检查，并且照着摩西所规定的，为你得洁净献祭，好向大家作证。”'),
('CNV', '马可福音', 41, 1, 45, '但那人出来，竟任意传讲，就把这事传开了，以致耶稣不能再公开进城，只好留在外边荒野的地方；然而还是有人从各处到他那里去。'),
('CNV', '马可福音', 41, 2, 1, '过了些日子，耶稣再回到迦百农。一听说他在屋子里，'),
('CNV', '马可福音', 41, 2, 2, '许多人就都来聚集，甚至连门前都没有地方了，耶稣就对他们讲道。'),
('CNV', '马可福音', 41, 2, 3, '那时有人把一个瘫子带到耶稣那里，是由四个人抬来的。'),
('CNV', '马可福音', 41, 2, 4, '因为人挤，不能带到他面前，就对着耶稣所在的地方，拆去房顶；拆通了，就把瘫子连人带褥子缒了下去。'),
('CNV', '马可福音', 41, 2, 5, '耶稣看见他们的信心，就对瘫子说：“孩子，你的罪赦了。”'),
('CNV', '马可福音', 41, 2, 6, '当时有几个经学家也坐在那里，心里议论说：'),
('CNV', '马可福音', 41, 2, 7, '“这个人为什么这样说话？他说僭妄的话了。除了神一位以外，谁能赦罪呢？”'),
('CNV', '马可福音', 41, 2, 8, '耶稣心里立刻知道他们这样议论，就对他们说：“你们心里为什么议论这事？'),
('CNV', '马可福音', 41, 2, 9, '对瘫子说‘你的罪赦了’，或说‘起来，拿着你的褥子走’，哪一样容易呢？'),
('CNV', '马可福音', 41, 2, 10, '然而为了要你们知道人子在地上有赦罪的权柄，（他就对瘫子说：）'),
('CNV', '马可福音', 41, 2, 11, '我吩咐你，起来，拿起你的褥子，回家去吧。”'),
('CNV', '马可福音', 41, 2, 12, '那人就起来，立刻拿着褥子，当众出去了。众人都非常惊奇，颂赞神，说：“我们从来没有见过这样的事。”'),
('CNV', '马可福音', 41, 2, 13, '耶稣又出去，到了加利利海边；众人都到他面前来，他就教导他们。'),
('CNV', '马可福音', 41, 2, 14, '他往前走的时候，看见亚勒腓的儿子利未坐在税关那里，就对他说：“来跟从我！”他就起来跟从了耶稣。'),
('CNV', '马可福音', 41, 2, 15, '后来耶稣在利未家里吃饭，有很多税吏和罪人也来与他和门徒一起吃饭；因为这样的人很多，并且他们已经跟随了耶稣。'),
('CNV', '马可福音', 41, 2, 16, '法利赛派的经学家，看见耶稣与罪人和税吏一起吃饭，就对耶稣的门徒说：“他跟税吏和罪人一起吃饭吗？”'),
('CNV', '马可福音', 41, 2, 17, '耶稣听见了，就对他们说：“健康的人不需要医生，有病的人才需要；我来不是要召义人，而是要召罪人。”'),
('CNV', '马可福音', 41, 2, 18, '约翰的门徒和法利赛人正在禁食，有人来问耶稣说：“为什么约翰的门徒和法利赛人的门徒常常禁食，你的门徒却不禁食呢？”'),
('CNV', '马可福音', 41, 2, 19, '耶稣回答：“新郎跟宾客在一起的时候，宾客怎能禁食呢？只要新郎还在，就不能禁食。'),
('CNV', '马可福音', 41, 2, 20, '但日子到了，新郎要被取去，离开他们，那一天他们就要禁食了。'),
('CNV', '马可福音', 41, 2, 21, '没有人会把一块新布缝在旧衣服上，如果这样，新的布就会把旧衣服扯破，裂开的地方就更大了。'),
('CNV', '马可福音', 41, 2, 22, '也没有人会把新酒装在旧皮袋里，如果这样，酒就会把皮袋胀破，酒和皮袋都损坏了；新酒总该装在新皮袋里。”'),
('CNV', '马可福音', 41, 2, 23, '有一次，在安息日，耶稣从麦田经过，他的门徒一面走路，一面摘麦穗。'),
('CNV', '马可福音', 41, 2, 24, '法利赛人对耶稣说：“你看，他们为什么作安息日不可作的事？”'),
('CNV', '马可福音', 41, 2, 25, '耶稣对他们说：“大卫和跟他一起的人在饥饿缺食的时候所作的，你们没有念过吗？'),
('CNV', '马可福音', 41, 2, 26, '他不是在亚比亚他作大祭司的时候，进了神的殿，吃了除祭司以外谁都不可以吃的陈设饼，而且还给跟他在一起的人吃吗？”'),
('CNV', '马可福音', 41, 2, 27, '耶稣又告诉他们：“安息日是为人设立的，人并不是为安息日设立的。'),
('CNV', '马可福音', 41, 2, 28, '这样，人子也是安息日的主。”'),
('CNV', '马可福音', 41, 3, 1, '耶稣又进了会堂，在那里有一个人，他的一只手枯干了。'),
('CNV', '马可福音', 41, 3, 2, '众人窥探他会不会在安息日医治那个人，好去控告他。'),
('CNV', '马可福音', 41, 3, 3, '耶稣对那一只手枯干了的人说：“起来，站在当中！”'),
('CNV', '马可福音', 41, 3, 4, '又对他们说：“在安息日哪一样是可以作的呢：作好事还是坏事？救命还是害命？”他们一声不响。'),
('CNV', '马可福音', 41, 3, 5, '耶稣怒目环视他们，因他们的心刚硬而难过，就对那人说：“伸出手来！”他把手一伸，手就复原了。'),
('CNV', '马可福音', 41, 3, 6, '法利赛人出来，立刻和希律党人商量怎样对付耶稣，好除掉他。'),
('CNV', '马可福音', 41, 3, 7, '耶稣和门徒退到海边去，一大群从加利利来的人跟着他；'),
('CNV', '马可福音', 41, 3, 8, '还有许多人听见他所作的一切事，就从犹太、耶路撒冷、以土迈、约旦河外和推罗、西顿一带地方来到他跟前。'),
('CNV', '马可福音', 41, 3, 9, '因为人多，耶稣就吩咐门徒为他预备一只小船，免得众人拥挤他。'),
('CNV', '马可福音', 41, 3, 10, '他医好了许多人，所以凡有病的都挤过来要摸他。'),
('CNV', '马可福音', 41, 3, 11, '污灵每次看到他，就仆倒在他面前，大声喊叫说：“你是神的儿子！”'),
('CNV', '马可福音', 41, 3, 12, '耶稣再三严厉地吩咐他们，不要把他的身分张扬出去。'),
('CNV', '马可福音', 41, 3, 13, '耶稣上了山，呼召自己所要的人，他们就来了。'),
('CNV', '马可福音', 41, 3, 14, '他选立了十二个人，称他们为使徒（有些抄本无“称他们为使徒”一句），要他们跟自己常在一起，好差遣他们去传道，'),
('CNV', '马可福音', 41, 3, 15, '又有权柄赶鬼。'),
('CNV', '马可福音', 41, 3, 16, '他选立的十二个人是：西门（耶稣给他起名叫彼得），'),
('CNV', '马可福音', 41, 3, 17, '西庇太的儿子雅各，和雅各的弟弟约翰（耶稣给他们二人起名叫半尼其，就是“雷子”的意思），'),
('CNV', '马可福音', 41, 3, 18, '安得烈、腓力、巴多罗迈、马太、多马、亚勒腓的儿子雅各、达太、激进派的西门，'),
('CNV', '马可福音', 41, 3, 19, '以及加略人犹大，就是出卖耶稣的那个人。'),
('CNV', '马可福音', 41, 3, 20, '耶稣进了屋子，群众又聚了来，以致他们连饭都不能吃，'),
('CNV', '马可福音', 41, 3, 21, '那些和他在一起的人听见了，就出来抓住他，因为他们说他癫狂了。'),
('CNV', '马可福音', 41, 3, 22, '从耶路撒冷下来的经学家说：“他有别西卜附在身上！”又说：“他靠着鬼王赶鬼。”'),
('CNV', '马可福音', 41, 3, 23, '耶稣把他们叫来，用比喻对他们说：“撒但怎能赶逐撒但呢？'),
('CNV', '马可福音', 41, 3, 24, '一国若自相纷争，那国就站立不住；'),
('CNV', '马可福音', 41, 3, 25, '一家若自相纷争，那家就站立不住。'),
('CNV', '马可福音', 41, 3, 26, '如果撒但自相攻打纷争，不但站立不住，而且还要灭亡。'),
('CNV', '马可福音', 41, 3, 27, '谁都不能进入壮汉的家，抢夺他的财物，除非先把壮汉捆绑起来，才可以抢劫他的家。'),
('CNV', '马可福音', 41, 3, 28, '我实在告诉你们，世人的一切罪和一切亵渎的话，都可以得到赦免；'),
('CNV', '马可福音', 41, 3, 29, '但亵渎圣灵的，就永世不得赦免，他还要担当罪恶到永远。”'),
('CNV', '马可福音', 41, 3, 30, '耶稣说这话，是因为他们说他有污灵附在身上。'),
('CNV', '马可福音', 41, 3, 31, '耶稣的母亲和弟弟来了，站在外面，传话给他，叫他出来。'),
('CNV', '马可福音', 41, 3, 32, '有许多人正围坐在耶稣身边，他们告诉他：“你看，你的母亲和弟弟（有些抄本在此有“姊妹”一词）在外面找你。”'),
('CNV', '马可福音', 41, 3, 33, '耶稣回答他们：“谁是我的母亲，我的弟兄呢？”'),
('CNV', '马可福音', 41, 3, 34, '于是四面观看那些围坐的人，说：“你们看，我的母亲！我的弟兄！'),
('CNV', '马可福音', 41, 3, 35, '凡遵行神旨意的，就是我的弟兄姊妹和母亲了。”'),
('CNV', '马可福音', 41, 4, 1, '耶稣又在海边教导人。有一大群人聚集到他那里，因此他上船坐下来。船在海中，群众都朝着海站在岸上。'),
('CNV', '马可福音', 41, 4, 2, '他用比喻教训他们许多事，在教训中他说：'),
('CNV', '马可福音', 41, 4, 3, '“你们听着！有一个撒种的出去撒种，'),
('CNV', '马可福音', 41, 4, 4, '撒的时候，有的落在路旁，小鸟飞来就吃掉了。'),
('CNV', '马可福音', 41, 4, 5, '有的落在泥土不多的石地上，因为泥土不深，很快就长起来。'),
('CNV', '马可福音', 41, 4, 6, '但太阳一出来，就把它晒干，又因为没有根就枯萎了。'),
('CNV', '马可福音', 41, 4, 7, '有的落在荆棘里，荆棘长起来，把它挤住，它就结不出果实来。'),
('CNV', '马可福音', 41, 4, 8, '有的落在好土里，就生长繁茂，结出果实，有三十倍的、有六十倍的、有一百倍的。”'),
('CNV', '马可福音', 41, 4, 9, '耶稣又说：“有耳可听的，就应当听。”'),
('CNV', '马可福音', 41, 4, 10, '耶稣独自一人的时候，那些经常跟着他的人和十二门徒，来问这些比喻的意义。'),
('CNV', '马可福音', 41, 4, 11, '耶稣对他们说：“神的国的奥秘，只给你们知道，但对于外人，一切都用比喻，'),
('CNV', '马可福音', 41, 4, 12, '叫他们‘看是看见了，却不领悟，听是听见了，却不明白，免得他们回转过来，得到赦免。’”'),
('CNV', '马可福音', 41, 4, 13, '耶稣又对他们说：“你们不明白这个比喻，怎能明白一切比喻呢？'),
('CNV', '马可福音', 41, 4, 14, '撒种的人所撒的就是道。'),
('CNV', '马可福音', 41, 4, 15, '那撒在路旁的，就是人听了道，撒但立刻来，把撒在他心里的道夺去。'),
('CNV', '马可福音', 41, 4, 16, '照样，那撒在石地上的，就是人听了道，立刻欢欢喜喜地接受了；'),
('CNV', '马可福音', 41, 4, 17, '可是他们里面没有根，只是暂时的；一旦为道遭遇患难，受到迫害，就立刻跌倒了。'),
('CNV', '马可福音', 41, 4, 18, '那撒在荆棘里的，是指另一些人；他们听了道，'),
('CNV', '马可福音', 41, 4, 19, '然而今世的忧虑、财富的迷惑，以及种种的欲望，接连进来，把道挤住，就结不出果实来。'),
('CNV', '马可福音', 41, 4, 20, '那撒在好土里的，就是人听了道，接受了，并且结出果实，有三十倍的、有六十倍的、有一百倍的。”'),
('CNV', '马可福音', 41, 4, 21, '耶稣又对他们说：“灯难道是拿来放在量器底下或床底下的吗？它不是该放在灯台上吗？'),
('CNV', '马可福音', 41, 4, 22, '因为没有什么隐藏的事不被显明出来，没有什么掩盖的事不被揭露的。'),
('CNV', '马可福音', 41, 4, 23, '有耳可听的，就应当听。”'),
('CNV', '马可福音', 41, 4, 24, '耶稣又对他们说：“要留心你们所听到的，你们用什么尺度量给人，神也要用什么尺度量给你们，并且要超过尺度给你们。'),
('CNV', '马可福音', 41, 4, 25, '因为那有的，还要给他；那没有的，就算他有什么也要拿去。”'),
('CNV', '马可福音', 41, 4, 26, '耶稣说：“神的国好像人在地里撒种，'),
('CNV', '马可福音', 41, 4, 27, '他夜里睡觉，白天起来，种子发芽生长，自己也不知道怎么会这样的。'),
('CNV', '马可福音', 41, 4, 28, '地生五谷是自然的，先长苗，后吐穗，最后穗上结满了子粒。'),
('CNV', '马可福音', 41, 4, 29, '庄稼熟了，就派人用镰刀割下，因为收成的时候到了。”'),
('CNV', '马可福音', 41, 4, 30, '又说：“我们要把神的国比作什么呢？我们可以用什么比喻来形容它呢？'),
('CNV', '马可福音', 41, 4, 31, '它好像一粒芥菜种，刚种下去的时候，比地上的一切种子都小，'),
('CNV', '马可福音', 41, 4, 32, '种下以后，生长起来，却比一切蔬菜都大，长出大枝子，甚至天空的飞鸟都可以在它的荫下搭窝。”'),
('CNV', '马可福音', 41, 4, 33, '耶稣用许多这样的比喻，照着他们所能听懂的，向他们讲道；'),
('CNV', '马可福音', 41, 4, 34, '不用比喻，就不对他们讲。只有单独和自己的门徒在一起的时候，才把一切解释给他们听。'),
('CNV', '马可福音', 41, 4, 35, '当天黄昏，耶稣对门徒说：“我们渡到海那边去吧。”'),
('CNV', '马可福音', 41, 4, 36, '门徒离开群众，耶稣已经在船上，他们就载他过去，也有别的船和他同去。'),
('CNV', '马可福音', 41, 4, 37, '忽然起了狂风，波浪不断地打进船来，舱里积满了水。'),
('CNV', '马可福音', 41, 4, 38, '耶稣却在船尾靠着枕头睡着了。门徒把他叫醒，对他说：“老师，我们要死了，你不管吗？”'),
('CNV', '马可福音', 41, 4, 39, '耶稣起来，斥责了风，又对海说：“不要作声！安静吧！”风就停止，大大地平静了。'),
('CNV', '马可福音', 41, 4, 40, '然后对他们说：“为什么这样胆怯呢？你们怎么没有信心呢？”'),
('CNV', '马可福音', 41, 4, 41, '门徒非常惧怕，彼此说：“这到底是谁，连风和海都听从他？”'),
('CNV', '马可福音', 41, 5, 1, '他们到了海的那边，进入格拉森人的地区。'),
('CNV', '马可福音', 41, 5, 2, '耶稣一下船，就有一个被污灵附着的人，从墓地里迎面而来。'),
('CNV', '马可福音', 41, 5, 3, '那人经常住在坟墓中间，从来没有人能绑住他，甚至用锁链都不能。'),
('CNV', '马可福音', 41, 5, 4, '曾经有很多次，人用脚镣和锁链捆绑他，锁链却被他挣断，脚镣也被他弄碎，始终没有人能制伏他。'),
('CNV', '马可福音', 41, 5, 5, '他昼夜在坟墓里和山野间喊叫，又用石头砍自己。'),
('CNV', '马可福音', 41, 5, 6, '他远远地看见耶稣，就跑过去拜他，'),
('CNV', '马可福音', 41, 5, 7, '大声呼叫，说：“至高神的儿子耶稣，我跟你有什么关系呢？我指着神恳求你，不要叫我受苦。”'),
('CNV', '马可福音', 41, 5, 8, '因为当时耶稣吩咐他：“你这污灵，从这人身上出来！”'),
('CNV', '马可福音', 41, 5, 9, '耶稣问他：“你叫什么名字？”他回答：“我名叫‘群’，因为我们众多。”'),
('CNV', '马可福音', 41, 5, 10, '他再三央求耶稣，不要把他们从那地方赶走。'),
('CNV', '马可福音', 41, 5, 11, '附近的山坡上有一大群猪正在吃东西；'),
('CNV', '马可福音', 41, 5, 12, '污灵求耶稣说：“打发我们到猪群那里附在猪身上吧。”'),
('CNV', '马可福音', 41, 5, 13, '耶稣准了他们。污灵就出来，进到猪群里去，于是那群猪闯下山崖，掉在海里淹死了，猪的数目约有两千。'),
('CNV', '马可福音', 41, 5, 14, '放猪的人都逃跑了，到城里和各乡村去报告，大家就来看发生了什么事。'),
('CNV', '马可福音', 41, 5, 15, '他们来到耶稣跟前，看见那被鬼附过的人，就是曾被名叫‘群’的鬼附过的人，坐在那里，穿上了衣服，神志清醒，他们就害怕。'),
('CNV', '马可福音', 41, 5, 16, '看见的人把被鬼附过的人所遭遇的和那群猪的事，告诉了他们。'),
('CNV', '马可福音', 41, 5, 17, '他们就要求耶稣离开他们的地区。'),
('CNV', '马可福音', 41, 5, 18, '耶稣上船的时候，那被鬼附过的人来求他，要和他在一起。'),
('CNV', '马可福音', 41, 5, 19, '耶稣不许，却对他说：“你回家到你的亲属那里去，把主为你作了多么大的事，并他怎样怜悯你，都告诉他们。”'),
('CNV', '马可福音', 41, 5, 20, '那人就走了，开始在低加波利传讲耶稣为他所作的大事，众人都希奇。'),
('CNV', '马可福音', 41, 5, 21, '耶稣又坐船渡到那边；还在海边的时候，有一大群人向他围拢过来。'),
('CNV', '马可福音', 41, 5, 22, '当时来了一位会堂的主管，名叫叶鲁。他一看见耶稣，就俯伏在他脚前，'),
('CNV', '马可福音', 41, 5, 23, '迫切地求他说：“我的小女儿快要死了，请你来按手在她身上，把她救活。”'),
('CNV', '马可福音', 41, 5, 24, '耶稣就和他一起去了。一大群人跟着他，拥挤着他。'),
('CNV', '马可福音', 41, 5, 25, '有一个女人，患了十二年的血漏病，'),
('CNV', '马可福音', 41, 5, 26, '在好些医生手中受了许多痛苦，又花尽了她一切所有的，不仅毫无起色，反而更加沉重。'),
('CNV', '马可福音', 41, 5, 27, '她听见耶稣的事，就从后面来杂在人群中间，摸耶稣的衣服。'),
('CNV', '马可福音', 41, 5, 28, '因为她说：“只要摸到他的衣服，我就必痊愈。”'),
('CNV', '马可福音', 41, 5, 29, '于是她血漏的源头立刻干了，她在身体上感觉到病已经得了医治。'),
('CNV', '马可福音', 41, 5, 30, '耶稣自己立刻觉得有能力从他里面出去，就转过身来对群众说：“谁摸了我的衣服？”'),
('CNV', '马可福音', 41, 5, 31, '门徒对他说：“你看，这么多人拥挤你，你还问‘谁摸我’吗？”'),
('CNV', '马可福音', 41, 5, 32, '耶稣周围观看，要看作这事的女人。'),
('CNV', '马可福音', 41, 5, 33, '那女人知道在她身上所成就的事，就恐惧战兢地前来向耶稣俯伏，把实情全告诉了他。'),
('CNV', '马可福音', 41, 5, 34, '耶稣对她说：“女儿，你的信使你痊愈了，平安地回去吧，你的病已经好了。”'),
('CNV', '马可福音', 41, 5, 35, '耶稣还在说话的时候，有人从会堂主管的家里来说：“你的女儿已经死了，何必还劳动老师呢？”'),
('CNV', '马可福音', 41, 5, 36, '耶稣听见所说的话，就对会堂主管说：“不要怕！只要信！”'),
('CNV', '马可福音', 41, 5, 37, '于是他不许别人跟他一起去，只带了彼得、雅各和雅各的弟弟约翰。'),
('CNV', '马可福音', 41, 5, 38, '他们来到会堂主管的家，耶稣看见许多人哭泣哀号，一片混乱，'),
('CNV', '马可福音', 41, 5, 39, '就走进去，对众人说：“为什么大哭大嚷呢？孩子不是死了，是睡着了。”'),
('CNV', '马可福音', 41, 5, 40, '众人就嘲笑他。耶稣把众人都赶出去，带着孩子的父母和跟随他的门徒，进入孩子所在的房间。'),
('CNV', '马可福音', 41, 5, 41, '耶稣拉着孩子的手，对她说：“大利大，古米！”翻译出来就是：“小女孩，我吩咐你起来！”'),
('CNV', '马可福音', 41, 5, 42, '那女孩子就立刻起来行走；那时她已经十二岁了。众人就非常惊奇。'),
('CNV', '马可福音', 41, 5, 43, '耶稣再三嘱咐他们，不要让人知道这事，又吩咐给她东西吃。'),
('CNV', '马可福音', 41, 6, 1, '耶稣离开那里，来到自己的家乡，他的门徒跟着他。'),
('CNV', '马可福音', 41, 6, 2, '到了安息日，他开始在会堂里教导人；很多人听见了，都惊奇地说：“这个人从哪里得来这一切呢？所赐给他的是怎么样的智慧，竟然藉着他的手行出这样的神迹？'),
('CNV', '马可福音', 41, 6, 3, '这不是那木匠吗？不是马利亚的儿子，雅各、约西、犹大、西门的哥哥吗？他的妹妹们不也在我们这里吗？”他们就厌弃耶稣。'),
('CNV', '马可福音', 41, 6, 4, '耶稣对他们说：“先知除了在自己的本乡、本族、本家之外，没有不受人尊敬的。”'),
('CNV', '马可福音', 41, 6, 5, '耶稣不能在那里行什么神迹，只给几个病人按手，医好了他们。'),
('CNV', '马可福音', 41, 6, 6, '对于那些人的不信，他感到诧异。耶稣到周围的乡村去继续教导人。'),
('CNV', '马可福音', 41, 6, 7, '他把十二门徒叫来，差遣他们两个两个地出去，赐给他们胜过污灵的权柄；'),
('CNV', '马可福音', 41, 6, 8, '吩咐他们说：“除了手杖以外，路上什么都不要带，不要带干粮，不要带口袋，腰袋里也不要带钱，'),
('CNV', '马可福音', 41, 6, 9, '只穿一双鞋，不要穿两件衣服。”'),
('CNV', '马可福音', 41, 6, 10, '又对他们说：“你们无论到哪里，进了一家就住在那家，直到离开那个地方。'),
('CNV', '马可福音', 41, 6, 11, '什么地方不接待你们，不听你们，你们离开那地方的时候，就要把脚上的灰尘跺下去，作为反对他们的见证。”'),
('CNV', '马可福音', 41, 6, 12, '门徒就出去传道，叫人悔改，'),
('CNV', '马可福音', 41, 6, 13, '赶出许多鬼，用油抹了许多病人，医好他们。'),
('CNV', '马可福音', 41, 6, 14, '当时耶稣的名声传扬出去，希律王也听到了。有人说：“施洗的约翰从死人中复活了，所以他身上有行神迹的能力。”'),
('CNV', '马可福音', 41, 6, 15, '又有人说：“他是以利亚。”还有人说：“他是先知，像古时先知中的一位。”'),
('CNV', '马可福音', 41, 6, 16, '希律听见就说：“是约翰，我砍了他的头，他又活了！”'),
('CNV', '马可福音', 41, 6, 17, '原来希律曾亲自派人去捉拿约翰，把他捆锁在监里。他这样作，是为了他弟弟的妻子希罗底的缘故，因为他娶了希罗底为妻，'),
('CNV', '马可福音', 41, 6, 18, '而约翰曾对希律说：“你占有你兄弟的妻子是不合理的。”'),
('CNV', '马可福音', 41, 6, 19, '于是希罗底怀恨在心，想要杀他，只是不能。'),
('CNV', '马可福音', 41, 6, 20, '因为希律惧怕约翰，知道他是公义圣洁的人，就保护他。希律听了约翰的话，就非常困扰，却仍然喜欢听他。'),
('CNV', '马可福音', 41, 6, 21, '有一天，机会来了。在希律生日的那一天，他为大臣、千夫长和加利利的要人摆设了筵席。'),
('CNV', '马可福音', 41, 6, 22, '希罗底的女儿进来跳舞，使希律和在座的宾客都很开心。王就对女孩子说：“你无论想要什么，只管向我求，我一定给你！”'),
('CNV', '马可福音', 41, 6, 23, '并且对她再三起誓：“你无论向我求什么，就是我国的一半，我也一定给你！”'),
('CNV', '马可福音', 41, 6, 24, '于是她出去问母亲：“我该求什么呢？”希罗底告诉她：“施洗的约翰的头！”'),
('CNV', '马可福音', 41, 6, 25, '她急忙到王面前，向王要求说：“愿王立刻把施洗的约翰的头放在盘子上给我！”'),
('CNV', '马可福音', 41, 6, 26, '希律王非常忧愁，但是因为他的誓言和在座的宾客，就不愿拒绝她。'),
('CNV', '马可福音', 41, 6, 27, '希律王立刻差遣一个侍卫，吩咐把约翰的头拿来。侍卫就去了，在监里斩了约翰的头，'),
('CNV', '马可福音', 41, 6, 28, '把头放在盘子上，拿来交给那女孩子，女孩子又交给她的母亲。'),
('CNV', '马可福音', 41, 6, 29, '约翰的门徒听见了，就来把他的尸体领去，安放在坟墓里。'),
('CNV', '马可福音', 41, 6, 30, '使徒们回来聚集在耶稣跟前，把他们所作和所教导的一切都报告给他听。'),
('CNV', '马可福音', 41, 6, 31, '耶稣对他们说：“来，你们自己到旷野去休息一下。”因为来往的人多，他们甚至没有时间吃饭。'),
('CNV', '马可福音', 41, 6, 32, '他们就悄悄地上了船，到旷野去了。'),
('CNV', '马可福音', 41, 6, 33, '群众看见他们走了，有许多人认出了他们，就从各城出来，跑到那里，比他们先赶到。'),
('CNV', '马可福音', 41, 6, 34, '耶稣一下船，看见一大群人，就怜悯他们，因为他们好像羊没有牧人一样，就开始教导他们许多事。'),
('CNV', '马可福音', 41, 6, 35, '天晚了，门徒前来对他说：“这里是旷野的地方，天已经很晚了，'),
('CNV', '马可福音', 41, 6, 36, '请叫他们散开，好让他们往周围的田舍村庄去，自己买点东西吃。”'),
('CNV', '马可福音', 41, 6, 37, '耶稣回答他们：“你们给他们吃吧！”门徒说：“要我们去买两百银币的饼给他们吃吗？”'),
('CNV', '马可福音', 41, 6, 38, '耶稣说：“去看看你们有多少饼！”他们知道了，就说：“五个饼，还有两条鱼。”'),
('CNV', '马可福音', 41, 6, 39, '耶稣吩咐他们叫大家分组坐在青草地上。'),
('CNV', '马可福音', 41, 6, 40, '他们就一排一排地坐了下来，有一百的，有五十的。'),
('CNV', '马可福音', 41, 6, 41, '耶稣拿起这五个饼、两条鱼，望着天，祝谢了；然后把饼擘开，递给门徒摆在群众面前，又把两条鱼也分给群众。'),
('CNV', '马可福音', 41, 6, 42, '大家都吃了，并且吃饱了。'),
('CNV', '马可福音', 41, 6, 43, '他们把剩下的零碎捡起来，装满了十二个篮子，'),
('CNV', '马可福音', 41, 6, 44, '吃饼的人，男人就有五千。'),
('CNV', '马可福音', 41, 6, 45, '事后耶稣立刻催门徒上船，叫他们先渡到对岸的伯赛大去，等他自己叫众人散开。'),
('CNV', '马可福音', 41, 6, 46, '他离开了他们，就上山去祷告。'),
('CNV', '马可福音', 41, 6, 47, '到了晚上，船在海中，耶稣独自在岸上，'),
('CNV', '马可福音', 41, 6, 48, '看见门徒辛辛苦苦地摇橹，因为风不顺。天快亮的时候（“天快亮的时候”原文作“夜里四更天”），耶稣在海面上向他们走去，想要赶过他们。'),
('CNV', '马可福音', 41, 6, 49, '门徒看见他在海面上走，以为是鬼怪，就喊叫起来；'),
('CNV', '马可福音', 41, 6, 50, '因为他们都看见了他，非常恐惧。耶稣立刻对他们说：“放心吧！是我，不要怕。”'),
('CNV', '马可福音', 41, 6, 51, '于是上了船，和他们在一起，风就平静了。门徒心里十分惊奇，'),
('CNV', '马可福音', 41, 6, 52, '因为他们还不明白分饼这件事的意义，他们的心还是迟钝。'),
('CNV', '马可福音', 41, 6, 53, '他们渡过了海，就在革尼撒勒靠岸，'),
('CNV', '马可福音', 41, 6, 54, '一下船，众人立刻认出耶稣来，'),
('CNV', '马可福音', 41, 6, 55, '就跑遍那一带地方，把有病的人放在褥子上，听见他在哪里，就抬到哪里。'),
('CNV', '马可福音', 41, 6, 56, '耶稣无论到什么地方，或村庄，或城市，或乡野，众人都把病人放在街上，求耶稣准他们摸他衣服的繸子，摸着的人就都好了。'),
('CNV', '马可福音', 41, 7, 1, '有法利赛人和几个经学家从耶路撒冷来，聚集到耶稣那里。'),
('CNV', '马可福音', 41, 7, 2, '他们看见他的门徒有人用不洁的手，就是没有洗过的手吃饭，'),
('CNV', '马可福音', 41, 7, 3, '（原来法利赛人和所有的犹太人都拘守古人的传统，如果不认真洗手，就不吃东西；'),
('CNV', '马可福音', 41, 7, 4, '从街市回来，若不洗手，就不吃东西，还有许多别的传统，他们都沿袭拘守，例如洗杯、洗罐、洗铜器等等。）'),
('CNV', '马可福音', 41, 7, 5, '法利赛人和经学家问耶稣：“你的门徒为什么不遵行古人的传统，用不洁的手吃饭呢？”'),
('CNV', '马可福音', 41, 7, 6, '耶稣对他们说：“以赛亚指着你们这班伪君子所说的预言是对的，经上记着：‘这人民用嘴唇尊敬我，心却远离我；'),
('CNV', '马可福音', 41, 7, 7, '他们把人的规条当作道理去教导人，所以拜我也是徒然。’'),
('CNV', '马可福音', 41, 7, 8, '你们拘守着人的传统，却离弃了神的诫命。”'),
('CNV', '马可福音', 41, 7, 9, '耶稣又对他们说：“你们为了坚守自己的传统，而巧妙地把神的诫命拒绝了。'),
('CNV', '马可福音', 41, 7, 10, '因为摩西说：‘当孝敬父母’，又说：‘咒骂父母的，必被处死。’'),
('CNV', '马可福音', 41, 7, 11, '你们倒说：‘人对父母说，我应该给你的供奉，已经作了各耳板’（各耳板意思是奉给神的供物），'),
('CNV', '马可福音', 41, 7, 12, '你们就不让那人再为父母作什么。'),
('CNV', '马可福音', 41, 7, 13, '这样，你们藉着所领受的传统，把神的话废弃了。你们还作了许多这一类的事。”'),
('CNV', '马可福音', 41, 7, 14, '于是耶稣又把群众叫过来，对他们说：“你们大家都要听我说，也要明白：'),
('CNV', '马可福音', 41, 7, 15, '从外面进去的，不能使人污秽，从里面出来的，才能使人污秽。”（有些抄本有第'),
('CNV', '马可福音', 41, 7, 16, '节：“有耳可听的，就应该听。”）'),
('CNV', '马可福音', 41, 7, 17, '耶稣离开群众，进了屋子，门徒就来问他这比喻的意思。'),
('CNV', '马可福音', 41, 7, 18, '他对他们说：“连你们也是这样不明白吗？难道不知道从外面进去的，不能使人污秽吗？'),
('CNV', '马可福音', 41, 7, 19, '因为不是进到他的心，而是进到他的肚腹，再排泄到外面（“外面”或译：“厕所”）去。”（他这样说是表示各样食物都是洁净的。）'),
('CNV', '马可福音', 41, 7, 20, '接着他又说：“从人里面出来的，才会使人污秽。'),
('CNV', '马可福音', 41, 7, 21, '因为从里面，就是从人的心里，发出恶念、淫乱、偷盗、凶杀、'),
('CNV', '马可福音', 41, 7, 22, '奸淫、贪心、邪恶、诡诈、放荡、嫉妒、毁谤、骄傲、愚妄；'),
('CNV', '马可福音', 41, 7, 23, '这一切恶事，是从人里面出来的，都能使人污秽。”'),
('CNV', '马可福音', 41, 7, 24, '耶稣从那里动身到推罗（有些抄本在此有“和西顿”）境内去。进了一所房子，本来不想让人知道，却隐藏不住。'),
('CNV', '马可福音', 41, 7, 25, '有一个女人，她的小女儿被污灵附着，她听见了耶稣的事，就来俯伏在他脚前。'),
('CNV', '马可福音', 41, 7, 26, '这女人是外族人，属于叙利亚的腓尼基族。她求耶稣把鬼从她女儿身上赶出去。'),
('CNV', '马可福音', 41, 7, 27, '耶稣对她说：“应该先让儿女吃饱。拿儿女的饼去丢给小狗吃是不好的。”'),
('CNV', '马可福音', 41, 7, 28, '那女人回答他：“主啊，是的，不过小狗在桌子底下，也可以吃孩子们掉下来的碎渣。”'),
('CNV', '马可福音', 41, 7, 29, '耶稣对她说：“就凭这句话，你回去吧，鬼已经从你女儿身上出去了。”'),
('CNV', '马可福音', 41, 7, 30, '她回到家里，看见小孩子躺在床上，鬼已经出去了。'),
('CNV', '马可福音', 41, 7, 31, '耶稣从推罗境内出去，经过西顿，回到低加波利地区的加利利海。'),
('CNV', '马可福音', 41, 7, 32, '有人带着一个又聋又哑的人到他那里，求耶稣按手在他身上。'),
('CNV', '马可福音', 41, 7, 33, '耶稣把他从人群中带到一边，用指头探他的耳朵，吐唾沫抹他的舌头，'),
('CNV', '马可福音', 41, 7, 34, '然后望着天，长长地叹了一口气，对他说：“以法大！”意思是“开了吧”。'),
('CNV', '马可福音', 41, 7, 35, '那人的耳朵就开了，舌头也松了，说话也准确了。'),
('CNV', '马可福音', 41, 7, 36, '耶稣嘱咐他们不要告诉人。但他越是嘱咐，他们却越发传扬。'),
('CNV', '马可福音', 41, 7, 37, '众人非常惊讶说：“他所作的一切事都好极了；他竟然使聋子听见，又使哑巴说话。”'),
('CNV', '马可福音', 41, 8, 1, '那些日子，又有一大群人聚集，他们没有什么东西吃。耶稣叫门徒来，对他们说：'),
('CNV', '马可福音', 41, 8, 2, '“我怜悯这一群人，因为他们和我在一起已经有三天，没有什么吃的了。'),
('CNV', '马可福音', 41, 8, 3, '如果我叫他们散开，饿着肚子回家去，他们会在路上晕倒，因为有人是从很远的地方来的。”'),
('CNV', '马可福音', 41, 8, 4, '门徒回答：“在这旷野地方，从哪里能找食物叫这些人吃饱呢？”'),
('CNV', '马可福音', 41, 8, 5, '他问他们：“你们有多少饼？”他们说：“七个。”'),
('CNV', '马可福音', 41, 8, 6, '耶稣吩咐群众坐在地上；拿起那七个饼，祝谢了，擘开递给门徒，叫他们摆开；门徒就摆在众人面前，'),
('CNV', '马可福音', 41, 8, 7, '他们还有几条小鱼，耶稣祝了福，就吩咐把这些也摆开。'),
('CNV', '马可福音', 41, 8, 8, '众人都吃了，并吃饱了。他们把剩下的零碎收拾起来，装满了七个大篮子。'),
('CNV', '马可福音', 41, 8, 9, '当时人数约有四千。耶稣解散了群众，'),
('CNV', '马可福音', 41, 8, 10, '就立刻和门徒上了船，来到大玛努他地区。'),
('CNV', '马可福音', 41, 8, 11, '法利赛人出来，跟耶稣辩论；他们想试探他，求他显个从天上来的神迹。'),
('CNV', '马可福音', 41, 8, 12, '耶稣灵里深深地叹息，说：“这世代为什么总是寻求神迹？我实在告诉你们，决不会有神迹显给这个世代的！”'),
('CNV', '马可福音', 41, 8, 13, '于是他离开他们，又上船往对岸去了。'),
('CNV', '马可福音', 41, 8, 14, '门徒忘了带饼，船上除了一个饼，身边没有别的了。'),
('CNV', '马可福音', 41, 8, 15, '耶稣嘱咐他们说：“你们要小心，提防法利赛人的酵和希律的酵！”'),
('CNV', '马可福音', 41, 8, 16, '门徒彼此议论说：“这是因为我们没有饼吧？”'),
('CNV', '马可福音', 41, 8, 17, '耶稣知道了，就说：“为什么议论没有饼这件事呢？你们还不知道，还不明白吗？你们的心还是这么迟钝吗？'),
('CNV', '马可福音', 41, 8, 18, '你们有眼不能看，有耳不能听吗？你们不记得吗？'),
('CNV', '马可福音', 41, 8, 19, '我擘开那五个饼给五千人吃，你们收拾的零碎装满了几个篮子呢？”他们说：“十二个。”'),
('CNV', '马可福音', 41, 8, 20, '“那七个饼分给四千人吃，你们收拾的零碎装满了几个大篮子呢？”他们说：“七个。”'),
('CNV', '马可福音', 41, 8, 21, '耶稣说：“你们还不明白吗？”'),
('CNV', '马可福音', 41, 8, 22, '后来他们到了伯赛大，有人带了一个瞎眼的人到他跟前，求耶稣摸他。'),
('CNV', '马可福音', 41, 8, 23, '耶稣拉着他的手，领他到村外，吐唾沫在他的眼睛上，又用双手按在他的身上，问他：“你看见什么没有？”'),
('CNV', '马可福音', 41, 8, 24, '他往上一看，说：“我看见人了！看见他们好像树走来走去。”'),
('CNV', '马可福音', 41, 8, 25, '于是耶稣再按手在他的眼睛上，他定睛一看，就复原了，样样都看得清楚了。'),
('CNV', '马可福音', 41, 8, 26, '耶稣叫他回家去，说：“连这村子你也不要进去。”'),
('CNV', '马可福音', 41, 8, 27, '耶稣和门徒出去，要到该撒利亚．腓立比附近的村庄。在路上他问门徒说：“人说我是谁？”'),
('CNV', '马可福音', 41, 8, 28, '他们回答：“有人说是施洗的约翰；有人说是以利亚；还有人说是先知里的一位。”'),
('CNV', '马可福音', 41, 8, 29, '他又问他们说：“那么你们呢？你们说我是谁？”彼得回答：“你就是基督。”'),
('CNV', '马可福音', 41, 8, 30, '耶稣郑重地嘱咐他们，不要把他的事告诉人。'),
('CNV', '马可福音', 41, 8, 31, '于是他教导他们，人子必须受许多苦，被长老、祭司长和经学家弃绝、杀害，三天后复活。'),
('CNV', '马可福音', 41, 8, 32, '耶稣坦白地说了这话，彼得就把他拉到一边，责怪他。'),
('CNV', '马可福音', 41, 8, 33, '耶稣转过身来，望着门徒，斥责彼得说：“撒但，退到我后面去！因为你不思念神的事，只思念人的事。”'),
('CNV', '马可福音', 41, 8, 34, '于是把众人和门徒都叫过来，对他们说：“如果有人愿意跟从我，就应当舍己，背起他的十字架来跟从我。'),
('CNV', '马可福音', 41, 8, 35, '凡是想救自己生命的，必丧掉生命；但为我和福音牺牲生命的，必救了生命。'),
('CNV', '马可福音', 41, 8, 36, '人就是赚得全世界，却赔上自己的生命，有什么好处呢？'),
('CNV', '马可福音', 41, 8, 37, '人还能用什么换回自己的生命呢？'),
('CNV', '马可福音', 41, 8, 38, '在淫乱罪恶的世代，凡把我和我的道当作可耻的，人子在他父的荣耀里，和圣天使一起降临的时候，也必把他当作可耻的。”'),
('CNV', '马可福音', 41, 9, 1, '耶稣又对他们说：“我实在告诉你们，站在这里的，有人在没有尝过死味以前，必定看见神的国带着能力降临。”'),
('CNV', '马可福音', 41, 9, 2, '过了六天，耶稣带着彼得、雅各、约翰，领他们悄悄地上了高山，在他们面前改变了形象。'),
('CNV', '马可福音', 41, 9, 3, '他的衣服闪耀发光，极其洁白，地上漂布的没有能漂得这样白的。'),
('CNV', '马可福音', 41, 9, 4, '又有以利亚和摩西向他们显现，并且跟耶稣谈话。'),
('CNV', '马可福音', 41, 9, 5, '彼得对耶稣说：“拉比，我们在这里真好！我们可以搭三个帐棚，一个为你，一个为摩西，一个为以利亚。”'),
('CNV', '马可福音', 41, 9, 6, '彼得不知道该说什么才好，因为他们都非常害怕。'),
('CNV', '马可福音', 41, 9, 7, '有一片云彩来，笼罩他们，又有声音从云中出来：“这是我的爱子，你们要听他。”'),
('CNV', '马可福音', 41, 9, 8, '门徒立刻周围观看，再也看不见别的人，只见耶稣单独和他们在一起。'),
('CNV', '马可福音', 41, 9, 9, '他们下山的时候，耶稣吩咐他们，人子从死人中复活之前，不要把所看见的告诉人。'),
('CNV', '马可福音', 41, 9, 10, '门徒把这句话记在心里，又彼此讨论从死人中复活是什么意思。'),
('CNV', '马可福音', 41, 9, 11, '他们就问耶稣：“经学家为什么说以利亚必须先来呢？”'),
('CNV', '马可福音', 41, 9, 12, '耶稣说：“以利亚固然要先来复兴一切，但圣经为什么又记载人子要受许多苦，被人藐视呢？'),
('CNV', '马可福音', 41, 9, 13, '其实我告诉你们，以利亚已经来了，他们却任意待他，正如经上指着他所说的。”'),
('CNV', '马可福音', 41, 9, 14, '他们回到门徒那里，看见一大群人围着他们，又有经学家和他们辩论。'),
('CNV', '马可福音', 41, 9, 15, '众人看见了耶稣，都很惊奇，就跑上前去向他问安。'),
('CNV', '马可福音', 41, 9, 16, '他问他们：“你们和他们辩论什么？”'),
('CNV', '马可福音', 41, 9, 17, '群众当中有一个回答他：“老师，我把我的儿子带到你这里来，他被哑巴鬼附着。'),
('CNV', '马可福音', 41, 9, 18, '无论在哪里，鬼抓住他，把他摔倒，他就口吐白沫，咬牙切齿，浑身僵硬。我请你的门徒把鬼赶出去，他们却办不到。”'),
('CNV', '马可福音', 41, 9, 19, '耶稣回答他们：“唉！不信的世代啊！我跟你们在一起到几时呢？我要忍受你们到几时呢？把他带到我这里来吧。”'),
('CNV', '马可福音', 41, 9, 20, '他们就把孩子带到他跟前。那鬼一见耶稣，就立刻使孩子抽了一阵疯，倒在地上，流着唾沫打滚。'),
('CNV', '马可福音', 41, 9, 21, '耶稣问他父亲：“这事临到他有多久了？”他说：“从小就是这样。'),
('CNV', '马可福音', 41, 9, 22, '鬼常常把他扔在火里水中，要毁灭他。如果你能作什么，求你可怜我们，帮助我们。”'),
('CNV', '马可福音', 41, 9, 23, '耶稣对他说：“‘如果你能’（“如果你能”有些抄本作“你若能信”）—对于信的人，什么都能！”'),
('CNV', '马可福音', 41, 9, 24, '孩子的父亲立刻喊着说：“我信！但我的信心不够，求你帮助我。”'),
('CNV', '马可福音', 41, 9, 25, '耶稣看见群众围拢了来，就斥责那污鬼说：“聋哑的鬼，我吩咐你从他身上出来，不要再进去。”'),
('CNV', '马可福音', 41, 9, 26, '那鬼大声喊叫，使孩子重重地抽了一阵疯，就出来了。孩子好像死了一样，所以许多人都说：“他死了！”'),
('CNV', '马可福音', 41, 9, 27, '但耶稣拉着他的手，扶他起来，他就站起来了。'),
('CNV', '马可福音', 41, 9, 28, '耶稣进了屋子，门徒私下问他说：“为什么我们不能把那污鬼赶出去呢？”'),
('CNV', '马可福音', 41, 9, 29, '耶稣对他们说：“这一类的鬼，非用祷告是赶不出去的。”'),
('CNV', '马可福音', 41, 9, 30, '他们从那里出去，经过加利利，耶稣不想让人知道，'),
('CNV', '马可福音', 41, 9, 31, '因为他正在教导门徒。他又对他们说：“人子将要被交在人的手里，他们要杀害他，死后三天他要复活。”'),
('CNV', '马可福音', 41, 9, 32, '门徒不明白这话，又不敢问他。'),
('CNV', '马可福音', 41, 9, 33, '他们来到迦百农。在屋里的时候，耶稣问他们：“你们在路上争论什么？”'),
('CNV', '马可福音', 41, 9, 34, '门徒一声不响，因为他们在路上彼此争论谁为大。'),
('CNV', '马可福音', 41, 9, 35, '耶稣坐下，叫十二门徒来，对他们说：“谁想为首，就该作众人中最末的一个，作众人的仆人。”'),
('CNV', '马可福音', 41, 9, 36, '于是拉过一个小孩子来，叫他站在门徒中间，又把他抱起来，对他们说：'),
('CNV', '马可福音', 41, 9, 37, '“凡因我的名接待一个这样的小孩子的，就是接待我；凡接待我的，不是接待我，而是接待那差我来的。”'),
('CNV', '马可福音', 41, 9, 38, '约翰对耶稣说：“老师，我们看见有一个人奉你的名赶鬼，就禁止他，因为他不跟从我们。”'),
('CNV', '马可福音', 41, 9, 39, '耶稣说：“不要禁止他，因为没有人能奉我的名行了神迹，又立刻毁谤我。'),
('CNV', '马可福音', 41, 9, 40, '不反对我们的，就是赞成我们的。'),
('CNV', '马可福音', 41, 9, 41, '无论谁因你们有属基督的名分，给你们一杯水喝的，我实在告诉你们，他决不会失掉赏赐。'),
('CNV', '马可福音', 41, 9, 42, '“如果有人使一个信我的小弟兄犯罪，倒不如在他的颈项上拴一块大磨石投在海里。'),
('CNV', '马可福音', 41, 9, 43, '如果你的一只手使你犯罪，就把它砍下来。你身体残废进永生，总比有两只手下到地狱，进入那不灭的火里好得多。（有些抄本有第'),
('CNV', '马可福音', 41, 9, 44, '节“在那里虫是不死的，火是不灭的。”）'),
('CNV', '马可福音', 41, 9, 45, '如果你的一只脚使你犯罪，就把它砍下来。你瘸腿进永生，总比你有两只脚而被丢在地狱里好得多。（有些抄本有第'),
('CNV', '马可福音', 41, 9, 46, '节“在那里虫是不死的，火是不灭的。”）'),
('CNV', '马可福音', 41, 9, 47, '如果你的一只眼睛使你犯罪，就把它挖出来。你只有一只眼睛进神的国，总比你有两只眼睛而被丢在地狱里好得多，'),
('CNV', '马可福音', 41, 9, 48, '在那里虫是不死的，火是不灭的。'),
('CNV', '马可福音', 41, 9, 49, '每一个人必被火当盐来腌。（有些抄本在此有“各祭物必用盐来腌”一句；也有些抄本只有附注的一句，而没有正文的一句）'),
('CNV', '马可福音', 41, 9, 50, '盐是好的，但如果失了味，可以用什么使它再咸呢？你们自己里面应当有盐，彼此和睦。”'),
('CNV', '马可福音', 41, 10, 1, '耶稣从那里动身，来到约旦河东的犹太境内。许多人又聚集到他那里，他像平常一样教导他们。'),
('CNV', '马可福音', 41, 10, 2, '有法利赛人前来试探耶稣，问他：“丈夫可以休妻吗？'),
('CNV', '马可福音', 41, 10, 3, '耶稣回答：“摩西吩咐你们的是什么呢？”'),
('CNV', '马可福音', 41, 10, 4, '他们说：“摩西准许‘人写了休书就可以休妻’。”'),
('CNV', '马可福音', 41, 10, 5, '耶稣说：“因为你们的心硬，摩西才写这条例给你们。'),
('CNV', '马可福音', 41, 10, 6, '但从起初创造的时候，神是‘造男造女’。'),
('CNV', '马可福音', 41, 10, 7, '‘因此人要离开父母，与妻子连合，'),
('CNV', '马可福音', 41, 10, 8, '二人成为一体了。’这样，他们不再是两个人，而是一体的了。'),
('CNV', '马可福音', 41, 10, 9, '所以神所配合的，人不可分开。”'),
('CNV', '马可福音', 41, 10, 10, '回到屋子里，门徒再提起这件事来问他。'),
('CNV', '马可福音', 41, 10, 11, '他对他们说：“谁休妻另娶，谁就是犯奸淫，得罪了妻子。'),
('CNV', '马可福音', 41, 10, 12, '如果妻子弃夫另嫁，也是犯了奸淫。”'),
('CNV', '马可福音', 41, 10, 13, '有人带着小孩子到耶稣跟前，要他触摸他们；门徒却责备那些人。'),
('CNV', '马可福音', 41, 10, 14, '耶稣看见了就生气，对门徒说：“让小孩子到我这里来，不要禁止他们，因为神的国是属于这样的人的。'),
('CNV', '马可福音', 41, 10, 15, '我实在告诉你们，凡是不像小孩子一样接受神的国的，绝对不能进去。”'),
('CNV', '马可福音', 41, 10, 16, '于是耶稣把小孩子抱起来，为他们按手祝福。'),
('CNV', '马可福音', 41, 10, 17, '耶稣又开始他的行程。那时，有一个人跑过来，跪在他面前，问他说：“良善的老师，我当作什么，才可以承受永生？”'),
('CNV', '马可福音', 41, 10, 18, '耶稣对他说：“你为什么称我是良善的？除了神一位以外，没有良善的。'),
('CNV', '马可福音', 41, 10, 19, '诫命你是知道的：不可杀人，不可奸淫，不可偷盗，不可作假证供，不可欺诈，当孝敬父母。”'),
('CNV', '马可福音', 41, 10, 20, '他对耶稣说：“老师，这一切我从小都遵守了。”'),
('CNV', '马可福音', 41, 10, 21, '耶稣看着他，就爱他，对他说：“你还缺少一件：去变卖你所有的，分给穷人，就必定有财宝在天上，而且你要来跟从我。”'),
('CNV', '马可福音', 41, 10, 22, '那人听见这话，就变了脸色，忧忧愁愁地走了，因为他的财产很多。'),
('CNV', '马可福音', 41, 10, 23, '耶稣周围观看，对门徒说：“富有的人要进神的国，是多么难哪！”'),
('CNV', '马可福音', 41, 10, 24, '门徒都希奇他的话，耶稣又对他们说：“孩子们哪，（有些抄本在此有“倚靠钱财的人”一句）要进神的国，是多么困难！'),
('CNV', '马可福音', 41, 10, 25, '骆驼穿过针眼，比有钱的人进神的国还容易呢！”'),
('CNV', '马可福音', 41, 10, 26, '门徒就更加惊奇，彼此说：“这样，谁可以得救呢？”'),
('CNV', '马可福音', 41, 10, 27, '耶稣看着他们，说：“在人不能，在神却不然，因为在神凡事都能。”'),
('CNV', '马可福音', 41, 10, 28, '彼得对他说：“你看，我们已经舍弃了一切，而且来跟从你了。”'),
('CNV', '马可福音', 41, 10, 29, '耶稣说：“我实在告诉你们，人为着我和福音舍弃了房屋、弟兄、姊妹、母亲、父亲、儿女、田地，'),
('CNV', '马可福音', 41, 10, 30, '没有不在今生得百倍─就是房屋、弟兄、姊妹、母亲、儿女、田地，同时要受迫害─在来世还要得永生。'),
('CNV', '马可福音', 41, 10, 31, '然而许多在前的将要在后，在后的将要在前。”'),
('CNV', '马可福音', 41, 10, 32, '在上耶路撒冷的路途中，耶稣走在前面，门徒希奇，跟从的人也害怕。耶稣又把十二门徒带到一边，把自己将要遭遇的事告诉他们，'),
('CNV', '马可福音', 41, 10, 33, '说：“我们现在上耶路撒冷去，人子要被交给祭司长和经学家，他们要定他的罪，并且把他交给外族人。'),
('CNV', '马可福音', 41, 10, 34, '他们要凌辱他，向他吐唾沫，鞭打他，杀害他，三天以后，他要复活。”'),
('CNV', '马可福音', 41, 10, 35, '西庇太的儿子雅各、约翰，来到耶稣跟前，对他说：“老师，我们无论向你求什么，愿你为我们作成。”'),
('CNV', '马可福音', 41, 10, 36, '耶稣说：“要我为你们作什么？”'),
('CNV', '马可福音', 41, 10, 37, '他们说：“在你的荣耀里，让我们一个坐在你的右边，一个坐在你的左边。”'),
('CNV', '马可福音', 41, 10, 38, '耶稣说：“你们不知道你们求的是什么。我喝的杯，你们能喝吗？我受的洗，你们能受吗？”'),
('CNV', '马可福音', 41, 10, 39, '他们说：“能。”耶稣说：“我喝的杯，你们固然要喝；我受的洗，你们也要受。'),
('CNV', '马可福音', 41, 10, 40, '只是坐在我的左右，不是我可以赐的，而是神预备赐给谁，就赐给谁。”'),
('CNV', '马可福音', 41, 10, 41, '其他十个门徒听见了，就向雅各、约翰生气。'),
('CNV', '马可福音', 41, 10, 42, '耶稣把他们叫过来，对他们说：“你们知道各国都有被尊为元首的统治他们，也有官长管辖他们。'),
('CNV', '马可福音', 41, 10, 43, '但你们中间却不要这样；谁想在你们中间为大的，就要作你们的仆役，'),
('CNV', '马可福音', 41, 10, 44, '谁想在你们中间为首的，就要作大家的奴仆。'),
('CNV', '马可福音', 41, 10, 45, '因为人子来，不是要受人服事，而是要服事人，并且要舍命，作许多人的赎价。”'),
('CNV', '马可福音', 41, 10, 46, '他们进了耶利哥。耶稣、门徒和一大群人从耶利哥出来的时候，有一个瞎眼的人，是底买的儿子，名叫巴底买，坐在路旁讨饭。'),
('CNV', '马可福音', 41, 10, 47, '他听见是拿撒勒人耶稣，就喊叫，说：“大卫的子孙耶稣啊，可怜我吧！”'),
('CNV', '马可福音', 41, 10, 48, '许多人斥责他，叫他不要出声；他却更加放声喊叫：“大卫的子孙啊，可怜我吧！”'),
('CNV', '马可福音', 41, 10, 49, '耶稣就站住，说：“把他叫过来。”他们就叫那瞎眼的人，对他说：“放心吧，起来，他叫你了。”'),
('CNV', '马可福音', 41, 10, 50, '他就丢下衣服，跳起来，走到耶稣那里。'),
('CNV', '马可福音', 41, 10, 51, '耶稣对他说：“你要我为你作什么呢？”瞎眼的人对他说：“拉波尼，我要能看见。”'),
('CNV', '马可福音', 41, 10, 52, '耶稣说：“去吧，你的信使你痊愈了。”他立刻看见了，就在路上跟随耶稣。'),
('CNV', '马可福音', 41, 11, 1, '他们走近耶路撒冷，到了伯法其和伯大尼，来到橄榄山那里，耶稣派了两个门徒，'),
('CNV', '马可福音', 41, 11, 2, '对他们说：“你们往对面的村子里去，一进去，就会看见一头小驴拴在那里，是没有人骑过的，把它解开牵来。'),
('CNV', '马可福音', 41, 11, 3, '如果有人问你们：‘为什么这样作？’你们就说：‘主需要它，并且很快会送还到这里来。’”'),
('CNV', '马可福音', 41, 11, 4, '门徒去了，就发现一头小驴，拴在门外的街上，就把它解开。'),
('CNV', '马可福音', 41, 11, 5, '站在那里的人有的问他们说：“你们为什么解它？”'),
('CNV', '马可福音', 41, 11, 6, '门徒照着耶稣所说的话回答他们，那些人就让他们牵走了。'),
('CNV', '马可福音', 41, 11, 7, '门徒把小驴牵到耶稣那里，把自己的衣服搭在上面，耶稣就骑了上去。'),
('CNV', '马可福音', 41, 11, 8, '许多人把衣服铺在路上，还有人从田野里砍了些树枝也铺在路上。'),
('CNV', '马可福音', 41, 11, 9, '前行后随的人都喊着说：“‘和散那’，奉主名来的是应当称颂的！'),
('CNV', '马可福音', 41, 11, 10, '那将要来临的，我们祖先大卫的国是应当称颂的！高天之上当唱‘和散那’！”'),
('CNV', '马可福音', 41, 11, 11, '耶稣到了耶路撒冷，进入圣殿，察看了一切，因为时候已经不早，就和十二门徒出城往伯大尼去。'),
('CNV', '马可福音', 41, 11, 12, '第二天他们从伯大尼出来，耶稣饿了。'),
('CNV', '马可福音', 41, 11, 13, '他远远看见一棵长满了叶子的无花果树，就走过去，看看是否可以在树上找到什么。到了树下，除了叶子什么也找不着，因为这不是收无花果的时候。'),
('CNV', '马可福音', 41, 11, 14, '耶稣对树说：“永远再没有人吃你的果子了！”他的门徒也听见了。'),
('CNV', '马可福音', 41, 11, 15, '他们来到耶路撒冷。耶稣进了圣殿，就把殿里作买卖的人赶走，又推倒找换银钱的人的桌子，和卖鸽子的人的凳子；'),
('CNV', '马可福音', 41, 11, 16, '不许人拿着器皿穿过圣殿。'),
('CNV', '马可福音', 41, 11, 17, '他又教训众人说：“经上不是写着‘我的殿要称为万国祷告的殿’吗？你们竟把它弄成贼窝了。”'),
('CNV', '马可福音', 41, 11, 18, '祭司长和经学家听见了，就想办法怎样除掉耶稣，却又怕他，因为群众都希奇他的教训。'),
('CNV', '马可福音', 41, 11, 19, '到了晚上，他们就到城外去。'),
('CNV', '马可福音', 41, 11, 20, '早晨，他们经过的时候，看见那棵无花果树连根都枯萎了。'),
('CNV', '马可福音', 41, 11, 21, '彼得想起来就对耶稣说：“拉比，请看，你所咒诅的无花果树，已经枯萎了。”'),
('CNV', '马可福音', 41, 11, 22, '耶稣回答他们：“你们对神要有信心（“你们对神要有信心”有些抄本作“如果你们对神有信心”）。'),
('CNV', '马可福音', 41, 11, 23, '我实在告诉你们，无论什么人对这座山说‘移开，投到海里’，只要他心里不怀疑，相信他所说的一定能够成就，就必给他成就。'),
('CNV', '马可福音', 41, 11, 24, '所以我告诉你们，凡是你们祷告祈求的，只要相信能够得到，就必得到。'),
('CNV', '马可福音', 41, 11, 25, '你们站着祷告的时候，如果有谁得罪了你们，就该饶恕他，好使你们的天父也饶恕你们的过犯。”（有些抄本有第'),
('CNV', '马可福音', 41, 11, 26, '节：“如果你们不饶恕人，你们的天父也必不饶恕你们的过犯。”）'),
('CNV', '马可福音', 41, 11, 27, '他们又来到耶路撒冷。耶稣在殿里行走的时候，祭司长、经学家和长老来到他跟前，'),
('CNV', '马可福音', 41, 11, 28, '问他：“你凭什么权柄作这些事？谁给你权柄作这些事？”'),
('CNV', '马可福音', 41, 11, 29, '耶稣对他们说：“我要问你们一句话，你们回答了我，我就告诉你们我凭什么权柄作这些事。'),
('CNV', '马可福音', 41, 11, 30, '约翰的洗礼是从天上来的，还是从人来的呢？你们回答我吧。”'),
('CNV', '马可福音', 41, 11, 31, '他们就彼此议论：“如果我们说‘是从天上来的’，他就会说‘那你们为什么不信他呢？’'),
('CNV', '马可福音', 41, 11, 32, '如果我们说‘是从人来的’……”他们害怕群众，因为众人都认为约翰的确是先知。'),
('CNV', '马可福音', 41, 11, 33, '于是他们回答耶稣：“我们不知道。”耶稣对他们说：“我也不告诉你们我凭什么权柄作这些事。”'),
('CNV', '马可福音', 41, 12, 1, '耶稣又用比喻对他们说：“有一个人栽种了一个葡萄园，四面围上篱笆，挖了一个压酒池，盖了一座瞭望台，然后租给佃户，就远行去了。'),
('CNV', '马可福音', 41, 12, 2, '到了时候，园主派了一个仆人到佃户那里，向佃户收取葡萄园一部分的果子。'),
('CNV', '马可福音', 41, 12, 3, '佃户抓住他，打了他，放他空手回去。'),
('CNV', '马可福音', 41, 12, 4, '园主再派另外一个仆人到他们那里，他们打伤了他的头，并且侮辱他。'),
('CNV', '马可福音', 41, 12, 5, '园主又派另一个去，他们就把他杀了。后来又派去许多仆人，有的给他们打了，有的给他们杀了。'),
('CNV', '马可福音', 41, 12, 6, '还有一个，就是园主的爱子，最后园主派他到那里去，说：‘他们必尊敬我的儿子。’'),
('CNV', '马可福音', 41, 12, 7, '那些佃户却彼此说：‘这是继承产业的；来，我们杀了他，产业就是我们的了。’'),
('CNV', '马可福音', 41, 12, 8, '于是抓住他，把他杀了，扔在葡萄园外。'),
('CNV', '马可福音', 41, 12, 9, '这样，葡萄园的主人要怎么办呢？他要来除掉那些佃户，把葡萄园租给别人。'),
('CNV', '马可福音', 41, 12, 10, '你们没有念过这段圣经吗：‘建筑工人所弃的石头，成了房角的主要石头；'),
('CNV', '马可福音', 41, 12, 11, '这是主所作的，在我们眼中看为希奇。’”'),
('CNV', '马可福音', 41, 12, 12, '他们知道他这比喻是针对他们说的，就想要捉拿他，但因为害怕群众，只好离开他走了。'),
('CNV', '马可福音', 41, 12, 13, '后来，他们派了几个法利赛人和希律党的人到耶稣那里去，要找他的把柄来陷害他。'),
('CNV', '马可福音', 41, 12, 14, '他们来到了，就对他说：“老师，我们知道你为人诚实，不顾忌任何人，因为你不徇情面，只照着真理把神的道教导人。请问纳税给凯撒可以不可以？我们该纳不该纳呢？”'),
('CNV', '马可福音', 41, 12, 15, '耶稣看出他们的假意，就对他们说：“你们为什么试探我呢？拿一个银币来给我，让我看看。”'),
('CNV', '马可福音', 41, 12, 16, '他们就拿来了。耶稣问他们：“这是谁的像，谁的名号？”他们回答他：“凯撒的。”'),
('CNV', '马可福音', 41, 12, 17, '耶稣说：“凯撒的应当归给凯撒，神的应当归给神。”他们就对他十分惊奇。'),
('CNV', '马可福音', 41, 12, 18, '撒都该人向来认为没有复活的事，他们来到耶稣那里，问他：'),
('CNV', '马可福音', 41, 12, 19, '“老师，摩西曾写给我们说：‘如果一个人死了，留下妻子，没有儿女，他的弟弟就应当娶他的妻子，为哥哥立后。’'),
('CNV', '马可福音', 41, 12, 20, '从前有兄弟七人，头一个娶了妻子，死了，没有留下孩子；'),
('CNV', '马可福音', 41, 12, 21, '第二个娶了她，也没有留下孩子，就死了；第三个也是这样。'),
('CNV', '马可福音', 41, 12, 22, '那七个人都没有留下孩子，最后那女人也死了。'),
('CNV', '马可福音', 41, 12, 23, '到了复活的时候，他们都要复活，她是哪一个的妻子呢？因为七个人都娶过她。”'),
('CNV', '马可福音', 41, 12, 24, '耶稣对他们说：“你们错了，不正是因为你们不明白圣经，也不晓得神的能力吗？'),
('CNV', '马可福音', 41, 12, 25, '因为人从死里复活以后，也不娶，也不嫁，而是像天上的天使一样。'),
('CNV', '马可福音', 41, 12, 26, '关于死人复活的事，摩西的经卷中荆棘篇上，神怎样对他说：‘我是亚伯拉罕的神，以撒的神，雅各的神’，你们没有念过吗？'),
('CNV', '马可福音', 41, 12, 27, '他不是死人的神，而是活人的神。你们是大错特错了！”'),
('CNV', '马可福音', 41, 12, 28, '有一个经学家，听到他们的辩论，觉得耶稣回答得好，就来问他：“诫命中哪一条是第一重要的呢？”'),
('CNV', '马可福音', 41, 12, 29, '耶稣回答：“第一重要的是：‘以色列啊，你要听！主我们的神是独一的主。'),
('CNV', '马可福音', 41, 12, 30, '你要全心、全性、全意、全力，爱主你的神。’'),
('CNV', '马可福音', 41, 12, 31, '其次是：‘要爱人如己。’再没有别的诫命比这两条更重要的了。”'),
('CNV', '马可福音', 41, 12, 32, '那经学家对耶稣说：“老师，是的，你说的很对，神是独一的，除了他以外再没有别的神。'),
('CNV', '马可福音', 41, 12, 33, '我们要用全心、全意、全力去爱他，并且要爱人如己，这就比一切燔祭和各样祭物好得多了。”'),
('CNV', '马可福音', 41, 12, 34, '耶稣见他回答得有智慧，就对他说：“你距离神的国不远了。”从此再也没有人敢问他了。'),
('CNV', '马可福音', 41, 12, 35, '耶稣在殿里教训人，说：“经学家怎么说基督是大卫的子孙呢？'),
('CNV', '马可福音', 41, 12, 36, '大卫自己被圣灵感动却说：‘主对我的主说：你坐在我的右边，等我把你的仇敌放在你的脚下（有些抄本作“等我使你的仇敌作你的脚凳”）。’'),
('CNV', '马可福音', 41, 12, 37, '大卫自己既然称他为主，他又怎么会是大卫的子孙呢？”群众都喜欢听他。'),
('CNV', '马可福音', 41, 12, 38, '耶稣教导人的时候，说：“你们要提防经学家，他们喜欢穿长袍走来走去，喜欢人在市中心向他们问安，'),
('CNV', '马可福音', 41, 12, 39, '又喜欢会堂里的高位，筵席上的首座。'),
('CNV', '马可福音', 41, 12, 40, '他们吞没了寡妇的房产，又假装作冗长的祷告。这些人必受更重的刑罚。”'),
('CNV', '马可福音', 41, 12, 41, '耶稣面对银库坐着，看着大家怎样把钱投入库中。许多有钱的人投入很多的钱。'),
('CNV', '马可福音', 41, 12, 42, '后来，有一个穷寡妇来投入了两个小钱，就是一个铜钱。'),
('CNV', '马可福音', 41, 12, 43, '耶稣把门徒叫过来，对他们说：“我实在告诉你们，这穷寡妇投入库里的，比众人投的更多。'),
('CNV', '马可福音', 41, 12, 44, '因为他们都是把自己剩余的投入，这寡妇是自己不足，却把她一切所有的，就是全部养生的，都投进去了。”'),
('CNV', '马可福音', 41, 13, 1, '耶稣从殿里出来的时候，有一个门徒对他说：“老师，请看，这是多么美好的石头！多么美好的建筑！”'),
('CNV', '马可福音', 41, 13, 2, '耶稣对他说：“你看见这些伟大的建筑吗？将来必没有一块石头留在另一块石头上面，每一块都要拆下来。”'),
('CNV', '马可福音', 41, 13, 3, '耶稣在橄榄山上，面对圣殿坐着，彼得、雅各、约翰和安得烈私下问他：'),
('CNV', '马可福音', 41, 13, 4, '“请告诉我们，什么时候会有这些事呢？这一切事将要成就的时候有什么预兆呢？”'),
('CNV', '马可福音', 41, 13, 5, '耶稣就告诉他们说：“你们要小心，不要被人迷惑。'),
('CNV', '马可福音', 41, 13, 6, '有许多人要来，假冒我的名说‘我就是基督’，并且要迷惑许多的人。'),
('CNV', '马可福音', 41, 13, 7, '你们听见战争和战争的风声，也不要惊慌，这是免不了的，不过，结局还没有到。'),
('CNV', '马可福音', 41, 13, 8, '一个民族要起来攻打另一个民族，一个国家要起来攻打另一个国家，到处要有地震，有饥荒，这些不过是痛苦的开始。'),
('CNV', '马可福音', 41, 13, 9, '但你们要小心！因为人要把你们交给公议会，你们要在会堂里被鞭打，又要为我的缘故站在总督和君王面前，向他们作见证。'),
('CNV', '马可福音', 41, 13, 10, '然而福音必须先传给万民。'),
('CNV', '马可福音', 41, 13, 11, '人把你们捉去送官的时候，用不着预先思虑要说什么，到那时候赐给你们什么话，你们就说什么，因为说话的不是你们，而是圣灵。'),
('CNV', '马可福音', 41, 13, 12, '弟兄要出卖弟兄，父亲要出卖儿子，甚至把他们置于死地；儿女要悖逆父母，害死他们。'),
('CNV', '马可福音', 41, 13, 13, '你们为我的名，要被众人恨恶，然而坚忍到底的必然得救。'),
('CNV', '马可福音', 41, 13, 14, '“当你们看见‘那造成荒凉的可憎者’，站在不该站的地方（读者必须领悟），那时，住在犹太的应当逃到山上；'),
('CNV', '马可福音', 41, 13, 15, '在房顶的不要下来，也不要进到屋子里拿什么东西；'),
('CNV', '马可福音', 41, 13, 16, '在田里的也不要回去取衣服。'),
('CNV', '马可福音', 41, 13, 17, '当那些日子，怀孕的和乳养孩子的有祸了！'),
('CNV', '马可福音', 41, 13, 18, '你们应当祈求，不要让这些事在冬天发生。'),
('CNV', '马可福音', 41, 13, 19, '因为那些日子必有灾难，这是从神创世的开始到现在未曾有过的，以后也必不会再有。'),
('CNV', '马可福音', 41, 13, 20, '如果不是主减少那些日子，没有一个人可以存活；但是为了自己的选民，他必使那些日子减少。'),
('CNV', '马可福音', 41, 13, 21, '那时，如果有人对你们说：‘看哪，基督在这里！看哪，他在那里！’你们不要信。'),
('CNV', '马可福音', 41, 13, 22, '因为必有假基督和假先知出现，行神迹和奇事，如果可以的话，连选民也要迷惑了。'),
('CNV', '马可福音', 41, 13, 23, '所以你们应当小心！我已经事先把一切都告诉你们了。'),
('CNV', '马可福音', 41, 13, 24, '“当那些日子，在那灾难以后，太阳就变黑了，月亮也不发光，'),
('CNV', '马可福音', 41, 13, 25, '众星从天坠落，天上的万象震动。'),
('CNV', '马可福音', 41, 13, 26, '那时，他们要看见人子，满有能力和荣耀，驾着云降临；'),
('CNV', '马可福音', 41, 13, 27, '他要差派天使，把他的选民从四方，从地极直到天边，都招聚来。'),
('CNV', '马可福音', 41, 13, 28, '“你们应该从无花果树学个功课：树枝发出嫩芽长出叶子的时候，你们就知道夏天近了。'),
('CNV', '马可福音', 41, 13, 29, '同样，你们什么时候看见这些事发生，就知道他已经近在门口了。'),
('CNV', '马可福音', 41, 13, 30, '我实在告诉你们，这一切都必会发生，然后这世代才会过去。'),
('CNV', '马可福音', 41, 13, 31, '天地都要过去，但我的话决不会废去。'),
('CNV', '马可福音', 41, 13, 32, '“至于那日子和时间，没有人知道，连天上的天使和子也不知道，只有父知道。'),
('CNV', '马可福音', 41, 13, 33, '你们要小心，要警醒，因为你们不知道那日期什么时候来到。'),
('CNV', '马可福音', 41, 13, 34, '这就像一个人出外远行，把责任（“责任”原文作“权柄”）一一地交给他的仆人，又吩咐看门的要警醒。'),
('CNV', '马可福音', 41, 13, 35, '所以你们要警醒，因为你们不知道家主什么时候来到，也许在黄昏，也许在半夜，也许在鸡叫时，也许在清晨。'),
('CNV', '马可福音', 41, 13, 36, '恐怕他忽然来到，发现你们正在睡觉。'),
('CNV', '马可福音', 41, 13, 37, '我对你们所说的话，也是对众人说的，‘你们要警醒’。”'),
('CNV', '马可福音', 41, 14, 1, '过两天，就是逾越节和除酵节了，祭司长和经学家设法怎样用诡计逮捕耶稣，把他杀害。'),
('CNV', '马可福音', 41, 14, 2, '不过他们说：“不可在节期下手，免得引起民众暴动。”'),
('CNV', '马可福音', 41, 14, 3, '耶稣在伯大尼，在患痲风的西门家里吃饭的时候，有一个女人来了，拿着一瓶珍贵的纯哪哒香膏。她打破了瓶，把香膏浇在耶稣的头上。'),
('CNV', '马可福音', 41, 14, 4, '有几个人很生气，彼此说：“为什么这样浪费香膏呢？'),
('CNV', '马可福音', 41, 14, 5, '这香膏可以卖三百多个银币，用来周济穷人。”他们就向她发怒。'),
('CNV', '马可福音', 41, 14, 6, '但耶稣说：“由她吧！为什么难为她呢？她在我身上作的是一件美事。'),
('CNV', '马可福音', 41, 14, 7, '你们常常有穷人跟你们在一起，只要你们愿意，随时都可以向他们行善，然而你们却不常有我。'),
('CNV', '马可福音', 41, 14, 8, '她已经尽她所能的作了。她预先用香膏膏了我的身体，是为了我的安葬。'),
('CNV', '马可福音', 41, 14, 9, '我实在告诉你们，福音无论传到世界上什么地方，都要传讲这女人所作的来记念她。”'),
('CNV', '马可福音', 41, 14, 10, '十二门徒中的一个，就是加略人犹大，去见祭司长，要把耶稣交给他们。'),
('CNV', '马可福音', 41, 14, 11, '他们听见了就很欢喜，答应给他银子。于是犹大就找机会出卖耶稣。'),
('CNV', '马可福音', 41, 14, 12, '除酵节的第一天，就是宰杀逾越节羊羔的那一天，门徒问耶稣：“你要我们到哪里去，为你预备逾越节的晚餐呢？”'),
('CNV', '马可福音', 41, 14, 13, '他就差派两个门徒，对他们说：“你们到城里去，必有一个拿着水瓶的人，向你们迎面而来，你们就跟着他，'),
('CNV', '马可福音', 41, 14, 14, '无论他进入哪一家，你们要对那家主说，老师说：‘我的客厅在哪里？我和门徒好在那里吃逾越节的晚餐。’'),
('CNV', '马可福音', 41, 14, 15, '他必指给你们楼上一间布置整齐、预备妥当的大房间，你们就在那里为我们预备。”'),
('CNV', '马可福音', 41, 14, 16, '门徒出去，进了城，所遇见的正如耶稣所说的，就预备好了逾越节的晚餐。'),
('CNV', '马可福音', 41, 14, 17, '到了晚上，耶稣和十二门徒来了。'),
('CNV', '马可福音', 41, 14, 18, '他们坐着吃饭的时候，耶稣说：“我实在告诉你们，你们中间有一个跟我一起吃饭的人要出卖我。”'),
('CNV', '马可福音', 41, 14, 19, '他们就很忧愁，一个一个地问他：“是我吗？”'),
('CNV', '马可福音', 41, 14, 20, '耶稣对他们说：“他是十二门徒里的一个，和我一同把手蘸在盘子里的。'),
('CNV', '马可福音', 41, 14, 21, '正如经上指着人子所说的，他固然要离世，但出卖人子的那人有祸了！他没有生下来还好。”'),
('CNV', '马可福音', 41, 14, 22, '他们吃的时候，耶稣拿起饼来，祝谢了，就擘开，递给门徒，说：“你们拿去吃吧，这是我的身体。”'),
('CNV', '马可福音', 41, 14, 23, '又拿起杯来，祝谢了就递给门徒，他们都喝了。'),
('CNV', '马可福音', 41, 14, 24, '耶稣说：“这是我的血，是为立约的，为许多人流出来的。'),
('CNV', '马可福音', 41, 14, 25, '我实在告诉你们，我决不再喝这葡萄酒，直到我在神的国里喝新酒的那一天。”'),
('CNV', '马可福音', 41, 14, 26, '他们唱完了诗，就出来，往橄榄山去。'),
('CNV', '马可福音', 41, 14, 27, '耶稣对他们说：“你们都要后退，因为经上记着：‘我要击打牧人，羊群就分散了。’'),
('CNV', '马可福音', 41, 14, 28, '但我复活以后，要比你们先到加利利去。”'),
('CNV', '马可福音', 41, 14, 29, '彼得对他说：“就算所有的人都后退，我却不会。”'),
('CNV', '马可福音', 41, 14, 30, '耶稣对他说：“我实在告诉你，就在今天晚上，鸡叫两遍以前，你会三次不认我。”'),
('CNV', '马可福音', 41, 14, 31, '彼得更坚决地说：“就算必须与你一同死，我也决不会不认你！”众人也都这样说。'),
('CNV', '马可福音', 41, 14, 32, '他们来到一个地方，名叫客西马尼；耶稣对门徒说：“你们坐在这里，我去祷告。”'),
('CNV', '马可福音', 41, 14, 33, '他带了彼得、雅各、约翰一起去，就惊惧起来，非常难过。'),
('CNV', '马可福音', 41, 14, 34, '于是对他们说：“我的心灵痛苦得快要死了；你们要留在这里，也要警醒。”'),
('CNV', '马可福音', 41, 14, 35, '耶稣稍往前走，俯伏在地上祷告：如果可能的话，使那时刻不要临到他。'),
('CNV', '马可福音', 41, 14, 36, '他说：“阿爸、父啊，你凡事都能作，求你叫这杯离开我。但不要照我的意思，只要照你的旨意。”'),
('CNV', '马可福音', 41, 14, 37, '耶稣回来，看见门徒睡着了，就对彼得说：“西门，你睡觉吗？你连一个小时也不能警醒吗？'),
('CNV', '马可福音', 41, 14, 38, '应当警醒、祷告，免得陷入试探；你们心灵虽然愿意，肉体却是软弱的。”'),
('CNV', '马可福音', 41, 14, 39, '耶稣又去祷告，说的也是同样的话。'),
('CNV', '马可福音', 41, 14, 40, '他再回来的时候，看见门徒睡着了；因为他们十分疲倦，不知道该怎样回答他。'),
('CNV', '马可福音', 41, 14, 41, '耶稣第三次回来，对他们说：“你们还在睡觉休息吗？够了，时候到了，看哪，人子要被交在罪人手里了。'),
('CNV', '马可福音', 41, 14, 42, '起来，我们走吧！出卖我的人来了。”'),
('CNV', '马可福音', 41, 14, 43, '耶稣还在说话的时候，十二门徒中的犹大和一群拿着刀棒的人来到了；他们是祭司长、经学家和长老派来的。'),
('CNV', '马可福音', 41, 14, 44, '出卖耶稣的人给他们一个暗号，说：“我跟谁亲吻，谁就是他。你们把他逮捕，小心带去。”'),
('CNV', '马可福音', 41, 14, 45, '犹大来到，立刻上前对耶稣说：“拉比！”就跟他亲吻。'),
('CNV', '马可福音', 41, 14, 46, '他们就动手拿住耶稣，逮捕了他。'),
('CNV', '马可福音', 41, 14, 47, '站在旁边的人中有一个拔出刀来，砍了大祭司的仆人一刀，削掉了他的一只耳朵。'),
('CNV', '马可福音', 41, 14, 48, '耶稣对他们说：“你们带着刀棒出来，把我当作强盗捉拿吗？'),
('CNV', '马可福音', 41, 14, 49, '我天天在殿里教导人，跟你们在一起，你们却没有捉拿我；但这是为了要应验经上的话。”'),
('CNV', '马可福音', 41, 14, 50, '门徒都离开他逃跑了。'),
('CNV', '马可福音', 41, 14, 51, '有一个青年，赤身披着一块麻布，跟着耶稣。众人捉住他的时候，'),
('CNV', '马可福音', 41, 14, 52, '他就丢掉麻布，赤身逃跑了。'),
('CNV', '马可福音', 41, 14, 53, '他们把耶稣押到大祭司那里，所有的祭司长、长老和经学家都聚集在一起。'),
('CNV', '马可福音', 41, 14, 54, '彼得远远地跟着耶稣，直到大祭司的官邸，和差役一同坐着烤火。'),
('CNV', '马可福音', 41, 14, 55, '祭司长和公议会全体都寻找证据控告耶稣，要把他处死，却没有找着。'),
('CNV', '马可福音', 41, 14, 56, '有许多人作假证供控告他，但他们的证供各不相符。'),
('CNV', '马可福音', 41, 14, 57, '有几个人站起来，作假证供控告他说：'),
('CNV', '马可福音', 41, 14, 58, '“我们听他说过：‘我要拆毁这座人手所造的圣所，三日之内要另建一座不是人手所造的圣所。’”')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '马可福音', 41, 14, 59, '就是这样的见证，他们也不一致。'),
('CNV', '马可福音', 41, 14, 60, '大祭司站起来，走到中间，问耶稣：“这些人作证控告你的是什么呢？你怎么不回答呢？”'),
('CNV', '马可福音', 41, 14, 61, '耶稣却不作声，什么也不回答。大祭司又问他：“你是那受称颂者的儿子基督吗？”'),
('CNV', '马可福音', 41, 14, 62, '耶稣说：“我是。你们要看见人子，坐在权能者的右边，驾着天上的云降临。”'),
('CNV', '马可福音', 41, 14, 63, '大祭司就撕开自己的衣服，说：“我们还要什么证人呢？'),
('CNV', '马可福音', 41, 14, 64, '你们都听见这亵渎的话了。你们认为怎么样？”众人都定他该死的罪。'),
('CNV', '马可福音', 41, 14, 65, '于是有些人就向他吐唾沫，蒙住他的脸。用拳头打他，对他说：“你说预言吧！”差役把他拉去，用手掌打他。'),
('CNV', '马可福音', 41, 14, 66, '彼得在下边院子的时候，大祭司的一个婢女来了，'),
('CNV', '马可福音', 41, 14, 67, '看见彼得烤火，就瞪着他说：“你也是和拿撒勒人耶稣一伙的！”'),
('CNV', '马可福音', 41, 14, 68, '彼得却否认说：“我不知道，也不明白你在说什么！”他就走出去，到了前院，鸡就叫了（有些抄本无“鸡就叫了”一句）。'),
('CNV', '马可福音', 41, 14, 69, '那婢女看见他，又对站在旁边的人说：“这个人也是他们一伙的。”'),
('CNV', '马可福音', 41, 14, 70, '彼得还是不承认。过了一会，站在旁边的人也对彼得说：“你真是他们一伙的，因为你也是加利利人。”'),
('CNV', '马可福音', 41, 14, 71, '彼得就发咒起誓说：“我不认得你们说的这个人！”'),
('CNV', '马可福音', 41, 14, 72, '立刻鸡就叫了第二遍。彼得想起耶稣对他说过的话：“鸡叫两遍以前，你要三次不认我。”他一想起来，就哭了（“他一想起来，就哭了”或译：“他就夺步而出，痛哭起来”）。'),
('CNV', '马可福音', 41, 15, 1, '一到清晨，祭司长和长老、经学家以及公议会全体一致议决，把耶稣绑起来，押去交给彼拉多。'),
('CNV', '马可福音', 41, 15, 2, '彼拉多问他：“你是犹太人的王吗？”耶稣回答：“你已经说了（“你已经说了”或译：“这是你说的”）。”'),
('CNV', '马可福音', 41, 15, 3, '祭司长控告了他许多事。'),
('CNV', '马可福音', 41, 15, 4, '彼拉多又问他：“你看，他们控告你这么多的事！你什么都不回答吗？”'),
('CNV', '马可福音', 41, 15, 5, '耶稣还是一言不答，使彼拉多非常惊奇。'),
('CNV', '马可福音', 41, 15, 6, '每逢这节期，彼拉多按着众人所要求的，照例给他们释放一个囚犯。'),
('CNV', '马可福音', 41, 15, 7, '有一个人名叫巴拉巴，和作乱的人囚禁在一起，他们作乱的时候，曾杀过人。'),
('CNV', '马可福音', 41, 15, 8, '群众上去，要求彼拉多援例给他们办理。'),
('CNV', '马可福音', 41, 15, 9, '彼拉多回答他们：“你们要我给你们释放这个犹太人的王吗？”'),
('CNV', '马可福音', 41, 15, 10, '他知道祭司长是因为嫉妒才把耶稣交了来。'),
('CNV', '马可福音', 41, 15, 11, '祭司长却煽动群众，宁可要总督释放巴拉巴给他们。'),
('CNV', '马可福音', 41, 15, 12, '彼拉多又对他们说：“那么，你们称为犹太人的王的，你们要我怎样处置他呢？”'),
('CNV', '马可福音', 41, 15, 13, '他们就喊着说：“把他钉十字架！”'),
('CNV', '马可福音', 41, 15, 14, '彼拉多说：“他作了什么恶事呢？”众人却更加大声喊叫：“把他钉十字架！”'),
('CNV', '马可福音', 41, 15, 15, '彼拉多有意讨好群众，就释放了巴拉巴给他们，把耶稣鞭打了，交给他们钉十字架。'),
('CNV', '马可福音', 41, 15, 16, '士兵把耶稣带进总督府的院子里，召集了全队士兵。'),
('CNV', '马可福音', 41, 15, 17, '他们给他披上紫色的外袍，又用荆棘编成冠冕给他戴上；'),
('CNV', '马可福音', 41, 15, 18, '就向他祝贺说：“犹太人的王万岁！”'),
('CNV', '马可福音', 41, 15, 19, '又用一根芦苇打他的头，向他吐唾沫，并且跪下来拜他。'),
('CNV', '马可福音', 41, 15, 20, '他们戏弄完了，就把他的紫色的外袍脱下，给他穿回自己的衣服，带他出去，要钉十字架。'),
('CNV', '马可福音', 41, 15, 21, '有一个古利奈人西门，就是亚历山大和鲁孚的父亲，从乡下来到，经过那里，士兵就强迫他背着耶稣的十字架。'),
('CNV', '马可福音', 41, 15, 22, '他们把耶稣带到各各他地方（这地名译出来就是“髑髅地”），'),
('CNV', '马可福音', 41, 15, 23, '拿没药调和的酒给他，他却不接受。'),
('CNV', '马可福音', 41, 15, 24, '他们就把他钉了十字架；又抽签分他的衣服，看谁得着什么。'),
('CNV', '马可福音', 41, 15, 25, '他们钉他十字架的时候，是在上午九点钟。'),
('CNV', '马可福音', 41, 15, 26, '耶稣的罪状牌上写着“犹太人的王”。'),
('CNV', '马可福音', 41, 15, 27, '他们又把两个强盗和他一同钉十字架，一个在右，一个在左（有些抄本有第'),
('CNV', '马可福音', 41, 15, 28, '节：“这就应验了经上所说的：‘他和不法者同列。’”）。'),
('CNV', '马可福音', 41, 15, 29, '过路的人讥笑他，摇着头说：“哼，你这个要拆毁圣所，三日之内又把它建造起来的，'),
('CNV', '马可福音', 41, 15, 30, '从十字架上把自己救下来吧！”'),
('CNV', '马可福音', 41, 15, 31, '祭司长和经学家也同样讥笑他，彼此说：“他救了别人，却不能救自己；'),
('CNV', '马可福音', 41, 15, 32, '以色列的王基督啊，现在可以从十字架上下来，让我们看见就信吧。”那和他同钉十字架的人也侮辱他。'),
('CNV', '马可福音', 41, 15, 33, '从正午到下午三点钟，遍地都黑暗了。'),
('CNV', '马可福音', 41, 15, 34, '下午三点的时候，耶稣大声呼号：“以罗伊，以罗伊，拉马撒巴各大尼？”这句话译出来就是：“我的神，我的神，你为什么离弃我？”'),
('CNV', '马可福音', 41, 15, 35, '有些站在旁边的人听见了就说：“看，他呼叫以利亚呢。”'),
('CNV', '马可福音', 41, 15, 36, '有一个人跑去拿海绵浸满了酸酒，绑在芦苇上，递给他喝，说：“等一等，我们看看以利亚来不来救他。”'),
('CNV', '马可福音', 41, 15, 37, '耶稣大叫一声，气就断了。'),
('CNV', '马可福音', 41, 15, 38, '圣所里的幔子，从上到下裂成两半。'),
('CNV', '马可福音', 41, 15, 39, '站在他对面的百夫长，看见他这样断气，就说：“这人真是神的儿子！”'),
('CNV', '马可福音', 41, 15, 40, '也有些妇女远远地观看，她们之中有抹大拉的马利亚，小雅各和约西的母亲马利亚，以及撒罗米。'),
('CNV', '马可福音', 41, 15, 41, '这些妇女，当耶稣在加利利的时候，就一直跟随他、服事他。此外，还有许多和他一同上耶路撒冷的妇女。'),
('CNV', '马可福音', 41, 15, 42, '到了晚上，因为是预备日，就是安息日的前一日，'),
('CNV', '马可福音', 41, 15, 43, '一个一向等候神国度的尊贵的议员，亚利马太的约瑟来了，就放胆地进去见彼拉多，求领耶稣的身体。'),
('CNV', '马可福音', 41, 15, 44, '彼拉多惊讶耶稣已经死了，就叫百夫长前来，问他耶稣是不是死了很久。'),
('CNV', '马可福音', 41, 15, 45, '他从百夫长知道了实情以后，就把尸体给了约瑟。'),
('CNV', '马可福音', 41, 15, 46, '约瑟买了细麻布，把耶稣取下，用细麻布裹好，安放在一个从磐石凿出来的坟墓里，又辊过一块石头来挡住墓门。'),
('CNV', '马可福音', 41, 15, 47, '抹大拉的马利亚和约西的母亲马利亚都看见安放他的地方。'),
('CNV', '马可福音', 41, 16, 1, '过了安息日，抹大拉的马利亚、雅各的母亲马利亚和撒罗米，买了香膏，要去膏耶稣。'),
('CNV', '马可福音', 41, 16, 2, '礼拜日的大清早，出太阳的时候，她们就来到坟墓那里，'),
('CNV', '马可福音', 41, 16, 3, '彼此说：“谁可以给我们辊开墓门的石头呢？”'),
('CNV', '马可福音', 41, 16, 4, '原来那块石头非常大，她们抬头一看，却见石头已经辊开了。'),
('CNV', '马可福音', 41, 16, 5, '她们进了坟墓，看见一位身穿白袍的青年，坐在右边，就非常惊恐。'),
('CNV', '马可福音', 41, 16, 6, '那青年对她们说：“不要惊慌！你们寻找那钉十字架的拿撒勒人耶稣，他不在这里，已经复活了；请看他们安放他的地方。'),
('CNV', '马可福音', 41, 16, 7, '你们去告诉他的门徒和彼得：他要比你们先到加利利去，你们在那里必定看见他，正如他从前告诉你们的。”'),
('CNV', '马可福音', 41, 16, 8, '因为惊恐战栗，她们一从坟墓出来就逃跑；由于害怕，她们什么也没有告诉人。（有些抄本无第9至20节）'),
('CNV', '马可福音', 41, 16, 9, '礼拜日的清早，耶稣复活了，先向抹大拉的马利亚显现，耶稣曾经从她身上赶出七个鬼。'),
('CNV', '马可福音', 41, 16, 10, '她就去告诉那些向来和耶稣在一起的人，那时他们正在悲哀哭泣。'),
('CNV', '马可福音', 41, 16, 11, '他们听见耶稣活了，又被马利亚看见了，却不相信。'),
('CNV', '马可福音', 41, 16, 12, '这事以后，门徒中有两个人往乡下去，正走路的时候，耶稣用另外的形象，向他们显现，'),
('CNV', '马可福音', 41, 16, 13, '他们就去告诉其他的人，那些人也不相信。'),
('CNV', '马可福音', 41, 16, 14, '后来，十一个门徒吃饭的时候，耶稣向他们显现，责备他们的不信和心硬，因为他们不信那些在他复活以后见过他的人。'),
('CNV', '马可福音', 41, 16, 15, '他又对他们说：“你们到全世界去，向所有的人传福音。'),
('CNV', '马可福音', 41, 16, 16, '信而受洗的必定得救，不信的必被定罪。'),
('CNV', '马可福音', 41, 16, 17, '信的人必有神迹随着他们，就是奉我的名赶鬼，用新方言说话，'),
('CNV', '马可福音', 41, 16, 18, '用手握蛇，喝了什么毒物也不受害，手按病人就必好了。”'),
('CNV', '马可福音', 41, 16, 19, '主耶稣向门徒讲完了话，就被接到天上，坐在神的右边。'),
('CNV', '马可福音', 41, 16, 20, '门徒出去，到处传扬福音，主和他们同工，藉着相随的神迹，证实所传的道。（有少数抄本有〔较短的结语〕：9“那些妇女把耶稣所吩咐的一切都告诉彼得和他的同伴。10这些事以后，耶稣藉着他们亲自把那神圣不朽、永远救恩的信息从东到西传扬出去。阿们。”放在第8节之后；另有少数抄本把它放在第20节之后。）'),
('CNV', '路加福音', 42, 1, 1, '尊敬的提阿非罗先生，因为有许多人，已经把在我们中间成就了的事，'),
('CNV', '路加福音', 42, 1, 2, '按照起初亲眼看见的传道人所传给我们的，编著成书；'),
('CNV', '路加福音', 42, 1, 3, '我已经把这些事从头考查过，认为也应该按着次序写给你，'),
('CNV', '路加福音', 42, 1, 4, '让你晓得所学到的道理，都是确实的。'),
('CNV', '路加福音', 42, 1, 5, '犹太王希律在位的日子，亚比雅班里有一个祭司，名叫撒迦利亚，他妻子是亚伦的后代，名叫以利沙伯。'),
('CNV', '路加福音', 42, 1, 6, '他们在神面前都是义人，遵行主的一切诫命规条，无可指摘，'),
('CNV', '路加福音', 42, 1, 7, '只是没有孩子，因为以利沙伯不生育，二人又都上了年纪。'),
('CNV', '路加福音', 42, 1, 8, '有一次，撒迦利亚在神面前按着班次执行祭司的职务，'),
('CNV', '路加福音', 42, 1, 9, '照祭司的惯例抽中了签，进入主的圣殿烧香。'),
('CNV', '路加福音', 42, 1, 10, '烧香的时候，众人都在外面祈祷。'),
('CNV', '路加福音', 42, 1, 11, '有主的使者站在香坛右边，向他显现。'),
('CNV', '路加福音', 42, 1, 12, '撒迦利亚一见就惊慌起来，十分害怕。'),
('CNV', '路加福音', 42, 1, 13, '天使说：“撒迦利亚，不要怕，因为你的祈求已蒙垂听，你妻子以利沙伯要给你生一个儿子，你要给他起名叫约翰。'),
('CNV', '路加福音', 42, 1, 14, '你必欢喜快乐，许多人因他出生，也必喜乐。'),
('CNV', '路加福音', 42, 1, 15, '他在主面前要被尊为大，淡酒浓酒都不喝，未出母腹就被圣灵充满。'),
('CNV', '路加福音', 42, 1, 16, '他要使许多以色列人转向主他们的神。'),
('CNV', '路加福音', 42, 1, 17, '他必有以利亚的灵和能力，行在主的前面，叫父亲的心转向儿女，叫悖逆的转向义人的意念，为主安排那预备好了的人民。”'),
('CNV', '路加福音', 42, 1, 18, '撒迦利亚对天使说：“我怎么能知道这事呢？我已经老了，我妻子也上了年纪。”'),
('CNV', '路加福音', 42, 1, 19, '天使回答：“我是站在神面前的加百列，奉差遣向你说话，报给你这好消息。'),
('CNV', '路加福音', 42, 1, 20, '看吧！到了时候我的话必要应验；因为你不信我的话，你必成为哑巴，直到这些事成就的那一天，才能说话。”'),
('CNV', '路加福音', 42, 1, 21, '众人等候撒迦利亚；因他在圣殿里迟迟不出来，觉得奇怪。'),
('CNV', '路加福音', 42, 1, 22, '等到他出来，却不能讲话，竟成了哑巴，不断地向他们打手式，他们就知道他在圣殿里见了异象。'),
('CNV', '路加福音', 42, 1, 23, '供职的日子满了，他就回家去。'),
('CNV', '路加福音', 42, 1, 24, '过了几天，他妻子以利沙伯怀了孕，隐藏了五个月，说：'),
('CNV', '路加福音', 42, 1, 25, '“主在眷顾的日子，这样看待我，要把我在人间的羞耻除掉。”'),
('CNV', '路加福音', 42, 1, 26, '到了第六个月，天使加百列奉神差遣，往加利利的拿撒勒城去，'),
('CNV', '路加福音', 42, 1, 27, '到了一个童贞女那里，她已经和大卫家一个名叫约瑟的人订了婚，童贞女的名字是马利亚。'),
('CNV', '路加福音', 42, 1, 28, '天使进去，对她说：“恭喜！蒙大恩的女子，主与你同在！”'),
('CNV', '路加福音', 42, 1, 29, '她却因这话惊慌起来，反覆思想这样祝贺是什么意思。'),
('CNV', '路加福音', 42, 1, 30, '天使说：“马利亚，不要怕！因你已从神那里蒙了恩。'),
('CNV', '路加福音', 42, 1, 31, '你将怀孕生子，要给他起名叫耶稣。'),
('CNV', '路加福音', 42, 1, 32, '他将要被尊为大，称为至高者的儿子，主神要把他祖大卫的王位赐给他，'),
('CNV', '路加福音', 42, 1, 33, '他要作王统治雅各家，直到永远，他的国没有穷尽。”'),
('CNV', '路加福音', 42, 1, 34, '马利亚对天使说：“我还没有出嫁（“我还没有出嫁”原文作“我不认识男人”），怎能有这事呢？”'),
('CNV', '路加福音', 42, 1, 35, '天使回答：“圣灵要临到你，至高者的能力要覆庇你，因此那将要出生的圣者，必称为神的儿子。'),
('CNV', '路加福音', 42, 1, 36, '你看，你亲戚以利沙伯，被称为不生育的，在老年也怀了男胎，现在已是第六个月了，'),
('CNV', '路加福音', 42, 1, 37, '因为在神没有一件事是不可能的。”'),
('CNV', '路加福音', 42, 1, 38, '马利亚说：“我是主的婢女，愿照你的话成就在我身上！”天使就离开她去了。'),
('CNV', '路加福音', 42, 1, 39, '后来，马利亚就起身，急忙向山地去，来到犹大的一座城，'),
('CNV', '路加福音', 42, 1, 40, '进了撒迦利亚的家，向以利沙伯问安。'),
('CNV', '路加福音', 42, 1, 41, '以利沙伯一听见马利亚的问安，腹中的胎儿就跳动，以利沙伯也被圣灵充满，'),
('CNV', '路加福音', 42, 1, 42, '就高声说：“你在女子中是有福的！你腹中的胎儿也是有福的！'),
('CNV', '路加福音', 42, 1, 43, '我主的母亲竟然到我这里来。这事怎会临到我呢？'),
('CNV', '路加福音', 42, 1, 44, '你看，你问安的声音一进我的耳朵，我腹中的胎儿就欢喜跳跃。'),
('CNV', '路加福音', 42, 1, 45, '这相信主传给她的话必要成就的女子是有福的。”'),
('CNV', '路加福音', 42, 1, 46, '马利亚说：“我心尊主为大，'),
('CNV', '路加福音', 42, 1, 47, '我灵以神我的救主为乐，'),
('CNV', '路加福音', 42, 1, 48, '因为他垂顾他婢女的卑微，看哪！今后万代都要称我为有福。'),
('CNV', '路加福音', 42, 1, 49, '全能者为我行了大事，他的名为圣；'),
('CNV', '路加福音', 42, 1, 50, '他的怜悯世世代代归与敬畏他的人。'),
('CNV', '路加福音', 42, 1, 51, '他用膀臂施展大能，驱散心里妄想的狂傲人。'),
('CNV', '路加福音', 42, 1, 52, '他使有权能的失位，叫卑微的升高，'),
('CNV', '路加福音', 42, 1, 53, '让饥饿的得饱美食，使富足的空手回去。'),
('CNV', '路加福音', 42, 1, 54, '他扶助了他的仆人以色列，为要记念他的怜悯，'),
('CNV', '路加福音', 42, 1, 55, '正如他向我们列祖所说的，恩待亚伯拉罕和他的后裔，直到永远。”'),
('CNV', '路加福音', 42, 1, 56, '马利亚和以利沙伯同住约有三个月，就回家去了。'),
('CNV', '路加福音', 42, 1, 57, '以利沙伯的产期到了，生了一个儿子。'),
('CNV', '路加福音', 42, 1, 58, '邻里亲戚，听见主向她大施怜悯，都和她一同欢乐。'),
('CNV', '路加福音', 42, 1, 59, '到了第八天，他们来给孩子行割礼，要照他父亲的名字，叫他撒迦利亚。'),
('CNV', '路加福音', 42, 1, 60, '但他母亲说：“不可，要叫他约翰。”'),
('CNV', '路加福音', 42, 1, 61, '他们说：“你亲族里没有叫这名字的。”'),
('CNV', '路加福音', 42, 1, 62, '他们就向孩子的父亲打手式，看他要叫他什么。'),
('CNV', '路加福音', 42, 1, 63, '他要了一块写字版，写上说：“他的名字是约翰。”众人都希奇。'),
('CNV', '路加福音', 42, 1, 64, '撒迦利亚的口舌立刻开了，就出声称颂神。'),
('CNV', '路加福音', 42, 1, 65, '住在周围的人都害怕，这一切事传遍了整个犹太山地，'),
('CNV', '路加福音', 42, 1, 66, '凡听见的就把这些事放在心里，说：“这孩子将会成为怎样的人呢？因为主的手与他同在。”'),
('CNV', '路加福音', 42, 1, 67, '他的父亲撒迦利亚被圣灵充满，预言说：'),
('CNV', '路加福音', 42, 1, 68, '“主，以色列的神，是应当称颂的，因他眷顾自己的子民，施行救赎，'),
('CNV', '路加福音', 42, 1, 69, '在他仆人大卫家中，为我们兴起救恩的角，'),
('CNV', '路加福音', 42, 1, 70, '正如主自古以来藉圣先知口中所说的，'),
('CNV', '路加福音', 42, 1, 71, '救我们脱离仇敌，和恨我们的人的手；'),
('CNV', '路加福音', 42, 1, 72, '向我们列祖施怜悯，记念他的圣约，'),
('CNV', '路加福音', 42, 1, 73, '就是他对我们祖先亚伯拉罕所起的誓，'),
('CNV', '路加福音', 42, 1, 74, '把我们从仇敌手中救拔出来，叫我们可以坦然无惧，用圣洁公义，在他面前一生一世敬拜他。'),
('CNV', '路加福音', 42, 1, 76, '孩子啊，你要称为至高者的先知，因为你要行在主的面前，预备他的路，'),
('CNV', '路加福音', 42, 1, 77, '使他的子民，因罪得赦，就知道救恩。'),
('CNV', '路加福音', 42, 1, 78, '因我们神的怜悯，使清晨的阳光从高天临到我们，'),
('CNV', '路加福音', 42, 1, 79, '光照那坐在黑暗中死荫里的人，引导我们的脚，走上平安的路。”'),
('CNV', '路加福音', 42, 1, 80, '这孩子渐渐长大，心灵健壮，住在旷野，直到他在以色列人中公开露面的日子。'),
('CNV', '路加福音', 42, 2, 1, '那时，有谕旨从凯撒奥古士督颁发下来，叫普天下的人登记户口。'),
('CNV', '路加福音', 42, 2, 2, '这是第一次户口登记，是在居里纽作叙利亚总督的时候举行的。'),
('CNV', '路加福音', 42, 2, 3, '众人各归各城去登记户口。'),
('CNV', '路加福音', 42, 2, 4, '约瑟本是大卫家族的人，也从加利利的拿撒勒上犹太去，到了大卫的城伯利恒，'),
('CNV', '路加福音', 42, 2, 5, '与所聘之妻马利亚一同登记户口。那时马利亚的身孕已经重了。'),
('CNV', '路加福音', 42, 2, 6, '他们在那里的时候，马利亚的产期到了，'),
('CNV', '路加福音', 42, 2, 7, '生了头胎儿子，用布包着，放在马槽里，因为客店里没有地方。'),
('CNV', '路加福音', 42, 2, 8, '在伯利恒的郊外，有一些牧人在夜间看守羊群。'),
('CNV', '路加福音', 42, 2, 9, '主的一位使者站在他们旁边，主的荣光四面照着他们，他们就非常害怕。'),
('CNV', '路加福音', 42, 2, 10, '天使说：“不要怕！看哪！我报给你们大喜的信息，是关于万民的：'),
('CNV', '路加福音', 42, 2, 11, '今天在大卫的城里，为你们生了救主，就是主基督。'),
('CNV', '路加福音', 42, 2, 12, '你们要找到一个婴孩，包着布，卧在马槽里，那就是记号了。”'),
('CNV', '路加福音', 42, 2, 13, '忽然有一大队天兵，同那天使一起赞美神说：'),
('CNV', '路加福音', 42, 2, 14, '“在至高之处，荣耀归与神！在地上，平安归与他所喜悦的人！”'),
('CNV', '路加福音', 42, 2, 15, '众天使离开他们升天去了，那些牧人彼此说：“我们往伯利恒去，看看主所指示我们已经成就的事。”'),
('CNV', '路加福音', 42, 2, 16, '他们急忙去了，找到马利亚、约瑟和那卧在马槽里的婴孩。'),
('CNV', '路加福音', 42, 2, 17, '他们见过以后，就把天使对他们论这孩子的话传开了。'),
('CNV', '路加福音', 42, 2, 18, '听见的人，都希奇牧人所说的事。'),
('CNV', '路加福音', 42, 2, 19, '马利亚把这一切放在心里，反覆思想。'),
('CNV', '路加福音', 42, 2, 20, '牧人因为听见的和看见的，正像天使对他们所说的一样，就回去了，把荣耀赞美归与神。'),
('CNV', '路加福音', 42, 2, 21, '满了八天，替孩子行割礼的时候，就给他起名叫耶稣，就是他成胎之前，天使所起的。'),
('CNV', '路加福音', 42, 2, 22, '满了洁净的日子，他们就按着摩西的律法，带孩子上耶路撒冷去，奉献给主。'),
('CNV', '路加福音', 42, 2, 23, '正如主的律法所记：“所有头生的男孩，都当称为圣归给主。”'),
('CNV', '路加福音', 42, 2, 24, '又照着主的律法所说的献上祭物，就是一对斑鸠或两只雏鸽。'),
('CNV', '路加福音', 42, 2, 25, '在耶路撒冷有一个人，名叫西面，这人公义虔诚，一向期待以色列的安慰者来到，又有圣灵在他身上。'),
('CNV', '路加福音', 42, 2, 26, '圣灵启示他，在死前必得见主所应许的基督，'),
('CNV', '路加福音', 42, 2, 27, '他又受圣灵感动进了圣殿。那时，耶稣的父母抱着孩子进来，要按着律法的规矩为他行礼。'),
('CNV', '路加福音', 42, 2, 28, '西面就把他接到手上，称颂神说：'),
('CNV', '路加福音', 42, 2, 29, '“主啊，现在照你的话，释放仆人平平安安地去吧！'),
('CNV', '路加福音', 42, 2, 30, '因我的眼睛已经看见你的救恩，'),
('CNV', '路加福音', 42, 2, 31, '就是你在万民面前所预备的，'),
('CNV', '路加福音', 42, 2, 32, '为要作外族人启示的光，和你民以色列的荣耀。”'),
('CNV', '路加福音', 42, 2, 33, '他父母因论到他的这些话而希奇。'),
('CNV', '路加福音', 42, 2, 34, '西面给他们祝福，对他母亲马利亚说：“看哪！这孩子被立，要叫以色列中许多人跌倒，许多人兴起，又要成为反对的目标，'),
('CNV', '路加福音', 42, 2, 35, '（你自己的心也会被刀刺透，）这样，许多人心中的意念就要被揭露出来。”'),
('CNV', '路加福音', 42, 2, 36, '又有一个女先知，就是亚拿，是亚设支派法内利的女儿。她已经上了年纪，从童女出嫁，和丈夫住了七年，'),
('CNV', '路加福音', 42, 2, 37, '就寡居了，直到八十四岁（“就寡居了，直到八十四岁”或译：“就寡居了八十四年”）。她没有离开过圣殿，以禁食和祷告昼夜事奉主。'),
('CNV', '路加福音', 42, 2, 38, '就在那时候，她前来称谢神，并且向期待耶路撒冷蒙救赎的众人，讲论孩子的事。'),
('CNV', '路加福音', 42, 2, 39, '他们按着主的律法办完一切，就回加利利，到自己的城拿撒勒去了。'),
('CNV', '路加福音', 42, 2, 40, '孩子渐渐长大，强壮起来，充满智慧，有神的恩典在他身上。'),
('CNV', '路加福音', 42, 2, 41, '每年逾越节，他父母都上耶路撒冷去。'),
('CNV', '路加福音', 42, 2, 42, '当他十二岁时，他们按着节期的惯例，照常上去。'),
('CNV', '路加福音', 42, 2, 43, '过完了节，他们回去的时候，孩童耶稣仍留在耶路撒冷，他父母却不知道，'),
('CNV', '路加福音', 42, 2, 44, '还以为他在同行的人中间。走了一天，就在亲戚和熟人中找他，'),
('CNV', '路加福音', 42, 2, 45, '没有找到，就转回耶路撒冷找他。'),
('CNV', '路加福音', 42, 2, 46, '过了三天，才发现他在圣殿里，坐在教师中间，一面听，一面问。'),
('CNV', '路加福音', 42, 2, 47, '所有听见他的人，都希奇他的聪明和应对。'),
('CNV', '路加福音', 42, 2, 48, '他父母见了，非常惊奇，他母亲说：“孩子，为什么这样对待我们呢？你看，你父亲和我都很担心地在找你呢！”'),
('CNV', '路加福音', 42, 2, 49, '他说：“为什么找我呢？你们不知道我必须在我父的家里吗？（“在我父的家里吗？”或译：“以我父的事为念吗？”）”'),
('CNV', '路加福音', 42, 2, 50, '但他们不明白他所说的话。'),
('CNV', '路加福音', 42, 2, 51, '他就同他们下去，回到拿撒勒，并且顺从他们。他母亲把这一切事，都存在心里。'),
('CNV', '路加福音', 42, 2, 52, '耶稣的智慧和身量，以及神和人对他的喜爱，都不断增长。'),
('CNV', '路加福音', 42, 3, 1, '凯撒提庇留执政第十五年，本丢．彼拉多作犹太总督，希律作加利利的分封王，他兄弟腓力作以土利亚和特拉可尼地区的分封王，吕撒尼亚作亚比利尼的分封王，'),
('CNV', '路加福音', 42, 3, 2, '亚那和该亚法作大祭司的时候，神的话临到撒迦利亚的儿子，在旷野的约翰。'),
('CNV', '路加福音', 42, 3, 3, '他就来到约旦河一带地方，宣讲悔改的洗礼，使罪得赦。'),
('CNV', '路加福音', 42, 3, 4, '正如以赛亚先知的书上写着：“在旷野有呼喊者的声音：‘预备主的道，修直他的路！'),
('CNV', '路加福音', 42, 3, 5, '一切洼谷都当填满，大小山冈都要削平！弯弯曲曲的改为正直，高高低低的修成平坦！'),
('CNV', '路加福音', 42, 3, 6, '所有的人都要看见神的救恩。’”'),
('CNV', '路加福音', 42, 3, 7, '约翰对那出来要受他洗礼的群众说：“毒蛇所生的啊，谁指示你们逃避那将要来的忿怒呢？'),
('CNV', '路加福音', 42, 3, 8, '应当结出果子来，与悔改的心相称；你们心里不要说：‘我们有亚伯拉罕作我们的祖宗。’我告诉你们，神能从这些石头中给亚伯拉罕兴起后裔来。'),
('CNV', '路加福音', 42, 3, 9, '现在斧头已经放在树根上，所有不结好果子的树，就砍下来，丢在火里。”'),
('CNV', '路加福音', 42, 3, 10, '群众问他：“那么，我们该作什么呢？”'),
('CNV', '路加福音', 42, 3, 11, '他回答：“有两件衣服的，当分给那没有的，有食物的也当照样作。”'),
('CNV', '路加福音', 42, 3, 12, '又有税吏来要受洗，问他：“老师，我们当作什么呢？”'),
('CNV', '路加福音', 42, 3, 13, '他说：“除了规定的以外，不可多收。”'),
('CNV', '路加福音', 42, 3, 14, '兵丁也问他：“至于我们，我们又应当作什么呢？”他说：“不要恐吓，不要敲诈，当以自己的粮饷为满足。”'),
('CNV', '路加福音', 42, 3, 15, '那时众人正在期待，人人心里都在猜想会不会约翰就是基督。'),
('CNV', '路加福音', 42, 3, 16, '约翰对众人说：“我用水给你们施洗，但那能力比我更大的要来，我就是给他解鞋带都没有资格。他要用圣灵与火给你们施洗。'),
('CNV', '路加福音', 42, 3, 17, '他手里拿着簸箕，要扬净麦场，把麦子收进仓里，却用不灭的火把糠秕烧尽。”'),
('CNV', '路加福音', 42, 3, 18, '他还用许多别的话劝勉众人，向他们传福音。'),
('CNV', '路加福音', 42, 3, 19, '分封王希律，因他弟弟的妻子希罗底，并因他自己所行的一切恶事，受到约翰的责备。'),
('CNV', '路加福音', 42, 3, 20, '他在这一切事以外，再加上一件，就是把约翰关在监里。'),
('CNV', '路加福音', 42, 3, 21, '众人受了洗，耶稣也受了洗。他正在祷告，天就开了，'),
('CNV', '路加福音', 42, 3, 22, '圣灵仿佛鸽子，有形体地降在他身上；有声音从天上来，说：“你是我的爱子，我喜悦你。”'),
('CNV', '路加福音', 42, 3, 23, '耶稣开始传道，年约三十岁，人以为他是约瑟的儿子，约瑟是希里的儿子，'),
('CNV', '路加福音', 42, 3, 24, '依次往上推，是玛塔、利未、麦基、雅拿、约瑟、'),
('CNV', '路加福音', 42, 3, 25, '玛他提亚、亚摩斯、拿鸿、以斯利、拿该、'),
('CNV', '路加福音', 42, 3, 26, '玛押、玛他提亚、西美、约瑟、约大、'),
('CNV', '路加福音', 42, 3, 27, '约哈难、利撒、所罗巴伯、撒拉铁、尼利、'),
('CNV', '路加福音', 42, 3, 28, '麦基、亚底、哥桑、以摩当、珥、'),
('CNV', '路加福音', 42, 3, 29, '耶书、以利以谢、约令、玛塔、利未、'),
('CNV', '路加福音', 42, 3, 30, '西缅、犹大、约瑟、约南、以利亚敬、'),
('CNV', '路加福音', 42, 3, 31, '米利亚、买拿、马达他、拿单、大卫、'),
('CNV', '路加福音', 42, 3, 32, '耶西、俄备得、波阿斯、撒门（“撒门”有些抄本作“撒拉”）、拿顺、'),
('CNV', '路加福音', 42, 3, 33, '亚米拿达、亚当民（有些抄本无“亚当民”一词）、亚兰（“亚兰”有些抄本作“亚珥尼”）、希斯仑、法勒斯、犹大、'),
('CNV', '路加福音', 42, 3, 34, '雅各、以撒、亚伯拉罕、他拉、拿鹤、'),
('CNV', '路加福音', 42, 3, 35, '西鹿、拉吴、法勒、希伯、沙拉、'),
('CNV', '路加福音', 42, 3, 36, '该南、亚法撒、闪、挪亚、拉麦、'),
('CNV', '路加福音', 42, 3, 37, '玛土撒拉、以诺、雅列、玛勒列、该南、'),
('CNV', '路加福音', 42, 3, 38, '以挪士、塞特、亚当，亚当是神的儿子。'),
('CNV', '路加福音', 42, 4, 1, '耶稣被圣灵充满，从约旦河回来，圣灵引他到旷野，'),
('CNV', '路加福音', 42, 4, 2, '四十天受魔鬼的试探。那些日子他什么也没有吃，日子满了他就饿了。'),
('CNV', '路加福音', 42, 4, 3, '魔鬼对他说：“你若是神的儿子，就吩咐这块石头变成食物吧！”'),
('CNV', '路加福音', 42, 4, 4, '耶稣回答：“经上记着：‘人活着不是单靠食物。’”'),
('CNV', '路加福音', 42, 4, 5, '魔鬼引他上到高处，霎时间把天下万国指给他看，'),
('CNV', '路加福音', 42, 4, 6, '对他说：“这一切权柄、荣华，我都可以给你；因为这些都交给了我，我愿意给谁就给谁。'),
('CNV', '路加福音', 42, 4, 7, '所以，只要你在我面前拜一拜，这一切就全是你的了。”'),
('CNV', '路加福音', 42, 4, 8, '耶稣回答：“经上记着：‘当拜主你的神，单要事奉他。’”'),
('CNV', '路加福音', 42, 4, 9, '魔鬼又引他到耶路撒冷，叫他站在殿的最高处，对他说：“你若是神的儿子，就从这里跳下去吧！'),
('CNV', '路加福音', 42, 4, 10, '因为经上记着：‘他为了你，会吩咐自己的使者保护你。’'),
('CNV', '路加福音', 42, 4, 11, '又记着：‘用手托住你，免得你的脚碰到石头。’”'),
('CNV', '路加福音', 42, 4, 12, '耶稣回答：“经上说：‘不可试探主你的神。’”'),
('CNV', '路加福音', 42, 4, 13, '魔鬼用尽了各种试探，就暂时离开了耶稣。'),
('CNV', '路加福音', 42, 4, 14, '耶稣带着圣灵的能力，回到加利利。他的名声传遍了周围各地。'),
('CNV', '路加福音', 42, 4, 15, '他在各会堂里教导人，很受众人的尊崇。'),
('CNV', '路加福音', 42, 4, 16, '耶稣来到拿撒勒自己长大的地方，照着习惯在安息日进入会堂，站起来要读经。'),
('CNV', '路加福音', 42, 4, 17, '有人把以赛亚先知的书递给他，他展开书卷找到一处，上面写着：'),
('CNV', '路加福音', 42, 4, 18, '“主的灵在我身上，因为他膏我去传福音给贫穷的人，差遣我去宣告被掳的得释放，瞎眼的得看见，受压制的得自由，'),
('CNV', '路加福音', 42, 4, 19, '又宣告主悦纳人的禧年。”'),
('CNV', '路加福音', 42, 4, 20, '他把书卷卷好，交还侍役，就坐下。会堂里众人都注视他。'),
('CNV', '路加福音', 42, 4, 21, '他就对他们说：“这段经文今天应验在你们中间（“中间”原文作“耳中”）了。”'),
('CNV', '路加福音', 42, 4, 22, '众人称赞他，希奇他口中所出的恩言，并且说：“这不是约瑟的儿子吗？”'),
('CNV', '路加福音', 42, 4, 23, '他说：“你们必向我说这俗语：‘医生，治好你自己吧！’也必说：‘我们听见你在迦百农所行的一切事，也该在你本乡这里行啊！’”'),
('CNV', '路加福音', 42, 4, 24, '他又说：“我实在告诉你们，没有先知在他本乡是受欢迎的。'),
('CNV', '路加福音', 42, 4, 25, '我对你们说实话，当以利亚的时候，三年六个月不下雨（“不下雨”原文作“天闭塞”），遍地大起饥荒，那时以色列中有许多寡妇，'),
('CNV', '路加福音', 42, 4, 26, '以利亚没有奉差遣往他们中间任何一个那里去，只到西顿撒勒法的一个寡妇那里。'),
('CNV', '路加福音', 42, 4, 27, '以利沙先知的时候，以色列中有许多患痲风的人，其中除了叙利亚的乃缦，没有一个得洁净的。”'),
('CNV', '路加福音', 42, 4, 28, '会堂里的众人听见这话，都怒气填胸，'),
('CNV', '路加福音', 42, 4, 29, '起来赶他出城（这城原来建在山上），他们拉他到山崖，要把他推下去。'),
('CNV', '路加福音', 42, 4, 30, '耶稣却从他们中间走过，就离去了。'),
('CNV', '路加福音', 42, 4, 31, '耶稣下到加利利的迦百农城，在安息日教导人。'),
('CNV', '路加福音', 42, 4, 32, '他们对他的教训都很惊奇，因为他的话带着权柄。'),
('CNV', '路加福音', 42, 4, 33, '会堂里有一个被污鬼附着的人，大声喊叫：'),
('CNV', '路加福音', 42, 4, 34, '“哎！拿撒勒人耶稣，我们跟你有什么关系呢？你来毁灭我们吗？我知道你是谁，你是神的圣者。”'),
('CNV', '路加福音', 42, 4, 35, '耶稣斥责他说：“住口！从他身上出来！”鬼把那人摔倒在众人中间，就从他身上出来了，没有伤害他。'),
('CNV', '路加福音', 42, 4, 36, '众人都惊骇，彼此谈论说：“这是怎么回事？他用权柄能力吩咐污灵，污灵竟出来了。”'),
('CNV', '路加福音', 42, 4, 37, '耶稣的名声，传遍了周围各地。'),
('CNV', '路加福音', 42, 4, 38, '他起身离开会堂，进入西门的家。西门的岳母正在发高热，他们为她求耶稣。'),
('CNV', '路加福音', 42, 4, 39, '耶稣站在她旁边，斥责那热病，热就退了；她立刻起身服事他们。'),
('CNV', '路加福音', 42, 4, 40, '日落的时候，不论害什么病的人，都被带到耶稣那里；他一一为他们按手，医好他们。'),
('CNV', '路加福音', 42, 4, 41, '又有鬼从好些人身上出来，喊着说：“你是神的儿子。”耶稣斥责他们，不许他们说话，因为他们知道他是基督。'),
('CNV', '路加福音', 42, 4, 42, '天一亮，耶稣出来，到旷野地方去。众人寻找他，一直找到他那里，要留住他，不要他离开他们。'),
('CNV', '路加福音', 42, 4, 43, '他却说：“我也必须到别的城去传神国的福音，因为我是为了这缘故奉差遣的。”'),
('CNV', '路加福音', 42, 4, 44, '于是他往犹太的各会堂去传道。'),
('CNV', '路加福音', 42, 5, 1, '耶稣站在革尼撒勒湖边，众人拥挤他，要听神的道。'),
('CNV', '路加福音', 42, 5, 2, '他看见两只船停在湖边，渔夫离开船洗网去了。'),
('CNV', '路加福音', 42, 5, 3, '他上了西门的那一只船，请他撑开，离岸不远，就坐下，从船上教导众人。'),
('CNV', '路加福音', 42, 5, 4, '讲完了，就对西门说：“把船开到水深的地方，下网打鱼！”'),
('CNV', '路加福音', 42, 5, 5, '西门说：“主啊，我们整夜劳苦，毫无所得，不过，我愿照你的话下网。”'),
('CNV', '路加福音', 42, 5, 6, '他们下了网，就圈住很多鱼，网几乎裂开，'),
('CNV', '路加福音', 42, 5, 7, '就招呼另外那只船上的同伴来帮助，他们就来把两只船装满，甚至船要下沉。'),
('CNV', '路加福音', 42, 5, 8, '西门．彼得看见这种情景，就俯伏在耶稣膝前，说：“主啊，离开我，因为我是个罪人。”'),
('CNV', '路加福音', 42, 5, 9, '他和跟他在一起的人，因这网所打的鱼，都十分惊骇。'),
('CNV', '路加福音', 42, 5, 10, '西门的伙伴，西庇太的儿子雅各、约翰也是这样。耶稣对西门说：“不要怕！从今以后，你要作得人的渔夫了。”'),
('CNV', '路加福音', 42, 5, 11, '他们把两只船拢了岸，撇下一切，跟从了耶稣。'),
('CNV', '路加福音', 42, 5, 12, '有一次，耶稣在一个城里，突然有一个满身痲风的人看见他，就把脸伏在地上，求他说：“主啊！如果你肯，必能使我洁净。”'),
('CNV', '路加福音', 42, 5, 13, '耶稣伸手摸他，说：“我肯，你洁净了吧！”痲风立刻离开了他。'),
('CNV', '路加福音', 42, 5, 14, '耶稣嘱咐他不可告诉任何人，“你只要去给祭司检查，并且照着摩西所规定的，为你得洁净献祭，好向大家作证。”'),
('CNV', '路加福音', 42, 5, 15, '但他的名声却越发传扬出去，成群的人来聚集，要听道，并且要使他们的疾病痊愈。'),
('CNV', '路加福音', 42, 5, 16, '耶稣却退到旷野去祷告。'),
('CNV', '路加福音', 42, 5, 17, '有一天，耶稣正在教导人，法利赛人和律法教师也坐在那里，他们是从加利利和犹太各乡村，并耶路撒冷来的；主的能力与他同在，叫他能医病。'),
('CNV', '路加福音', 42, 5, 18, '有人用床抬着一个瘫子，想送进去，放在耶稣跟前。'),
('CNV', '路加福音', 42, 5, 19, '因为人多，没有办法进去，就上了房顶，从瓦间把瘫子和床往当中缒下去，正在耶稣跟前。'),
('CNV', '路加福音', 42, 5, 20, '他看见他们的信心，就说：“朋友（“朋友”原文作“人”），你的罪赦了。”'),
('CNV', '路加福音', 42, 5, 21, '经学家和法利赛人就议论起来，说：“这人是谁，竟然说僭妄的话？除神一位以外，谁能赦罪呢？”'),
('CNV', '路加福音', 42, 5, 22, '耶稣知道他们的议论，就对他们说：“你们心里为什么议论呢？'),
('CNV', '路加福音', 42, 5, 23, '说：‘你的罪赦了’，或说：‘起来行走’，哪一样容易呢？'),
('CNV', '路加福音', 42, 5, 24, '然而为了要你们知道，人子在地上有赦罪的权柄，（他就对瘫子说：）我吩咐你，起来，拿起你的床，回家去吧。”'),
('CNV', '路加福音', 42, 5, 25, '那人立刻当众起来，拿着他躺过的床，颂赞神，回家去了。'),
('CNV', '路加福音', 42, 5, 26, '众人都惊奇，颂赞神，并且十分惧怕，说：“我们今天看见了不平常的事。”'),
('CNV', '路加福音', 42, 5, 27, '事后，耶稣出去，看见一个税吏，名叫利未，坐在税关那里，就对他说：“来跟从我！”'),
('CNV', '路加福音', 42, 5, 28, '他就撇下一切，起来跟从了耶稣。'),
('CNV', '路加福音', 42, 5, 29, '利未在自己家里，为他大摆筵席，有许多税吏和别的人一起吃饭。'),
('CNV', '路加福音', 42, 5, 30, '法利赛人和经学家埋怨他的门徒，说：“你们为什么跟税吏和罪人一起吃喝呢？”'),
('CNV', '路加福音', 42, 5, 31, '耶稣回答：“健康的人不需要医生，有病的人才需要。'),
('CNV', '路加福音', 42, 5, 32, '我来不是要召义人，而是要召罪人悔改。”'),
('CNV', '路加福音', 42, 5, 33, '他们说：“约翰的门徒常常禁食、祈祷，法利赛人的门徒也是这样，而你的门徒却又吃又喝。”'),
('CNV', '路加福音', 42, 5, 34, '耶稣说：“新郎跟宾客在一起的时候，你们怎么可以叫宾客禁食呢？'),
('CNV', '路加福音', 42, 5, 35, '但日子到了，新郎要被取去，离开他们，那一天他们就要禁食了。”'),
('CNV', '路加福音', 42, 5, 36, '他又对他们设个比喻说：“没有人会从新衣服撕下一块布，补在旧衣服上，如果这样，不但新衣服撕破了，而且新撕下的布，也和旧的不调和。'),
('CNV', '路加福音', 42, 5, 37, '也没有人会把新酒装在旧皮袋里；如果这样，新酒就会把皮袋胀破，不但酒漏掉，皮袋也损坏了；'),
('CNV', '路加福音', 42, 5, 38, '人总是把新酒装在新皮袋里。'),
('CNV', '路加福音', 42, 5, 39, '喝惯陈酒的人，就不想喝新酒，他总说陈的好。”'),
('CNV', '路加福音', 42, 6, 1, '有一个安息日，耶稣从麦田经过，他的门徒摘了麦穗，用手搓着吃。'),
('CNV', '路加福音', 42, 6, 2, '有几个法利赛人说：“你们为什么作安息日不可作的事呢？”'),
('CNV', '路加福音', 42, 6, 3, '耶稣回答：“大卫和跟他在一起的人，在饥饿的时候所作的，你们没有念过吗？'),
('CNV', '路加福音', 42, 6, 4, '他不是进了神的殿，吃了陈设饼，也给跟他在一起的人吃吗？这饼除了祭司以外，别的人是不可以吃的。”'),
('CNV', '路加福音', 42, 6, 5, '他又对他们说：“人子是安息日的主。”'),
('CNV', '路加福音', 42, 6, 6, '另一个安息日，耶稣进入会堂教导人，在那里有一个人，右手枯干，'),
('CNV', '路加福音', 42, 6, 7, '经学家和法利赛人要看他会不会在安息日治病，好找把柄控告他。'),
('CNV', '路加福音', 42, 6, 8, '耶稣知道他们的意念，就对那一只手枯干了的人说：“起来，站在当中！”那人就起来站着。'),
('CNV', '路加福音', 42, 6, 9, '耶稣对他们说：“我问你们：在安息日哪一样是可以作的呢：作好事还是坏事？救命还是害命？”'),
('CNV', '路加福音', 42, 6, 10, '他环视周围所有的人，就对那人说：“伸出你的手来！”他把手一伸，手就复原了。'),
('CNV', '路加福音', 42, 6, 11, '他们却大怒，彼此商议怎样对付耶稣。'),
('CNV', '路加福音', 42, 6, 12, '在那些日子，有一次耶稣出去到山上祷告，整夜祷告神。'),
('CNV', '路加福音', 42, 6, 13, '天亮以后，他把门徒叫来，从他们中间挑选了十二个人，称他们为使徒，'),
('CNV', '路加福音', 42, 6, 14, '就是西门（又给他起名叫彼得），和他弟弟安得烈，以及雅各、约翰、腓力、巴多罗迈、'),
('CNV', '路加福音', 42, 6, 15, '马太、多马、亚勒腓的儿子雅各、称为激进派的西门、'),
('CNV', '路加福音', 42, 6, 16, '雅各的儿子犹大，和出卖主的加略人犹大。'),
('CNV', '路加福音', 42, 6, 17, '耶稣和他们下了山，站在平地上，有一大群门徒同他在一起，又有一大批从犹太全地、耶路撒冷和推罗、西顿海边来的人。'),
('CNV', '路加福音', 42, 6, 18, '他们要听他讲道，也要他们的疾病得医好。还有一些被污灵缠扰的也痊愈了。'),
('CNV', '路加福音', 42, 6, 19, '群众都设法摸他，因为有能力从他身上出来，治好众人。'),
('CNV', '路加福音', 42, 6, 20, '耶稣抬头看着门徒，说：“贫穷的人有福了，因为神的国是你们的。'),
('CNV', '路加福音', 42, 6, 21, '饥饿的人有福了，因为你们要得饱足。哀哭的人有福了，因为你们将要喜乐。'),
('CNV', '路加福音', 42, 6, 22, '世人为人子的缘故憎恨你们、排斥你们、辱骂你们，弃绝你们的名好像弃绝恶物，你们就有福了。'),
('CNV', '路加福音', 42, 6, 23, '那时你们应该欢喜跳跃，因为你们在天上的赏赐是大的，他们的祖先对待先知也是这样。'),
('CNV', '路加福音', 42, 6, 24, '“然而你们富有的人有祸了，因为你们已经得了你们的安慰。'),
('CNV', '路加福音', 42, 6, 25, '你们饱足的人有祸了，因为你们将要饥饿。你们喜乐的人有祸了，因为你们将要痛哭。'),
('CNV', '路加福音', 42, 6, 26, '人都说你们好的时候，你们就有祸了，因为你们的祖先对待假先知也是这样。'),
('CNV', '路加福音', 42, 6, 27, '“只是我告诉你们听道的人：当爱你们的仇敌，善待恨你们的人。'),
('CNV', '路加福音', 42, 6, 28, '咒诅你们的，要为他们祝福，凌辱你们的，要为他们祷告。'),
('CNV', '路加福音', 42, 6, 29, '有人打你一边的脸，把另一边也转给他打；有人拿你的外衣，连内衣也让他拿去。'),
('CNV', '路加福音', 42, 6, 30, '向你求的，就给他；有人拿去你的东西，不用再要回来。'),
('CNV', '路加福音', 42, 6, 31, '你们愿意人怎样待你们，你们就应当怎样待人。'),
('CNV', '路加福音', 42, 6, 32, '如果单爱那些爱你们的人，那有什么好处呢？罪人也爱那些爱他们的人。'),
('CNV', '路加福音', 42, 6, 33, '如果只善待那些善待你们的人，那有什么好处呢？罪人也会这样行。'),
('CNV', '路加福音', 42, 6, 34, '如果借给人，又指望向人收回，那有什么好处呢？罪人也借给罪人，要如数收回。'),
('CNV', '路加福音', 42, 6, 35, '你们要爱仇敌，善待他们；借出去，不要指望偿还；这样你们的赏赐就大了，你们也必作至高者的儿子，因为神自己也宽待忘恩的和恶人。'),
('CNV', '路加福音', 42, 6, 36, '你们要仁慈像你们的父仁慈一样。'),
('CNV', '路加福音', 42, 6, 37, '“你们不要判断人，就必不受判断；不要定人的罪，就必不被定罪；要饶恕人，就必蒙饶恕；'),
('CNV', '路加福音', 42, 6, 38, '要给人，就必有给你们的；并且要用十足的升斗，连按带摇，上尖下流地倒在你们怀里；因为你们用什么升斗量给人，就必用什么升斗量给你们。”'),
('CNV', '路加福音', 42, 6, 39, '耶稣又用比喻对他们说：“瞎子怎能给瞎子领路呢？两个人不都要掉在坑里吗？'),
('CNV', '路加福音', 42, 6, 40, '学生不能胜过老师，所有学成的，不过和老师一样。'),
('CNV', '路加福音', 42, 6, 41, '为什么看得见你弟兄眼中的木屑，却想不到自己眼中的梁木呢？'),
('CNV', '路加福音', 42, 6, 42, '你不看见自己眼中的梁木，怎能对你弟兄说：‘弟兄，容我除去你眼中的木屑’呢？伪君子啊！先去掉自己眼中的梁木，才能看得清楚，好去掉弟兄眼中的木屑。'),
('CNV', '路加福音', 42, 6, 43, '“因为好树不能结坏果子，坏树不能结好果子。'),
('CNV', '路加福音', 42, 6, 44, '凭着果子就可以认出树来。人不能从荆棘上采无花果，也不能从蒺藜里摘葡萄。'),
('CNV', '路加福音', 42, 6, 45, '良善的人从心中所存的良善发出良善，邪恶的人从心中所存的邪恶发出邪恶；因为心中所充满的，口里就说出来。'),
('CNV', '路加福音', 42, 6, 46, '“你们为什么称呼我‘主啊！主啊！’却不遵行我的吩咐呢？'),
('CNV', '路加福音', 42, 6, 47, '每一个到我跟前，听我的话并且去行的，我要指示你们他像什么人。'),
('CNV', '路加福音', 42, 6, 48, '他像一个人建造房屋，挖深了地，把根基建在磐石上。大水泛滥的时候，急流冲击那房屋，不能使它动摇，因为它建造得好。'),
('CNV', '路加福音', 42, 6, 49, '但那听见而不遵行的，就像人在地上建屋，没有根基，急流一冲，就立刻倒塌，毁坏得很厉害。”'),
('CNV', '路加福音', 42, 7, 1, '耶稣向群众讲完这一切话，就进了迦百农。'),
('CNV', '路加福音', 42, 7, 2, '有百夫长所重用的一个奴仆，病得快要死了。'),
('CNV', '路加福音', 42, 7, 3, '百夫长听见耶稣的事，就打发犹太人中几个长老到他那里，求他去医治他的奴仆。'),
('CNV', '路加福音', 42, 7, 4, '长老们就来见耶稣，恳切地求他说：“你给他行这事，是他配得的，'),
('CNV', '路加福音', 42, 7, 5, '因为他爱我们的人民，给我们建造会堂。”'),
('CNV', '路加福音', 42, 7, 6, '耶稣就和他们同去。离那家不远的时候，百夫长派几个朋友来说：“主啊，不必劳驾，因为你到舍下来，我实在不敢当，'),
('CNV', '路加福音', 42, 7, 7, '我也觉得没有资格去见你；只要你说一句话，我的仆人就必好了。'),
('CNV', '路加福音', 42, 7, 8, '因为我自己是在别人的权下，也有兵在我以下；我对这个说：‘去！’他就去；对另一个说：‘来！’他就来；对我的仆人说：‘作这个！’他就作。”'),
('CNV', '路加福音', 42, 7, 9, '耶稣听见这些话，就很惊奇，转身对跟随的众人说：“我告诉你们，这样的信心，我在以色列中从来没有见过。”'),
('CNV', '路加福音', 42, 7, 10, '奉派的人回到家里，见那奴仆已经好了。'),
('CNV', '路加福音', 42, 7, 11, '后来耶稣往拿因城去，与他同去的有门徒和一大群人。'),
('CNV', '路加福音', 42, 7, 12, '他走近城门的时候，有人把一个死人抬出来，是个独生子，他母亲又是个寡妇。城里有一大群人陪着她。'),
('CNV', '路加福音', 42, 7, 13, '主看见了，就怜悯她，对她说：“不要哭！”'),
('CNV', '路加福音', 42, 7, 14, '于是上前按着杠子，抬的人就站住。他说：“青年人，我吩咐你起来！”'),
('CNV', '路加福音', 42, 7, 15, '那死人就坐起来，开口说话，耶稣就把他交给他母亲。'),
('CNV', '路加福音', 42, 7, 16, '众人都惊惧，颂赞神说：“有伟大的先知在我们中间兴起来了！”又说：“神眷顾他的子民了！”'),
('CNV', '路加福音', 42, 7, 17, '于是这话传遍了犹太和周围各地。'),
('CNV', '路加福音', 42, 7, 18, '约翰的门徒把这一切事告诉约翰。他就叫了两个门徒，'),
('CNV', '路加福音', 42, 7, 19, '差他们往主那里去，说：“你就是那位要来的，还是我们要等别人呢？”'),
('CNV', '路加福音', 42, 7, 20, '两人来到耶稣跟前，说：“施洗的约翰差我们来问你：‘你就是那位要来的，还是我们要等别人呢？’”'),
('CNV', '路加福音', 42, 7, 21, '就在那时候，耶稣治好许多患疾病的、遭灾难的、身上有污鬼附着的，并且施恩给瞎眼的，使他们看见。'),
('CNV', '路加福音', 42, 7, 22, '耶稣回答他们：“你们回去，把看见和听见的都告诉约翰，就是瞎的可以看见，跛的可以走路，患痲风的得到洁净，聋的可以听见，死人复活，穷人有福音听。'),
('CNV', '路加福音', 42, 7, 23, '那不被我绊倒的，就有福了。”'),
('CNV', '路加福音', 42, 7, 24, '约翰差来的人走了以后，耶稣对群众讲起约翰来，说：“你们到旷野去，是要看什么？被风吹动的芦苇吗？'),
('CNV', '路加福音', 42, 7, 25, '你们出去到底要看什么？身穿华丽衣服的人吗？这些衣服华丽，生活奢侈的人，是在王宫里的。'),
('CNV', '路加福音', 42, 7, 26, '那么，你们出去要看什么？先知吗？我告诉你们，是的。他比先知重要得多了。'),
('CNV', '路加福音', 42, 7, 27, '圣经所记：‘看哪，我差遣我的使者在你面前，他必在你前头预备你的道路’，这句话是指着他说的。'),
('CNV', '路加福音', 42, 7, 28, '我告诉你们，妇人所生的，没有一个比约翰更大，然而在神的国里最小的比他还大。”'),
('CNV', '路加福音', 42, 7, 29, '众人和税吏受过约翰的洗礼，听见这话，就称神为义。'),
('CNV', '路加福音', 42, 7, 30, '但法利赛人和律法师，未受过约翰的洗礼，就拒绝神对他们的美意。'),
('CNV', '路加福音', 42, 7, 31, '耶稣又说：“我要把这世代的人比作什么呢？他们好像什么呢？'),
('CNV', '路加福音', 42, 7, 32, '他们好像小孩子坐在市中心，彼此呼叫，说：‘我们给你们吹笛子，你们却不跳舞；我们唱哀歌，你们也不啼哭。’'),
('CNV', '路加福音', 42, 7, 33, '因为施洗的约翰来了，不吃饭，不喝酒，你们说他是鬼附的。'),
('CNV', '路加福音', 42, 7, 34, '人子来了，又吃又喝，你们说：‘你看，这人贪食好酒，与税吏和罪人为友。’'),
('CNV', '路加福音', 42, 7, 35, '但神的智慧，藉着他的儿女就证实是公义的了。”'),
('CNV', '路加福音', 42, 7, 36, '有一个法利赛人，请耶稣同他吃饭，他就到法利赛人家去赴席。'),
('CNV', '路加福音', 42, 7, 37, '那城里有一个女人，是个罪人，她知道耶稣在法利赛人家里吃饭，就拿着一玉瓶香膏，'),
('CNV', '路加福音', 42, 7, 38, '站在耶稣背后，挨近他的脚哭，她开始用泪水沾湿他的脚，然后用自己的头发擦干，又不住地吻他的脚，并且抹上香膏。'),
('CNV', '路加福音', 42, 7, 39, '请他的法利赛人看见了，心里说：“这人若是先知，必定知道摸他的是谁，是怎样的女人，因为她是个罪人！”'),
('CNV', '路加福音', 42, 7, 40, '耶稣对他说：“西门，我有句话要对你说。”他说：“老师，请说。”'),
('CNV', '路加福音', 42, 7, 41, '耶稣说：“一个债主有两个债户，一个欠五百银币，一个欠五十。'),
('CNV', '路加福音', 42, 7, 42, '他们都无力偿还，债主就把两人豁免了。他们之中哪一个更爱他呢？”'),
('CNV', '路加福音', 42, 7, 43, '西门回答：“我想是那个多得恩免的。”耶稣说：“你判断对了。”'),
('CNV', '路加福音', 42, 7, 44, '于是转身向着那女人，对西门说：“你看见这女人吗？我进了你的家，你没有给我水洗脚，但这女人用眼泪湿了我的脚，用头发擦干。'),
('CNV', '路加福音', 42, 7, 45, '你没有和我亲吻；但这女人，自从我进来，就不住地亲我的脚。'),
('CNV', '路加福音', 42, 7, 46, '你没有用油抹我的头；但这女人用香膏抹我的脚。'),
('CNV', '路加福音', 42, 7, 47, '所以我告诉你，她许多罪都蒙赦免了，因为她的爱多；那赦免少的，爱就少。”'),
('CNV', '路加福音', 42, 7, 48, '耶稣就对她说：“你的罪赦免了。”'),
('CNV', '路加福音', 42, 7, 49, '跟他一起吃饭的人心里说：“这是谁，竟然赦罪呢？”'),
('CNV', '路加福音', 42, 7, 50, '耶稣对那女人说：“你的信救了你，平安地去吧！”'),
('CNV', '路加福音', 42, 8, 1, '不久，耶稣周游各城各村讲道，宣扬神的国的福音，和他在一起的有十二个门徒，'),
('CNV', '路加福音', 42, 8, 2, '还有几个蒙了医治、脱离污鬼与疾病的妇女，其中有称为抹大拉的马利亚，曾有七个鬼从她身上赶出来；'),
('CNV', '路加福音', 42, 8, 3, '有希律的管家古撒的妻子约亚拿，又有苏珊娜，和许多别的妇女，她们都用自己的财物供给耶稣和门徒。'),
('CNV', '路加福音', 42, 8, 4, '当时有许多人聚在一起，还有人从各城来到耶稣那里，他就用比喻说：'),
('CNV', '路加福音', 42, 8, 5, '“有一个撒种的出去撒种，撒的时候，有的落在路旁，被人践踏，或给空中的小鸟吃掉。'),
('CNV', '路加福音', 42, 8, 6, '有的落在石头地上，一长出来就枯萎了，因为得不着滋润。'),
('CNV', '路加福音', 42, 8, 7, '有的落在荆棘丛中，荆棘也一齐生长，把它挤住了。'),
('CNV', '路加福音', 42, 8, 8, '有的落在好土里，就生长起来，结出百倍的果实。”他说了这些话，就大声说：“有耳可听的，就应当听！”'),
('CNV', '路加福音', 42, 8, 9, '门徒问他这比喻是什么意思。'),
('CNV', '路加福音', 42, 8, 10, '他说：“神的国的奥秘，只给你们知道，对别人就用比喻，叫他们看却看不见，听却听不明白。'),
('CNV', '路加福音', 42, 8, 11, '“这比喻是说，种子是神的道，'),
('CNV', '路加福音', 42, 8, 12, '那落在路旁的，就是人听了，魔鬼随即来到，从他们心里把道夺去，恐怕他们相信就得救了。'),
('CNV', '路加福音', 42, 8, 13, '那落在石头地上的，就是人听了，欢欢喜喜地接受，但是没有根，不过是暂时相信，一旦遭遇试炼，就倒退了。'),
('CNV', '路加福音', 42, 8, 14, '那落在荆棘里的，就是人听了，走开以后，被今世的忧虑、财富和宴乐挤住了，结不出成熟的子粒来。'),
('CNV', '路加福音', 42, 8, 15, '但那落在好土里的，就是人用诚实良善的心来听，把道持守住，忍耐着结出果实。'),
('CNV', '路加福音', 42, 8, 16, '“没有人点灯用器皿盖上，或放在床底下，而是放在灯台上，叫进来的人都看得见光。'),
('CNV', '路加福音', 42, 8, 17, '因为没有什么隐藏的事不被显明，也没有什么掩盖的事不被人知道而暴露出来。'),
('CNV', '路加福音', 42, 8, 18, '所以你们应当留心怎样听，因为凡是有的，还要给他；凡是没有的，连他自以为有的，也要拿去。”'),
('CNV', '路加福音', 42, 8, 19, '耶稣的母亲和弟弟来到他那里，因为人多，不能到他跟前。'),
('CNV', '路加福音', 42, 8, 20, '有人转告耶稣：“你母亲和弟弟站在外面要见你。”'),
('CNV', '路加福音', 42, 8, 21, '他回答他们：“听了神的道而遵行的人，才是我的母亲，我的弟兄。”'),
('CNV', '路加福音', 42, 8, 22, '有一天，耶稣和门徒上了船，他对他们说：“我们渡到海那边去吧。”他们就开了船。'),
('CNV', '路加福音', 42, 8, 23, '船行的时候，他睡着了。海上忽然起了狂风，他们全身湿透，非常危险。'),
('CNV', '路加福音', 42, 8, 24, '门徒来叫醒耶稣，说：“主啊！主啊！我们没命了！”他醒过来，斥责风浪，风浪就止息、平静了。'),
('CNV', '路加福音', 42, 8, 25, '耶稣对他们说：“你们的信心在哪里？”他们又惧怕、又希奇，彼此说：“这到底是谁？他吩咐风浪，连风浪也听从他。”'),
('CNV', '路加福音', 42, 8, 26, '船到了格拉森人的地区，正在加利利对面，'),
('CNV', '路加福音', 42, 8, 27, '耶稣一上岸，就有城里一个被鬼附着的人，迎面而来。这人已经很久不穿衣服，不住在家里，只住在坟墓里。'),
('CNV', '路加福音', 42, 8, 28, '他一见耶稣，就俯伏喊叫，大声说：“至高神的儿子耶稣，我跟你有什么关系呢？求你不要使我受苦。”'),
('CNV', '路加福音', 42, 8, 29, '因为耶稣已经吩咐这污灵从那人身上出来。原来这污灵屡次抓住那人；那人被铁链和脚链捆锁，而且有人看管，他竟挣断锁链，被鬼赶入旷野。'),
('CNV', '路加福音', 42, 8, 30, '耶稣问他：“你叫什么名字？”他说：“群。”因为进到那人里面的鬼很多。'),
('CNV', '路加福音', 42, 8, 31, '他们求耶稣，不要赶他们进入无底坑。'),
('CNV', '路加福音', 42, 8, 32, '那里有一大群猪正在山上吃东西。他们求耶稣准他们进入猪群。耶稣准许了，'),
('CNV', '路加福音', 42, 8, 33, '鬼就从那人身上出来，进入猪群，猪群闯下山崖，掉在海里淹死了。'),
('CNV', '路加福音', 42, 8, 34, '放猪的看见所发生的事就逃跑，到城里和各乡村把这事传开。'),
('CNV', '路加福音', 42, 8, 35, '众人就出来看发生了什么事。来到耶稣那里，看见鬼已经离开的那人，穿着衣服，神志清醒，坐在耶稣脚前，他们就害怕。'),
('CNV', '路加福音', 42, 8, 36, '当时看见的人，把被鬼附过的人怎样得到医治，说给他们听。'),
('CNV', '路加福音', 42, 8, 37, '格拉森一带的人，都要求耶稣离开他们，因为他们大大惧怕。他就上船回去了。'),
('CNV', '路加福音', 42, 8, 38, '鬼已经离开的那人求耶稣，要跟他在一起；但耶稣打发他回去，说：'),
('CNV', '路加福音', 42, 8, 39, '“你回家去，述说神为你作了怎样的事。”他就走遍全城，传讲耶稣为他作了怎样的事。'),
('CNV', '路加福音', 42, 8, 40, '耶稣回来的时候，众人欢迎他，因为大家都在等着他。'),
('CNV', '路加福音', 42, 8, 41, '那时，有一个人来了，名叫叶鲁，他是一位会堂主管。他俯伏在耶稣脚前，求他往他家里去，'),
('CNV', '路加福音', 42, 8, 42, '因为他的独生女，约十二岁，快要死了。耶稣去的时候，群众拥挤着他。'),
('CNV', '路加福音', 42, 8, 43, '有一个女人，患了十二年的血漏病，在医生手里花尽了全部养生的（有些抄本无“在医生手里花尽了全部养生的”一句），没有一个能医好她。'),
('CNV', '路加福音', 42, 8, 44, '她从后面挤来，一摸耶稣的衣裳繸子，血就立刻止住。'),
('CNV', '路加福音', 42, 8, 45, '耶稣说：“摸我的是谁？”众人都不承认。彼得说：“主啊，众人都拥挤着你。”'),
('CNV', '路加福音', 42, 8, 46, '耶稣说：“必定有人摸我，因为我觉得有能力从我身上出去。”'),
('CNV', '路加福音', 42, 8, 47, '那女人见不能隐瞒，就战战兢兢地过来，向他俯伏，把摸他的缘故，和怎样立刻得到医治，在众人面前说出来。'),
('CNV', '路加福音', 42, 8, 48, '耶稣对她说：“女儿，你的信使你痊愈了，平安地去吧！”'),
('CNV', '路加福音', 42, 8, 49, '耶稣还在说话的时候，有人从会堂主管家里来，说：“你的女儿死了，不必再劳动老师了。”'),
('CNV', '路加福音', 42, 8, 50, '耶稣听见就对他说：“不要怕，只要信，她必得痊愈。”'),
('CNV', '路加福音', 42, 8, 51, '到了那家，除了彼得、约翰、雅各和女孩的父母以外，他不准任何人同他进屋里去。'),
('CNV', '路加福音', 42, 8, 52, '众人都在为女孩痛哭哀号，他说：“不要哭！她不是死了，而是睡着了。”'),
('CNV', '路加福音', 42, 8, 53, '他们明知女孩已经死了，就嘲笑他。'),
('CNV', '路加福音', 42, 8, 54, '他进去拉着女孩的手，叫她说：“孩子，起来！”'),
('CNV', '路加福音', 42, 8, 55, '她的灵魂回来了，她就立刻起来。耶稣吩咐给她东西吃。'),
('CNV', '路加福音', 42, 8, 56, '她父母非常惊奇。耶稣嘱咐他们不要把他所作的事告诉人。'),
('CNV', '路加福音', 42, 9, 1, '耶稣召齐十二门徒，给他们能力、权柄，制伏一切鬼魔，医治各样的疾病，'),
('CNV', '路加福音', 42, 9, 2, '差遣他们去宣讲神的国和医治病人，'),
('CNV', '路加福音', 42, 9, 3, '对他们说：“不要带着什么上路，不要带手杖，不要带口袋，不要带食物，不要带银钱，也不要带两件衣服。'),
('CNV', '路加福音', 42, 9, 4, '无论进哪一家，就住在那里，直到离开。'),
('CNV', '路加福音', 42, 9, 5, '凡不接待你们的，你们离开那城的时候，当把脚上的灰尘跺下去，作为反对他们的表示。”'),
('CNV', '路加福音', 42, 9, 6, '于是他们就出去，走遍各乡，传讲福音，到处医治病人。'),
('CNV', '路加福音', 42, 9, 7, '分封王希律听见所发生的一切事，犹豫不定，因为有人说：“约翰从死人中复活了。”'),
('CNV', '路加福音', 42, 9, 8, '又有人说：“以利亚显现了。”还有人说：“古时的一位先知复活了。”'),
('CNV', '路加福音', 42, 9, 9, '希律说：“约翰已经斩头了，但这是谁，我怎么会听到他这些事呢？”就设法要见他。'),
('CNV', '路加福音', 42, 9, 10, '使徒们回来，把所作的事报告耶稣。他带着他们，悄悄地退往伯赛大城去。'),
('CNV', '路加福音', 42, 9, 11, '群众知道了，也跟了去。他接待他们，向他们讲论神的国，医好需要医治的人。'),
('CNV', '路加福音', 42, 9, 12, '天将晚的时候，十二门徒来到他跟前，说：“请解散众人，好让他们往周围的田舍村庄，去找地方住，找东西吃，因为我们这里是旷野。”'),
('CNV', '路加福音', 42, 9, 13, '他说：“你们给他们吃吧！”他们说：“我们所有的，不过是五个饼两条鱼，除非去为这些人另买食物。”'),
('CNV', '路加福音', 42, 9, 14, '原来男人就约有五千。他对门徒说：“叫他们一组一组地坐下，每组约五十人。”'),
('CNV', '路加福音', 42, 9, 15, '门徒就照他的话，叫众人坐下。'),
('CNV', '路加福音', 42, 9, 16, '耶稣拿起这五个饼，两条鱼，望着天，祝谢了，擘开递给门徒，摆在众人面前。'),
('CNV', '路加福音', 42, 9, 17, '他们都吃饱了，把剩下的零碎拾起来，装满了十二个篮子。'),
('CNV', '路加福音', 42, 9, 18, '有一次耶稣独自祈祷的时候，只有门徒和他在一起。他问他们：“人说我是谁？”'),
('CNV', '路加福音', 42, 9, 19, '他们回答：“有人说是施洗的约翰，有人说是以利亚，还有人说是古时的一位先知复活了。”'),
('CNV', '路加福音', 42, 9, 20, '他又问他们：“你们说我是谁？”彼得回答：“是神的基督！”'),
('CNV', '路加福音', 42, 9, 21, '耶稣警告他们，嘱咐他们，不要把这事告诉人。'),
('CNV', '路加福音', 42, 9, 22, '又说：“人子必须受许多苦，被长老、祭司长，和经学家弃绝、杀害，第三日复活。”'),
('CNV', '路加福音', 42, 9, 23, '耶稣又对众人说：“如果有人愿意跟从我，就当舍己，天天背起他的十字架来跟从我。'),
('CNV', '路加福音', 42, 9, 24, '凡是想救自己生命的，必丧掉生命；但为我牺牲自己生命的，必救了生命。'),
('CNV', '路加福音', 42, 9, 25, '人若赚得全世界，却丧失自己，或赔上自己，有什么好处呢？'),
('CNV', '路加福音', 42, 9, 26, '凡是把我和我的道当作可耻的，人子在自己与父并圣天使的荣耀里降临的时候，也必把他当作可耻的。'),
('CNV', '路加福音', 42, 9, 27, '我实在告诉你们，站在这里的，有人在没有尝过死味以前必定要看见神的国。”'),
('CNV', '路加福音', 42, 9, 28, '说了这些话以后约有八天，耶稣带着彼得、约翰和雅各，上山去祷告。'),
('CNV', '路加福音', 42, 9, 29, '正祷告的时候，他的面貌就改变了，衣服洁白发光。'),
('CNV', '路加福音', 42, 9, 30, '忽然有两个人和他谈话，就是摩西和以利亚。'),
('CNV', '路加福音', 42, 9, 31, '他们在荣光里显现，谈论他去世的事，就是他在耶路撒冷将要完成的。'),
('CNV', '路加福音', 42, 9, 32, '彼得和同伴都在打盹。醒过来之后，就看见他的荣光，并与他站在一起的那两个人。'),
('CNV', '路加福音', 42, 9, 33, '二人正要离开他的时候，彼得对耶稣说：“主啊，我们在这里真好！我们可以搭三个帐棚，一个为你，一个为摩西，一个为以利亚。”他根本不知道自己在说什么。'),
('CNV', '路加福音', 42, 9, 34, '他说这话的时候，有一片云彩笼罩他们，他们入了云彩，门徒就害怕起来。'),
('CNV', '路加福音', 42, 9, 35, '有声音从云彩里出来，说：“这是我的儿子，我所拣选的（“这是我的儿子，我所拣选的”有些抄本作“这是我的爱子”），你们要听从他！”'),
('CNV', '路加福音', 42, 9, 36, '声音过了，只见耶稣独自在那里。在那些日子，门徒保持缄默，不把所看见的告诉任何人。'),
('CNV', '路加福音', 42, 9, 37, '第二天，他们下了山，有一大群人迎面而来。'),
('CNV', '路加福音', 42, 9, 38, '在人群中有一个人喊叫说：“老师，求你怜悯我的儿子，因为他是我的独生子。'),
('CNV', '路加福音', 42, 9, 39, '你看，污灵一抓住他，他就忽然喊叫，并且抽疯，口吐白沫；污灵又折磨糟践他，不肯放过他。'),
('CNV', '路加福音', 42, 9, 40, '我求过你的门徒，把他赶出去，他们却办不到。”'),
('CNV', '路加福音', 42, 9, 41, '耶稣说：“唉！这不信又乖谬的世代啊！我跟你们在一起，忍受你们，要到几时呢？把你儿子带到这里来吧！”'),
('CNV', '路加福音', 42, 9, 42, '那孩子正走过来的时候，污鬼把他摔倒，使他重重地抽疯。耶稣斥责那污灵，把孩子医好，交给他父亲。'),
('CNV', '路加福音', 42, 9, 43, '众人都惊奇神的大能。众人还在希奇耶稣所作的这一切时，他对门徒说：'),
('CNV', '路加福音', 42, 9, 44, '“你们要把这些话存在心里：人子将要被交在人的手里。”'),
('CNV', '路加福音', 42, 9, 45, '门徒不明白这话，因为这话的意思是隐藏的，不让他们明白，他们也不敢问。'),
('CNV', '路加福音', 42, 9, 46, '后来，门徒起了意见，争论谁是最大的。'),
('CNV', '路加福音', 42, 9, 47, '耶稣看出他们的心意，就领了一个小孩子来，叫他站在自己旁边，'),
('CNV', '路加福音', 42, 9, 48, '对他们说：“凡因我的名接待这小孩子的，就是接待我；凡接待我的，就是接待那差我来的。谁是你们中间最小的，那人就是最大的。”'),
('CNV', '路加福音', 42, 9, 49, '约翰说：“主，我们看见有一个人奉你的名赶鬼，就禁止他，因为他不和我们一起跟从你。”'),
('CNV', '路加福音', 42, 9, 50, '耶稣说：“不要禁止他，因为不反对你们的，就是赞成你们的。”'),
('CNV', '路加福音', 42, 9, 51, '耶稣被接上升的日子快到了，他就决意向耶路撒冷去，'),
('CNV', '路加福音', 42, 9, 52, '并且差遣使者走在前头；他们去了，进入撒玛利亚的一个村庄，要为他预备。'),
('CNV', '路加福音', 42, 9, 53, '那里的人不接待他，因为他面向着耶路撒冷走。'),
('CNV', '路加福音', 42, 9, 54, '他的门徒雅各、约翰看见了，就说：“主啊，你要我们吩咐火从天降下来，烧灭他们吗？”'),
('CNV', '路加福音', 42, 9, 55, '耶稣就转过身来，责备他们，'),
('CNV', '路加福音', 42, 9, 56, '然后他们就往别的村庄去了。'),
('CNV', '路加福音', 42, 9, 57, '他们走路的时候，有一个人对他说：“你无论往哪里去，我都要跟从你！”'),
('CNV', '路加福音', 42, 9, 58, '耶稣说：“狐狸有洞，天空的飞鸟有窝，人子却没有栖身的地方。”'),
('CNV', '路加福音', 42, 9, 59, '他对另一个人说：“你跟从我吧！”那人说：“主啊，请准我先回去安葬我的父亲吧。”'),
('CNV', '路加福音', 42, 9, 60, '耶稣说：“让死人去埋葬他们的死人，你应该去传扬神的国。”'),
('CNV', '路加福音', 42, 9, 61, '又有一个人说：“主，我要跟从你，但容我先回去，向家人道别。”'),
('CNV', '路加福音', 42, 9, 62, '耶稣说：“手扶着犁向后看的，不适合进神的国。”'),
('CNV', '路加福音', 42, 10, 1, '这些事以后，主又另外指派了七十二个人（“七十二个人”有些抄本作“七十个人”），差遣他们两个两个地，在他前面，到他自己将要到的各城各地去。'),
('CNV', '路加福音', 42, 10, 2, '耶稣对他们说：“庄稼多，工人少，所以你们应当求庄稼的主，派工人出去收他的庄稼。'),
('CNV', '路加福音', 42, 10, 3, '你们去吧！我差你们去，如同羊羔进入狼群。'),
('CNV', '路加福音', 42, 10, 4, '不要带钱囊，不要带口袋，不要带鞋，不要在路上问候人。'),
('CNV', '路加福音', 42, 10, 5, '无论进哪一家，先说：‘愿平安归与这家！’'),
('CNV', '路加福音', 42, 10, 6, '那里若有配得平安的人（“配得平安的人”原文作“平安之子”），你们的平安就必临到他，不然，就归给你们。'),
('CNV', '路加福音', 42, 10, 7, '你们要住在那家，吃喝他们所供给的，因为作工的理当得工资；不必从这家搬到那家。'),
('CNV', '路加福音', 42, 10, 8, '无论进哪一城，人若接待你们，摆上什么，就吃什么。'),
('CNV', '路加福音', 42, 10, 9, '要医治城中的病人，对他们宣讲：‘神的国临近你们了。’'),
('CNV', '路加福音', 42, 10, 10, '无论进哪一城，人若不接待你们，你们就出来到街上，说：'),
('CNV', '路加福音', 42, 10, 11, '‘连你们城里那黏在我们脚上的尘土，我们也要当着你们擦去。虽然这样，你们应该知道：神的国临近了！’'),
('CNV', '路加福音', 42, 10, 12, '我告诉你们，当那日，所多玛所受的，比那城所受的还轻呢。'),
('CNV', '路加福音', 42, 10, 13, '“哥拉逊啊，你有祸了！伯赛大啊，你有祸了！因为在你们那里行过的神迹，如果行在推罗和西顿，他们早已披麻蒙灰，坐在地上悔改了。'),
('CNV', '路加福音', 42, 10, 14, '在审判的时候，推罗和西顿所受的，比你们所受的还轻呢。'),
('CNV', '路加福音', 42, 10, 15, '还有你，迦百农啊！你会被高举到天上吗？你必降到阴间。'),
('CNV', '路加福音', 42, 10, 16, '听从你们的，就是听从我；弃绝你们的，就是弃绝我；弃绝我的，就是弃绝那差我来的。”'),
('CNV', '路加福音', 42, 10, 17, '那七十二个人欢欢喜喜地回来，说：“主啊，因你的名，连鬼也服了我们。”'),
('CNV', '路加福音', 42, 10, 18, '耶稣说：“我看见撒但，像闪电一样从天坠落。'),
('CNV', '路加福音', 42, 10, 19, '我已经给你们权柄，去践踏蛇和蝎子，胜过仇敌的一切能力。绝对没有什么能伤害你们了。'),
('CNV', '路加福音', 42, 10, 20, '然而不要因为鬼服了你们就欢喜，却要因为你们的名字记录在天上而欢喜。”'),
('CNV', '路加福音', 42, 10, 21, '就在这时候，耶稣因圣灵而欢乐，说：“父啊，天地的主，我赞美你，因为你把这些事向智慧和聪明的人隐藏起来，却向婴孩显明。父啊，是的，这就是你的美意。'),
('CNV', '路加福音', 42, 10, 22, '我父已经把一切交给我；除了父没有人知道子是谁，除了子和子所愿意启示的人，也没有人知道父是谁。”'),
('CNV', '路加福音', 42, 10, 23, '耶稣转过身来，悄悄地对门徒说：“看见你们所看见的，那眼睛有福了！'),
('CNV', '路加福音', 42, 10, 24, '我告诉你们，曾经有许多先知和君王，想看你们所看见的，却没有看到；想听你们所听见的，却没有听到。”'),
('CNV', '路加福音', 42, 10, 25, '有一个律法师起来试探耶稣，说：“老师，我应该作什么，才可以承受永生呢？”'),
('CNV', '路加福音', 42, 10, 26, '耶稣对他说：“律法上写的是什么？你怎么念的呢？”'),
('CNV', '路加福音', 42, 10, 27, '他回答：“你要全心、全性、全力、全意爱主你的神，并且要爱邻舍如同自己。”'),
('CNV', '路加福音', 42, 10, 28, '耶稣说：“你答得对，你这样行，就必得生命。”'),
('CNV', '路加福音', 42, 10, 29, '那人想证明自己有理，就对耶稣说：“谁是我的邻舍呢？”'),
('CNV', '路加福音', 42, 10, 30, '耶稣回答：“有一个人从耶路撒冷下耶利哥去，落在强盗手中。他们剥去他的衣服，把他打得半死，撇下他一个人就走了。'),
('CNV', '路加福音', 42, 10, 31, '正好有一个祭司，从那条路下来，看见他，就从旁边走过去了。'),
('CNV', '路加福音', 42, 10, 32, '又有一个利未人，来到那里，看见他，也照样从旁边走过去了。'),
('CNV', '路加福音', 42, 10, 33, '只有一个撒玛利亚人，旅行来到他那里，看见了，就动了怜悯的心，'),
('CNV', '路加福音', 42, 10, 34, '上前用油和酒倒在他的伤处，包裹好了，把他扶上自己的牲口，带他到客店里照顾他。'),
('CNV', '路加福音', 42, 10, 35, '第二天，他拿出两个银币交给店主，说：‘请你照顾他，额外的开支，我回来的时候必还给你。’'),
('CNV', '路加福音', 42, 10, 36, '你想，这三个人，谁是那个落在强盗手中的人的邻舍呢？”'),
('CNV', '路加福音', 42, 10, 37, '他说：“是那怜悯他的。”耶稣说：“你去，照样作吧。”'),
('CNV', '路加福音', 42, 10, 38, '他们走路的时候，耶稣进了一个村庄。有一个名叫马大的女人，接他到家里。'),
('CNV', '路加福音', 42, 10, 39, '她有一个妹妹，名叫马利亚，坐在主的脚前听道。'),
('CNV', '路加福音', 42, 10, 40, '马大被许多要作的事，弄得心烦意乱，就上前来，说：“主啊，我妹妹让我一个人侍候，你不理吗？请吩咐她来帮助我。”'),
('CNV', '路加福音', 42, 10, 41, '主回答她：“马大，马大，你为许多事操心忙碌，'),
('CNV', '路加福音', 42, 10, 42, '但是最需要的只有一件，马利亚已经选择了那上好的分，是不能从她夺去的。”'),
('CNV', '路加福音', 42, 11, 1, '有一天，耶稣在一个地方祈祷，祈祷完了，有一个门徒对他说：“主啊，求你教导我们祷告，像约翰教导他的门徒一样。”'),
('CNV', '路加福音', 42, 11, 2, '耶稣说：“你们祷告的时候，要说：‘父啊，愿你的名被尊为圣，愿你的国降临（有些抄本在此有“愿你的旨意行在地上，如同行在天上”一句）；'),
('CNV', '路加福音', 42, 11, 3, '我们需用的食物，求你每天赐给我们；'),
('CNV', '路加福音', 42, 11, 4, '赦免我们的罪，因为我们也饶恕所有亏负我们的人；不要让我们陷入试探（有些抄本在此有“救我们脱离那恶者”一句）。’”'),
('CNV', '路加福音', 42, 11, 5, '耶稣又对他们说：“你们当中，谁有朋友半夜去找他，说：‘请你借给我三个饼，'),
('CNV', '路加福音', 42, 11, 6, '因为我有一个朋友旅行来到我这里，我没有什么可以招待他。’'),
('CNV', '路加福音', 42, 11, 7, '而他却在里面回答：‘不要麻烦我，门已经关好了，孩子也跟我在床上了，我不能起来拿给你。’'),
('CNV', '路加福音', 42, 11, 8, '我告诉你们，即使不因为他是朋友而起来给他，也会因为他厚颜地直求，而起来照他所需要的给他。'),
('CNV', '路加福音', 42, 11, 9, '我又告诉你们，你们祈求，就给你们；寻找，就寻见；叩门，就给你们开门。'),
('CNV', '路加福音', 42, 11, 10, '因为所有祈求的就得着，寻找的就寻见，叩门的就给他开门。'),
('CNV', '路加福音', 42, 11, 11, '你们中间作父亲的，哪有儿子求鱼（较后期的抄本多数作“儿子要饼，却给他石头呢？”），反拿蛇当作鱼给他呢？'),
('CNV', '路加福音', 42, 11, 12, '或求鸡蛋，反给他蝎子呢？'),
('CNV', '路加福音', 42, 11, 13, '你们虽然不好，尚且知道把好东西给自己的儿女，何况天父，岂不更把圣灵赐给求他的人吗？”'),
('CNV', '路加福音', 42, 11, 14, '耶稣赶出一个哑巴鬼，鬼既出去，哑巴就说起话来，众人都希奇。'),
('CNV', '路加福音', 42, 11, 15, '有人说：“他靠鬼王别西卜赶鬼。”'),
('CNV', '路加福音', 42, 11, 16, '又有人试探他，向他求一个从天上来的神迹。'),
('CNV', '路加福音', 42, 11, 17, '耶稣知道他们的心意，就对他们说：“如果一个国家自相纷争，就必定荒凉；如果一个家庭自相为敌，就必然败落。'),
('CNV', '路加福音', 42, 11, 18, '如果撒但自相纷争，他的国怎能站立得住呢？你们说我靠别西卜赶鬼，'),
('CNV', '路加福音', 42, 11, 19, '我若靠别西卜赶鬼，你们的子孙赶鬼又靠谁呢？因此，他们必要作你们的审判官。'),
('CNV', '路加福音', 42, 11, 20, '我若靠神的能力赶鬼，这就是神的国临到你们了。'),
('CNV', '路加福音', 42, 11, 21, '一个壮汉拿着武器，看守自己的家园，他的家财就平安无事。'),
('CNV', '路加福音', 42, 11, 22, '但是一个比他更强的人来了，胜过了他，夺去他所倚靠的武器，就把他的家财当作掠物分了。'),
('CNV', '路加福音', 42, 11, 23, '不站在我这一边的就是反对我的；不跟从一起收聚的就是分散的。'),
('CNV', '路加福音', 42, 11, 24, '“一个污灵离开了一个人，走遍干旱之地，寻找栖身的地方，却没有找到，就说：‘我要回到我从前离开了的那房子。’'),
('CNV', '路加福音', 42, 11, 25, '到了之后，看见里面已经打扫干净，粉饰好了，'),
('CNV', '路加福音', 42, 11, 26, '他就去带了另外七个比自己更恶的污灵来，进去住在那里；那人后来的情况，比以前更坏了。”'),
('CNV', '路加福音', 42, 11, 27, '耶稣正说这些话的时候，群众中有一个女人高声对他说：“怀你胎的和哺养你的有福了！”'),
('CNV', '路加福音', 42, 11, 28, '他说：“是的，却还不如听神的道而遵守的人有福。”'),
('CNV', '路加福音', 42, 11, 29, '众人聚集的时候，耶稣就说：“这世代是个邪恶的世代。这世代寻求神迹，可是除了约拿的神迹以外，再没有神迹给他们了。'),
('CNV', '路加福音', 42, 11, 30, '约拿怎样成了尼尼微人的神迹，人子也照样成为这个世代的神迹。'),
('CNV', '路加福音', 42, 11, 31, '审判的时候，南方的女王要和这世代的人一同起来，她要定他们的罪，因为她从地极来到，要听所罗门智慧的话。你看，这里有一位是比所罗门更大的。'),
('CNV', '路加福音', 42, 11, 32, '审判的时候，尼尼微人要和这世代的人一同起来，他们要定这个世代的罪，因为尼尼微人听了约拿所传的就悔改了。你看，这里有一位是比约拿更大的。'),
('CNV', '路加福音', 42, 11, 33, '“没有人点了灯，把它放在地窖里，或量器底下，却放在灯台上，叫进来的人看得见光。'),
('CNV', '路加福音', 42, 11, 34, '你的眼睛就是你身体的灯，你的眼睛健全，全身就明亮；如果不健全，全身就黑暗。'),
('CNV', '路加福音', 42, 11, 35, '所以要谨慎，免得你里面的光黑暗了。'),
('CNV', '路加福音', 42, 11, 36, '你若全身明亮，没有一点黑暗，你就完全明亮，好像明亮的灯光照你一样。”'),
('CNV', '路加福音', 42, 11, 37, '耶稣说话的时候，有一个法利赛人请耶稣和他一起吃饭；他就进去坐席。'),
('CNV', '路加福音', 42, 11, 38, '这个法利赛人见耶稣吃饭之前不洗手，觉得奇怪。'),
('CNV', '路加福音', 42, 11, 39, '主对他说：“你们法利赛人把杯盘的外面洗净，但你们里面却充满了抢夺和邪恶。'),
('CNV', '路加福音', 42, 11, 40, '无知的人哪，那造外面的，不也造里面吗？'),
('CNV', '路加福音', 42, 11, 41, '只要把里面的施舍出去，你们的一切就都洁净了。'),
('CNV', '路加福音', 42, 11, 42, '然而你们法利赛人有祸了！因为你们把薄荷、茴香和各样菜蔬献上十分之一，却把公义和爱神的事疏忽了；这些是你们应当作的，但其他的也不可疏忽。'),
('CNV', '路加福音', 42, 11, 43, '你们法利赛人有祸了！因为你们喜爱会堂里的高位和人在巿中心的问安。'),
('CNV', '路加福音', 42, 11, 44, '你们有祸了！因为你们好像不显露的坟墓，走在上面的人并不知道。”'),
('CNV', '路加福音', 42, 11, 45, '律法师中有一个回答他：“老师，你这样说，把我们也侮辱了！”'),
('CNV', '路加福音', 42, 11, 46, '耶稣说：“你们律法师也有祸了，因为你们把难担的担子叫人担，自己连一个指头也不动。'),
('CNV', '路加福音', 42, 11, 47, '你们有祸了！因为你们修造先知的坟墓，而那些先知正是你们祖先所杀的，'),
('CNV', '路加福音', 42, 11, 48, '这样，你们就成了证人，对你们祖先的作为表示同意；他们杀害先知，你们修造先知的坟墓。'),
('CNV', '路加福音', 42, 11, 49, '所以，神的智慧说：‘我要差遣先知和使徒到他们那里去，有的他们要杀害，有的他们要迫害，'),
('CNV', '路加福音', 42, 11, 50, '为要使创世以来众先知所流的血，从亚伯的血起，直到在祭坛和圣所之间受害的撒迦利亚的血为止，都向这一代追讨。’是的，我告诉你们，都要向这一代追讨。'),
('CNV', '路加福音', 42, 11, 52, '你们律法师有祸了！因为你们拿去知识的钥匙，自己不进去，又阻止要进去的人。”'),
('CNV', '路加福音', 42, 11, 53, '耶稣从那里出来，经学家和法利赛人非常敌视他，质问他很多问题，'),
('CNV', '路加福音', 42, 11, 54, '等机会从他的口中找把柄。'),
('CNV', '路加福音', 42, 12, 1, '那时有成千上万的人聚在一起，甚至彼此践踏。耶稣就先对门徒说：“你们要提防法利赛人的酵，就是虚伪。'),
('CNV', '路加福音', 42, 12, 2, '没有什么掩盖的事不被揭露，也没有什么隐藏的事不被人知道。'),
('CNV', '路加福音', 42, 12, 3, '所以，你们在暗处所说的，必在明处被人听见；在内室附耳所谈的，必在房顶上宣扬出来。'),
('CNV', '路加福音', 42, 12, 4, '“我的朋友，我告诉你们，那杀身体以后不能再作什么的，不要怕他们。'),
('CNV', '路加福音', 42, 12, 5, '我要指示你们当怕的是谁：当怕那杀身体以后，有权把人投入地狱里的；我告诉你们，应当怕他。'),
('CNV', '路加福音', 42, 12, 6, '五只麻雀，不是卖两个大钱吗？但在神面前，一只也不被忘记。'),
('CNV', '路加福音', 42, 12, 7, '甚至你们的头发都一一数过了。不要怕，你们比许多麻雀贵重得多呢。'),
('CNV', '路加福音', 42, 12, 8, '“我告诉你们，凡在人面前承认我的，人子在神的使者面前也承认他；'),
('CNV', '路加福音', 42, 12, 9, '在人面前不认我的，我在神的使者面前也不认他。'),
('CNV', '路加福音', 42, 12, 10, '凡说话得罪人子的，还可以赦免；但亵渎圣灵的，必不得赦免。'),
('CNV', '路加福音', 42, 12, 11, '人把你们拉到会堂、官长和当权者的面前，你们不要思虑怎样申辩或说什么话。'),
('CNV', '路加福音', 42, 12, 12, '到了时候，圣灵必把当说的话教导你们。”'),
('CNV', '路加福音', 42, 12, 13, '群众中有一个人对耶稣说：“老师，请吩咐我的兄弟和我分家业。”'),
('CNV', '路加福音', 42, 12, 14, '耶稣说：“你这个人，谁立我作你们的审判官和分家业的人呢？”'),
('CNV', '路加福音', 42, 12, 15, '于是他对众人说：“你们要谨慎，远离一切贪心，因为人的生命并不在于家道丰富。”'),
('CNV', '路加福音', 42, 12, 16, '就对他们讲了一个比喻，说：“有一个富翁的田地丰收。'),
('CNV', '路加福音', 42, 12, 17, '他自己心里说：‘怎么办呢？因为我没有足够的地方收藏出产了！’'),
('CNV', '路加福音', 42, 12, 18, '又说：‘我要这样办：我要拆掉这些仓房，建造更大的，好在那里收藏我的一切粮食和货物。'),
('CNV', '路加福音', 42, 12, 19, '然后，我要对我的灵魂说：灵魂啊，你拥有许多好东西，足够多年享用，只管安安逸逸地吃喝快乐吧！’'),
('CNV', '路加福音', 42, 12, 20, '神却对他说：‘无知的人哪，今天晚上，你的灵魂必被取去，你所预备的要归给谁呢？’'),
('CNV', '路加福音', 42, 12, 21, '凡为自己积财，在神面前却不富足的，也是这样。”'),
('CNV', '路加福音', 42, 12, 22, '耶稣又对门徒说：“所以我告诉你们，不要为生命忧虑吃什么，也不要为身体忧虑穿什么。'),
('CNV', '路加福音', 42, 12, 23, '因为生命比饮食重要，身体比衣服重要。'),
('CNV', '路加福音', 42, 12, 24, '你们想想乌鸦：它们不种也不收，无仓又无库，神尚且养活它们；你们比飞鸟贵重得多了。'),
('CNV', '路加福音', 42, 12, 25, '你们中间谁能用忧虑使自己的寿命延长一刻呢？'),
('CNV', '路加福音', 42, 12, 26, '既然连这极小的事都不能作，为什么还忧虑其他的事呢？'),
('CNV', '路加福音', 42, 12, 27, '你们想想百合花，怎样不劳苦，也不纺织。但我告诉你们，就是所罗门最荣华的时候所穿的，也比不上这花中的一朵呢。'),
('CNV', '路加福音', 42, 12, 28, '小信的人哪，田野的草，今天还在，明天就投进炉里，神尚且这样给它装饰，何况你们呢？'),
('CNV', '路加福音', 42, 12, 29, '你们不要求吃什么，喝什么，也不要忧虑，'),
('CNV', '路加福音', 42, 12, 30, '因为这一切都是世上不信的人所寻求的。你们的父原知道你们需要这一切。'),
('CNV', '路加福音', 42, 12, 31, '你们只管求他的国，这些东西都必加给你们。'),
('CNV', '路加福音', 42, 12, 32, '你们这小群，不要怕，因为你们的父乐意把国赐给你们。'),
('CNV', '路加福音', 42, 12, 33, '当变卖你们所有的施舍给人，为自己制造不朽坏的钱囊，积蓄用不尽的财宝在天上，就是贼不能近、虫不能蛀的地方。'),
('CNV', '路加福音', 42, 12, 34, '因为你们的财宝在哪里，你们的心也在哪里。'),
('CNV', '路加福音', 42, 12, 35, '“你们的腰当束起来，灯也该点着，'),
('CNV', '路加福音', 42, 12, 36, '像等候自己的主人从婚筵回来一样，好叫你们在主人回来敲门时，立刻给他开门。'),
('CNV', '路加福音', 42, 12, 37, '主人来到了，看见仆人警醒，这些仆人就有福了。我实在告诉你们，主人必亲自束腰，招待他们吃饭，进前来侍候他们。'),
('CNV', '路加福音', 42, 12, 38, '主人也许半夜之前，或天亮之前回来，看见他们这样，这些仆人就有福了。'),
('CNV', '路加福音', 42, 12, 39, '你们都知道，家主若晓得窃贼什么时候来，就不会让他摸进屋里。'),
('CNV', '路加福音', 42, 12, 40, '你们也要准备妥当，因为在想不到的时候，人子就来了。”'),
('CNV', '路加福音', 42, 12, 41, '彼得说：“主啊，你说这比喻，是为我们还是为众人呢？”'),
('CNV', '路加福音', 42, 12, 42, '主说：“谁是那忠心精明的管家，被主人指派管理家里的仆人，按时分粮呢？'),
('CNV', '路加福音', 42, 12, 43, '主人来到的时候，看见他这样作，那仆人就有福了。'),
('CNV', '路加福音', 42, 12, 44, '我实在告诉你们，主人要指派他管理主人的一切财产。'),
('CNV', '路加福音', 42, 12, 45, '如果那仆人心里说：‘我的主人不会那么快回来’，就动手打其他的仆人使女，并且吃喝醉酒；'),
('CNV', '路加福音', 42, 12, 46, '在他想不到的日子、不知道的时间，那仆人的主人要来，严厉地处罚他，使他和不信的人同在一起。'),
('CNV', '路加福音', 42, 12, 47, '那仆人知道主人的意思，却不预备，也不照他的意思行，必多受责打；'),
('CNV', '路加福音', 42, 12, 48, '但那不知道的，虽然作了该受责打的事，也必少受责打。多给谁就向谁多取，多托谁就向谁多要。'),
('CNV', '路加福音', 42, 12, 49, '“我来要把火投在地上，如果烧了起来，那是我所愿意的。'),
('CNV', '路加福音', 42, 12, 50, '我有应当受的洗，我是多么迫切地期待这事完成。'),
('CNV', '路加福音', 42, 12, 51, '你们以为我来是要地上有和平吗？不是的，我告诉你们，是要有纷争。'),
('CNV', '路加福音', 42, 12, 52, '从今以后，一家五口将起纷争，三个反对两个，两个反对三个。'),
('CNV', '路加福音', 42, 12, 53, '他们将起纷争：父亲反对儿子，儿子反对父亲，母亲反对女儿，女儿反对母亲，婆婆反对媳妇，媳妇反对婆婆。”'),
('CNV', '路加福音', 42, 12, 54, '耶稣又对众人说：“你们一看见西边有云彩升起来，就说：‘要下大雨’，果然这样；'),
('CNV', '路加福音', 42, 12, 55, '起了南风，就说：‘天要热了’，也果然这样。'),
('CNV', '路加福音', 42, 12, 56, '伪君子啊！你们知道分辨天地的气象，怎么不知道分辨这个时代呢？'),
('CNV', '路加福音', 42, 12, 57, '“你们为什么自己不能判断什么是对的呢？'),
('CNV', '路加福音', 42, 12, 58, '你和你的对头去见官长，还在路上的时候，应当尽力向他求和，免得他把你拉到法官面前，法官把你交给差役，差役把你关在监里。'),
('CNV', '路加福音', 42, 12, 59, '我告诉你，除非你还清最后的一个小钱，否则决不能从那里出来。”'),
('CNV', '路加福音', 42, 13, 1, '就在那时候，有几个在那里的人，把加利利人的事告诉耶稣，就是彼拉多把他们的血和他们的祭物搀在一起的事。'),
('CNV', '路加福音', 42, 13, 2, '他回答：“你们以为这些加利利人比其他的加利利人更有罪，才这样受害吗？'),
('CNV', '路加福音', 42, 13, 3, '不是的，我告诉你们，你们若不悔改，都要这样灭亡。'),
('CNV', '路加福音', 42, 13, 4, '你们以为从前西罗亚楼倒塌的时候，压死的那十八个人，比一切在耶路撒冷的居民更有罪吗？'),
('CNV', '路加福音', 42, 13, 5, '不是的，我告诉你们，你们若不悔改，也都要这样灭亡。”'),
('CNV', '路加福音', 42, 13, 6, '耶稣讲了这样一个比喻：“有一个人把一棵无花果树栽在自己的葡萄园里。他来到树那里找果子，却找不到。'),
('CNV', '路加福音', 42, 13, 7, '他对管园的说：‘你看，这三年，我来到这棵无花果树那里找果子，却找不到，把它砍了吧！何必白占地土呢？’'),
('CNV', '路加福音', 42, 13, 8, '管园的说：‘主人，今年且留着它，等我把周围的泥土挖松，加上肥料；'),
('CNV', '路加福音', 42, 13, 9, '以后结果子就罢，不然，再把它砍了。’”'),
('CNV', '路加福音', 42, 13, 10, '安息日的时候，耶稣在会堂里教导人。'),
('CNV', '路加福音', 42, 13, 11, '有一个女人被邪灵附着，病了十八年，弯腰曲背，完全直不起来。'),
('CNV', '路加福音', 42, 13, 12, '耶稣看见了，就叫她过来，对她说：“妇人，你脱离这疾病了。”'),
('CNV', '路加福音', 42, 13, 13, '耶稣用双手按在她身上，她立刻直起腰来，颂赞神。'),
('CNV', '路加福音', 42, 13, 14, '会堂的主管，因为耶稣在安息日治病，就气忿忿地对群众说：“有六天是应当作工的，你们可以在这六天里来求医，但在安息日却不可以。”'),
('CNV', '路加福音', 42, 13, 15, '主说：“伪君子啊，你们哪一个人在安息日，不从槽那里解开牛、驴，牵去喝水呢？'),
('CNV', '路加福音', 42, 13, 16, '何况这个女人是亚伯拉罕的后裔，已经被撒但捆绑了十八年，不应当在安息日解开她的捆绑吗？”'),
('CNV', '路加福音', 42, 13, 17, '他说完了这些话，那些与他为敌的人都惭愧；群众却都因他所行一切荣耀的事欢喜。'),
('CNV', '路加福音', 42, 13, 18, '耶稣说：“神的国好像什么呢？我要把它比作什么呢？'),
('CNV', '路加福音', 42, 13, 19, '它好像一粒芥菜种，人拿去种在自己的园子里。它长大了，成为一棵树，甚至天空的飞鸟也在它的枝头搭窝。”'),
('CNV', '路加福音', 42, 13, 20, '他又说：“我要把神的国比作什么呢？'),
('CNV', '路加福音', 42, 13, 21, '它好像面酵，女人拿去放在三斗面里，直到全团发起来。”'),
('CNV', '路加福音', 42, 13, 22, '耶稣经过各城各乡，往耶路撒冷去，沿途教导人。'),
('CNV', '路加福音', 42, 13, 23, '有一个人问他：“主啊，是不是只有很少的人得救呢？”他对众人说：'),
('CNV', '路加福音', 42, 13, 24, '“你们应当竭力进窄门！我告诉你们，将来许多人要进去，却是不能。'),
('CNV', '路加福音', 42, 13, 25, '等到家主起来关上门，你们站在门外叩门说：‘主啊，给我们开门！’他要回答你们：‘我不知道你们是从哪里来的。’'),
('CNV', '路加福音', 42, 13, 26, '那时，你们要说：‘我们在你面前吃过喝过，你也在我们街上教导过人。’'),
('CNV', '路加福音', 42, 13, 27, '他要说：‘我告诉你们，我不晓得你们是从哪里来的；你们所有作恶的人，离开我去吧！’'),
('CNV', '路加福音', 42, 13, 28, '当你们看见亚伯拉罕、以撒、雅各和众先知都在神的国里的时候，你们却被赶到外面去，在那里必要哀哭切齿。'),
('CNV', '路加福音', 42, 13, 29, '从东从南，从西从北，将有人来，在神的国里吃饭。'),
('CNV', '路加福音', 42, 13, 30, '在后的将要在前，在前的将要在后。”'),
('CNV', '路加福音', 42, 13, 31, '就在那时候，有几个法利赛人来对耶稣说：“你离开这里走吧！因为希律想要杀你。”'),
('CNV', '路加福音', 42, 13, 32, '他说：“你们去告诉那个狐狸，今天明天我赶鬼医病，第三天我的事就完成了。'),
('CNV', '路加福音', 42, 13, 33, '然而，今天明天后天，我必须前行，因为先知不能在耶路撒冷以外丧命。'),
('CNV', '路加福音', 42, 13, 34, '耶路撒冷啊，耶路撒冷，你杀害先知，又用石头把奉派到你那里的人打死。我多次想招聚你的儿女，好像母鸡招聚小鸡到翅膀底下，只是你们不愿意。'),
('CNV', '路加福音', 42, 13, 35, '你看，你们的家必成为荒场留给你们。我告诉你们，从今以后，你们一定见不到我，直等到你们说：‘奉主名来的，是应当称颂的。’”'),
('CNV', '路加福音', 42, 14, 1, '在安息日，耶稣进了一个法利赛人领袖的家里吃饭，众人都在窥探他。'),
('CNV', '路加福音', 42, 14, 2, '正好在他面前有一个患水臌病的人；'),
('CNV', '路加福音', 42, 14, 3, '耶稣对律法师和法利赛人说：“在安息日治病，可以不可以呢？”'),
('CNV', '路加福音', 42, 14, 4, '他们却不出声。耶稣扶着病人，治好他，叫他走了，'),
('CNV', '路加福音', 42, 14, 5, '就对他们说：“你们中间谁的儿子或牛在安息日掉在井里，不立刻把他拉上来呢？”'),
('CNV', '路加福音', 42, 14, 6, '他们不能回答这些话。'),
('CNV', '路加福音', 42, 14, 7, '耶稣看见被邀请的客人选择高位，就用比喻对他们说：'),
('CNV', '路加福音', 42, 14, 8, '“你被邀请参加婚筵的时候，不要自己坐在高位上，恐怕有比你更尊贵的客人也被请来；'),
('CNV', '路加福音', 42, 14, 9, '那请你又请他的人过来对你说：‘请你让位给这个人。’那时你就惭愧地退居末位了。'),
('CNV', '路加福音', 42, 14, 10, '你被邀请的时候，要坐在末位上，等请你的人过来对你说：‘朋友，请上座。’那时你在同席的人面前才有光彩。'),
('CNV', '路加福音', 42, 14, 11, '因为凡高抬自己的，必要降卑；自己谦卑的，必要升高。”'),
('CNV', '路加福音', 42, 14, 12, '耶稣又对邀请他的人说：“你设午餐或晚宴，不要请你的朋友、弟兄、亲戚或富裕的邻舍，恐怕他们又回请你，你就得了报答。'),
('CNV', '路加福音', 42, 14, 13, '你摆筵席的时候，总要邀请那贫穷的、残废的、瘸腿的、瞎眼的，'),
('CNV', '路加福音', 42, 14, 14, '那你就有福了。因为他们没有什么可以报答你，义人复活的时候，你必定得着报答。”'),
('CNV', '路加福音', 42, 14, 15, '一起吃饭的人中有一个，听了这些话，就对耶稣说：“在神的国里吃饭的人有福了。”'),
('CNV', '路加福音', 42, 14, 16, '耶稣对他说：“有一个人大摆筵席，请了许多客人。'),
('CNV', '路加福音', 42, 14, 17, '到了开席的时候，他打发仆人去对所请的人说：‘请来吧！样样都准备好了。’'),
('CNV', '路加福音', 42, 14, 18, '众人一致推辞，头一个说：‘我买了一块地，不得不去看一看，请原谅我。’'),
('CNV', '路加福音', 42, 14, 19, '另一个说：‘我买了五对牛，要去试一试，请原谅我。’'),
('CNV', '路加福音', 42, 14, 20, '又一个说：‘我刚结了婚，不能去。’'),
('CNV', '路加福音', 42, 14, 21, '仆人回来把这些事告诉他主人，家主就发怒，对仆人说：‘快到城里大街小巷去，把贫穷的、残废的、瞎眼的、瘸腿的，都领到这里来。’'),
('CNV', '路加福音', 42, 14, 22, '仆人说：‘主啊，你所吩咐的已经办了，还有空位。’'),
('CNV', '路加福音', 42, 14, 23, '主人就对仆人说：‘你出去到路边篱畔，勉强人进来，好把我的屋子坐满。'),
('CNV', '路加福音', 42, 14, 24, '我告诉你们，先前请的那些人，一个也不得尝我的筵席。’”'),
('CNV', '路加福音', 42, 14, 25, '有许多人与耶稣同行，他转身对他们说：'),
('CNV', '路加福音', 42, 14, 26, '“如果有人到我这里来，爱我不超过爱（“爱我不超过爱”原文作“不恨”）自己的父母、妻子、儿女、兄弟、姊妹，甚至自己的性命，就不能作我的门徒。'),
('CNV', '路加福音', 42, 14, 27, '凡不背着自己的十字架跟随我的，也不能作我的门徒。'),
('CNV', '路加福音', 42, 14, 28, '你们当中有谁要盖一座楼，不先坐下计算费用，能不能盖成呢？'),
('CNV', '路加福音', 42, 14, 29, '恐怕安了地基，而不能完成，所有看见的人都讥笑他，'),
('CNV', '路加福音', 42, 14, 30, '说：‘这个人开了工，却不能完工。’'),
('CNV', '路加福音', 42, 14, 31, '或者一个王去和别的王打仗，哪有不先坐下想想，能否用一万兵去抵抗那领两万来攻打他的呢？'),
('CNV', '路加福音', 42, 14, 32, '如果不能，就该趁对方还远的时候，派使者去谈判和平的条件。'),
('CNV', '路加福音', 42, 14, 33, '这样，你们中间不论谁，如果不撇下一切所有的，就不能作我的门徒。'),
('CNV', '路加福音', 42, 14, 34, '“盐本来是好的，但如果失了味，怎能使它再咸呢？'),
('CNV', '路加福音', 42, 14, 35, '或用在田里，或放在粪里，都不合适；只好扔在外面。有耳可听的，就应当听。”'),
('CNV', '路加福音', 42, 15, 1, '众税吏和罪人，都接近耶稣，要听他讲道。'),
('CNV', '路加福音', 42, 15, 2, '法利赛人和经学家，纷纷议论说：“这个人接待罪人，又和他们一起吃饭。”'),
('CNV', '路加福音', 42, 15, 3, '耶稣就对他们讲了这个比喻，说：'),
('CNV', '路加福音', 42, 15, 4, '“你们中间谁有一百只羊，失去一只，不把九十九只留下在旷野，去寻找那失落的，直到找着呢？'),
('CNV', '路加福音', 42, 15, 5, '既找着了，就欢欢喜喜地放在肩上，'),
('CNV', '路加福音', 42, 15, 6, '回到家里，请朋友邻舍来，对他们说：‘请大家和我一同欢乐，因为我失去的羊已经找到了！’'),
('CNV', '路加福音', 42, 15, 7, '我告诉你们，因为一个罪人悔改，天上也要这样为他欢乐，比为九十九个不用悔改的义人欢乐更大。'),
('CNV', '路加福音', 42, 15, 8, '“或是一个女人，有十个银币（“银币”原文作“拉克玛”，一个“拉克玛”相当于一天的工资），失去一个，哪能不点上灯，打扫屋子，细细地找，直到找着呢？'),
('CNV', '路加福音', 42, 15, 9, '既找着了，就请朋友邻舍来，说：‘请大家和我一同欢乐，因为我失去的那个银币，已经找到了。’'),
('CNV', '路加福音', 42, 15, 10, '我告诉你们，因为一个罪人悔改，神的使者也必这样为他欢乐。”'),
('CNV', '路加福音', 42, 15, 11, '耶稣又说：“某人有两个儿子。'),
('CNV', '路加福音', 42, 15, 12, '小儿子对父亲说：‘爸爸，请把我应得的家业给我。’父亲就把财产分给他们两兄弟。'),
('CNV', '路加福音', 42, 15, 13, '过了不多几天，小儿子收拾一切，到远方去了，在那里生活放荡，浪费钱财。'),
('CNV', '路加福音', 42, 15, 14, '他花尽了一切所有的，那地方又遇上了严重的饥荒，就穷困起来；'),
('CNV', '路加福音', 42, 15, 15, '于是他去投靠当地的一个居民。那人打发他到田里去放猪，'),
('CNV', '路加福音', 42, 15, 16, '他恨不得吃猪所吃的豆荚，可是没有人给他。'),
('CNV', '路加福音', 42, 15, 17, '他醒悟过来，说：‘我父亲有那么多雇工，又有丰富的食物，我却要在这里饿死吗？'),
('CNV', '路加福音', 42, 15, 18, '我要起来，到我父亲那里去，对他说：爸爸，我得罪了天，也得罪了你，'),
('CNV', '路加福音', 42, 15, 19, '不配再称为你的儿子，把我当作一个雇工吧！’'),
('CNV', '路加福音', 42, 15, 20, '于是他起来往父亲那里去。他还在远处时，他父亲看见了他，就动了慈心，跑过去抱着他，连连与他亲吻。'),
('CNV', '路加福音', 42, 15, 21, '儿子说：‘爸爸，我得罪了天，也得罪了你，不配再称为你的儿子。’'),
('CNV', '路加福音', 42, 15, 22, '父亲却吩咐仆人说：‘快把那最好的袍子拿来给他穿，把戒指戴在他手上，把鞋穿在他脚上，'),
('CNV', '路加福音', 42, 15, 23, '把肥牛犊牵来宰了，我们要吃喝快乐，'),
('CNV', '路加福音', 42, 15, 24, '因为我这儿子是死而复活、失而又得的。’他们就欢乐起来。'),
('CNV', '路加福音', 42, 15, 25, '“那时，大儿子正在田里。他回来离家不远的时候，听见音乐跳舞的声音，'),
('CNV', '路加福音', 42, 15, 26, '就叫了一个仆人来，问他这是怎么一回事。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '路加福音', 42, 15, 27, '仆人说：‘你弟弟回来了，你父亲因为他平安无恙地回来，就宰了肥牛犊。’'),
('CNV', '路加福音', 42, 15, 28, '大儿子就生气，不肯进去；父亲出来劝他。'),
('CNV', '路加福音', 42, 15, 29, '他对父亲说：‘你看，我服事你这么多年，从来没有违背过你的命令，可是你没有给我一只山羊羔，叫我和朋友一同欢乐。'),
('CNV', '路加福音', 42, 15, 30, '但你这个儿子，常常跟娼妓在一起，花尽了你的财产，他一回来，你倒为他宰杀肥牛犊！’'),
('CNV', '路加福音', 42, 15, 31, '父亲对他说：‘孩子，你常跟我在一起，我的一切都是你的。'),
('CNV', '路加福音', 42, 15, 32, '只是因为你这个弟弟是死而复活、失而又得的，我们应该欢喜快乐。’”'),
('CNV', '路加福音', 42, 16, 1, '耶稣又对门徒说：“有一个财主的管家，有人在他主人面前告他浪费主人的财物。'),
('CNV', '路加福音', 42, 16, 2, '主人把他叫来，对他说：‘我听见关于你的是怎么一回事呢？把你管理的帐目交代清楚，因为你不能再作管家了。’'),
('CNV', '路加福音', 42, 16, 3, '那管家心里说：‘主人不要我再作管家了，我作什么才好呢？锄地吧，没有力气！讨饭吧，怕羞！'),
('CNV', '路加福音', 42, 16, 4, '我知道要怎么作了，好使人在我离开管家的职务以后，接我到他们家里去。’'),
('CNV', '路加福音', 42, 16, 5, '于是把欠他主人债的人，一个一个地叫来，问头一个说：‘你欠我主人多少？’'),
('CNV', '路加福音', 42, 16, 6, '他说：‘四千公升油。’管家说：‘拿你的欠单去，快坐下写二千。’'),
('CNV', '路加福音', 42, 16, 7, '又问一个说：‘你欠多少？’他说：‘四万公升麦子。’管家说：‘拿你的欠单去，写三万。’'),
('CNV', '路加福音', 42, 16, 8, '主人就夸奖这不义的管家作事机警；因为在应付自己的世事上，今世之子比光明之子更精明。'),
('CNV', '路加福音', 42, 16, 9, '我告诉你们，要用不义的钱财（“钱财”亚兰文是“玛门”）去结交朋友，好叫钱财无用的时候，他们可以接你们到永恒的帐棚里。'),
('CNV', '路加福音', 42, 16, 10, '在最小的事上忠心的，在大事上也忠心；在最小的事上不义的，在大事上也不义。'),
('CNV', '路加福音', 42, 16, 11, '如果你们在不义的钱财上不忠心，谁还把真实的钱财托付给你们呢？'),
('CNV', '路加福音', 42, 16, 12, '如果你们在别人的东西上不忠心，谁还把你们自己的东西交给你们呢？'),
('CNV', '路加福音', 42, 16, 13, '“一个家仆不能服事两个主人；他若不是恨这个爱那个，就是忠于这个轻视那个。你们不能服事神，又服事金钱。”'),
('CNV', '路加福音', 42, 16, 14, '贪财的法利赛人听见这些话，就嗤笑耶稣。'),
('CNV', '路加福音', 42, 16, 15, '耶稣对他们说：“你们在人面前自称为义，神却知道你们的心；因为人所高举的，神却看作是可憎恶的。'),
('CNV', '路加福音', 42, 16, 16, '律法和先知到约翰就结束了。从此，神的国的福音就传开了，人人都要努力进去。'),
('CNV', '路加福音', 42, 16, 17, '天地过去，要比律法的一点一画失效还容易呢。'),
('CNV', '路加福音', 42, 16, 18, '凡休妻另娶的，就犯了奸淫；娶被丈夫所休的，也是犯了奸淫。'),
('CNV', '路加福音', 42, 16, 19, '“有一个财主，身穿紫色袍和细麻衣，天天奢华宴乐。'),
('CNV', '路加福音', 42, 16, 20, '又有一个乞丐，名叫拉撒路，满身是疮，被人放在财主门口，'),
('CNV', '路加福音', 42, 16, 21, '想得财主桌子上掉下来的零碎充饥；并且有狗来舔他的疮。'),
('CNV', '路加福音', 42, 16, 22, '后来乞丐死了，被天使送到亚伯拉罕的怀里。那财主也死了，并且埋葬了。'),
('CNV', '路加福音', 42, 16, 23, '财主在阴间受痛苦，举目远远望见亚伯拉罕，和他怀里的拉撒路，'),
('CNV', '路加福音', 42, 16, 24, '就喊着说：‘我祖亚伯拉罕啊，可怜我吧！打发拉撒路来用指头蘸点水，凉凉我的舌头吧！因为我在这火焰里非常痛苦。’'),
('CNV', '路加福音', 42, 16, 25, '亚伯拉罕说：‘孩子，你应该回想你生前享过福，同样拉撒路受过苦，现在他在这里得安慰，你却要受苦了。'),
('CNV', '路加福音', 42, 16, 26, '不但这样，我们与你们之间，有深渊隔开，人想从这边过到你们那里是不可能的，从那边过到我们这边也是不可能的。’'),
('CNV', '路加福音', 42, 16, 27, '那人说：‘我祖啊，那么求你差遣拉撒路到我家里去，'),
('CNV', '路加福音', 42, 16, 28, '因为我有五个兄弟，他可以警告他们，免得他们也到这受苦的地方来。’'),
('CNV', '路加福音', 42, 16, 29, '亚伯拉罕说：‘他们有摩西和先知可以听从。’'),
('CNV', '路加福音', 42, 16, 30, '他说：‘不然，我祖亚伯拉罕啊，如果有人从死人中复活，到他们那里去，他们必定会悔改。’'),
('CNV', '路加福音', 42, 16, 31, '亚伯拉罕说：‘如果他们不听从摩西和先知，就算有一个从死人中复活的人，他们也不会接受劝告。’”'),
('CNV', '路加福音', 42, 17, 1, '耶稣又对门徒说：“使人犯罪的事是免不了的，但那使人犯罪的人有祸了！'),
('CNV', '路加福音', 42, 17, 2, '就算拿一块大磨石拴在他的颈项上，把他沉在深海里，比他使这小子中的一个犯罪还好。'),
('CNV', '路加福音', 42, 17, 3, '你们应当谨慎。如果你弟兄得罪你，就劝戒他；他若懊悔，就饶恕他。'),
('CNV', '路加福音', 42, 17, 4, '如果他一天七次得罪你，又七次回转，对你说：‘我懊悔了！’你总要饶恕他。”'),
('CNV', '路加福音', 42, 17, 5, '使徒对主说：“请你加添我们的信心。”'),
('CNV', '路加福音', 42, 17, 6, '主说：“如果你们有信心像一粒芥菜种，就是对这棵桑树说：‘拔起根来，栽到海里去！’它也必听从你们。'),
('CNV', '路加福音', 42, 17, 7, '“你们中间谁有仆人去耕地或是放羊，从田里回来，你就对他说：‘快过来坐下吃饭’；'),
('CNV', '路加福音', 42, 17, 8, '而不对他说：‘给我预备晚餐，束起腰来服事我，等我吃喝完了，你才吃喝’呢？'),
('CNV', '路加福音', 42, 17, 9, '仆人作了所吩咐的事，主人还谢谢他吗？'),
('CNV', '路加福音', 42, 17, 10, '你们也是这样，作完一切吩咐你们的事，应该说：‘我们是无用的仆人，我们只作了应分作的。’”'),
('CNV', '路加福音', 42, 17, 11, '耶稣往耶路撒冷去，经过撒玛利亚和加利利的边境。'),
('CNV', '路加福音', 42, 17, 12, '他走进一个村庄，有十个痲风病人迎面而来，远远地站着，'),
('CNV', '路加福音', 42, 17, 13, '大声说：“主耶稣啊，可怜我们吧！”'),
('CNV', '路加福音', 42, 17, 14, '他看见了，就对他们说：“你们去给祭司检查吧。”他们去的时候就洁净了。'),
('CNV', '路加福音', 42, 17, 15, '内中有一个人见自己已经好了，就回来大声颂赞神，'),
('CNV', '路加福音', 42, 17, 16, '在耶稣脚前把脸伏在地上感谢他。他是一个撒玛利亚人。'),
('CNV', '路加福音', 42, 17, 17, '耶稣说：“洁净了的不是有十个人吗？那九个在哪里？'),
('CNV', '路加福音', 42, 17, 18, '除了这外族人，再没有一个回来颂赞神吗？”'),
('CNV', '路加福音', 42, 17, 19, '耶稣就对他说：“起来，走吧，你的信使你痊愈了。”'),
('CNV', '路加福音', 42, 17, 20, '法利赛人问耶稣：“神的国什么时候来到呢？”他回答：“神的国来到，是眼睛看不见的。'),
('CNV', '路加福音', 42, 17, 21, '人不能说：‘看哪！在这里’，或说：‘在那里’；因为神的国就在你们里面。”'),
('CNV', '路加福音', 42, 17, 22, '他又对门徒说：“日子将到，你们渴望看见人子的一个日子，却见不到。'),
('CNV', '路加福音', 42, 17, 23, '有人会对你们说：‘看哪，在那里；看哪，在这里！’你们不要出去，也不要追随他们。'),
('CNV', '路加福音', 42, 17, 24, '电光怎样从天这边一闪，直照到天那边，人子在他的日子也是这样。'),
('CNV', '路加福音', 42, 17, 25, '但他必须先受许多苦，被这个世代弃绝。'),
('CNV', '路加福音', 42, 17, 26, '挪亚的时代怎样，人子的时代也是怎样。'),
('CNV', '路加福音', 42, 17, 27, '当时人们吃喝嫁娶，直到挪亚进入方舟的那一天，洪水来了，把他们全都灭掉。'),
('CNV', '路加福音', 42, 17, 28, '在罗得的时代也是这样，人们吃喝买卖，耕种建造，'),
('CNV', '路加福音', 42, 17, 29, '直到罗得离开所多玛的那一天，火与硫磺从天上降下来，把他们全都灭掉。'),
('CNV', '路加福音', 42, 17, 30, '人子显现的日子也是这样。'),
('CNV', '路加福音', 42, 17, 31, '当那日，人在房顶上，器具在屋里，不要下来拿；在田里的，照样不要回家。'),
('CNV', '路加福音', 42, 17, 32, '应当记着罗得的妻子的教训。'),
('CNV', '路加福音', 42, 17, 33, '凡是想保全生命的，必丧掉生命；凡是牺牲生命的，却必保全生命。'),
('CNV', '路加福音', 42, 17, 34, '我告诉你们，当那夜，两个人在一张床上，一个被接去，一个被撇下。'),
('CNV', '路加福音', 42, 17, 35, '两个女人一起推磨，一个被接去，一个被撇下。”（有些抄本有第36节：“两个人在田里，一个被接去，一个撇下来。”）'),
('CNV', '路加福音', 42, 17, 37, '门徒问耶稣：“主啊，这些事会在哪里发生呢？”主说：“尸首在哪里，鹰也会聚集在哪里。”'),
('CNV', '路加福音', 42, 18, 1, '耶稣对他们讲一个比喻，论到人必须常常祈祷，不可灰心。'),
('CNV', '路加福音', 42, 18, 2, '他说：“某城里有一个法官，不惧怕神，也不尊敬人。'),
('CNV', '路加福音', 42, 18, 3, '那城里有一个寡妇，常常来到他那里，说：‘求你给我伸冤，使我脱离我的对头！’'),
('CNV', '路加福音', 42, 18, 4, '他多次不肯，后来心里说：‘我虽然不惧怕神，也不尊敬人，'),
('CNV', '路加福音', 42, 18, 5, '只是因为这寡妇常常来麻烦我，就给她伸冤吧，免得她不断地来缠扰我。’”'),
('CNV', '路加福音', 42, 18, 6, '主说：“你们听听这不义的法官所说的话吧。'),
('CNV', '路加福音', 42, 18, 7, '难道神不会为昼夜呼吁他的选民伸冤吗？难道神会耽误他们吗？'),
('CNV', '路加福音', 42, 18, 8, '我告诉你们，他要快快地给他们伸冤。然而人子来的时候，在世上找得到这种信心吗？”'),
('CNV', '路加福音', 42, 18, 9, '耶稣向那些自恃为义、轻视别人的人，讲了这个比喻：'),
('CNV', '路加福音', 42, 18, 10, '“有两个人上圣殿去祈祷，一个是法利赛人，一个是税吏。'),
('CNV', '路加福音', 42, 18, 11, '法利赛人站着，祷告给自己听，这样说：‘神啊，我感谢你，我不像别人，勒索、不义、奸淫，也不像这个税吏。'),
('CNV', '路加福音', 42, 18, 12, '我一个礼拜禁食两次，我的一切收入都奉献十分之一。’'),
('CNV', '路加福音', 42, 18, 13, '税吏却远远站着，连举目望天也不敢，只捶着胸说：‘神啊，可怜我这个罪人！’'),
('CNV', '路加福音', 42, 18, 14, '我告诉你们，这个人回家去，比那个倒算为义了。因为高抬自己的，必要降卑；自己谦卑的，必要升高。”'),
('CNV', '路加福音', 42, 18, 15, '有人抱着婴孩到耶稣面前，要他触摸他们。门徒看见了，就责备那些人。'),
('CNV', '路加福音', 42, 18, 16, '耶稣却叫他们过来，说：“让小孩子到我这里来，不要禁止他们，因为神的国正属于这样的人。'),
('CNV', '路加福音', 42, 18, 17, '我实在告诉你们，凡不像小孩子一样接受神的国的，决不能进去。”'),
('CNV', '路加福音', 42, 18, 18, '有一个官长问耶稣：“良善的老师，我当作什么，才可以承受永生？”'),
('CNV', '路加福音', 42, 18, 19, '耶稣对他说：“你为什么称我是良善的呢？除了神一位以外，没有良善的。'),
('CNV', '路加福音', 42, 18, 20, '诫命你是知道的：不可奸淫，不可杀人，不可偷盗，不可作假见证，当孝敬父母。”'),
('CNV', '路加福音', 42, 18, 21, '他说：“这一切我从小都遵守了。”'),
('CNV', '路加福音', 42, 18, 22, '耶稣听了，就告诉他：“你还缺少一件，应当变卖你一切所有的，分给穷人，你就必定有财宝在天上，而且你还要来跟从我。”'),
('CNV', '路加福音', 42, 18, 23, '他听见这话，非常忧愁，因为他十分富有。'),
('CNV', '路加福音', 42, 18, 24, '耶稣见他这样，就说：“富有的人要进神的国，是多么难哪！'),
('CNV', '路加福音', 42, 18, 25, '骆驼穿过针眼，比有钱的人进神的国还容易呢。”'),
('CNV', '路加福音', 42, 18, 26, '听见的人说：“这样，谁可以得救呢？”'),
('CNV', '路加福音', 42, 18, 27, '耶稣说：“人所不能的，在神却是可能的。”'),
('CNV', '路加福音', 42, 18, 28, '彼得说：“你看，我们已舍弃自己所有的，跟从你了！”'),
('CNV', '路加福音', 42, 18, 29, '耶稣说：“我实在告诉你们，人为神的国撇下房屋、妻子、弟兄、父母或儿女，'),
('CNV', '路加福音', 42, 18, 30, '没有不在今世得许多倍，来世得永生的。”'),
('CNV', '路加福音', 42, 18, 31, '耶稣把十二门徒带到一边，对他们说：“我们现在上耶路撒冷去，先知所写的一切，都要成就在人子身上。'),
('CNV', '路加福音', 42, 18, 32, '他要被交给外族人，受戏弄，被凌辱，他们要向他吐唾沫，'),
('CNV', '路加福音', 42, 18, 33, '鞭打他，杀害他；第三日他要复活。”'),
('CNV', '路加福音', 42, 18, 34, '这些话的含义对门徒是隐藏的。他们听了，一点也不明白，不知道他说的是什么。'),
('CNV', '路加福音', 42, 18, 35, '耶稣走近耶利哥的时候，有一个瞎眼的人坐在路旁讨饭，'),
('CNV', '路加福音', 42, 18, 36, '他听见人群经过，就问是什么事。'),
('CNV', '路加福音', 42, 18, 37, '别人告诉他，是拿撒勒人耶稣经过。'),
('CNV', '路加福音', 42, 18, 38, '他就喊叫说：“大卫的子孙耶稣啊，可怜我吧！”'),
('CNV', '路加福音', 42, 18, 39, '在前头走的人责备他，叫他不要出声；但他越发喊叫：“大卫的子孙，可怜我吧！”'),
('CNV', '路加福音', 42, 18, 40, '耶稣站住，吩咐领他过来。等他走近，就问他：'),
('CNV', '路加福音', 42, 18, 41, '“你要我为你作什么？”他说：“主啊，叫我能看见！”'),
('CNV', '路加福音', 42, 18, 42, '耶稣说：“你就看见吧！你的信使你痊愈了。”'),
('CNV', '路加福音', 42, 18, 43, '他立刻看见了，就跟随耶稣，颂赞神。众人看见这事，也赞美神。'),
('CNV', '路加福音', 42, 19, 1, '耶稣进了耶利哥，正经过的时候，'),
('CNV', '路加福音', 42, 19, 2, '有一个人名叫撒该，是税吏长，又很富有。'),
('CNV', '路加福音', 42, 19, 3, '他想看看耶稣是怎么样的，因为人多，他又身材矮小，就看不见。'),
('CNV', '路加福音', 42, 19, 4, '于是他跑到前头，爬上一棵桑树，要看看耶稣，因为耶稣就要从那里经过。'),
('CNV', '路加福音', 42, 19, 5, '耶稣到了那里，往上一看，对他说：“撒该，快下来，今天我要住在你家里。”'),
('CNV', '路加福音', 42, 19, 6, '他就赶快下来，欢欢喜喜地接待耶稣。'),
('CNV', '路加福音', 42, 19, 7, '众人看见就纷纷议论说：“他竟到罪人家里去住宿！”'),
('CNV', '路加福音', 42, 19, 8, '撒该站着对主说：“主啊，请看，我要把家财的一半分给穷人，我若敲诈了谁，就还他四倍。”'),
('CNV', '路加福音', 42, 19, 9, '耶稣说：“今天救恩到了这家，他也是亚伯拉罕的子孙。'),
('CNV', '路加福音', 42, 19, 10, '因为人子来，是要寻找拯救失丧的人。”'),
('CNV', '路加福音', 42, 19, 11, '众人听这些话的时候，因为耶稣已经接近耶路撒冷，又因他们以为神的国快要出现，他就讲了一个比喻，'),
('CNV', '路加福音', 42, 19, 12, '说：“有一个贵族往远方去要接受王位，然后回来。'),
('CNV', '路加福音', 42, 19, 13, '他叫了自己的十个仆人来，给他们一千银币，说：‘你们拿去作生意，等到我回来。’'),
('CNV', '路加福音', 42, 19, 14, '他本国的人却恨他，就派使者跟着去说：‘我们不愿意这个人作王统治我们。’'),
('CNV', '路加福音', 42, 19, 15, '他得了王位回来，就吩咐把那些领了钱的仆人召来，要知道他们作生意赚了多少。'),
('CNV', '路加福音', 42, 19, 16, '第一个走过来说：‘主啊，你的一百银币，已经赚了一千。’'),
('CNV', '路加福音', 42, 19, 17, '主人说：‘好，良善的仆人，你既然在最小的事上忠心，可以有权管理十座城。’'),
('CNV', '路加福音', 42, 19, 18, '第二个来说：‘主啊，你的一百银币，已经赚了五百。’'),
('CNV', '路加福音', 42, 19, 19, '主人说：‘你可以管理五座城。’'),
('CNV', '路加福音', 42, 19, 20, '另一个来说：‘主啊，你看，你的一百银币，我一直保存在手巾里，'),
('CNV', '路加福音', 42, 19, 21, '因为我怕你，你一向是严厉的人，没有存的要提取，没有种的要收割。’'),
('CNV', '路加福音', 42, 19, 22, '主人说：‘可恶的仆人！我要凭你的口定你的罪。你知道我是严厉的人，没有存的要提取，没有种的要收割吗？'),
('CNV', '路加福音', 42, 19, 23, '那你为什么不把我的钱存入银行，等我回来的时候，把它连本带利取回来呢？’'),
('CNV', '路加福音', 42, 19, 24, '他就对侍卫说：‘夺过他的一百银币，给那有一千的。’'),
('CNV', '路加福音', 42, 19, 25, '他们说：‘主啊，他已经有一千银币了。’'),
('CNV', '路加福音', 42, 19, 26, '主人说：‘我告诉你们，凡是有的，还要给他；没有的，就算他有什么也要拿去。'),
('CNV', '路加福音', 42, 19, 27, '至于我那些仇敌，就是不愿意我作王统治他们的，把他们拉到这里来，在我面前杀掉！’”'),
('CNV', '路加福音', 42, 19, 28, '耶稣讲完这些话，就往前走，上耶路撒冷去。'),
('CNV', '路加福音', 42, 19, 29, '将到伯法其和伯大尼，就在橄榄山那里，他差派两个门徒，'),
('CNV', '路加福音', 42, 19, 30, '说：“你们往对面的村子里去，走进去的时候，就会看见一头从来没有人骑过的小驴，拴在那里，把它解开牵来。'),
('CNV', '路加福音', 42, 19, 31, '如果有人问为什么解开它，你们要这样说：‘主需要它。’”'),
('CNV', '路加福音', 42, 19, 32, '被差的人去了，发现和主所说的一样。'),
('CNV', '路加福音', 42, 19, 33, '他们解开小驴的时候，主人问他们：“你们为什么解开它？”'),
('CNV', '路加福音', 42, 19, 34, '他们说：“主需要它。”'),
('CNV', '路加福音', 42, 19, 35, '他们把小驴牵到耶稣那里，把自己的衣服搭在上面，扶着耶稣上去。'),
('CNV', '路加福音', 42, 19, 36, '耶稣前行的时候，众人把自己的衣服铺在路上。'),
('CNV', '路加福音', 42, 19, 37, '他走近耶路撒冷，快要下橄榄山的时候，全体门徒因为所看见的一切神迹，就欢乐起来，大声赞美神，'),
('CNV', '路加福音', 42, 19, 38, '说：“奉主名来的王，是应当称颂的！在天上有和平，在至高之处有荣耀！”'),
('CNV', '路加福音', 42, 19, 39, '群众中有几个法利赛人对他说：“先生，责备你的门徒吧！”'),
('CNV', '路加福音', 42, 19, 40, '耶稣说：“我告诉你们，他们若不出声，石头都要呼叫了。”'),
('CNV', '路加福音', 42, 19, 41, '耶稣走近耶路撒冷的时候，看见了城，就为城哀哭，'),
('CNV', '路加福音', 42, 19, 42, '说：“巴不得你在这日子，知道关于你平安的事，但现在这事在你眼前是隐藏的。'),
('CNV', '路加福音', 42, 19, 43, '日子将到，你的仇敌必筑垒攻击你，周围环绕你，四面困住你，'),
('CNV', '路加福音', 42, 19, 44, '要摧毁你和你里面的儿女，没有一块石头留在另一块石头上面，因为你不知道那眷顾你的时期。”'),
('CNV', '路加福音', 42, 19, 45, '耶稣进了圣殿，就赶走作买卖的人，'),
('CNV', '路加福音', 42, 19, 46, '对他们说：“经上记着：‘我的殿是祷告的殿’，你们竟把它弄成贼窝了。”'),
('CNV', '路加福音', 42, 19, 47, '他天天在圣殿里教导人，祭司长、经学家和民间的首领，都想杀害他；'),
('CNV', '路加福音', 42, 19, 48, '但他们不知道要怎样下手，因为众人都围着他，听他的教训。'),
('CNV', '路加福音', 42, 20, 1, '有一天，耶稣在殿里教导人，宣讲福音，众祭司长、经学家和长老上前来，'),
('CNV', '路加福音', 42, 20, 2, '对他说：“告诉我们，你凭着什么权柄作这些事？给你这权柄的是谁？”'),
('CNV', '路加福音', 42, 20, 3, '他回答他们：“我也要问你们一句话，你们告诉我：'),
('CNV', '路加福音', 42, 20, 4, '约翰的洗礼是从天上来的，还是从人来的呢？”'),
('CNV', '路加福音', 42, 20, 5, '他们就彼此议论说：“如果我们说：‘是从天上来的’，他就会问：‘那你们为什么不相信他呢？’'),
('CNV', '路加福音', 42, 20, 6, '如果我们说：‘是从人来的’，众人都会用石头打我们，因为他们都认定约翰是先知。”'),
('CNV', '路加福音', 42, 20, 7, '于是他们回答耶稣：“我们不知道是从哪里来的。”'),
('CNV', '路加福音', 42, 20, 8, '耶稣说：“我也不告诉你们，我凭着什么权柄作这些事。”'),
('CNV', '路加福音', 42, 20, 9, '于是耶稣向众人讲了这个比喻：“有一个人栽种了一个葡萄园，租给佃户，就远行去了很久。'),
('CNV', '路加福音', 42, 20, 10, '到了时候，园主派了一个仆人到佃户那里，叫他们把葡萄园当纳的果子交给他。佃户却打了他，放他空手回去。'),
('CNV', '路加福音', 42, 20, 11, '园主又派另一个仆人去，佃户又打了他，并且侮辱他，也叫他空手回去。'),
('CNV', '路加福音', 42, 20, 12, '于是他又派第三个去，佃户把他打伤，赶他走了。'),
('CNV', '路加福音', 42, 20, 13, '葡萄园的主人说：‘怎么办呢？我要派我的爱子去，也许这一个他们会尊敬的。’'),
('CNV', '路加福音', 42, 20, 14, '佃户一看他，就彼此商议说：‘这是继承产业的，让我们杀了他，那么，产业就成为我们的了。’'),
('CNV', '路加福音', 42, 20, 15, '于是他们把园主的爱子推出葡萄园外杀了。主人要怎样对待他们呢？'),
('CNV', '路加福音', 42, 20, 16, '他要来除掉这些佃户，把葡萄园租给别人。”他们听见了就说：“千万不要有这样的事发生！”'),
('CNV', '路加福音', 42, 20, 17, '耶稣看着他们，说：“那么，‘建筑工人所弃的石头，成了房角的主要石头’，这经文是什么意思呢？'),
('CNV', '路加福音', 42, 20, 18, '凡是跌在那石头上的，就必摔碎；那石头掉在谁的身上，就必把他压得粉碎。”'),
('CNV', '路加福音', 42, 20, 19, '经学家和祭司长知道这比喻是针对他们说的，当时就想动手拿他，可是又害怕群众。'),
('CNV', '路加福音', 42, 20, 20, '经学家和祭司长差派奸细伪装好人去窥探耶稣，要在他的话上抓着把柄，好把他交由总督全权裁决。'),
('CNV', '路加福音', 42, 20, 21, '奸细问他：“老师，我们知道你所说所教的都对，并且不讲情面，只照着真理把神的道教导人。'),
('CNV', '路加福音', 42, 20, 22, '我们纳税给凯撒可以不可以？”'),
('CNV', '路加福音', 42, 20, 23, '耶稣看透他们的诡计，就对他们说：'),
('CNV', '路加福音', 42, 20, 24, '“给我一个银币看看，上面是谁的像，谁的名号？”他们说：“凯撒的。”'),
('CNV', '路加福音', 42, 20, 25, '耶稣说：“这样，凯撒的应当归给凯撒，神的应当归给神。”'),
('CNV', '路加福音', 42, 20, 26, '他们在群众面前，不能抓住耶稣的把柄，又希奇他的回答，就沉默下来。'),
('CNV', '路加福音', 42, 20, 27, '撒都该人向来否认有复活的事，他们当中有几个人来问耶稣：'),
('CNV', '路加福音', 42, 20, 28, '“老师，摩西曾写给我们说：‘如果一个人娶了妻子，还没有儿女就死了，他的弟弟就应当娶他的妻子，为哥哥立后。’'),
('CNV', '路加福音', 42, 20, 29, '从前有兄弟七人，头一个娶了妻子，没有孩子就死了。'),
('CNV', '路加福音', 42, 20, 30, '第二个、'),
('CNV', '路加福音', 42, 20, 31, '第三个，也娶过她；七个都是这样，都没有留下孩子就死了。'),
('CNV', '路加福音', 42, 20, 32, '后来那女人也死了。'),
('CNV', '路加福音', 42, 20, 33, '那么，这女人在复活的时候，要作哪一个的妻子呢？因为七个人都娶过她。”'),
('CNV', '路加福音', 42, 20, 34, '耶稣说：“这世界的人又娶又嫁，'),
('CNV', '路加福音', 42, 20, 35, '但配得那世界的，又配从死人中复活的人，也不娶也不嫁。'),
('CNV', '路加福音', 42, 20, 36, '他们和天使一样，不能再死；既然是复活了的人，就是神的儿子了。'),
('CNV', '路加福音', 42, 20, 37, '至于死人复活的事，摩西在荆棘篇上提过，他称主是亚伯拉罕的神、以撒的神、雅各的神；'),
('CNV', '路加福音', 42, 20, 38, '神不是死人的神，而是活人的神，因为在他那里的人都是活的。”'),
('CNV', '路加福音', 42, 20, 39, '经学家中有几个说：“老师，你说得好。”'),
('CNV', '路加福音', 42, 20, 40, '从此他们再不敢问他什么了。'),
('CNV', '路加福音', 42, 20, 41, '耶稣问他们：“人怎么能说基督是大卫的子孙呢？'),
('CNV', '路加福音', 42, 20, 42, '大卫自己在诗篇上说：‘主对我的主说：你坐在我的右边，'),
('CNV', '路加福音', 42, 20, 43, '等我使你的仇敌作你的脚凳。’'),
('CNV', '路加福音', 42, 20, 44, '大卫既然称他为主，他又怎会是大卫的子孙呢？”'),
('CNV', '路加福音', 42, 20, 45, '众人听着的时候，耶稣对门徒说：'),
('CNV', '路加福音', 42, 20, 46, '“你们要提防经学家，他们好穿长袍走来走去，喜欢人在巿中心向他们问安，并且喜欢会堂里的高位、筵席上的首座。'),
('CNV', '路加福音', 42, 20, 47, '他们吞没了寡妇的房产，又用冗长的祷告作掩饰。这等人必受更重的刑罚。”'),
('CNV', '路加福音', 42, 21, 1, '耶稣抬眼看见有钱的人把奉献投入奉献箱。'),
('CNV', '路加福音', 42, 21, 2, '他又看见一个穷寡妇，投入两个小钱，'),
('CNV', '路加福音', 42, 21, 3, '就说：“我实在告诉你们，这个穷寡妇所投的，比众人投的更多。'),
('CNV', '路加福音', 42, 21, 4, '因为这些人都是把自己剩余的投进去作奉献，这寡妇是自己不足，却把所有养生的都投进去了。”'),
('CNV', '路加福音', 42, 21, 5, '有人在谈论圣殿，是用美丽的石头和供物装饰的。耶稣说：'),
('CNV', '路加福音', 42, 21, 6, '“你们看见的这些，到了日子，必没有一块石头留在另一块石头上面，每一块都要拆下来。”'),
('CNV', '路加福音', 42, 21, 7, '那些人问他：“老师，什么时候会有这些事呢？这些事要发生的时候，有什么预兆呢？”'),
('CNV', '路加福音', 42, 21, 8, '他说：“你们要小心，不要被人迷惑。因为有许多人要来，假冒我的名说：‘我就是基督’，又说：‘时候近了。’你们不要跟从这些人。'),
('CNV', '路加福音', 42, 21, 9, '你们要听见战乱和暴动，但不要惊慌，因为这些事是必先发生的，不过结局却不会立刻就到。”'),
('CNV', '路加福音', 42, 21, 10, '过了一会儿，耶稣又对他们说：“一个民族要起来攻打另一个民族，一个国家要起来攻打另一个国家。'),
('CNV', '路加福音', 42, 21, 11, '必有大地震，到处有饥荒和瘟疫，天上必有又恐怖又巨大的预兆。'),
('CNV', '路加福音', 42, 21, 12, '但在这一切以先，人必为我的名，下手拘捕、迫害你们，把你们交给会堂，下在监里，甚至押到君王和总督面前，'),
('CNV', '路加福音', 42, 21, 13, '结果却成了你们见证的机会。'),
('CNV', '路加福音', 42, 21, 14, '所以，你们应当心里镇定，用不着预先思虑怎样申辩。'),
('CNV', '路加福音', 42, 21, 15, '因为我必赐给你们口才、智慧，是你们所有的敌人不能抵抗，也不能驳倒的。'),
('CNV', '路加福音', 42, 21, 16, '你们也会被父母、弟兄、亲戚、朋友出卖，他们又要害死你们一些人。'),
('CNV', '路加福音', 42, 21, 17, '你们要因我的名，被众人恨恶，'),
('CNV', '路加福音', 42, 21, 18, '然而连你们的一根头发，也必不失落。'),
('CNV', '路加福音', 42, 21, 19, '你们要以坚忍的心志，赢取自己的灵魂。'),
('CNV', '路加福音', 42, 21, 20, '“当你们看见耶路撒冷被军队围困的时候，就知道它荒凉的日子近了。'),
('CNV', '路加福音', 42, 21, 21, '那时，住在犹太的，应该逃到山上；住在城里的，要离开；住在乡下的，不要进城。'),
('CNV', '路加福音', 42, 21, 22, '因为这是报仇的日子，使经上的一切话都得应验。'),
('CNV', '路加福音', 42, 21, 23, '当那些日子，怀孕的和乳养孩子的有祸了！因为大灾难要临到这地，烈怒要临到这民。'),
('CNV', '路加福音', 42, 21, 24, '他们将倒在刀下，被掳到各国，耶路撒冷必被外族人践踏，直到外族人的日期满足。'),
('CNV', '路加福音', 42, 21, 25, '“日月星辰将有异兆；在地上，各国也要因着海洋波涛的咆哮而困苦不安。'),
('CNV', '路加福音', 42, 21, 26, '天上的万象震动，人因为等待即将临到世界的事，都吓昏了。'),
('CNV', '路加福音', 42, 21, 27, '那时，他们要看见人子，带着能力，满有荣耀，驾着云降临。'),
('CNV', '路加福音', 42, 21, 28, '一有这些事，你们就当挺身昂首，因为你们的救赎近了。”'),
('CNV', '路加福音', 42, 21, 29, '耶稣又给他们讲了一个比喻：“你们看看无花果树和各样的树。'),
('CNV', '路加福音', 42, 21, 30, '它们什么时候发芽，你们看见了，就知道夏天近了。'),
('CNV', '路加福音', 42, 21, 31, '同样，你们什么时候看见这些事发生，也应该知道神的国近了。'),
('CNV', '路加福音', 42, 21, 32, '我实在告诉你们，这一切都必定发生，然后这世代才会过去。'),
('CNV', '路加福音', 42, 21, 33, '天地都过去，但我的话决不会废去。'),
('CNV', '路加福音', 42, 21, 34, '“你们应当自己小心，免得在贪食醉酒和生活的挂虑压住你们的心的时候，那日子突然临到你们，'),
('CNV', '路加福音', 42, 21, 35, '正如网罗临到全地的所有居民。'),
('CNV', '路加福音', 42, 21, 36, '你们要时刻警醒，常常祈求，好让你们能逃避这一切要发生的事，可以站在人子面前。”'),
('CNV', '路加福音', 42, 21, 37, '耶稣白天在殿里教导人，晚上就到橄榄山上去过夜。'),
('CNV', '路加福音', 42, 21, 38, '群众清早起来上圣殿，到他那里要听他讲道。'),
('CNV', '路加福音', 42, 22, 1, '除酵节又名逾越节近了。'),
('CNV', '路加福音', 42, 22, 2, '祭司长和经学家设法怎样杀害耶稣，因为他们惧怕群众。'),
('CNV', '路加福音', 42, 22, 3, '那时，撒但已经进入加略人犹大的心，他原是十二门徒中的一个。'),
('CNV', '路加福音', 42, 22, 4, '他去与祭司长和守殿官商量怎样把耶稣交给他们。'),
('CNV', '路加福音', 42, 22, 5, '他们很高兴，约定了给他银子。'),
('CNV', '路加福音', 42, 22, 6, '他答应了，就寻找机会，要趁群众不在的时候，把耶稣交给他们。'),
('CNV', '路加福音', 42, 22, 7, '除酵日到了，在这一天应当宰杀逾越节的羊羔。'),
('CNV', '路加福音', 42, 22, 8, '耶稣差派彼得和约翰，说：“你们去为我们预备逾越节的晚餐给我们吃。”'),
('CNV', '路加福音', 42, 22, 9, '他们说：“你要我们在哪里预备呢？”'),
('CNV', '路加福音', 42, 22, 10, '他说：“你们进了城，必有一个人顶着水罐，迎面而来，你们就跟着他，到他所进的那一家，'),
('CNV', '路加福音', 42, 22, 11, '对家主说，老师问你：‘客厅在哪里？我和门徒好在那里吃逾越节的晚餐。’'),
('CNV', '路加福音', 42, 22, 12, '他必指示你们楼上一间布置整齐的大房子，你们就在那里预备。”'),
('CNV', '路加福音', 42, 22, 13, '他们去了，所遇见的正像耶稣所说的一样，就预备好了逾越节的晚餐。'),
('CNV', '路加福音', 42, 22, 14, '到了时候，耶稣和使徒一同吃饭。'),
('CNV', '路加福音', 42, 22, 15, '他说：“我十分愿意在受难以前，跟你们吃这逾越节的晚餐。'),
('CNV', '路加福音', 42, 22, 16, '我告诉你们，我决不再吃这晚餐，直到它成就在神的国里。”'),
('CNV', '路加福音', 42, 22, 17, '耶稣接过杯来，感谢了，说：“你们拿这个，大家分着喝。'),
('CNV', '路加福音', 42, 22, 18, '我告诉你们，从今以后，我决不再喝这葡萄酒，直到神的国来临。”'),
('CNV', '路加福音', 42, 22, 19, '他拿起饼来，感谢了，擘开递给他们，说：“这是我的身体，为你们舍的，你们应当这样行，为的是记念我。”'),
('CNV', '路加福音', 42, 22, 20, '饭后，他照样拿起杯来，说：“这杯是用我的血所立的新约，这血是为你们流的。'),
('CNV', '路加福音', 42, 22, 21, '你看，出卖我的人的手和我一同在桌子上，'),
('CNV', '路加福音', 42, 22, 22, '人子固然要照所预定的离世，但出卖人子的那人有祸了！”'),
('CNV', '路加福音', 42, 22, 23, '于是，门徒彼此对问，他们中间谁要作这事。'),
('CNV', '路加福音', 42, 22, 24, '门徒中间又起了争论：他们中间谁是最大的。'),
('CNV', '路加福音', 42, 22, 25, '耶稣对他们说：“各国都有君王统治他们，他们的掌权者称为恩主，'),
('CNV', '路加福音', 42, 22, 26, '但你们却不要这样；你们中间最大的，应当像最小的；作首领的，应当像服事人的。'),
('CNV', '路加福音', 42, 22, 27, '哪一个大呢？是坐着吃喝的还是服事人的呢？不是坐着吃喝的吗？然而我在你们中间，如同服事人的。'),
('CNV', '路加福音', 42, 22, 28, '我在磨炼之中，常常和我同在的就是你们。'),
('CNV', '路加福音', 42, 22, 29, '父怎样把王权赐给我，我也照样赐给你们，'),
('CNV', '路加福音', 42, 22, 30, '叫你们在我的国里坐在我的席上吃喝，又坐在宝座上审判以色列的十二支派。'),
('CNV', '路加福音', 42, 22, 31, '“西门，西门，撒但设法要得着你们，好筛你们像筛麦子一样；'),
('CNV', '路加福音', 42, 22, 32, '但我已经为你祈求，叫你的信心不至失掉。你回头的时候，要坚固你的弟兄。”'),
('CNV', '路加福音', 42, 22, 33, '彼得说：“主啊！我已经准备好要跟你一同下监，一同死。”'),
('CNV', '路加福音', 42, 22, 34, '耶稣说：“彼得，我告诉你，今天鸡叫以前，你会三次说不认得我。”'),
('CNV', '路加福音', 42, 22, 35, '耶稣又对他们说：“从前我差你们出去，没有带钱囊、口袋、鞋子，你们缺乏什么没有？”他们说：“没有。”'),
('CNV', '路加福音', 42, 22, 36, '耶稣说：“但现在，有钱囊的应当带着，有口袋的也是这样；没有刀的，要卖掉衣服去买刀。'),
('CNV', '路加福音', 42, 22, 37, '我告诉你们，‘他被列在不法者之中’这句经文，必定应验在我身上，因为关于我的事必然成就。”'),
('CNV', '路加福音', 42, 22, 38, '他们说：“主啊，请看，这里有两把刀。”耶稣说：“够了。”'),
('CNV', '路加福音', 42, 22, 39, '耶稣照常到橄榄山去，门徒也跟着他。'),
('CNV', '路加福音', 42, 22, 40, '到了那里，他对门徒说：“你们应当祷告，免得陷入试探。”'),
('CNV', '路加福音', 42, 22, 41, '于是耶稣离开他们约有扔一块石头那么远，跪下祷告说：'),
('CNV', '路加福音', 42, 22, 42, '“父啊，如果你愿意，就把这杯拿走！但不要成就我的意思，只要成就你的旨意。”（有些抄本有第43、44节：“有一位天使从天上显现，加给他力量。耶稣非常伤痛，祷告更加恳切，汗如大血点滴在地上。”）'),
('CNV', '路加福音', 42, 22, 45, '他祷告完了，就起来到门徒那里，看见他们因为忧愁都睡着了，'),
('CNV', '路加福音', 42, 22, 46, '就说：“你们为什么睡觉呢？起来祷告！免得陷入试探。”'),
('CNV', '路加福音', 42, 22, 47, '耶稣还在说话的时候，来了一群人，十二门徒中的犹大走在前头，到了耶稣跟前要用嘴亲他。'),
('CNV', '路加福音', 42, 22, 48, '耶稣对他说：“犹大，你用亲吻作暗号出卖人子吗？”'),
('CNV', '路加福音', 42, 22, 49, '左右的人见了，就说：“主啊，我们用刀砍好吗？”'),
('CNV', '路加福音', 42, 22, 50, '他们中间有一个人砍了大祭司的仆人一刀，削掉他的右耳。'),
('CNV', '路加福音', 42, 22, 51, '耶稣说：“由他们吧！”就摸那人的耳朵，医好了他。'),
('CNV', '路加福音', 42, 22, 52, '耶稣对那些前来捉拿他的祭司长、守殿官和长老说：“你们带着刀棒出来，把我当作强盗捉拿吗？'),
('CNV', '路加福音', 42, 22, 53, '我天天跟你们在殿里，你们不向我下手；但现在是你们的时候了，也是黑暗掌权的时候了。”'),
('CNV', '路加福音', 42, 22, 54, '他们拿住耶稣，押到大祭司家里，彼得远远地跟着。'),
('CNV', '路加福音', 42, 22, 55, '他们在院内生了火，一同坐着，彼得也坐在他们中间。'),
('CNV', '路加福音', 42, 22, 56, '有一个使女，见他面向火光坐着，就注视他，说：“这人是和他一伙的。”'),
('CNV', '路加福音', 42, 22, 57, '彼得却否认，说：“你这个女人，我不认得他。”'),
('CNV', '路加福音', 42, 22, 58, '不久，另一个人看见他，就说：“你也是他们中间的一个。”彼得说：“你这个人，我不是。”'),
('CNV', '路加福音', 42, 22, 59, '大约过了一小时，又有一个人肯定地说：“这人真是和他一伙的，因为他也是加利利人。”'),
('CNV', '路加福音', 42, 22, 60, '彼得说：“你这个人，我不知道你说的是什么！”他还在说话的时候，鸡就叫了。'),
('CNV', '路加福音', 42, 22, 61, '主转过身来看彼得，彼得就想起主对他说过的话：“今天鸡叫以前，你要三次说不认得我。”'),
('CNV', '路加福音', 42, 22, 62, '他就出去痛哭。'),
('CNV', '路加福音', 42, 22, 63, '看管耶稣的人戏弄他，打他，'),
('CNV', '路加福音', 42, 22, 64, '蒙住他的眼睛问他：“你说预言吧，说打你的是谁。”'),
('CNV', '路加福音', 42, 22, 65, '他们还说了许多别的辱骂他的话。'),
('CNV', '路加福音', 42, 22, 66, '天一亮，民间的长老、祭司长和经学家就都聚集，把他带到他们的公议会里，说：'),
('CNV', '路加福音', 42, 22, 67, '“你若是基督，就告诉我们吧。”耶稣说：“就算我告诉你们，你们也决不相信。'),
('CNV', '路加福音', 42, 22, 68, '如果我问你们，你们也决不回答。'),
('CNV', '路加福音', 42, 22, 69, '从今以后，人子要坐在神权能的右边。”'),
('CNV', '路加福音', 42, 22, 70, '他们说：“那么你是神的儿子吗？”耶稣说：“你们说了，我是。”'),
('CNV', '路加福音', 42, 22, 71, '他们说：“我们还需要什么见证呢？我们亲自听见他所说的话了。”'),
('CNV', '路加福音', 42, 23, 1, '众人都起来，把耶稣押到彼拉多那里，'),
('CNV', '路加福音', 42, 23, 2, '控告他说：“我们查出这个人煽惑我们的同胞，阻止纳税给凯撒，并且自称是基督，是王。”'),
('CNV', '路加福音', 42, 23, 3, '彼拉多问他：“你是犹太人的王吗？”耶稣回答：“你已经说了（“你已经说了”或译：“这是你说的”）。”'),
('CNV', '路加福音', 42, 23, 4, '彼拉多对祭司长和众人说：“我在这人身上，查不出有什么罪。”'),
('CNV', '路加福音', 42, 23, 5, '但他们极力说：“他在犹太全地教导人，煽动群众，从加利利直到这里。”'),
('CNV', '路加福音', 42, 23, 6, '彼拉多听见了，就问耶稣是不是加利利人。'),
('CNV', '路加福音', 42, 23, 7, '既然知道他是属于希律管辖的，就把他送回希律那里；那时希律正在耶路撒冷。'),
('CNV', '路加福音', 42, 23, 8, '希律看见耶稣，非常欢喜，因为他曾经听过耶稣的事，早就想要见他，希望看他行个神迹。'),
('CNV', '路加福音', 42, 23, 9, '于是他问了耶稣许多话，但耶稣什么也不回答。'),
('CNV', '路加福音', 42, 23, 10, '祭司长和经学家站着，猛烈地控告他。'),
('CNV', '路加福音', 42, 23, 11, '希律和他的侍卫就藐视耶稣，戏弄他，给他穿上华丽的衣服，把他送回彼拉多那里。'),
('CNV', '路加福音', 42, 23, 12, '希律和彼拉多从前原是彼此为仇，在那一天就成了朋友。'),
('CNV', '路加福音', 42, 23, 13, '彼拉多召集了祭司长、官长和民众，'),
('CNV', '路加福音', 42, 23, 14, '对他们说：“你们把这人押到我这里来，说他煽惑群众，我已经在你们面前审讯过，在他身上一点也找不到你们控告他的罪状，'),
('CNV', '路加福音', 42, 23, 15, '连希律也找不到，又把他送回我这里，可见他没有作过该死的事。'),
('CNV', '路加福音', 42, 23, 16, '我要责打他，然后把他释放。”（有些抄本有第17节：“每逢节期，他必须照例给他们释放一个囚犯。”也有些抄本把这句放在第19节后）'),
('CNV', '路加福音', 42, 23, 18, '众人齐声喊叫：“除掉这个人，给我们释放巴拉巴！”'),
('CNV', '路加福音', 42, 23, 19, '这巴拉巴是因为在城里作乱杀人而入狱的。'),
('CNV', '路加福音', 42, 23, 20, '彼拉多再向他们说明，愿意释放耶稣。'),
('CNV', '路加福音', 42, 23, 21, '然而他们高声呼叫：“把他钉十字架，把他钉十字架！”'),
('CNV', '路加福音', 42, 23, 22, '彼拉多第三次对他们说：“这人作过什么恶事呢？我在他身上找不出什么该死的罪。所以我要责打他，然后把他释放。”'),
('CNV', '路加福音', 42, 23, 23, '但他们大声吵闹，要他把耶稣钉十字架，他们的声音就得了胜。'),
('CNV', '路加福音', 42, 23, 24, '彼拉多就宣判，照他们的要求，'),
('CNV', '路加福音', 42, 23, 25, '把他们所求那作乱杀人入狱的释放了，却把耶稣交出来，随他们的意思处理。'),
('CNV', '路加福音', 42, 23, 26, '他们把耶稣带走的时候，抓住了一个从乡下来的古利奈人西门，把十字架放在他身上，叫他背着跟在耶稣后面。'),
('CNV', '路加福音', 42, 23, 27, '一大群人跟随他，有些妇女为他捶胸痛哭。'),
('CNV', '路加福音', 42, 23, 28, '耶稣转过身来对她们说：“耶路撒冷的女儿啊，不要为我哭，却要为你们自己和你们的儿女哭。'),
('CNV', '路加福音', 42, 23, 29, '日子将到，人必说：‘不生育的和没有怀过胎的，也没有哺养过婴儿的有福了。’'),
('CNV', '路加福音', 42, 23, 30, '那时人要对大山说：‘倒在我们身上！’对小山说：‘遮盖我们！’'),
('CNV', '路加福音', 42, 23, 31, '他们在青绿的树上，既然这样作；在枯干的树上，又会怎样呢？”'),
('CNV', '路加福音', 42, 23, 32, '他们另外带来两个犯人，和耶稣一同处死，'),
('CNV', '路加福音', 42, 23, 33, '到了那名叫“髑髅”的地方，就把耶稣钉在十字架上，也钉了那两个犯人，一左一右。'),
('CNV', '路加福音', 42, 23, 34, '耶稣说：“父啊，赦免他们！因为他们不知道自己所作的是什么。”士兵抽签，分了他的衣服。'),
('CNV', '路加福音', 42, 23, 35, '群众站着观看，官长们嗤笑说：“他救了别人，如果他是基督，是神所拣选的，让他救自己吧！”'),
('CNV', '路加福音', 42, 23, 36, '士兵也上前戏弄他，拿酸酒给他喝，'),
('CNV', '路加福音', 42, 23, 37, '说：“如果你是犹太人的王，救你自己吧！”'),
('CNV', '路加福音', 42, 23, 38, '在耶稣的头以上有一个牌子写着：“这是犹太人的王。”'),
('CNV', '路加福音', 42, 23, 39, '悬挂着的犯人中，有一个侮辱他说：“你不是基督吗？救你自己和我们吧！”'),
('CNV', '路加福音', 42, 23, 40, '另一个就应声责备他说：“你是同样受刑的，还不惧怕神吗？'),
('CNV', '路加福音', 42, 23, 41, '我们是罪有应得的。我们所受的与所作的相称，然而这个人并没有作过什么不对的事。”'),
('CNV', '路加福音', 42, 23, 42, '他又对耶稣说：“耶稣啊，你得国降临的时候，求你记念我。”'),
('CNV', '路加福音', 42, 23, 43, '耶稣对他说：“我实在告诉你，今天你必定同我在乐园里了。”'),
('CNV', '路加福音', 42, 23, 44, '从大约正午直到下午三点钟，遍地都黑暗了。'),
('CNV', '路加福音', 42, 23, 45, '太阳没有光，圣所的幔子从当中裂开。'),
('CNV', '路加福音', 42, 23, 46, '耶稣大声呼叫：“父啊，我把我的灵魂交在你手里。”说了这话，气就断了。'),
('CNV', '路加福音', 42, 23, 47, '百夫长看见所发生的事，就颂赞神，说：“这真是个义人！”'),
('CNV', '路加福音', 42, 23, 48, '聚集观看的群众，看见所发生的事，都捶着胸回去了。'),
('CNV', '路加福音', 42, 23, 49, '与耶稣熟悉的人，和从加利利跟随他来的妇女，都远远地站着，看这些事。'),
('CNV', '路加福音', 42, 23, 50, '有一个人名叫约瑟，是个议员，为人良善公义，'),
('CNV', '路加福音', 42, 23, 51, '是犹太地亚利马太城的人，一向等候神的国，并不附和众人的计谋和行为。'),
('CNV', '路加福音', 42, 23, 52, '这人去见彼拉多，求领耶稣的身体。'),
('CNV', '路加福音', 42, 23, 53, '他把身体取下来，用细麻布裹好，放在从石头凿出来的坟墓里，这坟墓是从来没有葬过人的。'),
('CNV', '路加福音', 42, 23, 54, '那天是预备日，安息日就要开始，'),
('CNV', '路加福音', 42, 23, 55, '那些从加利利和耶稣一起来的妇女，跟着来了。她们看见了坟墓，和他的身体怎样安葬，'),
('CNV', '路加福音', 42, 23, 56, '就回去预备香料和香膏。安息日，她们遵着诫命安息。'),
('CNV', '路加福音', 42, 24, 1, '礼拜日大清早的时候，妇女们带着预备好的香料，来到坟墓那里，'),
('CNV', '路加福音', 42, 24, 2, '发现石头已经从坟墓辊开了，'),
('CNV', '路加福音', 42, 24, 3, '就进去，却找不着主耶稣的身体。'),
('CNV', '路加福音', 42, 24, 4, '她们正为此事猜疑的时候，忽然有两个人，穿着闪烁耀目的衣服，站在她们旁边。'),
('CNV', '路加福音', 42, 24, 5, '她们害怕，把脸伏在地上。那两个人对她们说：“为什么在死人中找活人呢？'),
('CNV', '路加福音', 42, 24, 6, '他不在这里，已经复活了。你们应当记得他还在加利利的时候，怎样告诉你们，'),
('CNV', '路加福音', 42, 24, 7, '说：‘人子必须被交在罪人手里，钉在十字架上，第三日复活。’”'),
('CNV', '路加福音', 42, 24, 8, '她们就想起他的话，'),
('CNV', '路加福音', 42, 24, 9, '于是从坟地回去，把这一切事告诉十一个使徒和其余的人。'),
('CNV', '路加福音', 42, 24, 10, '那些妇女就是抹大拉的马利亚，约亚拿和雅各的母亲马利亚，以及其他在一起的妇女，她们把这些事向使徒说了。'),
('CNV', '路加福音', 42, 24, 11, '使徒以为这些话是无稽之谈，就不相信。'),
('CNV', '路加福音', 42, 24, 12, '彼得却起来跑到坟墓那里，屈身往里观看，只见细麻布在那里，就回去了，对所发生的事非常惊奇。'),
('CNV', '路加福音', 42, 24, 13, '同一天，门徒中有两个人往一个叫以马午斯的村子去，那村子距耶路撒冷约十一公里；'),
('CNV', '路加福音', 42, 24, 14, '他们彼此谈论所发生的这一切事。'),
('CNV', '路加福音', 42, 24, 15, '正在交谈议论的时候，耶稣亲自走近他们，与他们同行，'),
('CNV', '路加福音', 42, 24, 16, '但他们的眼睛却给蒙蔽了，认不出他来。'),
('CNV', '路加福音', 42, 24, 17, '耶稣说：“你们走路的时候，彼此讨论的是什么事呢？”他们就站住，面带愁容；'),
('CNV', '路加福音', 42, 24, 18, '一个名叫革流巴的回答他：“在耶路撒冷作客的，难道只有你不知道这几天在那里所发生的事吗？”'),
('CNV', '路加福音', 42, 24, 19, '他说：“什么事呢？”他们说：“就是拿撒勒人耶稣的事。他是先知，在神和众人面前，说话行事都有大能。'),
('CNV', '路加福音', 42, 24, 20, '我们的祭司长和官长，竟把他交出去，判了死罪，钉在十字架上。'),
('CNV', '路加福音', 42, 24, 21, '但我们素来盼望要救赎以色列的就是他。不但这样，这些事发生到今天，已经是第三天了。'),
('CNV', '路加福音', 42, 24, 22, '而且我们中间有几个妇女使我们惊奇，她们清早到坟墓那里去，'),
('CNV', '路加福音', 42, 24, 23, '却找不到他的身体。她们回来说看见天使显现，天使说他活了。'),
('CNV', '路加福音', 42, 24, 24, '又有我们中间的几个人到坟墓那里去，所看见的正如妇女们所说的，只是没有看见他。”'),
('CNV', '路加福音', 42, 24, 25, '耶稣说：“无知的人哪，先知所说的一切话，你们心里信得太迟钝了！'),
('CNV', '路加福音', 42, 24, 26, '基督这样受害，然后进入他的荣耀，不是应当的吗？”'),
('CNV', '路加福音', 42, 24, 27, '于是他从摩西和众先知起，把所有关于自己的经文，都给他们解释明白了。')
on conflict (version, book, chapter, verse) do nothing;
